#include <iostream>
#include <queue>
using namespace std;
typedef long long ll;

const ll INF = 10000000000000000;

template <typename T>
struct Edge
{
    int to;
    T cost;
};

template <typename T>
struct WeightedGraph
{
    int n;
    vector<vector<Edge<T>>> g;

    WeightedGraph(int n) : n(n){
        g.resize(n);
    }

    void init(int n_){
        n = n_;
        g.resize(n_);
    }

    void add_edge(int from, int to, T cost){
        g[from].push_back((Edge<T>){to, cost});
    }
};

template <typename T>
vector<T> Dijkstra(WeightedGraph<T> &g, int s){
    typedef pair<T, int> P;
    int n = g.n;
    vector<T> d(n);
    fill(d.begin(), d.end(), INF);
    priority_queue<P, vector<P>, greater<P>> que;
    d[s] = 0;
    que.push(P(0, s));
    while(que.size()){
        P nowp = que.top();
        que.pop();
        if(d[nowp.second] < nowp.first) continue;
        for(Edge<T> e : g.g[nowp.second]){
            if(d[e.to] > d[nowp.second] + e.cost){
                d[e.to] = d[nowp.second] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
    return d;
}

int main()
{
    int n, m;
    cin >> n >> m;
    WeightedGraph<ll> g(n);
    int b[100005]{0};
    for(int i = 0; i < m; i++){
        int l, r;
        ll c;
        cin >> l >> r >> c;
        l--; r--;
        g.add_edge(l, r, c);
        b[l]++;
        b[r]--;
    }
    int k = 0;
    for(int i = 0; i < n; i++){
        k += b[i];
        if(k) g.add_edge(i + 1, i, 0);
    }
    vector<ll> d = Dijkstra(g, 0);
    if(d[n - 1] == INF) cout << -1 << endl;
    else cout << d[n - 1] << endl;
}

