};

void solve() {
  ll n, m; cin >> n >> m;
  vector<vector<Edge>> edges(n);
  rep(i, m) {
    ll l, r, c; cin >> l >> r >> c; --l, --r;
    edges[r].pb({l, r, c});
  }
  SegmentTree<Min> seg(n);
  seg.update(0, 0);
  rep(i, 1, n) {
    ll cost = linf;
    each(e, edges[i]) {
      assert(e.r == i);
      chmin(cost, seg.find(e.l, e.r) + e.c);
    }
