struct DIJK_LINK
{
	int from;
	int to;
	ll cost;
};

// リンクのリストから隣接リストをつくる
void dijkstra_make_G(vector< vector< pair<int, ll> > >& G, const vector < DIJK_LINK >& links, int N)
{
	G.clear();
	G.resize(N);

	for (int i = 0; i<SZ(links); i++)
	{
		G[links[i].from].push_back(make_pair(links[i].to, links[i].cost));
	}
}


void dijkstra(vector <ll>& D, const int start, const int N, const vector< vector< pair<int, ll> > >& G)
{
	D.clear();
	for (int i = 0; i<N; i++)
	{
		D.push_back(BIGLL);
	}
	priority_queue<pair<ll, int>, vector< pair<ll, int> >, greater< pair<ll, int> > > Q;
	D[start] = 0;
	Q.push(pair<ll, int>(0, start));

	while (!Q.empty()) {

		pair<ll, int> top = Q.top();
		Q.pop();

		int v = top.second;
		ll d = top.first;
		if (d <= D[v]) {
			for (int di = 0; di<SZ(G[v]); di++)
			{
				int v2 = G[v][di].first;
				ll cost = G[v][di].second;
				if (D[v2] > D[v] + cost) {
					D[v2] = D[v] + cost;
					Q.push(pair<ll, int>(D[v2], v2));
				}
			}
		}
	}
}

int main()
{
	int N, M;
	cin >> N >> M;

	int firstN = N;

	vector< vector< pair<int, ll> > > G;
	vector < DIJK_LINK > links;

	for(int i=0;i<M;i++)
	{
		DIJK_LINK tmp;
		int l, r, c;	
		cin >> l >> r >> c;
		l--;
		r--;

		for (int x = l; x <= r; x++)
		{
			tmp.from = x;
			tmp.to = N;
			tmp.cost = c;
			links.push_back(tmp);
			swap(tmp.from, tmp.to);
			links.push_back(tmp);
		}
		N++;
	}

	dijkstra_make_G(G, links, N);
	vector <ll> D;
	dijkstra(D, 0, N, G);


	if (D[firstN - 1] >= BIGLL)
	{
		D[firstN - 1] = -1;
	}
	else
	{
		D[firstN - 1] /= 2;
	}

	cout << D[firstN - 1] << endl;

	return 0;
}

