void bfs(){
	while (!Q.empty()) {
		int x=Q.front();
//		cout<<x<<" "<<dist[x]<<endl;
		Q.pop();
		inQ[x]=0;
		if(p[x].r==n) {
			ans=min(ans,dist[x]);
