void solve() {
  int N, M;
  cin >> N >> M;
  vi32 cost(M);
  vector<vi32> adds(N);
  vector<vi32> rems(N);
  rep(i, M) {
    int l, r, c;
    cin >> l >> r >> c;
    l--, r--;
    adds[l].emplace_back(i);
    rems[r].emplace_back(i);
    cost[i] = c;
  }
  vi64 dist(M);
  i64 ans = 0;
  set<pair<i64, int>> se;
  rep(i, N) {
    if (i != 0) {
      if (se.size() == 0) {
        cout << -1 << endl;
        return;
      }
      ans = se.begin()->first;
    }
    each(j, adds[i]) {
      se.emplace(ans + cost[j], j);
      dist[j] = ans + cost[j];
    }
    each(j, rems[i]) {
      se.erase(make_pair(dist[j], j));
    }
  }
  cout << ans << endl;
}

