struct weighted_directed_graph
{
	int n;
	vector<vector<pair<int, weight_type>>> v;

	weighted_directed_graph (int n = 0)
	{
		init(n);
	}
	void init(int n)
	{
		assert(n >= 0);
		this->n = n;
		v = vector<vector<pair<int, weight_type>>>(n+1);
	}
	void addedge(int x, int y, weight_type z)
	{
		assert(1 <= x && x <= n);
		assert(1 <= y && y <= n);
		v[x].push_back({y, z});
	}

	vector<weight_type> dis;
	weight_type shortest_path(int s, int t)
	{
		dis = vector<weight_type>(n+1, INF);
		dis[s] = 0;
		priority_queue<pair<weight_type, int>, vector<pair<weight_type, int>>, greater<pair<weight_type, int>>> Q;
		Q.push({0, s});
		while (!Q.empty())
		{
			int d, x;
			tie(d, x) = Q.top();
			Q.pop();
			if (dis[x] != d) continue;
			for (auto e : v[x])
			{
				int y, z;
				tie(y, z) = e;
				if (dis[y] > d+z) Q.push({dis[y] = d+z, y});
			}
		}
		return dis[t];
	}
};


int n, m;
int a[MAXN];

weighted_directed_graph<ll> G;

void addedge(int a, int b, int c)
{
	//printf("%d %d %d\n", a, b, c);
	G.addedge(a, b, c);
}

void build(int k, int L, int R)
{
	if (L == R)
	{
		addedge(L, n+m+k, 0);
		addedge(n+m+4*n+k, L, 0);
		return;
	}
	int mid = (L+R)/2;
	build(k<<1, L, mid);
	build(k<<1|1, mid+1, R);
	addedge(n+m+(k<<1), n+m+k, 0);
	addedge(n+m+(k<<1|1), n+m+k, 0);
	addedge(n+m+4*n+k, n+m+4*n+(k<<1), 0);
	addedge(n+m+4*n+k, n+m+4*n+(k<<1|1), 0);
}

void go(int k, int L, int R, int x, int y, int z, int id)
{
	if (L == x && R == y)
	{
		addedge(n+m+k, n+id, z);
		addedge(n+id, n+m+4*n+k, 0);
		return;
	}
	int mid = (L+R)/2;
	if (y <= mid)
		go(k<<1, L, mid, x, y, z, id);
	else if (x > mid)
		go(k<<1|1, mid+1, R, x, y, z, id);
	else
	{
		go(k<<1, L, mid, x, mid, z, id);
		go(k<<1|1, mid+1, R, mid+1, y, z, id);
	}
}

void solve()
{
	n = inp();
	m = inp();
	G.init(n+m+4*n+4*n);
	build(1, 1, n);
	for (int i = 1; i <= m; ++ i)
	{
		int x = inp();
		int y = inp();
		int z = inp();
		go(1, 1, n, x, y, z, i);
	}
	ll ans = G.shortest_path(1, n);
	if (ans == INF) ans = -1;
	writeln(ans);
}

