const ll INF = 1e18;
struct LazySegmentTree {
private:
    int n;
    vector<ll> node, lazy;

public:
    LazySegmentTree(vector<ll> v) {
        int sz = (int)v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1, INF);

        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = min(node[i*2+1], node[i*2+2]);
    }

    void eval(int k, int l, int r) {
        if(lazy[k] != INF) {
            node[k] = lazy[k];
            if(r-l > 1) {
                lazy[2*k+1] = lazy[k];
                lazy[2*k+2] = lazy[k];
            }
            lazy[k] = INF;
        }
    }

    void update(int a, int b, ll x, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            lazy[k] = x;
            eval(k, l, r);
        }
        else {
            update(a, b, x, 2*k+1, l, (l+r)/2);
            update(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = min(node[2*k+1], node[2*k+2]);
        }
    }

    ll getmin(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return INF;
        if(a <= l && r <= b) return node[k];
        ll vl = getmin(a, b, 2*k+1, l, (l+r)/2);
        ll vr = getmin(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }

};


int main() {
    int n, m;
    cin >> n >> m;
    vector<pair<int, pair<int,ll> > > query;
    rep(i, m){
        int l_, r_;
        ll c;
        cin >> l_ >> r_ >> c;
        l_--;
        r_--;
        query.push_back(make_pair(l_, make_pair(r_, c)));
    }

    sort(query.begin(), query.end());

    LazySegmentTree seg(vector<ll> (n, INF));
    seg.update(0, 1, 0);

    rep(i, m) {
        int l_ = query[i].first;
        int r_ = query[i].second.first;
        ll c = query[i].second.second;
        ll mind = seg.getmin(l_, n);
        if (mind+c < seg.getmin(r_, r_+1)) seg.update(r_, r_+1, mind+c);
    }

    if (seg.getmin(n-1, n) == INF) cout << -1 << endl;
    else cout << seg.getmin(n-1, n) << endl;


    return 0;
}

