template <typename T> vector<T> table(int n, T v) { return vector<T>(n, v); }

template <class... Args> auto table(int n, Args... args) {
  auto val = table(args...);
  return vector<decltype(val)>(n, move(val));
}

void solve(long long N, long long M, std::vector<long long> L,
           std::vector<long long> R, std::vector<long long> C) {
  WeightedGraph<ll> g(N);
  REP(i,N-1) add_edge(g, i + 1, i, 0LL);
  REP(i,M) add_edge(g, L[i] - 1, R[i] - 1, C[i]);
  auto d = dijkstra(g, 0);
  if (d[N-1] == inf<ll>()) cout << -1 << endl;
  else cout << d[N-1] << endl;
}

int main() {
  long long N;
  scanf("%lld", &N);
  long long M;
  scanf("%lld", &M);
  std::vector<long long> L(M);
  std::vector<long long> R(M);
  std::vector<long long> C(M);
  for (int i = 0; i < M; i++) {
    scanf("%lld", &L[i]);
    scanf("%lld", &R[i]);
    scanf("%lld", &C[i]);
  }
  solve(N, M, std::move(L), std::move(R), std::move(C));
  return 0;
}

