    D.set(0, 0LL);

    long long oo = numeric_limits<long long>::max();

    for (int i=0; i<N; i++)
    {
        long long d = D.query(i, N, 0LL);
        if (d<oo)
            for (int j=0; j<(int)R[i].size(); j++)
            {
                int r = R[i][j];
                long long c = C[i][j];
                if (d+c < D.get(r))
                    D.set(r, d+c);
            }
    }
    long long ans = D.get(N-1);
    cout<<(ans<oo ? ans : -1)<<endl;
}

