int N, M;

struct SegmentTree {
  private:
    int n;
    vector<ll> node;

  public:
    SegmentTree(vector<ll> v) {
        int sz = v.size();
        n = 1;
        while(n < sz) {
            n *= 2;
        }
        node.resize(2 * n - 1, INF);
        for(int i = 0; i < sz; i++) {
            node[i + n - 1] = v[i];
        }
        for(int i = n - 2; i >= 0; i--) {
            node[i] = min(node[2 * i + 1], node[2 * i + 2]);
        }
    }

    void update(int x, ll val) {
        x += (n - 1);
        node[x] = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2 * x + 1], node[2 * x + 2]);
        }
    }

    ll getmin(int a, int b, int k = 0, int l = 0, int r = -1) {
        if(r < 0) {
            r = n;
        }
        if(r <= a || b <= l) {
            return INF;
        }
        if(a <= l && r <= b) {
            return node[k];
        }

        ll vl = getmin(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = getmin(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
};

int main() {
    cin >> N >> M;
    SegmentTree seg(vector<ll>(N, INF));
    vector<ll> L(M), R(M), C(M);
    REP(i, M) {
        cin >> L[i] >> R[i] >> C[i];
        L[i]--;
        R[i]--;
    }
    vector<tuple<int, int, ll>> edge(M);
    REP(i, M) { edge[i] = make_tuple(L[i], R[i], C[i]); }
    sort(edge.begin(), edge.end());
    vector<ll> dp(N, INF);
    dp[0] = 0;
    seg.update(0, 0);
    REP(i, M) {
        int l = get<0>(edge[i]);
        int r = get<1>(edge[i]);
        int c = get<2>(edge[i]);
        ll t = seg.getmin(l, r);
        dp[r] = min(dp[r], t + c);
        seg.update(r, dp[r]);
    }
    ll ans = dp[N - 1];
    if(ans == INF) {
        cout << -1 << endl;
        return 0;
    }
    cout << ans << endl;
    return 0;
}

