//--GLOBAL---------------------------------
struct SegmentTreeLazy{
  ll N; //要素の個数より大きい2べき乗
  vector<ll> dat;
  vector<ll> lazy;
  vector<bool> need_eval;

  SegmentTreeLazy(ll n) {
    N = 1;
    while(N < n) N <<= 1;
    dat.resize(2*N-1, INF2);
    lazy.resize(2*N-1, INF2);
    need_eval.resize(2*N-1, false);
  }

  // k 番目のノードについて遅延評価を行う
  void eval(ll k, ll l, ll r) {
    if(need_eval[k]) {
      dat[k] = lazy[k];

      if(r - l > 1) { //最下段でないなら下にlazyを半分ずつ渡す
        lazy[2*k+1] = min(lazy[2*k+1],lazy[k]);
        lazy[2*k+2] = min(lazy[2*k+2],lazy[k]);
        need_eval[2*k+1] = true;
        need_eval[2*k+2] = true;
      }
      need_eval[k] = false;
    }
  }

  void update(ll a, ll b, ll x, ll k=0, ll l=0, ll r=-1) {
    if(r < 0) r = N; // [a,b) 0-indexed

    eval(k, l, r);

    if(b <= l || r <= a) return; //範囲外は返す

    if(a <= l && r <= b) { //被覆ならlazyに入れて評価
      lazy[k] =min(lazy[k],x);
      need_eval[k] = true;
      eval(k, l, r);
    }

    else { //それ以外は子のdatを計算してからもらってくる
      update(a, b, x, 2*k+1, l, (l+r)/2);
      update(a, b, x, 2*k+2, (l+r)/2, r);
      dat[k] = min(dat[2*k+1], dat[2*k+2]);
    }
  }

  ll getmin(ll a, ll b, ll k=0, ll l=0, ll r=-1) {
    if(r < 0) r = N; // [a,b) 0-indexed
    if(b <= l || r <= a) return INF2; //範囲外

    eval(k,l,r);
    if(a <= l && r <= b) return dat[k]; //被覆なら返す
    ll vl = getmin(a, b, 2*k+1, l, (l+r)/2);
    ll vr = getmin(a, b, 2*k+2, (l+r)/2, r);
    return min(vl, vr);
  }
};

//--MAIN-----------------------------------
void Main() {
    ll N,M; 
    cin >> N>>M;

    vector<tuple<ll,ll,ll>> lrc;

    rep(i,M){
        ll l,r,c; cin>>l>>r>>c;
        lrc.emplace_back(l,r,c);
    }

    SORT(lrc);

    SegmentTreeLazy st(N);

    st.update(0,1,0);

    rep(i,M){
        ll l=get<0>(lrc[i]);
        ll r=get<1>(lrc[i]);
        ll c=get<2>(lrc[i]);
        ll x=st.getmin(l-1,l);
        if(x==INF2){
            cout<< -1<<"\n";
            return;
        }
        st.update(l,r,x+c);
    }

    if(st.getmin(N-1,N)==INF2){
        cout<< -1<<"\n";
        return;
    }

    cout<< st.getmin(N-1,N) <<"\n";


}

