void dijkstra() {
    vector<bool> visit(n+1, false);
    cost = vector<ll>(n+1, INF);
    cost[1] = 0;
    pq.push(make_pair(0, 1));
    while (!pq.empty()) {
        auto x = pq.top();
        pq.pop();
        if (visit[x.second]) continue;
        visit[x.second] = true;
        for (Link y : w[x.second]) {
            if (visit[y.to]) continue;
            if (cost[y.to] > cost[x.second] + y.c) {
                cost[y.to] = cost[x.second] + y.c;
                pq.push(make_pair(cost[y.to], y.to));
            }
        }
    }
}

