ll solve(int N, int M, vi& l, vi& r, vi& c) {
    map<int, set<ii>> mp;
    rep(i,M){
        mp[ l[i] ].insert( ii(r[i], c[i]) );
    }

    auto f = [](ll a, ll b){ return min(a,b); };
    auto g = [](ll a, ll b){ return b; };
    auto h = [](ll a, ll b){ return min(a,b); };

    LazySegmentTree<ll,ll,decltype(f),decltype(g),decltype(h)> st(f, g, h, LLONG_MAX, LLONG_MAX);

    st.build(vector<ll>(N+1, LLONG_MAX));

    for(int i=1; i<N; ++i){
        ll x = (i==1) ? 0 : st.query(i, i+1);
        if (x == LLONG_MAX) return -1;

        for(ii p: mp[i]) {
            st.update(i+1, p.first+1, x + p.second);
        }
    }

    ll x = st.query(N, N+1);
    if (x == LLONG_MAX) return -1;
    return x;
}

