    int N, M; scanf("%d %d%*c", &N, &M);
    vi l(M),r(M),c(M);
    rep(i,M) scanf("%d %d %d%*c", &l[i], &r[i], &c[i]);
    cout << solve(N,M,l,r,c) << endl;
    return 0;
}

