inline void build1(int &rt, int l, int r) {
    rt = ++tot;
    if (l == r) {
        pos[l] = rt;
        return ;
    }
    int mid = (l + r) >> 1;
    build1(t[rt].ls, l, mid), build1(t[rt].rs, mid + 1, r);
    add(t[rt].ls, rt, 0), add(t[rt].rs, rt, 0);
    return ;
}

inline void build2(int &rt, int l, int r) {
    rt = ++tot;
    if (l == r) {
        add(rt, pos[l], 0);
        return ;
    }
    int mid = (l + r) >> 1;
    build2(t[rt].ls, l, mid), build2(t[rt].rs, mid + 1, r);
    add(rt, t[rt].ls, 0), add(rt, t[rt].rs, 0);
    return ;
}

inline void link1(int rt, int l, int r, int L, int R, int C) {
    if (L <= l && r <= R) {
        add(rt, tot, C);
        return ;
    }
    int mid = (l + r) >> 1;
    if (L <= mid)
        link1(t[rt].ls, l, mid, L, R, C);
    if (R > mid)
        link1(t[rt].rs, mid + 1, r, L, R, C);
    return ;
}

inline void link2(int rt, int l, int r, int L, int R,int C) {
    if (L <= l && r <= R) {
        add(tot, rt, C);
        return ;
    }
    int mid = (l + r) >> 1;
    if (L <= mid)
        link2(t[rt].ls, l, mid, L, R, C);
    if (R > mid)
        link2(t[rt].rs, mid + 1, r, L, R, C);
    return ;
}

priority_queue<pair<int, int>, vector<pair<int, int> >, greater<pair<int, int> > >q;

int dis[N << 1];
bool vis[N << 1];

void dijkstra() {
    memset(dis, 127/3, sizeof(dis));
    dis[pos[1]] = 0;
    q.push(make_pair(0, pos[1]));
    while (!q.empty()) {
        while (vis[q.top().second] && !q.empty()) q.pop();
        if (q.empty()) break;
        int u = q.top().second; q.pop();
        vis[u] = 1;
        for (RG int i = last[u]; i; i = g[i].nxt) {
            int v = g[i].to;
            if (dis[v] > dis[u] + g[i].w) {
                dis[v] = dis[u] + g[i].w;
                q.push(make_pair(dis[v], v));
            }
        }
    }
    return ;
}

