    void set(int k, ll x)
    {
        k += n;
        data[k] = min(x, data[k]);
        while (k >>= 1)
            data[k] = min(data[2 * k], data[2 * k + 1]);
    }

    ll query(int a, int b)
    {
        ll vl = MAXD, vr = MAXD;
        for (int l = a+n, r = b+n; l < r; l >>= 1, r >>= 1)
        {
            if (l&1) vl = min(vl, data[l++]);
            if (r&1) vr = min(vr, data[--r]);
        }
        return min(vl, vr);
    }
};



