    for (int i = 1; i <= n; i++) {
        a[i] = oo;
    }
    a[1] = 0;
    IT.build(1, 1, n);
    for (int i = 0; i < m; i++) {
        int l, r, c;
        cin >> l >> r >> c;
        segs.emplace_back(Segs(l, r, c));
    }
    sort(segs.begin(), segs.end());
    for (auto seg: segs) {
        long long mn = IT.get(1, seg.l, seg.r);
//        cout << seg.l << " "<< seg.r << " " << seg.c << "\n";
        IT.update(1, seg.l, seg.r, mn + seg.c);
    }
//    cout << oo << "\n";for (int i = 1; i <= n; i++) {cout << IT.get(1, i, i) << " ";}cout << "\n";
    long long res = IT.get(1, n, n);
    if (res == oo) {
        cout << -1;
    } else {
        cout << res;
    }
    return 0;
}

