using namespace std;

using TUP = tuple<int, int, int>;

const long long inf = 1e18;

int main() {
	int N, M;
	cin >> N >> M;

	int l, r, c;
	vector<TUP> tups(M);
	for (int i = 0; i < M; i++) {
		cin >> l >> r >> c;
		tups[i] = make_tuple(l, r, c);
	}

	sort(tups.begin(), tups.end());
	map<int, long long> dists;
	dists[1] = 0;
	for (auto t: tups) {
		tie(l, r, c) = t;
		// printf("%2d %2d %2d\n", l, r, c);

		if (dists.count(r) == 0) {
			dists[r] = inf;
		}

		long long mini = inf;
		for (auto it = dists.lower_bound(l); it != dists.end(); it++) {
			mini = min(mini, it->second);
			// printf("%d %lld\n", it->first, it->second);
			if (it->first > r) {
				break;
			}

			if (it->second > mini + c) {
				it->second = mini;
			}

			dists[r] = min(dists[r], it->second + c);
		}
	}

	long long ans = -1;
	if (dists.count(N) > 0 && dists[N] != inf) {
		ans = dists[N];
	}

	cout << ans << endl;
	return 0;
}

