#include <bits/stdc++.h>
using namespace std;
using ll = long long;

// Range Minimum/Maximum Query: Semigroup
struct Element{
    ll value;
    bool isIdentity;
};
Element Identity = {0, true};
Element Operation(const Element &A, const Element &B){
    if(A.isIdentity) return B;
    if(B.isIdentity) return A;
    return {min(A.value, B.value)};
    // return {max(A.value, B.value)};
}

struct SegmentTree{
    int size; // number of leaves: power of two
    vector<Element> cbt; // complete binary tree

    // Initialize with Identity Element
    SegmentTree(int N){
        size = 1;
        while (size < N) size *= 2;
        cbt.resize(size * 2 - 1, Identity);
    }

    // Initial Input
    void initial_set(int i, const Element &A) {
        i += size - 1;
        cbt[i] = A;
    }

    void initial_build() {
        for (int i = size - 2; i >= 0; --i) {
            cbt[i] = Operation(cbt[i*2+1], cbt[i*2+2]);
        }
    }

    Element get(int i){
        i += size - 1;
        return cbt[i];
    }

    // Update i-th Leaf (0-indexed) to A
    void update(int i, const Element &A){
        i += size - 1;
        cbt[i] = A;
        while (i > 0){
            i = (i - 1) / 2;
            cbt[i] = Operation(cbt[i*2+1], cbt[i*2+2]);
        }
    }

    // Product of Interval [a, b) (0-indexed)
    Element query(int a, int b) {
        return query_rec(a, b, 0, 0, size);
    }

    Element query_rec(int a, int b, int k, int l, int r){
        // k is root of subtree [l, r)
        if(r <= a || b <= l) return Identity; // outside [a, b)
        if(a <= l && r <= b) return cbt[k]; // interior of [a, b)
        Element vl = query_rec(a, b, k*2+1, l, (l+r)/2);
        Element vr = query_rec(a, b, k*2+2, (l+r)/2, r);
        return Operation(vl, vr);
    }
};

struct query{int L; int R; int C;};
bool cmp(query A, query B){
    return A.L < B.L;
}

int main() {
    int N, M;
    cin >> N >> M;
    vector<query>qu(M);
    for (int i = 0; i < M; ++i) {
        int L, R, C;
        cin >> L >> R >> C;
        qu[i] = {L, R, C};
    }
    sort(qu.begin(), qu.end(), cmp);

    SegmentTree tree(N+2);
    tree.initial_set(1, {0});
    tree.initial_build();
    for (int i = 0; i < M; ++i) {
        auto minimum = tree.query(qu[i].L, qu[i].R);
        if(minimum.isIdentity) {
            continue;
        }
        ll temp = minimum.value + qu[i].C;
        if(tree.get(qu[i].R).isIdentity || tree.get(qu[i].R).value > temp){
            tree.update(qu[i].R, {temp});
        }
    }

    auto ans = tree.get(N);
    if(ans.isIdentity){
        cout << -1 << "\n";
    } else{
        cout << ans.value << "\n";
    }

    return 0;
}

