void add_edge(graph &g,int s, int d, LL w=1){g[s].pb(edge(s,d,w));}


Vll dijkstra(graph &g,int s){
	int i,j,k; int n=g.size(); int visit[n]; Vll dist(n);
	priority_queue<Pll,V<Pll>,greater<Pll>> q;
	REP(i,n){visit[i]=0; dist[i]=INFLL/2;}
	dist[s]=0;
	q.push(mp(0,s));
	int nv; LL min_cost=0;
	while(!q.empty()){
		LL d,t; tie(d,t)=q.top(); q.pop();
		if(visit[t]==1){continue;}
		visit[t]=1; dist[t]=d;
		for(auto &e:g[t]){
			if(dist[e.dst]<=d+e.weight){continue;}
			q.push(mp(d+e.weight,e.dst));
		}
	}
	return dist;
}

