int t[400000];

int get(int v, int l, int r, int pos) {
	if (l == r - 1) {
		return t[v];
	}
	int m = (l + r) / 2;
	if (pos < m)
		return min(t[v], get(v * 2, l, m, pos));
	return min(t[v], get(v * 2 + 1, m, r, pos));
}


void upd(int v, int l, int r, int l2, int r2, int st) {
	if (l == l2 && r == r2) {
		t[v] = min(t[v], st);
		return;
	}
	int m = (l + r) / 2;
	if (r2 <= m)
		upd(v * 2, l, m, l2, r2, st);
	else if (l2 >= m)
		upd(v * 2 + 1, m, r, l2, r2, st);
	else {
		upd(v * 2, l, m, l2, m, st);
		upd(v * 2 + 1, m, r, m, r2, st);
	}
}


