    return min(c0, c1);
  }, INF);

  segTree.update(1, 0);
  for(int i = 0; i < M; i++){
    segTree.update(e[i].first.second, min(segTree.query(e[i].first.second, e[i].first.second + 1), segTree.query(e[i].first.first, e[i].first.second) + e[i].second));
  }

