int n, m;
vector<pair<int, ll>> g[100005];
ll d[100005];
void solve() {
    cin >> n >> m;

    rep(i, n - 1) g[i + 1].emplace_back(i, 0);

    rep(i, m) {
        int l, r; ll c; cin >> l >> r >> c; --l; --r;

        g[l].emplace_back(r, c);
    }

    fill(d, d + n, inf);

    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> que;
    que.emplace(0LL, 0);
    d[0] = 0;
    while (!que.empty()) {
        auto p = que.top(); que.pop();
        auto v = p.second;

        if (d[v] < p.first) continue;

        rep(i, g[v].size()) {
            auto e = g[v][i];
            if (d[v] + e.second < d[e.first]) {
                d[e.first] = d[v] + e.second;
                que.emplace(d[e.first], e.first);
            }
        }
    }

    if (d[n - 1] != inf)
        cout << d[n - 1] << endn;
    else
        cout << -1 << endn;

}

