    cost_graph<ll> g(n);
    for (usize i = 1; i < n; i++) { g.add_edge(i, i - 1, 0LL); }
    for (usize i = 0; i < m; i++) {
        const auto l = read<usize>() - 1, r = read<usize>() - 1;
        const auto c = read<ll>();
        g.add_edge(l, r, c);
    }
    const auto d = dijkstra(g, 0);
    if (d[n - 1] >= inf_v<ll>) {
        std::cout << -1 << std::endl;
    } else {
        std::cout << d[n - 1] << std::endl;
    }
    return 0;
}

