template <typename T, T F(T, T), T INIT>
struct SegmentTree {
    T n;
    vector<T> v;

    SegmentTree(T n_){
        n = 1;
        while(n < n_){ n *= 2; }
        v.resize(2 * n - 1);
        fill(v.begin(), v.end(), INIT);
    }

    // zero-indexed
    void update(ll k, T a){
        k += n - 1;
        v[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            v[k] = F(v[k * 2 + 1], v[k * 2 + 2]);
        }
    }

    // [a, b), zero-indexed
    T query(ll a, ll b) const {
        return query_internal(a, b, 0, 0, n);
    }

    T query_internal(ll a, ll b, ll k, ll l, ll r) const {
        if(r <= a || b <= l){ return INIT; }
        if(a <= l && r <= b){
            return v[k];
        }else{
            T v1 = query_internal(a, b, k * 2 + 1, l, (l + r) / 2);
            T v2 = query_internal(a, b, k * 2 + 2, (l + r) / 2, r);
            return F(v1, v2);
        }
    }
};

ll op(ll a, ll b){ return min(a, b); }

int main(){
    ll n, m;
    cin >> n >> m;
    vector<array<ll, 3>> lrc(m);
    REP(i, m){
        cin >> lrc[i][0] >> lrc[i][1] >> lrc[i][2];
        lrc[i][0]--;
        lrc[i][1]--;
    }
    sort(lrc.begin(), lrc.end());

    SegmentTree<ll, op, numeric_limits<ll>::max()> st(n);
    st.update(0, 0);
    REP(i, m){
        ll mval = st.query(lrc[i][0], lrc[i][1]);
        if(mval == numeric_limits<ll>::max()){
            continue;
        }
        ll newval = mval + lrc[i][2];
        st.update(
            lrc[i][1],
            op(newval, st.query(lrc[i][1], lrc[i][1] + 1))
        );
    }
    if(st.query(n - 1, n) == numeric_limits<ll>::max()){
        cout << -1 << endl;
    }else{
        cout << st.query(n - 1, n) << endl;
    }
    return 0;
}

