void updateRangeUtil(ll si, ll ss, ll se, ll us, 
                     ll ue, ll diff, ll tree[], ll lazy[]) 
{ 
    if(us>ue)   
        return;
    if (lazy[si] != INF) 
    { 
        tree[si] = min(tree[si], lazy[si]);
        if (ss != se) 
        { 
            lazy[si*2 + 1]   = min(lazy[2*si+1], lazy[si]);
            lazy[si*2 + 2]   = min(lazy[2*si+2], lazy[si]);
        } 


        lazy[si] = INF; 
    } 

    if (ss>se || ss>ue || se<us) 
        return ; 

    if (ss>=us && se<=ue) 
    { 
        tree[si] = min(tree[si], diff);
        if (ss != se) 
        { 
            lazy[si*2 + 1]   = min(diff, lazy[si]);
            lazy[si*2 + 2]   = min(diff, lazy[si]);
        }
        return; 
    } 

    ll mid = (ss+se)/2; 
    updateRangeUtil(si*2+1, ss, mid, us, ue, diff, tree, lazy); 
    updateRangeUtil(si*2+2, mid+1, se, us, ue, diff, tree, lazy); 

    tree[si] = min(tree[si*2+1],tree[si*2+2]); 
} 

ll getSumUtil(ll ss, ll se, ll qs, ll qe, ll si, ll tree[], ll lazy[]) 
{ 
    if(qs>qe)
        return INF;

    if (lazy[si] != INF) 
    { 

        tree[si] = min(tree[si], lazy[si]);
        if (ss != se) 
        { 
            lazy[si*2 + 1]   = min(lazy[2*si+1], lazy[si]);
            lazy[si*2 + 2]   = min(lazy[2*si+2], lazy[si]);
        } 


        lazy[si] = INF; 
    } 

    if (ss>se || ss>qe || se<qs) 
        return INF; 

    if(ss == se)
        return tree[si];


    ll mid = (ss + se)/2;

    if(qs>mid)
        return getSumUtil(mid+1, se, qs, qe, 2*si+2, tree, lazy);
    else return getSumUtil(ss, mid, qs, qe, 2*si+1, tree, lazy);        

    //return min(getSumUtil(ss, mid, qs, qe, 2*si+1, tree, lazy),getSumUtil(mid+1, se, qs, qe, 2*si+2, tree, lazy)); 
} 


