/* constant */

const int MAX_N = 100000;
const long long LINF = 1LL << 62;

/* typedef */

typedef long long ll;
typedef pair<int,int> pii;
typedef pair<ll,int> pli;
typedef vector<pii> vpii;

/* global variables */

vpii nbrs[MAX_N];
ll ds[MAX_N];

/* subroutines */

/* main */

int main() {
  int n, m;
  scanf("%d%d", &n, &m);

  for (int i = 0; i < m; i++) {
    int l, r, c;
    scanf("%d%d%d", &l, &r, &c);
    l--, r--;
    nbrs[l].push_back(pii(r, c));
  }
  for (int i = 1; i < n; i++) nbrs[i].push_back(pii(i - 1, 0));

  fill(ds, ds + n, LINF);
  ds[0] = 0;

  priority_queue<pli> q;
  q.push(pli(0, 0));

  while (! q.empty()) {
    pli u = q.top(); q.pop();
    ll ud = -u.first;
    int &ui = u.second;
    if (ds[ui] != ud) continue;

    if (ui == n - 1) break;

    vpii &nbru = nbrs[ui];
    for (vpii::iterator vit = nbru.begin(); vit != nbru.end(); vit++) {
      int &vi = vit->first;
      ll vd = ud + vit->second;
      if (ds[vi] > vd) {
	ds[vi] = vd;
	q.push(pli(-vd, vi));
      }
    }
  }

  ll &gd = ds[n - 1];
  printf("%lld\n", (gd >= LINF) ? -1LL : gd);
  return 0;
}

#include<bits/stdc++.h>
using namespace std;

long long INF = 1e18;

struct SegmentTree {
private:
    int n;
    vector<long long> node;

public:
    // 元配列 v をセグメント木で表現する
    SegmentTree(vector<long long> v) {
        // 最下段のノード数は元配列のサイズ以上になる最小の 2 冪 -> これを n とおく
        // セグメント木全体で必要なノード数は 2n-1 個である
        int sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, INF);

        // 最下段に値を入れたあとに、下の段から順番に値を入れる
        // 値を入れるには、自分の子の 2 値を参照すれば良い
        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        //ここでminを使うことで区間の最小値となる、最大にすれば最大値
        for(int i=n-2; i>=0; i--) node[i] = min(node[2*i+1], node[2*i+2]);
    }

//x番目(0-indexed)の要素をvalにする
void update(int x, long long val) {
    // 最下段のノードにアクセスする
    x += (n - 1);

    // 最下段のノードを更新したら、あとは親に上って更新していく
    node[x] = min(node[x], val);
    while(x > 0) {
        x = (x - 1) / 2;
        //ここでminを使うことで区間の最小値となる、最大にすれば最大値
        node[x] = min(node[2*x+1], node[2*x+2]);
    }
}

// 要求区間 [a, b) 中の要素の最小値を答える(つまりbは含まれない)
// k := 自分がいるノードのインデックス
// 対象区間は [l, r) にあたる

long long getmin(int a, int b, int k = 0, int l = 0, int r = - 1) {
    // 最初に呼び出されたときの対象区間は [0, n)
    if(r < 0) r = n;

    // 要求区間と対象区間が交わらない -> 適当に返す(今回は最小値なので、結果に影響しないような大きい値を返しておく)
    if(r <= a || b <= l) return INF;

    // 要求区間が対象区間を完全に被覆 -> 対象区間を答えの計算に使う
    if(a <= l && r <= b) return node[k];

    // 要求区間が対象区間の一部を被覆 -> 子について探索を行う
    // 左側の子を vl ・ 右側の子を vr としている
    // 新しい対象区間は、現在の対象区間を半分に割ったもの
    long long vl = getmin(a, b, 2*k+1, l, (l+r)/2);
    long long vr = getmin(a, b, 2*k+2, (l+r)/2, r);
    return min(vl, vr);
}

};

int main(){
    int n, m;
    cin >> n >> m;
    vector<tuple<int, int, int>> edge(m);
    int a, b, c;
    for (int i = 0; i < m; i++) {
        cin >> a >> b >> c; a--; b--;
        edge[i] = tie(a, b, c);
    }
    sort(edge.begin(), edge.end());
    vector<long long> d(n, INF);
    d[0] = 0;
    SegmentTree seg(d);
    for (int i = 0; i < m; i++){
        tie(a, b, c) = edge[i];
        long long x = seg.getmin(a, n);
        if (x == INF) continue;
        seg.update(b, x + c);
    }
    long long ans = seg.getmin(n - 1, n);
    if (ans == INF) cout << - 1 << endl;
    else cout << ans << endl;
}

