using namespace std;

class Edge {
	unsigned long long to;
	unsigned long long cost;
public:
	Edge():to(ULLONG_MAX),cost(ULLONG_MAX){}
	Edge(unsigned long long t, unsigned long long c) {
		to = t;
		cost = c;
	}
	unsigned long long To() { return to; }
	unsigned long long Cost() { return cost; }
};

class Node {
	unsigned long long node_no;
	unsigned long long min_cost;
	bool done;
	vector<Edge> to_cost;
public:
	Node():node_no(ULLONG_MAX),min_cost(ULLONG_MAX),done(false){}
	void push_edge(unsigned long long t, unsigned long long c) {
		to_cost.push_back(Edge(t, c));
	}

	void set_no(unsigned long long n) { node_no = n; }
	unsigned long long get_no() { return node_no; }

	void set_cost(unsigned long long c) { min_cost = c; }
	unsigned long long Min_cost() { return min_cost; }

	void set_done() { done = true; }
	bool is_Done() { return done; }

	vector<Edge>::size_type count_Edge() { return to_cost.size(); }
	Edge Return_Edge(vector<Edge>::size_type i) {
		return to_cost[i];
	}

	//昇順に並べたいので　<　に　>　を返す
	friend bool operator<(const Node& a, const Node& b) {
		return a.min_cost > b.min_cost;
	}
};

int main() {
	unsigned long long N, M;
	cin >> N >> M;
	vector<Node> NodeA;
	for (unsigned long long i = 0; i < N; i++) {
		NodeA.push_back(Node());
		NodeA[i].set_no(i);
		if (i != 0) {
			NodeA[i].push_edge(i - 1ULL, 0ULL);
		}
	}

	for (unsigned long long i = 0; i < M; i++) {
		unsigned long long L, R, C;
		cin >> L >> R >> C;
		NodeA[L - 1].push_edge(R - 1, C);
	}

	NodeA[0].set_cost(0ULL);
	priority_queue<Node> search_list;
	search_list.push(NodeA[0]);

	while (search_list.empty() == false) {
		Node tmp = search_list.top();
		search_list.pop();

		while (true) {
			//完了フラグをセット
			NodeA[tmp.get_no()].set_done();

			//iからi-1のノードに向かう辺しかないノード
			if (tmp.count_Edge() == 1 && tmp.Return_Edge(0).Cost() == 0) {
				if (NodeA[tmp.Return_Edge(0).To()].is_Done() == false && NodeA[tmp.Return_Edge(0).To()].Min_cost() > tmp.Min_cost()) {
					NodeA[tmp.Return_Edge(0).To()].set_cost(tmp.Min_cost());
				}
				tmp = NodeA[tmp.Return_Edge(0).To()];
			}
			else {
				break;
			}
		}

		vector<Edge>::size_type max_count = tmp.count_Edge();
		for (vector<Edge>::size_type i = 0; i < max_count; i++) {
			unsigned long long to = tmp.Return_Edge(i).To();
			unsigned long long cost = tmp.Return_Edge(i).Cost();
			if (NodeA[to].is_Done() == false) {
				if (NodeA[to].Min_cost() > tmp.Min_cost() + cost) {
					NodeA[to].set_cost(tmp.Min_cost() + cost);
				}
				search_list.push(NodeA[to]);
