        for (int i = 0; i < e[v].size(); ++i) {
            int to = e[v][i].first, cost = e[v][i].second;
            if (d[to] > d[v] + cost) {
                d[to] = d[v] + cost;
                que.push({d[to], to});
            }
        }
    }
}

