lint inf = 1e15;

int main() {
  int N, M;
  cin >> N >> M;
  map<int, map<int, lint> > m;
  REP(i, M) {
    lint L, R, C;
    cin >> L >> R >> C;
    L--;
    R--;
    if (m[R][L] == 0)
      m[R][L] = C;
    else
      m[R][L] = min(m[R][L], C);
  }
  map<int, lint> ans;
  ans[0] = 0;
  for (auto em : m) {
    int R = em.first;
    ans[R] = inf;
    for (auto e : em.second) {
      int L = e.first;
      lint C = e.second;
      auto p = ans.lower_bound(L);
      if (p == ans.end()) continue;
      ans[R] = min(ans[R], ans[p->first] + C);
    }
    // ans[R]よりKeyが小さくValueが小さい要素を削除する
    auto itr1 = ans.lower_bound(R);
    lint v = itr1->second;
    auto itr2 = ans.lower_bound(R);
    itr2--;
    while (itr2->second >= v) {
      ans.erase(itr2);
      itr2 = ans.lower_bound(R);
      itr2--;
    }
  }
  if (ans[N - 1] == 0 or ans[N - 1] == inf) {
    cout << -1 << endl;
  } else {
    cout << ans[N - 1] << endl;
  }
  return 0;
}

