void pushup(int i){
	T[i]=min(T[i<<1],T[i<<1|1]);
}
void pushdown(int i){
	if(lazy[i]<inf){
		lazy[i<<1]=min(lazy[i<<1],lazy[i]);
		lazy[i<<1|1]=min(lazy[i<<1|1],lazy[i]);
		T[i<<1]=min(T[i<<1],lazy[i]);
		T[i<<1|1]=min(T[i<<1|1],lazy[i]);
		lazy[i]=inf;
	}
}
void build(int i,int l,int r){
	lazy[i]=inf;
	if(l==r){
		T[i]=inf;
		return;
	}
	int m=l+r>>1;
	build(i<<1,l,m);
	build(i<<1|1,m+1,r);
	pushup(i);
}
void update(int i,int L,int R,int l,int r,ll x){
	if(l<=L&&R<=r){
		lazy[i]=min(lazy[i],x);
		T[i]=min(T[i],x);
		return;
	}
	pushdown(i);
	int m=L+R>>1;
	if(l<=m)update(i<<1,L,m,l,r,x);
	if(r>=m+1)update(i<<1|1,m+1,R,l,r,x);
	pushup(i);
}
ll query(int i,int L,int R,int l,int r){
	if(l<=L&&R<=r)return T[i];
	pushdown(i);
	int m=L+R>>1;
	ll ans=inf;
	if(l<=m)ans=min(ans,query(i<<1,L,m,l,r));
	else ans=min(ans,query(i<<1|1,m+1,R,l,r));
	return ans;
}
