	for(int i=1; i<n; i++){
		for(auto p:v[i]){
			dp[i]=min(dp[i], seg.query(p.first, i)+p.second);
		}
		seg.update(i, dp[i]);
	}
	if(dp[n-1]<=INF/2) cout<<dp[n-1]<<endl;
	else cout<<-1<<endl;
	return 0;
}

