  map<int, ll> amap;
  for(int i=0;i<N;++i) amap[i] = -1;
  ll node, cost;
  while(!que.empty()) {
    state = que.top();que.pop();
    node = state.se;
    cost = state.fi;
    if(amap[node]>-1) continue;
    amap[node] = cost;
    for(int i=0;i<edge[node].size();++i) {
      if(amap[edge[node][i].fi]>-1 && amap[edge[node][i].fi]<=cost+edge[node][i].se) continue;
      que.push(mp(cost+edge[node][i].se, edge[node][i].fi));
    }
  }
  cout<<amap[N-1]<<endl;
}

