const ll MOD = 1e9+7;

const ll INF = 1e16;
class SegmentTree{
public:
    ll n;
    vector<ll> node;

    SegmentTree(vector<ll> v){
        ll size = v.size();
        n = 1;
        while(n < size) n *= 2;
        node.resize(2*n-1, INF);

        for(ll i = 0; i < size; i++){
            node[n-1+i] = v[i];
        }
        for(ll i = n-2; i >= 0; i--){
            node[i] = min(node[2*i+1], node[2*i+2]);
        }
    }

    void update(ll idx, ll val){
        idx += n-1;
        //node[idx] = val;
        chmin(node[idx], val);
        while(idx > 0){
            idx = (idx-1)/2;
            //node[idx] = min(node[2*idx+1], node[2*idx+2]);
            ll tmp = min(node[2*idx+1], node[2*idx+2]);
            chmin(node[idx], tmp);
        }
    }

    //return min value within [a,b)
    //call get_min(a, b);
    ll get_min(ll a, ll b, ll k=0, ll l=0, ll r=-1){
        if(r < 0) r = n;

        if(b <= l || r <= a) return INF;

        if(a <= l && r <= b) return node[k];

        ll vl = get_min(a, b, 2*k+1, l, (l+r)/2);
        ll vr = get_min(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};


int main(){
    ll N, M;
    cin >> N >> M;
    vector<ll> X(N, INF);
    X[0] = 0;
    SegmentTree tree(X);

    vector<tuple<ll, ll, ll>> BAC;
    REP(i,M){
        ll a, b;
        ll c;
        cin >> a >> b >> c;
        a--, b--;
        BAC.emplace_back(b, a, c);
    }

    sort(BAC.begin(), BAC.end());
    for(auto&& t : BAC){
        ll a, b;
        ll c;
        a = get<1>(t);
        b = get<0>(t);
        c = get<2>(t);
        ll m = tree.get_min(a,b+1);
        tree.update(b, m+c);
    }

    ll ans;
    ans = tree.get_min(N-1, N);
    //ans = tree.node[tree.n-1 + N-1];
    if(ans == INF)
        ans = -1;
    cout << ans << endl;
    return 0;
}

