    nei[i].l--;
    nei[i].r--;
  }
  sort(nei, nei+m, cmp_lrc);
  bool ch[V][V];
  for ( int i = 0; i < V; i++ ) { fill(ch[i], ch[i]+V, false); }
  for ( int i = 0; i < m; i++ ) {
    for ( int j = nei[i].l; j < nei[i].r; j++ ) {
      for ( int k = j+1; k <= nei[i].r; k++ ) {
        if ( ch[j][k] ) { continue; }
        edge e = {k, nei[i].c};
        G[j].push_back(e);
        ch[j][k] = true;
      }
    }
  }

  dijkstra(0);
  long long ans = ( d[V-1] != INF ) ? d[V-1] : -1;
  cout << ans << endl;
  return 0;
}

