void ps_up(int u)
{
    tree[u]=Min(tree[ls(u)],tree[rs(u)]);
}
void build(int pos,int l,int r){
	tree[pos]=llinf;
	tag[pos]=llinf;
	if(l==r) return;
	build(ls(pos),l,mid);
	build(rs(pos),mid+1,r);
	ps_up(pos); 
}
void ps_dw(int u)
{
    if(tag[u]<tag[ls(u)])
    {
        tree[ls(u)]=Min(tree[ls(u)],tag[u]);
        tag[ls(u)]=tag[u];
    }
    if(tag[u]<tag[rs(u)])
    {
        tree[rs(u)]=Min(tree[rs(u)],tag[u]);
        tag[rs(u)]=tag[u];
    }
    tag[u]=llinf;
}
void asv(int pos,int l,int r,int L,int R,int val)
{
    if(L<=l&&r<=R)
    {
        tag[pos]=Min(tag[pos],val);
        tree[pos]=Min(tree[pos],val);
        return;
    }
    if(tag[pos]!=llinf) ps_dw(pos);
    if(L<=mid) asv(ls(pos),l,mid,L,R,val);
    if(R>mid) asv(rs(pos),mid+1,r,L,R,val);
    ps_up(pos);
}
int query(int pos,int l,int r,int L,int R)
{
    if(L<=l&&r<=R)
    {
        return tree[pos];
    }
    int ret=llinf;
    if(tag[pos]!=llinf) ps_dw(pos);
    if(L<=mid) ret=Min(ret,query(ls(pos),l,mid,L,R));
    if(R>mid) ret=Min(ret,query(rs(pos),mid+1,r,L,R));
    return ret;
}
