struct graph{
	private:
	vector<vector<pll>> gt;
	vector<ll> dist;
	priority_queue<pll,vector<pll>,cmp> bruh;
	ll n;

	void proc(pll cur)
	{
		ll v=cur.fi,t=cur.se;
		if (t>dist[v]) return;
		for (auto g: gt[v])
			if (dist[g.fi]>dist[v]+g.se)
		{
			dist[g.fi]=dist[v]+g.se;
			bruh.push({g.fi,dist[v]+g.se});
		}
	}
	public:
	graph (ll n)
	{
		this->n=n;
		for (ll i=0;i<n;i++)
		{
			gt.push_back({});
			dist.push_back(0);
		}
	}
	void addEdge (ll a, ll b, ll c)
	{
		gt[a].push_back({b,c});
	}
	vector<ll> dijkstra(ll s)
	{
		for (ll i=0;i<n;i++)
		{
			dist[i]=1e9;
		}
		dist[s]=0;
		bruh.push({s,0});
		while(bruh.size())
		{
			auto toproc(bruh.top());
			bruh.pop();
			proc(toproc);
		}
		return dist;
	}
};
