struct node
{
    int val;
    int vl, vr;
    node *l = 0, *r = 0;
    node() {}
    node(int tl, int tr, vector <int> &a)
    {
        vl = tl, vr = tr;
        if (vr - vl == 1)
        {
            val = a[vl];
            return;
        }
        int vm = (vl + vr) >> 1;
        l = new node(vl, vm, a), r = new node(vm, vr, a);
        val = min(l->val, r->val);
    }
    int get(int ql, int qr)
    {
        if (vl == ql && vr == qr)
            return val;
        int vm = (vl + vr) >> 1;
        if (qr <= vm)
            return l->get(ql, qr);
        if (ql >= vm)
            return r->get(ql, qr);
        return min(l->get(ql, vm), r->get(vm, qr));
    }
    void change(int pos, int x)
    {
        if (vr - vl == 1)
        {
            val = x;
            return;
        }
        int vm = (vl + vr) >> 1;
        if (pos < vm)
            l->change(pos, x);
        else
            r->change(pos, x);
        val = min(l->val, r->val);
    }
};

