    for (auto rlc : a)
    {
        int r = rlc.x.x, l = rlc.x.y, c = rlc.y;
        int val = t->get(l, r + 1);
        val += c;
        if (d[r] > val)
            d[r] = val, t->change(r, val);
    }
    if (d[n - 1] == INF)
        cout << -1;
    else
        cout << d[n - 1];
    return 0;
}

