void solve() {
    i64 N = RD();
    i64 M = RD();

    vector<vector<pair<i64,i64>>> G(N);
    REP(v, N-1) {
        G[v+1].emplace_back(v, 0);
    }
    REP(_, M) {
        i64 l = RD1();
        i64 r = RD1();
        i64 c = RD();
        G[l].emplace_back(r, c);
        G[r].emplace_back(l, c);
    }

    auto que = priority_queue_make<pair<i64,i64>>(greater<>{});
    vector<i64> dist(N, INF);
    que.emplace(0, 0);
    dist[0] = 0;
    while(!que.empty()) {
        i64 d,v; tie(d,v) = POP(que);
        if(dist[v] < d) continue;

        for(const auto& e : G[v]) {
            i64 to,cost; tie(to,cost) = e;
            i64 d_new = d + cost;
            if(chmin(dist[to], d_new))
                que.emplace(d_new, to);
        }
    }
    DBG(dist);

    i64 ans = dist[N-1];
    if(ans == INF) ans = -1;

    PRINTLN(ans);
}

