const long long INF = 1e18 + 5;
template<typename Type>
struct SegmentTree {
        vector<Type> data;
        int n;
        SegmentTree(int x) {
                n = pow(2, ceil(log2(x)));
                data.resize(2 * n - 1, INF); //initial value
        }
        Type merge(Type x, Type y) { //merge function
                return min(x, y);
        }
        void update(int k, Type p) { //update k-th value to p
                k += n - 1;
                data[k] = p;
                while (k > 0) {
                        k = (k - 1) / 2;
                        data[k] = merge(data[k * 2 + 1], data[k * 2 + 2]);
                }
        }
        // [l, r)
        Type query(int a, int b) { return query(a, b, 0, 0, n); }
        Type query(int a, int b, int k, int l, int r) {
                if (r <= a || b <= l) return INF; //initial value
                if (a <= l && r <= b) return data[k];
                int m = (l + r) / 2;
                return merge(query(a, b, k * 2 + 1, l, m), query(a, b, k * 2 + 2, m, r));
        }
};

int main() {
        int n, m;
        scanf("%d%d", &n, &m);
        vector<vector<pair<int, int>>> g(n);
        rep(i, m) {
                int l, r, c;
                scanf("%d%d%d", &l, &r, &c);
                l --, r --;
                g[r].push_back({l, c});
        }
        SegmentTree<long long> seg(n);
        rep(i, n) {
                seg.update(i, INF);
        }
        seg.update(0, 0);
        rep(i, n) if (i) {
                for (auto a : g[i]) {
                        int l = a.first;
                        int c = a.second;
                        seg.update(i, min((long long) c + seg.query(l, i), seg.query(i, i + 1)));
                }
        }
        if (seg.query(n - 1, n) >= INF) {
                printf("-1\n");
        } else {
                printf("%lld\n", seg.query(n - 1, n));
        }
        return 0;
}

