class djikstra {
private:
    map<ll, set<pair<ll, ll>>> path; //src dst cost
    map<ll, ll> dist; //dst cost
public:
    void compute(ll start) {
        dist.clear();
        dist[start] = 0;
        priority_queue<pair<ll, ll>, deque<pair<ll, ll>>, greater<>> q;
        for (auto &e:path[start]) q.push(make_pair(e.second, e.first));
        while (!q.empty()) {
            auto c = q.top();
            q.pop();
            if (dist.find(c.second) != dist.end()) continue;
            dist[c.second] = c.first;
            for (auto &e:path[c.second]) {
                if (dist.find(e.first) != dist.end()) continue;
                q.push(make_pair(c.first + e.second, e.first));
            }
        }
    }

    void add_path(ll src, ll dst, ll cost) {
        path[src].insert(make_pair(dst, cost));
    }

    ll get_dist(ll dst) {
        if (dist.find(dst) == dist.end()) return -1;
        return dist[dst];
    }
};

