vector<long long> dijkstra(int n,int start,vector<vector<pair<long long, long long>>> &edge){
    vector<long long> shortest(n,linf);
    priority_queue<pair <long long, long long> ,vector<pair<long long,long long>>,greater<pair<long long,long long>>  > que;
    shortest[start] = 0LL;
    que.push(make_pair(0,start));
    while (!que.empty()){
        pair<long long,long long> now = que.top();
        que.pop();
        long long v = now.second;
        if (shortest[v] < now.first){
            continue;
        }else{
            for (int i = 0; i < edge[v].size(); ++i){
                long long to = edge[v][i].first;
                long long cost = edge[v][i].second;
                long long new_cost = shortest[v]+cost;
                if (new_cost < shortest[to]){
                    shortest[to] = new_cost;
                    que.push(make_pair(new_cost,to));
                }
            }
        }
    }
    return shortest;
}



