#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N=1e5+5;
int n,m;
ll t[N<<2],lz[N<<2];
vector<pair<int,int> >v[N];
void build(int l,int r,int k)
{
    t[k]=lz[k]=1e18;
    if(l==r&&l==1) t[k]=0;
    if(l==r) return;
    int m=l+r>>1;
    build(l,m,k<<1);build(m+1,r,k<<1|1);
}
void update(int l,int r,int k)
{
    if(l==r) return;
    t[k<<1]=min(t[k<<1],lz[k]);
    t[k<<1|1]=min(t[k<<1|1],lz[k]);
    lz[k<<1]=min(lz[k<<1],lz[k]);
    lz[k<<1|1]=min(lz[k<<1|1],lz[k]);
    lz[k]=1e18;
}
ll query(int l,int r,int k,int x)
{
    update(l,r,k);
    if(l==r) return t[k];
    int m=l+r>>1;
    if(x<=m) return query(l,m,k<<1,x);
    else return query(m+1,r,k<<1|1,x);
}
void fix(int l,int r,int k,int x,int y,ll v)
{
    if(r<x||l>y) return;
    update(l,r,k);
    if(l>=x&&r<=y)
    {
        t[k]=min(t[k],v);lz[k]=min(lz[k],v);update(l,r,k);return;
    }
    int m=l+r>>1;
    fix(l,m,k<<1,x,y,v);fix(m+1,r,k<<1|1,x,y,v);
}
int main()
{
    scanf("%d%d",&n,&m);
    for(int i=1;i<=m;i++)
    {
        int l,r,c;
        scanf("%d%d%d",&l,&r,&c);
        v[l].push_back({r,c});
    }
    build(1,n,1);
    for(int i=1;i<=n;i++)
    {
        ll mn=query(1,n,1,i);
        for(int j=0;j<v[i].size();j++)
            fix(1,n,1,i,v[i][j].first,mn+v[i][j].second);
    }
    ll ans=query(1,n,1,n);
    if(ans==1e18) ans=-1;
    printf("%lld\n",ans);
}

