  REP(i, M) {
    int l, r, c;
    scanf("%d %d %d", &l, &r, &c);
    G[l].push_back(PI(r, c));
  }

  REP2(i, 1, N) {
    G[i + 1].push_back(PI(i, 0));
  }

  D[1] = 0;
  priority_queue<PI, vector<PI>, greater<PI>> que;
  que.push(PI(0, 1));

  while (!que.empty()) {
    PI p = que.top();
    que.pop();
    // cout << p << endl;
    if (p.second == N) {
      break;
    }

    if (p.first > D[p.second]) {
      continue;
    }

    for (const auto &w: G[p.second]) {
      if (D[w.first] > D[p.second] + w.second) {
        D[w.first] = D[p.second] + w.second;
        que.push(PI(D[w.first], w.first));
      }
    }
  }

  if (D[N] < INF) {
    cout << D[N] << endl;
  } else {
    cout  << -1 << endl;
  }

  return 0;
}

