//非再帰抽象セグ木 0-indexed 単位元はiで指定
template <class T>
class SegmentTree {
 private:
  long long n;
  T init;
  std::vector<T> dat;
  std::function<T(T, T)> fn;

 public:
  SegmentTree(long long i, T para, std::function<T(T, T)> fun)
      : init(para), fn(fun) {
    n = 1;
    while (n < i) {
      n *= 2;
    }
    dat = std::vector<T>(2 * n - 1, init);
  }

  // k番目(0-indexed)を値aで更新,dest=trueのときは更新前を破壊して初期化する
  void update(long long k, T a, bool dest) {
    k += n - 1;
    if (dest)
      dat[k] = a;
    else
      dat[k] = fn(dat[k], a);

    while (k > 0) {
      k = (k - 1) / 2;
      dat[k] = fn(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  T query(long long a, long long b){
    assert(0<=a&&b<=n);
    T val=init;

    long long l=a+n-1,r=b+n-1;
    for(;l<r;l=(l>>1),r=(r>>1)){
      if(!(r&1)){
        r--;
        val=fn(val,dat[r]);
      }
      if(!(l&1)){
        val=fn(val,dat[l]);
        l++;
      }
    }

    return val;
  }
};

int main() {
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);

  ll n,m;
  std::cin>>n>>m;

  const ll MAX=1e16;

  std::vector<Edge> edge(m);
  rep(i,0,m){
    ll l,r,c;
    std::cin>>l>>r>>c;
    l--;r--;
    edge[i]={l,r,c};
  }

  std::sort(all(edge),[](Edge t1,Edge t2){
    return t1.r<t2.r;
  });

  ll itr=0;

  SegmentTree<ll> seg(n+2,MAX,[](ll a,ll b){return std::min(a,b);});

  seg.update(0,0,true);

  rep(i,1,n){
    while(itr!=m&&edge[itr].r==i){
      seg.update(i,seg.query(edge[itr].l,edge[itr].r)+edge[itr].cost,false);

      itr++;
    }
  }

  if(seg.query(n-1,n)==MAX)std::cout<<-1;
  else std::cout<<seg.query(n-1,n);

  return 0;
}

