// computational complexity : O(E*logV)

struct edge{
    int to, cost;
};

int V,E;// number of (vertices, edges)
vector<vector<edge>> graph;
vector<long long int> d;// shortest distances

void Dijkstra(int s){// s = starting point
    priority_queue<
        pair<int, int>// temporarily keeping (shortest distance, vertex)
        , vector<pair<int, int>>, greater<pair<int, int>>// shorter ones first
    > pq;

    // initialize (INF)
    for(int i=0; i<V; i++){
        d[i] = INF;
    }
    d[s] = 0;
    pq.push({0,s});

    // search
    pair<int, int> current;// (shortest-distance confirmed, vertex)
    while(!pq.empty()){
        current = pq.top(); pq.pop();

        int v = current.second;
        if(d[v] < current.first){
            continue;// ignore (not the shortest path)
        }
        // else (need to check)
        for(edge e : graph[v]){// adjacent nodes
            if(d[e.to] > d[v] + e.cost){
                d[e.to] = d[v] + e.cost;// update minimum cost
                pq.push({d[e.to], e.to});
            }
        }
    }
}

int main(){
    cin >> V >> E;
    graph.resize(V);
    d.resize(V);
    for(int i=0; i+1<V; i++){
        graph[i+1].push_back({i,0});
    }

    for(int i=0; i<E; i++){
        int l, r, c;
        cin >> l >> r >> c;
        l -= 1;
        r -= 1;
        graph[l].push_back({r,c});
    }

    Dijkstra(0);// starting from s
    if(d[V-1] != INF) cout << d[V-1] << endl;
    if(d[V-1] == INF) cout << -1 << endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int maxn=1e5+5;
int mn[maxn<<3],lazy[maxn<<3];
void up(int t){
	mn[t]=min(mn[t<<1],mn[t<<1|1]);
}
void down(int t){
	if(lazy[t]){
		mn[t<<1]=min(mn[t<<1],lazy[t]);
		mn[t<<1|1]=min(mn[t<<1|1],lazy[t]);
		lazy[t<<1]=min(lazy[t<<1],lazy[t]);
		lazy[t<<1|1]=min(lazy[t<<1|1],lazy[t]);
		lazy[t]=0;
	}
}
void build(int l,int r,int t){
	if(l==r){
		mn[t]=(1<<30);
		return ;
	}
	int mid=(l+r)>>1;
	build(l,mid,t<<1);
	build(mid+1,r,t<<1|1);
	up(t);
}
void update(int ll,int rr,int l,int r,int num,int t){
	if(ll>rr) return ;
	if(ll<=l&&r<=rr){
		mn[t]=min(mn[t],num);
		if(lazy[t]) lazy[t]=min(num,lazy[t]);
		else lazy[t]=num;
		return ;
	}
	int mid=(l+r)>>1;
	down(t);
	if(ll<=mid) update(ll,rr,l,mid,num,t<<1);
	if(rr>mid) update(ll,rr,mid+1,r,num,t<<1|1);
	up(t);
}
int solve(int pos,int l,int r,int t){
	if(l==r){
		return mn[t];
	}
	int mid=(l+r)>>1;
	down(t);
	if(pos<=mid) return solve(pos,l,mid,t<<1);
	else return solve(pos,mid+1,r,t<<1|1);
} 
struct query{
	int l,r,w;
	bool operator<(const query &h)const{
		return l==h.l?r<h.r:l<h.l;
	}
}e[maxn];
int main(){
	ios::sync_with_stdio(0);
	cin.tie(0),cout.tie(0);
	int n,m;
	cin>>n>>m;
	build(1,n,1);
	for(int i=1;i<=m;++i){
		cin>>e[i].l>>e[i].r>>e[i].w;
	}
	sort(e+1,e+m+1);
	update(1,1,1,n,0,1);
	for(int i=1;i<=m;++i){
		int tmp=solve(e[i].l,1,n,1);
		update(e[i].l+1,e[i].r,1,n,tmp+e[i].w,1);
	}
	int tmp=solve(n,1,n,1);
	cout<<(tmp==(1<<30)?-1:tmp)<<'\n';
	return 0;
}

