#define WHITE 0
#define GRAY 1
#define BLACK 2
ll n,m;
vector<pair<ll,ll> >adj[100001];//邻接表表示
vector<ll>d;
void dijkstraplus(){
    d.resize(n+m-1);
    priority_queue<pair<ll,ll> > pq;
    ll color[10001];
    for(ll i=0;i<n;i++){
        d[i]=INF;
        color[i]=WHITE;
    }
    d[0]=0;
    pq.push(make_pair(0,0));//pq和adj里面的元素是反的
    color[0]=GRAY;
    while(!pq.empty()){
        pair<ll,ll> f=pq.top();
        pq.pop();
        ll u=f.second;
        color[u]=BLACK;
        if(d[u]<f.first*(-1)) //pq是从大到小所以要*-1 如果不是最小路径则忽略
            continue;
        for(ll j=0;j<adj[u].size();j++){
            ll v=adj[u][j].first;
            if(color[v]==BLACK)
                continue;
            if(d[v]>d[u]+adj[u][j].second){
                d[v]=d[u]+adj[u][j].second;
                pq.push(make_pair(d[v]*(-1),v));
                color[v]=GRAY;
            }
        }
    }
    //for(int i=0;i<n;i++)
     //   cout<<d[i]<<endl;
    if(d[n-1]==INF)
       d[n-1]=-1;
    cout<<d[n-1]<<endl;
}
