void update(int L,int R,ll v)
{
    while(L<=R){
        if(L&1)tree[L] = min(tree[L],v),L++;
        if(!(R&1))tree[R] = min(tree[R],v),R--;
        L>>=1; R>>=1;
    }
    return;
}

ll getans(int tmp)
{
    ll res = LINF;
    while(tmp){
        res = min(res,tree[tmp]);
        tmp>>=1;
    }
    return res;
}

