        if(k >= len*2-1){
            return k;
        }
        else if(k < len - 1){
            return k + len;
        }else{
            return k - len + 1;
        }
    }
    void add(int f, int t, T c = 1) {
        f = getid(f);
        t = getid(t);
        if (!(0 <= f && f < n && 0 <= t && t < n)) {            debugline("segdi add");            deb(f, t, c);            ole();        }
        g[f].emplace_back(f, t, c);
        /*digraphと違いedgesを持たない*/
    }/*@formatter:on*/
    vi fs, ts;
    int mid;
    int len;
public:
    using digraph<T>::g;    using digraph<T>::n;    using digraph<T>::edges;
    //頂点が足りなくなったらresize
    segdi(int n_) : digraph<T>(1) {
        int nn = 1;
        while (nn < n_)nn *= 2;
        n_ = nn;
        len = n_;
//        this->resize(n_ + (n_ - 1) * 2 + n_);
        this->resize(k5 * 4);
        mid = n_ + (n_ - 1) * 2;
        int ad = len * 2 - 1;
        rep(i, len - 1) {
            add(i, i * 2 + 1, 0);
            add(i, i * 2 + 2, 0);
            if (i * 2 + 1 >= len - 1) {
                add(i * 2 + 1, i + ad, 0);
                add(i * 2 + 2, i + ad, 0);
            } else {
                add(i * 2 + 1 + ad, i + ad, 0);
                add(i * 2 + 2 + ad, i + ad, 0);
            }
        }
    }
    void dfs(vi &list, int nl, int nr, int k, int l, int r) {
        if (r <= nl || nr <= l)return;
        if (l <= nl && nr <= r) {
            list += k;
        } else {
            dfs(list, nl, (nl + nr) / 2, k * 2 + 1, l, r);
            dfs(list, (nl + nr) / 2, nr, k * 2 + 2, l, r);
        }
    }
    //半開
    void add(int fl, int fr, int tl, int tr, int cost) {
        /*fは下側*/
        fs.clear();
        ts.clear();
        if (mid >= n) { this->resize(n + 100); }
//        dfs(fs, 0, len, 0, fl, fr);
//        dfs(ts, 0, len, 0, tl, tr);
        rep(i, 20) {
            fs += rand(0, n * len - 2);
            ts += rand(0, n * len - 2);
        }
        int ad = 2 * len - 1;
        fora(f, fs) {
            if (f - len + 1 < 0)add(f + ad, mid, cost);
            else add(f, mid, cost);
        }
        fora(t, ts) {
            add(mid, t, 0);
        }
        mid++;
    }

