template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    vector<vector<pll>> G(N);
    vector<int> imos(N+1);
    for(int i = 0; i < M;i++){
        int L,R,C; cin >> L >> R >> C;
        L--; R--;
        G[L].push_back(pll(R,C));

        imos[L]++;
        imos[R]--;
    }
    for(int i = 0; i < N;i++){
        imos[i+1] += imos[i];
    }

    for(int i = 0; i < N;i++){
        if(imos[i]) G[i+1].push_back(pll(i,0));
    }
    vector<ll> dist(N,LINF);
    priority_queue<pll> pq;
    pq.push(pll(0,0));
    dist[0] = 0;
    while(pq.size()){
        ll cost,n;
        tie(cost,n) = pq.top(); pq.pop();
        if(dist[n] < cost) continue;
        for(auto p:G[n]){
            if(dist[p.first] > dist[n] + p.second){
                dist[p.first] = dist[n] + p.second;
                pq.push(pll(-dist[p.first],p.first));
            }
        }
    }
    res = dist[N-1];
    if(res == LINF) res = -1;
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    // solve(0);
    cout << fixed << setprecision(15) << solve<ll>() << endl;
    return 0;
}

