vector<lint> bellman_ford(Edges<int> & edges,int V,int S)
{
  vector<lint> path(V,I64_MAX);
  path[S] = 0;

  for (int i = 0; i < V; i++)
  {
    for(auto &e :edges)
    {
      if(path[e.src] == I64_MAX) continue;
      path[e.to] = min(path[e.to],path[e.src] + e.cost);
    }
  }

  for(auto &e:edges)
  {
    if(path[e.src] == I64_MAX)continue;
    if(path[e.src] + e.cost < path[e.to]) return vector<lint>();
  }

  return path;
}


