using namespace std;

const int nsz = 1e5;
const num inf = 0x3f3f3f3f3f3f3f3f;
int n, m;
num ans;
pair< pair<int, int>, int > dat[nsz + 5];

struct segment_tree {
#define ls (u << 1)
#define rs (u << 1 | 1)
	num mn[4 * nsz + 5], del[4 * nsz + 5];

	void inline down(int u) {
		if (del[u] == inf)  return;
		mn[ls] = min(mn[ls], del[u]), mn[rs] = min(mn[rs], del[u]);
		del[ls] = min(del[ls], del[u]), del[rs] = min(del[rs], del[u]);
		del[u] = inf;
	}

	void init(int u = 1, int l = 1, int r = n) {
		mn[u] = del[u] = inf;
		if (l == r)  return;
		int md = (l + r) >> 1;
		init(ls, l, md);
		init(rs, md + 1, r);
	}

	void upd(int el, int er, num val, int u = 1, int l = 1, int r = n) {
		if (l >= el && r <= er) {
			mn[u] = min(mn[u], val);
			del[u] = min(del[u], val);
			return;
		}
		down(u);
		int md = (l + r) >> 1;
		if (el <= md) {
			upd(el, er, val, ls, l, md);
		}
		if (er >= md + 1) {
			upd(el, er, val, rs, md + 1, r);
		}
		mn[u] = min(mn[ls], mn[rs]);
	}

	num qry(int el, int er, int u = 1, int l = 1, int r = n) {
		if (l >= el && r <= er)  return mn[u];
		down(u);
		int md = (l + r) >> 1;
		num res = inf;
		if (el <= md) {
			res = qry(el, er, ls, l, md);
		}
		if (er >= md + 1) {
			res = min(res, qry(el, er, rs, md + 1, r));
		}
		return res;
	}
};
segment_tree tr;

int main() {
	scanf("%d%d", &n, &m);
	cont (i, m) {
		int l, r, w;
		scanf("%d%d%d", &l, &r, &w);
		dat[i] = make_pair(make_pair(l, r), w);
	}
	sort(dat + 1, dat + m + 1);
	tr.init();
	tr.upd(1, 1, 0);
	int it = 1;
	cont (u, n) {
		for (; dat[it].first.first == u; ++it) {
			int l = dat[it].first.first, r = dat[it].first.second, w = dat[it].second;
			tr.upd(l, r, tr.qry(l, r) + w);
		}
	}
	ans = tr.qry(n, n);
	ans = ans == inf ? -1 : ans;
	printf("%lld\n", ans);
}

