const ll mod=1e9+7;
const ll inf=1e15;

class SegmentTree{
public:
	vector<ll> dat;
	int n,max_n;

	SegmentTree(int n_){
		n=1;
		max_n=1<<17;
		//要素数を2のべき乗にする
		while(n<n_) n*=2;
		rep(i,2*n-1) dat.push_back(inf);//全ての要素をinfで初期化
	}

	//k番目の値をaに変更する
	void update(int k,ll a){
		k+=n-1;
		dat[k]=a;
		while(k>0){
			k=(k-1)/2;
			dat[k]=min(dat[2*k+1],dat[2*k+2]);
		}
	}

	//[a,b)の最小値を求める
	//query(a,b,0,0,st.n)で呼ぶ←ここnの呼び出し注意
	ll query(int a,int b,int k,int l,int r){
		if(r<=a || b<=l) return inf;
		if(a<=l && r<=b) return dat[k];
		else{
			ll vl=query(a,b,2*k+1,l,(l+r)/2);
			ll vr=query(a,b,2*k+2,(l+r)/2,r);
			return min(vl,vr);
		}
	}
};

