vl d;
void dijkstra(v(vp) &G,int V,int s) {
// G[f][i] = P(t,c) means that from `f` to `t` 's cost is `c` 
  d = vl(V,LINF);
  priority_queue<pair<ll,ll>,vector<pair<ll,ll>>, greater<pair<ll,ll>>> que;
  d[s] = 0;
  que.push(pair<ll,ll>(0,s));
  while(!que.empty()) {
    pair<ll,ll> p = que.top();
    que.pop();
    int tar = p.second;
    if(d[tar] < p.first) continue;
    rep(i,sz(G[tar])) {
      pair<ll,ll> e = G[tar][i];
      if(d[e.first] > d[tar] + e.second) {
        d[e.first] = d[tar] + e.second;
        que.push(pair<ll,ll>(d[e.first],e.first));
      }
    }
  }
}

