template<typename T>
class Dijkstra {
public:
  int n;
  T INF = numeric_limits<T>::max();
  vector< vector< pair<int,T> > > g;

  Dijkstra(int _n) : n(_n) {
    g.resize(n);
  }

  void add_edge(int u, int v, T w) {
    assert(0 <= u && u < n && 0 <= v && v < n);
    assert(w >= 0);
    g[u].emplace_back(v, w);
  }

  vector<T> short_path(int s) {
    vector<T> dis(n, INF);
    set< pair<T,int> > bag;
    bag.insert(make_pair(0, s));
    while (bag.size()) {
      int u, v;
      T w, cost;
      tie(cost, u) = *bag.begin();
      bag.erase(bag.begin());
      if (dis[u] > cost) {
        dis[u] = cost;
        for (auto i : g[u]) {
          tie(v, w) = i;
          bag.insert(make_pair(w + cost, v));
        }
      }
    }
    return dis;
  }
};

