        tie(l,r,c) = query[i];
        auto from = S.query(l,r);
        if(from==S.identity){
            cout << "-1\n";
            return 0;
        }
        auto to = S.query(r,r+1);
        if(to>from+c) S.set_val(r,from+c);
    }

    ll ans = S.get_val(N-1);
    cout << ans << endl;
}















