struct RangeAddQuery {
	int n;
	vector<int> d;
	int time;
	RangeAddQuery(int m) {
		for (n = 1; n < m; n *= 2);
		d.assign(n * 2, INF);
	}
	//[l, r)
	void add(int l, int r, int x) {
		for (; l && l + (l&-l) <= r; l += l&-l)
			d[(n + l) / (l&-l)] = min(x, d[(n + l) / (l&-l)]);
		for (; l < r; r -= r&-r)
			d[(n + r) / (r&-r) - 1] = min(x, d[(n + r) / (r&-r) - 1]);
	}
	int get(int i) {
		int ret = d[n + i];
		for (int j = (n + i) / 2; j > 0; j >>= 1)
			ret = min(ret, d[j]);
		return ret;
	}
};

