int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll N, M;
  cin >> N >> M;
  vector<vector<edge>> G(N);
  for (ll i = 0; i < M; ++i) {
    ll L, R, C;
    cin >> L >> R >> C;
    L -= 1;R -= 1;
    G.at(L).push_back({R, C});
  }
  for (ll i = 1; i < N - 1; ++i) {
    G.at(i + 1).push_back({i, 0});
  }
  ll ans = dijkstra(0, N, G).at(N - 1);
  if (ans == INF) {
    cout << -1 << "\n";
  }
  else {
    cout << ans << "\n";
  }
}

