namespace Cesare {

	ll n, m, Ans;

	struct Node {
		ll l, r, c;
		inline bool operator < (const Node &b) const {
			return l == b.l? r < b.r: l < b.l;
		}
	} K[N];

	#define ls(x) (x << 1)
	#define rs(x) (x << 1 | 1)
	#define mid ((l + r) >> 1)

	ll T[N << 2], Tag[N << 2];

	inline void pushUp(ll p) {
		T[p] = min(T[ls(p)], T[rs(p)]);
	}

	inline void pushDown(ll p, ll l, ll r) {
		if (Tag[p] >= INF) return ;
		Tag[ls(p)] = min(Tag[ls(p)], Tag[p]);
		Tag[rs(p)] = min(Tag[rs(p)], Tag[p]);
		T[p] = min(T[p], Tag[p]);
		T[ls(p)] = min(T[ls(p)], Tag[p]), 
		T[rs(p)] = min(T[rs(p)], Tag[p]);
		Tag[p] = INF;
	}

	inline void Update(ll p, ll l, ll r, ll ul, ll ur, ll k) {
		if (l >= ul && r <= ur) {
			T[p] = min(T[p], k); 
			Tag[p] = min(Tag[p], k);
			return ;
		}
		pushDown(p, l, r);
		if (mid >= ul) Update(ls(p), l, mid, ul, ur, k);
		if (mid < ur)  Update(rs(p), mid + 1, r, ul, ur, k);
		pushUp(p);
	}

	inline ll Query(ll p, ll l, ll r, ll x, ll res = INF) {
		if (l == r) return T[p]; 
		pushDown(p, l, r);
		if (mid >= x) res = min(res, Query(ls(p), l, mid, x));
		if (mid < x)  res = min(res, Query(rs(p), mid + 1, r, x));
		return res;
	}

	int main() {
		n = read(), m = read();
		for (int i = 1; i <= m; ++i)
			K[i] = (Node) {read(), read(), read()};
		sort(K + 1, K + m + 1);
		Set (T, 0x3f);
		Set (Tag, 0x3f);
		Update(1, 1, n, 1, 1, 0);
		for (int i = 1, j = 1; i <= n; ++i) {
			ll Mn = Query(1, 1, n, i);
			for (; j <= m && K[j].l == i; ++j) 
				Update(1, 1, n, i, K[j].r, Mn + K[j].c);
		} 
		Ans = Query(1, 1, n, n);
		return wln(Ans >= INF? -1: Ans), 0;
	}

}

