const int MAXN = 1e5 + 10, inf = 1e9 + 10;

int n, m;
int l, r, c;
long long d[MAXN];
set <pair <int, int> > st;
vector <pair <int, int> > adj[MAXN];

void dijk() {
	for (int i = 2; i <= n; i++)
		d[i] = inf;

	st.insert({0, 1});

	while (st.size()) {
		int x = st.begin() -> second;
		st.erase(st.begin());
		for (auto y: adj[x])
			if (d[y.first] > d[x] + y.second) {
				st.erase({d[y.first], y.first});
				d[y.first] = d[x] + y.second;
				st.insert({d[y.first], y.first});
			}
	}
}

