struct segTree{
  ll N;
  vll dat;
  void init(ll n){
    N = 1;
    while(N < n)
      N *= 2;

    dat = vll(2*N, INF);
  }

  void update(ll k, ll a){
    k += N-1; //leaf
    dat[k] = a;
    while(k > 0){
      k = (k-1)/2;
      dat[k] = min(dat[k*2+1], dat[k*2+2]);
    }
  }

  ll query(ll a, ll b){
    if(a > b)
      return query(b,a,0,0,N);
    else
      return query(a,b,0,0,N);
  }

  ll query(ll a, ll b, ll k, ll l, ll r){
    if(b <= l || r <= a)
      return LLINF;

    if(a <= l || r <= b)
      return dat[k];
    else{
      ll m = (l+r)/2;
      ll vl = query(a, b, k*2+1, l, m);
      ll vr = query(a, b, k*2+1, m, r);
      return min(vl, vr);
    }
  }
};


