  ll getMin(ll x, ll y, ll k=0, ll l=0, ll r=-1){
    if(r < 0) r = n;
    if(r<=x || l>=y) return INF;
    if(x<=l && r<=y) return node[k];

    ll vl = getMin(x, y, 2*k+1, l, (l+r)/2);
    ll vr = getMin(x, y, 2*k+2, (l+r)/2, r);
    return min(vl,vr);
  }
};

int main(){
  ll n,q;
  cin >> n >> q;
  segTree t;
  t.init(n);

  t.update(0,0);

  ll xx[q],tt[q],ss[q];
  vector<pair<int,PII>> p;
  rep(i,q){
    cin >> ss[i] >> tt[i] >> xx[i];
    p.push_back({ss[i],{tt[i],i}});
  }
  sort(all(p));
  rep(i,q){
    int idx = p[i].second.second;
    ll a = ss[idx];
    ll b = tt[idx];
    ll c = xx[idx];
    a--,b--;

    ll tmp = t.getMin(a,n);
    ll tmin = t.getMin(b,b+1);

    if(tmp == INF) continue;
    if(tmp + c > tmin) continue;
    t.update(b,tmp+c);
  }
  ll ans = t.getMin(n-1,n);
  if(ans == INF) cout << -1 << endl;
  else cout << ans << endl;
  return 0;
}

