typedef long long ll;
const int MOD=1e9+7;
const int INF=1e9;
const ll LINF=1e18;

struct SegmentTree{
private:
    int n;
    vector<ll> node;
public:
    SegmentTree(const int sz){
        n=1;
        while(n<sz)n*=2;
        node.resize(2*n-1,LINF);
        node[n-1]=0;
        for(int i=n-2;i>=0;i--){
            node[i]=min(node[2*i+1],node[2*i+2]);
        }
    }
    void update(int a,ll x){
        a+=n-1;
        node[a]=x;
        while(a>0){
            a=(a-1)/2;
            node[a]=min(node[2*a+1],node[2*a+2]);
        }
    }
    ll get(int a,int b,int k=0,int l=0,int r=-1){
        if(r==-1)r=n;
        if(b<=l||r<=a)return LINF;
        if(a<=l&&r<=b){
            return node[k];
        }
        else{
            return min(get(a,b,2*k+1,l,(l+r)/2),get(a,b,2*k+2,(l+r)/2,r));
        }
    }
    ll get(int a){
        return node[a+n-1];
    }
};

int main(){
    int n,m;
    cin>>n>>m;
    pair<pair<int,int>,int> p[m];
    for(int i=0;i<m;i++){
        int l,r,c;
        cin>>l>>r>>c;
        --l,--r;
        p[i]={{r,l},c};
    }
    sort(p,p+m);
    SegmentTree seg(n);
    for(int i=0;i<m;i++){
        int l=p[i].first.second;
        int r=p[i].first.first;
        int c=p[i].second;
        ll t=seg.get(l,r);
        if(seg.get(r)>t+c){
            seg.update(r,t+c);
        }
    }
    if(seg.get(n-1)==LINF){
        cout<<-1<<endl;
    }
    else{
        cout<<seg.get(n-1)<<endl;
    }
}

