	it++;
      }else {
	DLOG("remove", it->first, it->second);
	it = theS.erase(it);
      }
    }
    if (!xshort) {
      DLOG("emplace last", R.at(j), d+C.at(j));
      theS.emplace(R.at(j), d + C.at(j));
    }
  }
