vi64 dijkstra(vector<vector<pair<int, int>>> &g) {
  pqasc<pair<i64, int>> q;
  vi64 dist(g.size(), (i64) 1e18);
  q.emplace(0, 0);
  dist[0] = 0;
  while (q.size()) {
    i64 c; int u;
    tie(c, u) = q.top(), q.pop();
    if (dist[u] < c) continue;
    for (auto p : g[u]) {
      int v, cost;
      tie(v, cost) = p;
      if (dist[v] <= c + cost) continue;
      q.emplace(c + cost, v);
      dist[v] = c + cost;
    }    
  }
  return dist;
}

void solve() {
  int N, M;
  cin >> N >> M;
  vector<vector<pair<int, int>>> g(N);
  rep(i, N - 1) {
    g[i + 1].emplace_back(i, 0);
  }
  rep(i, M) {
    int l, r, c;
    cin >> l >> r >> c;
    l--, r--;
    g[l].emplace_back(r, c);
  }
  auto dist = dijkstra(g);
  i64 ans = dist[N - 1];
  if (ans == (i64) 1e18) ans = -1;
  cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
const int maxn = 1e5 + 10;
typedef long long ll;
const ll INF = 1e16;
struct P {
	int l, r, c;
	bool operator < (const P& b) const {
		if(l != b.l) return l < b.l;
		if(r != b.r) return r < b.r;
		return c < b.c;
	}
} p[maxn];
int n, m;
ll seg[maxn << 2], tg[maxn << 2];
ll dp[maxn];
void push_down(int o) {
	if(tg[o] == -1) return;
	seg[o << 1] = seg[o << 1 | 1] = tg[o];
	tg[o << 1] = tg[o << 1 | 1] = tg[o];
	tg[o] = -1;
}
void push_up(int o) {seg[o] = min(seg[o << 1], seg[o << 1 | 1]);}
void build(int l = 1, int r = n, int o = 1) {
	tg[o] = -1;
	if(l == r) {seg[o] = INF; return;}
	int m = (l + r) >> 1;
	build(l, m, o << 1), build(m + 1, r, o << 1 | 1);
	push_up(o);
}
void update(int ql, int qr, ll k, int l = 1, int r = n, int o = 1) {
	if(ql <= l && r <= qr) {
		seg[o] = tg[o] = k;
		return;
	}
	push_down(o);
	int m = (l + r) >> 1;
	if(ql <= m) update(ql, qr, k, l, m, o << 1);
	if(qr > m) update(ql, qr, k, m + 1, r, o << 1 | 1);
	push_up(o);
}
ll query(int ql, int qr, int l = 1, int r = n, int o = 1) {
	if(ql <= l && r <= qr) return seg[o];
	push_down(o);
	int m = (l + r) >> 1;
	if(qr <= m) return query(ql, qr, l, m, o << 1);
	if(ql > m) return query(ql, qr, m + 1, r, o << 1 | 1);
	return min(query(ql, qr, l, m, o << 1), query(ql, qr, m + 1, r, o << 1 | 1));
}
int main() {
	scanf("%d%d", &n, &m);
	for(int i = 0; i < m; i++) scanf("%d%d%d", &p[i].l, &p[i].r, &p[i].c);
	sort(p, p + m);
	if(p[0].l != 1) return puts("-1"), 0;
	int cur = 1;
	build();
	update(1, 1, 0);
	for(int i = 0; i < m; i++) { 
		ll x = query(p[i].l, p[i].r);
		if(x == INF) return puts("-1"), 0;
		ll now = query(p[i].r, p[i].r);
		if(now > x + p[i].c) update(p[i].r, p[i].r, x + p[i].c);
		if(cur < p[i].r)	
			cur = p[i].r; 
	}
	ll ans = query(n, n);
	if(ans == INF) puts("-1");
	else printf("%lld\n", ans);
	return 0;
}

