class LazySegTree {
 public:
  const ll def_val_ = INF;
  vl val_, lazy_;
  ll n_;

  ll comp(ll l, ll r) { return min(l, r); }

  ll getr(ll x, ll y, ll k, ll l, ll r) {
    if (y <= l || r <= x) return def_val_;

    // lazy evaluation
    eval(k, l, r);

    if (x <= l && r <= y) return val_[k];
    auto vl = getr(x, y, 2 * k + 1, l, (l + r) / 2);
    auto vr = getr(x, y, 2 * k + 2, (l + r) / 2, r);
    return comp(vl, vr);
  }

  void eval(ll k, ll l, ll r) {
    if (lazy_[k] != def_val_) {
      // val_[k] += lazy_[k];
      val_[k] = min(val_[k], lazy_[k]);
      if (r - l > 1) {
        // has children
        lazy_[2 * k + 1] = min(lazy_[2 * k + 1], lazy_[k]);
        lazy_[2 * k + 2] = min(lazy_[2 * k + 1], lazy_[k]);
      }
      lazy_[k] = def_val_;
    }
  }

  void add(ll x, ll y, ll v, ll k, ll l, ll r) {
    eval(k, l, r);
    if (y <= l || r <= x) return;
    if (x <= l && r <= y) {
      lazy_[k] = min(lazy_[k], v);
      eval(k, l, r);
    } else {
      add(x, y, v, 2 * k + 1, l, (l + r) / 2);
      add(x, y, v, 2 * k + 2, (l + r) / 2, r);
      val_[k] = comp(val_[2 * k + 1], val_[2 * k + 2]);
    }
  }

 public:
  LazySegTree(ll size) {
    n_ = 1;
    while (n_ < size) n_ *= 2;
    val_ = vl(2 * n_, def_val_);
    lazy_ = vl(2 * n_, def_val_);
  }

  void update(ll i, ll v) {
    i += (n_ - 1);
    val_[i] = v;
    while (i > 0) {
      i = (i - 1) / 2;
      val_[i] = comp(val_[2 * i + 1], val_[2 * i + 2]);
    }
  }

  void addRange(ll x, ll y, ll v) { add(x, y, v, 0, 0, n_); }

  // get XXX value between [x,y)
  ll getRange(ll x, ll y) { return getr(x, y, 0, 0, n_); }
};

