using namespace std;
class SegTree {
    using T = long long;
    static const T& op(const T& lhs, const T& rhs) { // binary operator
        return min(lhs, rhs);
    }
    constexpr static T unit = 1LL<<60; // unit element
    const int N;
    T *data;
    static int calc_size(int sz) {
        int n = 1;
        while (sz > n) n *= 2;
        return n;
    }
public:
    explicit SegTree(int sz) : N(calc_size(sz)) {
        data = new T[2*N-1];
        fill(data, data+2*N-1, unit);
    }
    ~SegTree() { delete[] data; }
    T query(int a, int b, int i = -1, int l = -1, int r = -1) const {
        if (i == -1) { i = 0; l = 0; r = N; }
        if (r <= a || b <= l) return unit; // need this if a query can be empty
        if (a <= l && r <= b) return data[i];
        int m = (l+r)/2;
        if (b <= m) return query(a, b, 2*i+1, l, m);
        if (m <= a) return query(a, b, 2*i+2, m, r);
        T v1 = query(a, b, 2*i+1, l, m),
          v2 = query(a, b, 2*i+2, m, r);
        return op(v1, v2);
    }
    T get(int i) const {
        return data[i + N - 1];
    }
    void update(int i, T v) {
        int x = i + N - 1;
        data[x] = v;
        while (x > 0) {
            x = (x-1)/2;
            data[x] = op(data[2*x+1], data[2*x+2]);
        }
    }
};

int main() {
    int n, m; cin >> n >> m;
    vector<int> L[n], C[n];
    for (int i = 0; i < m; i++) {
        int l, r, c; cin >> l >> r >> c;
        l--; r--;
        L[r].push_back(l);
        C[r].push_back(c);
    }
    const long long INF = 1LL<<60;
    SegTree dist(n);
    dist.update(0, 0);
    for (int x = 1; x < n; x++) {
        long long temp = INF;
        for (int i = 0; i < L[x].size(); i++)
            temp = min(temp, C[x][i] + dist.query(L[x][i], x));
        dist.update(x, temp);
    }
    long long ans = dist.get(n-1);
    cout << (ans == INF ? -1 : ans) << endl;
}

