namespace seg1
{
    const int maxnode=maxn<<2;
    ll tag[maxnode];
    int rest[maxnode];
    pll mn[maxnode];
    void change(int u,ll d)
    {
        if(rest[u]==-1) return;
        if(tag[u]==-1||tag[u]>d) tag[u]=d;
        if(mn[u].fi>d) mn[u]=make_pair(d,rest[u]);
    }
    inline void pushdown(int u)
    {
        if(tag[u]!=-1)
        {
            change(u<<1,tag[u]);
            change(u<<1|1,tag[u]);
            tag[u]=-1;
        }
    }
    inline void pushup(int u)
    {
        mn[u]=min(mn[u<<1],mn[u<<1|1]);
        rest[u]=-1;
        if(rest[u<<1]!=-1) rest[u]=rest[u<<1];
        if(rest[u<<1|1]!=-1) rest[u]=rest[u<<1|1];
    }
    void build(int u,int l,int r)
    {
        tag[u]=-1;
        if(l==r)
        {
            mn[u]=make_pair(l==1?0:inf,l);
            rest[u]=l;
            return;
        }
        int mid=(l+r)>>1;
        build(lson);
        build(rson);
        pushup(u);
    }
    void remove(int u,int l,int r,int qp)
    {
        if(l==r)
        {
            mn[u]=make_pair(inf,inf);
            rest[u]=-1;
            return;
        }
        int mid=(l+r)>>1;
        pushdown(u);
        if(qp<=mid) remove(lson,qp);
        else remove(rson,qp);
        pushup(u);
    }
    void update(int u,int l,int r,int ql,int qr,ll qv)
    {
        if(l==ql&&r==qr)
        {
            change(u,qv);
            return;
        }
        int mid=(l+r)>>1;
        pushdown(u);
        if(qr<=mid) update(lson,ql,qr,qv);
        else if(ql>mid) update(rson,ql,qr,qv);
        else
        {
            update(lson,ql,mid,qv);
            update(rson,mid+1,qr,qv);
        }
        pushup(u);
    }
}
