void solve(long long n, long long m, std::vector<long long> L,
           std::vector<long long> R, std::vector<long long> C) {
  lli inf = 1e18;
  vector<vector<pair<lli, lli>>> ma(n+10);
  vector<vector<pair<lli, lli>>> ena(n+10);

  using p = pair<lli, lli>;
  // cost, right check right
  vector<lli> dist(n + 10, inf);

  dist[0] = 0;
  priority_queue<p, vector<p>, greater<p>> que;
  rep(i, m) ma[L[i]].push_back(make_pair(C[i], i));
  lli frontier = 0;
  for(auto s:ma[0]){
       que.push(s);
  }

  rep(i, n){
    for(auto s:ma[i]){
       que.push(s);
    }
    while(!que.empty()){
      auto s = que.top();
      que.pop();
      if(R[s.second] > i){
        que.push(s);
        break;
      }
    }

    if(que.empty()) continue;
    auto f = que.top();
    lli right = R[f.second];
