#define pil    pair<ll, ll>
#define vec    vector<pil>
#define pb     push_back
#define mp     make_pair
vector<pil>                             V[maxn];
priority_queue<pil, vec, greater<pil> > q;
void init()
{
    for (int i = 2; i <= n; i++)
        V[i].pb(mp(i - 1, 0));
}
void solve()
{
    dis[1] = 0;
    for (int i = 2; i <= n; i++)
        dis[i] = INF;
    q.push(mp(dis[1], 1));
    while (!q.empty())
    {
        pil p = q.top(); q.pop();
        ll  x = p.second; if (vis[x])
