        G[i][0]--,G[i][1]--;
    }
    sort(G.begin(),G.end());
    vector<ll> ans(N,IINF);
    ans[0]=0;
    SegmentTree<ll,ll> seg(N,[](ll a,ll b){return min(a,b);},
                            [](ll a,ll b){return min(a,b);},IINF);
    seg.build(N,ans);
    rep(i,M){
        ll a=G[i][0],b=G[i][1];
        ll c=seg.query(a,N);
        if (c==IINF){
            cout << -1 << endl;
            return 0;
        }
        seg.update(b,c+G[i][2]);
    }
    if (seg.query(N-1,N)==IINF) cout << -1 << endl;
    else cout << seg.query(N-1,N) << endl;
}

