struct Node{
    int to;
    ll cost;
};

int n, m;
ll d[100001];

void dijkstra(vector<vector<Node>> G){
    // (cost, point)
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> que;
    fill(d, d+n, INF);
    d[0] = 0;
    que.push(make_pair(0, 0));
    while(!que.empty()){
        pair<int, int> f = que.top(); que.pop();

        int cur = f.second;

        // 最小値ではないため、見送り
        if(d[cur] < f.first) continue;
        rep(i, G[cur].size()){
            int next = G[cur][i].to;
            ll cost = G[cur][i].cost;
            if(d[next] > d[cur] + cost){
                d[next] = d[cur] + cost;
                que.push(make_pair(d[next], next));
            }
        }
    }
}

int main() {
    cin >> n >> m;
    vector<vector<Node>> G(n);
    // lからrにコストcの辺を追加
    rep(i, m){
        int l, r;
        ll c;
        cin >> l >> r >> c;
        l--, r--;
        G[l].emplace_back(Node{r, c});
    }
    // 逆向きの有効辺を追加
    rep(i, n-1) G[i+1].emplace_back(Node{i, 0});

    dijkstra(G);
    ll ans = (d[n-1]==INF) ? -1 : d[n-1];
    cout << ans << endl;
    return 0;
}

