const int N = 1e5 + 233;
int n , m;
vector < pii > ln[N];
ll dp[N] , t[N << 2];
void upd(int v, int tl , int tr , int pos){
	if(tl == tr)
		return void(t[v] = dp[pos]);
	int tm = (tl + tr) >> 1;
	if(pos <= tm)
		upd(v << 1, tl , tm , pos);
	else upd(v << 1|1, tm + 1, tr, pos);
	t[v] = min(t[v << 1] , t[v << 1|1]);	
}
int get(int v, int tl, int tr , int l , int r){
	if(l > r or l > tr or tl > r)
		return 1e15;
	if(l <= tl and tr <= r)
		return t[v];
	int tm = (tl + tr) >> 1;
	return min(get(v << 1 , tl , tm , l, r), get(v << 1|1, tm + 1 ,tr , l , r));
}
main(){
	scanf("%lld%lld" , &n , &m);
	for(int i = 1;  i <= n; i++){
		int l, r ,c;
		scanf("%lld%lld%lld" , &l , &r , &c);
		ln[r].pb({l , c});		
	}
	for(int i = 2; i <= n; i++)
		dp[i] = 1e15, upd(1 , 1 , n , i);

	upd(1 , 1 , n , 1);

	for(int i = 2 ; i <= n ; i++){
		int cur = 1e15;
		for(auto x : ln[i]){
			int tmp = get(1 , 1,  n , x.fi , i) + x.se;
			cur = min(cur , tmp);
		}
		dp[i] = cur;
		upd(1 , 1,  n, i);	
	}
	if(dp[n] >= 1e15)
		dp[n] = -1;
	ret(dp[n]);
}

