const int MAXN = 2e5 + 5;

template<typename temp_type> struct segment_tree {
	// Elements count
	int n;

	// Values
	ll vals[MAXN];

	// Tree
	temp_type tt[4 * MAXN];

	// Combine from two values
	temp_type combine(temp_type v1, temp_type v2){
		return min(v1, v2);
	}

	// Recursive build
	void build(int ind, int tl, int tr){
		if (tl == tr){
			tt[ind] = vals[tl];
			return;
		}
		int tm = (tl + tr) >> 1;
		build(ind << 1, tl, tm);
		build((ind << 1) + 1, tm + 1, tr);
		tt[ind] = combine(tt[ind << 1], tt[(ind << 1) + 1]);
	}	

	// Recursive get
	temp_type get_val(int ind, int tl, int tr, int l, int r){
		if (tl == l && tr == r){
			return tt[ind];
		}
		int tm = (tl + tr) >> 1;
		if (r <= tm){
			return get_val(ind << 1, tl, tm, l, r);
		} else if (l > tm){
			return get_val((ind << 1) + 1, tm + 1, tr, l, r);
		} else {
			return combine(get_val(ind << 1, tl, tm, l, tm), get_val((ind << 1) + 1, tm + 1, tr, tm + 1, r));
		}
	}	

	// Recursive update (set value)
	void upd_val(int ind, int tl, int tr, int pos, temp_type new_val){
		if (tl == tr){
			if (new_val < tt[ind]) {
				tt[ind] = new_val;
			}
			return;
		}
		int tm = (tl + tr) >> 1;
		if (pos <= tm){
			upd_val(ind << 1, tl, tm, pos, new_val);
		} else {
			upd_val((ind << 1) + 1, tm + 1, tr, pos, new_val);
		}
		tt[ind] = combine(tt[ind << 1], tt[(ind << 1) + 1]);
	}

	// Build (for call)
	void build(){
		build(1, 0, n - 1);
	}

	// Get (for call)
	temp_type get_val(int l, int r){
		return get_val(1, 0, n - 1, l, r);
	}

	// Recursive update (for call)
	void upd_val(int pos, temp_type new_val){
		upd_val(1, 0, n - 1, pos, new_val);
	}
};

segment_tree<ll> tt;
vector<pii> nxt[MAXN];

void solve(){
	int n, m;
	scanf("%d%d", &n, &m);
	REP(i, 0, m) {
		int l, r, c;
		scanf("%d%d%d", &l, &r, &c);
		l--, r--;
		nxt[l].pb(mp(r, c));
	}

	tt.n = n;
	REP(i, 1, n) {
		tt.vals[i] = LL_INF;
	}
	tt.build();

	REP(cur, 0, n - 1) {
		ll cur_val = tt.get_val(cur, cur);
		ll right_val = tt.get_val(cur + 1, n - 1);
		if (right_val < cur_val) {
			cur_val = right_val;
		}
		REP(i, 0, SZ(nxt[cur])) {
			tt.upd_val(nxt[cur][i]._1, cur_val + nxt[cur][i]._2);
		}
	}
	ll ans = tt.get_val(n - 1, n - 1);
	if (ans >= LL_INF) {
		ans = -1;
	}
	cout << ans << endl;
}   

