const int K = 19;
const int KM = 1 << (K - 1);
ll dat[1 << K];
ll laz[1 << K];
ll zero = 2e18;

void eval(int A, int l, int r) {
	if (laz[A] == zero) return;
	if (A * 2 < 1 << K) {
		laz[A * 2] = min(laz[A * 2], laz[A]);
		laz[A * 2 + 1] = min(laz[A * 2 + 1], laz[A]);
	}
	dat[A] = min(dat[A], laz[A]);
	laz[A] = zero;
}

ll update(int L, int R, ll X, int A, int l, int r) {
	eval(A, l, r);
	if (r <= L || R <= l) return dat[A];
	if (L <= l && r <= R) {
		laz[A] = min(laz[A], X);
		return min(dat[A], laz[A]);
	}
	dat[A] = min(update(L, R, X, A * 2, l, (l + r) / 2), update(L, R, X, A * 2 + 1, (l + r) / 2, r));
	return dat[A];
}

void add(int L, int R, ll X) {
	update(L, R, X, 1, 0, KM);
}

ll check(int L, int R, int A, int l, int r) {
	eval(A, l, r);
	if (r <= L || R <= l) return zero;
	if (L <= l && r <= R) return dat[A];
	return min(check(L, R, A * 2, l, (l + r) / 2), check(L, R, A * 2 + 1, (l + r) / 2, r));
}

ll query(int L, int R) {
	return check(L, R, 1, 0, KM);
}

