using namespace std;

typedef long long ll;
typedef pair <ll, ll> pii;
typedef pair <pii, ll> ppi;
#define L first.first
#define R first.second
#define C second

const ll MAX_N = 1e5 + 5, inf = 1000000LL * 1000000LL * 1000;
ll n, m;
ppi Arr[MAX_N];
ll dis[MAX_N];
ll seg[MAX_N << 4];

bool cmp (ppi a, ppi b) {
    return a.R < b.R;
}

void build (ll s = 0, ll e = n, ll id = 1) {
    if (e - s == 1) {
        seg[id] = dis[s];
        return ;
    }

    ll mid = e + s >> 1;
    build(s, mid, id << 1);
    build(mid, e, id << 1 | 1);
    seg[id] = min(seg[id << 1], seg[id << 1 | 1]);
}

ll get (ll l, ll r, ll s = 0, ll e = n, ll id = 1) {
    if (l <= s && e <= r)
        return seg[id];

    if (r <= s || e <= l)
        return inf;

    ll mid = e + s >> 1;
    return min(get(l, r, s, mid, id << 1), get(l, r, mid, e, id << 1 | 1));
}

void upd (ll val, ll tmp, ll s = 0, ll e = n, ll id = 1) {
    if (e - s == 1) {
        seg[id] = val;
        return ;
    }

    ll mid = e + s >> 1;
    if (tmp < mid)
        upd(val, tmp, s, mid, id << 1);
    else
        upd(val, tmp, mid, e, id << 1 | 1);

    seg[id] = min(seg[id << 1], seg[id << 1 | 1]);
}

int main() {
    ios::sync_with_stdio(false), cin.tie(0);
    cin >> n >> m;
    for (ll i = 0; i < m; i++) {
        cin >> Arr[i].L >> Arr[i].R >> Arr[i].C;
        Arr[i].L--, Arr[i].R--;
    }

    sort(Arr, Arr + m, cmp);

    for (ll i = 0; i < n; i++)
        dis[i] = inf;
    dis[0] = 0;
    build();

    for (ll i = 0; i < m; i++) {
        dis[Arr[i].R] = min(dis[Arr[i].R], Arr[i].C + get(Arr[i].L, Arr[i].R + 1));
        upd(dis[Arr[i].R], Arr[i].R);
    }

    cout << (dis[n - 1] == inf? -1: dis[n - 1]) << "\n";
    return 0;
}

