void AddEdge(int u,int v,long long w)
{
	//printf("%d %d %lld\n",u,v,w);
	edge[++cnt].u=u;edge[cnt].v=v;edge[cnt].w=w;
	edge[cnt].next=head[u];head[u]=cnt;
