typedef struct exGraph{
    int n=1, m;
    vector<int> f_id, t_id, q_id, f_v, t_v;

    exGraph(int n_, int m_) : n(n_), m(m_){
        while(n<n_) n*=2;
        f_id.resize(2*n-1);
        t_id.resize(2*n-1);
        q_id.resize(m);
        f_v.resize(n);
        t_v.resize(n);
        G.resize(4*n-2+m);

        int cur=0;
        rep(i, 2*n-1){
            f_id[i]=cur;
            if(i>=n-1) f_v[i-n+1]=cur;
            ++cur;
        }
        rep(i, 2*n-1){
            t_id[i]=cur;
            if(i>=n-1) t_v[i-n+1]=cur;
            ++cur;
        }
        rep(i, m) q_id[i]=cur++;
    }

    void add_edge(int from, int to, lint cost){
        G[from].emplace_back(from, to, cost);
    }

    void build(){
        For(i, 1, 2*n-1) add_edge(f_id[i], f_id[(i-1)/2], 0);
        rep(i, n-1){
            add_edge(t_id[i], t_id[i*2+1], 0);
            add_edge(t_id[i], t_id[i*2+2], 0);
        }
        rep(i, n) add_edge(t_id[i+n-1], f_id[i+n-1], 0);
    }

    void f_query(int a, int b, int t){
        for(a+=n-1, b+=n-1; a<b; a=(a-1)/2, b=(b-1)/2){
            if(!(a&1)) add_edge(f_id[a++], q_id[t], 0);
            if(!(b&1)) add_edge(f_id[--b], q_id[t], 0);
        }
    }

    void t_query(int a, int b, int t, lint c){
        for(a+=n-1, b+=n-1; a<b; a=(a-1)/2, b=(b-1)/2){
            if(!(a&1)) add_edge(q_id[t], t_id[a++], c);
            if(!(b&1)) add_edge(q_id[t], t_id[--b], c);
        }
    }

    vector<lint> dijkstra(int s){
        vector<lint> d(4*n-2+m, INF);
        priority_queue<pli, vector<pli>, greater<>> que;
        d[f_v[s]]=0;
        que.push(pli(0, f_v[s]));
        while(!que.empty()){
            pli p=que.top(); que.pop();
            lint td=p.fi;
            int v=p.se;
            if(d[v]<td) continue;
            for(edge &e: G[v])if(chmin(d[e.to], td+e.cost)){
                que.push(pli(d[e.to], e.to));
            }
        }
        return d;
    }
}exGraph;

int main(){
