// セグメント木を持つグローバル配列
int n;
ll dat[2 * MAX_N - 1];
const ll inf = 1234567812345678;
// 初期化
void init(int n_){
    // 簡単のため要素数を2のべき乗に
    n = 1;
    while(n < n_)n *= 2;

    // 全ての値をINT_MAXに
    for(int i = 0; i < 2 * n - 1; i++)dat[i] = inf;
}

// k番目の値(0-indexed)をaに変更
void update(int k, ll a){
    // 葉の接点
    k += n - 1;
    dat[k] = a;
    // 登りながら更新
    while(k > 0){
        k = (k - 1) / 2;
        dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
}

// [a,b)の最小値を求める
// 後ろのほうの引数は、計算の簡単のための引数。
// kは節点の番号、l, rはその節点が[l, r)に対応づいていることを表す。
// したがって、外からはquery(a, b, 0, 0, n)として呼ぶ。
ll query(int a, int b, int k, int l, int r){
    // [a, b)と[l, r)が交差しなければ、INT_MAX
    if (r <= a || b <= l)return inf;

    // [a, b)が[l, r)を完全に含んでいれば、この節点の値
    if (a <= l && r <= b)return dat[k];
    else {
        // そうでなければ、2つの子の最小値
        ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
}


int main(){
    int m;
    cin >> n >> m;
    int n_ = n;

    init(n);
    int now = 0;
    vector<pair<P,ll>> v;
    rep(i,m){
        int l,r;
        ll c;
        cin >> l >> r >> c;
        pair<P,ll> p;
        p.first.first = l;
        p.first.second = r;
        p.second = c;
        v.push_back(p);
    }
    sort(v.begin(), v.end());

    rep(i,m){
        int l = v[i].first.first;
        int r = v[i].first.second;
        ll c = v[i].second;
        l--; r--;
        if(l == 0){
            ll now = query(r,n,0,0,n);
            if(c < now){
                update(r,c);
            }
        }else{
            c = c + query(l,n,0,0,n);
            ll now = query(r,n,0,0,n);
            if(c < now){
                update(r,c);
            }
        }
    }
    ll ans = query(n_-1,n,0,0,n);
    if(ans>=inf)ans = -1;
    cout << ans << endl;
    return 0;
}

