struct Node {
  int l, r;
  ll v;
  Node *ls, *rs;

  void ch(int k, ll x) {
    if (l == r) {
      v = x;
      return;
    }
    (k <= ls->r ? ls : rs)->ch(k, x);
    v = min(v, x);
  }

  ll qry(int l, int r) {
    if (this->l == l && this->r == r) return v;
    if (r <= ls->r) return ls->qry(l, r);
    if (l >= rs->l) return rs->qry(l, r);
    return min(ls->qry(l, ls->r), rs->qry(rs->l, r));
  }
};

Node* build(int l, int r) {
  static Node pool[N * 2], *top = pool;
  Node *p = top++;
  p->l = l;
  p->r = r;
  p->v = INF;
  if (l == r) {
    return p;
  }
  int mid = (l + r) >> 1;
  p->ls = build(l, mid);
  p->rs = build(mid + 1, r);
  return p;
}

