		L[i]--; R[i]--;
		lv[i][0] = L[i];
		lv[i][1] = R[i];
		lv[i][2] = C[i];
	}
	dp[0] = 0;
	update(0, 0);
	sort(lv.begin(),lv.end());
	// rep(i, M) {
	// 	cout << lv[i][0] << " " << lv[i][1] << " " << lv[i][2] << endl;
	// }
	rep(i, M) {
		ll l = lv[i][0], r = lv[i][1], c = lv[i][2];
		// cout << lv[i][0] << " " << lv[i][1] << " " << lv[i][2] << endl;

		dp[r] = min(dp[r], query(l, r+1, 0, 0, n)+c);
		update(r, dp[r]);

		// rep(j, N+1) if (dp[j] >= INT_MAX/4) cout << "i"; else cout << dp[j];
		// cout << endl;
	}

	if (dp[N-1] >= INT_MAX ) printf("-1\n"); else printf("%d\n",dp[N-1]);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
const int maxn = 1e5 + 5;
struct Node {
    int left;
    int right;
    int w;
    Node() {}
    Node(int left, int right, int w)
        : left(left)
        , right(right)
        , w(w)
    {
    }
    friend bool operator<(const Node& a, const Node& b)
    {
        if (a.left == b.left)
            return a.right < b.right;
        return a.left < b.left;
    }
} node[maxn];
namespace Segment {
const LL inf = 0X3f3f3f3f3f3f3f3f;
LL tree[maxn << 2], lazy[maxn << 2];
void build()
{
    memset(tree, 0X3f, sizeof(tree));
    memset(lazy, 0X3f, sizeof(lazy));
}
void pushdown(int root, int left, int right)
{
    if (lazy[root] == inf)
        return;
    tree[root << 1] = min(tree[root << 1], lazy[root]);
    tree[root << 1 | 1] = min(tree[root << 1 | 1], lazy[root]);
    lazy[root << 1] = min(lazy[root << 1], lazy[root]);
    lazy[root << 1 | 1] = min(lazy[root << 1 | 1], lazy[root]);
    lazy[root] = inf;
}
void update(int root, int left, int right, int stdl, int stdr, LL x)
{
    if (left >= stdl && right <= stdr) {
        tree[root] = min(tree[root], x);
        lazy[root] = min(lazy[root], x);
        return;
    }
    pushdown(root, left, right);
    int mid = (left + right) >> 1;
    if (stdl <= mid)
        update(root << 1, left, mid, stdl, stdr, x);
    if (stdr > mid)
        update(root << 1 | 1, mid + 1, right, stdl, stdr, x);
    tree[root] = min(tree[root << 1], tree[root << 1 | 1]);
}
LL query(int root, int left, int right, int stdl, int stdr)
{
    if (left >= stdl && right <= stdr) {
        return tree[root];
    }
    pushdown(root, left, right);
    LL res = inf;
    int mid = (left + right) >> 1;
    if (stdl <= mid)
        res = min(res, query(root << 1, left, mid, stdl, stdr));
    if (stdr > mid)
        res = min(res, query(root << 1 | 1, mid + 1, right, stdl, stdr));
    return res;
}
}
int main()
{
    int n, m;
    scanf("%d%d", &n, &m);
    int u, v, w;
    for (int i = 1; i <= m; i++) {
        scanf("%d%d%d", &u, &v, &w);
        node[i] = Node(u, v, w);
    }
    sort(node + 1, node + 1 + m);
    // for (int i = 1; i <= m; i++) {
    //     cout << node[i].left << ' ' << node[i].right << ' ' << node[i].w << '\n';
    // }
    Segment::build();
    Segment::update(1, 1, n, 1, 1, 0);
    //cout << Segment::query(1, 1, n, 1, 1) << '\n';
    for (int i = 1; i <= m; i++) {
        Segment::update(1, 1, n, node[i].left, node[i].right,
            (Segment::query(1, 1, n, node[i].left, node[i].right) + node[i].w));
        // for (int j = 1; j <= n; j++)
        //     cout << Segment::query(1, 1, n, j, j) << ' ';
        // cout << '\n';
    }
    LL ans = Segment::query(1, 1, n, n, n);
    if (ans == Segment::inf)
        printf("-1\n");
    else
        printf("%lld\n", ans);
    return 0;
}

