using namespace std;

typedef long long ll;
typedef pair<int,int> Pair;

const ll inf = 1e18;
const int Nmax = 2e5 + 5;

ll dp[Nmax];
set<Pair> S1, S2;

priority_queue< pair<ll, int>, vector<pair<ll,int>>, greater<pair<ll,int>> > heap;

int L[Nmax], R[Nmax], C[Nmax];
int n, m;


void solve()
{
    int i;
    for(i=1; i<=m+1; ++i) S1.insert( {L[i], i} );
    for(i=1; i<=m+1; ++i) S2.insert( {R[i], i} );

    heap.push({ 0, 0 });

    for(i=1; i<=m+1; ++i) dp[i] = inf;

    while(heap.size())
    {
        int node = heap.top().second;
        heap.pop();

        ll dist = dp[node];

        ///
        set<Pair> :: iterator start, it;
        start = it = S1.lower_bound( { L[node], 0 } );


        while(it != S1.end() && it->first <= R[node])
        {
            int curr = it->second;
            if(dp[curr] == inf)
            {
                dp[curr] = dist + C[curr];
                heap.push( {dp[curr], curr} );
            }

            ++it;
        }

        S1.erase(start, it);

      //////
        start = it = S2.lower_bound( {L[node], 0} );
        while(it != S2.end() && it->first <= R[node])
        {
            int curr = it->second;
            if(dp[curr] == inf)
            {
                dp[curr] = dist + C[curr];
                heap.push( {dp[curr], curr} );
            }

            ++it;
        }

        S2.erase(start, it);
    }


    if(dp[m+1] == inf) cout << -1 << '\n';
        else cout << dp[m+1] << '\n';
}

