        l--; r--;
        fro[l].emplace_back(r,c);
        to[r].emplace_back(l,c);
    }

    const i64 inf=1e18;
    // Lazy_segment_tree<i64,i64> seg(n,inf,inf,minf<i64>,sbminf,sbminf);
