void build(int nod,int l,int r)
{
	if(l==r)
	{
		if(l!=1)st[nod]=llinf;
		else st[nod]=0;
		return;
	}
	int mid=(l+r)/2;
	build(2*nod,l,mid);
	build(2*nod+1,mid+1,r);
	st[nod]=min(st[2*nod],st[2*nod+1]);
}
void upd(int x,int l,int r,int p,ll v)
{
	if(l==r)
	{
		st[x]=min(st[x],v);
		return;
	}
	int mid=(l+r)/2;
	if(p<=mid)upd(2*x,l,mid,p,v);
	else upd(2*x+1,mid+1,r,p,v);
	st[x]=min(st[2*x],st[2*x+1]);
}
ll qry(int x,int l,int r,int tl,int tr)
{
	if(tl>r || l>tr)return llinf;
	if(tl<=l && r<=tr)return st[x];
	int mid=(l+r)/2;
	return min(qry(2*x,l,mid,tl,tr),qry(2*x+1,mid+1,r,tl,tr));
}
