    cin >> l[i] >> r[i] >> c[i];
    l[i]--, r[i]--;
    edge[i] = make_tuple(l[i], r[i], c[i]);
  }
  sort(edge.begin(),edge.end());

  vector<int> dp(n, INF);
  dp[0] = 0;
  SegmentTree<int> seg(dp,INF,[&](int x,int y){
    return min(x,y);
  });
  for(int i = 0; i < m; i++){
    auto e = edge[i];
