struct segmentTree{
    ll tree[400002], lazy[400002];

    void initialize(int i, int l, int r){
        if(l==r){
            if(l!=1) tree[i] = 1e18;
            return;
        }
        int m = (l+r)>>1;
        initialize(i*2, l, m);
        initialize(i*2+1, m+1, r);
    }

    void propagate(int i, int l, int r){
        if(!lazy[i]) return;
        if(l==r) tree[i] = min(tree[i], lazy[i]);
        else{
            lazy[i*2] = min(lazy[i*2]?lazy[i*2]:LLONG_MAX, lazy[i]);
            lazy[i*2+1] = min(lazy[i*2+1]?lazy[i*2+1]:LLONG_MAX, lazy[i]);
        }
        lazy[i] = 0;
    }

    ll getTree(int i, int l, int r, int x){
        propagate(i, l, r);
        if(l==r){
            return tree[i];
        }
        int m = (l+r)>>1;
        if(x<=m) return getTree(i*2, l, m, x);
        return getTree(i*2+1, m+1, r, x);
    }

    void setTree(int i, int l, int r, int s, int e, ll val){
        propagate(i, l, r);
        if(l==s && r==e){
            lazy[i] = val;
            propagate(i, l, r);
            return;
        }
        int m = (l+r)>>1;
        if(s<=m) setTree(i*2, l, m, s, min(m, e), val);
        if(m<e) setTree(i*2+1, m+1, r, max(m+1, s), e, val);
    }
} tree;

