const ll mod=1e9+7;
const ll INF=1e18;
const int maxn=1e5+5;
vector<pair<ll,ll>> seg(4*maxn,{INF,INF});
vl lazy(4*maxn,INF);
void build(int v,int tl,int tr){
    if(tl>tr) return;
    if(tl==tr){
        seg[v].se=tl;
        return;
    }
    int mid=(tl+tr)/2;
    build(2*v,tl,mid);
    build(2*v+1,mid+1,tr);
    seg[v]=min(seg[2*v],seg[2*v+1]);
}
void upd(int v,int tl,int tr,int pos,ll val){
    if(pos > tr or pos < tl) return;
    if(pos==tl and tl==tr) {seg[v].fi=val;seg[v].se=tl;return;}
    for(int x:{2*v,2*v+1}){
        seg[x].fi=min(seg[x].fi,lazy[v]);
        lazy[x]=min(lazy[x],lazy[v]);
    }
    lazy[v]=INF;
    int mid=(tl+tr)/2;
    upd(2*v,tl,mid,pos,val);
    upd(2*v+1,mid+1,tr,pos,val);
    seg[v]=min(seg[2*v],seg[2*v+1]);
}
void upd2(int v,int tl,int tr,int ql,int qr,ll val){
    if(tl > qr or tr < ql) return;
    if(tl>=ql and tr<=qr) {
        seg[v].fi=min(seg[v].fi,val);
        lazy[v]=min(lazy[v],val);
        return;
    }
    for(int x:{2*v,2*v+1}){
        seg[x].fi=min(seg[x].fi,lazy[v]);
        lazy[x]=min(lazy[x],lazy[v]);
    }
    lazy[v]=INF;
    int mid=(tl+tr)/2;
    upd2(2*v,tl,mid,ql,qr,val);
    upd2(2*v+1,mid+1,tr,ql,qr,val);
    seg[v]=min(seg[2*v],seg[2*v+1]);
}
pair<ll,ll> query(int v,int tl,int tr,int ql,int qr){
    if(tl>qr or tr < ql) return {INF,INF};
    if(tl>=ql and tr<=qr) return seg[v];
    for(int x:{2*v,2*v+1}){
        seg[x].fi=min(seg[x].fi,lazy[v]);
        lazy[x]=min(lazy[x],lazy[v]);
    }
    lazy[v]=INF;
    int mid=(tl+tr)/2;
    auto p1=query(2*v,tl,mid,ql,qr);
    auto p2=query(2*v+1,mid+1,tr,ql,qr);
    return min(p1,p2);
}
