    }
    dfs(v, L, R, k*2+1, l, (l+r)/2);
    dfs(v, L, R, k*2+2, (l+r)/2, r);
}

long long dijkstra(vector<vector<pair<int, long long>>> e, int s, int t){
    vector<long long> cost(e.size(), 1e18L);
    priority_queue<pair<long long, int>> pq;
    cost[s] = 0;
    pq.push({ 0,s });
    while(!pq.empty()){
        int n = pq.top().second;
        if(-pq.top().first != cost[n]){
            pq.pop();
            continue;
        }
        pq.pop();
        for(int i=0; i<e[n].size(); i++){
            if(cost[e[n][i].first] > cost[n] + e[n][i].second){
                cost[e[n][i].first] = cost[n] + e[n][i].second;
                pq.push({ -cost[e[n][i].first], e[n][i].first });
            }
        }
    }
    return cost[t];
}

