struct comp
{
	bool operator()(const PII &a, const PII &b) const
	{
		return a < b;
	}
};

int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(nullptr);
	int n, m;
	cin >> n >> m;
	vector<vector<PII>> g(n);
	for (int i = 0; i < m; ++i)
	{
		int l, r, c;
		cin >> l >> r >> c;
		--l, --r;
		g[l].EB(r, c);
		g[r].EB(l, c);
	}

	for (int i = 1; i < n; ++i)
	{
		g[i].EB(i - 1, 0);
	}
	vector<LL> dist(n, 1e18);
	dist[0] = 0;
	priority_queue<PII, vector<PII>, comp> que;
	que.emplace(dist[0], 0);
	while(!que.empty())
	{
		auto [d, v] = que.top();
		que.pop();
		if (d > dist[v])
		{
			continue;
		}
		for (auto [to, w] : g[v])
		{
			if (dist[to] > dist[v] + w)
			{
				dist[to] = dist[v] + w;
				que.push({dist[to], to});
			}
		}
	}

	if (dist[n - 1] > (LL)1e18 - 7)
	{
		cout << -1 << "\n";
	}
	else
	{
		cout << dist[n - 1] << "\n";
	}

	return 0;
}

