};

template <class Info>
class graph {
   protected:
    using edge_type = edge<Info>;
    ::std::size_t N;
    ::std::vector<::std::vector<edge_type>> edges;

   public:
    graph(::std::size_t N_) : N(N_), edges(N_) {}
    virtual void add_edge(int x, int y, Info info) = 0;
    const ::std::vector<edge_type> &delta(int v) const {
        assert(v < N);
        return edges[v];
    }
    const ::std::vector<edge_type> &operator[](int v) const {
        return this->delta(v);
    }
    ::std::size_t size() const { return N; }
};

template <class Info>
class undirected_graph : public graph<Info> {
   public:
    undirected_graph(::std::size_t N) : graph<Info>(N) {}
    void add_edge(int x, int y, Info info) {
        this->edges[x].push_back(edge<Info>(y, info));
        this->edges[y].push_back(edge<Info>(x, info));
    }
};

template <class Info>
class directed_graph : public graph<Info> {
   public:
    directed_graph(::std::size_t N) : graph<Info>(N) {}
    void add_edge(int x, int y, Info info) {
        this->edges[x].push_back(edge<Info>(y, info));
    }
};

template <class Info>
class bipartite_graph : public undirected_graph<Info> {
    ::std::size_t A;
    ::std::size_t B;

   public:
    bipartite_graph(::std::size_t A_, ::std::size_t B_)
        : A(A_), B(B_), undirected_graph<Info>(A_ + B_) {}
    void add_edge(int x, int y, Info info) {
        undirected_graph<Info>::add_edge(x, y + A, info);
    }
};

/* dijkstra (depends on Graph_template) */
template <typename T>
class RadixHeap64 {
   public:
    using key_type = std::uint_fast64_t;
    using value_type = std::pair<key_type, T>;
    using reference = value_type &;
    using const_reference = const value_type &;
    using size_type = std::uint_fast32_t;

   private:
    static size_type bsr(const key_type x) {
        if(!x) return 0;
#ifdef __GNUC__
        return 64 - __builtin_clzll(x);
#else
        size_type t = 32;
        for(size_type i = 4; ~i; --i) {
            if(x & ~(((key_type)1 << t) - 1))
                t += (size_type)1 << i;
            else
                t -= (size_type)1 << i;
        }
        if(x & ~(((key_type)1 << t) - 1)) ++t;
        return t;
#endif
    }
    std::vector<value_type> v[65];
    key_type last;
    size_type size_;

   public:
    RadixHeap64() : last(0), size_(0) {}
    value_type pop() {
        assert(size_);
        --size_;
        if(v[0].empty()) {
            size_type i = 1;
            while(v[i].empty()) ++i;
            last = std::numeric_limits<key_type>::max();
            for(const auto &d : v[i]) last = std::min(last, d.first);
            for(const auto &d : v[i]) v[bsr(last ^ d.first)].push_back(d);
            v[i].clear();
        }
        value_type ret = v[0].back();
        v[0].pop_back();
        return ret;
    }
    void push(const_reference x) {
        assert(last <= x.first);
        ++size_;
        v[bsr(x.first ^ last)].push_back(x);
    }
    bool empty() const { return !size_; }
    size_type size() const { return size_; }
};

template <typename T>
vector<T> dijkstra(graph<T> &g, int s) {
    const auto INF = numeric_limits<T>::max();
    vector<T> dist(g.size(), INF);
    vector<int> b(g.size(), -1);

    RadixHeap64<T> que;
    dist[s] = 0;
    que.push(pair<i64, T>(dist[s], s));
    while(!que.empty()) {
        T cost;
        int idx;
        tie(cost, idx) = que.pop();
        if(dist[idx] < cost) continue;
        for(auto &e : g[idx]) {
            auto next_cost = cost + e.info;
            if(dist[e.to] <= next_cost) continue;
            dist[e.to] = next_cost;
            b[e.to] = idx;
            que.push(pair<i64, T>(dist[e.to], e.to));
        }
    }
    return dist;
}

int main() {
    int N, M;
    cin >> N >> M;
    directed_graph<i64> G(N);
    for(int i = 0; i < N - 1; ++i) {
        G.add_edge(i + 1, i, 0);
    }
    REP(i, M) {
        int L, R, C;
        cin >> L >> R >> C;
        L--, R--;
        G.add_edge(L, R, C);
    }
    auto dist = dijkstra(G, 0);
    cout << (dist[N - 1] == numeric_limits<i64>::max() ? -1 : dist[N - 1])
         << endl;
    return 0;
}

