typedef vector<pair<pair<int,int>,int>> Graph;

struct Segtree{
  int data[2*SZ-1];

  Segtree(vector<int> v){
    int n = SZ;
    for(int i=0;i<2*n-1;i++) data[i] = INF;
    data[n-1] = 0;
    for(int i=n-2;i>=0;i--) data[i] = min(data[2*i+1],data[2*i+2]);
  }

  void change(int id, int val){
  	int i = id + SZ - 1;
    data[i] = val;
    i = i/2;
    while(1){
    	data[i] = min(data[2*i+1],data[2*i+2]);
      	if(i==0) break;
    	i = i/2;
    }
  }

  int find(int a, int b,int k=0, int l=0, int r=SZ){
  	if(a<=l && r<=b) return data[k];
    if(b <= l || r <= a) return INF;
    else {
    	return min(find(a, b, 2*k+1, l,(l+r)/2), find(a,b, 2*k+2, (l+r)/2, r));
    }
  }
};

