template <class M>
class SegmentTree {
public:
    using F = function<M(M, M)>;

    int n, lev;
    F f;
    M u1;
    vector<M> d;

    SegmentTree(int n_, F f, M u1) : f(f), u1(u1)
    {
        for (n = 1, lev = 0; n < n_; n <<= 1, ++lev);
        d.assign(n << 1, u1);
    }

    SegmentTree(const vector<M> &v, F f, M u1) : f(f), u1(u1)
    {
        int n_ = v.size();
        for (n = 1, lev = 0; n < n_; n <<= 1, ++lev);
        d.assign(n << 1, u1);
        for (int i = 0; i < n_; ++i) d[n + i] = v[i];
        for (int i = n - 1; i > 0; --i) d[i] = f(d[(i << 1) | 0], d[(i << 1) | 1]);
    }

    // k番目の要素をxに更新 (k: 0-indexed)
    void update(int k, M x)
    {
        d[k += n] = x;
        while (k >>= 1) d[k] = f(d[(k << 1) | 0], d[(k << 1) | 1]);
    }

    // 半開区間 [a, b) に対するクエリ (a, b: 0-indexed)
    M query(int a, int b)
    {
        M L = u1, R = u1;
		for (int l = a + n, r = b + n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) L = f(L, d[l++]);
            if (r & 1) R = f(d[--r], R);
		}
        return f(L, R);
    }
    M query(int a) { return query(a, a + 1); }

    void dump(int time= -1)
    {
        if (~time) cout << "time = " << time << endl;
        for (int i = 0; i <= lev; ++i) {
            int m = 1 << i;
            for (int j = 0; j < m; ++j) {
                cout << "  " << d[j + m];
            }
            cout << endl;
        }
        cout << endl;
    }
};
template <class M = int> using ST = SegmentTree<M>;

// Range Minimum Query (RmQ)
template <class M = int>
struct RmQ : SegmentTree<M> {
    RmQ(int n, M u1 = numeric_limits<M>::max()) : SegmentTree<M>(n, [&](M a, M b) { return min(a, b); }, u1) {}
    RmQ(const vector<M> &v, M u1 = numeric_limits<M>::max()) : SegmentTree<M>(v, [&](M a, M b) { return min(a, b); }, u1) {}
};

