	for (int i = 0; i < n; i++)	dist[i] = mod;
	set <pii> s;
	dist[0] = 0;
	s.insert({0, 0});
	while(!s.empty()) {
		int v = (*s.begin()).second;
		s.erase(s.begin());
		for (auto e : adj[v]) {
			int w = e.second, u = e.first;
			if(dist[u] > dist[v] + w) {
				dist[u] = dist[v] + w;
				s.insert({dist[u], u});
			}
		}
	}
}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
