		adj[i + 1].push_back({i, 0});
	}
	for (int i = 0; i < m; i++) {
		int v, u, w;
		cin >> v >> u >> w;
		v--, u--;
		adj[v].push_back({u, w});
		adj[u].push_back({v, w});
	}
	dij();
	if(dist[n - 1] == mod)	cout << -1 << "\n";
	else
		cout << dist[n - 1] << "\n";
}

