ll t[2 * pod];

void add(int l, int r, ll cost) {
	r += 1;
	for(l += pod, r += pod; l < r; l /= 2, r /= 2) {
		if(l & 1) {
			t[l] = min(t[l], cost);
			l += 1;
		}
		if(r & 1) {
			r -= 1;
			t[r] = min(t[r], cost);
		}
	}
}

ll query(int pos) {
	ll res = inf;
	pos += pod;
	while(pos) {
		res = min(res, t[pos]);
		pos /= 2;
	}
	return res;
}

