void operation(int st, int dr, int cost){
    int me = current_special_node++;
    for(st += maxn, dr += maxn + 1; st < dr; st /= 2, dr /= 2){
        if(st%2){
            add_edge(st, me, cost);
            add_edge(me, st + 2 * maxn, 0);
            ++st;
        }
        if(dr%2){
            --dr;
            add_edge(dr, me, cost);
            add_edge(me, dr + 2 * maxn, 0);
        }
    }
}

