template<class T, class E=T> struct LST{
    int n;T et; E ee;
    T f(T x,T y){return min(x,y);}
    T g(T x,T y){return min(x,y);}
    T h(T x,T y){return min(x,y);}
    T p(T x,int){return x;}
    int cur;
    vector<T> data;
    vector<E> lazy;
    vector<int> idx,len;

    LST(int n_,T et,E ee):n(1),et(et),ee(ee){
        while(n<n_) n<<=1;
        data.resize(n<<1, et);
        lazy.resize(n<<1, ee);
        idx.resize(128, -1);
        len.resize(n<<1, 1);
        for(int i=n-1;i;--i) len[i]=len[i<<1]<<1;
    }

    void build(vector<T>&v){
        for(int i=0;i<v.size();++i) data[i^n]=v[i];
        for(int i=n-1;i;--i) data[i]=f(data[i<<1],data[(i<<1)^1]);
    }

    inline void getidx(int a,int b){
        cur=0;
        if(a==n&&b==(n<<1)) return;
        while(1^a&1) a>>=1;
        while(1^b&1) b>>=1;
        a>>=1;
        b>>=1;
        while(a>1||b>1){
            if(a>=b){
                idx[cur++]=a;
                a>>=1;
            }
            else{
                idx[cur++]=b;
                b>>=1;
            }
        }
        idx[cur++]=1;
    }

    inline void eval(){
        int i;
        for(int k=cur-1;k>=0;--k){
            i=idx[k];
            if(lazy[i]==ee) continue;
            lazy[i<<1] = h(lazy[i<<1], lazy[i]);
            data[i<<1] = g(data[i<<1], p(lazy[i<<1], len[i<<1]));
            lazy[(i<<1)^1] = h(lazy[(i<<1)^1], lazy[i]);
            data[(i<<1)^1] = g(data[(i<<1)^1], p(lazy[(i<<1)^1], len[(i<<1)^1]));
            lazy[i] = ee;
        }
    }

    void ud(int a,int b,const E x){
        a+=n;b+=n;
        getidx(a, b);
        eval();
        for(;a<b;a>>=1,b>>=1){
            if(a&1){
                lazy[a]=h(lazy[a],x);
                data[a]=g(data[a],p(lazy[a],len[a]));
                ++a;
            }
            if(b&1){
                --b;
                lazy[b]=h(lazy[b],x);
                data[b]=g(data[b],p(lazy[b],len[b]));
            }
        }
        int i;
        for(int k=0;k<cur;++k){
            i=idx[k];
            data[i]=f(data[i<<1],data[(i<<1)^1]);
        }
    }

    T gt(int a, int b){
        a+=n;b+=n;
        getidx(a,b);
        eval();
        T vl=et,vr=et;
        for(;a<b;a>>=1,b>>=1){
            if(a&1) vl=f(vl,data[a++]);
            if(b&1) vr=f(data[--b],vr);
        }
        return f(vl,vr);
    }
};

