vector<ll> dijkstra(vector<vector<edge>> &g, int start, int n) {
  priority_queue<P, vector<P>, greater<P>> que;
  vector<ll> dist(n, INF);
  dist[start] = 0;
  que.push(P(0, start));
  while (!que.empty()) {
    P p = que.top();
    que.pop();
    int v = p.second;
