struct SegTree {
    int val, l, r;
    SegTree *lc, *rc;
    SegTree(int _l, int _r): l(_l), r(_r) {
        val = INF;
        if (r-l == 1);
        else {
            int mid = (l+r)>>1;
            lc = new SegTree(l, mid);
            rc = new SegTree(mid, r);
        }
    }
    void update(int x, int nw) {
        if (x < l || r <= x) return;
        val = min(val, nw);
        if (r-l == 1) return;
        int mid = (l+r)>>1;
        if (x < mid) lc->update(x, nw);
        else rc->update(x, nw);
    }
    int query(int ql, int qr) {
        if (qr < l || r <= ql) return INF;
        if (ql == l && qr == r) return val;
        int mid = (l+r)>>1;
        if (qr <= mid) return lc->query(ql, qr);
        if (mid <= ql) return rc->query(ql, qr);
        return min(lc->query(ql, mid), rc->query(mid, qr));
    }
};
struct Oper {
    int l, r, c;
};

signed main() {
    FAST
    srand(time(NULL));

    int n, m;
    cin >> n >> m;
    vector<Oper> v(m);
    Fr(i, 0, m) cin >> v[i].l >> v[i].r >> v[i].c;
    Fr(i, 0, m) v[i].l--, v[i].r--;
    sort(Iter(v), [](const Oper &a, const Oper &b) {
        return a.l < b.l;
    });
    SegTree *root = new SegTree(0, n);
    root->update(0, 0);
    int x;
    Fr(i, 0, m) {
        x = root->query(v[i].l, v[i].r);
      	if (x != INF)
        	root->update(v[i].r, x+v[i].c);
    }
    x = root->query(n-1, n);
    if (x == INF) x = -1;
    cout << x << endl;

    return 0;
}

