  seg.init(n);
  seg.update(0, 0);
  REP(i, m){
    ll l = lrc[i].FI.FI;
    ll r = lrc[i].FI.SE;
    ll c = lrc[i].SE;

    ll k = seg.query(l, r+1);
    seg.update(r, min(k+c, seg.at(r)));
  }

  ll ans = seg.at(n-1);
  if(ans == LLINF)
    cout << -1 << endl;
  else
    cout << ans << endl;

}

