	while ( q.size () ) {
		k = q.front(); q.pop();
		//printf ( "%lld %lld\n" , k , dis[k] );
		f[k] = 0;
		for ( node *j = g[k] ; j ; j = j -> next ) {
			if ( dis[j->v] > dis[k] + j -> c ) {
				dis[j->v] = dis[k] + j -> c;
				if ( !f[j->v] ) q.push ( j -> v );
				f[j->v] = 1; 
			}
		}
	}
}
