ll dist[100010];
const ll INF = 1e18;

int main ()
{
    cin >> N >> M;
    for (int i = 1; i < N; i++) {
        G[i + 1].push_back(Edge(i, 0));
    }
    REP(i,M) {
        ll L,R,C;
        cin >> L >> R >> C;
        G[L].push_back(Edge(R, C));
    }

    fill(dist, dist + 100010, INF);
    reversed_priority_queue<tuple<ll,ll>> que;
    que.push(make_tuple(0, 1));

    while(!que.empty()) {
        ll dt,idx;
        tie(dt,idx) = que.top();
        que.pop();
        if (dist[idx] < dt) {
            continue;
        }
        REP(i,G[idx].size()) {
            ll ndt = dt + G[idx][i].cost;
