struct RangeGraph{
  vector<vector<edge>>g;
  ll n,sz;
  ll cnt;
  RangeGraph(ll n,ll m):n(n){
    sz=1;
    cnt=0;
    while(sz<n)sz <<= 1;
    g.assign(3*sz+m,vector<edge>());
    for(ll i=1;i<sz;i++){
      g[i].EB(2*i,0);
      g[i].EB(2*i+1,0);
      if(2*i<sz){
        g[2*i+2*sz].EB(i+2*sz,0);
        g[2*i+1+2*sz].EB(i+2*sz,0);
      }
      else{
        g[2*i].EB(i+2*sz,0);
        g[2*i+1].EB(i+2*sz,0);
      }
    }
  }
  void add_edge(ll l1,ll r1,ll l2,ll r2,ll w){//[l1,r1)->[l2,r2)
    auto v=range(l1,r1);
    ll via=3*sz+cnt;
    for(auto z:v){
      if(z<sz)g[z+2*sz].EB(via,w);
      else g[z].EB(via,w);
    }
    v=range(l2,r2);
    for(auto z:v)g[via].EB(z,0);
    cnt++;
  }
  vector<ll>range(ll l,ll r){
    vector<ll>ret;
    l+=sz,r+=sz;
    while(l!=r){
      if(l&1)ret.PB(l++);
      if(r&1)ret.PB(--r);
      l>>=1,r>>=1;
    }
    return ret;
  };
  ll add(){
    return sz;
  }
};
