void upd (int cloc, ll x)
{
    cloc += P;
    while (cloc)
    {
        seg[cloc] = min (seg[cloc], x);
        cloc /= 2;
    }
}

ll ghi (int cloc)
{
    cloc += P;
    cloc++;
    ll res = 1e18;
    while (cloc > 1)
    {
        if (cloc & 1)
            res = min (res, seg[cloc-1]);
        cloc /= 2;
    }
    return res;
}

