using i64 = std::int64_t;

struct Edge {
	int l, r;
	i64 c;

	bool operator < (const Edge& e) const {
		return l < e.l;
	}
};

struct State {
	int pos;
	i64 costs;
	int hasUsed;

	bool operator < (const State& s) const {
		// greater
		return costs > s.costs;
	}
};

int main() {
	int n, m;
	std::cin >> n >> m;

	std::vector<Edge> edges(m);
	for (auto&& e : edges)
		std::cin >> e.l >> e.r >> e.c;

	std::sort(edges.begin(), edges.end());

	std::vector<bool> hasVisited(n + 1);
	std::priority_queue<State> pq;
	pq.push({ 1, 0ll, 0 });
	while (!pq.empty()) {
		const auto cur = pq.top();
		pq.pop();

		if (cur.pos == n) {
			std::cout << cur.costs << std::endl;
			return 0;
		}

		if (hasVisited[cur.pos])
			continue;

		hasVisited[cur.pos] = true;

		auto upper = static_cast<int>(std::upper_bound(edges.begin(), edges.end(), Edge{cur.pos, 0, 0ll}) - edges.begin());

		for (int i = cur.hasUsed; i < upper; ++i) {
			auto& e = edges[i];

			if (!hasVisited[e.r])
				pq.push({e.r, cur.costs + e.c, upper});
		}
	}

	std::cout << -1 << std::endl;
}

