const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}


//不可逆区間変更、区間最小
const ll N_ = 1<<18;
ll seg[2 * N_ - 1], lazy[2 * N_ - 1];

void init_seg(ll x = INFL){
  rep(i, 2 * N_ - 1){
    seg[i] = x;
    lazy[i] = x;
  }
}

void eval(ll k, ll l, ll r){
  chmin(seg[k], lazy[k]);
  if(r - l > 1){
    chmin(lazy[2 * k + 1], lazy[k]);
    chmin(lazy[2 * k + 2], lazy[k]);
  }
}

void update(ll a, ll b, ll x, ll k = 0, ll l = 0, ll r = N_){
  eval(k, l, r);
  if(r <= a || b <= l) return;
  if(a <= l && r <= b){
    chmin(lazy[k], x);
    eval(k, l, r);
    return;
  }
  update(a, b, x, 2 * k + 1, l, (l + r) / 2);
  update(a, b, x, 2 * k + 2, (l + r) / 2, r);
  seg[k] = min(seg[2 * k + 1], seg[2 * k + 2]);
  return;
}

ll getminimum(ll a, ll b, ll k = 0, ll l = 0, ll r = N_){
  if(r <= a || b <= l) return INFL;
  eval(k, l, r);
  if(a <= l && r <= b) return seg[k];
  ll res = INFL;
  res = min(res, getminimum(a, b, 2 * k + 1, l, (l + r) / 2));
  res = min(res, getminimum(a, b, 2 * k + 2, (l + r) / 2, r));
  return res;
}


