inline void add(int from,int to,ll dis){
    edge[++tot].next = head[from];
    edge[tot].to = to;
    edge[tot].dis = dis;
    head[from] = tot;
}
struct node
{
    ll val;int id;
    node(){}
    node(int a,ll b):id(a),val(b){}
    bool operator <(node A)const{
        return val > A.val;
    }
};
void dij(int u)
{
    mmt(vis,0);
    d[u] = 0;
    priority_queue<node> Q;
    Q.push({u,0});
    node tmp;
    while(Q.size()){
        tmp = Q.top();
        Q.pop();
        int x = tmp.id;
        if(vis[x]) continue;
        for(int i =  head[x];~i;i = edge[i].next){
            int y = edge[i].to;
            ll dis = edge[i].dis;
            if(d[y] > d[x] +dis){
                d[y] = d[x] + dis;
                Q.push({y,d[y]});
            }
        }
    }
}
inline void init(int n)
{
    mmt(head,-1);
    tot = 0;
    for(int i = 1;i <= n;++i) d[i] = INF;
}
