constexpr int MOD = 1000000007;
int main()
{
    int N, M;
    cin >> N >> M;
    vector<tuple<int, int, lint>> pair(M);
    REP(i, M) {
        int L, R;
        lint C;
        cin >> L >> R;
        cin >> C;
        pair[i] = make_tuple(L-1, R-1, C);
    }
    sort(pair.begin(), pair.end(),
       [](auto const &a, auto const &b) { return get<0>(a) < get<0>(b); });
    vector<lint> dp(N, 1e15);
    priority_queue<lint, vector<lint>, greater<lint> > pq;
    dp[0] = 0;
    int i = 0;
    REP(k, N) {
        int L = get<0>(pair[i]);
        if(L > k) {
            k++;
            if(pq.empty()) {

                if(dp[N-1] == 1e15) {
                    cout << -1 << endl;
                } else {
                    cout << dp[N-1] << endl;
                }
                return 0;
            }
            lint tmp = pq.top();
            if(dp[k] > tmp) {
                lint min = 1e15;
                int idx = -1;
                FOR(j, k+1, N) {
                    if(dp[j] < min) {
                        min = dp[j];
                        idx = j;
                    }

                } 
                if(idx == -1) {
                    if(dp[N-1] == 1e15) {
                        cout << -1 << endl;
                    } else {
                        cout << dp[N-1] << endl;
                    }
                    return 0;
                }
                if(dp[k] >= min) {
                    FOR(j, k, idx) {
                        dp[j] = min;
                    }

                }
                pq.pop();
            } else if(dp[k] == tmp) {
                pq.pop();
            }

            k--;
            continue;
        }
        //cout << dp[L]+get<2>(pair[i]) << " " << dp[get<1>(pair[i])] << endl;
        if(dp[L]+get<2>(pair[i]) < dp[get<1>(pair[i])]) {
            dp[get<1>(pair[i])] = dp[L]+get<2>(pair[i]);
            pq.push(dp[L]+get<2>(pair[i]));
        }
        k--;
        i++;
        if(i == M) break;
    }
    if(dp[N-1] == 1e15) {
        cout << -1 << endl;
    } else {
        cout << dp[N-1] << endl;
    }
}

template<class T>
class SegmentTree {

public:
    /**
     * @param N size
     * @param e identity element
     * @param operation operation for query
     * @param updater operation for update
     */
    SegmentTree(size_t N, T e, function<T(T, T)> operation, function<T(T, T)> updater)
            : e(e), operation(std::move(operation)), updater(move(updater)) {
        n = 1;
        while (n < N) {
            n *= 2;
        }
        data = vector<T>(2 * n - 1, e);
    }

    /**
     * iの値をxに更新
     * @param i index ( 0-indexed )
     * @param x  value
     */
    void update(int i, T x) {
        i += n - 1;
        data[i] = updater(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    /**
     * [a, b)の区間でクエリを実行
     */
    T query(int a, int b) {
        return query(a, b, 0, 0, n);
    }

    /**
     * 添字でアクセス
     * @param i index ( 0-indexed )
     */
    T operator[](int i) {
        return data[i + n - 1];
    }

private:
    int n;
    vector<T> data;
    T e;
    function<T(T, T)> operation;
    function<T(T, T)> updater;

    T query(int a, int b, int k, int l, int r) {
        // 交差しない
        if (r <= a || b <= l) return e;
        // 区間 [a, b) に l, r が含まれる
        if (a <= l && r <= b) return data[k];
        // 左の子
        T c1 = query(a, b, 2 * k + 1, l, (l + r) / 2);
        // 右の子
        T c2 = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return operation(c1, c2);
    }
};

