template <typename X>
class Graph{
private:
  int n; // number of node
  int m; // number of edge
  vector<Node<X>> node; 

  X inf = 1e+9;
  void Init_Node() {
    rep(i,n) node.emplace_back(i);
  }
public:
  explicit Graph(int n) : n(n) {
    Init_Node();
  }

  // edges have no-weight 
  Graph(int n, int m, vector<int> from, vector<int> to) : n(n), m(m) {
    Init_Node();
    rep(i,m) {
      add_edge(from[i], to[i]);
      add_edge(to[i], from[i]);      
    }
  }  

  // edges have weight
  Graph(int n, int m, vector<int> from, vector<int> to, vector<X> cost) : n(n), m(m) {
    Init_Node();
    rep(i,m) {
      add_edge(from[i], to[i], cost[i]);
      //      add_edge(to[i], from[i], cost[i]);      
    }
  }

  void add_edge(int from, int to, X cost = 1) {
    node[from].edge.emplace_back(from, to, cost);
  }

  void Dijkstra(int s) {
    rep(i,n) node[i].dist = inf;
    node[s].dist = 0;
    priority_queue<pi, vector<pi>, greater<pi>> q;
    q.push({0, s});
    while( !q.empty() ) {
      pi p = q.top(); q.pop();
      int nd = p.first, v = p.second;
      if(node[v].dist < nd) continue;
      for(auto next: node[v].edge) {
	int w = next.to;
	X cost = next.cost;
	if(chmin(node[w].dist, node[v].dist + cost)) {
	  q.push({node[w].dist, w});
	}
      }
    }
  }

  void Solve(vector<int> a, vector<int> b) {
    vector<pi> imos;
    rep(i,m) {
      imos.push_back({a[i], 1});
      imos.push_back({b[i], -1});
    }
    rep(i,n) imos.push_back({i, 2});
    sort(imos.begin(), imos.end());
    vector<int> vec(n, 0);
    int cnt = 0;
    rep(i,imos.size()) {
      int v = imos[i].first, c = imos[i].second;
      if(c == 2) vec[v] = cnt;
      else cnt += c;
    }
    rep1(i,n-1) {
      if(vec[i] > 0 && vec[i-1] > 0) add_edge(i, i-1, (X)0);
    }
    Dijkstra(0);
    cout << (node[n-1].dist == inf ? -1 : node[n-1].dist) << "\n";
  }

};


