struct SegTree {
    int N;
    vector<Int> A;
    SegTree(int n) {
        N = 1; while (N < n) N *= 2;
        A.resize(2*N, INF);
    }
    Int get(int idx) {
        idx += N;
        Int ans = INF;
        while (idx > 0) {
            ans = min(ans, A[idx]);
            idx /= 2;
        }
        return ans;
    }
    void chmin(int L, int R, Int val) {
        L += N, R += N;
        while (L < R) {
            if (L & 1) {
                A[L] = min(A[L], val);
                L++;
            }
            if (R & 1) {
                R--;
                A[R] = min(A[R], val);
            }
            L /= 2, R /= 2;
        }
    }
};
