//区間更新、区間Min。更新は新しい方ではなく、値の小さい方を優先。
const int DEPTH = 17;
const int INF = 1e+16;
struct RUQ {
	int d[1 << (DEPTH + 1)];
	RUQ() {
		int i;
		rep(i, (1 << (DEPTH + 1))) d[i] = INF;
	}

	//[l, r)
	void update(int l, int r, int x, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (a >= r || b <= l) return;
		if (l <= a && b <= r) {
			d[id] = min(d[id], x);
			return;
		}
		update(l, r, x, a, (a + b) / 2, id * 2 + 1);
		update(l, r, x, (a + b) / 2, b, id * 2 + 2);
	}

	int query(int pos) {
		int ret = INF;

		pos += (1 << DEPTH) - 1;
		ret = min(ret, d[pos]);
		while (pos > 0) {
			pos = (pos - 1) / 2;
			ret = min(ret, d[pos]);
		}
		return ret;
	}
};

int n, m;
T tupl[100001];	//(l, r, c)
int l[100001], r[100001], c[100001];
RUQ ruq;

signed main() {
	int i;

	cin >> n >> m;
	rep(i, m) {
		cin >> l[i] >> r[i] >> c[i];
		l[i]--; r[i]--;
		tupl[i] = T(l[i], r[i], c[i]);
	}
	sort(tupl, tupl + m);

	rep(i, m) {
		l[i] = get<0>(tupl[i]);
		r[i] = get<1>(tupl[i]);
		c[i] = get<2>(tupl[i]);
	}
	l[m] = n - 1; r[m] = n - 1; c[m] = 0;
	m++;

	ruq.update(0, 1, 0);	//dp[0] = 0
	rep(i, m - 1) {
		int val = ruq.query(i);
		val += c[i];

		//r[i] > l[j]なる最小のjを探す
		int iter = upper_bound(l, l + m, r[i]) - l;

		//[i + 1, iter)を更新
		ruq.update(i + 1, iter, val);
	}

	int res = ruq.query(m - 1);
	if (res >= INF / 2) cout << -1 << endl;
	else cout << res << endl;
	return 0;
}

