class MinSegTree{
	vector<ll> data;
	int baseSize, baseOffset;
public:
	MinSegTree(vector<ll> &ary){
		baseSize = 1;
		for(;;baseSize*=2){if (ary.size()<=baseSize) break;}
		baseOffset = baseSize - 1;
		data = vector<ll>(baseSize * 2, LLONG_MAX/10);
		for(int i=0;i<ary.size();i++) data[baseOffset+i] = ary[i];
		//initial upward propagation
		for(int i=baseOffset-1;i>=0;i--){
			data[i] = min(data[2*i+1], data[2*i+2]);
		}
	}
	ll getMin(int s, int e, int k=0, int l=0, int r=-1){
		/* getMin(s, e) で [s, e) の最小値を計算できます．

			クエリ区間 [s, e) と管理区間 [l, r) の共通部分について解く．
		  （(k,l,r)==(0,0,baseSize) から始めて，分割統治していく） */

		// cerr << "getMin(" << s << "," << e << "," << k << "," << l << "," << r << ")" << endl;
		if (r < 0) r = baseSize; //初期の管理区間

		ll ret;
		if (e <= l || r <= s) ret = LLONG_MAX/10; //クエリ区間と管理区間が交わらないケース（空区間）// !!
		else if (s <= l && r <= e) ret = data[k]; //クエリ区間が管理区間を被覆するケース
		else ret = min(getMin(s, e, k*2+1, l, (l+r)/2), getMin(s, e, k*2+2, (l+r)/2, r)); //分割統治 !!
		// cerr << "getMin(" << s << "," << e << "," << k << "," << l << "," << r << ") == " << ret << endl;
		return ret;
	}
	void update(int idx, ll val){
		/* (0 <= idx < baseSize) */
		// cerr << "======================" << endl;
		// cerr << "UPDATE " << idx << " TO " << val << endl;
		// cerr << to_string(data) << endl;
		idx += baseOffset;
		data[idx] = val;
		while(idx > 0){
			idx = (idx - 1) / 2;
			data[idx] = min(data[idx*2+1], data[idx*2+2]);
		}
		// cerr << to_string(data) << endl;
		// cerr << "====================" << endl;
		return;
	}
	ll at(int idx){
		return data[idx + baseOffset];
	}
	//TODO: 遅延評価セグ木（区間に一様に値を変更できるようになる・・・はず）
	//http://tsutaj.hatenablog.com/entry/2017/03/30/224339
};



