struct Edge {
  int to;
  ll cost;

  Edge(int to, ll cost): to(to), cost(cost) {}

  bool operator < (const Edge e) const {
    return cost < e.cost;
  }
};

vector<Edge> G[MAX];
ll d[MAX];
int n;

void dijkstra() {
  rep(i, n) d[i] = INF;
  d[0] = 0;

  int u;
  priority_queue<Edge> pq;
  pq.push(Edge(0, 0));

  while (!pq.empty()) {
    Edge ee = pq.top();
    pq.pop();
    u = ee.to;

    if (d[u] < -ee.cost) continue;

    rep(i, G[u].size()) {
      Edge e = G[u][i];
      if (d[u] + e.cost < d[e.to]) {
        d[e.to] = d[u] + e.cost;
        e.cost *= -1;
        pq.push(e);
      }
    }
  }

}

