    vector<int> rngs;
    for (int i = 0, j; i < 2 * M; i = j) {
        for (j = i + 1; j < 2 * M; ++j) {
            if (LRi[j].first != LRi[i].first) break;
        }

        rngs.push_back(LRi[i].first);
    }

    SegmentTree<ll, min_of<ll>, identity> dp;
