struct Seq {
    int l;
    int r;
    ll c;
};

bool operator<(Seq const& lhs, Seq const& rhs) {
    if (lhs.l == rhs.l) {
        if (lhs.r == rhs.r) {
            return lhs.c < rhs.c;
        }
        return lhs.r < rhs.r;
    }
    return lhs.l < rhs.l;
}

struct RNGT {
    int nd;
    vector<ll> d;

    RNGT(int n) {
        nd = n;
        d.resize(nd * 4, INF);
    }

    void update(int qp, ll val) { return __update(1, 0, nd - 1, qp, val); }
    void __update(int p, int l, int r, int qp, ll val) {
        if (qp < l || r < qp) return;
        if (l == r) {
            d[p] = min(d[p], val);
            return;
        }

        int mid = l + (r - l) / 2;
        if (qp <= mid) {
            __update(p * 2, l, mid, qp, val);
        } else {
            __update(p * 2 + 1, mid + 1, r, qp, val);
        }
        d[p] = min(d[p * 2], d[p * 2 + 1]);
    }

    ll query(int ql, int qr) { return __query(1, 0, nd - 1, ql, qr); }
    ll __query(int p, int l, int r, int ql, int qr) {
        if (l>r || r < ql || qr < l) return INF;
        if (ql <= l && r <= qr) return d[p];

        int mid = l + (r - l) / 2;
        return min(__query(p * 2, l, mid, ql, qr), __query(p * 2 + 1, mid + 1, r, ql, qr));
    }
};

