struct P {
  int L;
  int R;
  ll  C;
};

int N, M; 
std::vector<int> Lonly;
std::vector<P> list;

ll solve(int v /* 0 ~ M-1 */, ll cost) {
  if ( list[v].R == N ) return cost;
  int upind = std::distance( Lonly.begin(), std::upper_bound( all(Lonly), list[v].R ) );
  ll costmin = 1e15;
  for(int k=v+1; k<upind; k++) costmin = std::min(costmin, solve(k,cost+list[k].C));
  if ( costmin == 1e15 ) return -1;
  return costmin;
}

int main (void) {
