    Lonly[i] = list[i].L;
  }
  std::sort ( all(list), [](P &x, P &y) {return x.L < y.L;} );
  std::sort ( all(Lonly) );

  ll ans = 1e15;
  for(int i=0; i<M; i++) {
    if ( list[i].L != 1 ) break;
    ans = std::min(ans, solve(i,list[i].C));
  }
  std::cout << ans << std::endl;
  return 0;
}

