using namespace std;

template <typename T>
struct LazySegtree {
	private:
		size_t n;
		vector<T> node, lazy;
		T M0, L0;

	public:
		LazySegtree(size_t sz, T m0, T l0) {
			n = 1;
			M0 = m0;
			L0 = l0;
			while (n < sz) { n *= 2; }
			node.assign(2*n - 1, M0);
			lazy.assign(2*n - 1, L0);
		}

		T merge(T a, T b) { return min(a, b); }
		void updateNode(int k, T x) { lazy[k] = min(lazy[k], x); }
		void propagate(int k) { node[k] = min(node[k], lazy[k]); }

		void eval(int k, int l, int r) {
			if (lazy[k] == L0) { return; }
			propagate(k);
			if (r - l > 1) {
				updateNode(2*k + 1, lazy[k]);
				updateNode(2*k + 2, lazy[k]);
			}
			lazy[k] = L0;
		}

		void update(int a, int b, T x, int k=0, int l=0, int r=-1) {
			if (r < 0) { r = n; }
			eval(k, l, r);
			if (r <= a || b <= l) { return; }
			if (a <= l && r <= b) {
				updateNode(k, x);
				eval(k, l, r);
			} else {
				update(a, b, x, 2*k + 1, l, (l + r) / 2);
				update(a, b, x, 2*k + 2, (l + r) / 2, r);
				node[k] = merge(node[2*k + 1], node[2*k + 2]);
			}
		}

		T query(int a, int b, int k=0, int l=0, int r=-1) {
			if (r < 0) { r = n; }
			eval(k, l, r);
			if (r <= a || b <= l) { return M0; }
			if (a <= l && r <= b) { return node[k]; }
			T vl = query(a, b, 2*k + 1, l, (l + r) / 2);
			T vr = query(a, b, 2*k + 2, (l + r) / 2, r);
			return merge(vl, vr);
		}
};

int main() {
	const Int INF = 1e17;
	int N, M;
	cin >> N >> M;
	vector<tuple<int, int, int>> tap;
	for (int i = 0; i < M; ++i) {
		int L, R, C;
		cin >> L >> R >> C;
		tap.emplace_back(L, R, C);
	}
	sort(tap.begin(), tap.end());


	LazySegtree<Int> seg(N + 10, INF, INF);
	seg.update(1, 2, 0);
	for (int i = 0; i < M; ++i) {
		int L = get<0>(tap[i]);
		int R = get<1>(tap[i]);
		int C = get<2>(tap[i]);
		Int cost = min((Int)(seg.query(L, L + 1) + C), INF);
		seg.update(L + 1, R + 1, cost);
	}
	Int ans = seg.query(N, N + 1);
	cout << (ans < INF ? ans : -1) << endl;

	return 0;
}

