// 遅延伝播セグメント木
template <typename T,typename E,typename F,typename G,typename H>
struct LST{
  int n,height;
  F f;
  G g;
  H h;
  T ti;
  E ei;
  vector<T> dat;
  vector<E> laz;
  LST(int n, F f,G g,H h,T ti,E ei):
    f(f),g(g),h(h),ti(ti),ei(ei){
      init(n);
  }
  LST(const vector<T> &v, F f,G g,H h,T ti,E ei):
    f(f),g(g),h(h),ti(ti),ei(ei){
      init( (int)v.size() );
      build(v);
  }

  void init(int n_){
    n=1;height=0;
    while(n<n_) n<<=1,height++;
    dat.assign(2*n,ti);
    laz.assign(2*n,ei);
  }
  void build(const vector<T> &v){
    int n_=v.size();
    init(n_);
    for(int i=0;i<n_;i++) dat[n+i]=v[i];
    for(int i=n-1;i;i--)
      dat[i]=f(dat[(i<<1)|0],dat[(i<<1)|1]);
  }
  inline T reflect(int k){
    return laz[k]==ei?dat[k]:g(dat[k],laz[k]);
  }
  inline void eval(int k){
    if(laz[k]==ei) return;
    laz[(k<<1)|0]=h(laz[(k<<1)|0],laz[k]);
    laz[(k<<1)|1]=h(laz[(k<<1)|1],laz[k]);
    dat[k]=reflect(k);
    laz[k]=ei;
  }
  inline void thrust(int k){
    for(int i=height;i;i--) eval(k>>i);
  }
  inline void recalc(int k){    
    while(k>>=1)
      dat[k]=f(reflect((k<<1)|0),reflect((k<<1)|1));
  }
  void update(int a,int b,E x){
    thrust(a+=n);
    thrust(b+=n-1);
    for(int l=a,r=b+1;l<r;l>>=1,r>>=1){
      if(l&1) laz[l]=h(laz[l],x),l++;
      if(r&1) --r,laz[r]=h(laz[r],x);
    }
    recalc(a);
    recalc(b);
  }
  void set_val(int a,T x){
    thrust(a+=n);
    dat[a]=x;laz[a]=ei;
    recalc(a);
  }
  T query(int a,int b){
    thrust(a+=n);
    thrust(b+=n-1);
    T vl=ti,vr=ti;
    for(int l=a,r=b+1;l<r;l>>=1,r>>=1) {
      if(l&1) vl=f(vl,reflect(l++));
      if(r&1) vr=f(reflect(--r),vr);
    }
    return f(vl,vr);
  }
};

void solve(){
  ini(N , M);
  vi L(M) , R(M); vl C(M);
  rep(i , M) {
    in(L[i] , R[i] , C[i]);
    L[i]--; R[i]--;
  }
  vi ord(M); iota(all(ord) , 0);
  sort(all(ord),[&](int l,int r){
    //return R[l] == R[r] ? L[l] < L[r] : R[l] < R[r];
    return L[l] < L[r];
  });
  int oi = 0;

  // 区間をxに更新・区間最小を取得 
  // (区間更新一点取得にも使える)
  constexpr ll T_UNIT = infLL;
  constexpr ll E_UNIT = T_UNIT;
  vector<ll> v(N, T_UNIT);
  auto f=[](ll a, ll b){
    return min(a , b);
  };
  auto gg=[](ll a, ll b){
    return min(a , b);
  };
  auto h=[](ll a, ll b){
    return min(a , b);
  };
  LST<ll,ll,decltype(f),decltype(gg),decltype(h)>
    lst(v,f,gg,h,T_UNIT,E_UNIT);

  lst.update(0 , 1 , 0);
  rep1(i , N - 1){
    while(oi != M && L[ord[oi]] < i){
      // 更新
      ll nya = lst.query(L[ord[oi]] , L[ord[oi]] + 1);
      lst.update( L[ord[oi]] + 1, R[ord[oi]] + 1 , nya + C[ord[oi]]);
      oi++;
    }
  }
  ll ans = lst.query(N - 1 , N);
  out(ans >= infLL ? -1 : ans);
}

