	for(register int i=1;i<=N*4;i++) lat[i]=inf;
	int n,m;
	n=rf(),m=rf();
	int l,r,c;
	built(1,n,1);
	ll minn;
	for(int i=1;i<=m;i++){
		l=rf(),r=rf(),c=rf();
		minn=query(1,n,1,l,r);
		modify(1,n,1,l,r,minn+c);
	}
	ll ans=query(1,n,1,n,n);
	if(ans>=inf) cout<<"-1";
	else cout<<ans;
	return 0;
}

