// <最短距離, 頂点の番号>
using P = pair<ll, ll>;

ll V;
vector<edge> G[MAX_V];
ll d[MAX_V];

void dijkstra(ll s)
{
    priority_queue<P, vector<P>, greater<P>> que;

    fill(d, d + MAX_V, INF);
    d[s] = 0;

    que.push(P(d[s], s));

    while (!que.empty())
    {
        P p = que.top();

        que.pop();

        ll v = p.second;

        if (d[v] < p.first)
            continue;

        for (ll i = 0; i < G[v].size(); ++i)
        {
            edge e = G[v][i];

            ll tpcost = d[v] + e.cost;

            if (d[e.to] > tpcost)
            {
                d[e.to] = tpcost;

                que.push(P(d[e.to], e.to));
            }
        }
    }
}

