class Dijkstra{
public:
    struct edge{
        int to;
        int cost;
    };
    int vertex;
    vector<vector<edge>> graph;
    vector<int> dist;
    vector<int> hist;

    Dijkstra(int n){
        vertex = n;
        graph = vector<vector<edge>>(n);
        dist = vector<int>(n);
        hist = vector<int>(n,-1);
    };

    void dijkstra(int s){
        priority_queue<pii, vector<pii>, greater<pii>> que;
        fill(dist.begin(), dist.end(), MAX_DIST);
        dist[s] = 0;
        que.push(pii(0, s));

        while (!que.empty()){
            pii p = que.top();  //cost/to
            que.pop();
            int v = p.second;
            if (dist[v] < p.first) continue;
            for (int i = 0; i < graph[v].size(); i++) {
                edge e = graph[v][i];
                if (dist[e.to] > dist[v] + e.cost && !(dist[e.to] == MAX_DIST && dist[v] == MAX_DIST)){
                    dist[e.to] = dist[v] + e.cost;
                    hist[e.to] = v;
                    que.push(pii(dist[e.to], e.to));
                }
            }
        }

    }

    void addEdge(int from, int to, int cost) {
        edge e;
        e.to = to;
        e.cost = cost;
        graph[from].push_back(e);
    }

};


