#define MAX 100005
#define MOD 998244353
#define EPS 0.0000000001
#define INF 1000000000000000
long long segment_tree[MAX*4],d[MAX];
void build(int index,int l,int r)
{
    if(l==r)
    {
        segment_tree[index]=INF;
        d[l]=INF;
        return;
    }
    int m=(l+r)/2;
    build(index*2,l,m);
    build(index*2+1,m+1,r);
    segment_tree[index]=INF;
}
void update(int index,int l,int r,int L,int R,long long val)
{
    if(l>R||r<L) return;
    if(L<=l&&r<=R)
    {
        segment_tree[index]=min(segment_tree[index],val);
        return;
    }
    int m=(l+r)/2;
    update(index*2,l,m,L,R,val);
    update(index*2+1,m+1,r,L,R,val);
}
long long query(int index,int l,int r,int ind,long long val=INF)
{
    segment_tree[index]=min(segment_tree[index],val);
    if(ind<l||ind>r) return INF;
    if(l==r)
    {
        return segment_tree[index];
    }
    int m=(l+r)/2;
    long long first=query(index*2,l,m,ind,segment_tree[index]);
    long long second=query(index*2+1,m+1,r,ind,segment_tree[index]);
    return min(first,second);
}
