using namespace std;


int seg[400005];
int lz[400005];
void build(int ver,int tl,int tr)
{
    if(tl>tr)
        return ;
    else if(tl==tr)
    {
        lz[ver]=1e17;
        seg[ver]=1e17;
    }
    else
    {
        int tm=(tl+tr)/2;
        build(2*ver,tl,tm);
        build(2*ver+1,tm+1,tr);
        seg[ver]=1e17;
        lz[ver]=1e17;
    }
}

void push(int ver)
{
    seg[2*ver]=min(seg[2*ver],lz[ver]);
    seg[2*ver+1]=min(seg[2*ver+1],lz[ver]);
    lz[2*ver]=min(lz[2*ver],lz[ver]);
    lz[2*ver+1]=min(lz[2*ver+1],lz[ver]);
    lz[ver]=1e17;
}

void upd(int ver,int tl,int tr,int l,int r,int val)
{
    if(tl>tr||l>r||tr<l||r<tl)
        return ;
    else if(tl==l&&tr==r)
    {
        seg[ver]=min(seg[ver],val);
        lz[ver]=min(lz[ver],val);
    }
    else
    {
        int tm=(tl+tr)/2;
        if(lz[ver]!=1e17)
            push(ver);
        upd(2*ver,tl,tm,l,min(tm,r),val);
        upd(2*ver+1,tm+1,tr,max(tm+1,l),r,val);
        seg[ver]=min(seg[2*ver],seg[2*ver+1]);
    }    
}

int get(int ver,int tl,int tr,int l,int r)
{
    if(tl>tr||l>r||tr<l||r<tl)
        return 1e17;
    else if(tl==l&&tr==r)
    {
        return seg[ver];
    }
    else
    {
        int tm=(tl+tr)/2;
        if(lz[ver]!=1e17)
            push(ver);
        int z= min(get(2*ver,tl,tm,l,min(tm,r)),get(2*ver+1,tm+1,tr,max(tm+1,l),r));
        seg[ver]=min(seg[2*ver],seg[2*ver+1]);
        return z;        
    }    
}

