#define st first
#define nd second
#define PLL pair <LL, LL>
#define PII pair <int, int>

const int N = 1e6 + 7;
const int T = 1 << 17;

const int MX = 1e9 + 7;
const LL INF = 1LL * MX * MX;

int n, m;
LL dist[N];
bool vis[N];
vector <PII> G[N];

void addEdge(int from, int to, int id, int cost){
	from += T, to += T;
	while(from <= to){
		if(from & 1){
			G[from + n + m].push_back({id, 0});
			G[id].push_back({from + n + m + T + T, cost});
		}

		if(!(to & 1)){
			G[to + n + m].push_back({id, 0});
			G[id].push_back({to + n + m + T + T, cost});
		}

		from = (from + 1) >> 1;
		to = (to - 1) >> 1;
	}
}

void Dijkstra(){
	for(int i = 1; i <= n + m + 4 * T; ++i)
		dist[i] = INF;
	dist[1] = 0;

	priority_queue <PLL> Q;
	Q.push({0, 1});

	while(!Q.empty()){
		int u = Q.top().nd;
		Q.pop();

		if(vis[u])
			continue;
		vis[u] = true;

		for(auto v: G[u])
			if(dist[v.st] > dist[u] + v.nd){
				dist[v.st] = dist[u] + v.nd;
				Q.push({-dist[v.st], v.st});
			}
	}
}

int main(){
	scanf("%d %d", &n, &m);
	for(int i = 1; i <= m; ++i){
		int l, r, c;
		scanf("%d %d %d", &l, &r, &c);
		addEdge(l, r, i + n, c);
	}

	for(int i = 1; i <= n; ++i){
		G[i].push_back({n + m + T + i, 0});
		G[n + m + 3 * T + i].push_back({i, 0});
	}

	for(int i = 2; i < T + T; ++i){
		G[i + n + m].push_back({i / 2 + n + m, 0});
		G[i / 2 + n + m + T + T].push_back({i + n + m + T + T, 0});
	}

	Dijkstra();
	if(dist[n] == INF)
		puts("-1");
	else
		printf("%lld\n", dist[n]);
	return 0;
}

