/// sa bag curatari mai multe
struct AINT {
    vector<ll> val;
    vector<ll> lazy;

    AINT(int sz) {
        lazy.resize(4 * sz + 5, INF);
    }

    void update(ll val, int from, int to, int node, int le, int ri) {
        if(from <= le && ri <= to)
            lazy[node] = min(lazy[node], val);
        else {
            int mid = (le + ri) / 2;
            if(from <= mid)
                update(val, from, to, node * 2, le, mid);
            if(mid < to)
                update(val, from, to, node * 2 + 1, mid + 1, ri);
        }
    }

    ll query(int x, int node, int le, int ri) {
        if(le == ri)
            return lazy[node];

        int mid = (le + ri) / 2;
        if(x <= mid)
            return min(lazy[node], query(x, node * 2, le, mid));
        else
            return min(lazy[node], query(x, node * 2 + 1, mid + 1, ri));
    }

};

