#include <bits/stdc++.h>
using namespace std;

int n,m;
int MAXIMUM=200000;
long INF = 1e18+7;
// W:未訪問
// G:訪問する候補
// B:訪問済み
int W=0,G=1,B=2;
vector<pair<long,long>> adj[200000];

int dijkstra(){
  priority_queue<pair<long,long>> PQ;
  long u;
  long d[MAXIMUM],color[MAXIMUM];
  // d[n]:Tに属する頂点と V - T に属する頂点をつなぐ辺の中で重みが最小の辺の重みを記録

  //初期化
  for(int i=0;i<n;i++){
    d[i]=INF;
    color[i]=W;
  }

  d[0]=0;
  PQ.push(make_pair(0,0));
  color[0] = G;

  while (!PQ.empty()) {
    pair<long,long> f = PQ.top();
    PQ.pop();
    u = f.second;
    // 頂点を訪問済に
    color[u] = B;
    //最小値を取り出し、それが最短でなければ無視
    if( d[u]<f.first*(-1)) continue;

    //訪問済みでないかつ辺がつながっている頂点の中でコストが最小の辺を選択
    for(int j=0;j<adj[u].size();j++){
      long v = adj[u][j].first;
      if(color[v]== B) continue;
      if(d[v]>d[u]+adj[u][j].second){
        d[v]=d[u]+adj[u][j].second;
        PQ.push(make_pair(d[v]*(-1),v));
        color[v]=G;
      }
    }
  }


    if(d[n-1]!=INF) cout<<d[n-1]<<endl;
    else cout<<-1<<endl;

}

