        a--;
        b--;
        for (int a_ = a; a_ <= b; a_++)
        {
            for (int b_ = a_ + 1; b_ <= b; b_++)
            {
                edge e = {b_, c};
                G[a_].push_back(e);
            }
        }
        //G[b].push_back(e2);
    }
    dijkstra(0);
    if (d[V - 1] == INF)
    {
        cout << -1 << endl;
    }
    else
    {
        cout << d[V - 1] << endl;
    }
    return 0;
}

