using Data = ll;
constexpr Data INF = 1e15;

struct SegTreeLazy {
  static const int MAX_DEPTH = 18;
  static const int STsize = 1 << MAX_DEPTH;
  Data data[STsize];
  Data lazy[STsize]; int n;
  SegTreeLazy(void) : n(STsize / 2) {
    for(int i:irange(0,STsize)) {
      data[i]=lazy[i]=INF;
    }
  }
  void upd(int fr, int to, Data val) { upd_sub(fr, to, 2*n-2, 0, n, val); }
  Data min_(int fr, int to) { return min_sub(fr, to, 2*n-2, 0, n); }
 private:
  void upd_sub(int fr, int to, int node, int la, int ra, Data val) {
    if (ra<=fr || to<=la) return;
    if (fr<=la && ra<=to) {
      lazy[node] = min(lazy[node], val);
      data[node] = min(data[node], val);
      return;
    }
    data[node] = min(data[node], val);
    upd_sub(fr, to, (node-n)*2+0, la, (la+ra)/2, val);
    upd_sub(fr, to, (node-n)*2+1, (la+ra)/2, ra, val);
  }
  Data min_sub(int fr, int to, int node, int la, int ra) {
    if (ra<=fr || to<=la) return INF;
    if (fr<=la && ra<=to) return min(data[node], lazy[node]);
    Data res = lazy[node];
    res = min(res, min_sub(fr, to, (node-n)*2+0, la, (la+ra)/2));
    res = min(res, min_sub(fr, to, (node-n)*2+1, (la+ra)/2, ra));
    return res;
  }
};

int main()
{
