  for(auto t:vt) {
    ll l,r,c;
    tie(l,r,c) = t;
    ll d=stl.min_(l,l+1);
    stl.upd(l,r+1,d+c);
  }
  ll res = stl.min_(n-1,n);
  if (res >= INF) {
    cout<<-1<<endl;
  } else {
    cout<<res<<endl;
  }
  return 0;
}

