  dist[0] = 0;
  multiset<ll> costs;

  rep(i, N) {
    if (!costs.empty()) {
      dist[i] = *costs.cbegin();
    }

    if (dist[i] != INF) {
      for (auto e : ls[i]) {
        costs.insert(dist[i] + e.c);
      }
    }

    for (auto e : rs[i]) {
      if (dist[e.l] + e.c < INF) {
        costs.erase(costs.find(dist[e.l] + e.c));
      }
    }
  }

  ll res = dist[N - 1] == INF ? -1 : dist[N - 1];
  cout << res << endl;
}

