bool mar[MN];
vector<int> tree[3*MN];
void upd(int node, int a, int b, int l, int r, int val){
    if(a > r || b < l || a > b) return;

    //cout << "doing " << node << " " << a << " " << b << "\n";

    if(l <= a && b <= r){
        tree[node].pb(val);
        return;
    }

    upd(node*2, a, (a+b)/2, l, r, val);
    upd(node*2+1, 1+(a+b)/2, b, l, r, val);
}

ll dist[MN];
priority_queue<pll, vector<pll>, greater<pll> > pq;

void que(int node, int a, int b, int i, pll top){
    if(a > i || b < i || a > b) return;

    for(auto u : tree[node]){
        if(mar[u]) continue;
        pq.push({top.f+ed[u].s, ed[u].f.s});
    }
    if(a == b) return;
    que(node*2, a, (a+b)/2, i, top);
    que(node*2+1, 1+(a+b)/2, b, i, top);
}

ll dijk(){
    memset(dist, -1, sizeof dist);
    pq.push({0, 1});
    while(!pq.empty()){
        pii top = pq.top();
        pq.pop();
        int cn = top.s;
        if(dist[cn] != -1) continue;
        dist[cn] = top.f;
        //cout << "on " << cn << "\n";
        if(cn == n) return dist[cn];
        que(1, 1, n, cn, top);
    }
    return -1;
}

