// < 双対セグメント木クラス >
// @ 概要 | 区間更新・点取得が高速に行える O(logN)
// @ 要件 | monoid_type : 1, using value_type = oo; の形が記述されている等、用いる型にアクセス可能なこと
//                       2, staticメンバ変数として単位元 identity_element が定義されていること
//                       3, static関数 operation が定義されており, かつ以下の条件を満たすこと
//                           (i) (f*g)(x) = f(g(x))
template <class monoid_type> class dualSegmentTree{
private:
    using element_t = typename monoid_type::value_type;   // 要素の型 (渡した型に依存する)
    const unsigned int original_length;                   // 元の配列の長さ : A.size()
    const unsigned int height;                            // 配列の要素の数の指数部 : 
    const unsigned int length;                            // 配列の要素の数 : 2^k (2のべき乗)k
    std::allocator<element_t> alloc;                      // データのアロケータ
    element_t* data;                                      // 格納しているデータ(配列)本体(を指すポインタ)

    static unsigned int set_log_len(const unsigned int n){
        unsigned int res = 0; while((1U << res) < n) ++res; return res;
    }
    inline void propagate(unsigned int idx){
        for(unsigned int i = height, jp, jc; i ; --i){
            jp = idx >> i; jc = jp << 1;
            if(data[jp] == monoid_type::identity_element) continue;
            data[jc | 0] = monoid_type::operation(data[jc | 0], data[jp]);
            data[jc | 1] = monoid_type::operation(data[jc | 1], data[jp]);
            data[jp    ] = monoid_type::identity_element;
        }
    }
public:
    dualSegmentTree(const unsigned int n): original_length(n), height(set_log_len(n)), length(1U << height){
        data = alloc.allocate(length << 1); std::fill(data, data + (length << 1), monoid_type::identity_element);
    }
    template <class InputIterator>
    dualSegmentTree(InputIterator first, InputIterator last):original_length(last - first), height(set_log_len(original_length)), length(1U << height){
        data = alloc.allocate(length << 1); std::fill(data, data + length, monoid_type::identity_element);
        std::copy(first, last, data + length); std::fill(data + length + original_length, data + (length << 1), monoid_type::identity_element);
    }
    ~dualSegmentTree(void){ alloc.deallocate(data, (length << 1)); }

    // 区間更新 : O(logN)
    inline void update(unsigned int l, unsigned int r, const element_t& op){
        propagate(l += length); propagate((r += length) - 1);
        while(l < r){
            if(l & 1){ data[l] = monoid_type::operation(data[l], op); l++; }
            if(r & 1){ --r; data[r] = monoid_type::operation(data[r], op); }
            l >>= 1; r >>= 1;
        }
    }

    // 点更新 : O(logN)
    inline void update_at(unsigned int idx, const element_t& op){
        propagate(idx += length); data[idx] = monoid_type::operation(data[idx], op);
    }

    // 点取得 : 計算量 O(logN)
    inline element_t operator [](unsigned int idx) const {
        element_t res = data[idx += length]; while(idx >>= 1) res = monoid_type::operation(res, data[idx]);
        return res;
    }
    inline element_t at(unsigned int idx) const {
        assert(idx < original_length);
        element_t res = data[idx += length]; while(idx >>= 1) res = monoid_type::operation(res, data[idx]);
        return res;
    }
};

struct RangeUpdate{
    using value_type = long long int;
    static const value_type identity_element = 1LL << 60;
    static value_type operation(const value_type& val, const value_type& op){
        return (val > op) ? op : val;
    }
};

