    L[i]--;
    R[i]--;
    edge[L[i]].push_back(std::make_pair(R[i], C[i]));
  } 
  for (int i=1; i<N; i++) {
    edge[i].push_back(std::make_pair(i-1, 0));
  }
  std::vector<long long> dist(N, 1e18);
  std::priority_queue<std::pair<long long, int> > queue;
  queue.push(std::make_pair(0, 0));
  while(queue.size() > 0) {
    int v = queue.top().second;
    long long d = queue.top().first;
    queue.pop();
    if (dist[v]<d) continue;
    for (auto &entry : edge[v]) {
      int vv = entry.first;
      long long dd = entry.second;
      if (dist[vv]==(long long)1e18 || dist[vv]>d+dd ) {
        dist[vv] = d+dd;
        queue.push(std::make_pair(d+dd, vv));
      }
    }
  }
  if (dist[N-1] == (long long)1e18) {
