using namespace std;

typedef struct {
    int L;
    int R;
    long long int C;

    string to_string(){
        char s[100];
        sprintf(s, "{ L: %d, R: %d, C: %lld }", L, R, C);
        return string(s);
    }
} edge_t;

long long int get_shortest_time_on_point(
        int point, map<int, long long int> shortest_time_by_end_point) {
    if (point == 0) {
        return 0LL;
    }

    auto maybe_time_itr = shortest_time_by_end_point.lower_bound(point);
    if (maybe_time_itr == shortest_time_by_end_point.end()) {
        return INT64_MAX;
    } else {
        return maybe_time_itr->second;
    }
}

int main() {
    // get values from input
    int N, M;

    cin >> N >> M;

    map<int, vector<edge_t>> edges_by_start;
    for (int i = 0; i < M; ++i) {
        int Li, Ri;
        long long int Ci;

        // save L and R as substracted number by 1
        cin >> Li >> Ri >> Ci;
        edges_by_start[Li - 1].push_back(edge_t{Li - 1, Ri - 1, Ci});
    }

    // ### DEBUG ###
    // ========================================
//    for(auto edges:edges_by_start){
//        cout << "start from " << edges.first << endl;
//        for (auto edge:edges.second) {
//            cout << edge.to_string() << endl;
//        }
//        cout << "========================================" << endl;
//    }
    // ========================================


    // main procedure

    // if no edges connected with start node
    if(edges_by_start.count(0) == 0) {
        cout << -1 << endl;
        return 0;
    }

    /* ex. if you can go 6 points by
     *      0, 1, 1, 4, 7, 7
     * the map will be
     *      {[0]:0, [2]:1, [3]:4, [5]:7}
     */
    map<int, long long int> shortest_time_by_end_point;


    int current_start_point = 0; // currently looking L of edges
    auto maybe_current_edges_itr = edges_by_start.begin();

    while (maybe_current_edges_itr != edges_by_start.end()) {
        // edges that L = current_start
        vector<edge_t> current_edges = maybe_current_edges_itr->second;

        // sort so that the edge having biggest R comes first
        sort(current_edges.begin(), current_edges.end(), [](const edge_t& e1, const edge_t& e2){
            return e1.R > e2.R;
        });

        for(auto edge : current_edges){
            // ### DEBUG ###
            // ========================================
//            cout << "before applying edge: " << edge.to_string() << endl;
//            cout << "{ ";
//            for (auto pair : shortest_time_by_end_point) {
//                auto point = pair.first;
//                auto time = pair.second;
//                cout << point << ": " << time << ", ";
//            }
//            cout << "}" << endl;
//            cout << "========================================" << endl;
            // ========================================

            // shortest time at point R by using current edge
            long long int start_time_on_edge =
                    get_shortest_time_on_point(current_start_point, shortest_time_by_end_point);
            long long int shortest_time_by_edge;
            if (start_time_on_edge == INT64_MAX) {
                shortest_time_by_edge = INT64_MAX;
            } else {
                shortest_time_by_edge = start_time_on_edge + edge.C;
            }

            // ### DEBUG ###
            // ========================================
//            cout << "on applying edge: " << edge.to_string() << endl;
//            cout << "shortest time by edge: " << shortest_time_by_edge << endl;
//            cout << "current shortest time: " << get_shortest_time_on_point(edge.R, shortest_time_by_end_point) << endl;
//            cout << "========================================" << endl;
            // ========================================

            // if no need to change
            if (shortest_time_by_edge >=
                    get_shortest_time_on_point(edge.R, shortest_time_by_end_point)) {
                continue;
            }

            // when need to change
            shortest_time_by_end_point[edge.R] = shortest_time_by_edge;

            // setting previous point from R
            auto current_end_point_itr = shortest_time_by_end_point.find(edge.R);
            if (current_end_point_itr != shortest_time_by_end_point.begin()) {
                current_end_point_itr--;
            } else {
                // if no previous point exists
                continue;
            }

            int current_end_point = current_end_point_itr->first;
            while(current_end_point <= current_start_point) {
                // when no more need to delete
                if (shortest_time_by_edge >= shortest_time_by_end_point[current_end_point]) {
                    break;
                }
                // when need to delete
                shortest_time_by_end_point.erase(current_end_point_itr);

                // setting previous point from R
                current_end_point_itr = shortest_time_by_end_point.find(edge.R);
                if (current_end_point_itr != shortest_time_by_end_point.begin()) {
                    current_end_point_itr--;
                } else {
                    // if no previous point exists
                    break;
                }

                // refresh for next loop
                current_end_point = current_end_point_itr->first;
            }
        }

        // refresh values for next loop
        maybe_current_edges_itr = edges_by_start.upper_bound(current_start_point);
        current_start_point = maybe_current_edges_itr->first;
    }

    // output
    if (shortest_time_by_end_point.count(N - 1) == 0) {
        cout << -1 << endl;
    } else {
        cout << shortest_time_by_end_point[N - 1] << endl;
    }

    return 0;
}

