inline bool upd(int k, ll v, map<int, ll>& dp) {
  if(!dp.count(k) || v < dp[k]) {
    dp[k] = v;
    return true;
  }
  return false;
}

void solve() {
  int n, m;
  cin >> n >> m;
  vector<state> v;
  for(int i = 0; i < n; i++) {
    int a, b, c;
    cin >> a >> b >> c;
    v.push_back({pii(a, b), c});
  }
  sort(v.begin(), v.end());
  map<int, ll> dp;
  dp[1] = 0;
  int last = 1;
  int idx = 0;
  while(idx < sz(v)) {
    // cerr << idx << ": " << last << " " << dp[last] << endl;
    if(last < v[idx].first.first) {
      if(dp.upper_bound(last) == dp.end()) break;
      last = dp.upper_bound(last)->first;
      continue;
    }
    if(last >= v[idx].first.second) {
      idx++;
      continue;
    }
    assert(last < v[idx].first.second);
    upd(v[idx].first.second, dp[last] + v[idx].second, dp);
    while(dp.upper_bound(last) != dp.end()) {
      int cand = dp.upper_bound(last)->first;
      if(cand >= v[idx].first.first && cand < v[idx].first.second && upd(v[idx].first.second, dp[cand] + v[idx].second, dp)) {
        last = cand;
      }
      else {
        break;
      }
    }
    idx++;
  }
  if(!dp.count(n)) cout << "-1\n";
  else cout << dp[n] << "\n";
}

