const ll INF = 1e18;
struct edge{
	int to;
	int cost;
};

// sを始点とした全頂点の最短経路長（ダイクストラ）
// sからtに到達不可ならば d[t] = INF
vector<ll> dijkstra(int s, vector<vector<edge>> &to){
	// <最短距離、頂点番号>
	typedef pair<ll,int> P;

	priority_queue<P, vector<P>, greater<P>> que;
	vector<ll> d(to.size(), INF);

	d[s] = 0;
	que.push(P(0,s));

	while(!que.empty()){
		P p = que.top();
		que.pop();
		int v = p.second;
		if(d[v] < p.first) continue;

		for(edge e : to[v]){
			if(d[e.to] > d[v] + e.cost){
				d[e.to] = d[v] + e.cost;
				que.push(P(d[e.to], e.to));
			}
		}
	}

	return d;
}

int main(){

	int n,m;
	cin >> n >> m;

	vector<vector<edge>> to(n);
