    if(L == R) {if(flag) pos[L] = sz; return;}
    int mid = L + R >> 1;
    Build(ls[p], L, mid, flag); Build(rs[p], mid + 1, R, flag);
    if(flag) add(ls[p], p), add(rs[p], p);
    else add(p, ls[p]), add(p, rs[p]);
} 
void Add(int pa, int pb, int L, int R) {
    if(L == R) {add(pb, pa); return;}
    int mid = L + R >> 1;
    Add(ls[pa], ls[pb], L, mid); Add(rs[pa], rs[pb], mid + 1, R);
}
void Update(int p, int L, int R, int st, int ed, int c, bool flag) {
    if(L == st && ed == R) {
        if(flag) add(p, c, 0);
        else add(c, p, 0);
        return ;
    }
    int mid = L + R >> 1;
    if(st <= mid) Update(ls[p], L, mid, st, min(mid, ed), c, flag);
    if(ed > mid) Update(rs[p], mid + 1, R, max(st, mid + 1), ed, c, flag);
}
