        vis[u] = true;
        for(int i = pre[u]; i; i = nxt[i]) 
        if(!vis[to[i]] && dis[to[i]] > dis[u] + w[i]) {
            dis[to[i]] = dis[u] + w[i];
            q.push(data(to[i], dis[to[i]]));
        }
    }
}

