	sort(e + 1, e + m + 1);
	for(int i= 1; i <= m; i++) {
		update(1, 1, n, e[i].x, e[i].y, query(1, 1, n, e[i].x) + e[i].z);
	}
	int res= query(1, 1, n, n);
	if(res == 0x3f3f3f3f3f3f3f3f) res= -1;
