	int l,r,c;
	cin>>l>>r>>c;
	g[l].push_back( mp(r,c) );
	rg[r].push_back( mp(l,c) );
    }

    dp[0] = dp[1] = 0;
    ST tree;
    tree.init( dp );
    for(int i=1;i<=n;i++){
	for(int j=0;j<rg[i].size();j++){
	    ll mini =tree.find( rg[i][j].first ,i );
	    tree.update( i , min( tree.find(i,i+1), mini + rg[i][j].second)   );
	}
    }
    ll res =tree.find( n , n+1 );
    if( res == inf ){
	cout<<-1<<endl;
    }else cout<<res<<endl;

    return 0;
}

