const long long maxn=1e5+5;
long long mn[maxn<<3],lazy[maxn<<3];
void up(long long t){
	mn[t]=min(mn[t<<1],mn[t<<1|1]);
}
void down(long long t){
	if(lazy[t]){
		mn[t<<1]=min(mn[t<<1],lazy[t]);
		mn[t<<1|1]=min(mn[t<<1|1],lazy[t]);
		lazy[t<<1]=min(lazy[t<<1],lazy[t]);
		lazy[t<<1|1]=min(lazy[t<<1|1],lazy[t]);
		lazy[t]=0;
	}
}
void build(long long l,long long r,long long t){
	if(l==r){
		mn[t]=(1ll<<60);
		return ;
	}
	long long mid=(l+r)>>1;
	build(l,mid,t<<1);
	build(mid+1,r,t<<1|1);
	up(t);
}
void update(long long ll,long long rr,long long l,long long r,long long num,long long t){
	if(ll>rr) return ;
	if(ll<=l&&r<=rr){
		mn[t]=min(mn[t],num);
		if(lazy[t]) lazy[t]=min(num,lazy[t]);
		else lazy[t]=num;
		return ;
	}
	long long mid=(l+r)>>1;
	down(t);
	if(ll<=mid) update(ll,rr,l,mid,num,t<<1);
	if(rr>mid) update(ll,rr,mid+1,r,num,t<<1|1);
	up(t);
}
long long solve(long long pos,long long l,long long r,long long t){
	if(l==r){
		return mn[t];
	}
	long long mid=(l+r)>>1;
	down(t);
	if(pos<=mid) return solve(pos,l,mid,t<<1);
	else return solve(pos,mid+1,r,t<<1|1);
} 
