template <typename T, typename E>
class LazySegTree {
private:
    int n;
    vector<T> data;
    T idT;
    vector<E> lazy;
    E idE;
    function<T(T, T)> merge;
    function<T(T, E)> operate;
    function<E(E, E)> compose;
    function<E(E, int)> power;

    void eval(int k, int len) {
        if(lazy[k] == idE) return;
        if(2 * k + 1 < 2 * n - 1) {
            lazy[2 * k + 1] = compose(lazy[2 * k + 1], lazy[k]);
            lazy[2 * k + 2] = compose(lazy[2 * k + 2], lazy[k]);
        }
        data[k] = operate(data[k], power(lazy[k], len));
        lazy[k] = idE;
    }

    void _update(int a, int b, E x, int k, int l, int r) {
        eval(k, r - l);
        if(r <= a || b <= l) return;
        if(a <= l && r <= b) {
            lazy[k] = compose(lazy[k], x);
            return;
        }
       _update(a, b, x, 2 * k + 1, l, (l + r) / 2);
       _update(a, b, x, 2 * k + 2, (l + r) / 2, r);
    }

    T _query(int a, int b, int k, int l, int r) {
        eval(k, r - l);

        if(r <= a || b <= l) return idT;
        if(a <= l && r <= b) return data[k];

        T vl = _query(a, b, 2 * k + 1, l, (l + r) / 2);
        T vr = _query(a, b, 2 * k + 2, (l + r) / 2, r);
        if(2 * k + 1 < 2 * n - 1) data[k] = merge(data[2 * k + 1], data[2 * k + 2]);
        return merge(vl, vr);
    }

    public:
    LazySegTree(int _n, T _idT, E _idE, function<T(T, T)> _merge,
    function<T(T, E)> _operate, function<E(E, E)> _compose, function<E(E, int)> _power)
    : idT(_idT), idE(_idE), merge(_merge), operate(_operate), compose(_compose), power(_power) {
        n = 1;
        while(n < _n) n <<= 1;
        data = vector<T>(2 * n - 1, idT);
        lazy = vector<E>(2 * n - 1, idE);
    }

    void update(int a, int b, E x) {
        _update(a, b, x, 0, 0, n);
    }

    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }

    T operator[](int k) {
        return data[k + n - 1];
    }
};

