    [](long long a, long long b){return min(a, b);},
    [](long long a, long long b){return min(a, b);},
    [](long long a, long long b){return a;});

    tree.update(0, 1, 0);
    for(int i : order) {
        long long dist = tree.query(L[i], L[i] + 1);
        if(dist == INF) continue;
        tree.update(L[i] + 1, R[i], dist + C[i]);
    }

    long long res = tree.query(N - 1, N);
    if(res == INF) cout << -1 << endl;
    else cout << res << endl;
}

