        graph.add_edge(l - 1, r, l - 1, r, c);
        // graph.add_edge(N + M, N + M + 1, l - 1, r, 0);
    }

    graph.solve_dijkstra(0);
    cout << (graph.dist[N - 1] < 1e18 ? graph.dist[N - 1] : -1) << '\n';
}

