struct edge{
	int to;
  ll cost;
	edge(int to,ll cost):to(to),cost(cost){}
};
vector<edge> g[600100];
map<pair<int,int>,int> mu,md;
void dijkstra(int s){
    fill(d,d+V+1,LLINF);
    priority_queue<P,vector<P>,greater<P> > q;
    d[s]=0;
    q.push(P(0ll,s));
    while(!q.empty()){
        P a=q.top();
        q.pop();
        if(d[a.sec]<a.fi)continue;
        for(int i=0;i<g[a.sec].size();i++){
            edge e=g[a.sec][i];
            if(d[e.to]>d[a.sec]+e.cost){
                d[e.to]=d[a.sec]+e.cost;
                q.push(P(d[e.to],e.to));
            }
        }
    }
    return;
}
void add_edge(int s,int t,ll c){
  //cout << s << ' ' << t << ' ' << c << endl;
  g[s].pb(edge(t,c));
}
int A;
int N,M;
int n;
int L[100100],R[100100],C[100100];
void register_id(int l,int r,bool flag){
  if(l+1==r){
    if(flag)mu[mp(l,r)]=l;
    else md[mp(l,r)]=l; 
    return;
  }
  if(flag)mu[mp(l,r)]=A++;
  else md[mp(l,r)]=A++;
  int mid = (l+r)/2;
  register_id(l,mid,flag);
  register_id(mid,r,flag);
  return;
}

int construct(int l,int r,bool flag){
  if(l+1==r){
    if(flag)return mu[mp(l,r)];
    else return md[mp(l,r)];
  }
  int mid = (l+r)/2;
  int self;
  if(flag)self = mu[mp(l,r)];
  else self = md[mp(l,r)];
  int to1 = construct(l,mid,flag);
  int to2 = construct(mid,r,flag);
  if(flag){
    add_edge(self,to1,0ll);
    add_edge(self,to2,0ll);
  }else{
    add_edge(to1,self,0ll);
    add_edge(to2,self,0ll);
  }
  return self;
}

void range_to_vec(int a,int b,int l,int r,bool flag,vector<int>& v){
  if(r<=a||b<=l)return;
  if(a<=l&&r<=b){
    if(flag)v.pb(mu[mp(l,r)]);
    else v.pb(md[mp(l,r)]);
  }else{
    int mid = (l+r)/2;
    range_to_vec(a,b,l,mid,flag,v);
    range_to_vec(a,b,mid,r,flag,v);
  }
}

int main(){
  fastio();
  cin >> N >> M;
  n = 1;
  A = N;
  while(n<N)n*=2; 
  register_id(0,n,true);
  register_id(0,n,false);
  construct(0,n,true);
  construct(0,n,false);
  for(int i=0;i<M;i++){
    cin >> L[i] >> R[i] >> C[i];
    L[i]--;
    vector<int> s,t;
    range_to_vec(L[i],R[i],0,n,true,s);
    range_to_vec(L[i],R[i],0,n,false,t);
    for(int j=0;j<t.size();j++){
      add_edge(t[j],A,0);
    }
    for(int j=0;j<s.size();j++){
      add_edge(A+1,s[j],0);
    }
    add_edge(A,A+1,C[i]);
    A += 2;
  }
  V = A;
  dijkstra(0);
  if(d[N-1]==LLINF)cout << -1 << endl;
  else cout << d[N-1] << endl;
  return 0;
}

