const ll INF = 1ll << 60;

struct interval_t {
  int to;
  ll w;
};

int main() {
#ifdef DEBUG
  ifstream ifs("in.txt");
  cin.rdbuf(ifs.rdbuf());
#endif
  int N, M;
  while (cin >> N >> M) {
    vec<interval_t, 2> intervals(N);
    for (int i = 0; i < M; i++) {
      int l, r, c;
      cin >> l >> r >> c;
      --l;
      --r;
      intervals[l].push_back({ r + 1, c });
    }
    vec<ll, 2> ed(N + 1);
    multiset<ll> minS;
    vector<ll> dp(N, INF);
    dp[0] = 0;
    for (int i = 0; i < N; i++) {
      for (ll x : ed[i]) {
        auto it = minS.find(x);
        minS.erase(it);
      }
      if (!minS.empty()) {
        dp[i] = *minS.begin();
      }
      for (auto& interval : intervals[i]) {
        ll cost = dp[i] + interval.w;
        ed[interval.to].push_back(cost);
        minS.insert(cost);
      }
    }
    ll res = dp[N - 1];
    cout << (res >= INF ? -1 : res) << endl;
  }
  return 0;
}

