#include <iostream>
#include <algorithm>

using namespace std;

const int NMAX = 1e5 + 5;
const long long INF = (1LL << 60);
struct Edge
{
	int left, right, cost;
};

int N, M;
Edge edges[NMAX];
long long aint[4 * NMAX], dist[NMAX];

int LeftSon(int node)
{
	return 2 * node;
}

int RightSon(int node)
{
	return 2 * node + 1;
}

void Build(int node, int left, int right)
{
	if (left == right)
	{
		aint[node] = INF;
		return;
	}
	int mid = (left + right) / 2;
	Build(LeftSon(node), left, mid);
	Build(RightSon(node), mid + 1, right);
	aint[node] = INF;
}

void Update(int node, int left, int right, int pos, long long val)
{
	if (left == right)
	{
		dist[pos] = val;
		aint[node] = val;
		return;
	}
	int mid = (left + right) / 2;
	if (pos <= mid)
		Update(LeftSon(node), left, mid, pos, val);
	else
		Update(RightSon(node), mid + 1, right, pos, val);
	aint[node] = min(aint[LeftSon(node)], aint[RightSon(node)]);
}

long long Query(int node, int left, int right, int LeftQuery, int RightQuery)
{
	if (LeftQuery <= left && right <= RightQuery)
		return aint[node];
	int mid = (left + right) / 2;
	long long ans = INF;
	if (LeftQuery <= mid)
		ans = min(ans, Query(LeftSon(node), left, mid, LeftQuery, RightQuery));
	if (RightQuery >= mid + 1)
		ans = min(ans, Query(RightSon(node), mid + 1, right, LeftQuery, RightQuery));
	return ans;
}

int main()
{
	cin >> N >> M;
	for (int i = 1;i <= N;++i)
		dist[i] = INF;
	Build(1, 1, N);
	dist[1] = 0;
	Update(1, 1, N, 1, 0);
	for (int i = 1;i <= M;++i)
		cin >> edges[i].left >> edges[i].right >> edges[i].cost;
	sort(edges + 1, edges + M + 1, [&](Edge x, Edge y)
	{
		if (x.right == y.right)
			return x.left < y.left;
		return x.right < y.right;
	});
	for (int i = 1;i <= M;++i)
	{
		dist[edges[i].right] = min(dist[edges[i].right], min(Query(1, 1, N, edges[i].left, edges[i].right) + edges[i].cost, INF));
		Update(1, 1, N, edges[i].right, dist[edges[i].right]);
	}
	long long answer = dist[N];
	if (dist[N] == INF)
		answer = -1;
	cout << answer << "\n";
	return 0;
}

