vi dijkstra(v(vp) &G,int V,int s) {
// G[f][i] = P(t,c) means that from `f` to `t` 's cost is `c` 
    vi d(V,INF);
    priority_queue<P,vp, greater<P>> que;
    d[s] = 0;
    que.push(P(0,s));
    while(!que.empty()) {
      P p = que.top();
      que.pop();
      int tar = p.second;
      if(d[tar] < p.first) continue;
      rep(i,sz(G[tar])) {
        P e = G[tar][i];
        if(d[e.first] > d[tar] + e.second) {
          d[e.first] = d[tar] + e.second;
          que.push(P(d[e.first],e.first));
        }
      }
    }
    return d;
  }

