        l[i]--; r[i]--;
    }
    std::vector<int> id(m);
    std::iota(id.begin(), id.end(), 0);
    std::sort(id.begin(), id.end(), [&](int i, int j) {
        return l[i] < l[j];
    });
    std::reverse(id.begin(), id.end());
    std::vector<long long> dist(n, 1e18);
    dist[0] = 0;
    std::priority_queue<
        std::pair<long long, int>,
        std::vector<std::pair<long long, int>>,
        std::greater<std::pair<long long, int>>> que;
    que.emplace(0, 0);
    while (!que.empty()) {
        int pos = que.top().second;
        que.pop();
        if (id.empty()) break;

        while (!id.empty() && l[id.back()] <= pos) {
            if (dist[r[id.back()]] <= dist[pos] + c[id.back()]) {
                id.pop_back();
                continue;
