const int INF = 1e14;
class SegTree {
  public:
    vector<int> t;
    vector<bool> marked;
    SegTree(int n) {
      t.assign(4 * n, INF);
      marked.assign(4 * n, INF);
    }

    void push(int v) {
      if (marked[v]) {
        if (t[v] < t[2 * v]) {
          marked[2 * v] = true;
          t[2 * v] = t[v];
        }
        if (t[v] < t[2 * v + 1]) {
          marked[2 * v + 1] = true;
          t[2 * v + 1] = t[v];
        }
        marked[v] = false;
      }
    }

    void update(int v, int tl, int tr, int l, int r, int val) {
      if (l > r) return;
      if (tl == l && tr == r) {
        if (val < t[v]) {
          marked[v] = true;
          t[v] = val;
        }
      } else {
        push(v);
        int tm = (tl + tr) / 2;
        update(2 * v, tl, tm, l, min(r, tm), val);
        update(2 * v + 1, tm  + 1, tr, max(tm + 1, l), r, val);
      }
    }

    int get(int v, int tl, int tr, int pos) {
      if (tl == tr) return t[v];
      push(v);
      int tm = (tl + tr) / 2;
      if (pos <= tm) {
        return get(2 * v, tl, tm, pos);
      } else {
        return get(2 * v + 1, tm + 1, tr, pos);
      }
    }
};

