};

int main() {

	ll n, m;
	std::cin >> n >> m;
	std::vector<Edge> edges(m);
	rep(i, m) {
		std::cin >> edges[i].l >> edges[i].r >> edges[i].c;
	}

	std::sort(allof(edges), [](Edge lhs, Edge rhs) {
		if (lhs.l == rhs.l) return lhs.c < rhs.c;
		return lhs.l < rhs.l;
		});


	// 各頂点に最小コストいくつで行けるか
	std::vector<ll> dp(n + 1, infll);

	dp[0] = 0LL;

	// なるべく奥に，の考え方で行く
	// 遠くしか考えない 先端しか見なくてよい

	// 下位互換を消したい
	Rep(i, 1, m) {
		if (edges[i].l == edges[i - 1].l) {
			if (edges[i].r < edges[i - 1].r) {
				edges[i].r = edges[i - 1].r;
			}
		}
	}

	// 自分より右に小さい数がいたらそっちを優先
	ll left = 0;
	for (ll i = 1; i <= n; ++i) {
		if (left == m) break;
		if (dp[i - 1] == infll) continue;

		while (i >= edges[left].l) {
			dp[edges[left].r - 1] = std::min(dp[edges[left].r - 1], dp[i - 1] + edges[left].c);
			++left;
			if (left == m) break;
		}
	}

	if (dp[n - 1] == infll) {
		std::cout << -1 << std::endl;
	}
	else std::cout << dp[n - 1] << std::endl;

	return 0;
}

