    path.emplace_back(l, r, c);
  }

  sort(all(path));

  // get min
  SegTree<ll> st(
    n, INF, [](ll a, ll b) { return min(a, b); }, [](ll prev_val, ll new_val) { return new_val; });

  st.update(0, 0);

  for (const auto& p : path) {
    ll l, r, c;
    l = get<0>(p);
    r = get<1>(p);
    c = get<2>(p);

    ll co = st.query(l, r);
    co += c;
    if (st[r] > co) {
      st.update(r, co);
    }
  }

  ll ans = st[n - 1];
