struct SegmentTree{
  ll size = 1;
  vector<ll> data;
  SegmentTree(ll n){
    while(size < n) size *= 2;
    data.assign(size * 2, LINF);
  }
  void update(ll at){
    while(at /= 2) data[at] = min(data[at * 2], data[at * 2 + 1]);
  }
  void set(ll at, ll val){
    at += size;
    data[at] = val;
    update(at);
  }
  ll get(ll l, ll r){
    l += size; r += size;
    ll ans = LINF;
    while(l < r){
      if(l & 1) chmin(ans, data[l++]);
      if(r & 1) chmin(ans, data[--r]);
      l /= 2; r /= 2;
    }
    return ans;
  }
  ll operator[](ll at){ return data[at + size]; }
  void _chmin(ll at, ll val){
    at += size;
    if(chmin(data[at], val)) update(at);
  }
};

