const int MAX_N = 101000;
const ll INF = 1LL << 50;

ll dist[MAX_N];

void Dijkstra(int v){
  //vが始点
  dist[v] = 0;
  priority_queue<P,vector<P>,greater<P>> Q;
  // {距離、ノード}の組みを保持
  Q.push({0,v});

  while(!Q.empty()){
    P p = Q.top();  Q.pop();
    ll load = p.first; int pos = p.second;

    for(auto next : to[pos]){ 
      int u = next.first; ll cost = next.second;
      if(dist[u] <= load+cost){ continue;} 
      else{ dist[u] = load+cost;

           Q.push({dist[u],u});
          }
    } // for-とじ
  }// whileとじ

  return ;
}


