#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll LINF = 0x1fffffffffffffff;
template<class T> bool chmin(T& a, const T& b){ if(a > b){ a = b; return 1; } return 0; }

struct SegmentTree{
  ll size = 1;
  vector<ll> data;
  SegmentTree(ll n){
    while(size < n) size *= 2;
    data.assign(size * 2, LINF);
  }
  void update(ll at){
    while(at /= 2) data[at] = min(data[at * 2], data[at * 2 + 1]);
  }
  void set(ll at, ll val){
    at += size;
    data[at] = val;
    update(at);
  }
  ll get(ll l, ll r){
    l += size; r += size;
    ll ans = LINF;
    while(l < r){
      if(l & 1) chmin(ans, data[l++]);
      if(r & 1) chmin(ans, data[--r]);
      l /= 2; r /= 2;
    }
    return ans;
  }
  ll operator[](ll at){ return data[at + size]; }
  void _chmin(ll at, ll val){
    at += size;
    if(::chmin(data[at], val)) update(at);
  }
};

int main(){
  ll n, m;
  cin >> n >> m;
  vector<array<ll, 3>> a(m);
  for(auto& i : a) for(auto& j : i) cin >> j;
  sort(a.begin(), a.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
  SegmentTree seg(n);
  seg.set(0, 0);
  for(auto i : a){
    i[0]--; i[1]--;
    seg._chmin(i[1], seg.get(i[0], i[1]) + i[2]);
  }
  if(seg[n - 1] == LINF) return puts("-1") & 0;
  cout << seg[n - 1] << endl;
}

