using namespace std;

#define MAXN 200000
typedef long long i64;
typedef pair<int,int> pi;

int n, m;

vector<pi> g[MAXN];
int dist[MAXN];

int input() {
	if (scanf("%d %d", &n, &m) < 0) return 0;
	for (int i=0; i<m; i++) {
		int x, y, z;
		scanf("%d %d %d", &x, &y, &z);
		x--, y--;
		g[x].push_back({y, z});
	}
	return 1;
}

void init() {
	for (int i=1; i<n; i++)
		g[i].push_back({i-1, 0});
}

void dijkstra(int source) {
	priority_queue<pi, vector<pi>, greater<pi>> q;
	for (int i=0; i<n; i++)
		dist[i] = INT_MAX;
	dist[source] = 0;
	q.push({0, source});
	while (!q.empty()) {
		pi x = q.top();
		q.pop();
		int d = x.first, u = x.second;
		if (d > dist[u])
			continue;
		for (auto &y: g[u]) {
			int v = y.first, w = y.second + d;
			if (w < dist[v]) {
				dist[v] = w;
				q.push({w, v});
			}
		}
	}
}

int solve() {
	dijkstra(0);
	return dist[n-1]==INT_MAX? -1: dist[n-1];
}

void output(int ans) {
	printf("%d\n", ans);
}

void cleanup() {
	for (int i=0; i<n; i++) g[i].clear();
}

int main() {
	//precalc();
	//int ca; scanf("%d", &ca);
	while (input()) {
		init();
		output(solve());
		cleanup();
		//break;
	}
}

