struct edge { int to; long long weight;};

struct range_edge_graph {
    int n;
    vector<vector<edge>> g;

    range_edge_graph(int n_) {
        n = 1;
        while (n < n_) n <<= 1;
        g.resize(4*n);
        for (int i = 1; i < n; ++i) {
            int c1 = i<<1|0, c2 = i<<1|1;
            g[i].push_back({c1, 0});
            g[i].push_back({c2, 0});
            g[c1+2*n].push_back({i+2*n, 0});
            g[c2+2*n].push_back({i+2*n, 0});
        }
        for (int i = n; i < 2*n; ++i) {
            g[i].push_back({i+2*n, 0});
        }
    }

    // from [l1, r1) to [l2, r2)
    void add_edge(int l1, int r1, int l2, int r2, int w) {
        int id = g.size();
        l1 += n, r1 += n;
        while (l1 < r1) {
            if (l1 & 1) g[l1+2*n].push_back({id, 0}), l1++;
            if (r1 & 1) --r1, g[r1+2*n].push_back({id, 0});
            l1 >>= 1, r1 >>= 1;
        }
        vector<edge> res;
        l2 += n, r2 += n;
        while (l2 < r2) {
            if (l2 & 1) res.push_back({l2, w}), l2++;
            if (r2 & 1) --r2, res.push_back({r2, w});
            l2 >>= 1, r2 >>= 1;
        }
        g.push_back(res);
    }
};

vector<long long> dijkstra(int s, vector<vector<edge>>& g) {
    vector<long long> dist(g.size(), numeric_limits<long long>::max());
    dist[s] = 0;
    using P = pair<long long, long long>;
    priority_queue<P, vector<P>, greater<P>> que;
    que.push(P(0, s));
    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if (dist[v] < p.first) continue;
        for (edge e : g[v]) {
            if (dist[e.to] > dist[v] + e.weight) {
                dist[e.to] = dist[v] + e.weight;
                que.push(P(dist[e.to], e.to));
            }
        }
    }
    return dist;
}

