int main() {

    int n, m;cin >> n >> m;
    /// firstがto secondがcost
    const ll INF = 100100100100;
    struct Edge {ll to; ll cost;};
    vector<Edge> g[n];


    rep(i,m) {
        ll l, r; cin >> l >> r;
        ll c; cin >> c;
        Edge edge1 = {r-1, c};
        g[l-1].push_back(edge1);
    }
    rep(i, n-1) {
        Edge edge = {i, 0};
        g[i+1].push_back(edge);
    }
    priority_queue<P, vector<P>, greater<P>> pq;
    //ll d[n];
    //fill(d, d + n, INF);
    vector<ll> d(n, INF);
    d[0] = 0;
    pq.push(P(0, 0));

    while(! pq.empty()){
        P p = pq.top(); pq.pop();
        int v = p.second;
        if (d[v] < p.first) continue;
        rep(i, g[v].size()) {
            auto e = g[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                pq.push(P(d[e.to], e.to));
            }
        }
    }

    ll ans = d[n-1];
    if (ans >= INF) ans = -1;
    cout << ans << endl;
}

