// 1-indexed
template <class T, class E>
struct SegmentTreeLaze {
  // a,b:T c,d:E e:E(unit)
  // g(f(a,b),c) = f(g(a,c),g(b,c))
  // g(g(a,c),d) = g(a,h(c,d))
  // g(a,e) = a
  typedef function<T(T, T)> F;
  typedef function<T(T, E)> G;
  typedef function<E(E, E)> H;
  int n, height;
  F f;
  G g;
  H h;
  T tunit;
  E eunit;
  vector<T> dat;
  vector<E> laz;
  SegmentTreeLaze(){};
  SegmentTreeLaze(int newn, F f, G g, H h, T nt, E ne)
      : f(f), g(g), h(h), tunit(nt), eunit(ne) {
    init(newn);
  }
  void init(int newn) {
    n = 1, height = 0;
    while(n < newn) n <<= 1, ++height;
    dat.assign(n << 1, tunit);
    laz.assign(n << 1, eunit);
  }

  inline T reflect(int k) {
    return laz[k] == eunit ? dat[k] : g(dat[k], laz[k]);
  }

  inline void eval(int k) {
    if(laz[k] == eunit) return;
    laz[k << 1] = h(laz[k << 1], laz[k]);
    laz[(k << 1) | 1] = h(laz[(k << 1) | 1], laz[k]);
    dat[k] = reflect(k);
    laz[k] = eunit;
  }

  inline void thrust(int k) {
    for(int i = height; i; --i) eval(k >> i);
  }

  void recalc(int k) {
    while(k >>= 1)
      dat[k] = f(reflect(k << 1), reflect((k << 1) | 1));
  }
  // [a,b)
  void update(int a, int b, E newdata) {
    thrust(a += n);
    thrust(b += n - 1);
    for(int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
      if(l & 1) laz[l] = h(laz[l], newdata), l++;
      if(r & 1) --r, laz[r] = h(laz[r], newdata);
    }
    recalc(a);
    recalc(b);
  }

  void set_val(int k, T newdata) {
    thrust(k += n);
    dat[k] = newdata;
    laz[k] = eunit;
    recalc(k);
  }

  // [a,b)
  T query(int a, int b) {
    thrust(a += n);
    thrust(b += n - 1);
    T vl = tunit, vr = tunit;
    for(int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
      if(l & 1) vl = f(vl, reflect(l++));
      if(r & 1) vr = f(reflect(--r), vr);
    }
    return f(vl, vr);
  }
};

struct data {
  long long l, r, c;
};
bool operator<(const data &l, const data &r) {
  if(l.l != r.l) return l.l < r.l;
  if(l.r != r.r) return l.r < r.r;
  return l.c < r.c;
};

long long n, m;
vector<data> v;

long long sovle();

int main() {
  cin >> n >> m;
  v.resize(m);
  for(int i = 0; i < m; ++i)
    cin >> v[i].l >> v[i].r >> v[i].c;
  sort(v.begin(), v.end());
  cout << sovle() << endl;
  return 0;
}

long long sovle() {
  auto f = [](long long l, long long r) {
    return min(l, r);
  };
  auto g = [](long long l, long long r) {
    return min(l, r);
  };
  auto h = [](long long l, long long r) {
    return min(l, r);
  };
  SegmentTreeLaze<long long, long long> seg(n + 2, f, g, h,
                                            inf, inf);
  seg.update(1, 2, 0);
  for(int i = 0; i < m; ++i) {
    long long now = seg.query(v[i].l, v[i].l + 1);
    if(now == inf) continue;
    now += v[i].c;
    seg.update(v[i].l, v[i].r + 1, now);
  }
  if(seg.query(n, n + 1) == inf) return -1;
  return seg.query(n, n + 1);
}

