struct seg{int l,r;ll ta;}t[N*4];
void build(int nu,int l,int r){
	t[nu].l=l;t[nu].r=r;
	if (l==r){if (l==1)t[nu].ta=0;else t[nu].ta=INF;}
	else{
		t[nu].ta=-1;build(nu*2,l,(l+r)/2);build(nu*2+1,(l+r)/2+1,r);
	}
}
void ya(int nu){
	if (t[nu].l==t[nu].r||t[nu].ta==-1) return ;
	t[nu*2].ta=t[nu].ta;t[nu*2+1].ta=t[nu].ta;
	t[nu].ta=-1;return ;
}
ll que(int nu,int x){
	ya(nu);
	if (t[nu].l==t[nu].r) return t[nu].ta;
	if (x<=(t[nu].l+t[nu].r)/2) return que(nu*2,x);else return que(nu*2+1,x);
}
void fu(int nu,int l,int r,ll x){
	ya(nu);
	if (t[nu].l==l&&t[nu].r==r){t[nu].ta=x;return ;}
	int mid=(t[nu].l+t[nu].r)/2;
	if (l<=mid) fu(nu*2,l,min(mid,r),x);
	if (r>mid) fu(nu*2+1,max(mid+1,l),r,x);
}
