			ll y=que(1,k.first);
			if (y>no+k.second){
				int l=i+1,r=k.first,mid;
				while (l<r){
					mid=(l+r)/2;
					if (que(1,mid)>no+k.second) r=mid;else l=mid+1;
				}
				fu(1,l,k.first,no+k.second);
			}
		}
	}
	if (que(1,n)==INF)puts("-1");else cout<<que(1,n)<<endl;
	return 0;
}

