void build(int id, int l, int r,int rt) {
    nod[id][rt] = ++ C;
    //printf("id = %d, l = %d, r = %d, rt = %d, C = %d\n", id, l, r, rt, C);
    if (l == r) {
        if (id == 0 && l == 1) s = nod[id][rt];
        if (id == 1 && l == n) t = nod[id][rt];
        if (id == 1) {
            g[ nod[id][rt] ].push_back( make_pair(nod[0][rt], 0) );
        }
        return;
    }
    int mid = (l + r) >> 1;
    build(id, l, mid, rt<<1);
    build(id, mid+1, r, rt<<1|1);
    if (id == 0) {
        g[nod[id][rt<<1]].push_back( make_pair(nod[id][rt], 0));
        g[nod[id][rt<<1|1]].push_back( make_pair(nod[id][rt], 0));
    } else {
        g[nod[id][rt]].push_back( make_pair(nod[id][rt<<1], 0));
        g[nod[id][rt]].push_back( make_pair(nod[id][rt<<1|1], 0));
    }
}
void split(int id, int to, int l, int r, int rt, int L, int R) {
    if (L <= l && r <= R) {
        if (id == 0){
            //printf("[%d, %d], id = %d, rt = %d\n", l, r, id, rt);
            //printf("link %d -> %d\n", nod[id][rt], to);
            g[ nod[id][rt] ].push_back(make_pair(to, 0));
        } else {
            //printf("@ [%d, %d], id = %d, rt = %d\n", l, r, id, rt);
            //printf("link %d -> %d\n", to, nod[id][rt]);
            g[to].push_back( make_pair(nod[id][rt], 0) );
        }
        return;
    }
    int mid = (l + r) >> 1;
    if (L <= mid) split(id, to, l, mid, rt<<1, L, R);
    if (R  > mid) split(id, to, mid+1, r, rt<<1|1, L, R);
}

