    while (q.size()) {
        Nod tmp = q.top(); q.pop();
        int u = tmp.u;
        //printf("u = %d, %d\n", u, tmp.dis);
        if (dis[u] < tmp.dis) continue;
        for (auto e: g[u]) {
            int v = e.first;
            if (dis[v] == -1 || dis[v] > dis[u] + e.second) {
                dis[v] = dis[u] + e.second;
                q.push((Nod){dis[v], v});
            }
        }
    }
    printf("%lld\n", dis[t]);
}

