void AddEdge(int u, int v, int w)
{
    static int c;

    x[++ c] = h[u];
    h[u] = c;
    ::v[c] = v;
    ::w[c] = w;

    return;
}

void InitSegment(int x, int l, int r)
{
    int m;

    if(l == r)
    {
        k[l] = x;

        return;
    }

    m = (l + r) >> 1;
    InitSegment(x << 1    , l    , m);
    InitSegment(x << 1 | 1, m + 1, r);
    AddEdge(x << 1    , x, 0);
    AddEdge(x << 1 | 1, x, 0);

    return;
}

void AddSegment(int x, int l, int r, int s, int t, int k, int w)
{
    int m;

    if(l > t || r < s)
        return;
    if(l >= s && r <= t)
    {
        AddEdge(x, k, w);

        return;
    }

    m = (l + r) >> 1;
    AddSegment(x << 1    , l    , m, s, t, k, w);
    AddSegment(x << 1 | 1, m + 1, r, s, t, k, w);

    return;
}

void InitSegwin(int n)
{
    int i;

    for(i = 0; i < n; i ++)
        f[i + n] = make_pair(LLONG_MAX >> 2, i);
    for(i = n - 1; i > 0; i --)
    {
        f[i].first = min(f[i << 1].first, f[i << 1 | 1].first);
        f[i].second = f[i << 1].first < f[i << 1 | 1].first ? f[i << 1].second : f[i << 1 | 1].second;
    }

    return;
}

void SetSegwin(int p, long long v, int n)
{
    for(f[p += n].first = v; p >>= 1; )
    {
        f[p].first = min(f[p << 1].first, f[p << 1 | 1].first);
        f[p].second = f[p << 1].first < f[p << 1 | 1].first ? f[p << 1].second : f[p << 1 | 1].second;
    }

    return;
}

