{
    int n, m, l, r, w;
    int i, t;

    scanf("%d %d", &n, &m);
    InitSegment(1, 1, n);
    while(m --)
    {
        scanf("%d %d %d", &l, &r, &w);
        AddSegment(1, 1, n, l, r - 1, k[r], w);
    }

    for(i = 0; i < (n << 2); i ++)
        d[i] = LLONG_MAX >> 2;
    InitSegwin(n << 2);
    d[k[1]] = 0;
    SetSegwin(k[1], 0, n << 2);

    while(f[1].first != LLONG_MAX >> 2)
    {
        t = f[1].second;
        // printf("%d %lld %lld\n", t, d[t], f[1].first);
        SetSegwin(t, LLONG_MAX >> 2, n << 2);
        for(i = h[t]; i; i = x[i])
            if(d[v[i]] > d[t] + ::w[i])
            {
                d[v[i]] = d[t] + ::w[i];
                SetSegwin(v[i], d[v[i]], n << 2);
            }
    }
    printf("%lld\n", d[k[n]] == LLONG_MAX >> 2 ? -1 : d[k[n]]);

    return 0;
}

