        unit = unit_;
        rep(i,2*SEG_N) dat[i] = unit;
    }

    T get(int k){
        k += SEG_N-1;
        T ret = dat[k];
        while(k > 0){
            k = (k-1)/2;
            ret = min(ret, dat[k]);
        }
