    if(dist[v]<now.fi) continue;
    for(auto itr:g[v]){
      if(dist[itr.fi]>dist[v]+itr.se){
        dist[itr.fi]=dist[v]+itr.se;
        que.push(P(dist[itr.fi],itr.fi));
      }
    }
  }
  cout<<(dist[n-1]!=inf ? dist[n-1]:-1)<<endl;
}

