struct segtree {
    int N;
    vector<i64> dat, sum;
    segtree(int n) {
        N = 1;
        while(N < n) N <<= 1;
        dat.assign(2*N-1,1ll << 60);
        sum.assign(2*N-1,1ll << 60);
    }
    void add(int a, int b, i64 x) { add(a,b,x,0,0,N); }
    i64 add(int a, int b, i64 x, int k, int l, int r) {
        if(b <= l or r <= a) return dat[k];
        if(a <= l and r <= b) {
            sum[k] = min(sum[k], x);
            return dat[k] = min(dat[k], x);
        }
        int m = (l+r)/2;
        return dat[k] = min(min(add(a,b,x,2*k+1,l,m),add(a,b,x,2*k+2,m,r)),sum[k]);
    }
    i64 minimum(int a, int b) { return minimum(a,b,0,0,N); }
    i64 minimum(int a, int b, int k, int l, int r) {
        if(b <= l or r <= a) return 1ll << 60;
        if(a <= l and r <= b) return dat[k];
        int m = (l+r)/2;
        return min(min(minimum(a,b,2*k+1,l,m),minimum(a,b,2*k+2,m,r)),sum[k]);
    }
};


