const LL INF = 0x3f3f3f3f;
const LL maxn = 1e5 + 7;
const LL mod = 1e9 + 7;

struct Edge {
    LL v,cost;
    Edge(LL _v = 0 , LL _cost = 0) : v(_v),cost(_cost){}
};

vector<Edge>edge[maxn];

void addedge(LL u,LL v,LL cost) {
    edge[u].push_back(Edge(v,cost));
}

struct node {
    LL v,cost;
    node(LL _v = 0 , LL _cost = 0) : v(_v),cost(_cost){}
    bool operator < (const node &r) const {
        return cost > r.cost;
    }
};

LL dist[maxn];
bool vis[maxn];
priority_queue<node>pq;

void Dijkstra(LL n,LL start) {
    memset(vis,false,sizeof(vis));
    for(LL i = 0 ; i < n ; i++) dist[i] = INF;
    dist[start] = 0;
    while(!pq.empty()) pq.pop();
    pq.push(node(start,0));
    node k;
    while(!pq.empty()) {
        k = pq.top();
        pq.pop();
        LL u = k.v;
        if(vis[u]) continue;
        vis[u] = true;
        for(LL i = 0 ; i < edge[u].size() ; i++) {
            LL v = edge[u][i].v;
            LL cost = edge[u][i].cost;
            if(!vis[v] && dist[v] > dist[u] + cost) {
                dist[v] = dist[u] + cost;
                pq.push(node(v,dist[v]));
            }
        }
    }
}

