    LL n,m;
    while(~scanf("%lld%lld",&n,&m)) {
        for(LL i = 0 ; i <= n ; i++) {
            edge[i].clear();
        }
        for(LL i = 1 ; i < n ; i++) {
            addedge(i,i-1,0);
        }
        for(LL i = 1 ; i <= m ; i++) {
            LL u,v,w;
            scanf("%lld%lld%lld",&u,&v,&w);
            u--,v--;
            addedge(u,v,w);
        }
        Dijkstra(n,0);
        if(dist[n-1] == INF) dist[n-1] = -1;
        printf("%lld\n",dist[n-1]);
    }
    return 0;
}

