int n, m;
priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
int dp[100000 + 5];
signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> n >> m;
  vector<vector<pii>> RC(n);
  rep(i, n) dp[i] = INFLL;
  rep(i, m) {
    int l, r, c;
    cin >> l >> r >> c;
    l--; r--;
    RC[l].push_back({r, c});
  }
  dp[0] = 0;
  rep2(i, 1, n) {
    if ((int)RC[i-1].size() != 0) {
      for (auto p : RC[i-1]) {
        int r = p.fi;
        int c = p.se;
        pq.push({dp[i-1]+c, r});
      }
    }
    if (pq.empty()) break;
    dp[i] = pq.top().fi;
    while (!pq.empty() && pq.top().se <= i) {
      pq.pop();
    }
  }
  if (dp[n-1] == INFLL) cout << -1 << endl;
  else cout << dp[n-1] << endl;
}

