// adjacency list (weighted graph)
template<class T> struct GraphL {
  using size_t = std::size_t;
  struct E {
    size_t to; T w;
    E(size_t to) : to(to), w() {}
    E(size_t to, T w) : to(to), w(w) {}
  };
  size_t n; std::vector<std::vector<E>> dat;
  GraphL() {}
  GraphL(size_t n) : n(n), dat(n) {}
  void init(size_t n) { this->n = n; dat.assign(n, std::vector<E>()); }
  auto& operator[](size_t i) { return dat[i]; }
  auto& operator[](size_t i) const { return dat[i]; }
  auto begin() { return dat.begin(); }
  auto begin() const { return dat.begin(); }
  auto end() { return dat.end(); }
  auto end() const { return dat.end(); }
  size_t size() const { return n; }
  void de(size_t i, size_t j, T t) { dat[i].push_back(E(j, t)); }
  void e(size_t i, size_t j, T t) { de(i, j, t); de(j, i, t); }
  friend std::ostream& operator<<(std::ostream& os, GraphL const& g) {
    for(size_t i=0;i<g.size();++i) {
      os << i+1 << " -->";
      for(size_t j=0;j<g[i].size();++j)
        os << ' ' << g[i][j].to+1 << '(' << g[i][j].w << ')';
      if(i+1 < g.size()) os << '\n';
    }
    return os;
  }
};

template<class U, class T, class Cp=std::less<>, class Op=std::plus<>>
auto dijkstra(GraphL<T> const& g, std::size_t s, U u, Cp cp=Cp(), Op op=Op()) {
  using pr = std::pair<U, std::size_t>;
  std::vector<optional<U>> r(g.size());
  const auto f = [cp](pr const& p, pr const& q) -> bool { return cp(q.first, p.first); };
  std::priority_queue<pr, std::vector<pr>, decltype(f)> que(f);
  que.emplace(*(r[s]=u), s);
  while(!que.empty()) {
    U w; std::size_t v; std::tie(w, v) = que.top(); que.pop();
    if(r[v] && cp(*r[v], w)) continue;
    for(auto const& e : g[v]) {
      U nw = op(w, e.w);
      if(!r[e.to] || cp(nw, *r[e.to])) que.emplace(*(r[e.to]=nw), e.to);
    }
  }
  return r;
}

