const ll inf=0x1212121212121212ll;
ll n,m,i,j;
ll mi[400005],tag[400005];
struct eee
{
	ll l,r,c;
}a[100005];
bool cmp(eee x,eee y){return x.l<y.l;}
void build(ll x,ll l,ll r)
{
	tag[x]=inf;
	if(l==r){if(l==1)mi[x]=0;else mi[x]=inf;return;}
	int mid=(l+r)/2;build(x+x,l,mid);build(x+x+1,mid+1,r);
	mi[x]=min(mi[x+x],mi[x+x+1]);
}
void upd(ll x,ll y)
{
	mi[x]=min(mi[x],y);
	tag[x]=min(tag[x],y);
}
void pushdo(ll x)
{
	if(tag[x]!=inf){
		upd(x+x,tag[x]);
		upd(x+x+1,tag[x]);
		tag[x]=inf;
	}
}
void update(ll x,ll l,ll r,ll ql,ll qr,ll c)
{
	if(ql<=l&&r<=qr){upd(x,c);return;}
	int mid=(l+r)/2;pushdo(x);
	if(ql<=mid)update(x+x,l,mid,ql,qr,c);
	if(qr>mid)update(x+x+1,mid+1,r,ql,qr,c);
	mi[x]=min(mi[x+x],mi[x+x+1]);
}
ll query(ll x,ll l,ll r,ll ql,ll qr)
{
	if(ql<=l&&r<=qr)return mi[x];
	int mid=(l+r)/2;pushdo(x);
	if(qr<=mid)return query(x+x,l,mid,ql,qr);
	if(ql>mid)return query(x+x+1,mid+1,r,ql,qr);
	return min(query(x+x,l,mid,ql,qr),query(x+x+1,mid+1,r,ql,qr));
}
