	rep(i,m){scanf("%lld%lld%lld",&a[i].l,&a[i].r,&a[i].c);}
	sort(a+1,a+m+1,cmp);build(1,1,n);
	rep(i,m){
		update(1,1,n,a[i].l,a[i].r,query(1,1,n,a[i].l,a[i].r)+a[i].c);
	}
	ll ans=query(1,1,n,n,n);
	if(ans==inf) puts("-1");else printf("%lld\n",ans);
	return 0;
}

