Value connect(Value al,const Value ar){
	return min(al,ar);
}
Value dat[400001];
struct segtree {
	int N;

	segtree() {}

	segtree(int n)  {
		N = 1;
		while (N < n) N *= 2;

		for(int x=0;x<N;++x){

			dat[x+N-1] = ini;

		}
		for(int x=N-2;x>=0;--x){
			dat[x]=connect(dat[x*2+1],dat[x*2+2]);
		}
	}
	// update k th element
	void update(int k,const Value& a) {
		 k += N - 1;
		dat[k] = a;

		while (k > 0) {
			k = (k - 1) >>1;
			dat[k]=connect(dat[k * 2 + 1],dat[k * 2 + 2]);
		}
	}
	// min [a, b)
	Value  query(int a, int b) { return query(a, b, 0, 0, N); }
	Value  query(int a, int b, int k, int l, int r) {
		if (r <= a or b <= l) return ini;
		if (a <= l and r <= b) return dat[k];
		const int m = (l + r) / 2;
		return connect(query(a, b, k * 2 + 1, l, m),query(a, b, k * 2 + 2, m, r));
	}


};

int main() {
	ios::sync_with_stdio(false);
	int N,M;cin>>N>>M;
	vector<pair<int,pair<int,ll>>>qs;
	for(int i=0;i<M;++i){
		int l,r;ll c;
		cin>>l>>r>>c;
		qs.push_back(make_pair(l-1,make_pair(r,c)));
	}
	sort(qs.begin(),qs.end());
	segtree seg(N);
	seg.update(0,0);
	for(int i=0;i<M;++i){
		int l=qs[i].first;
		int r=qs[i].second.first;
		ll c=qs[i].second.second;
		ll amin=seg.query(l,r-1);
		seg.update(r-1,min(seg.query(r-1,r),amin+c));
	}
	ll answer=seg.query(N-1,N);
	if(answer>=ll(1e17))answer=-1;
	cout<<answer<<endl;
	return 0;
}

