int main() {
    ll n, m;
    cin >> n >> m;

    vvpll G(n);
    rep(v, n-1) {
        G[v].pb(make_pair(v+1, 0));
        G[v+1].pb(make_pair(v, 0));
    }
    rep(loop, m) {
        ll L, R, c;
        cin >> L >> R >> c;
        L--;  R--;
        G[L].pb(make_pair(R, c));
        G[R].pb(make_pair(L, c));
    }

    // ダイクストラ法。計算量はO((V+E)*log(V))
    const ll sv = 0;  // 始点となる頂点。デフォルトでは0
    vl dist(n, INF);  // dist[v] : 頂点svから頂点vへの最短距離
    priority_queue<P, vector<P>, greater<P>> prQ;
    dist[sv] = 0;
    prQ.push(make_pair(sv, 0));  // (頂点番号, 頂点svからの最短距離)
    while(!prQ.empty()) {
        auto p = prQ.top();
        prQ.pop();
        ll v = p.first;
        if(dist[v] < p.second) {
            continue;
        }
        for(auto pp : G[v]) {
            ll u = pp.first;
            ll cost = pp.second;
            if(dist[u] > dist[v] + cost) {
                dist[u] = dist[v] + cost;
                prQ.push(make_pair(u, dist[u]));
            }
        }
    }

    out(dist[n-1]);
    re0;
}

