ll getmin(int l, int r) {
    ll ans = 1e15;
    while (r - l > 1) {
        if (l % 2 == 0)
            ans = min(ans, tr[l + 1]);
        if (r % 2 == 1)
            ans = min(ans, tr[r - 1]);
        l >>= 1, r >>= 1;
    }
    return ans;
}

