class segtree {
    int n = 1; VL dat;
#define def LLINF
public:
    segtree(int _n) {
        while (n < _n)n *= 2;
        dat.resize(2 * n - 1, def);
    }
    segtree(VL a) {
        int _n = a.size();
        while (n < _n)n *= 2;
        dat.resize(2 * n - 1, def);
        FOR(i, 0, _n)dat[i + n - 1] = a[i];
        rFOR(i, 0, n - 1)dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);
    }
    void Chmin(int i, ll a) {
        i += n - 1;
        if (!chmin(dat[i], a))return;
        while (i > 0) {
            --i /= 2;
            dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }
    ll Min(int a, int b, int k, int l, int r) {
        if (b <= l || r <= a)return def;
        if (a <= l && r <= b)return dat[k];
        ll s = Min(a, b, 2 * k + 1, l, (l + r) / 2);
        ll t = Min(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(s, t);
    }
