constexpr ll INF = 1e18;

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int N,M; cin>>N>>M;
  struct Node {
    int p; ll c;
    Node(int p, ll c) : p(p), c(c) {}
    bool operator>(const Node& x) const {return c > x.c;}
  };
  vector<Node> graph[N];
  for (int i = N-1; i > 0; i--)
    graph[i].emplace_back(i-1, 0);
  for (int i = 0; i < M; i++) {
    int l,r,c; cin>>l>>r>>c;
    l--; r--;
    graph[l].emplace_back(r,c);
  }
  auto dijkstra = [&]() {
    priority_queue<Node, vector<Node>, greater<>> qs;
    vector<ll> dis(N, INF);
    qs.emplace(0, 0);
    while (not qs.empty()) {
      Node q = qs.top(); qs.pop();
      if (dis[q.p] < q.c)
        continue;
      for (Node t : graph[q.p]) {
        auto c = q.c+t.c;
        if (dis[t.p] <= c)
          continue;
        dis[t.p] = c;
        if (t.p < N-1)
          qs.emplace(t.p, c);
      }
    }
    return dis[N-1];
  };
  auto ans = dijkstra();
  cout << (ans==INF?-1:ans) << endl;

  return 0;
}

