constexpr auto INF = LIM< LL >::max() / 2;

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	IN( int, N, M );

	VT< VPII > G( N );
	REP( M )
	{
		IN( int, L, R, C );
		--L, --R;
		G[L].EB( R, C );
// 		cout << L << ' ' << R << ' ' << C << endl;
	}
	REP( i, N - 1 )
	{
		G[ i + 1 ].EB( i, 0 );
// 		cout << i + 1 << ' ' << i << ' ' << 0 << endl;
	}

	VT< LL > distances( N, INF );
	distances[0] = 0;

	priority_queue< pair< LL, int >, VT< pair< LL, int > >, greater< pair< LL, int > > > que;
	que.EM( 0, 0 );

	while ( !que.empty() )
	{
		const LL d = que.top().fst;
		const int u = que.top().snd;
		que.pop();

		if ( distances[u] < d )
		{
			continue;
		}

		FOR( e, G[u] )
		{
			const int v = e.fst;
			const int c = e.snd;

			if ( chmin( distances[v], distances[u] + c ) )
			{
				que.EM( distances[u] + c, v );
			}
		}
	}

	const LL res = distances.back();
	cout << ( res == INF ? -1 : res ) << endl;

	return 0;
}

