struct edge {
  ll to, cost;
};

typedef pair<ll, ll> P;

int main() {
  int N, M;
  cin >> N >> M;

  vector<edge> G[N];
  rep0(i, M) {
    ll l, r, c;
    cin >> l >> r >> c;
    l--, r--;
    edge e;
    e.to = r, e.cost = c;
    G[l].push_back(e);
  }
  rep0(i, N - 1) {
    edge e;
    e.to = i, e.cost = 0;
    G[i + 1].push_back(e);
  }


  priority_queue< P, vector<P>, greater<P> > q;
  vector<ll> d(N, 1e9);
