    for(auto e: G[v]) {
      if(d[e.to] > d[v] + e.cost) {
          d[e.to] = d[v] + e.cost;
          q.push(P(d[e.to], e.to));
      }
    }
  }

  if(d[N - 1] >= 1e9) d[N - 1] = -1;
