using lli = long long int;

void solve(long long n, long long m, std::vector<long long> L,
           std::vector<long long> R, std::vector<long long> C) {
  lli inf = 1e18;

  using p = tuple<lli, lli, lli>;
  vector<vector<p>> ma(n+10);

  // cost, right check right
  vector<lli> dist(n + 10, inf);

  dist[0] = 0;
  priority_queue<p, vector<p>, greater<p>> que;
  rep(i, m) ma[L[i]].push_back(make_tuple(C[i], -R[i], i));
  lli frontier = 0;
  for(auto s:ma[0]){
       que.push(s);
  }

  rep(i, n){
    for(auto s:ma[i]){
       que.push(s);
    }
    lli a,b,c;
    while(!que.empty()){
      auto s = que.top();
      que.pop();
      tie(a,b,c) = s;
      if(R[c] > i){
        que.push(s);
        break;
      }
    }

    if(que.empty()) continue;
    auto f = que.top();

      tie(a,b,c) = f;
    lli right = R[c];
    // cerr << i << " " << f.first << " " << f.second << endl;
    for(int j = frontier ;j<= right;j++){
      // for(auto s:ma[j]){
      //  ena[j].push_back(s);
      // }
      dist[j] = min(dist[L[c]] + a, dist[j]);
    }
    frontier = max(frontier, right);
  }
  cout << ((dist[n-1] >= inf) ? -1 : dist[n-1]) << endl;
}

