const ll INF=1LL<<60;

int n;
ll dat[2*MAX-1],lazy[2*MAX-1];
bool done[2*MAX-1];//0なら評価済み

void init(int n_){
    n=1;
    while(n<n_) n*=2;
    for(int i=0;i<2*n-1;i++){
        dat[i]=INF;
        lazy[i]=INF;
    }
}

void eval(int k,int l,int r){
    if(done[k]==0) return;

    dat[k]=min(dat[k],lazy[k]);

    if(r-l>1){
        lazy[k*2+1]=lazy[k];
        lazy[k*2+2]=lazy[k];
        done[k*2+1]=done[k*2+2]=1;
    }

    done[k]=0;
}

void update(int a,int b,ll x,int k,int l,int r){
    eval(k,l,r);

    if(r<=a||b<=l) return;

    if(a<=l&&r<=b){
        lazy[k]=min(lazy[k],x);
        done[k]=1;
        eval(k,l,r);
    }

    else{
        update(a,b,x,2*k+1,l,(l+r)/2);
        update(a,b,x,2*k+2,(l+r)/2,r);
        dat[k]=min(dat[2*k+1],dat[2*k+2]);
    }
}

ll query(int a,int b,int k,int l,int r){

    eval(k,l,r);

    if(r<=a||b<=l) return INF;
    if(a<=l&&r<=b) return dat[k];

    ll vl=query(a,b,2*k+1,l,(l+r)/2);
    ll vr=query(a,b,2*k+2,(l+r)/2,r);
    return min(vl,vr);
}

