void dijkstra(int s){
    fill(d,d+V+1,LLINF);
    priority_queue<P,vector<P>,greater<P> > q;
    d[s]=0;
    q.push(P(0ll,s));
    while(!q.empty()){
        P a=q.top();
        q.pop();
        if(d[a.sec]<a.fi)continue;
        for(int i=0;i<g[a.sec].size();i++){
            edge e=g[a.sec][i];
            if(d[e.to]>d[a.sec]+e.cost){
                d[e.to]=d[a.sec]+e.cost;
                q.push(P(d[e.to],e.to));
            }
        }
    }
    return;
}
