void add(int a, int b, int k, int l, int r, llint s, llint c)
{
	if(b < l || r < a) return;
	if(a <= l && r <= b){
		G[S+s].push_back(edge(k, c));
		return;
	}
	add(a, b, k*2, l, (l+r)/2, s, c);
	add(a, b, k*2+1, (l+r)/2+1, r, s, c);
}
