struct UnionFind{
    vector<int> par,sizes;
    UnionFind(int n):par(n+1),sizes(n+1,1){
        rep2(i,1,n)par[i]=i;
    }
    int find(int x){
        return (x==par[x]?x:par[x]=find(par[x]));
    }
    void unite(int x,int y){
        x=find(x);y=find(y);
        if(x==y)return ;
        if(sizes[x]<sizes[y]){
            swap(x,y);
        }
        par[y]=x;
        sizes[x]+=sizes[y];
    }
    bool same(int x,int y) {return (find(x)==find(y));}
    int size(int x) {return sizes[find(x)];}
};
int solve_min(vector<pii> G,int n){
    UnionFind uf(n);
    for(auto e:G){
        uf.unite(e.first,e.second);
    }
    int cnt=0;
    rep2(i,1,n){
        if(uf.par[i]==i)cnt++;
    }
    return cnt-1;
}

