void dijkstra() {
  d[0] = 0;
  priority_queue<Edge> pq;
  pq.push({0, 0});
  while (!pq.empty()) {
    int v = pq.top().t;
    pq.pop();
    for (Edge e: G[v]) {
      ll u = e.t, c = e.c;
      if (chmin(d[u], d[v] + c)) {
        pq.push(e);
      }
    }
  }
}

