const long long inf = 1e9+7;
class Dijkstra{
    private:
        static const int INF = 1e9+7;
        vector<vector<pair<long long,int>>> graph; //pair<cost,next_path>
        vector<long long> total_cost;
        vector<vector<int>>  shortest_path;

    public:

        Dijkstra(vector<vector<pair<long long,int>>> graph,int start,int size,bool path_check = false){
            priority_queue<
                pair<long long,int>,
                vector<pair<long long,int>>,
                greater<pair<long long,int>>> q;
            vector<long long> cost(size,INF);
            vector<vector<int>> path(size);
            if(path_check)for(int i=0;i<size;i++) path[i].push_back(i);//自分は必ず通る
            cost[start] = 0;
            q.push(make_pair(0ll,start));
            while (!q.empty()){
                auto now = q.top();
                q.pop();
                int prev = now.second;
                if(cost[prev] < now.first) continue;
                for (auto next : graph[prev]){
                    if (cost[next.second] <= cost[prev] + next.first) continue;
                    cost[next.second] = cost[prev] + next.first;
                    //先頭からpathを追加
                    if(path_check) path[next.second].insert(path[next.second].begin(),path[now.second].begin(),path[now.second].end()); 
                    q.push(next);
                }
            }
            total_cost = cost;
            if(path_check) shortest_path = path;
        }
        vector<long long> get_cost(){ return total_cost; }
        vector<vector<int>> get_path(){ return shortest_path; }
};

