const long double PI=3.141592653589793238462643383279;
const int N=500005,M=998244353;
int n,i,m,s[N],d,j,head[100005],Next[200005],adj[200005],l,r,c,leng[200005],k;
long long lazy[N*4];
void modify(int i,int l,int r,int ll,int rr,long long y)
{
	if(l>=ll&&r<=rr)
	{
		lazy[i]=min(lazy[i],y);
		return;
	}
	int mid=l+r>>1;
	if(mid>=ll)
		modify(i<<1,l,mid,ll,rr,y);
	if(mid<rr)
		modify(i<<1|1,mid+1,r,ll,rr,y);
}
long long Query(int i,int l,int r,int x)
{
	if(l==r)
		return lazy[i];
	int mid=l+r>>1;
	if(mid>=x)
		return min(Query(i<<1,l,mid,x),lazy[i]);
	else
		return min(Query(i<<1|1,mid+1,r,x),lazy[i]);
}
void Push(int u,int v,int c)
{
	Next[++k]=head[u];
	head[u]=k;
	adj[k]=v;
	leng[k]=c;
}
int main()
{
	scanf("%d %d",&n,&m);
	for(i=0;i<N;++i)
		lazy[i]=100000000000000000ll;
	modify(1,1,n,1,1,0);
	for(i=1;i<=m;++i)
	{
		scanf("%d %d %d",&l,&r,&c);
		Push(l,r,c);
	}
	for(i=1;i<n;++i)
	{
		long long u=Query(1,1,n,i); 
		for(j=head[i];j!=0;j=Next[j])
			modify(1,1,n,i+1,adj[j],u+leng[j]);
	}
	long long u=Query(1,1,n,n);
	if(u>=100000000000000000ll)
		puts("-1");
	else
		cout<<u;
}

