      g[i].EB(2*i,0);
      g[i].EB(2*i+1,0);
      if(2*i<sz){
        g[2*i+2*sz].EB(i+2*sz,0);
        g[2*i+1+2*sz].EB(i+2*sz,0);
      }
      else{
