const int N = 100005;

int n, m, id[N];

struct Graph {
	static const int N = 500005;
	static const long long INF = 0x3f3f3f3f3f3f3f3fll;

	std::vector<std::pair<int, int>> E[N];
	bool vis[N];
	long long dis[N];

	void addEdge(int u, int v, int w) {
		E[u].push_back({v, w});
	}

	long long Dijkstra(int n, int s, int t) {
		for (int i = 1; i <= n; ++i) {
			vis[i] = 0;
			dis[i] = INF;
		}
		std::priority_queue<std::pair<long long, int>> Q;
		dis[s] = 0, Q.push({0, s});
		while (!Q.empty()) {
			int u = Q.top().second;
			Q.pop();
			if (vis[u]) {
				continue;
			}
			vis[u] = 1;
			for (auto p : E[u]) {
				int v = p.first, w = p.second;
				if (dis[v] > dis[u] + w) {
					dis[v] = dis[u] + w;
					Q.push({-dis[v], v});
				}
			}
		}
		return dis[t];
	}
} G;

struct SegmentTree {
	int rt, cnt;
	int ls[N << 1], rs[N << 1];

	void build(int &u, int l, int r) {
		u = ++cnt, ls[u] = rs[u] = 0;
		if (l == r) {
			id[l] = u;
			return;
		}
		int md = (l + r) >> 1;
		build(ls[u], l, md), build(rs[u], md + 1, r);
		G.addEdge(ls[u], u, 0), G.addEdge(rs[u], u, 0);
	}

	void link(int u, int l, int r, int L, int R, int t, int w) {
		if (L <= l && r <= R) {
			G.addEdge(u, t, w);
			G.addEdge(t, u + cnt, w);
			return;
		}
		int md = (l + r) >> 1;
		if (L <= md) {
			link(ls[u], l, md, L, R, t, w);
		}
		if (R > md) {
			link(rs[u], md + 1, r, L, R, t, w);
		}
	}
} T;

int main() {
	read(n), read(m);
	T.build(T.rt, 1, n);
	int cnt = T.cnt;
	for (int i = 1; i <= cnt; ++i) {
		if (T.ls[i] && T.rs[i]) {
			G.addEdge(i + cnt, T.ls[i] + cnt, 0);
			G.addEdge(i + cnt, T.rs[i] + cnt, 0);
		}
	}
	for (int i = 1; i <= n; ++i) {
		G.addEdge(id[i] + cnt, id[i], 0);
	}
	cnt *= 2;
	for (int i = 1; i <= m; ++i) {
		int l, r, w;
		read(l), read(r), read(w);
		++cnt;
		T.link(T.rt, 1, n, l, r, cnt, w);
	}
	long long ans = G.Dijkstra(cnt, id[1], id[n] + T.cnt);
	if (ans == G.INF) {
		print(-1);
	} else {
		print(ans / 2);
	}
}

