const double EPS = 1e-6;
const double PI = 3.14159265358979;

int N, M;
vii reach[MAX];
vl memo(MAX,-1);
set<int> beg;
ll pd(int i){
	if(i == N) return 0LL;
	if(memo[i] != -1LL) return memo[i];
	ll total = INF;
	int mn = i;
	for(int j = 0; j < sz(reach[i]); j++){
		ll C = reach[i][j].f;
		int R = reach[i][j].s;

		if(mn >= R) continue;

		set<int>::iterator ns = beg.lower_bound(mn+1);
		set<int>::iterator ne = beg.upper_bound(R);
		mn = R;
		for(; ns != ne; ns++){
			total = min(total, C + pd(*ns));
		}
	}
	return memo[i] = total;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> M;
	while(M--){
		int Li, Ri, Ci;
		cin >> Li >> Ri >> Ci;
		reach[Li].pb(ii(Ci,Ri));
		beg.insert(Li);
		if(Ri == N) beg.insert(N);
	}

	for(int i = 1; i <= N; i++){
		if(sz(reach[i])){
			sort(reach[i].begin(), reach[i].end());
		}	
		/*
		cout << "i: " << i << endl;
		for(int j = 0; j < sz(reach[i]); j++){
			cout << " C: " << reach[i][j].f << " R: " << reach[i][j].s << endl;		
		}*/
	}

	ll total = pd(1);
	if(total >= INF){
		cout << -1 << endl;	
	}
	else {
		cout << total << endl;
	}

	return 0;
}

