using namespace std;
typedef long long ll;
typedef pair<int, int> P;

const ll INF = 1e18;

ll dijkstra(int N, int s, int g, vector<vector<ll>> cost){

	vector<ll> d(N+1, INF);
	vector<bool> used(N+1, false);
	vector<int> back(N+1, -1);

    fill(d.begin(), d.end(), INF);
    fill(used.begin(), used.end(), false);
    fill(back.begin(), back.end(), -1);
    d[s] = 0;

    while(true){
        int v = -1;
        for(int u=0; u < N + 1; u++){
            if(!used[u] && (v == -1 || d[u] < d[v])) v = u;
        }

        if(v == -1) break;

        used[v] = true;

        for(int u = 0; u < N + 1; u++){
            if(d[u] > d[v] + cost[v][u]){
                d[u] = d[v] + cost[v][u];
                back[u] = v;
            }
        }
    }

	return d[g];
}

int main(){
