	vector<int > Rs(M);
	vector<int > Cs(M);
	vector<vector <int> > mat_E(N,vector<int>(N,INF) );

	for (int mi = 0; mi < M; mi++) {
		cin >> Ls[mi] >> Rs[mi] >> Cs[mi];
		Ls[mi]--;
		Rs[mi]--;
	}

	for (int mi = 0; mi < M; mi++) {
		for (int li = Ls[mi]; li < Rs[mi]; li++) {
			for (int ri = li + 1; ri <= Rs[mi]; ri++) {
				if (Cs[mi] < mat_E[li][ri]) {
					mat_E[li][ri] = Cs[mi];
					mat_E[ri][li] = Cs[mi];
				}
			}
		}
	}

	vector<long long> dis(N,INF);
	priority_queue< P, vector<P>, greater<P> > que;

	dis[0] = 0;
	for(int ni = 0; ni < N; ni++){
		if(mat_E[0][ni] != INF){
			que.push(P(mat_E[0][ni],ni));
		}
	}

	P to;
	while(!que.empty()){
		to = que.top();
		que.pop();
		if (to.first < dis[to.second]) {
			dis[to.second] = to.first;
			for (int ni = 0; ni < N; ni++) {
				if (mat_E[to.second][ni] != INF && dis[ni] == INF) {
					que.push(P(dis[to.second] + mat_E[to.second][ni], ni));
				}
			}
		}
	}

