            if (lewa[d]>b || prawa[d]<a) return INF;
            if (lewa[d]==a && prawa[d]==b) return W[d];
            return min(w[d], min(query (a,min(b,prawa[2*d]),2*d), query (max(a,lewa[2*d+1]),b,2*d+1)));
}

