bool reach(const V<t3> &lrclist, ll n, ll m) {
    ll v = 1LL;

    for (auto lrc : lrclist) {
        ll left = get<0>(lrc);
        ll right = get<1>(lrc);
        debug_printf("left=%lld right=%lld\n", left, right);
        if (left > v) return false;
        v = max(v, right);
    }

    debug_printf("v=%lld n=%lld\n", v, n);
    return (v == n);
}

void makelink(V<t2> linklist[], const V<t3> &lrclist, ll n)
{
    srep (i, 1, n) linklist[i+1].pb(t2(i, 0LL));
    for (auto lrc : lrclist) {
        ll left = get<0>(lrc);
        ll right = get<1>(lrc);
        ll cost = get<2>(lrc);
        linklist[left].pb(t2(right, cost));
    }
}

