struct range_edge_graph {
    int n;
    struct edge { int to; ll weight; };
    vector<vector<edge>> g;

    range_edge_graph(int n) : n(n) {
        g.resize(n*4);
        for (int i = 1; i < n; i++) {
            int c1 = i*2, c2 = i*2+1;
            g[i].push_back({c1, 0ll});
            g[i].push_back({c2, 0ll});
            g[c1+2*n].push_back({i+2*n, 0ll});
            g[c2+2*n].push_back({i+2*n, 0ll});
        }
        for (int i = n; i < 2*n; ++i) g[i].push_back({i+2*n, 0ll});
    }

    // range edge : from [l1, r1) to [l2, r2) 
    void add_edge(int l1, int r1, int l2, int r2, ll w) {
        int id = g.size();
        for (l1 += n, r1 += n; l1 < r1; l1 /= 2, r1 /= 2) {
            if (l1 & 1) g[l1+2*n].push_back({id, 0ll}), l1++;
            if (r1 & 1) --r1, g[r1+2*n].push_back({id, 0ll});
        }
        vector<edge> node;
        for (l2 += n, r2 += n; l2 < r2; l2 /= 2, r2 /= 2) {
            if (l2 & 1) node.push_back({l2, w}), l2++;
            if (r2 & 1) --r2, node.push_back({r2, w});
        }
        g.push_back(node);
    } // 非再帰セグメント木

    vector<ll> dijkstra(int s) {
        s += n;
        vector<ll> dist(g.size(),INF); dist[s] = 0;
        using P = pair<ll,ll>;
        priority_queue<P,vector<P>,greater<P>> que;
        que.push(make_pair(0,s));
        while (!que.empty()) {
            P p = que.top(); que.pop();
            int v = p.second;
            if (dist[v] < p.first) continue;
            for (edge e : g[v]) {
                if (dist[e.to] > dist[v] + e.weight) {
                    dist[e.to] = dist[v] + e.weight;
                    que.push(make_pair(dist[e.to],e.to));
                }
            }
        }
        vector<ll> res(n);
        for(int i = 0; i < n; i++)  res[i] = dist[n+i];
        return res;
    }
};

int main() {
    int n, m; cin >> n >> m;
    range_edge_graph g(n);

    for (int i = 0; i < m; i++) {
        int l, r, c;  cin >> l >> r >> c; l--; r--;
        g.add_edge(l, r+1, l, r+1, c);
    }
    auto dist = g.dijkstra(0);
    cout << (dist[n-1] == INF ? -1 : dist[n-1]) << endl;
}

