data ST[4*N+5];

data operate(data a, data b){
	a.maksi = max(a.maksi,b.maksi);
	a.mini = min(a.mini,b.mini);
	return a;
}

void build(int node, int l, int r){
	if(l==r){
		ST[node].maksi = ST[node].mini = ans[l];
//		cout << node << " >> " << l << " ke " << r << " " << ST[node].mini << endl;
		return;
	}
	int mid =  (l+r)/2;
	build(node*2,l,mid);
	build(node*2+1,mid+1,r);
	ST[node] = operate(ST[node*2],ST[node*2+1]);
	return;
}

void update(int node, int l, int r, int ul, int ur,ll val){ // min(val, x);
	if(ul > r || ur < l) return;
	if(ST[node].maksi <= val) return;
	if(l == r){
		if(ST[node].mini >= val){
			ST[node].maksi = ST[node].mini = val;
			return;
		}
	}
	int mid = (l+r)/2;
	update(node*2,l,mid,ul,ur,val);
	update(node*2+1,mid+1,r,ul,ur,val);
	ST[node] = operate(ST[node*2] , ST[node*2+1]);
	return;
}

data query(int node, int l, int r, int ql, int qr){
	if(ql > r || qr < l) return data(-INF,INF);
	if(l >= ql && r<=qr){
//		cout << "PART OF " << l << "-" << r << endl;
		return ST[node];
	}
	int mid = (l+r)/2;
	return operate( query(node*2,l,mid,ql,qr) , query(node*2+1,mid+1,r,ql,qr));
}

