struct LazySegmentTree {
private:
    int n;
    vector<ll> node, lazy;

public:
  LazySegmentTree(vector<ll> v) {
      int sz = (int)v.size();
      n = 1; while(n < sz) n *= 2;
      node.resize(2*n-1);
      lazy.resize(2*n-1,inf);

      for(int i=0; i<sz; i++) node[i+n-1] = v[i];
      for(int i=n-2; i>=0; i--) node[i] = min(node[i*2+1],node[i*2+2]);
  }
  // k 番目のノードについて遅延評価を行う
  void eval(int k, int l, int r) {
    // 遅延配列が空でない場合、自ノード及び子ノードへの
    // 値の伝播が起こる
    if(lazy[k] != inf) {
      node[k] =min(node[k],lazy[k]);
      // 最下段かどうかのチェックをしよう
      // 子ノードは親ノードの 1/2 の範囲であるため、
      // 伝播させるときは半分にする
      if(r - l > 1) {
        lazy[2*k+1]=min(lazy[2*k+1],lazy[k]);
        lazy[2*k+2]=min(lazy[2*k+2],lazy[k]);
      }
      // 伝播が終わったので、自ノードの遅延配列を空にする
      lazy[k] = inf;
    }
  }

  void add(int a, int b, ll x, int k, int l, int r) {
    if(r < 0) r = n;

    // k 番目のノードに対して遅延評価を行う
    eval(k, l, r);

    // 範囲外なら何もしない
    if(b <= l || r <= a) return;

    // 完全に被覆しているならば、遅延配列に値を入れた後に評価
    if(a <= l && r <= b) {
      lazy[k] =x;
      eval(k, l, r);
    }

    // そうでないならば、子ノードの値を再帰的に計算して、
    // 計算済みの値をもらってくる
    else {
      add(a, b, x, 2*k+1, l, (l+r)/2);
      add(a, b, x, 2*k+2, (l+r)/2, r);
      node[k] =min(node[2*k+1],node[2*k+2]);
    }
  }
  void update(int a, int b, ll x){
    add(a,b,x,0,0,-1);
  }
  //[a,b)の最小値を取得
  ll getsum(int a, int b, int k, int l, int r) {
    if(r < 0) r = n;
    if(b <= l || r <= a) return inf;

    // 関数が呼び出されたら評価！
    eval(k, l, r);
    if(a <= l && r <= b) return node[k];
    ll vl = getsum(a, b, 2*k+1, l, (l+r)/2);
    ll vr = getsum(a, b, 2*k+2, (l+r)/2, r);
    return min(vl,vr);
  }
  ll get(int a,int b){
    return getsum(a,b,0,0,-1);
  }
};


