#define MOD 998244353
ll gcd(ll a, ll b) {
    return (b==0) ? a : gcd(b, a%b);
}

int main() {

    int n, m;cin >> n >> m;
    /// firstがto secondがcost
    const int MAX_N = 100005;
    const ll INF = 1001001001;
    struct Edge {int to; ll cost;};
    ll d[n];
    vector<Edge> g[MAX_N];

    rep(i,m) {
        ll l, r, c; cin >> l >> r >> c;
        for (int s=l;s<=r-1;s++) {
            for (int t=l+1;t<=r;t++) {
                Edge edge1 = {t-1, c};
                g[s-1].push_back(edge1);
                Edge edge2 = {s-1, c};
                g[t-1].push_back(edge2);
            }
        }
    }

    priority_queue<P, vector<P>, greater<P>> pq;
    fill(d, d + n, INF);
    d[0] = 0;
    pq.push(P(0, 0));

    while(! pq.empty()){
        P p = pq.top(); pq.pop();
        int v = p.second;
        if (d[v] < p.first) continue;
        rep(i, g[v].size()) {
            auto e = g[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                pq.push(P(d[e.to], e.to));
            }
        }
    }

    ll ans = d[n-1];
    if (ans == INF) ans = -1;
    cout << ans << endl;
}

