      VI Y;
      for(auto it2=prev(D.find(r)); it2!=D.begin()&&it2->second>=D[r]; --it2) {
        Y.push_back(it2->first);
      }
      FORR(i,Y) D.erase(i);
    }
  }
  LL res=D.count(N)?D[N]:-1;
  if(res>=Inf) res=-1;
  return res;
}

