void dijkstra(vl& d, vvi& es, int s, vvl& cost) {
    int N = es.size();
    d = vl(N, LINF);

    d[s] = 0;

    priority_queue<pll, vector<pll>, greater<pll>> pq;

    pq.push(pll(d[s], s));
    vb vis(N, false);

    while (!pq.empty()) {
        // get the smallest(nearest) element
        pll p = pq.top(); pq.pop();

        int i = p.second;
        vis[i] = true;

        for (int t : es[i]) {
            if (vis[t]) continue;

            if (p.first + cost[i][t] < d[t]) {
                d[t] = p.first + cost[i][t];
                pq.push(pll(d[t], t));
            }
        }
    }
}

