	int n,rn,bn;
	vector<ll> a,b;
	MQ(int n_){
		n = n_; rn = sqrt(n); bn = ceil((double)n/rn);
		a.resize(n,INF);
		b.resize(bn,INF);
	}
	ll value(ll s){
		if(a[s]>b[s/rn])a[s] = b[s/rn];
		return a[s];
	}
	void updete(int s,int t,ll x){
		for(int i=s;i<=t;i++){
			if(i%rn==0 && (i+rn-1)<=t){
