void eval(int i, int l, int r) {
	dat[i].x = min(dat[i].x, dat[i].y);
	if (r - l > 1) {
		dat[i * 2 + 1].y = min(dat[i * 2 + 1].y, dat[i].y);
		dat[i * 2 + 2].y = min(dat[i * 2 + 2].y, dat[i].y);
	}
	dat[i].y = Inf;
}
void update(int i, int l, int r, int a, int b, int x) {
	eval(i, l, r);
	if (b <= l || r <= a) return;
	if (a <= l && r <= b) {
		dat[i].y = min(dat[i].y, x);
		eval(i, l, r);
		return;
	}
	update(i * 2 + 1, l, (l + r) / 2, a, b, x);
	update(i * 2 + 2, (l + r) / 2, r, a, b, x);
	dat[i].x = min(dat[i * 2 + 1].x, dat[i * 2 + 2].x);
}
int query(int i, int l, int r, int a, int b) {
	eval(i, l, r);
	if (b <= l || r <= a) return Inf;
	if (a <= l && r <= b) {
		return dat[i].x;
	}
	return min(query(i * 2 + 1, l, (l + r) / 2, a, b),
		query(i * 2 + 2, (l + r) / 2, r, a, b));
}
