    ll N, M;
    cin >> N >> M;
    vector<pair<pair<ll, ll>, ll>> LR(M);
    for (ll i = 0; i < M; i++)
    {
        ll a, b, c;
        cin >> a >> b >> c;
        a--;
        b--;
        LR[i] = make_pair(make_pair(a, b), c);
    }
    sort(ALL(LR));
    LazyRMQ dp(vector<ll>(101010, LLINF));
    dp.update(0, 1, 0);
    for (ll i = 0; i < M; i++)
    {
        ll l = LR[i].first.first;
        ll r = LR[i].first.second;
        ll c = LR[i].second;
        dp.update(l + 1, r + 1, dp.getmin(l, l + 1) + c);
    }
    ll ans = dp.getmin(N - 1, N);
    cout << (ans == LLINF ? -1 : ans) << endl;
}

