            }
            sld.push_back({LRC[j].first.second, LRC[j].second});
            j++;
        }
        if(dp[i+1]==1e15)
            continue;
        while(sld.size()){
            pll a = sld.front();
            dp[a.first] = min(dp[a.first], dp[i + 1] + a.second);
            sld.pop_front();
        }

    }
    if(dp[N]==1e15){
        printf("-1");
    }else
    printf("%lld", dp[N]);

    return 0;
}

