struct segtree{
private:
  vector<ll> node;
  ll siz;
public:
  segtree(int n){
    siz=1;
    while(siz<=n) siz*=2;
    node.resize(siz*2+1,inf);
  }
  void upd(ll pos,ll x){
    pos+=siz-1;
    node[pos]=x;
    while(pos>0){
      pos=(pos-1)/2;
      node[pos]=min(node[pos*2+1],node[pos*2+2]);
    }
  }
  ll get_min(ll a,ll b,ll pos,ll l,ll r){
    if(a<=l&&r<=b) return node[pos];
    if(r<=a||b<=l) return inf;
    ll mid=(l+r)/2;
    ll lb=get_min(a,b,pos*2+1,l,mid);
    ll rb=get_min(a,b,pos*2+2,mid,r);
    //cout<<l<<" "<<r<<" "<<lb<<" "<<rb<<" "<<min(lb,rb)<<endl;
    return min(lb,rb);
  }
  ll min_q(ll a,ll b){
    return get_min(a,b,0,0,siz);
  }
  void seg_debug(){
    cout<<siz<<"SIZ**"<<endl;
    for(int i=0;i<node.size();i++) cout<<(node[i]==inf?-1:node[i])<<" ";
    cout<<endl;
  }
};
