const long INF = 1e18;

struct segtree
{
	int sz;
	long tree[400003], lazy[400003];
	segtree()
	{
		for(int i = 0; i <= 400000; i++)
		{
			lazy[i] = INF;
			tree[i] = INF;
		}
	}
	void cek_lazy(int pos, int kir, int kan)
	{
		if(lazy[pos] != INF)
		{
			tree[pos] = min(tree[pos], lazy[pos]);
			if(kan-kir) lazy[pos*2] = min(lazy[pos*2], lazy[pos]);
			if(kan-kir) lazy[pos*2+1] = min(lazy[pos*2+1], lazy[pos]);
			lazy[pos] = INF;

		}
	}
	void update(int pos, int kir, int kan, int qkir, int qkan, long val)
	{
		// printf("%d %d %d %d %d %d\n", pos, kir, kan, qkir, qkan, val);
		cek_lazy(pos, kir, kan);
		if(qkan < kir || kan < qkir) return;
		else if(qkir <= kir && kan <= qkan) lazy[pos] = min(lazy[pos], val), cek_lazy(pos, kir, kan);
		else
		{
			int mid = (kir+kan)/2;
			update(pos*2, kir, mid, qkir, qkan, val);
			update(pos*2+1, mid+1, kan, qkir, qkan, val);
			tree[pos] = min(tree[pos*2], tree[pos*2+1]);
		}
	}
	void update(int kir, int kan, long val)
	{
		update(1, 1, sz, kir, kan, val);
	}
	long query(int pos, int kir, int kan, int qkir, int qkan)
	{
		cek_lazy(pos, kir, kan);
		if(qkan < kir || kan < qkir) return INF;
		else if(qkir <= kir && kan <= qkan) return tree[pos];
		else
		{
			int mid = (kir+kan)/2;
			long a = query(pos*2, kir, mid, qkir, qkan);
			long b = query(pos*2+1, mid+1, kan, qkir, qkan);
			return min(a,b);
		}
	}
	long query(int kir, int kan)
	{
		return query(1, 1, sz, kir, kan);
	}
};

