using range = tuple<int, int, int>;
vector<range> stock;


void helper(int a, int b, ll c){
	// cerr << a << " " << b <<  " " << c << endl;
	graph[a].push_back({b, c});
}

void init(int k, int l, int r) {
	const int len = r - l;
	if (len <= 1) return;

	const int m = (l + r) / 2;

	helper(2 * k + 1, k, 0);
	helper(k + nmax, 2 * k + 1 + nmax, 0);

	helper(2 * k + 2, k, 0);
	helper(k + nmax, 2 * k + 2 + nmax, 0);

	init(2 * k + 1, l, m);
	init(2 * k + 2, m, r);
}


void get_range(int a, int b, int k, int l, int r) {
	const int len = r - l;	
	if (r <= a or b <= l) return;

	if (a <= l and r <= b) {
		stock.push_back(range(l, r, k));
		return;
	}

	const int m = (l + r) / 2;
	get_range(a, b, 2 * k + 1, l, m);
	get_range(a, b, 2 * k + 2, m, r);
}

void add_edge(int l, int r, ll c){
	stock.clear();
	get_range(l, r, 0, 0, ndummy);
	sort(begin(stock), end(stock));
	const int m = stock.size();

	rep(i, m) rep(j, i, m){
		const int ik = get<2>(stock[i]);
		const int jk = get<2>(stock[j]);
		helper(ik, jk + nmax, c);
	}
}

const ll inf = 1LL << 60;
auto dijkstra(int n, int s) {
    vector<ll> dist(n, inf);
    using state = tuple<ll, int>;

    priority_queue<state, vector<state>, greater<state>> q;
    dist[s] = 0, q.push(state(0, s));

    while (!q.empty()) {
        ll c; int v;
        tie(c, v) = q.top(); q.pop();
        for (auto &e : graph[v]) {
            ll nc = c + e.cost; int nv = e.to;
            if (chmin(dist[nv], nc)) q.push(state(nc, nv));
        }
    }
    return dist;
}

