  int n, m;
  scanf("%d %d", &n, &m);
  for (int i = 0; i < m; ++i) {
    int l, r, c;
    scanf("%d %d %d", &l, &r, &c);
    edges[l].emplace_back(r, c);
  }
  printf("%lld\n", solve(n));
  return 0;
}

