}

void update(int idx1, int idx2, long long val) {
    idx1 += (TREE >> 1), idx2 += (TREE >> 1);
    if (idx1 == idx2) {
        tree[idx1] = min(tree[idx1], val);
        return;
    }
    tree[idx1] = min(tree[idx1], val); bool flag1 = !(idx1 & 1); idx1 >>= 1;
    tree[idx2] = min(tree[idx2], val); bool flag2 =  (idx2 & 1); idx2 >>= 1;
    while (idx1 != idx2) {
        if (flag1) tree[(idx1 << 1) | 1] = min(tree[(idx1 << 1) | 1], val);
        if (flag2) tree[(idx2 << 1) | 0] = min(tree[(idx2 << 1) | 0], val);
        flag1 = !(idx1 & 1), idx1 >>= 1;
        flag2 =  (idx2 & 1), idx2 >>= 1;
    }
}

void solve() {
    for (int i = 0; i < TREE; i++)
        tree[i] = INF;

    sort(a, a + m);
//    for (int i = 0; i < m; i++)
//        fprintf(stderr, "%d %d %d\n", a[i].left, a[i].right, a[i].cost);
    long long ans = INF;
    for (int i = 0; i < m; i++) {
        long long cost = a[i].cost;
        if (a[i].right < n) {
            cost += query(a[i].right);
        }
        if (a[i].left == 1) {
            ans = min(ans, cost);
        }
        update(a[i].left, a[i].right, cost);
    }
    fprintf(out, "%lld\n", ans >= INF ? -1 : ans);
}

