struct In {
    ll l, r, c;
    In(){}
    In(ll l, ll r, ll c):l(l),r(r),c(r){}
};


typedef struct Edge {
    ll to, cost;
} Edge;

typedef struct Info {
    ll dist, from;
} Info;


void dijkstra(vector<Info> &dp, int s, const vector<vector<Edge>> &g) {
    priority_queue<P,vector<P>,greater<P>> pq;
    dp[s].dist = 0;
    // P(dist, v)
    pq.push({0,s});

    while (!pq.empty()) {
        P p = pq.top(); pq.pop();
        int v = p.second;
        for (auto &&e: g[v]) {
            if (dp[e.to].dist > dp[v].dist+e.cost) {
                dp[e.to].dist = dp[v].dist+e.cost;
                dp[e.to].from = v;
                pq.push({dp[e.to].dist, e.to});
            }
        }
    }
}



