    B--;
    es[A].emplace_back(A,B,C);
  }

  for (int i = 1; i < N - 1 ; i++)
  {
    es[i+1].emplace_back(i+1,i,0);
  }

  vector<int> path = dijkstra(es,0);

  if(path[N-1] == I64_MAX) cout<<-1<<endl;
  else if(path.empty()) cout<<-1<<endl;
  else
  {
    cout<<path[N-1]<<endl;
  }

  return;
}

