const int N=1e5+7;
ll inf=1e18+7;
ll t[N*4],lat[N*4];
void pushup(int rt){
	t[rt]=min(t[rt<<1],t[rt<<1|1]);
}
void pushdown(int rt){
	if(lat[rt]){
		t[rt<<1]=min(t[rt<<1],lat[rt]);
		t[rt<<1|1]=min(t[rt<<1|1],lat[rt]);
		lat[rt<<1]=min(lat[rt<<1],lat[rt]);
		lat[rt<<1|1]=min(lat[rt<<1|1],lat[rt]);
	}
}
void built(int l,int r,int rt){
	if(l==r){
		if(l==1){
			t[rt]=0;
			return;
		}
		t[rt]=inf;
		return ;
	}
	int mid=(l+r)/2;
	built(lson);
	built(rson);
	pushup(rt); 
}
void modify(int l,int r,int rt,int L,int R,ll x){
	if(l>=L&&R>=r){
		t[rt]=min(t[rt],x);
		lat[rt]=min(lat[rt],x);
		return ;
	}
	pushdown(rt);
	int mid=(l+r)/2;
	if(L<=mid) modify(lson,L,R,x);
	if(R>mid) modify(rson,L,R,x);
	pushup(rt);
}
ll query(int l,int r,int rt,int L,int R){
	if(l>=L&&R>=r){
		return t[rt];
	}
	pushdown(rt);
	int mid=(l+r)/2;
	ll res=inf;
	if(L<=mid) res=min(res,query(lson,L,R));
	if(R>mid) res=min(res,query(rson,L,R));
	return res; 
}
struct node{
	int l,r,c;
}a[N];
bool cmp(node x,node y){
	return x.l<y.l;
}
int main(){
	for(register int i=1;i<=N*4;i++) lat[i]=inf;
	int n,m;
	n=rf(),m=rf();
	int l,r,c;
	built(1,n,1);
	ll minn;
	for(int i=1;i<=m;i++) a[i].l=rf(),a[i].r=rf(),a[i].c=rf();
	sort(a+1,a+1+m,cmp);
	for(int i=1;i<=m;i++){
		l=a[i].l,r=a[i].r,c=a[i].c;
		minn=query(1,n,1,l,r);
		modify(1,n,1,l,r,minn+c);
	}
	ll ans=query(1,n,1,n,n);
	if(ans>=inf) cout<<"-1";
	else cout<<ans;
	return 0;
}

