#define FOR(i, a, b) for (int i = (a); i < (b); ++i)
#define REP(i, n) FOR(i, 0, n)

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N, M;
    cin >> N >> M;
    vector<tuple<int, int, int>> lcr(M);
    REP(i, M) {
        int l, r, c;
        cin >> l >> r >> c;
        lcr[i] = make_tuple(l, c, r);
    }
    sort(lcr.begin(), lcr.end());
    if (get<0>(lcr[0]) != 1) {
        cout << -1 << endl;
        exit(0);
    }

    vector<ll> dp(N + 1, LLONG_MAX);
    dp[1] = 0;

    int l = get<0>(lcr[0]);
    int r = get<2>(lcr[0]);
    int c = get<1>(lcr[0]);
    FOR(i, l + 1, r + 1) dp[i] = c;
    int i = 1;
    while (i < M) {
        int il = get<0>(lcr[i]);
        int ic = get<1>(lcr[i]);
        int ir = get<2>(lcr[i]);
        if (il == l) {
            if (ir > r && dp[ir] > dp[l] + ic) {
                FOR(j, r + 1, ir + 1) dp[j] = min(dp[j], dp[l] + ic);
                r = ir;
            }
            i++;
        } else {
            l = il;
            r = il;
            if (dp[l] == LLONG_MAX) {
                cout << -1 << "\n";
                exit(0);
            }
        }
    }
    cout << (dp[N] == LLONG_MAX ? -1 : dp[N]) << endl;
}

