	t[id].cl=cl; if (cl) add(2*cl,2*id,0),add(2*id+1,2*cl+1,0);
	t[id].cr=cr; if (cr) add(2*cr,2*id,0),add(2*id+1,2*cr+1,0);
	return id;
}
void qry(int a,int b,int id){
	int l=t[id].l,r=t[id].r;
	int cl=t[id].cl,cr=t[id].cr;
	if (l>b||r<a) return;
	if (a<=l&&r<=b){
		lis.push_back(id);
		return;
	}
	qry(a,b,cl); qry(a,b,cr);
}
