	rt=build(1,n);
	for (int i=1;i<=m;i++){
		int l,r; ll x; scanf("%d%d%lld",&l,&r,&x);
		lis.clear();
		qry(l,r,rt);
		for (int i=0;i<lis.size();i++){
			int u=lis[i];
			for (int j=0;j<lis.size();j++){
				int v=lis[j];
				add(2*u,2*v+1,x);
				if (u!=v) add(2*v+1,2*u,x);
				else add(2*v+1,2*u,0);
			}
		}
	}
	for (int i=1;i<=2*M+3;i++) dist[i]=inf;
	lis.clear(); qry(1,1,rt);
	q.push((rec){2*lis[0],0}); dist[2*lis[0]]=0;
	while (!q.empty()){
		rec u=q.top(); q.pop();
		if (use[u.u]) continue;
		use[u.u]=1;
		for (int e=head[u.u];e;e=nex[e]){
			int v=tail[e];
			if (dist[v]>dist[u.u]+w[e]){
				dist[v]=dist[u.u]+w[e];
				q.push((rec){v,dist[v]});
			}
