struct ST{//build(1,1,n) update(1,1,n,?,?,?) query(1,1,n,?,?)
	ll a[400010],lazy[400010];//四倍空间
	void build(int n,int l,int r){
		int lc=n*2,rc=n*2+1,m=(l+r)/2;
		lazy[n]=MAXN;
		if(l==r){
			a[n]=MAXN;
			return;
		}
		build(lc,l,m);
		build(rc,m+1,r);
		a[n]=min(a[lc],a[rc]);
	}
	void down(int n,int l,int r){
		int lc=n*2,rc=n*2+1,m=(l+r)/2;
		if(l<r){
			lazy[lc]=min(lazy[lc],lazy[n]);
			lazy[rc]=min(lazy[rc],lazy[n]);
		}
		a[n]=min(a[n],lazy[n]);
		lazy[n]=MAXN;
	}
	void update(int n,int l,int r,int x,int y,ll del){
		int lc=n*2,rc=n*2+1,m=(l+r)/2;
		x=max(x,l); y=min(y,r); if(x>y){down(n,l,r);return;}//!!
		if(x==l && y==r){
			lazy[n]=min(lazy[n],del);
			down(n,l,r);
			return;
		}
		down(n,l,r);
		update(lc,l,m,x,y,del);
		update(rc,m+1,r,x,y,del);
		a[n]=min(a[lc],a[rc]);
	}
	ll query(int n,int l,int r,int x,int y){
		int lc=n*2,rc=n*2+1,m=(l+r)/2;
		x=max(x,l); y=min(y,r); if(x>y)return MAXN;
		down(n,l,r);
		if(x==l && y==r)
			return a[n];
		return min(query(lc,l,m,x,y),query(rc,m+1,r,x,y));
	}
}st;
