void dijkstra()
{
	dist[1] = 0;
	priority_queue<ii,vector<ii>,greater<ii> >pq;
	pq.push(ii(0,1));
	while(!pq.empty())
	{
		ii x = pq.top();pq.pop();
		int a = x.first;
		int b = x.second;
		if(dist[b]==a)
		{
			for(int i=0;i<graph[b].size();++i)
			{
				ii c = graph[b][i];
				if(dist[c.first]==-1||dist[c.first] > dist[b] + c.second)
				{
					dist[c.first] = dist[b] + c.second;
					pq.push(ii(dist[c.first],c.first));
				}
			}
		}
	}
}
