const ll inf = (1ll << 62) - 1;

struct LazySegmentTree {
private:
    int n;
    vector<ll> node, lazy;
    vector<bool> lazyFlag;

public:
    LazySegmentTree(int sz) {
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1, inf);
        lazyFlag.resize(2*n-1, false);

        for(int i=0; i<sz; i++) node[i+n-1] = inf;
        for(int i=n-2; i>=0; i--) node[i] = min(node[i*2+1], node[i*2+2]);
    }

    void lazyEvaluate(int k, int l, int r) {
        if(lazyFlag[k]) {
            node[k] = min(lazy[k], node[k]);
            if(r - l > 1) {
                lazy[k*2+1] = min(lazy[k], lazy[k*2+1]);
				lazy[k*2+2] = min(lazy[k], lazy[k*2+2]);
                lazyFlag[k*2+1] = lazyFlag[k*2+2] = true;
            }
            lazyFlag[k] = false;
        }
    }

    void update(int a, int b, ll x, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        lazyEvaluate(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            lazy[k] = min(x, lazy[k]);
            lazyFlag[k] = true;
            lazyEvaluate(k, l, r);
        }
        else {
            update(a, b, x, 2*k+1, l, (l+r)/2);
            update(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = min(node[2*k+1], node[2*k+2]), node[k];
        }
    }

    ll find(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        lazyEvaluate(k, l, r);
        if(b <= l || r <= a) return inf;
        if(a <= l && r <= b) return node[k];
        ll vl = find(a, b, 2*k+1, l, (l+r)/2);
        ll vr = find(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};

int main()
{
	int n, m;
	cin >> n >> m;

	multimap<int, pair<int, int>> e;

	LazySegmentTree st(n);

	REP (i, m)
	{
		int l, r, c;
		cin >> l >> r >> c;
		e.emplace(l - 1, make_pair(r - 1, c));
	}
	st.update(0, 1, 0);

	for (auto& i : e)
	{
		st.update(i.first, i.second.first + 1, st.find(i.first, i.second.first + 1) + i.second.second);
	}

	const auto res = st.find(n - 1, n);

	cout << (res == inf ? -1 : res) << endl;

	return 0;
}

