}

void change(int id,ll w){
	lz[id]=min(lz[id],w);
	mn[id]=min(mn[id],w);
}

void pushdown(int id){
	if(lz[id]!=inf){
		change(lson(id),lz[id]);
		change(rson(id),lz[id]);
		lz[id]=inf;
	}
}

void update(int id,int l,int r,int pos,ll w){
	if(l==r){
		change(id,w);
		return ;
	}
	int mid=(l+r)/2;
	pushdown(id);
	if(mid>=pos) update(lson(id),l,mid,pos,w);
	else update(rson(id),mid+1,r,pos,w);
	pushup(id);
}

ll query(int id,int l,int r,int L,int R){
	if(l>=L&&r<=R)return mn[id];
	if(l>R||L>r) return inf;
	int mid=(l+r)/2;
	pushdown(id);
	return min(query(lson(id),l,mid,L,R),query(rson(id),mid+1,r,L,R));
}

