void insert(int a, ll b) {
    int now = a + (1 << 17);
    while (now > 0) {
        seg[now] = min(seg[now], b);
        now /= 2;
    }
}

ll mi(int left, int right) {
    left += (1 << 17);
    right += (1 << 17);
    ll ret = inf;
    while (left < right) {
        if (right % 2 == 0) {
            ret = min(ret, seg[right]);
            right--;
        }
        if (left % 2 != 0) {
            ret = min(ret, seg[left]);
            left++;
        }
        left /= 2;
        right /= 2;
    }
    if (left == right) {
        ret = min(ret, seg[left]);
    }
    return ret;
}

void solve() {
    sort(p,p+m);
    for (int i = 0; i < (1 << 18); i++) {
