void solve()
{
	READ(int, N, M);

	using P = pair<int, llong>;

	vector<vector<P>> gi(N + 1);
	vector<vector<P>> gd(N + 1);

	REP(i, M)
	{
		READ(int, L, R, C); L--, R--;
		gi[L].emplace_back(R, C);
		gd[R + 1].emplace_back(R, C);
	}

	vector<llong> totalCost(N, INF(llong));
	totalCost[0] = 0;

	using ikisaki = int;
	using cost = llong;
	map<ikisaki, multiset<cost>> s;
	REP(i, N)
	{
		FORE(p : gi[i])
		{
			s[p.first].insert(p.second);
		}

		FORE(p : gd[i])
		{
			s[p.first].erase(p.second);
			if (s[p.first].empty())
			{
				s.erase(p.first);
			}
		}

		if (totalCost[i] != INF(llong))
		{
			FORE(r : s)
			{
				if (!r.second.empty())
				{
					totalCost[r.first] =
						std::min(
						totalCost[r.first], 
						totalCost[i] + *r.second.begin());
				}
			}
		}
	}

	WRITE(totalCost[N - 1] < INF(llong) ? totalCost[N - 1] : -1);
}

