lli fastPow(lli base, lli exp, lli module = mod) {
	lli ans = 1;
	base %= module;
	while (exp) {
		if (exp & 1) ans = ans * base % module;
		base = base * base % module;
		exp >>= 1;
	}
	return ans;
}

bool millerRabin(lli n, lli a) {
	if (n < 2 or n % 2 == 0) return n == 2;
	lli u, t;
	for (u = n-1, t = 0; u & 1; u >>= 1, ++t);
	a = fastPow(a, u, n);
	if (a == 1 or a == n - 1) return true;
	for (int i = 0; i < t; ++i) {
		a = a * a % n;
		if (a == 1) return false;
		if (a == n - 1) return true;
	}
	return false;
}

int ls(int x) {return x << 1;}
int rs(int x) {return x << 1 | 1;}

const int maxn = 131072;

struct Path {
	lli L, R, C;
};

vector<lli> tree(2 * maxn, 1E16);

void ChangeMin(int L, int R, lli val, int np = 1, int lp = 1, int rp = maxn) {
	if (L > rp or R < lp) return;
	if (L <= lp and R >= rp) {
		tree[np] = min(tree[np], val);
		return;
	}
	if (tree[np] != (lli)1E16) {
		tree[ls(np)] = min(tree[ls(np)], tree[np]);
		tree[rs(np)] = min(tree[rs(np)], tree[np]);
		tree[np] = 1E16;
	}
	ChangeMin(L, R, val, ls(np), lp, (lp + rp) / 2);
	ChangeMin(L, R, val, rs(np), (lp + rp) / 2 + 1, rp);
}

lli GetValue(int x) {
	x += maxn - 1;
	lli minVal = 1E16;
	while (x) {
		minVal = min(minVal, tree[x]);
		x >>= 1;
	}
	return minVal;
}

bool cmp(Path a, Path b) {
	return a.L < b.L;
}

void solve() {
	int n, m;
	cin >> n >> m;

	vector<Path> path(m);
	for (auto &x : path) cin >> x.L >> x.R >> x.C;

	sort(ALL(path), cmp);

	tree[maxn] = 0;

	for (int i = 0; i < m; ++i) {
		ChangeMin(path[i].L, path[i].R, GetValue(path[i].L) + path[i].C);
	}

	if (GetValue(n) == (lli)1E16) cout << -1 << "\n";
	else cout << GetValue(n) << "\n";
}

int main() {
	int t = 1;
	// cin >> t;
	while (t--) {
		solve();
	}
	return 0;
}

