template<class T>
using Edges = vector<Edge<T>>;

template<class T>
using WeightedGraph = vector<Edges<T>>;

using UnWeightedGraph = vector<vector<int>>;

template<class T>
using DistMatrix = vector<vector<T>>;

struct GraphAdapter {
    template<class T>
    static UnWeightedGraph to_unweighted_graph(const WeightedGraph<T> &origin) {
        int V = origin.size();
        UnWeightedGraph graph(V);
        for (int i = 0; i < V; i++) for (auto &e: origin[i]) graph[i].push_back((int) e);
        return graph;
    }

    static WeightedGraph<int> to_weighted_graph(const UnWeightedGraph &origin) {
        int V = origin.size();
        WeightedGraph<int> graph(V);
        for (int i = 0; i < V; i++) for (auto to: origin[i]) graph[i].push_back({i, to, 1});
        return graph;
    }

    template<class T>
    static DistMatrix<T> to_dist_matrix(const WeightedGraph<T> &origin, T INF) {
        int V = origin.size();
        DistMatrix<T> matrix(V, vector<T>(V, INF));
        for (int i = 0; i < V; i++) for (auto &e:origin[i]) matrix[i][e.to] = e.cost;
        for (int i = 0; i < V; i++) matrix[i][i] = 0;
        return matrix;
    }
};

template<typename T>
class Dijkstra {
    using Pr = pair<T, int>;
private:
    int V;
    const WeightedGraph<T> &graph;
    const T INF = numeric_limits<T>::max();
    vector<T> dist;
    vector<int> prev;

public:

    Dijkstra(const WeightedGraph<T> &graph, int s) : graph(graph) {
        V = graph.size();
        dijkstra(s);
    }

    void dijkstra(int s) {
        priority_queue<Pr, vector<Pr>, greater<>> Q;
        dist = vector<T>(V, INF);
        prev = vector<int>(V, -1);
        Q.push(make_pair(0, s));
        dist[s] = 0;
        while (!Q.empty()) {
            auto p = Q.top();
            Q.pop();
            T now = p.first;
            int v = p.second;
            if (dist[v] < now)continue;
            for (auto e: graph[v]) {
                int to = e.to;
                T cost = e.cost;
                if (dist[to] > dist[v] + cost) {
                    dist[to] = dist[v] + cost;
                    prev[to] = v;
                    Q.push(make_pair(dist[to], to));
                }
            }
        }
    }

    vector<T> get_dist() const {
        return dist;
    }

    vector<int> get_prev() const {
        return prev;
    }

};

int main() {

    int N, M;
    cin >> N >> M;

    WeightedGraph<LL> graph(N);
    for (int i = 0; i < N - 1; i++) graph[i + 1].push_back({i + 1, i, 0});

    for (int i = 0; i < M; i++) {
        int l, r;
        cin >> l >> r;
        l--, r--;
        LL c;
        cin >> c;
        graph[l].push_back({l, r, c});
    }

    Dijkstra<LL> dijkstra(graph, 0);

    auto dist = dijkstra.get_dist();

    if (dist[N - 1] == numeric_limits<LL>::max()) cout << -1 << endl;
    else cout << dist[N - 1] << endl;

    return 0;
}

