  void update(int i,int j, long long k){
    if (i==s && j==e){
        val=min(val,k);
        lazy=min(lazy,k);
        return;
    }
    else{
        if (j<=m) l->update(i,j,k);
        else if (m<i) r->update(i,j,k);
        else l->update(i,m,k),r->update(m+1,j,k);
        val=min(l->val,r->val);
    }
  }
}*root;


