class Dijkstra{
    struct edge {
        int to;
        long long cost;
        edge(int a, long long b) {
            to = a;
            cost = b;
        }
    };

    private:
        int V;
        vector<vector<edge>> G;
        vector<long long> d;

    public:
        Dijkstra(int v) {
            V = v;
            G = vector<vector<edge>>(V);
            d = vector<long long>(V);
        }

        void add_edge(int from, int to, long long cost) {
            G[from].emplace_back(edge(to, cost));
        }

        vector<long long>& shortest_path(int s) {
            priority_queue<
                pair<long long, int>,
                vector<pair<long long, int>>,
                greater<pair<long long, int>>
            > que;

            for (long long& i : d) i = INF;
            d[s] = 0;
            que.push(make_pair(0, s));

            while (!que.empty()) {
                auto p = que.top(); que.pop();
                int v = p.second;
                if (d[v] < p.first) continue;

                for (const edge& e : G[v]) {
                    if (d[e.to] > d[v] + e.cost) {
                        d[e.to] = d[v] + e.cost;
                        que.push(make_pair(d[e.to], e.to));
                    }
                }
            }

            return d;
        }
};

int main(){
    int N, M;
