void add_edge(int u, int v, int w) {
	g[u].push_back(v);
	cost[u].push_back(w);
}

struct SegT {
	int siz;
	int id[N + N];

	void assign(int tp) {
		memset(id, -1, sizeof(id));
		for (int i = 1; i < N; ++ i) id[i] = cnt ++;
		for (int i = 0; i < n; ++ i) id[i + N] = i;
		for (int i = 1; i < N; ++ i)
			if (tp) {
				if (~id[i + i]) add_edge(id[i], id[i + i], 0);
				if (~id[i + i + 1]) add_edge(id[i], id[i + i + 1], 0);
			} else {
				if (~id[i + i]) add_edge(id[i + i], id[i], 0);
				if (~id[i + i + 1]) add_edge(id[i + i + 1], id[i], 0);
			}
	}

	void add(int i, int a, int b, int l, int r, int tp, int u, int w) {
		if (l <= a && b <= r) {
			if (tp)
				add_edge(u, id[i], w);
			else
				add_edge(id[i], u, w);
			return;
		}
		if (r <= a || b <= l) return;
		int m = (a + b) >> 1;
		add(i + i, a, m, l, r, tp, u, w);
		add(i + i + 1, m, b, l, r, tp, u, w);
	}
} from, to;

long long dis[N * 5];
priority_queue <pair <long long, int> > pq;

void dij() {
	memset(dis, 0x3f, sizeof(dis));
	pq.push(make_pair(0, 0));
	dis[0] = 0;
	while (!pq.empty()) {
		long long d = -pq.top().first;
		int u = pq.top().second;
		pq.pop();
		if (dis[u] != d) continue;
//		printf("%d %lld\n", u, dis[u]);
		for (int i = 0; i < g[u].size(); ++ i) {
			int v = g[u][i], w = cost[u][i];
			if (dis[v] > d + w) {
				dis[v] = d + w;
				pq.push(make_pair(-dis[v], v));
			}
		}
	}
}

