		from.add(1, 0, N, l, r, 0, cnt, c);
		to.add(1, 0, N, l, r, 1, cnt ++, 0);
	}
	dij();
	if (dis[n - 1] >= inf)
		puts("-1");
	else
		printf("%lld\n", dis[n - 1]);
	return 0;
}

