using namespace std;
typedef long long ll;

struct edge {
    int to;
    ll cost;
};

struct status {
    ll cost;
    int v;

    bool operator<(const status &another) const { return cost < another.cost; };

    bool operator>(const status &another) const { return cost > another.cost; };
};

const ll INF = 1145141919810364364;

ll dijkstra(int n, vector<vector<edge>> &graph) {
    priority_queue<status, vector<status>, greater<>> que;
    vector<ll> dis(n, INF);
    dis[0] = 0;
    que.push({0, 0});

    while (!que.empty()) {
        status now = que.top();
        que.pop();

        if (dis[now.v] < now.cost)continue;

        for (auto next:graph[now.v]) {
            if (dis[next.to] > dis[now.v] + next.cost) {
                dis[next.to] = dis[now.v] + next.cost;
                que.push({dis[next.to], next.to});
            }
        }
    }

    return dis[n - 1];
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<edge>> graph(n);
    for (int i = 1; i < n; i++)graph[i].push_back({i - 1, 0});

    for (int i = 0; i < m; i++) {
        int l, r, c;
        cin >> l >> r >> c;
        graph[l - 1].push_back({r - 1, c});
    }

    ll ret = dijkstra(n, graph);
    cout << (ret == INF ? -1 : ret) << endl;
    return 0;
}

