const long long inf = 1e17;

const int maxn = 1e5+10;

long long f[maxn << 2];

long long res[maxn];

typedef pair<int,int> II;
typedef pair<II, int> III;

III a[maxn];

void update(int k, int l, int r,int x, long long v) {
	if (l > x || r < x) return;
	if (l == r) {
		f[k] = min(f[k], v);
	} else {
		int g = (l + r) >> 1;
		update(k << 1, l , g, x, v);
		update(k << 1 | 1, g + 1, r, x , v);
		f[k] = min(f[k << 1], f[k << 1 | 1]);
	}
}

long long get(int k, int l,int r,int u,int v) {
	if (l > v || r < u) return inf;
	if (l >= u && r <= v) {
		return f[k];
	} else {
		int g = (l+r) >> 1;
		return min(get(k << 1, l, g, u, v), get(k << 1 | 1, g + 1, r, u, v));
	}
}

