EdgeTC::EdgeTC(int to, CostType cost)
	: to(to), cost(cost) {
}

int EdgeTC::compareByCost(const EdgeTC& left, const EdgeTC& right) {
	if (left.cost > right.cost) return 1;
	if (left.cost < right.cost) return -1;
	if (left.to > right.to) return 1;
	if (left.to < right.to) return -1;
	return 0;
}

bool EdgeTC::GreaterCost::operator()(const EdgeTC& left, const EdgeTC& right) {
	return compareByCost(left, right) > 0;
}

