EdgeFTC::EdgeFTC(int from, int to, CostType cost)
	:from(from), to(to), cost(cost) {
}

int EdgeFTC::compareByCost(const EdgeFTC & left, const EdgeFTC & right) {
	if (left.cost > right.cost) return 1;
	if (left.cost < right.cost) return -1;
	if (left.from > right.from) return 1;
	if (left.from < right.from) return -1;
	if (left.to > right.to) return 1;
	if (left.to < right.to) return -1;
	return 0;
}

bool EdgeFTC::GreaterCost::operator()(const EdgeFTC & left, const EdgeFTC & right) {
	return compareByCost(left, right) > 0;
}

bool EdgeFTC::LessCost::operator()(const EdgeFTC & left, const EdgeFTC & right) {
	return compareByCost(left, right) < 0;
}


