        for(i=x;i<=y-1;i++)
        {
            for(j=i+1;j<=y;j++)
            {
                struct YPO a;
                a.x=k; a.y=j;
                G[i].push_back(a);
                a.x=k; a.y=i;
                G[j].push_back(a);
            }
        }
    }
    memset(d,-1,sizeof(d));
    struct YPO a;
    a.x=0; a.y=1; d[1]=0;
    q.push(a);
    while(!q.empty())
    {
        a=q.top(); q.pop();
        if(d[a.y]!=-1&&d[a.y]<a.x) continue;
        for(i=0;i<G[a.y].size();i++)
        {
