struct edge{
	int src; int dst; LL weight;
	edge() : src(0), dst(0), weight(0) {}
	edge(int s, int d, LL w) : src(s), dst(d), weight(w) {}
};

using edges = V<edge>;
using graph = V<edges>;

void add_edge(edges &g,int s, int d, LL w=1){g.pb(edge(s,d,w));}
void add_edge(graph &g,int s, int d, LL w=1){g[s].pb(edge(s,d,w));}


Vi dijkstra(graph &g,int s){
	int i,j,k; int n=g.size(); int visit[n]; Vi dist(n);
	priority_queue<Pii,V<Pii>,greater<Pii>> q;
	REP(i,n){visit[i]=0; dist[i]=INF/2;}
	dist[s]=0;
	q.push(mp(0,s));
	int nv; int min_cost=0;
	while(!q.empty()){
		int d,t; tie(d,t)=q.top(); q.pop();
		if(visit[t]==1){continue;}
		visit[t]=1; dist[t]=d;
		for(auto &e:g[t]){
			if(dist[e.dst]<=d+e.weight){continue;}
			q.push(mp(d+e.weight,e.dst));
		}
	}
	return dist;
}

