template<typename T> class SegmentTree {
private:
	typedef function<T(T, T)> F;
	int n;
	T d0;
	vector<T> vertex;
	F f;
public:
	SegmentTree(int _n, F f, T d) :d0(d), f(f) {
		init(_n);
	}
	void init(int _n) {
		n = 1;
		while (n < _n) n *= 2;
		vertex.resize(2 * n - 1, d0);
	}
	void update(int i, T x) {
		int k = i + n - 1;
		vertex[k] = x;
		while (k > 0) {
			k = (k - 1) / 2;
			vertex[k] = f(vertex[2 * k + 1], vertex[2 * k + 2]);
		}
		return;
	}
	T query(int l, int r) {
		T vl = d0, vr = d0;
		l += n - 1;
		r += n - 1;
		for (; l <= r; l /= 2, r = r / 2 - 1) {
			if (l % 2 == 0) vl = f(vl, vertex[l]);
			if (r & 1) vr = f(vr, vertex[r]);
		}
		return f(vl, vr);
	}
};

int main(void)
{
	ll n, m;
	cin >> n >> m;

	SegmentTree<ll> t(n+1, [&](ll a, ll b) {return min(a, b); }, (ll)1e15);
	t.update(1, 0);
