		ll l, r, c;
		tie(l, r, c) = vs[i];
		auto prev = t.query(l, n + 1);
		auto next = t.query(r, n + 1);
		t.update(r, min(prev + c, next));
	}
	auto dist = t.query(n, n + 1);
	if (dist >= (ll)1e15) {
		cout << -1 << endl;
	}
	else {
		cout << dist << endl;
	}
	return 0;
}

