        cin >> a >> b >> c;
        g[a - 1].push_back({b - 1, c});
    }
    vl dist(n);
    dist = dijkstra(g, 0, n);
    if(dist[n - 1] == INF_LL) {
        cout << -1 << endl;
    } else {
        cout << dist[n - 1] << endl;
    }
}

