const ll inf = 1LL<<60;
int N, M;
vector<vector<pair<ll, ll>>> adj;
vector<ll> dist;

void input(){
    cin >> N >> M;
    adj.resize(N);
    dist.resize(N+5, inf);
    rep(i, N-1) adj[i+1].push_back(make_pair(i, 0));
    rep(i, M){
        int l, r, c; cin >> l >> r >> c;
        --l; --r;
        adj[l].push_back(make_pair(r, c));
    }
}

void Dijkstra(){
    priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> pq;
    dist[0] = 0;
    pq.push(make_pair(0, 0));

    while(!pq.empty()){
        auto p = pq.top(); pq.pop();
        ll d = p.first;
        int now = p.second;
        if(dist[now] < d) continue;
        for(auto q : adj[now]){
            int to = q.first;
            if(dist[to] > dist[now]+q.second){
                dist[to] = dist[now] + q.second;
                pq.push(make_pair(dist[to], to));
            }
        }
    }
}

void solve(){
    Dijkstra();
    cout << (dist[N-1]==inf? -1:dist[N-1]) << endl;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    input();
    solve();

    return 0;
}

