vector<pil> V[maxn];
void init()
{
    for (ll i = 2; i <= n; i++)
        V[i].pb(mp(i - 1, 0));
}
priority_queue<pil, vil, greater<pil> > q;
void solve()
{
    int s = 1;
    for (int i = 1; i <= n; i++)
        dis[i] = inf;
    dis[s] = 0;
    q.push(mp(dis[s], s));
    while (!q.empty())
    {
        pil p   = q.top(); q.pop();
        int mid = p.second;
        if (vis[mid])
            continue;
        vis[mid] = 1;
        for (int i = 0; i < V[mid].size(); i++)
        {
            int y = V[mid][i].first, d = V[mid][i].second;
            if (!vis[y] && dis[mid] + d < dis[y])
            {
                dis[y] = dis[mid] + d;
                q.push(mp(dis[y], y));
            }
        }
    }
    // for (int i = 1; i <= n; i++)
    //     cout << dis[i] << endl;
    if (dis[n] != inf)
        cout << dis[n] << endl;
    else
        cout << "-1\n";
}

