struct edge {
	ll from, to, cost;
};
struct range {
	ll L, R, C;
};
bool cmp(const range& a, const range& b) {
	if(a.L==b.L)return a.C < b.C;

	return a.L < b.L;

}
range road[10000000];
edge es[10000000];
ll d[10000000];
ll E = 0;
void shortest_path(int s) {
	for (int i = 0; i < N; i++)d[i] = INF*N;
	d[s] = 0;
	while (true) {
		bool update = false;
		for (int i = 0; i < E; i++) {
			edge e = es[i];
			if (d[e.from] != INF*N && d[e.to] > d[e.from] + e.cost) {
				d[e.to] = d[e.from] + e.cost;
				update = true;
			}
		}
		if (!update)break;
	}
}


