	for (int i = 0; i < M; i++) {

		for (int s = start; s <= to; s++) {
			for (int t = s + 1; t <= to; t++) {

				es[E++] = { s,t,cost };
				es[E++] = { t,s,cost };
			}

		}
		if (i + 1 >= M)break;
		start = road[i+1].L;
		to = road[i + 1].R;
