void add(int u, int v, int w) {
    G[u].push_back(make_pair(v, w));
}

#define mid (l + r >> 1)
#define ls (k << 1)
#define rs (k << 1 | 1)
void build1(int k, int l, int r) {
    if (l == r) { add(l, k + n, 0); return; }
    build1(ls, l, mid), build1(rs, mid + 1, r);
    add(ls + n, k + n, 0), add(rs + n, k + n, 0);
}

void build2(int k, int l, int r) {
    if (l == r) { add(k + 5 * n, l, 0); return; }
    build2(ls, l, mid), build2(rs, mid + 1, r);
    add(k + 5 * n, ls + 5 * n, 0), add(k + 5 * n, rs + 5 * n, 0);
}

void add1(int k, int l, int r, int ql, int qr, int p) {
    if (l >= ql && r <= qr) { add(k + n, p, 0); return; }
    if (mid >= ql) add1(ls, l, mid, ql, qr, p);
    if (mid < qr) add1(rs, mid + 1, r, ql, qr, p);
}

void add2(int k, int l, int r, int ql, int qr, int p) {
    if (l >= ql && r <= qr) { add(p, k + 5 * n, 0); return; }
    if (mid >= ql) add2(ls, l, mid, ql, qr, p);
    if (mid < qr) add2(rs, mid + 1, r, ql, qr, p);
}

