    scanf("%d %d", &n, &m);
    build1(1, 1, n), build2(1, 1, n);
    int tot = 9 * n;
    for (int i = 1, l, r, c; i <= m; i++) {
        scanf("%d %d %d", &l, &r, &c);
        add1(1, 1, n, l, r, tot + 1), add2(1, 1, n, l, r, tot + 2);
        add(tot + 1, tot + 2, c), tot += 2;
    }
    memset(f, 0x3f, sizeof(f)), q.push({f[1] = 0, 1});
    while (!q.empty()) {
        auto p = q.top(); q.pop();
        if (p.first ^ f[p.second]) continue;
        for (auto nxt : G[p.second]) {
            ll nd = p.first + nxt.second;
            if (nd < f[nxt.first]) q.push({f[nxt.first] = nd, nxt.first});
        }
    }
    printf("%lld\n", f[n] > 1e18 ? 0 : f[n]);
    return 0;
}

