template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    vector<vector<pll>> G(N);
    vector<int> imos(N+1);
    for(int i = 0; i < M;i++){
        int L,R,C; cin >> L >> R >> C;
        L--; R--;
        G[L].push_back(pll(R,C));

        imos[L]++;
        imos[R]--;
    }
    for(int i = 0; i < N;i++){
        imos[i+1] += imos[i];
    }

    for(int i = 0; i < N;i++){
        if(imos[i]) G[i+1].push_back(pll(i,0));
    }
    vector<ll> dist(N,LINF);
    queue<ll> q;
    q.push(0);
    dist[0] = 0;
    while(q.size()){
        ll n = q.front(); q.pop();
        for(auto p:G[n]){
            if(dist[p.first] > dist[n] + p.second){
                dist[p.first] = dist[n] + p.second;
                q.push(p.first);
            }
        }
    }
    res = dist[N-1];
    if(res == LINF) res = -1;
    return res;
}
