//セグ木
ll dat[2560000], sz;

void init(ll n) {
	sz = 1;
	while (sz < n)sz *= 2;
	REP(i, sz * 2 - 1) dat[i] = INF; //初期値
}

void update(ll k, ll a) { //場所(0-indexed), 値
	k += sz - 1;
	dat[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]); //更新
	}
}

ll query(ll a, ll b, ll k, ll l, ll r) { //[a, b) 呼ぶとき (a, b, 0, 0, sz)
	if (r <= a or b <= l)return INF;
	if (a <= l and r <= b)return dat[k];
	ll v1 = query(a, b, k * 2 + 1, l, (l + r) / 2);
	ll v2 = query(a, b, k * 2 + 2, (l + r) / 2, r);
	return min(v1, v2); //戻り値
}

#define PP pair<P, ll>
ll n, m;

int main() {
	init(110000);
	cin >> n >> m;
	vector<PP> s;
	REP(i, m) {
		ll a, b, c;
		cin >> a >> b >> c;
		a--;
		b--;
		s.push_back(PP(P(b, a), c));
	}
	sort(ALL(s));
	update(0, 0);
	REP(i, m) {
		ll a = s[i].first.second, b = s[i].first.first, c = s[i].second;
		update(b, min(query(a, b, 0, 0, sz) + c, query(b, b + 1, 0, 0, sz)));

	}
	ll ans = query(n - 1, n, 0, 0, sz);
	if (ans == INF)cout << -1 << endl;
	else cout << ans << endl;
}

