template<class T>
class LazySegT{
private:
  int NN;
  struct Node{
    T dat;
    T lazy;
  };
  Node *segT;
public:
  LazySegT(int n){
    NN = 1;
    while(NN < n) NN <<= 1;
    segT = new Node[2 * NN];

    for(int i=0;i<2*NN-1;++i)
      segT[i].dat = INF, segT[i].lazy = INF;
  }

  ~LazySegT(){
    delete segT;
  }

  void eval(int k, int l, int r){
    if(segT[k].lazy == INF) return;

    mini(segT[k].dat, segT[k].lazy);
    if(k < NN-1){ // not leaf
      mini(segT[2*k+1].lazy, segT[k].lazy);
      mini(segT[2*k+2].lazy, segT[k].lazy);
    }
    segT[k].lazy = INF;
  }

  void update(int a, int b, T c, int k, int l, int r){
    eval(k,l,r);
    if(r <= a || b <= l) return;

    if(a <= l && r <= b){
      mini(segT[k].lazy, c);
      eval(k,l,r);
    }
    else{
      update(a, b, c, k*2+1, l, (l+r)/2);
      update(a, b, c, k*2+2, (l+r)/2, r);
      segT[k].dat = min(segT[k*2+1].dat, segT[k*2+2].dat);
    }
  }
  // dat[idx] = c, a <= idx < b
  void update(int a, int b, T c){
    update(a, b, c, 0, 0, NN);
  }

  T query(int a, int b, int k, int l, int r){
    eval(k,l,r);
    if(r <= a || b <= l) return INF;

    if(a <= l && r <= b) return segT[k].dat;
    else{
      T vl = query(a, b, k*2+1, l, (l+r)/2);
      T vr = query(a, b, k*2+2, (l+r)/2, r);
      segT[k].dat = min(segT[k*2+1].dat, segT[k*2+2].dat);
      return min(vl, vr);
    }
  }
  T query(int a, int b){
    return query(a, b, 0, 0, NN);
  }
};


int main(int argc, char* argv[]){
  init_io(argc, argv);

  int N, M;
  cin >> N >> M;

  LazySegT<LL> seg(N);
  vector<pair<PII,LL>> es(M);

  REP(i,M){
    cin >> es[i].FF.FF >> es[i].FF.SS >> es[i].SS;
    es[i].FF.FF--;
  }
  SORT(es);

  seg.update(0, 1, 0);
  for(auto e : es){
    auto l = e.FF.FF;
    auto r = e.FF.SS;
    auto c = e.SS;
    LL up = seg.query(l, l+1) + c;
    seg.update(l, r, up);
  }

  auto ans = seg.query(N-1, N);
  cout << (ans == INF ? -1 : ans) << endl;

  return 0;
}

