// 始点sから各頂点への最短距離を求める
vector<ll> dijkstra(int s) {
  priority_queue<P, VP, GP> que;  // 最短距離の小さい順に取り出す
  vector<ll> d(n, INF);
  d[s] = 0;
  que.push(P(0, s));
  while (que.size()) {
    P p = que.top();
    que.pop();
    int v = p.second;
    if (d[v] < p.first) continue;
    REP(i, g[v].size()) {
      edge e = g[v][i];
      if (d[v] + e.cost < d[e.to]) {
        d[e.to] = d[v] + e.cost;
        que.push(P(d[e.to], e.to));
      }
    }
  }
  return d;
}

