struct do_elem {
    ll min = LL_INF;
    ll to_change = -1;
};
vector<do_elem> st(404040);

void propagate(ll node) {
    if (st[node].to_change != -1) {
        st[node * 2].min = st[node].to_change;
        st[node * 2].to_change = st[node].to_change;
        st[node * 2 + 1].to_change = st[node].to_change;
        st[node * 2 + 1].min = st[node].to_change;
        st[node].to_change = -1;
    }
}


ll change_seg(ll node, ll l, ll r, ll tl, ll tr, ll change) {
    if (l > r) {
        return LL_INF;
    }
    if (tl != tr) {
        propagate(node);
    }
    if (tl == l && tr == r) {
        st[node].min = change;
        st[node].to_change = change;
        return st[node].min;
    }
    ll mid = (tl + tr) / 2;
    ll left_res = change_seg(node * 2, l, min(r, mid), tl, mid, change);
    ll right_res = change_seg(node * 2 + 1, max(mid + 1, l), r, mid + 1, tr, change);
    st[node].min = min(st[2 * node + 1].min, st[2 * node].min);
    return st[node].min;
}

ll get_seg(ll node, ll l, ll r, ll tl, ll tr) {
    if (l > r) {
        return LL_INF;
    }
    if (tl != tr) {
        propagate(node);
    }
    if (tl == l && tr == r) {
        return st[node].min;
    }
    ll mid = (tl + tr) / 2;
    ll left_res = get_seg(node * 2, l, min(r, mid), tl, mid);
    ll right_res = get_seg(node * 2 + 1, max(mid + 1, l), r, mid + 1, tr);
    return min(left_res, right_res);
}

