    kek[r].emplace_back(l, c);
  }
  for (int r = 1; r < n; ++r) {
    long long mn = 1e18;
    for (auto [l, c] : kek[r]) {
      mn = min(mn, dp.get(l, r) + c);
    }
    dp.update(r, mn);
  }
  long long ans = dp.get(n - 1, n - 1);
  cout << (ans == 1e18 ? -1 : ans);

