signed main()
{
  IOS; /* making cin faster */
  int N,M;
  vector<vector<pair<int,int> > > G(N);
  REP(_,M)
    {
      int l,r,c;
      SCAND3(l,r,c);
      -- l;
      -- r;
      G[l].push_back(make_pair(r,c));
    }

  REP(i,N-1)
    {
      G[i+1].push_back(make_pair(i,0));
    }

  const lli LINF = 1e18;
  vector<bool> cango(N,true);
  vector<lli> d(N,LINF);
  priority_queue<pair<lli,int> > pq;
  d[0] = 0;
  pq.push(make_pair(0LL,0));

  while( not pq.empty() )
    {
      pair<lli,int> r = pq.top();
      pq.pop();
      int u = r.second;
      if( -r.first < d[u] )
	{
	  continue;
	}
      cango[u] = false;

      for( auto elem : G[u] )
	{
	  int v = elem.first;
	  int c = elem.second;

	  if( cango[v] and d[u] + c < d[v] )
	    {
	      d[v] = d[u] + c;
	      pq.push(make_pair(-d[v],v));
	    }
	}
    }


  if( d[N-1] == LINF )
    {
      PRINTD(-1);
    }
  else
    {
      PRINTLLD(d[N-1]);
    }

}

