ll dijkstra(int s, int t, Graph<pii> &G) {
    int N = G.size();
    vector<ll> dist(N, 1e17);
    priority_queue<pli, vector<pli>, greater<pli>> que;

    dist[s] = 0;
    que.emplace(pli{s, dist[s]});
    while (!que.empty()) {
        auto [d, v] = que.top();
        que.pop();
        if (dist[v] < d)
            continue;
        for (auto [nv, cost] : G[v]) {
            if (dist[nv] <= dist[v] + cost)
                continue;
            dist[nv] = dist[v] + cost;
            que.push({dist[nv], nv});
        }
    }

    return dist[t];
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, M;
    cin >> N >> M;
    Graph<pii> G(N);

    for (int i = 0; i + 1 < N; ++i)
        G[i + 1].emplace_back(pii{i, 0});
    for (int i = 0; i < M; ++i) {
        int L, R, C;
        cin >> L >> R >> C;
        L--, R--;
        G[L].emplace_back(pii{R, C});
    }

    ll ans = dijkstra(0, N - 1, G);
    cout << (ans < 1e17 ? ans : -1) << endl;

    return 0;
}

