const ll mxm = 1e18;
struct SegmentTree {
private:
    int n;
    vector<ll> node;
public:
    SegmentTree(vector<ll> v) {
        auto sz = v.size();
        n = 1; while (n < sz) n *= 2;
        node.resize(2 * n - 1, mxm);
        for (int i = 0; i < sz; ++i) node[i + n - 1] = v[i]; // 最下段に値を入れる
        for (int i = n - 2; i >= 0; --i) node[i] = min(node[2 * i + 1], node[2 * i + 2]);
    }
    void update(int x, ll val) {
        x += n - 1;
        node[x] = val;
        while (x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2 * x + 1], node[2 * x + 2]);
        }
    }
    ll getmin(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n; // init
        if (r <= a || b <= l) return mxm;
        if (a <= l && r <= b) return node[k];
        ll vl = getmin(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = getmin(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
    // http://tsutaj.hatenablog.com/entry/2017/03/29/204841
    void out() {
        rep(i, sz(node)) cout << (node[i] == mxm ? -1 : node[i]) << " "; cout << endl;
    }
};


