  }
  sort(v.begin(), v.end(),
       [](auto &lhs, auto &rhs) { return get<1>(lhs) < get<1>(rhs); });
  RUP t(n);
  const int inf = 1e9 + 7;
  t.update(0, 1, 0);
  for (auto p : v) {
