    if (mn + c < cur) t.update(r, r + 1, mn + c);
  }
  // rep(i, n) { cout << t.query(i, i + 1) << " "; }
  auto ans = t.query(n - 1, n);
  if (ans == inf) ans = -1;
  cout << ans << endl;

  return 0;
}

