        n=1; while (n<mx) n <<=1;
        d=vector<F>(n<<1);
    }
    void upd(int i){ d[i]=d[i<<1]+d[i<<1|1];}
    F& operator[](int i) {return d[n+1];}
    void init() { for(int i=n-1;i;--i) upd(i); }
