        L--, R--;
        edge e = {L, C};
        es[R].pb(e);
    }
    //dp[i]:=頂点0〜頂点iへの最短距離
    ll dp[N];
    fill(dp, dp+N, INF);
    dp[0] = 0;
    int pre = 0;
    rep(i, N){
        if(es[i].empty()) continue;
        for(auto &e: es[i]){
            dp[i] = min(dp[i], dp[e.from]+e.cost);
        }
        rep2(j, pre+1, i-1) dp[j] = dp[i];
        pre = i;
    }
    if(dp[N-1] == INF) cout << -1 << endl;
    else cout << dp[N-1] << endl;
}

#include <iostream>
#include <vector>
