ll N,M;
struct edge {
	ll from, to, cost;
};
struct range {
	ll L, R, C;
};
bool cmp(const range& a, const range& b) {
	if(a.L==b.L)return a.C < b.C;

	return a.L < b.L;

}
range road[100000];
edge es[100000];
ll d[100000];
ll E = 0;
void shortest_path(int s) {
	for (int i = 0; i < N; i++)d[i] = INF*N;
	d[s] = 0;
	while (true) {
		bool update = false;
		for (int i = 0; i < E; i++) {
			edge e = es[i];
			if (d[e.from] != INF*N && d[e.to] > d[e.from] + e.cost) {
				d[e.to] = d[e.from] + e.cost;
				update = true;
			}
		}
		if (!update)break;
	}
}


int main() {
	cin >> N>>M;
	rep(i, M) {
		ll L, R, C;
		cin >> L >> R >> C;
		L--; R--;
		road[i] = { L,R,C };
	}
	sort(road, road + M, cmp);
	ll start = road[0].L,to=road[0].R;
	ll cost = road[0].C;

	for (int i = 0; i < M; i++) {

		for (int s = start; s <= to; s++) {
			for (int t = s + 1; t <= to; t++) {

				es[E++] = { s,t,cost };
				es[E++] = { t,s,cost };
			}

		}
		if (i + 1 >= M)break;
		start = road[i+1].L;
		to = road[i + 1].R;
		cost = road[i + 1].C;

	}


	shortest_path(0);
	if (d[N - 1] == INF*N) {
		cout << -1 << endl;
		return 0;
	}
	cout << d[N - 1] << endl;

}

