// SegmentTree
template <class T>
class SegmentTree {
	vector<T> seg;
	function<T(T, T)> func;
	/*func:ex)
	function<int(int,int)>down=[](int a,int b){return min(a,b);};
	*/
private:
	T findquary(int left, int right, int index, int atStart, int atStop) {
		if ((left <= atStart) and
		    (atStop <= right)) {  //対象範囲に完全に囲まれる
			return seg[index];
		}
		if ((atStop <= left) or (right < atStart)) {  //対象範囲に全く関わらない
			return init;
		}
		if (index >= size) {  //範囲外・子がいない
			return seg[index];
		}
		//対象に一部が含まれる
		T aL = findquary(left, right, index * 2, atStart,
		                 atStart + (atStop - atStart) / 2);
		T aR = findquary(left, right, index * 2 + 1,
		                 atStart + (atStop - atStart) / 2, atStop);
		return func(aL, aR);
	}
	T upquary(int index) {  // q1
		return func(seg[index], seg[index + 1]);
	}
	int bin_quary(int left, int right, int index, int atStart, int atStop,
	              T value, bool leftFirst) {
		if (found == false) {
			clean();
		}  // fprintf(stderr,"%d %d %d %d %d %d
		   // %d\n",left,right,index,atStart,atStop,value,leftFirst);
		int res = (leftFirst ? (size * 2) : (size - 1));  //初期値
		if (index >= size * 2) {                          //範囲外
			return (leftFirst ? (size * 2) : (0));
		}  // fprintf(stderr,"seg[%d]:%lld\n",index,seg[index]);
		if (index >= size) {  //子がいない
			if (seg[index] <= value) {
				return index;
			} else {
				return (leftFirst ? (size * 2) : (0));
			}
		}  // fprintf(stderr, "(seg[%d]:%lld, seg[%d]:%lld)\n", index*2,
		   // seg[index*2],(index*2)+1,seg[(index*2)+1]);
		if ((left <= atStart) and (atStop <= right)) {  //完全に囲まれる
			if (leftFirst) {
				if (seg[index * 2] <= value) {
					return bin_quary(left, right, index * 2, atStart,
					                 atStart + (atStop - atStart) / 2, value,
					                 true);
				}
				if (seg[index * 2 + 1] <= value) {
					return bin_quary(left, right, index * 2 + 1,
					                 atStart + (atStop - atStart) / 2, atStop,
					                 value, true);
				}
				return res;
			} else {
				if (seg[index * 2 + 1] <= value) {
					return bin_quary(left, right, index * 2 + 1,
					                 atStart + (atStop - atStart) / 2, atStop,
					                 value, false);
				}
				if (seg[index * 2] <= value) {
					return bin_quary(left, right, index * 2, atStart,
					                 atStart + (atStop - atStart) / 2, value,
					                 false);
				}
				return res;
			}
		}
		if ((atStop <= left) or (right < atStart)) {  //全くかかわらない
			return (leftFirst ? (size * 2) : (0));
		}
		//一部が含まれる
		if (leftFirst) {
			if (seg[index * 2] <= value) {
				chmin(res,
				      bin_quary(left, right, index * 2, atStart,
				                atStart + (atStop - atStart) / 2, value, true));
			}
			if (seg[index * 2 + 1] <= value) {
				chmin(res, bin_quary(left, right, index * 2 + 1,
				                     atStart + (atStop - atStart) / 2, atStop,
				                     value, true));
			}
		} else {
			if (seg[index * 2 + 1] <= value) {
				chmax(res, bin_quary(left, right, index * 2 + 1,
				                     atStart + (atStop - atStart) / 2, atStop,
				                     value, false));
			}
			if (seg[index * 2] <= value) {
				chmax(res, bin_quary(left, right, index * 2, atStart,
				                     atStart + (atStop - atStart) / 2, value,
				                     false));
			}
		}
		return res;
	}

public:
	int size;            // size of segmenttree
	T init;              // unit
	bool found = false;  // find query done
	// constructor
	SegmentTree(int _legth, function<T(T, T)> _func, T _init = 0) {
		size = 1;
		func = _func;
		init = _init;
		while (size <= _legth) {
			size <<= 1;
		}
		seg.assign(size << 1, init);
	}
	T get(int index) { return seg[size + index]; }
	void show() {
		rep(i, size * 2) { clog << seg[i] << " "; }
		clog << endl;
	}
	void clean() {
		found = true;
		for (int i = (size << 1) - 2; i >= 2; i -= 2) {
			seg[i / 2] = upquary(i);
		}
	}
	//指定範囲内で、value以下となる左側の配列の番号を返す(notfound:-1)
	int left_bound(int left, int right, T value) {
		return bin_quary(left, right, 1, 0, size, value, true) - size;
	}
	//指定範囲内で、value以下となる右側に位置を返す(not found:size)
	int right_bound(int left, int right, T value) {
		return bin_quary(left, right, 1, 0, size, value, false) - size;
	}
	// change value
	void update(int index, T value) {
		chmin(seg[size + index], value);
		if (found == false) {
			return;
		}
		int ter = index + size;
		while (ter != 1) {
			ter /= 2;
			seg[ter] = upquary(ter * 2);
		}  // show();
	}
	// find value
	T find(int l, int r) {  // q2
		if (found == false) {
			clean();  // show();
		}
		T res = seg[size + l];
		res   = findquary(l, r, 1, 0, size);
		return res;
	}
};
