class IntervalEdgeTech {
public:
	int Eto[PA * 5 + MA], Eco[PA * 5 + MA], Ene[PA * 5 + MA], Ehe[PA * 5 + AN * 2 + 2], EN, Nadd;
	ll D[PA * 5 + AN * 2 + 2];
	void adde(int v, int to, int co) {
		Eto[EN] = to;
		Eco[EN] = co;
		Ene[EN] = Ehe[v];
		Ehe[v] = EN++;
	}
	IntervalEdgeTech() : Ehe() {
		EN = 1;
		for (int i = PA * 2 - 1; i > 1; i--) adde(i << 1, i >> 1 << 1, 0);
		rep1(i, PA - 1) {
			adde(i << 1 | 1, i << 2 | 1, 0);
			adde(i << 1 | 1, i << 2 | 3, 0);
		}
		for (int i = PA * 2; i < PA * 4; i += 2) adde(i + 1, i, 0);
		Nadd = PA * 4;
	}
	void AddE(int L1, int R1, int L2, int R2, int C) {
		for (L1 += PA, R1 += PA; L1 < R1; L1 >>= 1, R1 >>= 1) {
			if (L1 & 1) adde(L1++ << 1, Nadd, 0);
			if (R1 & 1) adde(--R1 << 1, Nadd, 0);
		}
		for (L2 += PA, R2 += PA; L2 < R2; L2 >>= 1, R2 >>= 1) {
			if (L2 & 1) adde(Nadd + 1, L2++ << 1 | 1, 0);
			if (R2 & 1) adde(Nadd + 1, --R2 << 1 | 1, 0);
		}
		adde(Nadd, Nadd + 1, C);
		Nadd += 2;
	}
