		rep(i, PA * 5 + AN * 2 + 2) D[i] = 1e18;
		priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> que;
		que.push(mp(0, (v + PA) << 1));
		D[(v + PA) << 1] = 0;
		while (que.size()) {
			auto p = que.top();
			que.pop();
			int from = p.second;
			if (D[from] != p.first) continue;
			for (int ind = Ehe[from]; ind; ind = Ene[ind]) {
				int to = Eto[ind];
				ll d = D[from] + Eco[ind];
				if (D[to] > d) {
					D[to] = d;
					que.push(mp(d, to));
				}
			}
		}
	}
