long long int d[MAX_V];

// O(ElogV)

void shortest_path(int s, int V){

	priority_queue<P, vector<P>, greater<P> > que;

	for(int i = 0; i < V; i++){
		d[i] = INF;
	}
	d[s] = 0;

	que.push(P(0, s));

	while(!que.empty()){

		P p = que.top();
		que.pop();

		int v = p.second;

		if(d[v] < p.first){
			continue;
		}

		for(int i = 0; i < G[v].size(); i++){
			edge e = G[v][i];
			if(d[e.to] > e.cost + d[v]){
				d[e.to] = d[v] + e.cost;
				que.push(P(d[e.to], e.to));
			}
		}
	}
}

