        --L, --R;
        dijkstra.add_edge(L, R, C);
    }
    rep(i, 1, N) {
        dijkstra.add_edge(i, i - 1, 0);
    }
    dijkstra.calc_shortest_path(0);
    if (dijkstra.get_dist(N - 1) == INF) {
        cout << -1 << endl;
    }
    else {
        cout << dijkstra.get_dist(N - 1) << endl;
    }
    return 0;
}

