    REP(i, m) {
        cin >> l >> r >> c;
        l--, r--;
        g[l].push_back(Edge{r, c});
        g[r].push_back(Edge{l, c});
    }
    REP(i, n - 1) {
        g[i + 1].push_back(Edge{i, 0});
    }
    ll res = dijkstra(g, 0)[n - 1];
    if (res == inf) res = -1;
    cout << res << endl;
    return 0;
}

