using namespace std;

const ll INF = 1e18;

struct Node {
    ll mn;
    ll lazy;
    Node() {
        mn = lazy = INF;
    }
};

class Lazy_SegTree {
public:

    vector <Node> aint;
    int n;

    inline void init(int _n) {
        n = _n;
        aint.resize(4 * n + 1);
    }

    inline void update(int l, int r, Node cur) {
        update(1, 1, n, l, r, cur);
    }

    inline Node query(int l, int r) {
        return query(1, 1, n, l, r);
    }

private:

    inline void push(int nod) {
        aint[2 * nod].lazy = min(aint[nod].lazy, aint[2 * nod].lazy);
        aint[2 * nod + 1].lazy = min(aint[nod].lazy, aint[2 * nod + 1].lazy);
        aint[nod].mn = min(aint[nod].mn, aint[nod].lazy);
        aint[nod].lazy = INF;
    }

    void update(int nod, int left, int right, int l, int r, Node cur) {
        if(l <= left && right <= r) {
            aint[nod].lazy = min(aint[nod].lazy, cur.lazy);
            return ;
        }
        push(nod);
        int mid = (left + right) / 2;

        if(l <= mid) update(2 * nod, left, mid, l, r, cur);
        if(mid < r) update(2 * nod + 1, mid + 1, right, l, r, cur);
    }

    Node query(int nod, int left, int right, int l, int r) {
        if(l <= left && right <= r) {
            return aint[nod];
        }
        push(nod);
        int mid = (left + right) / 2;
        Node ans;

        if(l <= mid) ans = query(2 * nod, left, mid, l, r);
        if(mid < r) ans = query(2 * nod + 1, mid + 1, right, l, r);

        return ans;
    }
};

