#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = 1e18;

// ダイクストラ法 O(ElogV)
vector<ll> d; // 最短距離

void dijkstra(const vector<vector<pair<int, ll>>> &G, int s) {
  priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq; // first:最短距離 second:頂点の番号
  d.resize(G.size(), INF); // 初期化
  d[s] = 0;
  pq.push(make_pair(0, s));
  while (!pq.empty()) {
    pair<ll, int> p = pq.top();
    pq.pop();
    int v = p.second;
    if (d[v] < p.first) continue;
    for (int i = 0; i < G[v].size(); i++) {
      pair<int, ll> p2 = G[v][i];
      if (d[p2.first] > d[v] + p2.second) {
        d[p2.first] = d[v] + p2.second;
        pq.push(make_pair(d[p2.first], p2.first));
      }
    }
  }
  return;
}

