};

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    vector<Range> as;
    for (int i = 0; i < m; i++) {
        int l, r, c;
        cin >> l >> r >> c;
        l--;
        as.push_back((Range){l, r, c});
    }
    sort(as.begin(), as.end(), [](auto &a, auto &b) { return a.l == b.l ? a.r > b.r : a.l < b.l; });

    MinUpdateQuery<int, int> seg;
    seg.set_by_vector(vector<int>(n, 1e9));
    seg.update(0, 0);

    for (int i = 0; i < m; i++) {
        int l = as[i].l, r = as[i].r, c = as[i].c;
        int x = seg.query(l) + c;
        // R: 初めてxより大きくなる座標
        if (seg.query(r - 1) <= x) continue;
        int L = l, R = r;
        while (L < R - 1) {
            int M = (L + R) / 2;
            if (seg.query(M) <= x)
                L = M;
            else
                R = M;
        }
        seg.update(R, r, x);
    }

    int ans = seg.query(n - 1);
    if (ans == 1e9) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }
}

