    int tm = (tl + tr) >> 1;
    build1(v * 2 + 1, tl, tm);
    build1(v * 2 + 2, tm + 1, tr);
    mx[v] = max(mx[v * 2 + 1], mx[v * 2 + 2]);
}
void go(int v, int tl, int tr, int l, int r, int u, int d) {
    if (tr < l || r < tl || mx[v] < u) {
        return;        
    }   
    if (tl == tr) {
        upd(0, 1, n, seg[tl].l, seg[tl].r, d+seg[tl].c);
