        return;
    }   
    int tm = (tl + tr) >> 1;
    go(v * 2 + 1, tl, tm, l, r, u, d);
    go(v * 2 + 2, tm + 1, tr, l, r, u, d);
    mx[v] = max(mx[v * 2 + 1], mx[v * 2 + 2]);
}   

