void push_down(int rt){
    //if(a[rt]==0x3f3f3f3f)return;
	t[rt] = min(t[rt], a[rt]);
    a[rt*2+1]=min(a[rt*2+1],a[rt]);
    a[rt*2+2]=min(a[rt*2+2],a[rt]);
    t[rt*2+1]=min(t[rt*2+1],a[rt*2+1]);
    t[rt*2+2]=min(t[rt*2+2],a[rt*2+2]);
    t[rt]=min(t[rt*2+1],t[rt*2+2]);
    a[rt]=0x3f3f3f3f;
}
void update(int rt,int l,int r,int nl,int nr,int x){
    if(l<=nl&&nr<=r)t[rt]=min(t[rt],x),a[rt]=min(a[rt],x);
    else if(nr<l||nl>r)return;
    else{
        push_down(rt);
        int mid=(nl+nr)/2;
        update(rt*2+1,l,r,nl,mid,x);
        update(rt*2+2,l,r,mid+1,nr,x);
        push_down(rt);
    }
}
int query(int rt,int l,int r,int nl,int nr){
    //printf("%d %d %d %d %d\n",rt,l,r,nl,nr);
    push_down(rt);
    if(l<=nl&&nr<=r)return t[rt];
    else if(nr<l||nl>r)return 0x3f3f3f3f;
    else{
        int mid=(nl+nr)/2;
        //cout<<"!"<<min(query(rt*2+1,l,r,nl,mid),query(rt*2+2,l,r,mid+1,nr))<<endl;
        return min(query(rt*2+1,l,r,nl,mid),query(rt*2+2,l,r,mid+1,nr));
    }
}
