void add_edge(int a, int b, ll c, int idx, int k, int l, int r) {
	// debug(a, b, c, k, l, r);
	if(b <= l || r <= a) return;
	if(a <= l && r <= b) {
		G[k + 2 * n].pb(pl(idx, c));
		G[idx].pb(pl(k, 0));
	}
	else {
		add_edge(a, b, c, idx, k * 2 + 1, l, (l + r) / 2);
		add_edge(a, b, c, idx, k * 2 + 2, (l + r) / 2, r);
	}
}

ll d[MAX_N];

void dijkstra(int s) {
	//can be used as bfs.
	priority_queue<pl, vector<pl>, greater<pl> > que;
	fill(d, d + 4 * n + M, linf);
	d[s] = 0;
	que.push(pi(0, s));
	while(!que.empty()) {
		pl p = que.top(); que.pop();
		int v = p.second;
		if(d[v] < p.first) continue;
		for(int i = 0; i < sz(G[v]); i++) {
			pl e = G[v][i];
			if(d[e.fst] > d[v] + e.sec) {
				d[e.fst] = d[v] + e.sec;
				que.push(pi(d[e.fst], e.fst));
			}
		}
	}
}

