template<typename T>
struct segment_tree {
    int n;
    T ZERO;
    std::vector<T> data;
    int get_size(int n_) const {
        int ret = 1;
        while (ret < n_) { ret <<= 1; }
        return ret;
    }
    segment_tree(int n_, T ZERO = T()) : n(get_size(n_)), ZERO(ZERO), data(n << 1, ZERO) {}
    template<typename I> segment_tree(I begin, I end, T ZERO = T())
        : n(get_size(end - begin)), ZERO(ZERO), data(n << 1) {
        std::copy(begin, end, data.begin() + n);
        for (int i = n - 1; i > 0; i--) { data[i] = data[i << 1] + data[(i << 1) + 1]; }
    }
    void set(int i, T x) {
        i += n;
        data[i] = x;
        while (i > 1) {
            i >>= 1;
            data[i] = data[i << 1] + data[(i << 1) + 1];
        }
    }
    T operator[](int i) const { return data[i + n]; }
    T get_sum(int l, int r) const {
        if (l < 0) { l = 0; }
        if (r > n) { r = n; }
        T ret = ZERO;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) { ret += data[l], l++; }
            if (r & 1) { ret += data[r - 1]; }
        }
        return ret;
    }
};

struct min_monoid {
    long long val;
    min_monoid() : val(LLONG_MAX) {}
    min_monoid(long long val) : val(val) {}
    bool operator==(const min_monoid &rhs) const { return val == rhs.val; }
    bool operator!=(const min_monoid &rhs) const { return std::rel_ops::operator!=(*this, rhs); }
    min_monoid &operator+=(const min_monoid &rhs) {
        val = std::min(val, rhs.val);
        return *this;
    }
    min_monoid operator+(const min_monoid rhs) const { return min_monoid(*this) += rhs; }
    friend std::istream &operator>>(std::istream &is, min_monoid &rhs) {
        long long v;
        is >> v;
        rhs = min_monoid(v);
        return is;
    }
    friend std::ostream &operator<<(std::ostream &os, const min_monoid &rhs) { return os << rhs.val; }
};

