//(len, init_value)
//(vector<> &) 参照を付けないとおかしくなる
//答えが存在しないことがある場合 index付きで、答えが-1になるかで判定したほうがいい
template<class M=int> struct segmin {/*@formatter:off*/int n;vector<M> seg; M f(M a,M b){return a < b ? a : b;}const M e = MAX(M);
    segmin(int len, M init_value = MAX(M)) : e(init_value) {        n = 1;        int asz = len;        while (n <= asz)n <<= 1;        seg.assign((n << 1) - 1, e);        rep(i, asz) seg[i + n - 1] = e;        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);        debu();    }
    segmin(vector<M> &dat, M init_value = MAX(M)) : e(init_value) {        n = 1;        int asz = dat.size();        while (n <= asz)n <<= 1;        seg.assign((n << 1) - 1, e);        rep(i, asz) seg[i + n - 1] = dat[i];        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);        debu();    }
    void update(int k, M v, bool debug = true) {        int tk = k;        seg[k + n - 1] = v;        k += n - 1;        while (k) {            k = (k - 1) >> 1;            seg[k] = f(seg[(k << 1) | 1], seg[(k << 1) + 2]);        }        if (debug)debup(tk, v);    }
    void del(int k) { update(k, e); }
    void add(int k, int v, bool debug = true) { update(k, v + seg[k + n - 1], debug); }    M query_bottomup(int l, int r, bool debug = true) {        int tl = l, tr = r;        M retl = e;        M retr = e;        l += n - 1;        r += n - 1;        while (l < r) {            /*右なら、次に右上へ移動してしまうので*/            if (!(l & 1)) { retl = f(retl, seg[l]); }            /*右なら、左を取らないと機会を逃す*/            if (!(r & 1)) { retr = f(seg[r - 1], retr); }            l >>= 1;            r = (r - 1) >> 1;        }        M ret = f(retl, retr);        if (debug)debge(tl, tr, ret);        return ret;    }    M query(int a, int b, int k, int l, int r) {        if (r <= a || b <= l)return e;        else if (a <= l && r <= b)return seg[k];        else {            M sl = query(a, b, (k << 1) | 1, l, (l + r) >> 1);            M sr = query(a, b, (k << 1) + 2, (l + r) >> 1, r);            return f(sl, sr);        }    }/*    M get(int a = 0, int b = -1) { return query(a, b == -1 ? n : b, 0, 0, n); }*/
    M get(int a, int b, bool debug = true) { return query_bottomup(a, min(b, n), debug); }
    M get(int b = inf, bool debug = true) { return query_bottomup(0, min(b, n), debug); }
    M operator()(int b = inf) { return get(0, b); }
    M operator()(int a, int b) { return get(a, b); }
    M operator[](int k) { return seg[k + n - 1]; }
    //r)でv以下を満たす最右のindexを返す
    int most_r(int r, M v) {        M d = get(0, r, false);        if (get(0, r, false) > v) {            err("most_r : ", r, ")  <= ", v, " :  ", -1);            debu();            return -1;        }        int l = 0;        while (r - l > 1) {            int m = (l + r) >> 1;            if (get(m, r, false) <= v) { l = m; } else { r = m; }        }        err("most_r : ", r, ")  <= ", v, " :  ", l);        debu();        return l;    }
    int most_r(M v) { return most_r(n, v); }
    //[lで v以下を満たす最左のindexを返す
    int most_l(int l, M v) {        if (get(l, n, false) > v) {            err("most_l : ", "[" , l, "<= ", v, " :  ", -1);            debu();            return -1;        }        int r = n;        while (r - l > 1) {            int m = (l + r) >> 1;            if (get(l, m, false) <= v) { r = m; } else { l = m; }        }        err("most_l : ", "[" , l, "<= ", v, " :  ", l);        debu();        return l;    }
    int most_l(M v) { return most_l(0, v); }
#ifdef _DEBUG
    void debu() {        rep(i, min(n, 10ll)) {            int v = operator[](i);            if (v == MIN(ll) || v == MAX(ll)) { cerr << "e "; } else { cerr << v << " "; }        }        cerr << "" << endl << endl;    }    void debup(int k, int v) {        cerr << "upd : [" << k << "] = " << v << endl;        debu();    }    void debge(int l, int r, M v) {        cerr << "get : [" << l << ", " << r << ") = " << v << endl;        debu();    }
#else
    void debu(){;}    void debup(int k,int v){;}    void debge(int l,int r,M v){;}/*@formatter:on*/
#endif
};


