  while (!que.empty()) {
    auto q = que.top();
    que.pop();
    int u = q.second;
    for (auto g : G[u]) {
      int v = g.first, c = g.second;
      if (chmin(dist[v], dist[u] + c)) {
        que.push(make_pair(dist[v], v));
