struct event{
    ll loc, val, sgn;
    bool operator<(const event& e) const{
        if (loc == e.loc) return sgn == 1;
        return loc < e.loc;
    }

    bool operator>(const event& e) const{
        if (loc == e.loc) return sgn == -1;
        return loc > e.loc;
    }

    tuple<ll, ll, ll> get_value(){return make_tuple(loc, val, sgn);}
};

