        a--; b--;
        for(ll i=a;i<=b;i++){
            edge e = {i, c};
            G[a].push_back(e);
        }
    }
    dijkstra(0);
    if(d[V-1] != INF)
        cout << d[V-1] << endl;
    else
        cout << -1 << endl;
}

