template <typename T>
struct Graph{
  using weight_type = T;
  using edge_type = Edge<T>;

  std::vector<std::vector<Edge<T>>> data;

  auto& operator[](size_t i){return data[i];}
  const auto& operator[](size_t i) const {return data[i];}

  auto begin() const {return data.begin();}
  auto end() const {return data.end();}

  Graph(){}
  Graph(int N): data(N){}

  bool empty() const {return data.empty();}
  int size() const {return data.size();}

  void add_edge(int i, int j, T w, int index = -1){
    data[i].emplace_back(i, j, w, index);
  }

  void add_undirected(int i, int j, T w, int index = -1){
    add_edge(i, j, w, index);
    add_edge(j, i, w, index);
  }

  template <size_t I, bool DIRECTED = true, bool WEIGHTED = true>
  void read(int M){
    for(int i = 0; i < M; ++i){
      int u, v; std::cin >> u >> v;
      u -= I;
      v -= I;
      T w = 1;
      if(WEIGHTED) std::cin >> w;
      if(DIRECTED) add_edge(u, v, w, i);
      else add_undirected(u, v, w, i);
    }
  }
};

template <typename T>
using Tree = Graph<T>;


/**
 * @title Dijkstra algorithm
 * @docs dijkstra.md
 */
template <typename T>
auto dijkstra(const Graph<T> &graph, std::vector<int> src){
  using P = std::pair<T, int>;

  const int n = graph.size();
  std::vector<std::optional<T>> dist(n);

  std::vector<bool> check(n, false);
  std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

  for(auto s : src){
    dist[s] = 0;
    pq.emplace(0, s);
  }

  while(not pq.empty()){
    const auto [d, i] = pq.top(); pq.pop();

    if(check[i]) continue;
    check[i] = true;

    for(auto &e : graph[i]){
      if(not dist[e.to]){
        dist[e.to] = d + e.cost;
        pq.emplace(*dist[e.to], e.to);
      }else{
        if(*dist[e.to] > d + e.cost){
          dist[e.to] = d + e.cost;
          if(not check[e.to]) pq.emplace(*dist[e.to], e.to);
        }
      }
    }
  }

  return dist;
}

template <typename T>
class RangeGraph : public Graph<T>{
  using super = Graph<T>;

  int k, N;
  int calc_size(int N) const {
    int ret = 1;
    while(ret < N) ret *= 2;
    return ret;
  }

public:
  RangeGraph(int N): Graph<T>(5 * (k = (calc_size(N)))), N(N){
    for(int i = 2; i < 2 * k; ++i){
      super::add_edge(k + (i >> 1), k + i, 0);
      super::add_edge(3 * k + i, 3 * k + (i >> 1), 0);
    }

    for(int i = 0; i < N; ++i){
      super::add_edge(2 * k + i, i, 0);
      super::add_edge(i, 4 * k + i, 0);
    }
  }

  void add_edge(int i, int j, T w){
    super::add_edge(i, j, w);
  }

  void add_edge(int i, std::pair<int, int> p, T w){
    auto [l, r] = p;
    for(l += k, r += k; l < r; l >>= 1, r >>= 1){
      if(l & 1) super::add_edge(i, l + k, w), ++l;
      if(r & 1) --r, super::add_edge(i, r + k, w);
    }
  }

  void add_edge(std::pair<int, int> p, int i, T w){
    auto [l, r] = p;
    for(l += k, r += k; l < r; l >>= 1, r >>= 1){
      if(l & 1) super::add_edge(l + 3 * k, i, w), ++l;
      if(r & 1) --r, super::add_edge(r + 3 * k, i, w);
    }
  }

  void add_edge(std::pair<int, int> p, std::pair<int, int> q, T w){
    int x = super::size();
    super::data.emplace_back();
    int y = super::size();
    super::data.emplace_back();

    add_edge(p, x, 0);
    add_edge(x, y, w);
    add_edge(y, q, 0);
  }
};




