int tree[maxn<<2],tag[maxn<<2];
#define ls(u) (u<<1)
#define rs(u) (u<<1|1)
#define mid ((l+r)>>1)
inline void pushup(int u)
{
    tree[u]=min(tree[ls(u)],tree[rs(u)]);
}
inline void build(int pos,int l,int r)
{
	tree[pos]=llinf;
	tag[pos]=llinf;
	if(l==r) return;
	build(ls(pos),l,mid);
	build(rs(pos),mid+1,r);
	pushup(pos); 
}
void pushdown(int u)
{
    if(tag[u]<tag[ls(u)])
    {
        tree[ls(u)]=min(tree[ls(u)],tag[u]);
        tag[ls(u)]=tag[u];
    }
    if(tag[u]<tag[rs(u)])
    {
        tree[rs(u)]=min(tree[rs(u)],tag[u]);
        tag[rs(u)]=tag[u];
    }
    tag[u]=llinf;
}
inline void asv(int pos,int l,int r,int L,int R,int val)
{
    if(L<=l&&r<=R)
    {
        tag[pos]=min(tag[pos],val);
        tree[pos]=min(tree[pos],val);
        return;
    }
    if(tag[pos]!=llinf) pushdown(pos);
    if(L<=mid) asv(ls(pos),l,mid,L,R,val);
    if(R>mid) asv(rs(pos),mid+1,r,L,R,val);
    pushup(pos);
}
inline int query(int pos,int l,int r,int L,int R)
{
    if(L<=l&&r<=R) return tree[pos];
    int ret=llinf;
    if(tag[pos]!=llinf) pushdown(pos);
    if(L<=mid) ret=min(ret,query(ls(pos),l,mid,L,R));
    if(R>mid) ret=min(ret,query(rs(pos),mid+1,r,L,R));
    return ret;
}
