ll d[MAX];

void dijkstra(int s){
    priority_queue<P,vector<P>,greater<P>> pq;
    rep(i,v) d[i] = INF;
    d[s]=0;
    pq.push({0,s});
    while(!pq.empty()){
        P p = pq.top(); pq.pop();
        int v = p.second;
        if(d[v]<p.first) continue;
        for(edge u:G[v]){
            if(d[u.to]>d[v]+u.cost){
                d[u.to]=(ll)d[v]+u.cost;
                pq.push({d[u.to],u.to});
            }
        }
    }
}

