    return t1.r<t2.r;
  });

  ll itr=0;

  SegmentTree<ll> seg(n+2,MAX,[](ll a,ll b){return std::min(a,b);});

  seg.update(0,0,true);

  rep(i,1,n){
    while(itr!=n&&edge[itr].r==i){
      seg.update(i,seg.query(edge[itr].l,edge[itr].r)+edge[itr].cost,false);

      itr++;
    }
  }

