		if (lhs.l != rhs.l) return lhs.l < rhs.l;
		return lhs.r < rhs.r;
	});

	SegTree segt(n + 1, INT64_MAX);
	segt.update(1, 0);
	for (auto& b : bs) {
		int64_t v = segt.query(b.l);
		if (v == INT64_MAX) {
			cout << -1 << endl;
			return 0;
		}

		segt.update(b.r, v + b.c);
	}

	int64_t v = segt.query(n);
	if (v == INT64_MAX) {
		cout << -1 << endl;
	}
	else {
		cout << v << endl;
	}

	return 0;
}

