const ll INF = 1e18;

struct SqrtDecomposition{
    int n, sqrtn, k;
    VL dat, lazy;
    vector<bool> lazyflag;

    void init(int x){
        n = x;
        sqrtn = sqrt(n) + 1;
        k = (n + sqrtn - 1) / sqrtn;
        dat.assign(sqrtn * k, INF);
        lazy.assign(k, INF);
        lazyflag.assign(k, false);
    }

    void eval(int b){
        if (!lazyflag[b]) return;
        lazyflag[b] = false;
        FOR(i, sqrtn * b, sqrtn * (b+1) - 1){
            chmin(dat[i], lazy[b]);
        }
        lazy[b] = INF;
    }

    // [l, r)
    void update(int l, int r, ll x){
        REP(b,k){
            int p = sqrtn * b;
            int q = sqrtn * (b+1);
            if (q <= l || r <= p) continue;
            if (l <= p && q <= r){
                lazyflag[b] = true;
                chmin(lazy[b], x);
            }else{
                eval(b);
                FOR(i,max(l,p),min(r,q)-1){
                    chmin(dat[i], x);
                }
            }
        }
    }

    // [l, r)
    ll query(int l, int r){
        ll ret = INF;
        REP(b,k){
            int p = sqrtn * b;
            int q = sqrtn * (b+1);
            if (q <= l || r <= p) continue;
            if (l <= p && q <= r){
                // ret = min(ret, buk[b]);
            }else{
                eval(b);
                FOR(i,max(l,p),min(r,q)-1){
                    // ret = min(ret, dat[i]);
                    chmin(ret, dat[i]);
                }
            }
        }
        return ret;
    }
};

int main() {
    int n, m;
    cin >> n >> m;
    VVL l2r(n), l2c(n);
    REP(i,m){
        int l = in() - 1, r = in(), c = in();
        l2r[l].push_back(r);
        l2c[l].push_back(c);
    }

    SqrtDecomposition sd;
    sd.init(n);
    sd.update(0, 1, 0);

    REP(i,n-1){
        ll x = sd.query(i, i + 1);
        if (x == INF){
            cout << -1 << endl;
            return 0;
        }
        REP(j,l2r[i].size()){
            int r = l2r[i][j];
            ll c = l2c[i][j];
            sd.update(i + 1, r, x + c);
        }
    }
    ll ans = sd.query(n - 1, n);
    cout << ans << endl;

    return 0;
}

