ll mymin(int l, int r) {
	ll ret = INF;
	l += N;
	r += N;
	while (l <= r) {
		ret = min(ret, tt[l]);
		ret = min(ret, tt[r]);
		l++;
		l >>= 1;
		r--;
		r >>= 1;
	}
	return ret;
}

void myup(int pos, ll val) {
	pos += N;
	while (pos) {
		tt[pos] = min(tt[pos], val);
