const int N = 220000;

int L[N], R[N], id[N];
long long C[N], t[N];

void add(int u, long long w) {
	for (; u; u -= u & -u) t[u] = min(t[u], w);
}

long long get(int u) {
	long long ret = LLONG_MAX;
	for (; u < N; u += u & -u) ret = min(ret, t[u]);
	return ret;
}

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	int n, m; cin >> n >> m;
