	for (int i = 0; i < m; i++) id[i] = i;
	sort(id, id + m, [&](int u, int v) {
		if (L[u] != L[v]) return L[u] < L[v];
		return R[u] < R[v];
	});
	for (int i = 0; i < N; i++) t[i] = LLONG_MAX;
	add(1, 0);
	for (int i = 0; i < m; i++) {
		int u = id[i];
		int st = L[u], en = R[u]; long long w = C[u];
		long long now = get(st);
		if (now != LLONG_MAX) add(en, now + w);
	}
	long long ans = get(n);
	if (ans == LLONG_MAX) ans = -1;
	cout << ans << "\n";
	return 0;
}

