void warshall_floyd(int n,vector<vector<ll>> &d) {
  for (int k = 0; k < n; k++){       // 経由する頂点
    for (int i = 0; i < n; i++) {    // 始点
      for (int j = 0; j < n; j++) {  // 終点
        d[i][j] = std::min(d[i][j], d[i][k] + d[k][j]);
      }
    }
  }
};


