#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for(int i = 0; i < (n); ++i)

typedef long long ll;
typedef pair<ll, int> P;

const int MAX = 1e5 + 5;
const ll INF = 1e14 + 5;
const int MOD = 1e9 + 7;

struct edge { int to, cost; };
vector<edge> G[MAX];
ll d[MAX];

int main(){
    int N, M;
    cin >> N >> M;

    rep(i, M) {
        int l, r, c;
        cin >> l >> r >> c;
        l--, r--;
        edge e = edge();
        e.to = r, e.cost = c;
        G[l].push_back(e);
    }

    for (int i = 1; i < N; ++i) {
        edge e = edge();
        e.to = i - 1, e.cost = 0;
        G[i].push_back(e);
    }

    rep(i, N) {
        d[i] = INF;
    }

    d[0] = 0;
    priority_queue<P, vector<P>, greater<P> > que;
    que.push(P(0, 0));

    while (!que.empty()) {
        P p = que.top(); que.pop();
        int v = p.second;

        if (d[v] < p.first) continue;

        for (auto e : G[v]) {
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }

    if (d[N - 1] != INF) {
        cout << d[N - 1] << endl;
    } else {
        cout << -1 << endl;
    }
}

