struct edge{
    int to;
    ll cost;
};

int main(){
    int v,n;
    cin >> v >> n;
    ll d[v];
    vector<edge> G[v];
    rep(i,n){
        int a,b;
        ll c;
        cin >> a >> b >> c;
        a--; b--;
        for(int j=a;j<=b;j++){
            for(int k=j;k<=b;k++){
                edge e = {k,c};
                G[j].push_back(e);
            }
        }
    }
    priority_queue<P,vector<P>,greater<P>> pq;
    rep(i,v) d[i]=INF;
    d[0]=0;
    pq.push(P(0,0));
    while(!pq.empty()){
        P p=pq.top();
        pq.pop();
        ll c = p.second;
        if(d[c]<p.first) continue;
        rep(i,G[c].size()){
            edge e = G[c][i];
            if(d[e.to] > d[c]+e.cost){
                d[e.to] = d[c] + e.cost;
                pq.push(P(d[e.to],e.to));
            }
        }
    }
    if(d[v-1]!=INF) cout << d[v-1] << endl;
    else cout << -1 << endl;
}

