	for (int i = 1; i < n; ++i) {
		AddEdge(i + 1, i, 0);
	}
}

void solve() {
	mset(dis, 0x3f);
	mset(vis, 0);
	dis[1] = 0;
	q.push(make_pair(0, 1));
	while (!q.empty()) {
		int u = q.top().se;
		q.pop();
		if (vis[u]) continue;
		vis[u] = 1;
		for (int i = first[u]; i; i = e[i].nxt) {
			int v = e[i].v;
			if (dis[v] > dis[u] + e[i].w) {
				dis[v] = dis[u] + e[i].w;
				q.push(make_pair(-dis[v], v));
			}
		}
	}
	printf("%lld\n", (dis[n] == INF)? -1 : dis[n]);
}

int main() {
	init();
	solve();
	return 0;
}

