    vector<path> pathes;
    cin >> n >> m;
    for (int i=0;i<n;i++){
        line.push_back(-1);
    }
    for (int i=0;i<m;i++){
        cin >> l >> r >> c;
        path p;
        p.l = l-1;
        p.r = r-1;
        p.c = c;
        pathes.push_back(p);
    }
    sort(pathes.begin(), pathes.end(), compareTwoPath);
    line[0] = 0;
    for (int i=0;i<pathes.size();i++){
        path p = pathes[i];
        if (line[p.l] == -1){
            cout << -1;
            return 0;
        }
        else {
