ll query(int left,int right,int l,int r,int i)
{
	if(left>=l&&right<=r)
	return tree[i];
	int mid=(left+right)/2;
	if(r<=mid)
	return query(left,mid,l,r,2*i);
	if(l>mid)
	return query(mid+1,right,l,r,2*i+1);
	ll t2=query(mid+1,right,mid+1,r,2*i+1);
	ll t1=query(left,mid,l,mid,2*i);

	return min(t1,t2);
}


void update(int left,int right,int pos,int d,int i)
{
	if(left==right)
	{
		tree[i]=dp[pos];
	 	return;
	}

	int mid=(left+right)/2;
	if(pos<=mid)
	update(left,mid,pos,d,2*i);
	else
	update(mid+1,right,pos,d,2*i+1);
	tree[i]=min(tree[2*i],tree[2*i+1]);

}

