struct edge{
  int to;
  T cost;
  edge(int to,T cost):to(to),cost(cost){}
};

vector<int>pre;

template<typename T>
vector<T> dijkstra(vector<vector<edge<T>>> &g,int s){//sは始点
  const auto INFTY=numeric_limits<T>::max();
  vector<T>dist(g.size(),INFTY);
  pre.resize(g.size(),-1);
  using P=pair<T,int>;//firstは最短距離,secondは頂点の番号
  priority_queue<P,vector<P>,greater<P>>pq;
  dist[s]=0;
  pq.emplace(dist[s],s);

  while(!pq.empty()){
    auto x=pq.top();pq.pop();
    int v=x.second;
    if(dist[v]<x.first)continue;//最短距離でなければ飛ばす
    for(auto e:g[v]){
      if(dist[e.to]>dist[v]+e.cost){
        pre[e.to]=v;
        dist[e.to]=dist[v]+e.cost;
        pq.emplace(dist[e.to],e.to);
      }
    }
  }
  return dist;
}

template<typename T>
vector<T>get_path(int t){//頂点tへの最短経路
    vector<T>path;
    for(;t!=-1;t=pre[t]){
      path.push_back(t);
    }
    reverse(path.begin(),path.end());
    return path;
}


