//区間更新、区間Min。更新は新しい方ではなく、値の小さい方を優先。
const int DEPTH = 17;
const int INF = 1e+16;
struct RUQ {
	int d[1 << (DEPTH + 1)];
	RUQ() {
		int i;
		rep(i, (1 << (DEPTH + 1))) d[i] = INF;
	}

	//[l, r)
	void update(int l, int r, int x, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (a >= r || b <= l) return;
		if (l <= a && b <= r) {
			d[id] = min(d[id], x);
			return;
		}
		update(l, r, x, a, (a + b) / 2, id * 2 + 1);
		update(l, r, x, (a + b) / 2, b, id * 2 + 2);
	}

	int query(int pos) {
		int ret = INF;

		pos += (1 << DEPTH) - 1;
		ret = min(ret, d[pos]);
		while (pos > 0) {
			pos = (pos - 1) / 2;
			ret = min(ret, d[pos]);
		}
		return ret;
	}
};

