	m += 2;

	sort(tupl, tupl + m);

	rep(i, m) {
		l[i] = get<0>(tupl[i]);
		r[i] = get<1>(tupl[i]);
		c[i] = get<2>(tupl[i]);
	}

	//rep(i, m) { cout << l[i] << ", " << r[i] << ", " << c[i] << endl; }

	ruq.update(0, 1, 0);	//dp[0] = 0
	rep(i, m - 1) {
