Int sm[4 * MA];

void init(int x, int L, int R) {
  sm[x] = INFLL;
  if (R - L == 1) return;
  init(2 * x + 0, L, (L + R) / 2);
  init(2 * x + 1, (L + R) / 2, R);
}

void update(int x, int L, int R, int l, int r, Int v) {
  if (L == l && R == r) {
    chmin(sm[x], v);
    return;
  }
  const int M = (L + R) / 2;
  if (l < M) update(2 * x + 0, L, M, l, min(r, M), v);
  if (r > M) update(2 * x + 1, M, R, max(l, M), r, v);
}

Int query(int x, int L, int R, int k) {
  if (R - L == 1 && L == k) {
    return sm[x];
  }
  const int M = (L + R) / 2;
  if (k < M) return min(sm[x], query(2 * x + 0, L, M, k));
  else       return min(sm[x], query(2 * x + 1, M, R, k));
}

