struct Seg {
    int L, R, C;

    bool operator<(const Seg s) const {
        if (L == s.L) {
            if (R == s.R) return C < s.C;
            return R < s.R;
        }
        return L < s.L;
    }
};

int main() {
    //freopen("in.txt", "r", stdin);
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, M; cin >> N >> M;
    Seg s[M];
    FOR(i,0,M-1){
        int L, R, C; cin >> L >> R >> C;
        s[i] = { L, R, C };
    }

    sort(s,s+M);
    set<pair<int, ll> > ans;
    int idx = 0;
    for(; idx < M && s[idx].L == 1; ++idx) {
        auto cur = mp(s[idx].R, (ll)s[idx].C);
        while (!ans.empty() && prev(ans.end())->fi >= cur.fi && prev(ans.end())->sc >= cur.sc)
            ans.erase(prev(ans.end()));
        if (ans.empty() || prev(ans.end())->fi < cur.fi)
            ans.insert(cur);
    }

    for(; idx < M; ++idx) {
        auto it = ans.lower_bound({ s[idx].L, 0 });
        if (it == ans.end()) continue;

        auto cur = mp(s[idx].R, it->sc + s[idx].C);

        auto y = ans.insert(cur).fi;
        if (y != ans.begin() && prev(y)->fi == y->fi) ans.erase(y);
        else if (next(y) != ans.end() && y->sc >= next(y)->sc) ans.erase(y);
        else {
            if (next(y) != ans.end() && y->fi == next(y)->fi) ans.erase(next(y));
            while (y != ans.begin() && prev(y)->sc >= y->sc) ans.erase(prev(y));
        }

        //for(auto x : ans) { cout << x.fi << "," << x.sc << "  "; } cout << endl;
    }

    if (ans.empty() || prev(ans.end())->fi != N) cout << -1;
    else cout << prev(ans.end())->sc;
}

