template<class Monoid> struct SegmentTree {
    using F = function<Monoid(Monoid, Monoid)>;
    using G = function<Monoid(int, Monoid)>;
    int n;
    Monoid id;
    vector<Monoid> data;
    F op;
    G ud;

    SegmentTree(int sz, F f, G g, Monoid def) : op(f), ud(g) {
        n = 1; id = def;
        while (n < sz) n *= 2;
        data = vector<Monoid>(2*n-1, id);
    }

    void update (int i, Monoid x) {
        i += n - 1;
        data[i] = ud(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = op(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    Monoid query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return id;
        if (a <= l && r <= b) return data[k];
        Monoid vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        Monoid vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return op(vl, vr);
    }
};


int main() {
    int N, M;
    cin >> N >> M;
    vector<pair<pair<int, int>, long long>> C;
    for (int i = 0; i < M; i++) {
        int l, r; long long c;
        cin >> l >> r >> c;
        C.emplace_back(make_pair(l, r), c);
    }
    sort(C.begin(), C.end());

    auto f = [](long long a, long long b) { return min(a, b); };
    auto g = [](int i, long long x) { return x; };
    SegmentTree<long long> sg(N+1, f, g, INF);
    sg.update(1, 0);
    ///*
    for (int i = 0; i < M; i++) {
        int l, r; long long c = C[i].second;
