const ll INF = 1LL << 61;
struct P {
  int L;
  int R;
  int C;
};

const int MAX_N = 112345;
const int MAX_M = 112345;
vector<P> p[MAX_M];

struct RMQ {
  using Val = ll;
  int n;
  vector<Val> vs;
  void clear(int N) {
    for (n = 1; n < N; n <<= 1);
    vs.assign(n * 2, INF);
  }
  Val get(int pos) {
    return vs[n+pos];
  }
  void update(int pos, Val val) {
    vs[n+pos] = val;
    for (int k = (n+pos)/2; k > 0; k >>= 1)
      vs[k] = min(vs[2*k], vs[2*k+1]);
  }
  // [l, r) の最小値を返す
  Val query(int l, int r) {
    return query(0, n, 1, l, r);
  }
  Val query(int nl, int nr, int k, int l, int r) {
    if (r <= nl || nr <= l) return INF;
    if (l <= nl && nr <= r) return vs[k];
    Val x = query(nl, (nl+nr)/2, 2*k  , l, r);
    Val y = query((nl+nr)/2, nr, 2*k+1, l, r);
    return min(x, y);
  }
};

