	}
};
std::priority_queue<Point>que;
int n,m,head[MAXN],cnt,u[MAXN],v[MAXN];bool vis[MAXN];long long dis[MAXN],w[MAXN];Edge edge[MAXN*3];
void AddEdge(int u,int v,long long w)
{
	//printf("%d %d %lld\n",u,v,w);
	edge[++cnt].u=u;edge[cnt].v=v;edge[cnt].w=w;
	edge[cnt].next=head[u];head[u]=cnt;
}
void Dijkstra()
{
	Point tmp,temp;
	memset(dis,0x3f3f3f,sizeof(dis));
	temp.v=0;temp.w=0;dis[0]=0;
	que.push(temp);
	while(!que.empty())
	{
		temp=que.top();que.pop();
		if(vis[temp.v]) continue;
		//printf("%d\n",temp.v);
		vis[temp.v]=1;
		for(int i=head[temp.v];i;i=edge[i].next)
		{
			//printf("%d*\n",edge[i].v);
			if(dis[edge[i].v]>dis[temp.v]+edge[i].w)
			{
				//printf("%d ADD\n",edge[i].v);
				dis[edge[i].v]=dis[temp.v]+edge[i].w;
				tmp.v=edge[i].v;
				tmp.w=dis[edge[i].v];
				que.push(tmp);
			}
		}
	}
}
bool cover(int s1,int t1,int s2,int t2)
{
	if(t2<=t1) return 0;
	return (s2>=s1&&t2<=t1)||(((s2<=s1&&t2>=s1)||(s2<=t1&&t2>=t1)));
}
