int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll N, M;
  cin >> N >> M;

  vector<pair<pair<ll, ll>, ll>> edges(M);

  rep(i, M) {
    ll l, r, c;
    cin >> l >> r >> c;
    l--, r--;
    edges[i] = {pair<ll, ll>(r, l), c};
  }

  sort(edges.begin(), edges.end());

  V<ll> dp(N, 1e18);
  dp[N - 1] = 0;

  V<bool> visited(M);

  for (ll i = N - 1; i >= 0; i--) {
    if (dp[i] == 1e18) continue;
    pair<pair<ll, ll>, ll> f = {pair<ll, ll>(i - 1, 1e18), 1e18};
    auto it = lower_bound(edges.begin(), edges.end(), f);
    it++;  // i で終わる最初のやつ
    ll ii = it - edges.begin();
    auto it2 = it;
    ll ii2 = ii;
    while (true) {
      visited[ii] = true;
      auto edge = *it;
      if (edge.first.second > i) break;
      ll l = edge.first.second;
      chmin(dp[l], dp[i] + edge.second);
      if (it == edges.end()) break;
      it++;
      ii++;
      if (visited[ii]) break;
    }

    ii2--;
    it2--;
    while (ii2 >= 0) {
      visited[ii2] = true;
      auto edge = *it2;
      if (edge.first.first < i) break;
      ll l = edge.first.second;
      chmin(dp[l], dp[i] + edge.second);
      if (it2 == edges.begin()) break;
      it2--;
      ii2--;
      if (visited[ii2]) break;
    }
  }

  ll res = dp[0] == 1e18 ? -1 : dp[0];
  cout << res << endl;
  return 0;
}

