void update(int node,int st,int en,int l,int r,long long val)
{
	if (en<l || st>r || r<l)
	return;
	if (l<=st && en<=r)
	{
		tree[node]=min(tree[node],val);
		return;
	}
	int mid=(st+en)/2;
	update(2*node,st,mid,l,r,val);
	update(2*node+1,mid+1,en,l,r,val);
}
long long query(int node,int st,int en,int idx)
{
	long long ans=tree[node];
	if (st!=en)
	{
		int mid=(st+en)/2;
		if (st<=idx && idx<=mid)
		ans=min(ans,query(2*node,st,mid,idx));
		else
		ans=min(ans,query(2*node+1,mid+1,en,idx));
	}
	return ans;
}
