struct SegmentTree{
	struct Node
	{
		ll x,l;
		Node() {
			x = 1e18;
			l = 1e18;
		};
		Node(ll x,ll l): x(x) , l(l) {};
	};
	ll max_n;
	Node* tree;
	SegmentTree(ll max_n){
		this->max_n = max_n;
		tree = new Node[4*max_n+2];
		For(i,0,4*max_n+2) tree[i] = Node(1e18,1e18);
	}

	void propagate(ll ti){
		tree[ti].x = min(tree[ti].x,tree[ti].l);
		tree[2*ti].l = min(tree[2*ti].l,tree[ti].l);
		tree[2*ti+1].l = min(tree[2*ti+1].l,tree[ti].l);
	}

	void up(ll ti){
		tree[ti].x = min(min(tree[2*ti].x,tree[2*ti].l) , min(tree[2*ti+1].x,tree[2*ti+1].l));
	}

	void update(ll ti,ll l,ll r,ll left,ll right,ll x){
		if(l>right || r<left) return;
		if(l>=left && r<=right){
			tree[ti].l = min(tree[ti].l,x);
			tree[ti].x = min(tree[ti].x,x);
			return;
		}

		propagate(ti);

		ll mid = (l+r)/2;
		update(2*ti,l,mid,left,right,x);
		update(2*ti+1,mid+1,r,left,right,x);

		up(ti);

	}

	ll query(ll ti,ll l,ll r,ll left,ll right){
		if(l>right || r<left) return 1e18;
		if(l>=left && r<=right){
			return min(tree[ti].x,tree[ti].l);
		}

		propagate(ti);

		ll mid = (l+r)/2;
		ll t1 = query(2*ti,l,mid,left,right);
		ll t2 = query(2*ti+1,mid+1,r,left,right);

		up(ti);

		return min(t1,t2);
	}

	void update(ll left,ll right,ll x){
		update(1,0,max_n-1,left,right,x);
	}
	ll query(ll left,ll right){
		return query(1,0,max_n-1,left,right);
	}

};

