struct dijkstra{
  struct Node{
    vector<int> edges_to;
    vector<int> edges_cost;
    bool done;
    int cost=-1;
  };
  vector<Node> graph;
  void init(int N){
    graph.resize(N);
  }
  void add(int from, int to, int cost){
    graph[from].edges_to.push_back(to);
    graph[from].edges_cost.push_back(cost);
  }
  void shortest(int start){
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> d;
    d.push(make_pair(0,start));
    while(!d.empty()){
      pair<int,int> p = d.top();
      d.pop();
      Node &point = graph[p.second];
      if(point.done) continue;
      point.done = true;
      point.cost = p.first;
      for(int i = 0; i < (int)point.edges_to.size(); i++){
        if(graph[point.edges_to[i]].done)continue;
        d.push(make_pair(point.cost+point.edges_cost[i],point.edges_to[i]));
      }
    }
  }
};

