struct node {
  ll L, R, c;
  node() {}
  node(ll L, ll R, ll c) : L(L), R(R), c(c) {}
};

bool comp(node &a, node &b) { return a.L < b.L; }
int32_t main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);

  ll n, m;
  cin >> n >> m;

  node arr[m + 5];

  for (ll i = 1; i <= m; i++) {
    cin >> arr[i].L >> arr[i].R >> arr[i].c;
  }

  sort(arr + 1, arr + m + 1, comp);

  ll curr = 1;

  ll ptr = 1;

  SegTree obj;
  obj.init(n);
  for (ll i = 1; i <= n; i++) {
    obj.update(i, i, inf);
  }
  obj.update(1, 1, 0);

  while (ptr <= m && arr[ptr].L <= curr) {

    ll L = arr[ptr].L, R = arr[ptr].R, c = arr[ptr].c;
    ll min1 = obj.query(L, R).mn;

    obj.update(L, R, min1 + c);

    curr = max(curr, R);
    ptr++;
  }

  ll ans = obj.query(n, n).mn;
  if (ans > 1e15)
    cout << -1 << en;
  else
    cout << ans << en;

  return 0;
}

