//0-indexed
template <class T>
class SegmentTree
{
	int size;
	T def;
	vector<T> data;
	function<T(T, T)> f;

public:
	SegmentTree<T>(int _size, T _def, function<T(T, T)> _f) : f(_f), def(_def), size(1)
	{
		while (size < _size)
			size <<= 1;
		data = vector<T>(size * 2, def);
	}
	//bottom-up implementation
	//query for[l, r)
	T query(int l, int r)
	{
		T L = def, R = def;
		for (l += size, r += size; l < r; l >>= 1, r >>= 1)
		{
			if (l & 1)
				L = f(L, data[l++]);
			if (r & 1)
				R = f(data[--r], R);
		}
		return f(L, R);
	}
	void update(int idx, T val)
	{
		idx += size;
		data[idx] = val;
		while (idx > 1)
		{
			idx >>= 1;
			data[idx] = f(data[2 * idx], data[2 * idx + 1]);
		}
	}
	T operator[](int idx)
	{
		return data[idx + size];
	}
};

class Solution {
public:
