			vlrc[i] = make_tuple(l-1, r, c);
		}
		sort(vlrc.begin(), vlrc.end());
		SegmentTree<long long> st(n, 0x3f3f3f3f3f3f3f3f, [](long long a, long long b){return min(a, b);});
		st.update(0, 0);
		for(int i=0; i < m; i++){
			int l,r;
			long long c;
			tie(l, r, c) = vlrc[i];
			long long d = st.query(l, n);
