const int MAX_N = 1e5 + 5;
int n, q;
vector<pair<int, int> > Q[MAX_N];
#define INF 1e17

long long tree[4 * MAX_N], lazy[4 * MAX_N];

void pushDown(int p, int l, int r){
    if (lazy[p] != INF){
        tree[p] = min(tree[p], lazy[p]);
        if (l != r){
            lazy[2 * p] = min(lazy[2 * p], lazy[p]);
            lazy[2 * p + 1] = min(lazy[2 * p + 1], lazy[p]);
        }
        lazy[p] = INF;
    }
}

void updateSegment(int st, int en, long long v, int p = 1, int l = 0, int r = n - 1){
    if (l >= st && r <= en)
    {
        lazy[p] = min(lazy[p], v);
        pushDown(p, l, r);
        return;
    }
    pushDown(p, l, r);
    if (l > en || r < st)
        return;
    int mid = (l + r)/2;
    updateSegment(st, en, v, 2 * p, l, mid);
    updateSegment(st , en ,v,  2 * p + 1, mid + 1, r);
    tree[p] = min(tree[2 * p], tree[2 * p + 1]);
}

long long get(int st, int en, int p = 1, int l = 0, int r = n - 1){
    pushDown(p, l, r);
    if ( l >= st && r <= en)
        return tree[p];
    if (l > en || r < st)
        return INF;
    int mid = (l+r)/2;
    return min(get(st, en, 2 * p, l, mid), get(st, en, 2 * p + 1, mid + 1 ,r));
}


int main()
{
