        --l; --r;
        Q[l].push_back({r, c});
    }

    updateSegment(0, 0, 0);

    for (int i = 0; i < n; ++i){
        long long d = get(i, i);
//        cout << d << endl;
        for (auto p : Q[i]){
            int r = p.first, c = p.second;
            updateSegment(i, r, min((ll)INF, c + d));
        }
    }

    long long ans = get(n - 1, n - 1);

    if (ans >= INF){
        cout << -1;
    }
    else
        cout << ans;
    return 0;
}

