vi dijkstra(int from,vvp g){
    vi dis(g.size(),inf);
    dis[from]=0;
    SPQ(P) pq;
    pq.push(P(0,from));
    while(!pq.empty()){
        auto t=pq.top();pq.pop();
        if(t.fi!=dis[t.se])continue;
        for(auto x:g[t.se]){
            if(chmin(dis[x.fi],t.fi+x.se))pq.push(P(dis[x.fi],x.fi));
        }
    }
    return dis;
}
