constexpr int INF = 0x3f3f3f3f;
constexpr int64_t LINF = 0x3f3f3f3f3f3f3f3fLL;
// }}} End

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    size_t N, M; cin >> N >> M;

    vector<pair<size_t, intmax_t>> G[N];
    vector<int> imos(N + 1);
    for (size_t i = 0; i < M; ++i) {
        size_t l, r, c; cin >> l >> r >> c;
        l--, r--;
        imos[l]++, imos[r + 1]--;
        G[l].emplace_back(r, c);
    }

    for (size_t i = 1; i <= N; ++i) {
        imos[i] += imos[i - 1];
        if (imos[i] != 0) {
            G[i].emplace_back(i - 1, 0);
        }
    }

    vector<intmax_t> cost(N, LINF);
    cost[0] = 0;
    priority_queue<pair<intmax_t, size_t>, vector<pair<intmax_t, size_t>>, greater<>> que;
    que.emplace(0, 0);

    while (!que.empty()) {
        intmax_t nowCost = que.top().first;
        size_t nowNode = que.top().second;
        que.pop();

        if (cost[nowNode] < nowCost) continue;

        for (const auto &nextNode: G[nowNode]) {
            if (chmin(cost[nextNode.first], cost[nowNode] + nextNode.second)) {
                que.emplace(cost[nextNode.first], nextNode.first);
            }
        }
    }

    cout << (cost[N - 1] == LINF ? -1: cost[N - 1]) << "\n";

    return 0;
}

