template<typename Monoid>
struct SegmentTree {
	using Op = function<Monoid(const Monoid& lhs, const Monoid& rhs)>;
	size_t width;
	vector<Monoid> node;
	Op op;
	Monoid unit;

	SegmentTree(const vector<Monoid>& elems, Op op, Monoid unit)
	: op(op)
	, unit(unit) {
		width = 1;
		while (width < elems.size()) {
			width *= 2;
		}
		node.resize(2 * width - 1, unit);
		for (size_t i = 0; i < elems.size(); i++) {
			node[i + width - 1] = elems[i];
		}
		for (size_t i = width - 2; i != numeric_limits<size_t>::max(); i--) {
			node[i] = op(node[2 * i + 1], node[2 * i + 2]);
		}
	}
	void update(size_t idx, Monoid elem) {
		idx += width - 1;
		node[idx] = elem;
		while (idx >= 1) {
			idx = (idx - 1) / 2;
			node[idx] = op(node[2 * idx + 1], node[2 * idx + 2]);
		}
	}
	Monoid query(size_t a, size_t b, size_t root) const {
		assert(0 <= a && b <= width);
		size_t left = root, right = root;
		while (left < width - 1) {
			left = 2 * left + 1;
		}
		left -= (width - 1);
		while (right < width - 1) {
			right = 2 * right + 2;
		}
		right -= (width - 1);
		right++;
		if (right <= a || b <= left) {
			return unit;
		}
		if (a <= left && right <= b) {
			return node[root];
		}
		Monoid ans_l = query(a, b, 2 * root + 1);
		Monoid ans_r = query(a, b, 2 * root + 2);
		return op(ans_l, ans_r);
	}
};

int main() {
	ll N, M;
	cin >> N >> M;
	struct Range {
		ll L;
		ll R;
		ll C;
	};
	vector<Range> ranges;
	rep(i,0,M) {
		ll l, r, c;
		cin >> l >> r >> c;
		l--;
		r--;
		ranges.push_back(Range{l, r, c});
	}
	sort(ranges.begin(), ranges.end(), 
		 [](Range lhs, Range rhs){ return lhs.R < rhs.R; });
	vector<ll> dp_init(N, numeric_limits<ll>::max());
	SegmentTree<ll> dp(dp_init, [](ll lhs, ll rhs){ return min(lhs, rhs); },
						numeric_limits<ll>::max());
	dp.update(0, 0);
	rep(i,0,M) {
		Range range = ranges[i];
		ll now = dp.query(range.R, range.R+1, 0);
		ll x = dp.query(range.L, range.R, 0);
		ll v = numeric_limits<ll>::max();
		if (x < numeric_limits<ll>::max()) {
			v = x + range.C;
		}
		dp.update(range.R, min(now, v));
	}
	ll ans = dp.query(N-1, N, 0);
	if (ans == numeric_limits<ll>::max()) {
		cout << -1 << endl;
	} else {
		cout << ans << endl;
	}
}

