static long long MAX = 	9223372036854775800;
int N,M;

struct d{
  int l;
  int r;
  int c;
};

ll graph(int ptr, ll cost, vector<d> D){
  int tmp = ptr + 1;
  long long res = MAX;
  if(D[ptr].r == N) return cost + D[ptr].c;
  for(int i = ptr + 1; D[i].l <= D[ptr].r && i < M; i++){
    if(D[i].l == D[ptr].l) continue;
    ll t = graph(i, cost + D[ptr].c, D);
    res = min(res, t);
  }
  return res;
}

