struct Edge {
    int l, r;
    ll c;
    Edge(int _l=0, int _r=0, ll _c=0): l(_l), r(_r), c(_c) {}
    bool operator < (const Edge &e) const {
        if(l != e.l) return l < e.l;
        if(c != e.c) return c < e.c;
        return r < e.r;
    }
};

template<class T> class SegmentTree {
    public:
    size_t n;          // 葉の数
    vector<T> data; // データ
    T def;          // 単位元
    function<T(T, T)> update_func;  // 点更新で使う処理
    function<T(T, T)> find_func;    // 区間クエリで使う処理

    SegmentTree(size_t _n, T _def, function<T(T, T)> _update_func, function<T(T, T)> _find_func)
        : def(_def), update_func(_update_func), find_func(_find_func) {
        // 2のべき乗にする
        n = 1;
        while(n < _n) n <<= 1;
        data = vector<T>(2*n-1, _def);
    }

    void update(size_t i, T x){
        i += n-1;
        data[i] = update_func(data[i], x);
        while(i){
            i = (i-1)/2;
            data[i] = find_func(data[2*i+1], data[2*i+2]);
        }
    }

    T _find(size_t s, size_t t, size_t k, size_t kl, size_t kr){
        if(kr <= s || t <= kl) return def;
        if(s <= kl && kr <= t) return data[k];
        size_t kc = (kl+kr)/2;
        T vl = _find(s, t, 2*k+1, kl, kc);
        T vr = _find(s, t, 2*k+2, kc, kr);
        return find_func(vl, vr);
    }

    T find(size_t s, size_t t) {
        return _find(s, t, 0, 0, n);
    }
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<Edge> edges(m);
    for(int i=0;i<m;++i){
        cin >> edges[i].l >> edges[i].r >> edges[i].c;
        --edges[i].l;
        --edges[i].r;
    }
    sort(edges.begin(), edges.end());

    SegmentTree<ll> tree(
        n, INF, 
        [](ll a, ll b) { return b; }, 
        [](ll a, ll b) { return min(a, b); }
    );

    tree.update(0, 0);

    int l, r; ll c;
    for(int i=0;i<m;++i){
        l = edges[i].l;
        r = edges[i].r;
        c = edges[i].c;
        if(tree.find(l, n) == INF) {
            continue;
        }
        tree.update(
            r, 
            min(tree.find(r, r+1), tree.find(l, n) + c)
        );
    }

    ll ans = tree.find(n-1, n);

    cout << ((ans == INF)?-1:ans) << endl;
}

