long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a % b, y, x);
    y -= a / b * x;
    return d;
}

long long mul(long long a, long long b, long long mod) {
    long long keta[20] = {};
    long long c = b;
    long long now = 0;
    while (c != 0ll) {
        keta[now] = c % 10; c /= 10; now++;
    }
    long long res = 0;
    for (int i = 19; i >= 0; --i) {
        res *= 10; res %= mod;
        res += keta[i] * a % mod;
    }
    return res % mod;
}

bool cmp(pair<pair<int, int>, int> a, pair<pair<int, int>, int> b) {
    if (a.first.first != b.first.first) return a.first.first < b.first.first;
    if (a.first.second != b.first.second) return a.first.second < b.first.second;
    return a.second < b.second;
}

vector<pair<int, int>> g[100005];

void solve() {
    int n, m; cin >> n >> m;
    vector<pair<pair<int, int>, int>> lrc(m);
    rep (i, m) {
        int l, r, c; cin >> l >> r >> c; --l, --r;
        lrc[i] = {{l, r}, c};
    }
    sort(all(lrc), cmp);
    set<int> cnd{0};
    int now = 0;
    vector<int> cost(n, INF); cost[0] = 0;
    rep (i, m) {
        int l, r, c;
        l = lrc[i].first.first;
        r = lrc[i].first.second;
        c = lrc[i].second;
        set<int> tmp = cnd;
        for (auto nxt : cnd) {
            if (nxt < l) tmp.erase(nxt);
            else if (nxt < r) {
                tmp.insert(r);
                g[nxt].pb({r, c});
            } else {
                break;
            }
        }
        cnd = tmp;
    }

    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.push({0, 0});
    while (!pq.empty()) {
        int nxt = pq.top().second, cst = pq.top().first; pq.pop();
        if (cost[nxt] < cst) continue;
        for (auto to : g[nxt]) {
            if (cost[to.first] > cst + to.second) {
                cost[to.first] = cst + to.second;
                pq.push({cost[to.first], to.first});
            }
        }
    }

    if (cost[n - 1] == INF) cout << -1 << endl;
    else cout << cost[n - 1] << endl;
    return;
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();    
}

