	REP(i, m) {
		cin >> l[i] >> r[i] >> c[i];
		l[i]--;
		r[i];
		pp[i].first.first = l[i];
		pp[i].first.second = r[i];
		pp[i].second = c[i];
	}
	sort(all(pp));
	REP(i, m) {
		l[i] = pp[i].first.first;
		r[i] = pp[i].first.second;
		c[i] = pp[i].second;
	}
	ll inf = LLONG_MAX/3;
	vector<ll> dp(n, inf);
	priority_queue<P> pq;
	int cons = 1;
	int used = 1;
	REP(i, m) {
		if (l[i] == 0) {
			pq.push(P(-c[i], i));
			used = i+1;
		}
	}
	dp[0] = 0;
	while (!pq.empty()) {
		P p = pq.top();
		pq.pop();
		if (dp[l[p.second]] != inf) {
			FOR(i, cons, r[p.second]) {
				dp[i] = dp[l[p.second]] - p.first;
			}
			cons = r[p.second];
			while(used < m && l[used] <= cons) {
				pq.push(P(-c[used], used));
				used++;
			}
		}
	}
	if (dp[n - 1] == inf) {
		put(-1);
		return 0;
	}
	put(dp[n - 1]);
	return 0;
}

