class LRC{
  public:
  long long int L, R, C;

  LRC(long long int l, long long int r, long long int c){
    L = l;
    R = r;
    C = c;
  }

  bool operator < (const class LRC & another) const{
    return L < another.L;
  }

};

long long int INF = 1e18;

// update range [a, b) by min(value, current value)
// the variables should be k = 0, l = 0, r = N_segtree
int update_range(std::vector<long long int> &min_segtree, std::vector<long long int> &lazy, long long int N_segtree, long long int a, long long int b, long long int value, long long int k, long long int l, long long int r);

// get min in range [a, b) 
// the variables should be k = 0, l = 0, r = N_segtree
long long int get_min(std::vector<long long int> &min_segtree, std::vector<long long int> &lazy, long long int N_segtree, long long int a, long long int b, long long int k, long long int l, long long int r);

// subroutines
int propagate_lazy(std::vector<long long int> &segtree, std::vector<long long int> &lazy, long long int index, long long int l, long long int r);


int main(){

  // read problem
  long long int N, M, tmp1, tmp2, tmp3;
  std::vector<class LRC> lrc;
  scanf("%lld%lld", &N, &M);
  for(long long int i = 0; i < M; i++){
    scanf("%lld%lld%lld", &tmp1, &tmp2, &tmp3);
    lrc.push_back(LRC(tmp1-1, tmp2-1, tmp3));
  }
  std::sort(lrc.begin(), lrc.end(), std::less<class LRC>());

  // solve problem
  long long int N_segtree = (1LL<<17); 
  std::vector<long long int> min_segtree(2*N_segtree-1);
  std::vector<long long int> lazy(2*N_segtree-1);
  for(long long int i = 0; i < 2*N_segtree-1; i++){
    min_segtree[i] = INF;
    lazy[i] = INF;
  }

  update_range(min_segtree, lazy, N_segtree, 0, 1, 0, 0, 0, N_segtree);

  for(long long int i = 0; i < M; i++){
    update_range(min_segtree, lazy, N_segtree, lrc[i].L+1, lrc[i].R+1, get_min(min_segtree, lazy, N_segtree, lrc[i].L, lrc[i].L+1, 0, 0, N_segtree) + lrc[i].C, 0, 0, N_segtree);
  }

  // print answer
  long long int ans = get_min(min_segtree, lazy, N_segtree, N-1, N, 0, 0, N_segtree);
  std::cerr << "Answer: " << std::endl;
  if(ans >= INF){
    std::cout << "-1" << std::endl;
  }
  else{
    std::cout << ans << std::endl;
  }

  return 0;




