int propagate_lazy(std::vector<long long int> &segtree, std::vector<long long int> &lazy, long long int index, long long int l, long long int r){

  // evaluate
  segtree[index] = std::min(segtree[index], lazy[index]);    
  // if not lowest node
  if(r-l > 1){
    lazy[2*index+1] = std::min(lazy[2*index+1], lazy[index]);
    lazy[2*index+2] = std::min(lazy[2*index+2], lazy[index]);
  }
  lazy[index] = INF;

  return 0;
}

int update_range(std::vector<long long int> &min_segtree, std::vector<long long int> &lazy, long long int N_segtree, long long int a, long long int b, long long int value, long long int k, long long int l, long long int r){  
  // propagate 
  propagate_lazy(min_segtree, lazy, k, l, r);

  // if out of range
  if(b <= l || r <= a){
    return 0;
  }

  // if [a, b) covers [l, r)
  if(a <= l && b >= r){
    lazy[k] = std::min(lazy[k], value);
    propagate_lazy(min_segtree, lazy, k, l, r);

    return 0;
  }

  // calculate child nodes
  else{
    min_segtree[k] = std::min(min_segtree[k], value);

    update_range(min_segtree, lazy, N_segtree, a, b, value, 2*k+1, l, (l+r)/2);
    update_range(min_segtree, lazy, N_segtree, a, b, value, 2*k+2, (l+r)/2, r);

    return 0;
  }
}

long long int get_min(std::vector<long long int> &min_segtree, std::vector<long long int> &lazy, long long int N_segtree, long long int a, long long int b, long long int k, long long int l, long long int r){

  // if [a, b) and [l, r) have no intersection
  if(r <= a || l >= b){
    return INF;
  }

  // propagate
  propagate_lazy(min_segtree, lazy, k, l, r);

  // if [a, b) covers [l, r)
  if(a <= l && b >= r){
    return min_segtree[k];
  }
  // if [a, b) and [l, r) have intersection
  else{
    return std::min(get_min(min_segtree, lazy, N_segtree, a, b, 2*k+1, l, (l+r)/2), get_min(min_segtree, lazy, N_segtree, a, b, 2*k+2, (l+r)/2, r));
  }
}

