namespace {  // 名前なし名前空間
	// gcd, lcm は C++17 でstdに標準入りしたので言語のバージョンに注意
	// 最大公約数
	ll gcd(ll a, ll b) {
		if (b == 0) return a;
		return gcd(b, a % b);
	}

	// 最小公倍数
	ll lcm(ll a, ll b) {
		return a / gcd(a, b) * b;
	}
}

struct Edge {
	ll l, r, c;
};

int main() {

	ll n, m;
	std::cin >> n >> m;
	std::vector<Edge> edges(m);
	rep(i, m) {
		std::cin >> edges[i].l >> edges[i].r >> edges[i].c;
	}

	std::sort(allof(edges), [](Edge lhs, Edge rhs) {
		if (lhs.l == rhs.l) return lhs.c < rhs.c;
		return lhs.l < rhs.l;
		});


	// 各頂点に最小コストいくつで行けるか
	std::vector<ll> dp(n + 1, infll);

	dp[0] = 0LL;

	// なるべく奥に，の考え方で行く
	// 遠くしか考えない 先端しか見なくてよい

	// 自分より右に小さい数がいたらそっちを優先
	ll left = 0;
	//// first がインデックス second が最小値
	//std::pair<ll, ll> min_num({ 0, 0 });
	for (ll i = 1; i <= n; ++i) {
		if (left == m) break;
		if (dp[i - 1] == infll) continue;
		// くそこーど 
		if (left >= 1) while ((edges[left].l == edges[left - 1].l) && edges[left].r <= edges[left - 1].r) { ++left;  if (left == m) break; }
		if (left == m) break;
		while (i >= edges[left].l) {
			dp[edges[left].r - 1] = std::min(dp[edges[left].r - 1], dp[i - 1] + edges[left].c);
			++left;
			if (left == m) break;
		}
	}

	if (dp[n - 1] == infll) {
		std::cout << -1 << std::endl;
	}
	else std::cout << dp[n - 1] << std::endl;

	return 0;
}

