using namespace std;

#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
#define FOR(i, m, n) for(int i = (int)(m); i < (int)(n); ++i)

struct edge
{
    int to;
    long long cost;
    edge(int x, long long y): to(x), cost(y) {}
};

template <typename T>
void dijkstra(int s, vector<T>& d, vector<vector<edge>>& G){
    d[s] = 0;

    priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> q;
    q.push({(T) 0, s});
    while(!q.empty()){
        auto tmp = q.top(); q.pop();
        T d_min = tmp.first;
        int v = tmp.second;
        if(d[v] < d_min) continue;
        for(auto e: G[v]){
            if(d[e.to] > d[v] + e.cost){
