typedef struct {
    int l, r, c;
} pathInfo;

long long solve(const int n, std::vector<pathInfo> path)
{
    const int m = path.size();
    std::vector<long long> dist(n, std::numeric_limits<long long>::max());

    std::sort(path.begin(), path.end(), [](const pathInfo &a, const pathInfo &b){return a.l < b.l;});

    dist[0] = 0;

    for (int i = 0; i < n - 1; i++) {
        if (dist[i] == std::numeric_limits<long long>::max()) {return -1;}
        for (int j = 0; j < m; j++) {
            if ((path[j].l <= i) && (i < path[j].r)) {
                const int last = path[j].r;
                for (int k = i + 1; k <= last; k++) {
                    dist[k] = std::min(dist[k], dist[i] + path[j].c);
                }
            }
        }
    }

#ifdef _DEBUG
    for (int i = 0; i < n; i++) {
        std::cout << dist[i] << ", ";
    }
    std::cout << std::endl;
#endif

    return dist[n - 1];
}

