 //distance from s
//O(E log V)
template<class T = long long>
void dijkstra(vector<vector<edge> > &G, vector<T> &dist, long long s, const T INF = 1ll<<58){

  //first : distance from s, second : its vertex
  priority_queue< pair<T, long long> , vector<pair<T, long long> >, greater< pair<T, long long> > > pq;

  fill(dist.begin(), dist.end(), INF);
  dist[s] = 0;
  pq.push( {dist[s], s} );

  while(!pq.empty()){
    auto q = pq.top();
    pq.pop();
    long long from = q.second;
    if(dist[from] < q.first) continue; // it's not minimum distance

    for(auto& e: G[from]){
      if(dist[e.to] > dist[from] + e.cost){
        dist[e.to] = dist[from] + e.cost;
        pq.push( make_pair(dist[e.to], e.to) );
      }
    }
  }
}

