    for(int i = 0; i < m; i++){
        cin >> l[i] >> r[i] >> c[i];
    }

    vector<tuple<ll,ll,ll>> edge;
    for(int i = 0; i < m; i++){
        edge.push_back(make_tuple(l[i],c[i],r[i]));
    }

    sort(edge.begin(),edge.end());

    auto f1 = [](pair<ll,ll> a,pair<ll,ll> b)->pair<ll,ll>{
        return {a.first + b.first,a.second};
    };

    auto f2 = [](pair<ll,ll> a,pair<ll,ll> b)->pair<ll,ll>{
        if(a.first > b.first){
            return b;
        }else{
            return a;
        }
    };

    SegmentTree<pair<ll,ll>> st(n,{INF,-1},f1,f2);

    st.updateQuery(1,{0,1});
    for(int i = 2; i <= n; i++){
        st.updateQuery(i,{INF,i});
    }

    for(int i = 0; i < edge.size(); i++){
        ll pos = st.getQuery(get<0>(edge[i]),get<2>(edge[i])).first + get<1>(edge[i]);
        ll ng = get<0>(edge[i]) - 1;
        ll ok = get<2>(edge[i]) + 1;
        while(abs(ok - ng) > 1){
            ll middle = (ok + ng)/2;
            if(st.getQuery(middle,middle).first > pos){
                ok = middle;
            }else{
                ng = middle;
            }
        }
        for(int j = ok; j <= get<2>(edge[i]); j++){
            st.updateQuery(j,{pos,j});
        }
    }

    if(st.getQuery(n,n).first >= INF){
        cout << -1 << endl;
        return 0;
    }

    cout << st.getQuery(n,n).first << endl;

    return 0;
}

