using namespace std;

const long long INF = 1LL<<60;
int N = 131072;
long long dat[262144];

void update(int i, long long x) {
	i += N-1;
	dat[i] = x;
	while (i > 0) {
		i = (i-1)/2;
		dat[i] = min(dat[i*2+1], dat[i*2+2]);
	}
}

long long query(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l) return INF;
	if (a <= l && r <= b) return dat[k];
	return min(query(a,b,k*2+1,l,(l+r)/2), query(a,b,k*2+2,(l+r)/2,r));
}

long long get(int a, int b) {
	long long r = query(a, b, 0, 0, N);
	//cerr << a << " " << b << " " << r << endl;
	return r;
}

long long solve() {
	for (int i = 0; i < 262144; ++ i) dat[i] = INF;

	int n, M;
	cin >> n >> M;
	vector<pair<pair<int,int>,int>> a;
	for (int i = 0; i < M; ++ i) {
		int x, y, z;
		cin >> x >> y >> z;
		a.push_back({{x,y},z});
	}
	sort(a.begin(), a.end());
	update(1, 0);
	for (auto p : a) {
		int li = p.first.first;
		int ri = p.first.second;
		int ci = p.second;
		auto c1 = get(li, ri+1);
		auto c2 = get(ri, ri+1);
		if (c1+ci < c2) {
			update(ri, c1+ci);
		}
	}
	auto r = get(n, n+1);
	if (r == INF) return -1;
	return r;
}

int main() {
	cout << solve() << endl;
}

