	}
	int mid=(L+R)>>1,ls=rt<<1,rs=ls|1;
	if (x<=mid)
		update(ls,L,mid,x,v);
	else
		update(rs,mid+1,R,x,v);
	mi[rt]=min(mi[ls],mi[rs]);
