            auto cur_it = prev(st.upper_bound(R));
            while (*cur_it >= L) {
                  if (dis[*cur_it] < cur) break;
                  if (cur <= dis[*cur_it]) {
                     cur_it = st.erase(cur_it);
                     cur_it = prev(cur_it);
                  }
            }

            //for (auto k = st.lower_bound(L); k != st.upper_bound(R);) {
            //    if (*k <= R && cur <= dis[*k]) k = st.erase(k);
            //    else k++;
            //}
            it = st.lower_bound(R);
            if (it == st.end() || dis[*it] > cur) {
               st.insert(R);
               dis[R] = cur;
            }
        }
    }
    if (st.find(N) == st.end()) return !printf("-1\n");
    else printf("%lld\n", dis[N]);
    return 0;
}

