    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; ++ i){
        scanf("%d%d%d", &l[i], &r[i], &c[i]);
        -- l[i], -- r[i];
        append(1, 0, MAX - 1, l[i], r[i], i);
    }
    for (int i = 0; i < MAX << 1; ++ i){
        lazy[i] = LLONG_MAX;
    }
    for (int i = 0; i < n; ++ i){
        seg[i + MAX] = {i == 0 ? 0 : LLONG_MAX, i};
    }
    for (int i = MAX - 1; i; -- i){
        seg[i] = std::min(seg[i << 1], seg[i << 1 | 1]);
    }
    while (true){
        pii dis = query(0, n - 1);
        if (dis.second == n - 1){
            printf("%lld\n", dis.first);
            return 0;
        }
        if (dis.first == LLONG_MAX){
            break;
        }
        int pos = dis.second + MAX;
        for ( ; pos; pos >>= 1){
            for (auto u : divide[pos]){
                if (vis[u]){
                    continue;
                }
                add(l[u], r[u], dis.first + c[u]);
                vis[u] = true;
            }
            divide[pos].clear();
        }
        set(1, 0, MAX - 1, dis.second, LLONG_MAX);
    }
    puts("-1");
    return 0;
}

