		RL[r[i]].emplace_back(l[i], c[i]);
	}

	SegmentTree<Monoid::min<int>> st(n);
	st.update(0, 0);

	FOR(i, 1, n) {
		int res = INFLL;
		for (auto& p : RL[i]) {
			CHMIN(res, st.query(p.first, i) + p.second);
		}
		st.update(i, res);
	}

	int ans = st.query(n - 1, n);
	if (ans >= INFLL) ans = -1;
	OUT(ans)BR;

	return 0;
}

