    d.resize(s+2, INF);
  }
  inline void insert(ll a, ll b, ll c){
    G[a].push_back(edge{b, c});
  }
  void init(){
    for(int i=0;i<d.size();i++) pre[i] = -1, d[i] = INF;
  }
  void dijkstra(int start){
    init();
    st = start;
    d[start]=0;
    que.push(p(0, start));
    while(!que.empty()){
      p p_now=que.top(); que.pop();
      ll v = p_now.second;
      if(d[v]<p_now.first) continue;
      for(int i=0;i<G[v].size();i++){
        edge e = G[v][i];
        if(d[e.to]>d[v]+e.cost){
          d[e.to]=d[v]+e.cost;
          pre[e.to] = v;
          que.push(p(d[e.to], e.to));
        }
      }
    }
  }
  vll get_path(int now){
    vll ret;
    while(now!=-1){
      ret.push_back(now);
      now = pre[now];
    }
    return ret;
  }
};
struct Merge{
  map<ll, ll> l, r;
  ll INF = 1000000000000000000, tmp = 0;
  vll remove(ll a, ll b){
    if(a>b) swap(a, b);
    auto y = r.lower_bound(a);
    if(r.size()==0||y==r.end()) return vll{a, b};
    auto x = --l.lower_bound(b+1);
    ll to = (*x).second;
    while(true){
      bool br = false;
      if((*y).second==to) br=true;
      ll now_y = (*y).first, now_x = (*x).first;
      a = min(now_x, a), b = max(now_y, b);
      y++, x--;
      l.erase(now_x), r.erase(now_y);
      if(br) break;
    }
    return vll{a, b};
  }
  void merge(ll a, ll b){
    tmp++;
    vll t = remove(a, b);
    l.emplace(t[0], tmp), r.emplace(t[1], tmp);
  }
  vll get(ll a){
    auto left = l.upper_bound(a);
    auto right = r.lower_bound(a);
    if(left==l.begin()) return vll{INF, INF};
    left--;
    if((*right).first>=a&&(*left).first<=a) return vll{(*left).first, (*right).first};
    else return vll{INF, INF};
  }
  bool same(ll a, ll b){
    return get(a)[0]==get(b)[0];
  }
  vvl check(int i=-1){
    if(i==-1) i = l.size();
    auto itl = l.begin(), itr = r.begin();
    vvl ret = vv(0, 2, 0, ll);
    for(int j=0;j<i&&itl!=l.end();j++, itl++, itr++){
      //std::cout << (*itl).first << " " << (*itr).first << '\n';
      ret.push_back(vll{(*itl).first, (*itr).first});
    }
    return ret;
  }
};
int main(int argc, char const *argv[]) {
  ll a, b, c, n, m;std::cin >> n >> m;
  Dijkstra d(n);
  Merge mg;
  for(int i=0;i<m;i++){
    std::cin >> a >> b >> c;
    mg.merge(a, b);
    d.insert(a, b, c);
  }
  vvl t = mg.check();
  for(int i=0;i<t.size();i++){
    for(int j=t[i][1];j>t[i][0];j--){
      d.insert(j, j-1, 0);
    }
  }
  d.dijkstra(1);
  std::cout << (d.d[n]==d.INF?-1:d.d[n]) << '\n';
  return 0;
}

