void modify(int l, int r, int x, int y, int k, ll v) {
	if (x >= r || l >= y) return;
	if (x <= l && r <= y) {
		tag[k] = min(tag[k], v);
		return;
	}
	pd(k); int mid = (l + r) >> 1;
	modify(l, mid, x, y, 2 * k + 1, v);
	modify(mid, r, x, y, 2 * k + 2, v);
}
ll qry(int l, int r, int p, int k) {
	if (r - l == 1) return tag[k];
	pd(k); int mid = (l + r) >> 1;
	if (p < mid) return qry(l, mid, p, 2 * k + 1);
	else return qry(mid, r, p, 2 * k + 2);
}
