	int u,v,w;
}t[maxn];

bool cmp(const Node &x,const Node &y){
	if(x.u==y.u) return x.v<=y.v;
	return x.u<y.u;
}

struct segment_tree{
#define lson (o<<1)
#define rson (o<<1|1)
	int minv[4*maxn];
	inline void build(int o,int l,int r){
		if(l==r){
			minv[o]=inf;
			return;
		}
		int mid=(l+r)>>1;
		build(lson,l,mid);build(rson,mid+1,r);
		minv[o]=min(minv[lson],minv[rson]);
	}
	inline LL query(int o,int l,int r,int q){
		if(l==r) return minv[o];
		int mid=(l+r)>>1;
		minv[lson]=min(minv[lson],minv[o]);
		minv[rson]=min(minv[rson],minv[o]);
		if(q<=mid) return query(lson,l,mid,q);
		else return query(rson,mid+1,r,q);
	}
	inline void add(int o,int l,int r,int ql,int qr,int v){
		if(ql<=l&&qr>=r){
			minv[o]=min(v,minv[o]);
			return;
		}
		int mid=(l+r)>>1;
		if(ql<=mid) add(lson,l,mid,ql,qr,v);
		if(qr>mid) add(rson,mid+1,r,ql,qr,v);
	}
}tree;

