int taken[100005];
vector< pair<int, int> > X[100005];

priority_queue< pair<pair<int, int>, int>, vector< pair<pair<int, int>, int> >, greater< pair<pair<int, int>, int> > > Q;

int main() {

    ios::sync_with_stdio(0);
    cin.tie(NULL), cout.tie(NULL);

    int N, M;
    cin >> N >> M;

    while(M--)
    {
        int L, R, C;
        cin >> L >> R >> C;
        X[L].push_back({R, C});
    }

    int ptr = 2;
    long long ans = 0;

    for(auto x : X[1])
        Q.push({{x.second, x.first},  1});

    while(!Q.empty())
    {
        pair< pair<int, int>, int> pr = Q.top();
        Q.pop();

        ans += pr.first.first - taken[pr.second];
        taken[pr.second] = pr.first.first;

        while(ptr <= N && ptr <= pr.first.second)
        {
            for(auto x : X[ptr])
                Q.push({{x.second, x.first}, ptr});

            ptr++;
        }

        while(!Q.empty() && Q.top().first.second < ptr)
            Q.pop();
    }

    if(ptr <= N)
        ans = -1;

    cout << ans << "\n";
    return 0;
}

