template<typename Monoid>
class SegTree {

//半開区間!!!!!!!!!!!!!!!
public:
    int p = 2;
    vector<Monoid> node;
    using Func = function<Monoid(Monoid,Monoid)>;
    Func pick; Monoid init;//操作と単位元

    SegTree(vector<Monoid> A, string type, Monoid m) {
        if (type == "min") {
            pick = [](int a, int b){return min(a,b);};
        } else if (type == "max") {
            pick = [](int a, int b){return max(a,b);};
        } else if (type == "sum") {
            pick = [](int a, int b){return a + b;};
        }

        init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    SegTree(vector<Monoid> A, Func f, Monoid m) {
        pick = f; init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    //1点更新
    void update(int i, Monoid v) {
        for (node[(i+=p)-1] = v; i >>= 1;) {
            node[i-1] = pick(node[i*2-1], node[i*2]);
        }
    }

    //1点加算
    void add(int i, Monoid v) {
        update(i, this[i] + v);
    }

    int getval(int start,int end,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = p;
        if (r <= start || end <= l) {return init;}
        if (start <= l && r <= end) {return node[k];}
        int L,R;
        L = getval(start,end,k*2+1,l,(l+r)/2);
        R = getval(start,end,k*2+2,(l+r)/2,r);
        return {pick(L,R)};
    }

    inline Monoid operator [] (int i) {
        return node[i+p-1];
    }
};

void solve() {
    int n, m; cin >> n >> m;
    vector<pair<pair<int, int>, int>> lrc(m);
    rep (i, m) {
        int l, r, c; cin >> l >> r >> c; --l, --r;
        lrc[i] = {{l, r}, c};
    }
    sort(all(lrc), cmp);
    vector<int> dp(n, INF); dp[0] = 0;
    SegTree<int> seg(dp, "min", INF);
    rep (i, m) {
        int l = lrc[i].first.first;
        int r = lrc[i].first.second;
        int c = lrc[i].second;
        seg.update(r, min(seg[r], seg.getval(l, r) + c));
    }
    if (seg[n - 1] == INF) cout << -1 << endl;
    else cout << seg[n - 1] << endl;
    return;
}

