struct LRC{
  int L, R, C;
  LRC(){

  }
  LRC(int l, int r, int c){
    L = l, R = r, C = c;
  }
};
vector<LRC> lrc;
bool cmp(const LRC l, const LRC r){
  if(l.L != r.L){
    return l.L < r.L;
  }
  else if(l.R != r.R){
    return l.R < r.R;
  }
  else{
    return r.C < r.C;
  }
}
ll ans = (ll)1 << 62;
ll solve(int r, ll c, int k){
  if(r == N-1) return c;
  ll cost = (ll) 1 << 62;
  FOR(i, k+1, lrc.size()){
    if(lrc[i].L <= r && r < lrc[i].R){
      cost = min(cost, solve(lrc[i].R, c+lrc[i].C, i));
    }
    else if(lrc[i].L > r){
      break;
    }
  }
  return cost;
}
