using namespace std;

struct Section
{
	long long l;
	long long r;
	long long cost;

	bool operator < (const Section &a) const {
		if (this->l == a.l)
		{
			if (this->cost == a.cost)
			{
				//最大值优先
        		return this->r < a.r;
			}
			else
			{
				//最小值优先
				return this->cost > a.cost;
			}
		}
		else
		{
			//最小值优先
			return this->l > a.l;
		}
	}
};

std::priority_queue<Section> q;

int n, m;
int d[100010];

bool compareLR(const Section &a, const Section &b)
{
	if (a.l == b.l)
	{
		if (a.r == b.r)
		{
			return a.cost < b.cost;
		}
		else
		{
			return a.r < b.r;
		}
	}
	else
	{
		return a.l < b.l;
	}
}

void swap(Section &a, Section &b)
{
	long long temp;
	temp = a.l;
	a.l = b.l;
	b.l = temp;

	temp = a.r;
	a.r = b.r;
	b.r = temp;

	temp = a.cost;
	a.cost = b.cost;
	b.cost = temp;
}

Section ss[100010];

