{
	scanf("%d%d", &n, &m);

	int lastPos = 0;

	for (int i = 0 ; i < m ; i++)
	{
		scanf("%lld%lld%lld", &(ss[i].l), &(ss[i].r), &(ss[i].cost));
		if (lastPos < ss[i].r)
			lastPos = ss[i].r;
	}

	sort(ss, ss + m, compareLR);

	Section curSection;
	curSection.l = ss[0].l;
	curSection.r = ss[0].r;
	curSection.cost = ss[0].cost;
	for (int i = 1 ; i < m ; i++)
	{
		if ((curSection.l == ss[i].l) && (curSection.r == ss[i].r))
			continue;
		else
		{
			q.push(curSection);
			curSection.l = ss[i].l;
			curSection.r = ss[i].r;
			curSection.cost = ss[i].cost;
		}
	}
	q.push(curSection);




//	Section curSection;
	curSection = q.top();
	q.pop();

	if (curSection.l != 1)
	{
		printf("-1\n");
		return 0;
	}

	long long totalCost = 0;
	while (!q.empty())
	{
		Section nextSection = q.top();
		q.pop();

		if (curSection.r == nextSection.l)
		{
			totalCost = totalCost + curSection.cost;

			curSection.l = nextSection.l;
			curSection.r = nextSection.r;
			curSection.cost = nextSection.cost;
			continue;
		}

		if (curSection.l == nextSection.l)
		{
			if (curSection.cost > nextSection.cost)	//正常是不会的 
				swap(curSection, nextSection);

			if (curSection.r < nextSection.r)
			{
				nextSection.l = curSection.r;
				q.push(nextSection);
				continue;
			}
			//如果小那就完全吃掉 
		}
		else
		{
			if (curSection.r < nextSection.l)
			{
				printf("-1\n");
				return 0;
			}

			if (curSection.cost <= nextSection.cost)
			{
				if (curSection.r < nextSection.r)
				{
					nextSection.l = curSection.r;
					q.push(nextSection);
					continue;
				}
			}
			else
			{
				//4 7 10
				//5 9 8
				if (curSection.r < nextSection.r)
				{
					nextSection.l = curSection.r;
					q.push(nextSection);
					continue;
				}
			}
		}
	}

	if (lastPos < n)
	{
		printf("-1\n");
		return 0;
	}

	totalCost = totalCost + curSection.cost;

	printf("%lld\n", totalCost);

	return 0;
}

