#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll INF = (1ll << 60) - 1;

struct Segment {
    int n;
    vector<ll> node;

    Segment(int N) {
        n = 1;
        while (n < N) n *= 2;

        // ノード数は ceil(log2(N))^2 * 2 (葉数が2べきとなるよう調整)
        node.assign(2 * n - 1, INF);
    }

    void update(int k, ll a) {  // k番目の値をaに変更
        // k番目の葉 : k+n-1
        k += n - 1;
        node[k] = a;

        // 子 → 親 : (k-1)/2
        // 親 → 子(1,2) : 2*k + (1,2)
        while (k > 0) {
            k = (k - 1) / 2;
            node[k] = min(node[2 * k + 1], node[2 * k + 2]);
        }
    }

    ll find_min(int a, int b, int k = 0, int l = 0, int r = -1) {  // [a,b)の最小値を返す
        if (r < 0) r = n;

        // 含まない
        if (r <= a || b <= l) return INF;
        // 完全に含む
        if (a <= l && r <= b)
            return node[k];
        else {
            ll vl = find_min(a, b, 2 * k + 1, l, (l + r) / 2);
            ll vr = find_min(a, b, 2 * k + 2, (l + r) / 2, r);

            return min(vl, vr);
        }
    }
};

struct Range {
    int l, r;
    ll c;
};
bool operator<(const Range& x0, const Range& x1) {
    return (x0.l == x1.l ? x0.r < x1.r : x0.l < x1.l);  //<で昇順
}

int main() {
    int n, m;
    cin >> n >> m;
    Segment tree(n);
    vector<Range> v(m);
    for (int i = 0; i < m; i++) {
        cin >> v[i].l >> v[i].r >> v[i].c;
        v[i].l--, v[i].r--;
    }
    sort(v.begin(), v.end());
    tree.update(0, 0);
    for (int i = 0; i < m; i++) {
        tree.update(v[i].r, min(tree.find_min(v[i].r, v[i].r + 1), tree.find_min(v[i].l, v[i].r) + v[i].c));
    }
    ll ans = tree.find_min(n - 1, n);
    cout << (ans == INF ? -1 : ans) << endl;
    return 0;
}

