class RangeMin {
public:
	int size_ = 1;
	vector<long long> dat;

	void init(int sz) {
		while (size_ <= sz) size_ *= 2;
		dat.resize(size_ * 2, 0);
	}
	void update(int pos, long long x) {
		pos += size_;
		dat[pos] = x;
		while (pos >= 2) {
			pos >>= 1;
			dat[pos] = min(dat[pos * 2], dat[pos * 2 + 1]);
		}
	}
	long long query_(int l, int r, int a, int b, int u) {
		if (l <= a && b <= r) return dat[u];
		if (r <= a || b <= l) return (1LL << 60);
		long long v1 = query_(l, r, a, (a + b) >> 1, u * 2);
		long long v2 = query_(l, r, (a + b) >> 1, b, u * 2 + 1);
		return min(v1, v2);
	}
	long long query(int l, int r) {
		return query_(l, r, 0, size_, 1);
	}
};

long long N, M;
long long L[1 << 18], R[1 << 18], C[1 << 18];
long long dp[1 << 18];
vector<int> G[1 << 18];
RangeMin Z;

int main() {
	cin >> N >> M;
	for (int i = 1; i <= M; i++) cin >> L[i] >> R[i] >> C[i];
	for (int i = 1; i <= M; i++) G[R[i]].push_back(i);
	for (int i = 2; i <= N; i++) dp[i] = (1LL << 60);

	Z.init(N + 2);
	for (int i = 2; i <= N; i++) {
		for (int j : G[i]) {
			long long cl = L[j], cost = C[j];
			long long v = Z.query(L[j], i);
			dp[i] = min(dp[i], v + cost);
		}
		Z.update(i, dp[i]);
	}

	if (dp[N] == (1LL << 60)) cout << "-1" << endl;
	else cout << dp[N] << endl;
	return 0;
}

