void dijkstra(ll s, vector<vector<edge>> e){
  priority_queue<pll, vector<pll>, greater<pll>> que;
  d[s] = 0;
  que.push(pll(0, s));

  while(!que.empty()){
    pll p = que.top();
    que.pop();
    ll v = p.SE;
    if(d[v] < p.FI)
      continue;
    for(ll i = 0; i < e[v].size(); i++){
      edge g = e[v][i];
      if(d[g.to] > d[v] + g.cost){
        d[g.to] = d[v] + g.cost;
        que.push(pll(d[g.to], g.to));
      }
    }

  }
}

