vector<int> lazy(400005,inf);
void buildTree(int *tree,int start,int end,int node){
	if(start==end) {
		if(start==0) tree[node] = 0;
		else tree[node]=inf;
	}
	else if(start<end){
		int mid=(start+end)/2,left=2*node+1,right=left+1;
		buildTree(tree,start,mid,left);
		buildTree(tree,mid+1,end,right);
		tree[node]=min(tree[left],tree[right]);
	}
	lazy[node] = inf;
}
void update(int *tree,int start,int end,int l,int r,int dif,int node){
	// cout<<"#"<<start<<" "<<end<<" -- "<<dif<<endl;
	if(lazy[node]!=inf){
		// there are pending updates
		tree[node]=min(lazy[node],tree[node]);
		if(start!=end){
			lazy[2*node+1]=min(lazy[2*node+1],lazy[node]);
			lazy[2*node+2]=min(lazy[2*node+2],lazy[node]);
		}
		lazy[node]=inf;
	}
	if(start> r or end<l)return;
	else if(start>=l and end<=r){
		lazy[node] = min(lazy[node], dif);
		tree[node]=min(tree[node],dif);	// make the update for the current range and keep them pending for the child nodes
		if(start!=end){
			lazy[2*node+1]=min(lazy[2*node+1],lazy[node]);
			lazy[2*node+2]=min(lazy[2*node+2],lazy[node]);
		}
		return;
	}
	int mid=(start+end)/2;
	update(tree,start,mid,l,r,dif,2*node+1);
	update(tree,mid+1,end,l,r,dif,2*node+2);
	tree[node]=min(tree[2*node+1],tree[2*node+2]);
}
int queryMin(int *tree,int start,int end,int l,int r,int node){
	if(lazy[node]!=inf){
		// if there are updates pending, apply them before making the queries
		tree[node]=min(lazy[node],tree[node]);
		if(start!=end){
			lazy[2*node+1]=min(lazy[2*node+1],lazy[node]);
			lazy[2*node+2]=min(lazy[2*node+2],lazy[node]);
		}
		lazy[node]=inf;
	}
	if(start>r or end<l)return inf;
	else if(start>=l and end<=r)return tree[node];
	else{
		int mid=(start+end)/2,left=2*node+1,right=left+1;
		return min(queryMin(tree,start,mid,l,r,left),queryMin(tree,mid+1,end,l,r,right));
	}
}

