vector<ll> storage;
ll INF=(1ll*1000*1000*1000)*(1ll*1000*1000);
int n=1;
void updateLeaf(int i,ll v) {
    i+=n-1;
    if (storage[i]<=v)return;
    storage[i]=v;
    while(i>0) {
        i=(i-1)/2;
        storage[i]=min(storage[i*2+1],storage[i*2+2]);
    }
}
ll rangeMin(int a, int b, int k, int l, int r) {
    if(b<=l || a>=r) return INF;
    if(a<=l && b>=r) {
        return storage[k];
    } else {
        ll tl = rangeMin(a,b,k*2+1,l,(l+r)/2);
        ll tr = rangeMin(a,b,k*2+2,(l+r)/2,r);
        return min(tl,tr);
    }
}
