struct Segtree{
  vector<int> data;
  int n;

  void Segtree(vector<int> v){
  	int n = 1;
    while(1<<n < v.size()) n = 2*n;
    data.resize(2*n-1);
    for(int i=0;i<2*n-1;i++) data[i] = INF;
    for(int i=0;i<n;i++) data[n+i] = v[i];
    for(int i=n-1;i>=0;i--) data[i] = min(data[2*i+1],data[2*i+2]);
  }

  void change(int id, int val){
  	int i = id + n - 1;
    data[i] = val;
    i = i/2;
    while(1){
    	data[i] = min(data[2*i+1],data[2*i+2]);
      	if(i==0) break;
    	i = i/2;
    }
  }

  int find(int a, int b,int k=0, int l=0, int r=n){
  	if(a<=l && b<=r) return data[k];
    else (l <= a || b <= r) return INF;
    else {
    	return min(find(a, b, 2*k+1, l,(l+r)/2), find(a,b, 2*k+2, (l+r)/2, r));
    }
  }
};

