    REP(i, M) {
        cin >> LRC[i].first.first >> LRC[i].first.second >> LRC[i].second;
    }
    sort(ALL(LRC));

    SegmentTree st(N);
    st.update(0, 0);
    REP(i, M) {
        ll L = LRC[i].first.first-1;
        ll R = LRC[i].first.second-1;
        ll C = LRC[i].second;

        ll Q0 = st.query(L, R+1);
        ll Q1 = st.query(R, R+1);

        ll x = min(Q0+C, Q1);
        st.update(R, x);
    }

    ll score = st.query(N-1, N);
    cout << (score>=INF?-1:score) << endl;
}

