int dijkstra(){
    fill(d,d+n,INF);
    fill(used,used+n,false);
    d[0] = 0;

    while(true){
        int v = -1;
        //まだ使われていない頂点のうち距離が最小のものを探す
        for(int u=0;u<n;u++){
            if(!used[u]&&(v==-1||d[u]<d[v])){
                v=u;
            }
