	if(l[0].l!=1)
	{
		cout << -1 << '\n';
		return 0;
	}

	multiset <long long int> S;
	priority_queue <pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pque;

	for(int i=0;i<m;i++)
	{
		while(!pque.empty())
		{
			if(pque.top().first < l[i].l)
			{
				S.erase(S.find(dp[pque.top().second]));
				pque.pop();
			}
			else
			{
				break;
			}
		}

		if(l[i].l==1)
		{
			dp[i] = l[i].c;
			S.insert(dp[i]);
			pque.push(make_pair(l[i].r,i));
		}
		else
		{
			if(S.size()!=0)
			{
				dp[i] = *S.begin() + l[i].c;
