using namespace std;
typedef long long ll;

const ll INF = 1LL << 60;

vector< vector< pair<int,int> > > to(100005);
ll dist[100005];

int main() {
  int N,M;
  cin >> N >> M;
  vector< int > L(M),R(M),C(M);
  REP(i,M) {
    cin >> L[i] >> R[i] >> C[i];
    L[i]--; R[i]--;
    to[L[i]].emplace_back(R[i],C[i]);
  }
  REP(i,N-1)
    to[i+1].emplace_back(i,0);

  REP(i,N)
    dist[i] =INF;
  dist[0] = 0;
  // ダイクストラ
  priority_queue< pair<ll, int> > q;
  q.push( make_pair(0, 0) );
  while( !q.empty() ) {
    auto v = q.top(); q.pop();
    for ( auto nv: to[v.second] ) {
      if ( dist[nv.first] > dist[v.second] + nv.second ) {
        dist[nv.first] = dist[v.second] + nv.second;
        q.push( make_pair(dist[nv.first], nv.first) );
      }
    }
  }
  ll ans = (dist[N-1] == INF) ? -1 : dist[N-1];
  cout << ans << endl;
}

