ll segtree[816225][2],dp[225816];
bool delayed[816225];

void eval(int i, int l, int r){
	if(delayed[i]){
		segtree[i][0] = min(segtree[i][1],segtree[i][0]);
		if(r-l>1){
			segtree[2*i+1][1] = min(segtree[i][1],segtree[2*i+1][1]);
			delayed[2*i+1] = false;
			segtree[2*i+2][1] = min(segtree[i][1],segtree[2*i+2][1]);
			delayed[2*i+2] = false;
		}
		delayed[i] = false;
		segtree[i][1] = INFLL;
	}
}

void update(int a, int b, int i, int l, int r, ll v){
	eval(i,l,r);
	if(b<=l || r<=a){
		return;
	}
	if(a<=l && r<=b){
		segtree[i][1] = min(v,segtree[i][1]);
		delayed[i] = true;
		eval(i,l,r);
	}else{
		update(a,b,2*i+1,l,(l+r)/2,v);
		update(a,b,2*i+2,(l+r)/2,r,v);
		segtree[i][0] = min(segtree[2*i+1][0],segtree[2*i+2][0]);
	}
}

ll query(int a, int b, int i, int l, int r){
	ll vl,vr;
	eval(i,l,r);
	if(b<=l || r<=a){
		return INFLL;
	}
	if(a<=l && r<=b){
		return segtree[i][0];
	}else{
		vl = query(a,b,2*i+1,l,(l+r)/2);
		vr = query(a,b,2*i+2,(l+r)/2,r);
		return min(vl,vr);
	}
}

