 int N;             // 葉の数

 void update(int i, int x) {
     // i 番目の葉の値を x に変える
     i += N - 1; // i 番目の葉のノード番号
     value[i] = x;
     while (i > 0) {
         i = (i - 1) / 2; // ノード i の親ノードの番号に変える
         value[i] = min(value[i * 2 + 1],
                        value[i * 2 + 2]); // 左右の子の min を計算しなおす
     }
 }

 int RMQ(int a, int b, int k, int l, int r) {
     // [a, b) の区間に対するクエリについて
     // ノード k （区間 [l, r) 担当）が答える
     if (r <= a || b <= l) return INF; // 区間が被らない場合は INF を返す
