struct SegmentTree{
private:
    int n;
    vector<ll> node;
public:
    SegmentTree(vector<ll> v){
        int sz=v.size();
        n=1;
        while(n<sz)n*=2;
        node.resize(2*n-1,LINF);
        for(int i=0;i<sz;i++){
            node[i+n-1]=v[i];
