typedef long long ll;
struct LazySegmentTree
{
public:
	int n;
	vector<ll> node, lazy;

	LazySegmentTree(vector<ll> v)
	{
		int sz = (int)v.size();
		n = 1; while (n < sz) n *= 2;
		node.resize(2 * n - 1, 1e18);
		lazy.resize(2 * n - 1, 1e18);

		for (int i = 0; i < sz; i++) node[i + n - 1] = v[i];
		for (int i = n - 2; i >= 0; i--) node[i] = min(node[i * 2 + 1], node[i * 2 + 2]);
	}

	void lazyEvaluate(int k, int l, int r)
	{
		node[k] = min(node[k], lazy[k]);

		if (r - l > 1)
		{
			lazy[k * 2 + 1] = min(lazy[k * 2 + 1], lazy[k]);
			lazy[k * 2 + 2] = min(lazy[k * 2 + 2], lazy[k]);
		}
		//lazy[k] = 1e18;
	}

	void update(int a, int b, ll x, int k = 0, int l = 0, int r = -1)
	{
		if (r < 0) r = n;

		lazyEvaluate(k, l, r);
		if (b <= l || r <= a) return;
		if (a <= l && r <= b)
		{
			lazy[k] = min(lazy[k], x);

			lazyEvaluate(k, l, r);
		}
		else
		{
			update(a, b, x, 2 * k + 1, l, (l + r) / 2);
			update(a, b, x, 2 * k + 2, (l + r) / 2, r);
			node[k] = min(node[2 * k + 1], node[2 * k + 2]);
			//cerr<<k<<" "<<node[k]<<endl;
		}
	}

	ll find(int a, int b, int k = 0, int l = 0, int r = -1)
	{
		if (r < 0) r = n;
		lazyEvaluate(k, l, r);
		//cerr << l << " " << r<<" "<<a<<" "<<b << endl;
		if (b <= l || r <= a) return 1e18;
		if (a <= l && r <= b) return node[k];
		ll vl = find(a, b, 2 * k + 1, l, (l + r) / 2);
		ll vr = find(a, b, 2 * k + 2, (l + r) / 2, r);

		//cerr<<vl<<" "<<vr<<endl;
		node[k] = min(node[2 * k + 1], node[2 * k + 2]);
		return min(vl, vr);
	}
};

