// Segment tree (range add)
struct F { // min func
  typedef ll TT;
  TT d;
  F(TT d=LINF):d(d) {}
  F& operator+=(const F& f) {
    mins(d, f.d);
    return *this;
  }
  F operator+(const F& f) const { return F(*this) += f;}
};
struct seg {
  vector<F> d; int n;
  seg(){}
  seg(int mx) {
    n = 1; while (n < mx) n <<= 1;
    d = vector<F>(n<<1);
  }
  void upd(int i) { d[i] = d[i<<1]+d[i<<1|1];}
  F& operator[](int i) { return d[n+i];}
  void init() { for(int i=n-1;i;--i) upd(i);}
  F get(int i) {
    F x;
    for (i+=n;i;i>>=1) x += d[i];
    return x;
  }
  void add(int l, int r, F f) {
    l += n; r += n;
    while (l < r) {
      if (l&1) d[l] += f, ++l;
      if (r&1) --r, d[r] += f;
      l >>= 1; r >>= 1;
    }
  }
};
