    int l, r, c; cin >> l >> r >> c;
    --l, --r;
    G[l].emplace_back(r, c);
  }
  rep(i, n-1) G[i+1].emplace_back(i, 0);

  auto dist = dijkstra(G, 0);
  cout << (dist[n-1] < INFll ? dist[n-1] : -1) << "\n";
  return 0;
}

