using namespace std;
using ll = long long;

struct Edge {
    int to;
    ll cost;
};

int main() {
    int n, m; cin >> n >> m;
    // cost, to
    vector<vector<Edge>> g(n);
    for (int i = 0; i < m; i++)
    {
        ll l, r, c; cin >> l >> r >> c;
        l--; r--;
        g[l].emplace_back(Edge{(int)r, c});
    }

    for (int i = 1; i < n; i++)
    {
        g[i].emplace_back(Edge{i-1, 0});
    }

    ll inf = 1e14;
    vector<ll> dist(n, inf);

    using P = pair<ll, int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.push(P(0, 0));
    dist[0] = 0;

    while (!pq.empty()) {
        P a = pq.top();
        pq.pop();
        ll d = a.first;
        ll now = a.second;
        if (d > dist[now]) continue;

        for (int i = 0; i < g[now].size(); i++) {
            ll cost = g[now][i].cost;
            int next = g[now][i].to;

            if (dist[next] > dist[now]+cost) {
                dist[next] = dist[now]+cost;
                pq.push(P(dist[next], next));
            }
        }
    }

    if (dist[n-1] == inf) cout << -1 << endl;
    else cout << dist[n-1] << endl;

    return 0;
}

