	dis[pos[P]] = 0; 
    priority_queue<Pair> q; 
    q.push(MP(0, pos[P]));
    while(!q.empty()) {
        int p = q.top().second; q.pop();
        if(vis[p]) continue; vis[p] = 1;
        for(int i = head[p]; ~i; i = E[i].nxt) {
            int to = E[i].v;
            if(!vis[to] && (dis[to] > dis[p] + E[i].w)) 
                dis[to] = dis[p] + E[i].w, q.push(MP(-dis[to], to));
        }
    }
}
