struct node{
	int u;
	long long val;
	long long lazy;
	node(){u = 0;val = 0;lazy = 1e18;}
}seg[4*N];
void fix(int c,int l,int r){
	seg[c].val = min(seg[c].val,seg[c].lazy);
	if(l != r){
		seg[2*c + 1].lazy = min(seg[2*c + 1].lazy,seg[c].lazy);
		seg[2*c + 2].lazy = min(seg[2*c + 2].lazy,seg[c].lazy);
	}
	seg[c].lazy = 1e18;
}
pair<long long,int> get(int c,int l,int r,int s,int e
	){
	fix(c,l,r);
	if(e < l || r < s)return {1e18,-1};
	if(s <= l && r <= e)return {seg[c].val,seg[c].u};
	pair<long long,int> x = get(2*c + 1,l,(l + r)/2,s,e);
	pair<long long,int> y = get(2*c + 2,(l + r)/2 + 1,r,s,e);
	if(x.first == -1)x.first = 1e18;
	if(y.first == -1)y.first = 1e18;
	return min(x,y);
}
void update(int c,int l,int r,int s,int e,long long val){
	fix(c,l,r);
	if(e < l || r < s)return;
	if(s <= l && r <= e){
		seg[c].lazy = val;
		fix(c,l,r);
		return;
	}
	update(2*c + 1,l,(l + r)/2,s,e,val);
	update(2*c + 2,(l + r)/2 + 1,r,s,e,val);
	pair<long long,int> x = {seg[2*c + 1].val,seg[2*c + 1].u};
	pair<long long,int> y = {seg[2*c + 2].val,seg[2*c + 2].u};
	if(x.first == -1)x.first = 1e18;
	if(y.first == -1)y.first = 1e18;
	if(x.first < y.first){
		seg[c].val = x.first;
		seg[c].u = x.second;	
	}
	else{
		seg[c].val = y.first;
		seg[c].u = y.second;
	}
}
