    int l, w;
};
vector<node> G[N];

int main() {   
    n = read(); m = read();
    REP(i, 1, m) {
        int x = read(), y = read(), z = read();
        G[y].push_back((node){x, z});
    }
    REP(i, 1, n * 4) s[i] = INF;
    for(int i = 1; i <= n; ++i) {
        for(int j = 0; j < G[i].size(); ++i) {
            int l = G[i][j].l, w = G[i][j].w;
            if(l == 1) update(1, 1, n, i, w);
            else {
                LL res = query(1, 1, n, l, i);
                if(res != INF) update(1, 1, n, i, w + res);
            }
        }
    }
    LL ans = query(1, 1, n, n, n);
    if(ans == INF) cout << -1 << endl;
    else cout << ans << endl;
	return 0;
}

