class SegmentTree{
public:
	int mode;
	int base;
	inline void build(int x, int l, int r){
		if(l == r){
			if(mode){
				//if(l == n - 1) printf("NOTE: %d %d\n", siz + l, x + base);
				g[siz + l].PB(MP(x + base, 0));
			}
			return;
		}
		int md = l + r >> 1;
		build(x << 1, l, md);
		build(x << 1 | 1, md + 1, r);
		if(mode){
			g[(x << 1) + base].PB(MP(x + base, 0));
			g[(x << 1 | 1) + base].PB(MP(x + base, 0));
		}
		else{
			g[x + base].PB(MP((x << 1) + base, 0));
			g[x + base].PB(MP((x << 1 | 1) + base, 0));
		}
		return;
	}
	inline void init(int _mode){
		mode = _mode;
		base = mode * (siz << 1) - 1;
		if(base < 0) base = 0;
		build(1, 0, siz - 1);
		return;
	}
	inline void update(int x, int l, int r, int s, int t, int y, int k){
		//printf("base = %d x = %d l = %d r = %d\n", base, x, l, r);
		if(l >= s && r <= t){
			//printf("u = %d v = %d w = %d mode = %d l = %d r = %d s = %d t = %d\n", x + base, y, k, mode, l, r, s, t);
			if(mode) g[base + x].PB(MP(y, k));
			else g[y].PB(MP(base + x, k));
			return;
		}
		int md = l + r >> 1;
		if(s <= md) update(x << 1, l, md, s, t, y, k);
		if(t > md) update(x << 1 | 1, md + 1, r, s, t, y, k);
		return;
	}
}segIn, segOut;

inline int ID(int u){
	if(u <= (siz << 1) - 1) return u;
	if(u < (siz << 2) - 1) return u - (siz << 1);
	return u - ((siz << 2) - 1);
}

inline void dijkstra(int s){
	//printf("s = %d\n", s);
	FOR(i, 0, (siz << 2) + maxn) dis[i] = INF;
	dis[s] = 0;
	priority_queue<pli, vector<pli>, greater<pli> > que;
	que.PH(MP(0, s));
	while(!que.empty()){
		pli p = que.top(); que.pop();
		int u = p.snd;
		ll d = p.fst;
		//printf("u = %d %d d = %lld\n", u, ID(u), d);
		if(d != dis[u]) continue;
		FOR(i, 0, g[u].size()){
			int v = g[u][i].fst;
			int w = g[u][i].snd;
			if(dis[v] > dis[u] + w){
				//printf("u = %d %d v = %d %d w = %d\n", u, ID(u), v, ID(v), w);
				dis[v] = dis[u] + w;
				que.PH(MP(dis[v], v));
			}
		}
	}
	return;
}

int main(){
	scanf("%d%d", &n, &m);
	segIn.init(0);
	segOut.init(1);
	int tot = (siz << 2) - 1;
	FOR(i, 0, m){
		int l, r, c; scanf("%d%d%d", &l, &r, &c); --l; --r;
		segIn.update(1, 0, siz - 1, l, r, i + tot, c);
		segOut.update(1, 0, siz - 1, l, r, i + tot, 0);
	}
	dijkstra(siz * 3 - 1);
	if(dis[siz + n - 1] != INF) printf("%lld\n", dis[siz + n - 1]);
	else puts("-1");
	return 0;
}

