void build(int k,int l,int r)
{
	maxx=max(maxx,k);
	if (l==r) {idx[l]=k;return;}
	int mid=(l+r)/2;
	build(k<<1,l,mid);
	build(k<<1|1,mid+1,r);
}
void build2(int k,int l,int r)
{
	f[k+maxx].pb(mp(k,0));
	if (l==r) {return;}
	int mid=(l+r)/2;
