void build(int v, int l, int r){
    int m = (l + r) / 2;

    if(l == r){
        g[v + n].push_back({l, 0});
        g[l].push_back({v + 5 * n, 0});
        return;
    }

    g[v * 2 + n * 5].push_back({v + 5 * n, 0});
