    if(l > r)
        return;

    if(tl == l && tr == r){
        //cout << "$$$" << v + 5 * n<< " " <<x << endl;
        pr.push_back(v);
        return;
    }

    upd(v * 2, tl, m, l, min(r, m), x);
    upd(v * 2 + 1, m + 1, tr, max(l, m + 1), r, x);
}

