#include <bits/stdc++.h>
using namespace std;

template <typename T>
struct segtree {

  vector<T> seg, lazy;

  segtree(int n = 1e5) {
    n += 5;
    seg.assign(4*n, 1e16);
    lazy.assign(4*n, 1e16);
  }

  T join(T x, T y) {
    return min(x, y);
  }

  void lazy_update(int x, int s, int e) {
    if (lazy[x] == 1e16)  return ;
    seg[x] = min(seg[x], lazy[x]);

    if (s != e)
      lazy[2*x] = min(lazy[2*x], lazy[x]), lazy[2*x+1] = min(lazy[2*x+1], lazy[x]);
    lazy[x] = 1e16;
  }

  void build(int x, int s, int e) {
    if (s == e) {
      seg[x] = 0;
      return; 
    }

    int mid = (s + e) >> 1;
    build(2 * x, s, mid);
    build(2 * x + 1, mid + 1, e);

    seg[x] = join(seg[2*x], seg[2*x+1]);
  }

  void update(int x, int s, int e, int l, int r, T val) {
    lazy_update(x, s, e);
    if (s > r || e < l)  return ;

    if (s >= l && e <= r) {
      lazy[x] = min(lazy[x], val);
      lazy_update(x, s, e);
      return;
    }

    int mid = (s + e) >> 1;
    update(2 * x, s, mid, l, r, val);
    update(2 * x + 1, mid + 1, e, l, r, val);

    seg[x] = join(seg[2 * x], seg[2 * x + 1]);
  }

  T query(int x, int s, int e, int l, int r) {
    lazy_update(x, s, e);
    if (e < l || s > r)  return 1e16;
    if (s >= l && e <= r){
      return seg[x];
    }

    int mid = (s + e) >> 1;
    return join(query(2 * x, s, mid, l, r), query(2 * x + 1, mid + 1, e, l, r));
  }
};

int main() {

  ios::sync_with_stdio(false);
  cout.tie(nullptr);
  cin.tie(nullptr);

  int n, m;
  cin >> n >> m;

  vector<pair<pair<int, int>, int>> p;
  for (int i = 0; i < m; ++i) {
    int l, r, c;
    cin >> l >> r >> c;

    p.push_back({{l, r}, c});
  }

  sort(p.begin(), p.end(), [&](auto la, auto lb) {
    return la.first.first > lb.first.first;
  });

  segtree<long long> seg(n);
  seg.update(1, 1, n, n, n, 0);

  for (int i = 0; i < m; ++i) {
    int l = p[i].first.first, r = p[i].first.second, c = p[i].second;
    long long mn = seg.query(1, 1, n, l, r);
    seg.update(1, 1, n, l, l, c + mn);
  }

  long long ans = seg.query(1, 1, n, 1, 1);
  if (ans > 1e15) ans = -1;
  cout << ans << '\n';
}

