    }
    sort(g.begin(), g.end(), [](Node a, Node b){
        return (a.l < b.l) || (a.l == b.l && a.c < b.c);
    });

    st.n = n;
    st.build(1, 1, n);
    LL l = 1, r = 1;
    st.update(1, 1, n, 1, 1, 0);
    for(LL i = 0; i < m; ++i){
        if(g[i].l > r) {
            cout << "-1" <<endl;
            return 0;
        }
        PLL u = st.query(1, 1,n, g[i].l, r);
        st.update(1, 1,n, u.second+1, g[i].r, u.first+g[i].c);
        r = max(g[i].r, r);

