      dist[r] = min(rc, dist.lower_bound(l)->second + c);
    }
  }
  if (dist.find(n - 1) == dist.end()) {
    cout << -1 << endl;
  } else {
    cout << dist[n - 1] << endl;
  }
  return 0;
}

