class RangeMinQuery {
private:
    int bottomSt, bottomEd;
    vector<int> a;
    vector<int> rs, re;
    vector<int> cand;
    int set(int n) {
        int left = 2 * n + 1;
        int right = 2 * n + 2;
        if (left <= a.size() - 1) {
            a[n] = min(set(left), set(right));
            rs[n] = rs[left];
            re[n] = re[right];
        }
        return a[n];
    }
    void search(int s, int t, int n) {
        if (s <= rs[n] && re[n] <= t) {
            cand.push_back(a[n]);
            return;
        }
        int left = 2 * n + 1;
        int right = 2 * n + 2;
        if (s <= re[left]) search(s, t, left);
        if (rs[right] <= t) search(s, t, right);
    }
public:
    RangeMinQuery(vector<int> &v) {
        bottomEd = 0;
        for (int i = 1, plus = 1; plus < v.size(); i++) {
            plus *= 2;
            bottomEd += plus;
        }
        a.resize(bottomEd + 1);
        rs.resize(bottomEd + 1);
        re.resize(bottomEd + 1);

        bottomSt = bottomEd / 2;

        for (int i = bottomSt; i <= bottomEd; i++) {
            int j = i - bottomEd / 2;
            a[i] = j < v.size() ? v[j] : LLONG_MAX;
            rs[i] = j;
            re[i] = j;
        }

        set(0);
    }

    void update(int index, int x) {
        int pt = bottomSt + index;
        a[pt] = x;
        while (pt > 0) {
            pt = (pt - 1) / 2;
            a[pt] = min(a[2 * pt + 1], a[2 * pt + 2]);
        }
    }

    int find(int s, int t) {
        cand.clear();
        search(s, t, 0);
        int ret = cand[0];
        for (int i = 1; i < cand.size(); i++) {
            ret = min(ret, cand[i]);
        }
        return ret;
    }
};

signed main() {
    int N, M;
    cin >> N >> M;

    vector<Info> infos;
    rep(i, M) {
        int L, R, C;
        cin >> L >> R >> C;
        L--; R--;
        infos.push_back(Info(L, R, C));
    }

    sort(all(infos));

    const int INF = LLONG_MAX / 10;
    rep(i, N) dp[i] = INF;
    dp[0] = 0;

    vector<int> v(N, INF);
    RangeMinQuery rmq(v);

    for (auto &info : infos) {
        if (dp[info.L] == INF) {
            int minval = rmq.find(info.L, N - 1);
            if (minval == INF) {
                cout << -1 << endl;
                return 0;
            }
            dp[info.L] = minval;
        }
        if (dp[info.R] > dp[info.L] + info.C) {
            dp[info.R] = dp[info.L] + info.C;
            rmq.update(info.R, dp[info.R]);
        }
    }

    if (dp[N - 1] == INF) {
        cout << -1 << endl;
    } else {
        cout << dp[N - 1] << endl;
    }

    return 0;
}

