const int INF = 1e18, MAXN = 1e6, MOD = 998244353, BASE = 37;	
int t[4 * MAXN];

void upd(int v, int tl, int tr, int id, int val) {
	if (id < tl || id > tr) {
		return;
	}
	if (tl == tr) {
		t[v] = min(t[v], val);
		return;
	}
	int tm = (tl + tr) / 2;
	upd(v * 2, tl, tm, id, val);
	upd(v * 2 + 1, tm + 1, tr, id, val);
	t[v] = min(t[v * 2], t[v * 2 + 1]);
}

int gt(int v, int tl, int tr, int l, int r) {
	if (tr < l || tl > r) {
		return INF;
	}
	if (l <= tl && tr <= r) {
		return t[v];
	}
	int tm = (tl + tr) / 2;
	int ans1 = gt(v * 2, tl, tm, l, r);
	int ans2 = gt(v * 2 + 1, tm + 1, tr, l, r);
	return min(ans1, ans2);
}

