const ll inf = 1e18;
void answer() {
  int n, m;
  cin >> n >> m;
  vector<set<T> > mp(n + 1);
  rep(i, n) {
    int l, r, c;
    cin >> l >> r >> c;
    mp[l].emplace(c, l, r);
  }
  vector<ll> dist(n + 1, inf);
  int cur = 0;
  dist[cur] = 0;
  set<T> s;
  s.emplace(0, 0, 1);
  while (!s.empty()) {
    auto [c, l, r] = *(s.begin());
    s.erase(s.begin());
    REPC(i, cur + 1, r) {
      chmin(dist[i], dist[l] + c);
      for (auto x : mp[i]) s.emplace(x);
    }
    chmax(cur, r);
  }
  ll ans = dist[n];
  if (ans == inf) ans = -1;
  cout << ans << '\n';
}

