    }
    SegmentTree seg(N + 1);
    sort(D, D + M, [](Data a, Data b) { return a.l < b.l; });
    seg.set(0, 0);
    REP(i, M)
    {
        ll min = seg.get(D[i].l - 1, D[i].r - 2);
        ll cost = min + D[i].c;
        ll t = seg.get(D[i].r - 1, D[i].r - 1);
        seg.set(D[i].r - 1, std::min(t, cost));
    }

    ll c = seg.get(N - 1, N - 1);
    if (c == INF)
        cout << -1 << endl;
    else
        cout << c << endl;
