const ll linf = 1LL << 60;
multiset<ll> distances;
priority_queue<mypair, vector<mypair>, greater<mypair>> que;
vector<tupdata> operations;
int N, M;

int main() {
	cin >> N >> M;
	operations.reserve(M);
	REP(_i, M) {
		int l;
		int r;
		ll c;
		cin >> l >> r >> c;
		operations.emplace_back(tupdata(--l, --r, c));
	}
	sort(ALL(operations));

	/* que
			first : index
			second : distance
	*/
	/* operations
			first : l
			second : r
			third : c
	*/

	ll ans = linf;

	REP(i, M) {
		int l = get<0>(operations[i]);
		int r = get<1>(operations[i]);
		ll c = get<2>(operations[i]);

		while (!que.empty() && que.top().first < l) {
			auto erase_it = distances.find(que.top().second);
			distances.erase(erase_it);
			que.pop();
		}

		ll cur_min_dist;
		if (l == 0) {
			cur_min_dist = 0;
		} else {
			if (distances.empty())
				break;
			cur_min_dist = *distances.begin();
		}

		ll cur_dist = cur_min_dist + c;
		distances.insert(cur_dist);
		que.push(mypair(r, cur_dist));

		if (r == N - 1) {
			chmin(ans, cur_dist);
		}
	}

	if (ans == linf)
		cout << -1 << endl;
	else
		cout << ans << endl;
}

