ll get_min(vector<vector<ll>>& rmq, int l, int r){
    if (l == r)
        return rmq[0][l];
    ll len = 1;
    int t = 0;
    while(2*len < r-l+1){
        len <<= 1;
        t++;
        rmq[t][l] = min(rmq[t-1][l], rmq[t-1][l+len/2]);
        rmq[t][r-len+1] = min(rmq[t-1][r-len+1], rmq[t-1][r-len+1+len/2]);
    }
    return min(rmq[t][l], rmq[t][r-len+1]);
}

void update(vector<vector<ll>>& rmq, int pos, ll newmin){
    rmq[0][pos] = min(rmq[0][pos], newmin);
    ll len = 1;
    FOR1(t, 19){
        if (pos+len >= rmq[t-1].size()) break;
        rmq[t][pos] = min(rmq[t-1][pos], rmq[t-1][pos+len]);
        len <<= 1;
    }
}

