			to[l].push_back(edge{r,c});
			for(int i = r; i > l; i--) to[i].push_back(edge{i-1,0});
	}

	vector<ll> d = dijkstra(0,to);

	if(d[n-1]==INF) cout << -1 << endl;
	else cout << d[n-1] << endl;
	return 0;
}

