LL dijkstra() {
    priority_queue< LP, vector< LP >, greater< LP > > pq;
    pq.push( MP( 1, 0 ) );
    bool visit[SIZE];
    for( int i = 0; i < SIZE; ++i ) {
        dist[i] = LINF;
        visit[i] = false;

    }

    while( !pq.empty() ) {
        LP node = pq.top(); pq.pop();
        if( visit[node.F] ) continue;
        visit[node.F] = true;

        if( node.F == n ) continue;

        for( int i = 0; i < graph[node.F].size(); ++i ) {
            LP p = graph[node.F][i];
            if( dist[p.F] > node.S + p.S ) {
                dist[p.F] = node.S + p.S;
                pq.push( MP( p.F, dist[p.F] ) );

            }
        }
    }

    return dist[n];
}

