std::vector<ll> seg;
void init(ll N){
  while(M<N) M*=2;
  M=M*2-1;
  for(int i=0;i<M;i++) {
    seg.push_back(INF);
  }
}
void update(ll a, ll b, ll l, ll r,  ll x, ll k){
  if(r<=a || b<=l) return;
  if(a<=l&&r<=b) {
    seg[k] = min(seg[k], x);
    return;
  }
  update(a, b, l, (l+r)/2, x, k*2+1);
  update(a, b, (l+r)/2, r, x, k*2+2);
}

ll query(ll a, ll b, ll l, ll r, ll k){
  if(r<=a || b<=l) return INF;
  ll tmp = seg[k];
  if(k>=M/2) return tmp;
  ll A = query(a, b, l, (l+r)/2, k*2+1);
  ll B = query(a, b, (l+r)/2, r, k*2+2);
  return min({tmp, A, B});
}
