} edge; // 辺を定義

typedef struct{
    long dist; //　計算された距離
    int v; // ノードのインデックス
} vtx;

bool operator< (const vtx a, const vtx b){
    return a.dist > b.dist;  // ascend　これで小さい順に　vtxが出てくる
}
bool operator> (const vtx a, const vtx b){
    return a.dist < b.dist;  // ascend　これで小さい順に　vtxが出てくる
}

long distance(int s, int g, vector<edge> * G, int N){  // 結局は隣接リストに行先のその辺のコストを渡せば十分である。
    long d[N];
    fill(d, d + N, INF);

    priority_queue< vtx > que;
    d[s] = 0;
    que.push(vtx{d[s], s});

    while(!que.empty()){
        vtx now = que.top(); que.pop();
        if(now.dist > d[now.v]) continue;
        for(edge e : G[now.v]){
            if(d[e.to] > d[now.v] + e.cost){
                d[e.to] = d[now.v] + e.cost;
                que.push(vtx{d[e.to], e.to});
            }         
        }
    }
    if(d[g] == INF) return -1;
    else return d[g];
}

