using namespace std;
typedef long long ll;
typedef pair<int, int> P;

const ll INF = 1e18;

ll dijkstra(int N, int s, int g, vector<vector<ll>> cost, vector<vector<int>> adj){

	vector<ll> d(N+1, INF);
	vector<bool> used(N+1, false);
	vector<int> back(N+1, -1);

    fill(d.begin(), d.end(), INF);
    fill(used.begin(), used.end(), false);
    fill(back.begin(), back.end(), -1);
    d[s] = 0;

	priority_queue<P, vector<P>, greater<P>> PQ;
	PQ.push(make_pair(s,0));
	used[s] = true;

    while(!PQ.empty()){
        pair<int, int> f = PQ.top(); PQ.pop();
		int u = f.first;
		used[u] = true;
		if(d[u] < f.second) continue;

        for(int j = 0; j < adj[u].size(); j++){
			int v = adj[u][j];
			if(used[v] == true) continue;
            if(d[v] > d[u] + cost[u][v]){
                d[v] = d[u] + cost[u][v];
				PQ.push(make_pair(v, d[v]));
                back[u] = v;
            }
        }
    }

	return d[g];
}

