void solve(){
    int n,m;
    cin>>n>>m;
    pair<pair<int,int>, int> arr[m];
    for(int i=0;i<m;i++){
        cin>>arr[i].first.first>>arr[i].first.second>>arr[i].second;
    }
    sort(arr, arr+m,comp);
    vector<int> dp(n+1,INF);
    dp[1] = 0;
    int i=0,d=1,base=0,maxx=1;
    while(i<m){
        d=maxx;
        while(i<m && arr[i].first.first<=d){
            //cout<<arr[i].first.first<<" "<<arr[i].first.second<<"\n";
            dp[arr[i].first.second] = min(dp[arr[i].first.second], dp[arr[i].first.first] + arr[i].second);
            maxx = max(maxx, arr[i].first.second);
            i++;
        }
        if(d==maxx) break;
        for(int j=maxx-1; j>d;j--){
            dp[j] = min(dp[j], dp[j+1]);
        }
        int temp=d+1;
        for(int j=d+1;j<=maxx;j++){
            if(dp[j]!=dp[d+1]){
                temp=j-1;
                break;
            }
        }
        maxx=temp;
        // for(int i=1;i<=n;i++){
