void _main()
{
    ll n; llin(n);
    ll m; llin(m);
    S V<t3> lrclist; llinl3(lrclist, m);

    S V<t2> edgelist[100005];
    S priority_queue_incr<t2> q;
    for (auto lrc : lrclist) {
        ll left = get<0>(lrc);
        ll right = get<1>(lrc);
        ll c = get<2>(lrc);
        edgelist[left].pb(t2(right, c));
        q.push(t2(left, 1));
        q.push(t2(right, -1));
    }

    ll cnt = 0;

    srep (v, 1, n+1) {
        while (q.size()) {
            auto item = q.top();
            ll vv = get<0>(item);
            ll diff = get<1>(item);
            if (vv > v) break;
            q.pop();
            cnt += diff;
        }
        if (cnt) edgelist[v+1].pb(t2(v, 0));
    }

    S priority_queue_incr<t2> dq;
    S ll costs[100005];
    rep (i, 100005) costs[i] = -1;

    dq.push(t2(0, 1));

    while (dq.size()) {
        auto item = dq.top(); dq.pop();
        ll cost = get<0>(item);
        ll v = get<1>(item);
        if (costs[v] >= 0) continue;
        costs[v] = cost;

        if (v == n) {
            cout << costs[v] << endl;
            return;
        }

        for (auto nvd : edgelist[v]) {
            ll nv = get<0>(nvd);
            ll nd = get<1>(nvd);
            if (costs[nv] >= 0) continue;
            dq.push(t2(cost + nd, nv));
        }
    }

    cout << -1 << endl;
}

