typedef long long ll;
typedef pair<ll, ll> pll;
typedef pair<pll, ll> tpl;

const int MAXN = 1e5 + 10;
const ll inf = 1e18;

int N, M;
ll L[MAXN], R[MAXN], C[MAXN];
ll D[MAXN];
ll F[MAXN];

ll SEG[MAXN * 4], LAZY[MAXN * 4];

void f(int here, int l, int r){
    SEG[here] = min(SEG[here], LAZY[here]);
    if(l != r){
        LAZY[here * 2] = min(LAZY[here * 2], LAZY[here]);
        LAZY[here * 2 + 1] = min(LAZY[here * 2 + 1], LAZY[here]);
    }
    LAZY[here] = inf;
}

void init(int here, int l, int r){
    SEG[here] = inf, LAZY[here] = inf;
    if(l == r) return;
    int mid = (l + r) / 2;
    init(here * 2, l, mid); init(here * 2 + 1, mid + 1, r);
}

void update(int here, int l, int r, int x, int y, ll val){
    f(here, l, r);
    if(y < l || r < x) return ;
    if(x <= l && r <= y) {
        LAZY[here] = val;
        f(here, l, r);
        return;
    }

    int mid = (l + r) / 2;
    update(here * 2, l, mid, x, y, val);    update(here * 2 + 1, mid + 1, r, x, y, val);
    SEG[here] = min(SEG[here * 2], SEG[here * 2 + 1]);
}

ll query(int here, int l, int r, int x, int y){
    f(here, l, r);
    if(y < l || r < x) return inf;
    if(x <= l && r <= y) return SEG[here];
    int mid = (l + r) / 2;
    ll res = query(here * 2, l, mid, x, y);
    res = min(res, query(here * 2 + 1, mid + 1, r, x, y));
    return res;
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M;
    for(int i = 1 ; i <= M ; i++) cin >> L[i] >> R[i] >> C[i];

    vector<tpl> V;
    for(int i = 1 ; i <= M ; i++){
        V.push_back(tpl(pll(L[i], R[i]), C[i]));
    }   

    sort(V.begin(), V.end());

    init(1, 1, N);
    update(1, 1, N, 1, 1, 0);
    for(auto val : V){
        int l = val.first.first, r = val.first.second;
        ll v = val.second;
        ll b = query(1, 1, N, l, l);
        update(1, 1, N, l, r, b + v);
    }

    ll ans = query(1, 1, N, N, N);
    if(ans == inf) ans = -1;
    cout << ans;
    return 0;
}

