const int INF = INT_MAX;
const ll LLINF = 1LL<<62;

class DIJKSTRA {
public:
    ll V;

    struct edge {
        ll to;
        ll cost;
    };

    typedef pair<ll, ll> PI; //firstは最短距離、secondは頂点の番号
    vector<vector<edge> >G;
    vector<ll> d; //これ答え。d[i]:=V[i]までの最短距離
    vector<ll> prev; //経路復元

    DIJKSTRA(ll size) {
        V = size;
        G = vector<vector<edge> >(V);
        prev = vector<ll> (V, -1);
    }

    void add(ll from, ll to, ll cost) {
        edge e = {to, cost};
        G[from].push_back(e);
    }

    void dijkstra(ll s) {
        //greater<P>を指定することでfirstが小さい順に取り出せるようにする
        priority_queue<PI, vector<PI>, greater<PI> > que;
        d = vector<ll> (V, INF);
        d[s] = 0;
        que.push(PI(0, s));

        while(!que.empty()) {
            PI p = que.top();
            que.pop();
            ll v = p.second;
            if(d[v] < p.first) continue;
            for(ll i = 0; i < G[v].size(); i++) {
                edge e = G[v][i];
                if(d[e.to] > d[v] + e.cost) {
                    d[e.to] = d[v] + e.cost;
                    prev[e.to] = v;
                    que.push(PI(d[e.to], e.to));
                }
            }
        }
    }
    vector<ll> get_path(ll t) {
        vector<ll> path;
        for(;t != -1; t = prev[t]) {
            //tがsになるまでprev[t]をたどっていく
            path.push_back(t);
        }
        //このままだとt->sの順になっているので逆順にする
        reverse(path.begin(),path.end());
        return path;
    }
    void show() {
        for(ll i = 0; i < d.size()-1; i ++) {
            cout << d[i] << " ";
        }
        cout << d[d.size()-1] << endl;
    }
};

int main(void) {

    ll n,m;
    cin>>n>>m;
    DIJKSTRA dj(n);

    for(ll i=0;i<m;i++){
        ll l,r,c;
        cin>>l>>r>>c;
        dj.add(l-1,r-1,c);
    }
    for(ll i=0;i<n-1;i++){
        dj.add(i+1,i,0);
    }
    dj.dijkstra(0);
    cout<<((dj.d[n-1]==INF)?-1:dj.d[n-1])<<endl;


}

