#define LLINF 12345678901234567LL

struct addedge{
	int L;
	int R;
	long long C;
};

vector<long long> dist;
int N,M,n;
vector<addedge> A;
set<int> s;

bool sort_addedge(const addedge &x,const addedge &y){
	if(x.R==y.R)return x.L<y.L;
	else return x.R<y.R;
}

void update(int i,long long x){
	i+=n-1;
	dist[i]=x;
	while(i>0){
		i=(i-1)/2;
		dist[i]=min(dist[i*2+1],dist[i*2+2]);
	}
}

long long query(int a,int b,int k,int l,int r){
	if(r<=a || b>=l)return LLINF;
	if(a<=l && r<=b)return dist[k];
	long long ret1=query(a,b,2*k+1,l,(l+r)/2);
	long long ret2=query(a,b,2*k+2,(l+r)/2,r);
	return min(ret1,ret2);
}

int main(){
