		cin >> a.L >> a.R >> a.C;
		a.L--;
		a.R--;
		A.push_back(a);
	}

	sort(A.begin(),A.end(),sort_addedge);

	update(0,0LL);
	s.insert(0);
	for(auto a:A){
		auto it=s.lower_bound(a.L);
		if(it!=s.end()){
			int f=*it;
			long long df=dist[f+n-1];
			long long dt=dist[a.R+n-1];
			if(df+a.C<dt){
				update(a.R,df+a.C);
				s.insert(a.R);
			}
		}
	}

	long long ans= (dist[N-1+n-1]==LLINF)?(-1):(dist[N-1+n-1]);
	cout << ans << endl;

