    static ll costs[100005];
    rep (i, 100005) costs[i] = 1e18;

    q.push(t2(0LL, 1LL));
    costs[1] = 0LL;
    auto tocheck = lrclist.begin();
    ll maxv = 0LL;

    while (!q.empty()) {
        auto cv = q.top(); q.pop();
        ll v = get<1>(cv);
        if (v < maxv) continue;
        maxv = v;
        debug_printf("xx1 v=%lld\n", v);
        auto stop = upper_bound(ALL(lrclist), t3(v, 1e18, 1e18));
        V<t2> crlist;
        for ( ; tocheck != stop; tocheck++) {
            ll nleft = get<0>(*tocheck);
            ll nright = get<1>(*tocheck);
            ll ncost = get<2>(*tocheck);
            debug_printf("== nleft=%lld v=%lld\n", nleft, v);
            assert(nleft <= v);
            crlist.pb(t2(ncost, nright));
        }
        sort(crlist);
        ll maxnv = -1LL;
        for (auto cr : crlist) {
            ll ncost = get<0>(cr);
            ll nright = get<1>(cr);
            if (nright <= maxnv) continue;
            maxnv = max(maxnv, nright);
            if (nright <= v) continue;
            costs[nright] = min(costs[nright], costs[v] + ncost);
            q.push(t2(costs[nright], nright));
        }
    }

    if (costs[cnt_v] >= 1e16) {
        cout << -1 << endl;
        return;
