struct segment_tree {
  struct node;
  using iter = vector<node>::iterator;

  struct node {
    int a, b;
    iter left, right;
    int64 minv, pass;
    void pushup() {
      minv = min(left->minv, right->minv);
    }
    void pushdown() {
      if (pass == INF) return;
      left->update(pass);
      right->update(pass);
      pass = INF;
    }
    void update(int64 pass) {
      minv = min(minv, pass);
      this->pass = min(this->pass, pass);
    }
  };

  vector<node> pool;
  iter last, root;

  iter _build(int a, int b) {
    iter cur = last++;
    cur->a = a;
    cur->b = b;
    cur->minv = cur->pass = INF;
    if (a + 1 == b) {
      if (a == 0) cur->minv = 0;
      return cur;
    }
    cur->left = _build(a, (a + b) / 2);
    cur->right = _build((a + b) / 2, b);
    cur->pushup();
    return cur;
  }

  void init(int n) {
    pool.resize(n * 2);
    last = pool.begin();
    root = _build(0, n);
  }

  void insert(iter cur, ii range, int64 pass) {
    if (cur->a >= range.first && cur->b <= range.second) {
      cur->update(pass);
      return;
    }
    cur->pushdown();
    if ((cur->a + cur->b) / 2 > range.first) {
      insert(cur->left, range, pass);
    }
    if ((cur->a + cur->b) / 2 < range.second) {
      insert(cur->right, range, pass);
    }
    cur->pushup();
  }

  int64 query(iter cur, ii range) {
    if (cur->a >= range.first && cur->b <= range.second) {
      return cur->minv;
    }
    cur->pushdown();
    int64 ret = INF;
    if ((cur->a + cur->b) / 2 > range.first) {
      ret = min(ret, query(cur->left, range));
    }
    if ((cur->a + cur->b) / 2 < range.second) {
      ret = min(ret, query(cur->right, range));
    }
    return ret;
  }
};

struct Edge {
  int L, R, c;
  bool operator <(const Edge& rhs) const {
    return L < rhs.L;
  }
};

