    Dijkstra dijkstra(N, 0);
    REP(i, M) {
        int L, R, C; cin >> L >> R >> C;
        --L; --R;
        dijkstra.add_edge(L, R, C);
    }
    REP(i, N - 1) {
        dijkstra.add_edge(i + 1, i, 0);
    }
    dijkstra.build();
    cout << dijkstra.shortest_path_value(N - 1) << endl;
}

