int cv;

int build(int L, int R) {
    int v = cv++;
    if (L == R) {
        g[v].push_back({L, 0});
    }
    else {
        int m = (L + R) >> 1;
        ch[v][0] = build(L, m);
        ch[v][1] = build(m + 1, R);
        g[v] = {{ch[v][0], 0}, {ch[v][1], 0}};
    }
    return v;
}

int build_r(int L, int R) {
    int v = cv++;
    if (L == R) {
        g[L].push_back({v, 0});
    }
    else {
        int m = (L + R) >> 1;
        ch[v][0] = build_r(L, m);
        ch[v][1] = build_r(m + 1, R);

        g[ch[v][0]].push_back({v, 0});
        g[ch[v][1]].push_back({v, 0});
    }
    return v;
}

vector<int> ver, ver_r;

void que(int l, int r, int x, int v, int v_r, int L, int R) {
    if (l > r)
        return;
    if (l == L && r == R) {
        ver.push_back(v);
        ver_r.push_back(v_r);
    }
    else {
        int m = (L + R) >> 1;
        que(l, min(m, r), x, ch[v][0], ch[v_r][0], L, m);
        que(max(m + 1, l), r, x, ch[v][1], ch[v_r][1], m + 1, R);
    }
}

