		int l,r; ll c;
		cin >> l >> r >> c;
		l--;r--;
		LRC[i] = tie(l,r,c);
	}
	SORT(LRC);
	MQ minq(N);
	minq.updete(0,0,0);
	FOR(i,0,M){
		ll l,r,c;
		tie(l,r,c) = LRC[i];
		ll v = minq.value(l);
		if(v>=INF)continue;
		minq.updete(l+1,r,c+v);
	}
	ll ans = minq.value(N-1);
	if(ans==INF)ans=-1;
	cout << ans << endl;
}

