#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair <int, int> ii;

const int Maxn = 100005;
const int Maxs = 524288;
const ll Inf = 1000000000000000000ll;

int n, m;
ll st[Maxs];
vector <ii> neigh[Maxn];

void Create(int v, int l, int r)
{
    st[v] = Inf;
    if (l < r) {
        int m = l + r >> 1;
        Create(2 * v, l, m);
        Create(2 * v + 1, m + 1, r);
    }
}

void Update(int v, int l, int r, int a, int b, ll val)
{
    if (l == a && r == b) st[v] = min(st[v], val);
    else {
        int m = l + r >> 1;
        if (a <= m) Update(2 * v, l, m, a, min(m, b), val);
        if (m + 1 <= b) Update(2 * v + 1, m + 1, r, max(m + 1, a), b, val);
    }
}

ll Get(int v, int l, int r, int x)
{
    ll res = st[v];
    if (l < r) {
        int m = l + r >> 1;
        if (x <= m) res = min(res, Get(2 * v, l, m, x));
        else res = min(res, Get(2 * v + 1, m + 1, r, x));
    }
    return res;
}

int main()
{
    scanf("%d %d", &n, &m);
    Create(1, 1, n);
    Update(1, 1, n, 1, 1, 0);
    for (int i = 0; i < m; i++) {
        int l, r, c; scanf("%d %d %d", &l, &r, &c);
        neigh[l].push_back(ii(r, c));
    }
    ll g;
    for (int i = 1; i <= n; i++) {
        g = Get(1, 1, n, i);
        if (g >= Inf) { printf("-1\n"); return 0; }
        for (int j = 0; j < neigh[i].size(); j++)
            Update(1, 1, n, i + 1, neigh[i][j].first, g + ll(neigh[i][j].second));
    }
    printf("%lld\n", g);
    return 0;
}

