int main(){

    int N, M;
    cin >> N >> M;

    int L[M], R[M], C[M];
    for(int i = 0; i < M; i++){
        cin >> L[i] >> R[i] >> C[i] ;
        L[i]--; R[i]--; 
    }

    bool bonded[N]; for(int i=0; i<N; i++) bonded[i] = false;
    for(int i = 0; i<M; i++){
        G[L[i]].emplace_back(edge{R[i], C[i]});
        G[R[i]].emplace_back(edge{L[i], C[i]});
        for(int j = L[i]; j < R[i]; j++){
            if(!bonded[j]){
                G[j+1].emplace_back(edge{j, 0});
                bonded[j] = true;
            }
        }
    }

    dijkstra(0, N);

    if(d[N-1] == INF) cout << -1 << endl;
    else cout << d[N-1] << endl;

    return 0;

}

void dijkstra(int s, int V){

    for(int i = 0; i<V; i++)    d[i] = INF;

    priority_queue< rte > que;
    d[s] = 0;
    que.push(rte{d[s], s});

    bool visited[V]; for(int i=0; i<V; i++) visited[i] = false;

    for(int i= 0; i < V; i++ ){
        if(que.empty()) return ;
        rte now = que.top(); que.pop();
        visited[now.v] = true;
        for(edge e : G[now.v]){
            if(!visited[e.to]){
                if(d[e.to] > d[now.v] + e.cost){
                    d[e.to] = d[now.v] + e.cost;
                    que.push(rte{d[e.to], e.to});
                }
            }
        }
    }
}

