    seg.update(0, 0);
    rep(i, 0, M){
        ll l = P[i].first.first, r = P[i].first.second;
        ll c = P[i].second;
        ll up = seg.getmin(l, N + 1) + c;
        if(seg.getmin(r, r + 1) > up)seg.update(r, up);
    }
    ll ans = seg.getmin(N-1, N);
    if(ans >= LLINF) cout << -1 << endl;
    else cout << ans << endl;

