const ll INF = 999999999999999;
const ll MOD = 998244353;
ll a, b, c, d, e, f, p, t, x, y, z, q, m, n, r, h, k, ans = 0, w, l;
vector<pair<PP,ll>> A;
struct segtree {
	ll N;
	vl dat;
	void init(ll n) {
		N = 1;
		while (N < n) N *= 2;
		dat = vl(N * 2);
		for (int i = 0; i < 2 * N - 1; i++)
			dat[i] = INF;
	}
	// update k th element
	void update(ll k, ll a) {
		k += N - 1; // leaf
		dat[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}
	// min [a, b)
	ll query(ll a, ll b) { return query(a, b, 0, 0, N); }
	ll query(ll a, ll b, ll k, ll l, ll r) {
		if (r <= a or b <= l) return INF;
		if (a <= l and r <= b) return dat[k];
		ll m = (l + r) / 2;
		return min(query(a, b, k * 2 + 1, l, m), query(a, b, k * 2 + 2, m, r));
	}

	ll at(ll a) {
		return dat[a + N - 1];
	}
};
void input() {
	cin >> n >> m;
	rep(i, m) {
		cin >> a >> b >> c;
		A.push_back({ {a,b},c });
	}
}
void solve() {
	sort(all(A));
	segtree seg;
	seg.init(n + 1);
	seg.update(1, 0);
	rep(i,m){
		x = A[i].first.first;
		y = A[i].first.second;
		z = A[i].second;
		t = seg.query(x, y + 1);
		h = seg.at(y);
		seg.update(y, min(z + t, h));
	}

	if(seg.at(n)>INF-1){
		cout << -1 << endl;
	}
	else cout << seg.at(n) << endl;
}

int main() {
	input();
	solve();
}

#include<bits/stdc++.h>
using namespace std;
#define FOR(i,a,b) for (int i=(a);i<(b);i++)
#define RFOR(i,a,b) for (int i=(b)-1;i>=(a);i--)
#define REP(i,n) for (int i=0;i<(n);i++)
#define RREP(i,n) for (int i=(n)-1;i>=0;i--)
typedef long long LL;

//根ノードを1としているので，
//左の子:k*2
//右の子:k*2+1
//親:floor(k/2)
//となる．
//根ノードを1とすると非再帰が書きやすい(二進数的性質が優れているため)のだが，
//再帰的に書くのであればどちらでも問題ない．
//int maxi[N*2];
//int lazy[N*2];
namespace LST_{
	using RET = LL;//葉の個数
	constexpr int BUF =1048576+20;
	RET t[BUF];
	int ptr=0;
	inline RET* get(const int size){
		ptr+=size;
		return t+ptr-size;
	}

}

struct LazySegTree{
	using T=LST_::RET;
	T* maxi;//ノードkに対応する区間の最大値
	T* lazy;//lazy[k]はノードkの配下全体をlazy[k]で塗りつぶすという命令を表す．lazy[k]=NILのときは何もしないと約束する.
	static const T NIL = 1e17+8;//lazyがこの値の時は更新しない
	//2^20=1048576, 2^19= 524288
	//2^18=262144,  2^17= 131072(2のべきでないといけない)
	static const int N = 262144;
	LazySegTree(){
		maxi=LST_::get(2*N);//最大値の配列の確保
		lazy=LST_::get(2*N);//遅延の確保
		//更新用
		REP(i,2*N){
			lazy[i]=NIL;
			maxi[i]=1e17;
		}
		//加算用
		//REP(i,2*N){
		//	lazy[i]=0;
		//	maxi[i]=0;
		//}
	}

	//kをvで塗りつぶす
	void setLazy(int k,T v){
		//更新用
		lazy[k]=v;
		maxi[k]=v;
		//加算用
		//lazy[k]+=v;
		//maxi[k]+=v;
	}
	void push(int k){
		//遅延命令がなにもなければ何もしない
		//更新用
		if(lazy[k]==NIL){
			return;
		}
		//加算用
		//if(lazy[k]==0){
		//	return;
		//}
		setLazy(k*2+0,lazy[k]);
		setLazy(k*2+1,lazy[k]);
		//子に命令を伝搬させたので，命令を空にする
		lazy[k] =NIL;
		//lazy[k]=0;//加算用
	}
	//最大値を求める
	T compar(T a, T b){
		//return max(a,b);
		return min(a,b);//最小値を求める場合はこっちを使う
	}

	void fix(int k){
		//ノードkに対応する区間の最大値は，「左の子の最大値」と「右の子の最大値」の最大値
		maxi[k]=compar(maxi[k*2],maxi[k*2+1]);
	}
	//区間[queryL,queryR)をvalで塗りつぶす
	void fill(int queryL, int queryR, T val, int k=1,int nodeL =0,int nodeR=N){
		 //クエリ区間とノード区間が交差していないのなら，これ以上，処理する必要はない
		if(nodeR <= queryL || queryR<=nodeL){
			return;
		}
		//ノード区間がクエリ区間に完全に覆われたら，遅延命令をセットして，さっさと帰る
		if(queryL <= nodeL && nodeR<=queryR){
			setLazy(k,val);
			return;
		}
		//ノードが下がる時には命令をpushする
		push(k);
		int nodeM =(nodeL + nodeR) /2;
		fill(queryL,queryR, val, k*2+0,nodeL, nodeM);
		fill(queryL,queryR, val ,k*2+1,nodeM, nodeR);
		//ノードが上がる時には情報をfixする
		fix(k);
	}
	//区間[queryL,queryR)の最大値を求める
	T maximum(int queryL, int queryR, int k=1,int nodeL=0,int nodeR =N){
		//クエリ区間とノード区間が交差していない
		if(nodeR<=queryL||queryR<=nodeL){
			return (1e17);
		}
		//ノード区間がクエリ区間に完全に覆われた
		if(queryL <= nodeL && nodeR <=queryR){
			return maxi[k];
		}
		//ノードが下がるときは命令をpushする
		push(k);
		int nodeM =(nodeL+nodeR)/2;
		T vl =maximum(queryL,queryR, k*2+0,nodeL,nodeM);
		T vr =maximum(queryL,queryR, k*2+1,nodeM,nodeR);
		return compar(vl,vr);
	}
};



int N,M;
