    int nodes = 4*nn+m;
    vector<vector<pair<int,ll>>> g(nodes);
    rep(i,1,nn) {
        g[2*i+1].emplace_back(2*(2*i)+1,0);
        g[2*i+1].emplace_back(2*(2*i+1)+1,0);
        g[2*(2*i)].emplace_back(2*i,0);
        g[2*(2*i+1)].emplace_back(2*i,0);
    }
    rep(i,0,n) g[2*(nn+i)+1].emplace_back(2*(nn+i),0);
    rep(j,0,m) {
        int u = 4*nn+j;
        function<void(int,int,int,int,int)> construct =
            [&](int i, int nodel, int noder, int left, int right) {
            if(left>=right || left>=noder || right<=nodel) return;
            if(left<=nodel && right>=noder) {
                g[2*i].emplace_back(u,c[j]);
                g[u].emplace_back(2*i+1,0);
                return;
            }
            int nodem = (nodel+noder)/2;
            construct(2*i, nodel, nodem, left, min(nodem, right));
            construct(2*i+1, nodem, noder, max(nodem,left), right);
