template<int MAX_N>
class Dijkstra {

public:
  struct Edge {
    int from;
    int to;
    ll cost;

    Edge(int from_, int to_, ll cost_)
      : from(from_), to(to_), cost(cost_) {}
  };

private:
  const int N;
  using P = pair<ll, int>; // (distance, node id)
  vector<vector<Edge> > edges;
  priority_queue<P, vector<P>, greater<P> > q;

public:
  vll d; // distance to Node i

  explicit Dijkstra(int N_) :
	  N(N_), d(N, LINF) {
    edges.resize(N);
  }

  // Add a directed edge.
  // For an undirected graph, the caller should add both directions.
  void add_edge(int from, int to, ll cost) {
    edges[from].emplace_back(from, to, cost);
  }

  void add_edge(const Edge& e) {
    edges[e.from].push_back(e);
  }

  void run(int start) {
    // Dijkstra
    // C++のpriority queueは値のupdateはできない
    // あるノードの距離が短く更新されたら、再度pushする
    // popするときに、確定済みであれば無視する

    q.emplace(0, start);
    d[start] = 0;
    //vector<bool> visited(N);

    while (!q.empty()) {
      P p = q.top(); q.pop();
      const int v = p.second;
      if (d[v] < p.first) continue;
      //if (visited[v]) continue;
      //visited[v] = true;

      for (const auto& e : edges[v]) {
        const ll new_cost = d[v] + e.cost;
        if (d[e.to] > new_cost) {
          d[e.to] = new_cost;
          q.emplace(new_cost, e.to); // 重複しているかもしれないpush
        }
      }
    }
  }

  // Return the distance from the root to i
  ll get_distance(int i) {
    return d[i];
  }
};
// ========== end of template ==========
