priority_queue<pair<int,int> >q;
void add(int k,int l,int r,int ll,int rr,int id)
{
	if(l>rr||r<ll)return ;
	if(l>=ll&&r<=rr)return E[k].push_back(id),void();
	add(k<<1,l,l+r>>1,ll,rr,id);
	add(k<<1|1,(l+r>>1)+1,r,ll,rr,id);
}
int find(int k,int l,int r,int ll,int rr)
{
	if(l>rr||r<ll||vis[k])return 0;
	if(l==r)return vis[k]=1,l;
	int ret=0;
	if(ret=find(k<<1,l,l+r>>1,ll,rr))return vis[k]=vis[k<<1]&vis[k<<1|1],ret;
	if(ret=find(k<<1|1,(l+r>>1)+1,r,ll,rr))return vis[k]=vis[k<<1]&vis[k<<1|1],ret;
	vis[k]=vis[k<<1]&vis[k<<1|1];
	return 0;
}
void query(int k,int l,int r,int p)
{
	int x;
	for(auto u:E[k])
		if(!used[u])
		{
			used[u]=1;
			q.push(make_pair(-dis[p]-w[u],u));
		}
	E[k].clear();
	if(l==r)return ;
	if(p<=l+r>>1)query(k<<1,l,l+r>>1,p);
	else query(k<<1|1,(l+r>>1)+1,r,p);	
}
