const long long INF = (1LL << 60);

// SegmentTree
template<typename T>
class SegTree{
public:
    int n;
    T defaultValue;
    vector<T> dat;

    SegTree(int m, T value){
        n = 1;
        while(n < m){
            n *= 2;
        }
        dat.assign(2 * n - 1, value);
        defaultValue = value;
    }

    void update(int i, T value){
        i += n - 1;
        dat[i] = value;
        while(i > 0){
            i = (i - 1) / 2;
            dat[i] = ope(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1){
        if(r < 0){
            r = n;
        }

        if(r <= a || b <= l){
            return defaultValue;
        }
        if(a <= l && r <= b){
            return dat[k];
        }
        else{
            T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
            T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
            return ope(vl, vr);
        }
    }

private:
    T ope(T a, T b){
        return min(a, b);
    }
};

int main(){

    int N, M;
    cin >> N >> M;
    vector<pair<pair<int, int>, int>> RLC(M);

    int l, r, c;
    for(int i = 0; i < M; i++){
        cin >> l >> r >> c;

        RLC[i] = make_pair(make_pair(r - 1, l - 1), c);
    }

    sort(RLC.begin(), RLC.end());

    SegTree<long long> minDistSegTree(N, INF);

    minDistSegTree.update(0, 0);

    for(int i = 0; i < M; i++){
        auto temp = RLC[i];
        int l = temp.first.second;
        int r = temp.first.first;
        int c = temp.second;

        long long minDist = minDistSegTree.query(l, r);
        if(minDist == INF){
            continue;
        }
        else{
            long long currentDist = minDistSegTree.query(r, r + 1);
            if(minDist + c < currentDist){
                minDistSegTree.update(r, minDist + c);
            }
        }
    }

    long long dist = minDistSegTree.query(N - 1, N);
    if(dist == INF){
        cout << -1 << endl;
    }
    else{
        cout << dist << endl;
    }

    return 0;
}

