		while (vindex < K && v[vindex].first.first <= curR) {
			q.push(v[vindex]);
			vindex++;

		}
		if (q.empty()) break;
		auto b = q.top();
		q.pop();

		for (ll i = curR+1; i <= b.first.second; i++) {
			ans[i] = min(ans[b.first.first] + b.second, ans[i]);
			curR++;
		}



	}


	if (ans[N - 1] == inf)
		cout << -1 << endl;
	else
		cout << ans[N - 1] << endl;


	return 0;
}

