const int N = 1e5 + 100;
const ll inf = 2e18;

int n, m;
int l[N], r[N], c[N];

ll tree[2 * N];

void update(int p, ll value)
{
	p += n;
	if (value > tree[p]) return;
	tree[p] = value;
    for (; p > 1; p >>= 1)
        tree[p >> 1] = min(tree[p], tree[p ^ 1]);
}

ll query(int l, int r)
{
    ll res = inf;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
        if (l & 1)
            res = min(res, tree[l++]);
        if (r & 1)
            res = min(res, tree[--r]);
    }
    return res;
}

void load()
{
	scanf("%d%d", &n, &m);
	FOR(i, m) {
		scanf("%d%d%d", l + i, r + i, c + i);
		l[i]--; r[i]--;
	}
}

void solve()
{
	FOR(i, (2*N)) tree[i] = inf;
	update(0, 0);
	int qs[m]; FOR(i, m) qs[i] = i;
	sort(qs, qs + m, [&](int x, int y) {
			if (r[x] == r[y] && l[x] == l[y]) return x < y;
			if (r[x] == r[y]) return l[x] < l[y];
			return r[x] < r[y];
			});
	FOR(j, m) {
		int i = qs[j];
		update(r[i], query(l[i], r[i] + 1) + c[i]);
	}
	ll sol = query(n-1, n);
	if (sol < inf) printf("%lld\n", sol);
	else printf("-1\n");
}

int main()
{
    load();
    solve();
    return 0;
}

