        L--, R--;
        edge e = {L, C};
        es[R].pb(e);
    }
    rep(i, N){
        if(es[i].empty()) continue;
        ll tmp = INF;
        for(auto &e: es[i]){
            ll m = seg.query(e.from, i);
            tmp = min(tmp, m+e.cost);
        }
        seg.update(i, tmp);
    }
    ll res = seg.query(N-1, N);
    if(res == INF) cout << -1 << endl;
    else cout << res << endl;
}

