using namespace std;
using ll = long long;
constexpr int inf = 1000000000;
constexpr ll INF = 1000000000000000000;

struct Edge {int to; ll cost;};

int main() {
    int N_, M;
    cin >> N_ >> M;
    int N = 1;
    while (N < N_) N <<= 1;
    vector<vector<Edge>> G(5 * N - 2 + 2 * M);
    for (int i = 0; i < N - 1; ++i) {
        G[i].push_back(Edge{2 * i + 1, 0});
        G[i].push_back(Edge{2 * i + 2, 0});
    }
    for (int i = N - 1; i < 2 * N - 1; ++i) {
        G[i].push_back(Edge{i + 3 * N - 1, 0});
    }
    for (int i = 2 * N - 1; i < 3 * N - 2; ++i) {
        G[2 * i - 2 * N + 2].push_back(Edge{i, 0});
        G[2 * i - 2 * N + 3].push_back(Edge{i, 0});
    }
    for (int i = 3 * N - 2; i < 4 * N - 2; ++i) {
        G[i + N].push_back(Edge{i, 0});
    }
    rep(i, M) {
        int L, R;
        ll C;
        cin >> L >> R >> C;
        --L;
        vector<int> S;
        L += N - 1;
        R += N - 1;
        while (R - L) {
            if (!(L & 1)) {
                S.push_back(L);
                ++L;
            }
            if (!(R & 1)) {
                --R;
                S.push_back(R);
            }
            L = (L - 1) >> 1;
            R = (R - 1) >> 1;
        }
        for (int x : S) {
            G[x + 2 * N - 1].push_back(Edge{5 * N - 2 + i * 2, 0});
            G[5 * N - 1 + i * 2].push_back(Edge{x, 0});
        }
        G[5 * N - 2 + i * 2].push_back(Edge{5 * N - 1 + i * 2, C});
    }
    vector<ll> dist(5 * N - 2 + 2 * M, INF);
    vector<int> used(5 * N - 2 + 2 * M, 0);
    priority_queue<pair<ll, int>> pq;
    dist[4 * N - 2] = 0;
    pq.push(pair<ll, int>{0, 4 * N - 2});
    while (!pq.empty()) {
        int v = pq.top().second;
        pq.pop();
        if (used[v]) continue; 
        for (auto e : G[v]) {
            ll alt = dist[v] + e.cost;
            if (alt < dist[e.to]) {
                dist[e.to] = alt;
                pq.push(pair<ll, int>{-alt, e.to});
            }
        }
        used[v] = 1;
    }
    if (dist[4 * N + N_ - 3] == INF) cout << -1 << "\n";
    else cout << dist[4 * N + N_ - 3] << "\n";
