struct SegmentTree {
private:
    long n;
    std::vector<long> node;

public:
    SegmentTree(std::vector<long> v) {
        long sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, LINF);
        for(long i=0; i<sz; i++) node[i+n-1] = v[i];
        for(long i=n-2; i>=0; i--) node[i] = std::min(node[2*i+1], node[2*i+2]);
    }

    void update(long x, long val) {
        x += (n - 1);
        node[x] = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = std::min(node[2*x+1], node[2*x+2]);
        }
    }

    long getmin(long a, long b, long k=0, long l=0, long r=-1) {
        if(r < 0) r = n;
        if(r <= a || b <= l) return LINF;
        if(a <= l && r <= b) return node[k];

        long vl = getmin(a, b, 2*k+1, l, (l+r)/2);
        long vr = getmin(a, b, 2*k+2, (l+r)/2, r);
        return std::min(vl, vr);
    }
};

