vector<pii>G[N];
int n,m;
ll dis[N];

int getRoot(int l,int r){
    int ans=l+r;
    if(l==r || (ans&1)) return ans;
    return ans+1;
}

void addEdge(int u,int v,int w,int flag=0){
    if(flag==0) G[u].push_back(pii(v,w));
    else G[v].push_back(pii(u,w));
}

void dfs(int l,int r,int flag,int add){
    if(l==r){
        if(flag==0)
            addEdge(getRoot(l,r),getRoot(l,r)+2*n,0,0);
        return ;
    }
    int m=(l+r)>>1;
    addEdge(getRoot(l,r)+add,getRoot(l,m)+add,0,flag);
    addEdge(getRoot(l,r)+add,getRoot(m+1,r)+add,0,flag);
    dfs(l,m,flag,add);
    dfs(m+1,r,flag,add);
}

void dfs2(int l,int r,int a,int b,int c,int cur){
    if(l==a && r==b){
        addEdge(getRoot(l,r)+2*n,cur,0);
        addEdge(cur,getRoot(l,r),c);
        return ;
    }
    int m=(l+r)>>1;
    if(b<=m) dfs2(l,m,a,b,c,cur);
    else if(a>m) dfs2(m+1,r,a,b,c,cur);
    else{
        dfs2(l,m,a,m,c,cur);
        dfs2(m+1,r,m+1,b,c,cur);
    }
}

priority_queue< pii,vector<pii>,greater<pii> > que;

void dijkstra(int s){
    for(int i=0;i<N;i++) dis[i]=INF;
    dis[s]=0;
    que.push(pii(0,s));
    while(!que.empty()){
        pii t=que.top();
        que.pop();
        int u=t.second;
        if(dis[u]<t.first) continue;
        for(auto e:G[u]){
            int v=e.first;
            if(dis[v]>e.second+dis[u]){
                dis[v]=e.second+dis[u];
                que.push(pii(dis[v],v));
            }
        }
    }
}

void solve(){
    scanf("%d%d",&n,&m);
    dfs(1,n,0,0);
    dfs(1,n,1,2*n);
    int cur=4*n;
    for(int i=1;i<=m;i++){
        int l,r,c;
        scanf("%d%d%d",&l,&r,&c);
        dfs2(1,n,l,r,c,++cur);
    }
    dijkstra(getRoot(1,1));
    ll ans=dis[getRoot(n,n)];
    if(ans>=INF) ans=-1;
    printf("%lld\n",ans);
}

