//-------------------------------------

struct LazyRMQ
{
private:
    ll n;
    vector<ll> node, lazy;
    vector<bool> lazyFlag;

public:
    LazyRMQ(vector<ll> v)
    {
        ll sz = (ll)v.size();
        n = 1;
        while (n < sz)
        {
            n *= 2;
        }
        node.resize(2 * n - 1);
        lazy.resize(2 * n - 1, LLINF);
        lazyFlag.resize(2 * n - 1, false);
        for (ll i = 0; i < sz; i++)
        {
            node[i + n - 1] = v[i];
        }
        for (ll i = n - 2; i >= 0; i--)
        {
            node[i] = min(node[2 * i + 1], node[2 * i + 2]);
        }
    }

    void eval(ll now, ll l, ll r)
    {
        if (lazyFlag[now])
        {
            node[now] = lazy[now];
            if (r - l > 1)
            {
                lazy[2 * now + 1] = lazy[2 * now + 2] = lazy[now];
                lazyFlag[2 * now + 1] = lazyFlag[2 * now + 2] = true;
            }
            lazyFlag[now] = false;
        }
    }

    void update(ll a, ll b, ll x, ll now = 0, ll l = 0, ll r = -1)
    {
        if (r < 0)
        {
            r = n;
        }
        eval(now, l, r);
        if (b <= l || r <= a)
        {
            return;
        }
        if (a <= l && r <= b)
        {
            lazy[now] = x;
            lazyFlag[now] = true;
            eval(now, l, r);
        }
        else
        {
            update(a, b, x, 2 * now + 1, l, (l + r) / 2);
            update(a, b, x, 2 * now + 2, (l + r) / 2, r);
            node[now] = min(node[2 * now + 1], node[2 * now + 2]);
        }
    }

    ll getmin(ll a, ll b, ll now = 0, ll l = 0, ll r = -1)
    {
        if (r < 0)
        {
            r = n;
        }
        eval(now, l, r);
        if (b <= l || r <= a)
        {
            return LLINF;
        }
        if (a <= l && r <= b)
        {
            return node[now];
        }
        ll vl = getmin(a, b, 2 * now + 1, l, (l + r) / 2);
        ll vr = getmin(a, b, 2 * now + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
};

