constexpr ll INF = LLONG_MAX / 3;

class segtree {
  private:
    int n;
    vector<ll> local, global;
    void update_impl(int l, int r, ll x, int k, int a, int b) {
      if (r <= a || b <= l) return;
      local[k] = min(local[k], x);
      if (l <= a && b <= r) {
        global[k] = min(global[k], x);
        return;
      }
      int m = (a + b) / 2;
      update_impl(l, r, x, 2 * k, a, m);
      update_impl(l, r, x, 2 * k + 1, m, b);
    }
    ll minimum_impl(int l, int r, int k, int a, int b) {
      if (r <= a || b <= l) return INF;
      if (l <= a && b <= r) return local[k];
      int m = (a + b) / 2;
      ll left = minimum_impl(l, r, 2 * k, a, m),
         right = minimum_impl(l, r, 2 * k + 1, m, b);
      return min({left, right, global[k]});
    }
  public:
    segtree(int n_) {
      n = 1;
      while (n < n_)
        n *= 2;
      global.assign(2 * n, INF);
      local.assign(2 * n, INF);
    }
    void update(int l, int r, ll x) {
      update_impl(l, r, x, 1, 0, n);
    }
    ll minimum(int l, int r) {
      return minimum_impl(l, r, 1, 0, n);
    }
};

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  int n, m;
  cin >> n >> m;
  segtree tree(n);
  vector<tuple<int, int, ll>> edges(m);
  for (auto& t : edges)
    cin >> get<0>(t) >> get<1>(t) >> get<2>(t);
  sort(begin(edges), end(edges));
  tree.update(0, 1, 0);
  for (auto&& tup : edges) {
    int f, t;
    ll l;
    tie(f, t, l) = tup;
    f--; t--;
    ll current = tree.minimum(f, t + 1);
    tree.update(f, t + 1, current + l);
  }
  ll dist = tree.minimum(n - 1, n);
  cout << (dist == INF ? -1 : dist) << endl;
}

