const int N = 1<<17;
ll seg[2*N];
ll lazy[2*N];
const ll INF = 1ll<<60;
void push(int k){
    if(lazy[k] == INF)return;
    CHMIN(seg[k], lazy[k]);
    if(k<N-1){
        CHMIN(lazy[2*k+1], lazy[k]);
        CHMIN(lazy[2*k+2], lazy[k]);
    }
    lazy[k] = INF;
}
void add(int l, int r, ll v, int a, int b, int k){
    push(k);
    if(r<=a || b<=l)return;
    if(l<=a && b<=r){
        CHMIN(lazy[k], v);
        push(k);
        return;
    }
    int m = (a+b)/2;
    add(l,r,v,a,m,2*k+1);
    add(l,r,v,m,b,2*k+2);
    seg[k] = min(seg[2*k+1], seg[2*k+2]);
}
ll query(int l, int r, int a, int b, int k){
    push(k);
    if(r<=a || b<=l)return 1ll<<60;
    if(l<=a && b<=r)return seg[k];
    int m = (a+b)/2;
    return min(query(l,r,a,m,2*k+1), query(l,r,m,b,2*k+2));
}

