ll solve() {
    ll INF = 1LL<<60;
    ll N, M;
    cin >> N >> M;
    vector<ll> L(M), R(M), C(M);
    vector<pii> ix;
    for ( int i = 0; i < M; i++ ) {
        cin >> L[i] >> R[i] >> C[i];
        L[i]--, R[i]--;
        ix.push_back(pii(L[i], i));
    }
    sort(ix.begin(), ix.end());
    priority_queue<pii, vector<pii>, greater<>> q;  //d,r
    ll d = 0;
    int ii = 0;
    vector<ll> dp(N+1, INF);
    dp[0] = 0;
    while ( ii < M && ix[ii].first == 0 ) {
        int j = ix[ii].second;
        q.push(pii(dp[0]+C[j],R[j]));
        ii++;
    }
    if ( !q.empty() && q.top().second <= 0 ) q.pop();
    for ( ll l = 1; l <= N-1; l++ ) {
        dp[l] = min(dp[l], q.top().first);
        while ( ii < M && ix[ii].first == l ) {
            int j = ix[ii].second;
            q.push(pii(dp[l]+C[j],R[j]));
            ii++;
        }
        if ( !q.empty() && q.top().second <= l ) q.pop();
        if ( q.empty() ) return -1;
    }
    return dp[N-1];
}

