struct MQ{//平方分割 0-index
	ll n,rn,bn,Q=0;
	vector<ll> a,b,at,bt;
	MQ(ll n_){
		n = n_; rn = sqrt(n); bn = ceil((double)n/rn);
		a.resize(n,INF);at.resize(n,0);
		b.resize(bn,INF);bt.resize(n,0);
	}
	ll value(ll s){
		if(a[s]>b[s/rn])a[s] = b[s/rn];
		return a[s];
	}
	void updete(ll s,ll t,ll x){
		Q++;
		FOR(i,s,t+1){
			if(i%rn==0 && (i+rn-1)<=t){
				if(x<b[i/rn])b[i/rn]=x;
				bt[i/rn] = Q;
				i += rn-1;
			}else{
				if(a[i]>x)a[i]=x;
				at[i] = Q;
			}
		}
	}
};



