using LL = long long;
using PII = pair<int, int>;

struct Tree {
	using T = LL;
	T f(T a, T b) { return min(a, b); }
	vector<T> nodes;
	int size = 1;

	Tree(int n, T val = 0) {
		while(size < n) size *= 2;
		nodes.resize(size * 2, val);
	}


	T get(int pos) {
		T ret = nodes[pos += size];
		while(pos /= 2)
			ret = f(ret, nodes[pos]);
		return ret;
	}

	void update(int l, int r, T val) {
		l += size, r += size;
		for(int v : {l, r}) 
			nodes[v] = f(nodes[v], val);
		while(l + 1 < r) {
			if(l % 2 == 0)
				nodes[l + 1] = f(nodes[l + 1], val);
			if(r % 2 == 1)
				nodes[r - 1] = f(nodes[r - 1], val);
			l /= 2, r /= 2;
		}
	}
};

