    cin >> N >> M;

    vector<map<int, int>> edge(N);
    rep(i, N-1) {
        edge[i+1][i] = 0;
    }

    rep(i, M) {
        int L, R, C;
        cin >> L >> R >> C;
        --L; --R;
        if (edge[L].find(R) == edge[L].end()) {
            edge[L][R] = C;
        } else {
            edge[L][R] = min(C, edge[L][R]);
        }
    }

    vector<bool> visited(N);
    vector<int> costTo(N, INT_MAX);
    costTo[0] = 0;
    priority_queue<pair<int, int>> q;  //! (cost, dest)
    q.push({0, 0});

    while (!q.empty()) {
        auto c = q.top(); q.pop();
        int cost = -c.first; 
        int curr = c.second;
        if (!visited[curr]) {
            visited[curr] = true;
            costTo[curr] = min(cost, costTo[curr]);
            for (auto next: edge[curr]) {
                int nextCost = costTo[curr] + next.second;
                q.push({-nextCost, next.first});
            }
        }
    }

    LL ans = -1;
    if (visited[N-1]) {
        ans = costTo[N-1];
    }
    cout << ans << endl;

    return 0;
}

