void build(int v, int tl, int tr){ //По массиву arr строим
    if(tl==tr){
        t[v]=dp[tl];
        return;
    }
    int tmp=(tl+tr)>>1;
    build( 2*v, tl, tmp);
    build( 2*v+1, tmp+1, tr);
    t[v]=min(t[2*v],t[2*v+1]); //К примеру это построили сумму на отрехке l,r  - можно кучу всего другого
}//o(n)

ll sum(int v, int tl, int tr, int l, int r){
    if(l>r) return inf;
    if(l==tl && r==tr) return t[v];
    int tmp=(tl+tr)/2;
    return min(sum(2*v, tl,tmp, l, min(r,tmp)), sum(2*v+1, tmp+1, tr, max(l,tmp+1),r));
}//o(logn)

void update(int v, int tl, int tr, int pos, ll new_el){//Хотим пересчитать дерево, если arr[pos]=new_el;
    if(tl==tr) {
        t[v]=new_el;
        return;
    }
    int tmp=(tl+tr)>>1;
    if(pos<=tmp) update(2*v, tl,tmp,pos,new_el);
    else update(2*v+1,tmp+1,tr, pos,new_el);
    t[v]=min(t[2*v],t[2*v+1]);
}//o(logn)



