const LL INF = 1e16;
const int N = 2e5 + 5;
LL s[N << 2];
inline void pushup(int p) {
    s[p] = min(s[p << 1], s[p << 1 | 1]);
}

inline void build(int p, int l, int r) {
    if(l == r) {
        s[p] = INF;
        return;
    }
    int mid = (l + r) >> 1;
    build(p << 1, l, mid); build(p << 1 | 1, mid + 1, r);
    pushup(p);
}

inline LL query(int p, int l, int r, int x, int y) {
    if(x <= l && r <= y) return s[p];
    int mid = (l + r) >> 1;
    LL ans = INF;
    if(x <= mid) ans = min(ans, query(p << 1, l, mid, x, y));
    if(y > mid) ans = min(ans, query(p << 1 | 1, mid + 1, r, x, y));
    return ans;
}

inline void update(int p, int l, int r, int x, int v) {
    if(l == r) {
        if(v < s[p]) s[p] = v;
        return;
    }
    int mid = (l + r) >> 1;
    if(x <= mid) update(p << 1, l, mid, x, v);
    else update(p << 1 | 1, mid + 1, r, x, v);
    pushup(p);
}
