            int l = G[i][j].l, w = G[i][j].w;
            if(l == 1) update(1, 1, n, i, w);
            else {
                LL res = query(1, 1, n, l, i);
                if(res <= INF) update(1, 1, n, i, w + res);
            }
        }
    }
    LL ans = query(1, 1, n, n, n);
    if(ans >= INF) cout << -1 << endl;
    else printf("%lld\n", ans);
