void dijkstra(auto &G, auto &dis, int s)
{
  /*
  ダイクストラ法。任意の始点から各点への最短距離を求める。計算量は O((V+E)logV)。
  引数のグラフは 0-indexed の隣接リストを想定。要素は、PII(to, weight)。
  始点から各点までの距離を格納する配列を用意し、参照渡しする。すべての要素をINFで初期化しておく。
  */
  dis[s] = 0;
  priority_queue< pair<LL, int>, vector<pair<LL, int>>, greater<pair<LL, int>> > q; // 値の小さい要素を優先
  q.push({0, s});
  while(!q.empty())
  {
    pair<LL, int> node = q.top();
    q.pop();
    int u = node.second;
    LL c = node.first;
    REPx(x, G[u])
    {
      int v = x.first;
      LL w = x.second;
      if (c + w < dis[v])
      {
        dis[v] = c + w;
        q.push({dis[v], v});
      }
    }
  }
}

int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);
  int n, m;
  cin >> n >> m;
  vector<vector<pair<int, LL>>> G(n, vector<pair<int, LL>>());
  REP2(i, 1, n) G[i].push_back({i-1, 0});
  REP(i, m)
  {
    int L, R;
    LL C;
    cin >> L >> R >> C;
    G[L-1].push_back({R-1, C});
  }
  VLL dis(n, INF);
  dijkstra(G, dis, 0);
  if (dis[n-1] != INF) cout << dis[n-1] << endl;
  else cout << -1 << endl;

  return 0;
}

