template<typename T> struct pq_small{
	priority_queue<T,vector<T>,greater<T> > pq;
	void push(T x){
		pq.push(x);
	}

	void pop(){
		pq.pop();
	}

	int size(){
		return pq.size();
	}

	bool empty(){
		return pq.empty();
	}

	T top(){
		return pq.top();
	}
};

int n,m;

vector<pair<int,ll>> ra[100005];

ll dis[100005];

pq_small<pair<int,ll>> kill;
multiset<ll> val;

const ll inf=1e18;

int main(int argc,char* argv[]){
	qi;
	cin>>n>>m;
	for(int i=0;i<m;i++){
		int a,b,c;
		cin>>a>>b>>c;
		a--;b--;
		ra[a].push_back(make_pair(b,c));
	}

	for(int i=0;i<n;i++){

//		cout<<"Current at "<<i<<endl;
//		for(int j:val){
//			cout<<j<<" ";
//		}
//		cout<<endl;

		//value
		if(i==0){
			dis[i]=0;
		}else{
			if(val.empty()){
				dis[i]=inf;
			}else{
				dis[i]=*val.begin();	
			}

		}

		//remove
		while(!kill.empty()){
			pair<int,ll> last=kill.top();
			if(last.first==i){
				val.erase(last.second);
				kill.pop();
//				cout<<"Remove:"<<last.second<<endl;
			}else{
				break;
			}
		}

		//shoot the bullet
		for(pii x:ra[i]){
			ll v=0ll+x.second+dis[i];
//			cout<<"INsert "<<x.first<<" "<<v<<endl;
			kill.push(make_pair(x.first,v));
			val.insert(v);
		}


	}

	if(dis[n-1]>=inf){
		cout<<"-1";
	}else{
		cout<<dis[n-1]<<endl;	
	}

	return 0;
}

