template <class V = ll, bool max = false, V defval = (V)1e16>
struct SegTreeT{
    SegTreeT *l, *r;
    int left, right;
    V value = defval;
    SegTreeT(int size):SegTreeT(0, size - 1){ }
    SegTreeT(int st, int lt): left(st), right(lt){
        if(left == right){
            l = r = nullptr;
        }else{
            l = new SegTreeT(left, (right - left) / 2 + left);
            r = new SegTreeT((right - left) / 2 + left + 1, right);
        }
    }
    void set(int lv, int rv, V val){
        if(lv <= left && right <= rv){
            value = (max ^ (value < val)) ? value : val;
        }else if(l){
            l->set(lv, rv, val);
            r->set(lv, rv, val);
        }
    }
	V getVal(int idx){
		if(right < idx || idx < left){ return defval; }
        ll ret = value;
        if(l){
            //TODO
            ret = min(ret, l->getVal(idx));
            ret = min(ret, r->getVal(idx));
        }
        return ret;
	}
};
