    seg.set(0, 0);
    seg.set(1, 0);
    seg.build();
    for (int i = 0; i < M; i++)
    {
        int l = Es[i].l;
        int r = Es[i].r;
        ll c = Es[i].c;
        ll dpr = seg.query(l, r + 1) + c;
        if(seg.query(r,r+1) > dpr) seg.update(r, dpr);
    }
    ll ans = seg.query(N,N+1);
    if(ans==INF) cout << -1 << endl;
    else cout << ans << endl;
    return 0;
}   

