template <typename T>
struct RadixHeap {
    using uint = uint64_t;
    vector<pair<uint, T>> v[65];
    uint size, last;

    RadixHeap() : size(0), last(0) {}

    bool empty() const { return size == 0; }

    inline int getbit(int a) { return a ? 64 - __builtin_clz(a) : 0; }

    void push(uint key, const T &value) {
        ++size;
        v[getbit(key ^ last)].emplace_back(key, value);
    }

    pair<uint, T> pop() {
        if(v[0].empty()) {
            int idx = 1;
            while(v[idx].empty()) ++idx;
            last = min_element(begin(v[idx]), end(v[idx]))->first;
            for(auto &p : v[idx]) v[getbit(p.first ^ last)].emplace_back(p);
            v[idx].clear();
        }
        --size;
        auto ret = v[0].back();
        v[0].pop_back();
        return ret;
    }
};

template <typename T>
vector<T> dijkstra(WeightedGraph<T> &g, int s) {
    const auto INF = numeric_limits<T>::max();
    vector<T> dist(g.size(), INF);
    vector<int> b(g.size(), -1);

    RadixHeap<int> que;
    dist[s] = 0;
    que.push(dist[s], s);
    while(!que.empty()) {
        T cost;
        int idx;
        tie(cost, idx) = que.pop();
        if(dist[idx] < cost) continue;
        for(auto &e : g[idx]) {
            auto next_cost = cost + e.cost;
            if(dist[e.to] <= next_cost) continue;
            dist[e.to] = next_cost;
            b[e.to] = idx;
            que.push(dist[e.to], e.to);
        }
    }
    return dist;
}

