struct Tmp
{
public:
  ll inf = std::numeric_limits<ll>::max();
  int N, M;
  using P = pair<int, ll>;
  vector<vector<P>> graph;
  vector<ll> distance;
  Tmp(int N, int M)
  : N(N), M(N)
  , graph(N)
  , distance(N, inf)
  {}

  void operator() () {
    for (int i = 0; i < M; ++i) {
      int l, r, c; cin >> l >> r >> c;
      --l; --r;
      graph[l].push_back({r, c});
      graph[r].push_back({l, c});
    }

    distance[0] = 0;
    std::priority_queue<pair<ll, int>> que{};
    for (const auto& p : graph[0]) {
      auto n = p.first;
      auto d = p.second;
      if (chmin(distance[n], distance[0] + d)) {
        que.push({d, n});
      }
    }
    while (!que.empty()) {
      auto p = que.top(); que.pop();
      auto cost = p.first;
      auto current = p.second;
      for (const auto& edge : graph[current]) {
        auto next = edge.first;
        auto dis = edge.second;
        auto newCost = cost + dis;
        if (chmin(distance[next], newCost)) {
          que.push({newCost, next});
        }
      }
    }
    auto ans = distance[N-1] == inf ? -1 : distance[N-1];
    cout << ans << CRLF;
  }
};

void solve(void)
{
  int N, M; cin >> N >> M;
  Tmp t(N, M);
  t();
  return;
}

