void solve()
{
	READ(int, N, M);

	using P = pair<int, llong>;

	vector<vector<P>> gi(N + 1);
	vector<vector<P>> gd(N + 1);

	REP(i, M)
	{
		READ(int, L, R, C); L--, R--;
		gi[L].emplace_back(R, C);
		gd[R + 1].emplace_back(R, C);
	}

	using ikisaki = int;
	using cost = llong;
	map<ikisaki, multiset<cost>> s;
	auto t = SegTree<cost>(N);
	t[0] = 0;
	t.rebuild();

	REP(i, N)
	{
		FORE(p : gi[i])
		{
			s[p.first].insert(p.second);
		}

		FORE(p : gd[i])
		{
			s[p.first].erase(p.second);
			if (s[p.first].empty())
			{
				s.erase(p.first);
			}
		}

		auto a = t[i];
		if (t[i] != INF(llong))
		{
			if (t[i] < t.query(i + 1, N))
			{
				FORE(r : s)
				{
					if (!r.second.empty())
					{
						t.update(
							r.first,
							std::min(t[r.first], t[i] + *r.second.begin()));
					}
				}
			}
		}
	}

	WRITE(t[N - 1] < INF(llong) ? t[N - 1] : -1);
}

