  std::vector< std::vector< std::pair< int, lint > > > graph(n);
  rep(i, 1, n) {
    graph.at(i).emplace_back(i - 1, 0);
  }
  loop(m) {
    int l, r, x;
    std::cin >> l >> r >> x;
    l--, r--;
    graph.at(l).emplace_back(r, x);
  }
  // debug(graph);

  auto dist = dijkstra(graph, 0, inf);
  // debug(dist);
  auto ans = dist.back();
  if (ans == inf) ans = -1;
  std::cout << ans << std::endl;
  return 0;
}

