void dijkstra(ll s, vector<vll> edge){
  priority_queue<pll, vector<pll>, greater<pll>> que;
  d[s] = 0;
  que.push(pll(0, s));

  while(!que.empty()){
    pll p = que.top();
    que.pop();
    ll v = p.SE;
    if(d[v] < p.first)
      continue;
    for(ll i = 0; i < edge[v].size(); i++){
      ll cost = edge[v][i];
      if(d[i] > d[v] + cost){
        d[i] = d[v] + cost;
        que.push(pll(d[i], i));
      }
    }

  }
}

