template<class Monoid> struct SegmentTree {
    using Function = function< Monoid(Monoid, Monoid) >;

    int N; vector<Monoid> segment;
    const Function func;
    const Monoid id;

    SegmentTree(int n, const Function func, const Monoid id) : func(func), id(id) {
        N = 1;
        while (N < n) N <<= 1;
        segment.assign(2 * N, id);
    }

    void set(int num, Monoid x) {
        segment[N + num] = x;
    }
    void build() {
        for (int k = N - 1; k > 0; k--) {
            segment[k] = func(segment[2*k], segment[2*k+1]);
        }
    }
    void update(int k, Monoid x) {
        k = k + N; segment[k] = x;
        while(k >>= 1) {
            segment[k] = func(segment[2*k], segment[2*k+1]);
        }
    }

    // query:[a, b)
    Monoid query(int a, int b) {
        Monoid L = id; Monoid R = id; a += N; b += N;
        for (; a < b; a >>= 1, b >>= 1) {
            if (a & 1) L = func(L, segment[a++]);
            if (b & 1) R = func(segment[--b], R);
        }
        return func(L, R);
    }
    // 0-based numbering;
    Monoid operator[](const int k) const {
        return segment[N+k];
    }
};

int main() {
    int n, m; cin >> n >> m;
    vector<pair<pair<int, int>, long long>> e;
    for (int i = 0; i < m; i++) {
        int a, b; long long c; cin >> a >> b >> c;
        e.push_back({{b, a}, c});
    }
    sort(e.begin(), e.end());
    SegmentTree<long long> dp(n+1, [](long long a, long long b){return min(a, b);}, (long long) 1e16);
    dp.update(0, 0);
    for (int i = 0; i < m; i++) {
        auto a = e[i].first.second;
        auto b = e[i].first.first;
        auto c = e[i].second;
        auto d = dp.query(a-1, b-1);
        dp.update(b-1, min(d+c, dp[b-1]));
    }
    if (dp[n-1] == 1e16) cout << -1 << endl;
    else cout << dp[n-1] << endl;
    return 0;
}

