class Edge {
	unsigned long long to;
	unsigned long long cost;
public:
	Edge() :to(ULLONG_MAX), cost(ULLONG_MAX) {}
	Edge(unsigned long long t, unsigned long long c) {
		to = t;
		cost = c;
	}
	unsigned long long To() { return to; }
	unsigned long long Cost() { return cost; }
};

class Node {
	unsigned long long node_no;
	unsigned long long min_cost;
	bool done;
	vector<Edge> to_cost;
public:
	Node() :node_no(ULLONG_MAX), min_cost(ULLONG_MAX), done(false) {}
	void push_edge(unsigned long long t, unsigned long long c) {
		to_cost.push_back(Edge(t, c));
	}

	void set_no(unsigned long long n) { node_no = n; }
	unsigned long long get_no() { return node_no; }

	void set_cost(unsigned long long c) { min_cost = c; }
	unsigned long long Min_cost() { return min_cost; }

	void set_done() { done = true; }
	bool is_Done() { return done; }

	vector<Edge>::size_type count_Edge() { return to_cost.size(); }
	Edge Return_Edge(vector<Edge>::size_type i) {
		return to_cost[i];
	}

	//昇順に並べたいので　<　に　>　を返す
	friend bool operator<(const Node& a, const Node& b) {
		return a.min_cost > b.min_cost;
	}
};

