vector<int> dijkstra(int n,int start,vector<vector<pair<int, int>>> &edge){
    vector<int> shortest(n,iinf);
    priority_queue<pair <int, int> > que;
    shortest[start] = 0LL;
    que.push(make_pair(0,start));
    while (!que.empty()){
        pair<int,int> now = que.top();
        que.pop();
        int v = now.second;
        if (shortest[v] < now.first){
            continue;
        }else{
            for (int i = 0; i < edge[v].size(); ++i){
                int to = edge[v][i].first;
                int cost = edge[v][i].second;
                int new_cost = shortest[v]+cost;
                if (new_cost < shortest[to]){
                    shortest[to] = new_cost;
                    que.push(make_pair(new_cost,to));
                }
            }
        }
    }
    return shortest;
}



