void register_id(int l,int r,bool flag){
  if(l+1==r){
    if(flag)mu[mp(l,r)]=l;
    else md[mp(l,r)]=l; 
    return;
  }
  if(flag)mu[mp(l,r)]=A++;
  else md[mp(l,r)]=A++;
  int mid = (l+r)/2;
  register_id(l,mid,flag);
  register_id(mid,r,flag);
  return;
}

int construct(int l,int r,bool flag){
  if(l+1==r){
    if(flag)return mu[mp(l,r)];
    else return md[mp(l,r)];
  }
  int mid = (l+r)/2;
  int self;
  if(flag)self = mu[mp(l,r)];
  else self = md[mp(l,r)];
  int to1 = construct(l,mid,flag);
  int to2 = construct(mid,r,flag);
  if(flag){
    add_edge(self,to1,0ll);
    add_edge(self,to2,0ll);
  }else{
    add_edge(to1,self,0ll);
    add_edge(to2,self,0ll);
  }
  return self;
}

void range_to_vec(int a,int b,int l,int r,bool flag,vector<int>& v){
  if(r<=a||b<=l)return;
  if(a<=l&&r<=b){
    if(flag)v.pb(mu[mp(l,r)]);
    else v.pb(md[mp(l,r)]);
  }else{
    int mid = (l+r)/2;
    range_to_vec(a,b,l,mid,flag,v);
    range_to_vec(a,b,mid,r,flag,v);
  }
}

