using index_t = std::size_t;

template<class T>using p_queue = std::priority_queue<T, std::vector<T>, std::greater<>>;
template<class T>std::vector<boost::optional<T>> dijkstra(std::vector<std::map<index_t, T>>const& edge, index_t start)
{
	p_queue<std::pair<T, index_t>> queue;
	queue.emplace(T(), start);
	std::vector<boost::optional<T>> ret(edge.size());
	while (queue.size())
	{
		T value;
		index_t index;
		std::tie(value, index) = queue.top();
		queue.pop();
		if (ret[index])
		{
			continue;
		}
		ret[index] = value;
		for (auto&& p : edge[index])
		{
			queue.emplace(value + p.second, p.first);
		}
	}
	return ret;
}

void Main()
{
	int N, M;
	std::cin >> N >> M;
	std::vector<std::map<index_t, std::int64_t>> edge(N);
	for (auto i : boost::irange(1, N))
	{
		edge[i][i - 1] = 0;
	}
	for (auto _ : boost::irange(0, M))
	{
		index_t L, R;
		std::int64_t C;
		std::cin >> L >> R >> C;
		--L;
		--R;
		edge[L][R] = C;
	}
	auto result = dijkstra(edge, 0);
	std::cout << result.back().get_value_or(-1) << std::endl;
}

