    while (!pq.empty()) {
        const auto cur = pq.top();
        pq.pop();
        if (dist[cur.second] < cur.first) continue;

        const auto &cur_edges = edges[cur.second];
        auto nxt = edges.upper_bound(cur.second);
        auto itr = begin(cur_edges);
        while (nxt != end(edges) && itr != end(cur_edges)) {
            while (itr != end(cur_edges) && itr->second <= nxt->first) {
                itr++;
            }
            if (itr == end(cur_edges)) break;

            const auto nxt_cost = cur.first + itr->first;
            if (nxt_cost < dist[nxt->first]) {
                dist[nxt->first] = nxt_cost;
                pq.emplace(nxt_cost, nxt->first);
            }

            nxt++;
        }
    }

