class SegTree{
    public:
        ll n;
        ll g;
        std::vector<ll> data;

        SegTree(std::vector<ll> a, ll _g){
            g = _g;
            for (n = 1; n < (ll) a.size(); n *= 2);
            data.resize(n * 2, g);
        }

        ll rec(ll l, ll r, ll node, ll node_l, ll node_r, ll val) {
            if (node_r <= l || node_l >= r) return g;
            if (node_l >= l && node_r <= r) return data[node] = min(data[node], val);
            ll mid = (node_l + node_r) / 2;
            return Calcu(
                rec(l, r, node * 2, node_l, mid, val),
                rec(l, r, node * 2 + 1, mid, node_r,val));
        }

        void query(ll l,ll r, ll val){
            rec(l,r,1,0,n,val);
        }

        ll get(ll index){
            ll res = data[index += n];
            for(;index /= 2;)
                res = min(res, data[index]);
            return res;
        }
};
