constexpr int s = 1 << 17;
ll stree[s*2], lazy[s*2];
void init() {
	for (int i = 0; i < 2 * s; i++)
		stree[i] = lazy[i] = 1e18;
}
void forward(int x) {
	stree[x * 2 + 1] = min(stree[x * 2 + 1], lazy[x]);
	stree[x * 2 + 2] = min(stree[x * 2 + 2], lazy[x]);
	lazy[x * 2 + 1] = min(lazy[x * 2 + 1], lazy[x]);
	lazy[x * 2 + 2] = min(lazy[x * 2 + 2], lazy[x]);
	lazy[x] = 1e18;
	stree[x] = min(stree[x * 2 + 1], stree[x * 2 + 2]);
}
ll rmin(int l, int r, int low = 0, int upp = s, int x = 0) {
	if (r <= low || upp <= l)
		return 1e18;
	if (l <= low && upp <= r)
		return min(stree[x], lazy[x]);
	forward(x);
	int cen = (low + upp) / 2;
	ll lv = rmin(l, r, low, cen, x * 2 + 1);
	ll rv = rmin(l, r, cen, upp, x * 2 + 2);
	return min(lv, rv);
}
void upd8(int l, int r, ll val, int low = 0, int upp = s, int x = 0) {
	if (r <= low || upp <= l)
		return;
	if (l <= low && upp <= r) {
		lazy[x] = min(lazy[x], val);
		stree[x] = min(stree[x], lazy[x]);
		return;
	}
	int cen = (low + upp) / 2;
	upd8(l, r, val, low, cen, x * 2 + 1);
	upd8(l, r, val, cen, upp, x * 2 + 2);
	stree[x] = min(stree[x * 2 + 1], stree[x * 2 + 2]);
}

