void dijkstra(graph &g, int source, T *dist) {
	typedef pair<T,int> node;
	int n = g.size();
	priority_queue<node, vector<node>, greater<node>> q;
	for (int i=0; i<n; i++)
		dist[i] = MAXT;
	dist[source] = 0;
	q.push({0, source});
	while (!q.empty()) {
		node x = q.top();
		q.pop();
		T d = x.first;
		int u = x.second;
		if (d > dist[u])
			continue;
		for (auto &y: g[u]) {
			int v = y.first;
			T w = y.second + d;
			if (w < dist[v]) {
				dist[v] = w;
				q.push({w, v});
			}
		}
	}
}

