void build(int v, int tl, int tr) {
	up[v] = add_vertex();
	down[v] = add_vertex();

	if(tl == tr) {
		add_edge(up[v], down[v], 0);
		add_edge(down[v], up[v], 0);
	} else {
		int tm = (tl + tr) / 2;
		build(2 * v + 1, tl, tm);
		build(2 * v + 2, tm + 1, tr);

		add_edge(down[v], down[2 * v + 1], 0);
		add_edge(down[v], down[2 * v + 2], 0);

		add_edge(up[2 * v + 1], up[v], 0);
		add_edge(up[2 * v + 2], up[v], 0);
	}
}

void add(int v, int tl, int tr, int l, int r, int node, int cost) {
	DBG(v); DBG(l); DBG(r);

	if(tl == l && tr == r) {
		add_edge(up[v], node, cost);
		add_edge(node, down[v], 0);
	} else {
		int tm = (tl + tr) / 2;

		if(r <= tm) {
			add(2 * v + 1, tl, tm, l, r, node, cost);
		} else if(l >= tm + 1) {
			add(2 * v + 2, tm + 1, tr, l, r, node, cost);
		} else {
			add(2 * v + 1, tl, tm, l, tm, node, cost);
			add(2 * v + 2, tm + 1, tr, tm + 1, r, node, cost);
		}
	}
}

int get_leaf(int v, int tl, int tr, int pos) {
	if(tl == tr) {
		return v;
	} else {
		int tm = (tl + tr) / 2;

		if(pos <= tm) {
			return get_leaf(2 * v + 1, tl, tm, pos);
		} else {
			return get_leaf(2 * v + 2, tm + 1, tr, pos);
		}
	}
}

