	const int src = up[get_leaf(0, 0, n - 1, 0)];
	const int dst = up[get_leaf(0, 0, n - 1, n - 1)];

	for(int i = 0; i < V; ++i) {
		dist[i] = LL_INF;
	}

	dist[src] = 0;

	for(int i = 0; i < V; ++i) {
		setik.emplace(dist[i], i);
	}

	while(!setik.empty()) {
		auto fst = setik.begin();
		int v = fst->second;
		setik.erase(fst);

		for(auto& ed: g[v]) {
			int u = ed.first;

			if(dist[u] > dist[v] + ed.second) {
				setik.erase(make_pair(dist[u], u));
				dist[u] = dist[v] + ed.second;
				setik.emplace(dist[u], u);
			}
		}
	}

#ifdef __LOCAL
	for(int i = 0; i < V; ++i) {
		cout << '@' << i << ' ' << dist[i] << '\n';
	}
#endif

	cout << (dist[dst] == LL_INF ? -1 : dist[dst]) << '\n';
}

