struct SegmentTree{
    ll ide = LINF;

    int n;
    vector<ll> node;

    SegmentTree(int sz){
        n = 1;
        while(n < sz) n <<= 1;
        node.resize(2 * n - 1, ide);
        // for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        // for(int i=n-2; i>=0; i--) node[i] = node[i*2+1] + node[i*2+2];
    }

    ll get(int k){
        ll ans = ide;
        k += n - 1;
        ans = min(ans, node[k]);
        while(k){
            k = (k - 1) / 2;
            ans = min(ans, node[k]);
        }
      return ans;
    }

    void update(int a, int b, ll x, int k = 0, int l = 0, int r = -1){
        if(r < 0)r = n;
        if(r <= a || b <= l) return;
        if(a <= l && r <= b){
            node[k] = min(node[k], x);
            return;
        }
        update(a, b, x, 2 * k + 1, l, (l + r) / 2);
        update(a, b, x, 2 * k + 2, (l + r) / 2, r);
    }
};

