struct Info {
    int L, R, C;

    Info(int L, int R, int C) : L(L), R(R), C(C) {}

    bool operator< (const Info &a) const {
        if (L == a.L && R == a.R) return C < a.C;
        if (L == a.L) return R < a.R;
        return L < a.L;
    }
};

