void build(int l,int r,int k)
{
	tree[k].l=l;
	tree[k].r=r;
	tree[k].data=1e18;
	tree[k].lz=0;
	if(l==r) return ;
	int mid=(l+r)>>1;
	build(l,mid,2*k);
	build(mid+1,r,2*k+1);
}
void pushdown(int k)
{
	if(tree[k].lz==0) return ;
	if(tree[2*k].lz==0) tree[2*k].lz=tree[k].lz;
	else tree[2*k].lz=min(tree[2*k].lz,tree[k].lz);
	if(tree[2*k+1].lz==0) tree[2*k+1].lz=tree[k].lz;
	else tree[2*k+1].lz=min(tree[2*k+1].lz,tree[k].lz);
	tree[2*k].data=min(tree[2*k].data,tree[k].lz);
	tree[2*k+1].data=min(tree[2*k+1].data,tree[k].lz);
	tree[k].lz=0;
}
void change(int l,int r,int k,ll x)
{
	if(tree[k].l>=l&&tree[k].r<=r)
	{
		if(tree[k].lz==0) tree[k].lz=x;
		else tree[k].lz=min(tree[k].lz,x);
		tree[k].data=min(tree[k].data,x);
		return ;
	}
	pushdown(k);
	int mid=(tree[k].l+tree[k].r)>>1;
	if(mid>=l) change(l,r,2*k,x);
	if(mid<r) change(l,r,2*k+1,x);
	tree[k].data=min(tree[2*k].data,tree[2*k+1].data);
}
ll query(int l,int r,int k)
{
	ll ans=1e18;
	if(tree[k].l>=l&&tree[k].r<=r)return tree[k].data;
	pushdown(k);
	int mid=(tree[k].l+tree[k].r)>>1;
	if(mid>=l) ans=min(ans,query(l,r,2*k));
	if(mid<r) ans=min(ans,query(l,r,2*k+1));
	return ans;
}
