template<class T> void chmin(T& x, T y){if(x > y) x = y;}
template<class T> void chmax(T& x, T y){if(x < y) x = y;}

template<class T>
struct BIT{
    int N;
    vector<T> bit;
    T init;

    BIT(int n = 0, T init = linf) : N(n), bit(n + 1, init), init(init) {}

    T val(int i){
        T mini = init;
        while(i <= N){
            chmin(mini, bit[i]);
            i += i & -i;
        }
        return mini;
    }

    void update(int r, T x){
        while(r > 0){
            chmin(bit[r], x);
            r -= r & -r;
        }
    }

    void output(){
        cout << (bit[N] == init ? -1 : bit[N]) << endl;
    }
};

struct range{
    int L, R;
    ll C;
    range() {}
    range(int L, int  R, ll C) : L(L), R(R), C(C) {}

    bool operator < (const range r) const {
        return L < r.L;
    }
    bool operator > (const range r) const {
        return L > r.L;
    }
};

int N, M;
vector<range> rs;
int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> N >> M;
    BIT<ll> bit(N, linf);
    for(int i = 0; i < M; i++){
        int L, R;
        ll C;
        cin >> L >> R >> C;
        rs.push_back({L, R, C});
    }
    sort(rs.begin(), rs.end());
    bit.bit[1] = 0;
    for(int i = 0; i < M; i++){
        range r = rs[i];
        ll val = bit.val(r.L);
        bit.update(r.R, val + r.C);
    }
    bit.output();
    return 0;
}

