const int MAX_N = 1 << 17;
// セグメント木を持つグローバル配列 
int n, dat[2 * MAX_N - 1];
// 初期化
void init(int n_) {
	// 簡単のため、要素数を2のべき乗に 
	n = 1;
	while (n < n_) n *= 2;
	// すべての値をINT_MAX/2に
	for (int i = 0; i < 2 * n - 1; i++) dat[i] = INT_MAX/2; 
}
// k番目の値(0-indexed)をaに変更
void update(int k, int a) {
	// 葉の節点
	k += n - 1; 
	dat[k] = a; 
	// 登りながら更新
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}

int query(int a, int b, int k, int l, int r) {
	// [a, b)と[l, r)が交差しなければ、INT_MAX/2 
	if (r <= a || b <= l) return INT_MAX/2;
	// [a, b)が[l, r)を完全に含んでいれば、この節点の値 
	if (a <= l && r <= b) return dat[k]; 
	else {
		// そうでなければ、2つの子の最小値
		int vl = query(a, b, k * 2 + 1, l, (l + r) / 2); 
		int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vl, vr);
	} 
}



