void dijkstra() {
	for (int i = 1; i <= n; ++i) dis[i] = inf, vis[i] = 0;
	q.push(mp(0, 1)); dis[1] = 0; 
	while (q.size()) {
		int u = q.top().sc; q.pop();
		if (vis[u]) continue; vis[u] = 1;
		for (int i = head[u]; i; i = e[i].nxt) {
