	int pos1=tot+1,pos2=tot+2;
	tot+=2;
	addin(1,n,ra,l1,r1,pos1,0);
	add_edge(pos1,pos2,w);
	addout(1,n,rb,pos2,l2,r2,0);
	return;
}
void dijkstra (int x) {
	q.push(make_pair(0,x));
	dis[x]=0;
	while (!q.empty()) {
		pair<ll,int> a=q.top();
		q.pop();
		if (vis[a.second]) {continue;}
		vis[a.second]=1;
		for (int i=hd[a.second];i;i=nx[i]) {
			if (dis[ver[i]]>dis[a.second]+edge[i]) {
				dis[ver[i]]=dis[a.second]+edge[i];
				q.push(make_pair(a.first-edge[i],ver[i]));
			}
		}
	}
	return;
}
