    }

    vector<int> o(m);
    iota(o.begin(), o.end(), 0);
    sort(o.begin(), o.end(), [&](int i, int j) {
        return r[i] < r[j];
    });

    SegmentTree<RMQ<>> tree(n);
    tree.modify(0, 0);

    REP(i, m) {
        ll m = tree.query(l[o[i]], r[o[i]]);
        if (m == RMQ<>::identify()) continue;

        ll now = tree.get(r[o[i]]);
        tree.modify(r[o[i]], min(now, m + c[o[i]]));
    }

    if (tree.get(n-1) != RMQ<>::identify()) {
