/* SegTreeLazy<X,M>(n,fx,fa,fm,ex,em): モノイド(集合X, 二項演算fx,fa,fm, 単位元ex,em)についてサイズnで構築
    set(int i,X x), build(): i番目の要素をxにセット。まとめてセグ木を構築する。O(n)
    update(a,b,x): [a,b) 全ての要素を x に更新。O(log(n))
    query(a,b): [a,b) 全てにfxを作用させた値を取得。O(log(n))
*/
template <typename X, typename M,typename T>
struct SegTreeLazy{
  using FX=function<X(X, X)>;
  using FA=function<X(X, M)>;
  using FM=function<M(M, M)>;
  int n;
  FX fx;
  FA fa;
  FM fm;
  const X ex;
  const M em;
  vector<X> dat;
  vector<M> lazy;
  SegTreeLazy(int n_,FX fx_,FA fa_,FM fm_,X ex_,M em_)
    : n(),fx(fx_),fa(fa_),fm(fm_),ex(ex_),em(em_),dat(n_*4,ex),lazy(n_*4,em){
    int x=1;
    while(n_>x) x*=2;
    n=x;
  }

  void set(int i,X x) {dat[i+n-1]=x;}
  void build(){
    for(int k=n-2;k>=0;k--) dat[k]=fx(dat[2*k+1],dat[2*k+2]);
  }

  /* lazy eval */
  void eval(int k){
      if (lazy[k]==em) return;  // 更新するものが無ければ終了
      if (k < n - 1){           // 葉でなければ子に伝搬
        lazy[k*2+1]=fm(lazy[k*2+1],lazy[k]);
        lazy[k*2+2]=fm(lazy[k*2+2],lazy[k]);
      }
      // 自身を更新
      dat[k]=fa(dat[k],lazy[k]);
      lazy[k]=em;
  }

  void update(int a,int b,M x,int k,int l,int r){
    eval(k);
    if(a<=l&&r<=b){  // 完全に内側の時
      lazy[k]=fm(lazy[k],x);
      eval(k);
    }
    else if(a<r&&l<b){                     // 一部区間が被る時
      update(a,b,x,k*2+1,l,(l+r)/2);  // 左の子
      update(a,b,x,k*2+2,(l+r)/2,r);  // 右の子
      dat[k]=fx(dat[k*2+1],dat[k*2+2]);
    }
  }
  void update(int a,int b,M x) {update(a,b,x,0,0,n);}

  X query_sub(int a,int b,int k,int l,int r){
    eval(k);
    if(r<=a||b<=l){  // 完全に外側の時
      return ex;
    }
    else if(a<=l&&r<=b){  // 完全に内側の時
      return dat[k];
    }
    else{  // 一部区間が被る時
      X vl=query_sub(a,b,k*2+1,l,(l+r)/2);
      X vr=query_sub(a,b,k*2+2,(l+r)/2,r);
      return fx(vl,vr);
    }
  }
  X query(int a,int b) {return query_sub(a,b,0,0,n);}

  //O(log(n)+α??)
  X find_rightest(int a,int b,T x) {return find_rightest_sub(a,b,x,0,0,n);}  //[a,b)で x 以下の要素を持つ最右位置
  X find_leftest(int a,int b,T x) {return find_leftest_sub(a,b,x,0,0,n);}  //[a,b)で x 以下の要素を持つ最左位置
  X find_rightest_sub(int a,int b,T x,int k,int l,int r){
    eval(k);
    if(dat[k] > x ||r<=a||b<=l){  // 自分の値がxより大きい or [a,b)が[l,r)の範囲外ならreturn a-1
      return a-1;
    }
    else if (k>=n-1){  // 自分が葉ならその位置をreturn
      return (k-(n-1));
    }
    else{
      X vr = find_rightest_sub(a,b,x,2*k+2,(l+r)/2,r);
      if (vr!=a-1){  // 右の部分木を見て a-1 以外ならreturn
          return vr;
      } else{  // 左の部分木を見て値をreturn
          return find_rightest_sub(a,b,x,2*k+1,l,(l+r)/2);
      }
    }
  }
  X find_leftest_sub(int a,int b,T x,int k,int l,int r){
    eval(k);
    if(dat[k] > x ||r<=a||b<=l){  // 自分の値がxより大きい or [a,b)が[l,r)の範囲外ならreturn b
      return b;
    }
    else if(k>=n-1){  // 自分が葉ならその位置をreturn
      return (k-(n-1));
    }
    else{
      X vl=find_leftest_sub(a,b,x,2*k+1,l,(l+r)/2);
      if(vl!=b){  // 左の部分木を見て b 以外ならreturn
        return vl;
      }
      else{  // 右の部分木を見て値をreturn
        return find_leftest_sub(a,b,x,2*k+2,(l+r)/2,r);
      }
    }
  }
};

int main(){
  int n,m; cin >> n >> m;
  using X=ll;
  using M=ll;
  auto fx=[](X x1,X x2) -> X {return min(x1,x2);};
  auto fa=[](X x,M m) -> X {return min(x,m);};
  auto fm=[](M m1,M m2) -> M {return min(m1,m2);};
  ll ex=numeric_limits<ll>::max();
  ll em=numeric_limits<ll>::max();
  SegTreeLazy<X,M,ll> rmq(n,fx,fa,fm,ex,em);

  rmq.update(0,1,0);
  vector<tiii> inputt(m);
  rep(i,m){
    ll l,r,c;
    cin >> l >> r >> c;
    l--; r--;
    inputt[i]=tiii(l,r,c);
  }
  sortt(inputt);
  rep(i,m){
    ll l,r,c;
    tie(l,r,c)=inputt[i];
    ll mn=rmq.query(l,r+1);
    if(mn==llmax) continue;
    rmq.update(l,r+1,mn+c);
  }
  ll ans=rmq.query(n-1,n);
  if(ans!=llmax) cout << rmq.query(n-1,n) << endl;
  else cout << -1 << endl;
}

