void buildtree ( tree *id , long long l , long long r , long long f ) {
	id -> l = l; id -> r = r; id -> nd = ++index;
	if ( l == r ) {
		if ( f == 1 ) add ( id -> nd , l , 0 );
		else add ( l , id -> nd , 0 );
		return ;
	}
	long long mid = (l+r)/2;
	id -> ll = &poolt[++topt];
	id -> rr = &poolt[++topt];
	buildtree ( id -> ll , l , mid , f );
	buildtree ( id -> rr , mid + 1 , r , f );
	if ( f == 1 ) {
		add ( id -> nd , id -> ll -> nd , 0 );
		add ( id -> nd , id -> rr -> nd , 0 );
	}
	else {
		add ( id -> ll -> nd , id -> nd , 0 );
		add ( id -> rr -> nd , id -> nd , 0 );
	}
}
void change ( tree *id1 , tree *id2 , long long l , long long r , long long c , long long num ) {
	if ( id1 -> l == l && id1 -> r == r ) {
		add ( num , id1 -> nd , c );
		add ( id2 -> nd , num , 0 );
		return ;
	}
	long long mid = (id1->l+id1->r)/2;
	if ( r <= mid ) change ( id1 -> ll , id2 -> ll , l , r , c , num );
	else {
		if ( l > mid ) change ( id1 -> rr , id2 -> rr , l , r , c , num );
		else {
			change ( id1 -> ll , id2 -> ll , l , mid , c , num );
			change ( id1 -> rr , id2 -> rr , mid + 1 , r , c , num );
		}
	}
