	seg[k*2+1]=min(seg[k*2+1],seg[k]);
	seg[k*2+2]=min(seg[k*2+2],seg[k]);
	seg[k]=INF;
}

void segchange(ll l,ll r,ll x,ll k,ll a,ll b){
	if(r<=a||b<=l){
		return;
	}
	lazpro(k,a,b);
	if(l<=a&&b<=r){
		seg[k]=min(seg[k],x);
	}else{
		ll m=(a+b)>>1;
		segchange(l,r,x,k*2+1,a,m);
		segchange(l,r,x,k*2+2,m,b);
	}
}
