    int R = P[i].second.first - 1;
    long long int C = P[i].second.second;
    update(R, min(value[R + N - 1],query(L, R , 0, 0, N) + C));
  }
  if(value[n + N - 2]  == INF)
           value[n + N - 2]  = -1;
  cout << value[n + N - 2] << endl;
}

