class SegTreeRMQ{
public:
    SegTreeRMQ(int N){
        init(N);
    }
    void init(int N){
        int s = 1;
        while(s < N){
            s*=2;
        }
        dat = std::vector<ll>(s * 2, 1e18);
        n = s;
    }
    void update(int i,ll x){
        i += n - 1;
        dat[i]= x;
        while(i > 0){
            i = (i-1) / 2;
            dat[i] = min(dat[i * 2 + 1],dat[i * 2 + 2]);
        }
    }
    //使う時は変数名.query(a,b,k,l,変数名getSize())
    //区間の左端(b)に注意+1しよう
    ll query(int a,int b,int k,int l,int r){
      //  cout<<k<<endl;
        if(r <= a || b<= l)return 1e18;
        if(a <= l && r <= b)return dat[k];
        else{
            ll vl = query(a,b,k * 2 + 1,l,(l+r)/2);
            ll vr = query(a,b,k * 2 + 2,(l+r)/2,r);
            return min(vl,vr);
        }
    }
    int getSize(){
        return n;
    }
    void show(){
        for(int a = 0;a < n;a++){
            cout<<dat[a]<<" ";
        }
        cout<<endl;
        return;
    }
private:
    int n;
    std::vector<ll> dat;
};


