void Dijkstra(int s)
{
	memset(dis,0x3f,sizeof(dis));
	memset(vis,0,sizeof(vis));
	dis[s] = 0;
	priority_queue <pli,vector<pli>,greater<pli>> q;
	q.push(mp(0,s));
	while(!q.empty())
	{
		int u = q.top().second; 
		q.pop();
		if(vis[u]) continue;
		vis[u] = 1;
		for(int i=head[u];i;i=e[i].next)
		{
			int v = e[i].to;
			if(dis[v]>dis[u]+e[i].w)
			{
				dis[v] = dis[u] + e[i].w;
				q.push(mp(dis[v],v));
			}
		}
	}
}
