int kai(int x, int y) {
	int res = 1;
	for (int i = x - y + 1; i <= x; i++) {
		res *= i; res %= mod;
	}
	return res;
}
int mod_pow(int x, int y, int m) {
	int res = 1;
	while (y > 0) {
		if (y & 1) {
			res = res * x % m;
		}
		x = x * x % m;
		y >>= 1;
	}
	return res;
}

int comb(int x, int y) {
	if (y > x)return 0;
	return kai(x, y) * mod_pow(kai(y, y), mod - 2, mod) % mod;
}

int s;
vector<int> dat, lazy;

void init(int n_) {
	s = 1;
	while (s < n_)s *= 2;
	dat.resize(2 * s - 1);
	dat[s - 1] = 0;
	for (int i = s; i < 2 * s - 1; i++)dat[i] = INF;
	for (int i = s - 2; i >= 0; i--)dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);
	lazy.resize(2 * s - 1, INF);
}

void eval(int k, int l, int r) {
	if (lazy[k] != INF) {
		dat[k] = min(dat[k], lazy[k]);
		if (r - l > 1) {
			lazy[2 * k + 1] = min(lazy[k], lazy[2 * k + 1]);
			lazy[2 * k + 2] = min(lazy[k], lazy[2 * k + 2]);
		}
		lazy[k] = INF;
	}
}

void add(int a, int b, int x, int k = 0, int l = 0, int r = -1) {
	if (r < 0)r = s;
	if (r <= a || b <= l)return;
	eval(k, l, r);
	if (a <= l && r <= b) {
		lazy[k] = min(lazy[k], x);
		eval(k, l, r);
	}
	else {
		add(a, b, x, 2 * k + 1, l, (l + r) / 2);
		add(a, b, x, 2 * k + 2, (l + r) / 2, r);
		dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
	}
}

int query(int k) {
	k += s - 2;
	eval(k, 0, 0);
	return dat[k];
}

int n, m;
