int solve() {
	init(n);
	for (int i = 1; i < n; i++) {
		int k = query(i);
		for (int j = 0; j < (int)vec[i].size(); j++) {
			add(i, vec[i][j].first, k + vec[i][j].second);
		}
	}
	int res = query(n);
	if (res == INF)return -1;
	else return res;
}

