    g[cn].pb( rc ) ; cost[cn].pb( 0 ) ;  g[rc+off].pb(cn+off) ; cost[rc+off].pb(0) ;
    build(lc,b,m) ;    build(rc,m+1,e) ;
}

void addEdge( int cn , int b, int e, int l , int r, int c, int from )
{
    if( e<l || b>r ) return ;
    if( l<=b && e<=r )
