ll pow(ll x, ll y)
{
	if (y == 0) return 1;
	if (y % 2)
	{
		return pow(x, y - 1) * x % mod;
	}
	else
	{
		ll yyy = pow(x, y / 2);
		return yyy * yyy % mod;
	}
}

ll div(ll x)
{
	return pow(x, mod - 2);
}

void init(ll n_)
{
	n = 1;
	while (n < n_)
	{
		n *= 2;
	}

	for (int i = 0; i < 2 * n - 1; i++)
	{
		dat[i] = INF;
	}
}

void update(ll k, ll a)
{
	k += n - 1;
	dat[k] = a;
	while (k > 0)
	{
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}

ll query(ll a, ll b, ll k, ll l, ll r)
{
	if (r <= a || b <= l)
	{
		return INF;
	}

	if (a <= l && r <= b)
	{
		return dat[k];
	}
	else
	{
		ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vl, vr);
	}
}

