template<class Data, int N>
struct SegTree {
  typedef typename Data::T T;
  typedef Data D;
  int m;
  Data dat[N*4];
  void init(int n) { for (m=1; m<n; m*=2); REP(i,2*m-1) dat[i] = Data(); }
  void setleaf(int idx, const Data &d) { dat[m-1+idx] = d; }
  void finishset() { for (int i=m-2; i>=0; --i) dat[i] = Data(dat[i*2+1],dat[i*2+2]); }
  void init(T *v, int n) { init(n); REP(i,n) setleaf(i,v[i]); finishset(); }
  void change(int k, const Data &d) {
    k += m-1;
    dat[k] = d;
    while(k) {
      k = (k-1)>>1;
      dat[k] = Data(dat[(k<<1)+1],dat[(k<<1)+2]);
    }
  }
  Data query(int a, int b) { return q(a, b, 0, 0, m); }
  Data q(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return Data();
    if (a <= l && r <= b) return dat[k];
    const Data &ld = q(a, b, k*2+1, l, (l+r)/2);
    const Data &rd = q(a, b, k*2+2, (l+r)/2, r);
    return Data(ld,rd);
  }
};

