using ll = long long;
using tiii = tuple<int, int, ll>;
struct lazy_range_query_behavior {
	using value_type    = ll;
	using modifier_type = ll;
	value_type identity_value() const { return std::numeric_limits<ll>::max(); }
	modifier_type identity_modifier() const { return std::numeric_limits<ll>::max(); }
	std::pair<modifier_type, modifier_type>
	split_modifier(const modifier_type& m, size_t) const {
		return std::make_pair(m, m);
	}
	modifier_type merge_modifier(const modifier_type& a, const modifier_type& b) const {
		return std::min(a, b);
	}
	value_type merge_value(const value_type& a, const value_type& b) const {
		return std::min(a, b);
	}
	value_type modify(size_t, const value_type& v, const modifier_type& m) const {
		return std::min(v, m);
	}
};
int main(){
	ios_base::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<tiii> queries(m);
	for(int i = 0; i < m; ++i){
		int l, r, c;
		cin >> l >> r >> c;
		queries[i] = tiii(l - 1, r, c);
	}
	sort(queries.begin(), queries.end());
	loquat::lazy_segment_tree<lazy_range_query_behavior> lst(n);
	lst.modify(0, 1, 0);
	for(const auto& t : queries){
		const int l = get<0>(t);
		const int r = get<1>(t);
		const ll c = get<2>(t);
		const ll v = lst.query(l, r);
		if(v < std::numeric_limits<ll>::max()){
			lst.modify(l, r, v + c);
		}
	}
	ll answer = lst.query(n - 1, n);
	if(answer == std::numeric_limits<ll>::max()){ answer = -1; }
	cout << answer << endl;
	return 0;
}

