        graph[X].push_back(Edge(Y, L));
    }
    Rep(i,1,N-1){
        graph[i+1].pb(Edge(i,0));
    }
    dis_dijkstra dis = dijkstra(N,graph,1LL,0LL);
    cout << (dis[N]==LINF ? -1 : dis[N]) << endl;
}

