    VVL l2r(n), l2c(n);
    REP(i,m){
        int l = in() - 1, r = in(), c = in();
        l2r[l].push_back(r);
        l2c[l].push_back(c);
    }

    SqrtDecomposition sd;
    sd.init(n);
    sd.update(0, 1, 0);

    REP(i,n-1){
        ll x = sd.query(i, i + 1);
        if (x == INF){
            cout << -1 << endl;
            return 0;
        }
        REP(j,l2r[i].size()){
            int r = l2r[i][j];
            ll c = l2c[i][j];
            sd.update(i + 1, r, x + c);
        }
    }
