        Query[L].emplace_back(R, C);
    }
    for(int i = 1; i <= N; i++) {
        dp[i] = INF;
    }
    LazySegmentTree seg;
    for(int pos = 1; pos <= N; pos++) {
        dp[pos] = seg.find(pos, pos + 1);
        if(pos == 1) {
            dp[pos] = 0;
        }
        //cerr << pos << " " << dp[pos] << endl;
        if(dp[pos] == INF) {
            cout << -1 << endl;
            return 0;
        }
        for(auto now : Query[pos]) {
            seg.update(pos, now.first + 1, dp[pos] + now.second);
        }
    }
    cout << dp[N] << endl;
    return 0;
}

