        {
            return min(x,y);
        }
        i64 identity()
        {
            return inf;
        }
    };

    struct action
    {
        using value_type=i64;
        void operator()(i64 &x,i64 y)
        {
            x=min(x,y);
        }
        void act(i64 &x,i64 y)
        {
            x=min(x,y);
        }
        i64 identity()
        {
