		query.emplace(L, R, C);
	}
	p_queue<std::pair<std::int64_t, int>> queue;
	auto end = upper_bound(query, 1);
	for (auto ite = query.begin(); ite != end; ++ite)
	{
		queue.emplace(std::get<2>(*ite), std::get<1>(*ite));
	}
	query.erase(query.begin(), end);
	std::int64_t result = 0;
	int reach = 1;
	while (queue.size())
	{
		std::int64_t C;
		int R;
		std::tie(C, R) = queue.top();
