using namespace std;

typedef long long int ll;

const int MAXN = 1e5 + 5;

vector < ll > t(4 * MAXN), cst;

void build(int v, int tl, int tr){
  if(tl == tr){
    t[v] = cst[tl];
  }else{
    int tm = (tr - tl) / 2 + tl;
    build(2 * v, tl, tm);
    build(2 * v + 1, tm + 1, tr);
    t[v] = min(t[2 * v], t[2 * v + 1]);
  }
}

ll query(int v, int tl, int tr, int l, int r){
  if(r < l) return 1e17;
  if(tl == l && tr == r){
    return t[v];
  }else{
    int tm = (tr - tl) / 2 + tl;
    return min(query(2 * v, tl, tm, l, min(r, tm)), query(2 * v + 1, tm + 1, tr, max(tm + 1, l), r));
  }
}

void update(int v, int tl, int tr, int idx, ll val){
  if(tl == tr){
    t[v] = val;
  }else{
    int tm = (tr - tl) / 2 + tl;
    if(idx <= tm) update(2 * v, tl, tm, idx, val);
    else update(2 * v + 1, tm + 1, tr, idx, val);
    t[v] = min(t[2 * v], t[2 * v + 1]);
  }
}

