    ll rc = min(seg[id*2+2],(tg[id*2+2] == -1 ?INF:tg[id*2+2]));
    seg[id] = min(lc,rc);
}
void push(ll id){
    if (tg[id] == -1) return;
    seg[id] = min(seg[id],tg[id]);
    if (tg[id*2+1] == -1) tg[id*2+1] = tg[id];
    else tg[id*2+1] = min(tg[id*2+1],tg[id]);
    if (tg[id*2+2] == -1) tg[id*2+2] = tg[id];
    else tg[id*2+2] = min(tg[id*2+2],tg[id]);
    tg[id] = -1;
}
void build(ll id,ll L,ll R){
    tg[id] = -1;
    if (L == R-1) {
        seg[id] = INF;
        return;
    }
    ll mid = (L+R)>>1;
    build(id*2+1,L,mid);
    build(id*2+2,mid,R);
    pull(id);
}
void ins(ll id,ll L,ll R,ll l,ll r,ll v){
    // debug(id,L,R);
