        if (tg[id] == -1) tg[id] = v;
        else tg[id] = min(tg[id],v);
        // debug(id,tg[id]);
        return;
    }
    push(id);
    ll mid = (L+R)>>1;
    if (r <= mid) ins(id*2+1,L,mid,l,r,v);
    else if (l >= mid) ins(id*2+2,mid,R,l,r,v);
    else {
        ins(id*2+1,L,mid,l,mid,v);
        ins(id*2+2,mid,R,mid,r,v);
    }
    pull(id);
}
ll qr(ll id,ll L,ll R,ll l,ll r){
    // debug(id,L,R,seg[id],tg[id]);
    if (l == L && r == R) {
        return min(seg[id],(tg[id] == -1 ?INF:tg[id]));
    }
    push(id);
    ll mid = (L+R)>>1;
    if (r <= mid) return qr(id*2+1,L,mid,l,r);
    else if (l >= mid) return qr(id*2+2,mid,R,l,r);
    else {
        ll lc = qr(id*2+1,L,mid,l,mid);
        ll rc = qr(id*2+2,mid,R,mid,r);
        return min(lc,rc);
    }
}
