int main(){

  int N, M; cin >> N >> M;

  vector < pair< pair<int, int>, ll> > LRC(M);
  for (int i = 0; i < M; i++){
    int L, R; ll C; cin >> L >> R >> C;
    L--; R--;
    LRC[i].first = make_pair(L, R);
    LRC[i].second = C;
  }
  sort(LRC.begin(), LRC.end());

  vector <ll> ans(N); fill(ans.begin(), ans.end(), -1);
  vector <bool> visited(N);
  ans[0] = 0; visited[0] = true;
  int edge = 0;
  for (int i = 0; i < M; i++){
    int L = LRC[i].first.first, R = LRC[i].first.second;
    ll C = LRC[i].second;

    if (visited[L] == false){
      break;
    }else{
      ll compare = ans[L] + C;

      int l = L + 1, r = min(R, edge);
      if (ans[r] > compare){
        int now; bool flag = true;
        while (flag == true){
          now = (l + r) / 2;
          if (ans[now] > compare){
            r = now;
          }else{
            l = now;
          }
          if (now == (l + r) / 2){
            flag = false;
          }
        }

        for (int j = now; j <= min(R, edge); j++){
          ans[j] = compare;
        }
      }

      if (edge + 1 <= R){
        for (int j = edge + 1; j <= R; j++){
          ans[j] = compare;
          visited[j] = true;
        }
      }

      edge = max(edge, R);

    }
  }

