ll dijkstra(int start) {
  vector<ll> dist(n, INF);
  priority_queue<pair<ll, int>, vector<pair<ll, int> >, greater<pair<ll, int> > > q;
  dist[start] = 0;
  q.emplace(0, start);
  while (!q.empty()) {
    pair<ll, int> cur = q.top(); q.pop();
    ll d = cur.first;
    int v = cur.second;
    if (dist[v] < d) continue;
    for (int i = 0; i < G[v].size(); ++i) {
      P next = G[v][i];
      ll d2 = next.second + d;
      int u = next.first;
      if (d2 < dist[u]) {
	dist[u] = d2;
	q.emplace(d2, u);
      }
    }
  }
  return dist[n - 1];
}
