void update(int l, int r, long long x, int id = 1, int st = 0, int en = n) {
	if (r <= st || en <= l)
		return;
	if (l <= st && en <= r) {
		seg[id] = min(seg[id], x);
		return;
	}
	int mid = st + en >> 1;
	update(l, r, x, id << 1, st, mid);
	update(l, r, x, id << 1 | 1, mid, en);
}

long long get(int p, int id = 1, int st = 0, int en = n) {
	if (en - st == 1)
		return seg[id];
	int mid = st + en >> 1;
	return min(seg[id], p < mid? get(p, id << 1, st, mid): get(p, id << 1 | 1, mid, en));
}

