	for(int i=1;i<=n;i++) dis[i]=INF;
	priority_queue<node>q;
	while(!q.empty()) q.pop();
	dis[start]=0;
	q.push(node(start,0));
	node x;
	while(!q.empty()) {
		x=q.top();
		q.pop();
