constexpr const int maxn = 1 << 17;
vector<pii> adj[maxn << 2 ^ maxn];

#define mid  (begin + end >> 1)
#define lson (index << 1)
#define rson (lson ^ 1)
#define lll  begin, mid, lson
#define rrr  mid, end, rson
#define decl int begin, int end, int index

void build(decl) {
	if (begin + 1 == end) return;
	adj[lson].eb(index, 0);
	adj[rson].eb(index, 0);
	adj[maxn << 1 ^ index].eb(maxn << 1 ^ lson, 0);
	adj[maxn << 1 ^ index].eb(maxn << 1 ^ rson, 0);
	build(lll);
	build(rrr);
}

void link(decl, int l, int r, int c, int k) {
	if (begin >= r || end <= l) return;
	if (begin >= l && end <= r) {
		debug(begin, end, index, c);
		adj[index].eb(k, c);
		adj[k].eb(maxn << 1 ^ index, 0);
		return;
	}
	link(lll, l, r, c, k);
	link(rrr, l, r, c, k);
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int n, m;
	cin >> n >> m;
	rep(i, 0, n) {
		adj[maxn ^ i].eb(maxn << 1 ^ maxn ^ i, 0);
		adj[maxn << 1 ^ maxn ^ i].eb(maxn ^ i, 0);
	}
	build(0, maxn, 1);
	while (m--) {
		int l, r, c;
		cin >> l >> r >> c;
		link(0, maxn, 1, l - 1, r, c, maxn << 2 ^ m);
	}
	constexpr const i64 inf = 0x3f3f3f3f3f3f3f3fLL;
	vector<i64> dis(maxn << 2 ^ maxn, inf);
	vector<bool> vis(maxn << 2 ^ maxn);
	priority_queue<pair<i64, int>, vector<pair<i64, int>>, greater<pair<i64, int>>> heap;
	heap.emplace(0LL, maxn);
	dis[maxn] = 0;
	while (!heap.empty()) {
		auto top = heap.top();
		heap.pop();
		if (vis[top.ss]) continue;
		debug(top);
//		dis[top.ss] = top.ff;
		for (const auto& e : adj[top.ss]) if (top.ff + e.ss < dis[e.ff]) {
			debug(e);
			dis[e.ff] = top.ff + e.ss;
			heap.emplace(dis[e.ff], e.ff);
		}
	}
	i64 ans = dis[maxn << 1 ^ maxn ^ n - 1];
	if (ans == inf) ans = -1;
	cout << ans << endl;
}

