class RmqTree {
private:
	ll _find(ll a, ll b, ll k, ll l, ll r) {
		//区間[l,r)の最小値を持つk番目のノードを探索
		if (r <= a || b <= l)return INF;    // 交差しない
		if (a <= l && r <= b)return dat[k];   // 完全に含む
		else {
			ll s1 = _find(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子
			ll s2 = _find(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子
			return min(s1, s2);
		}
	}
public:
	ll n, height;
	vector<ll> dat;

	// 初期化（_nは最大要素数）
	RmqTree(ll _n) {
		n = 1;
		height = 1;
		while (n < _n) {
			n *= 2;
			height++;
		}
		dat = vector<ll>(2 * n - 1, INF);
	}

	// i番目の値(0-indexed)をxに変更
	void update(ll i, ll x) {
		i += n - 1; // i番目の葉ノードへ
		dat[i] = x;
		while (i > 0) { // 登りながら更新
			i = (i - 1) / 2;//親ノードのインデックス
			dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
			//子ノードの小さい方の値を代入
		}
	}

	// 区間[a,b)の最小値の取得
	ll find(ll a, ll b) {
		return _find(a, b, 0, 0, n);
	}
};
int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);

	ll n, m;
	cin >> n >> m;
	vector<pair<P, ll>> lrc(m);
	REP(i, m) {
		cin >> lrc[i].first.first >> lrc[i].first.second >> lrc[i].second;
	}
	sort(all(lrc));

	RmqTree rmq(n+10);
	rmq.update(1, 0);
	REP(i, m) {
		ll l = lrc[i].first.first;
		ll r = lrc[i].first.second;
		ll c = lrc[i].second;
		ll min = rmq.find(l, r);
		//cout <<l<<" "<<r<<" "<< min<<" " << c << endl;
		if (rmq.find(r,r+1)>min+c) {
			rmq.update(r, min + c);
		}
	}

	ll ans = rmq.find(n,n+1);
	if (ans == INF) {
		cout << -1 << endl;
	}
	else {
		cout << ans << endl;
	}


	return 0;
}

