template<typename M=int> struct dual {
    //区間に対して演算するときに
    //一つ一つに対して行いたい演算
    using H = function<M(M, M)>;
    int n, height;
    H h;
    M e;
    vector<M> laz;

    dual(int n_, M e, H h) : h(h), e(e) {        n = 1;        height = 0;        while (n < n_) n <<= 1, height++;        laz.assign(2 * n, e);    }
    dual(vector<M> &a, M e, H h) : h(h), e(e) {        n = 1;        height = 0;        int asz = sz(a);        while (n < asz) n <<= 1, height++;        laz.assign(2 * n, e);        rep(i, N) {            laz[i + n] = a[i];        }    }

     void propagate(int k) {        if (laz[k] == e) return;        laz[(k << 1) | 0] = h(laz[(k << 1) | 0], laz[k]);        laz[(k << 1) | 1] = h(laz[(k << 1) | 1], laz[k]);        laz[k] = e;    }
     void thrust(int k) {        for (int i = height; i; i--) propagate(k >> i);    }
    void update(int a, int b, M x) {        thrust(a += n);        thrust(b += n - 1);        for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {            if (l & 1) laz[l] = h(laz[l], x), l++;            if (r & 1) --r, laz[r] = h(laz[r], x);        }    }    M operator[](int a) {        thrust(a += n);        return laz[a];    }
#ifdef _DEBUG
    void debu() {        for (int i = 0; i < n; i++) {            cerr << operator[](i) << " ";        }        cout << "" << endl;    }
#else
    void debu(){};
#endif
    void update(int a, M x) {
        thrust(a += n);
        laz[a] = x;
    }
};
