	for (int i = 0; i < M; i++) {
		long long L, R, C;
		cin >> L >> R >> C;
		L--, R--;
		V[L].push_back({ R, C });
	}
	for (int i = 0; i < N - 1; i++) {
		V[i + 1].push_back({ i, 0 });
	}
	vector<long long> Dist = Dijkstra(V, 0);
	cout << (Dist[N - 1] == INF ? -1 : Dist[N - 1]) << endl;
}

