ll solve() {
  ll v = 0, d = 0, e = 0;
  priority_queue<P, vector<P>, greater<P>> que;
  while (v != N - 1) {
    for (; e < E.size() && get<0>(E[e]) <= v; ++e) {
      ll l, r, c;
      tie(l, r, c) = E[e];
      que.push(make_pair(d + c, r));
    }
    if (que.empty()) return -1;
    ll dx, r;
    tie(dx, r) = que.top();
    que.pop();
    d = dx;
    v = r;
  }
  return d;
}
