#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

constexpr ll INF = 1e15;

//1点更新,区間最小
class SegmentTree {
public:
    SegmentTree(ll n, ll value) {
        n_ = (ll)pow(2, ceil(log2(n)));
        nodes_.resize(2 * n_ - 1, value);
    }
    void update(ll x, ll v) {
        nodes_[x + n_ - 1] = min(nodes_[x + n_ - 1], v);
        for (ll i = (x + n_ - 2) / 2; ; i = (i - 1) / 2) {
            nodes_[i] = min(nodes_[2 * i + 1], nodes_[2 * i + 2]);
            if (i == 0) {
                break;
            }
        }
    }

    ll getMin(ll a, ll b, ll k = 0, ll l = 0, ll r = -1) {
        if (r < 0) {
            r = n_;
        }
        if (r <= a || b <= l) {
            return INF;
        }
        if (a <= l && r <= b) {
            return nodes_[k];
        }
        ll lv = getMin(a, b, 2 * k + 1, l, (l + r) / 2);
        ll rv = getMin(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(lv, rv);
    }

private:
    //2のべき乗
    ll n_;
