void add_edge(int a, int b, ll c, int idx, int k, int l, int r) {
	// debug(a, b, c, k, l, r);
	if(b <= l || r <= a) return;
	if(a <= l && r <= b) {
		G[k + 2 * n].pb(pi(idx, c));
		G[idx].pb(pi(k, 0));
	}
	else {
		add_edge(a, b, c, idx, k * 2 + 1, l, (l + r) / 2);
		add_edge(a, b, c, idx, k * 2 + 2, (l + r) / 2, r);
	}
}

ll d[MAX_N];

void dijkstra(int s) {
	//can be used as bfs.
	priority_queue<pl, vector<pl>, greater<pl> > que;
	fill(d, d + 4 * n + M, linf);
	d[s] = 0;
	que.push(pl(0, s));
	while(!que.empty()) {
		pl p = que.top(); que.pop();
		int v = p.second;
		if(d[v] < p.first) continue;
		for(int i = 0; i < sz(G[v]); i++) {
			pi e = G[v][i];
			if(d[e.fst] > d[v] + e.sec) {
				d[e.fst] = d[v] + e.sec;
				que.push(pl(d[e.fst], e.fst));
			}
		}
	}
}

void solve() {
	cin >> N >> M;
	n = 1;
	while(n < N) n *= 2;

	rep(i, 0, n - 1) {
		G[i].pb(pi(i * 2 + 1, 0));
		G[i].pb(pi(i * 2 + 2, 0));
		G[i * 2 + 1 + 2 * n].pb(pi(i + 2 * n, 0));
		G[i * 2 + 2 + 2 * n].pb(pi(i + 2 * n, 0));
	}
	for(int i = n - 1; i < 2 * n - 1; i++) {
		G[i].pb(pi(i + 2 * n, 0));
	}
	rep(i, 0, M) {
		int l, r, c; cin >> l >> r >> c; l--;
		add_edge(l, r, c, 4 * n + i, 0, 0, n);
	}
	dijkstra(n - 1);
	// rep(i, 0, 4 * n) {
	// 	debug(i, vector<pl>(all(G[i])), d[i]);
	// }
	if(d[n - 1 + N - 1] == linf) cout << -1 << "\n";
	else cout << d[n - 1 + N - 1] << "\n";
}

