struct union_find{
  vector<long long> data;//そのノードがrootであれば-（集合のサイズ）を表し、そうでなければ親ノードidを示す。
  vector<long long> diff_weight;
  union_find(long long size, long long abel_sum_unity = 0)
  :data(size,-1),diff_weight(size,abel_sum_unity){}//コンストラクタ,size個のノードを作成し、-1で初期化
  //根を探す,経路圧縮
  inline long long root(long long a){
    if(data[a]<0) return a;
    long long r = root(data[a]);
    diff_weight[a] += diff_weight[data[a]];
    return data[a] = r;
    // return data[a] < 0 ? a : data[a]=root(data[a]),diff_weight[a] += diff_weight[data[a]];
  }
  //a,bが同じ集合に属するか調べる
  inline bool same(long long a,long long b){
    return root(a) == root(b);
  }
  //小さい方の木の根に大きい方の根を上書きする
  inline bool unite(long long a,long long b, long long w=1){
    w += weight(a) - weight(b);
    a = root(a),b = root(b);
    if(a==b) return false;//根が同じなら終了,uniteが失敗したことを出力
    if(-data[a]<-data[b]) swap(a,b),w=-w; //-data[a]≥-data[b]となるようにswap
    //集合サイズの大きい方に小さい方をつける。
    data[a] += data[b];//集合サイズを統合
    data[b] = a;//bの親をaにする。
    diff_weight[b] = w;
    return true;//unite成功を出力
  }
  //aが属する集合のサイズを出力
  inline long long size(long long a){
    return -data[root(a)];
  }
  //root(a)からaまでの距離を返す。
  inline long long weight(long long a){
    root(a);
    return diff_weight[a];
  }
  inline long long diff(long long a,long long b){
    return weight(b) - weight(a);
  }
};
typedef int Weight;
struct Edge {  //src:辺の始点,dst:辺の終点,weight:辺の重さ
  int src, dst;
  Weight weight;
  Edge(int src, int dst, Weight weight) :
    src(src), dst(dst), weight(weight) { }
};
bool operator < (const Edge &e, const Edge &f) {
  return e.weight != f.weight ? e.weight > f.weight : //辺は重さが重いものを"小さい"と定義する
    e.src != f.src ? e.src < f.src : e.dst < f.dst;
}
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

//引数 g:隣接リスト,r:最小全域木の始点
//戻値 total:最小全域木の重み,T:最小全域木の辺集合
pair<Weight, Edges> prim(const Graph &g, int r = 0) {
  int n = g.size();
  Edges T;
  Weight total = 0;
  vector<bool> visited(n);
  priority_queue<Edge> Q;
  Q.push( Edge(-1, r, 0) );    //始め、-1とrを結ぶ辺があると考える
  while (!Q.empty()) {
    Edge e = Q.top(); Q.pop();
    if (visited[e.dst]) continue;
    T.push_back(e);
    total += e.weight;
    visited[e.dst] = true;
    for(auto f=g[e.dst].begin();f!=g[e.dst].end();++f) if(!visited[f->dst]) Q.push(*f);
  }
  return pair<Weight, Edges>(total, T);
}
