template < class T, class UT, class MERGE_VALUE_VALUE, class MERGE_VALUE_UPDATE, T NEUTRAL_VALUE >
struct binary_indexed_tree {
  vector < T > tree;
  int n;
  MERGE_VALUE_VALUE merge_values;
  MERGE_VALUE_UPDATE update_value;
  void build_tree(T *arr, int a, int b, int node) {
    if(a>b) return;
    if(a==b) {
      tree[node]=arr[a];
      return;
    }
    build_tree(arr,a,(a+b)>>1,node<<1);
    build_tree(arr,((a+b)>>1)+1,b,(node<<1)|1);
    tree[node]=merge_values(tree[node<<1],tree[(node<<1)|1]);
  }
  void update_tree(int a, int b, int pos, UT value, int node) {
    if(a>b || a>pos || b<pos) return;
    if(a==b) {
      tree[node]=update_value(tree[node],value);
      return;
    }
    update_tree(a,(a+b)>>1,pos,value,node<<1);
    update_tree(((a+b)>>1)+1,b,pos,value,(node<<1)|1);
    tree[node]=merge_values(tree[node<<1],tree[(node<<1)|1]);
  }
  T query_tree(int a, int b, int i, int j, int node) {
    if(a>b || a>j || b<i) return NEUTRAL_VALUE;
    if(a>=i && b<=j) return tree[node];
    return merge_values(query_tree(a,(a+b)>>1,i,j,node<<1),query_tree(((a+b)>>1)+1,b,i,j,(node<<1)|1));
  }
  void initialize(int k) {
    n=k;
    tree.assign(4*n+5,NEUTRAL_VALUE);
  }
  void initialize(T *arr, int k) {
    n=k;
    tree.assign(4*n+5,NEUTRAL_VALUE);
    build_tree(arr,1,n,1);
  }
  void update(int pos, UT value) {
    update_tree(1,n,pos,value,1);
  }
  T query(int l, int r) {
    return query_tree(1,n,l,r,1);
  }
};

struct edge {
  int l, r, w;
};

struct min_merge {
  long long operator()(const long long &a, const long long &b) const {
    return min(a, b);
  }
};

struct assign_merge {
  long long operator()(const long long &a, const long long &b) const {
    return b;
  }
};

int n, m;
vector < int > starting[N], ending[N];
long long dp[N];
edge e[N];
multiset < int > weights[N];
binary_indexed_tree < long long, long long, min_merge, assign_merge, INF > bit;

void add_edge(edge e) {
  weights[e.r].insert(e.w);
  bit.update(e.r, min(INF, dp[e.r] + *weights[e.r].begin()));
}

void remove_edge(edge e) {
  weights[e.r].erase(weights[e.r].find(e.w));
  bit.update(e.r, weights[e.r].empty() ? INF : min(INF, dp[e.r] + *weights[e.r].begin()));
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  int i, j;

  cin>>n>>m;
  for(i=1;i<=m;i++) {
    cin>>e[i].l>>e[i].r>>e[i].w;
    starting[e[i].r].push_back(i);
    ending[e[i].l].push_back(i);
  }

  bit.initialize(n);

  dp[n] = 0;
  for(i=n;i>=1;i--) {
    if(i<n) {
      dp[i] = min(INF, bit.query(i + 1, n));
    }

    for(j=0;j<(int)(starting[i].size());j++) {
      add_edge(e[starting[i][j]]);
    }

    for(j=0;j<(int)(ending[i].size());j++) {
      remove_edge(e[ending[i][j]]);
    }
  }

  cout<<(dp[1]==INF ? -1 : dp[1])<<endl;

  return 0;
}

