    rep(i, m) {
        ll l, r, c;
        cin >> l >> r >> c;
        l--, r--;
        es.eb(edge(l, r, c));
    }
    sort(all(es), [](edge &a, edge &b) { return a.cost < b.cost; });

    UnionFind uf(n);
    Graph g(n);
    set<ll> idxs;
    rep(i, n) idxs.insert(i);
    rep(i, m) {
        ll s, t, c;
        s = es[i].from, t = es[i].to, c = es[i].cost;
        if (!uf.is_same(s, t)) {
            g.add(uf.find(s), uf.find(t), c);
        }
        auto itr = idxs.upper_bound(s);
        if (itr == idxs.end()) continue;
        ll now = *itr;
        itr++;

        while (itr != idxs.end() && *itr <= t) {
            uf.unite(now, *itr);
            idxs.erase(itr++);
        }
        g.add(uf.find(s), uf.find(now), c);
    }
    vl ans = g.dijkstra(0);
    cout << ans << '\n';
    cout << ans.back() << '\n';
}

