template < typename T >
struct Monoid
{
	T id;
	function < T(T, T) > op;
	Monoid ( T id, function < T(T, T) > op) : id(id), op(op) {}
};

template < typename T >
struct SegmentTree
{

	const Monoid < T > monoid;
	vector < T > dat;
	int size;

	SegmentTree(int n, Monoid < T > monoid) : monoid(monoid)
	{
		size = 1;
		while ( size < n ) {
			size *= 2;
		}
		dat.assign(size * 2 + 10, monoid.id);
	}

	void update(int k, T x)
	{
		k += size - 1;
		dat[k] = x;
		while ( k > 0 ) {
			k = (k - 1) / 2;
			dat[k] = monoid.op(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}

	void add(int k, T x)
	{
		update(k, monoid.op(x, dat[k + size - 1]));
	}

	T query(int a, int b)
	{
		return (query(a, b, 0, 0, size - 1));
	}

	T query(int a, int b, int k, int l, int r)
	{
		T vl, vr;
		if ( r < a || b < l ) return ( monoid.id );
		if ( a <= l && r <= b ) return ( dat[k] );
		vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		vr = query(a, b, k * 2 + 2, (l + r) / 2 + 1, r);
		return ( monoid.op(vl, vr) );
	}
};

int main()
{
	int N, M;
	vector < Edge > G[100005];

	cin >> N >> M;

	SegmentTree < ll > seg(N, Monoid < ll > (LLINF, [](ll a, ll b) { return (min(a, b)); } ));

	while ( M-- ) {
		ll L, R, C;
		cin >> L >> R >> C; --L, --R;
		G[L].emplace_back(R, C);
	}

	seg.update(0, 0);

	for ( int i = 0; i < N; i++ ) {
		for ( Edge &e : G[i] ) {
			ll cost = seg.query(i, N - 1);
			if ( cost != LLINF ) {
				cost += e.cost;
				seg.add(e.to, cost);
			}
		}
	}

	ll ans = seg.query(N - 1, N - 1);

	if ( ans == LLINF ) {
		cout << -1 << endl;
	} else {
		cout << ans << endl;
	}

	return ( 0 );
}

