int V;
const int MAX_V=100100;
vector<edge> G[MAX_V];
ll d[MAX_V];

void dijkstra(int s){
	priority_queue<Pi,vector<Pi>,greater<Pi> >que;
	fill(d,d+V,1e15);
	d[s]=0;
	que.push(Pi(0,s));
	while(!que.empty()){
		Pi p=que.top();que.pop();
		int v=p.second;
		if(d[v]<p.first)continue;
		for(int i=0;i<G[v].size();i++){
			edge e=G[v][i];
			if(d[e.to]>d[v]+e.cost){
				d[e.to]=d[v]+e.cost;
				que.push(Pi(d[e.to],e.to));
			}
		}
	}
}

