#include <bits/stdc++.h>

struct graph_t {
	std::vector<std::vector<std::pair<int, int>>> G;
	void add_edge(int u, int v, int w) {
		G[u].emplace_back(w, v);
		//std::cout << u << " -> " << v << ": " << w << '\n';
	}
	int size() {
		return G.size();
	}
	int new_var() {
		int res = size();
		G.emplace_back();
		return res;
	}
	int64_t dijkstra(int s, int t) {
		std::priority_queue<std::pair<int64_t, int>, std::vector<std::pair<int64_t, int>>, std::greater<std::pair<int64_t, int>>> q;
		std::vector<int64_t> dis(size(), LLONG_MAX);
		q.emplace(dis[s] = 0, s);
		while (!q.empty()) {
			int64_t w = q.top().first;
			int u = q.top().second;
			q.pop();
			if (w != dis[u]) continue;
			for (std::pair<int, int>& it : G[u]) {
				if (dis[u] + it.first < dis[it.second]) {
					dis[it.second] = dis[u] + it.first;
					q.emplace(dis[it.second], it.second);
				}
			}
		}
		return dis[t] == LLONG_MAX ? -1 : dis[t];
	}
};

struct seg_t {
	const int n;
	std::vector<int> seg;
	template <class Fun>
	seg_t(int n, graph_t& graph, Fun&& fun): n(n), seg(n + n) {
		for (int i = 0; i < n; i++)
			seg[i + n] = i;
		for (int i = n - 1; i; i--) {
			seg[i] = graph.new_var();
			fun(seg[i], seg[i + i + 0]);
			fun(seg[i], seg[i + i + 1]);
		}
	}
	template <class Fun>
	void travel(int l, int r, Fun&& fun) {
		for (l += n, r += n; l < r; l /= 2, r /= 2) {
			if (l & 1) fun(seg[l++]);
			if (r & 1) fun(seg[--r]);
		}
	}
};

int main() {
	int n, m;
	scanf("%d%d", &n, &m);
	graph_t graph;
	for (int i = 0; i < n; i++)
		graph.new_var();
	seg_t segA(n, graph, [&](int u, int v) {
		graph.add_edge(u, v, 0);
	});
	seg_t segB(n, graph, [&](int u, int v) {
		graph.add_edge(v, u, 0);
	});
	for (int i = 0, l, r, w; i < m; i++) {
		scanf("%d%d%d", &l, &r, &w);
		--l;
		int var = graph.new_var();
		segA.travel(l, r, [&](int v) {
			graph.add_edge(var, v, 0);
		});
		segB.travel(l, r, [&](int v) {
			graph.add_edge(v, var, w);
		});
	}
	printf("%lld\n", graph.dijkstra(0, n - 1));
	return 0;
}

