void add(ll a,ll b,ll c){
    e[idx] = b,w[idx] = c,ne[idx] = h[a],h[a] = idx++;
}

ll Dijkstra(){
    for(ll i = 1;i<=N;i++) dis[i] = inf;
    heap.push({0,1});
    dis[1] = 0;

    while (heap.size()) {
        auto cur = heap.top();heap.pop();
        ll d = cur.first,s = cur.second;
        if(vis[s] == 1) continue;
        for(ll i = h[s];i!=-1;i = ne[i]){
            ll j = e[i];
            if(d+w[i] < dis[j]){
                dis[j] = d+w[i];
                heap.push({dis[j],j});
            }
        }
    }
    if(dis[N] == inf ) return -1;
    return dis[N];
}

