    scanf("%d%d",&n,&m);
    build(0,1,n,1); build(1,1,n,1);
    for(int i=1;i<=m;i++){
        int l,r,c; scanf("%d%d%d", &l,&r,&c);
        {
            int x=++C, y=++C;
            split(0, x, 1, n, 1, l, r);
            g[x].push_back(make_pair(y, c));
            split(1, y, 1, n, 1, l, r);
        }
        {
            int x=++C, y=++C;
            split(0, y, 1, n, 1, l, r);
            g[y].push_back(make_pair(x, c));
            split(1, x, 1, n, 1, l, r);
        }
    }
    //printf("s = %d, t = %d\n", s, t);
    dijkstra();
}

