vl memo(MAX,-1);
set<int> beg;
ll pd(int i){
	if(i == N) return 0LL;
	if(memo[i] != -1LL) return memo[i];
	ll total = INF;
	int mn = i;
	for(int j = 0; j < sz(reach[i]); j++){
		ll C = reach[i][j].f;
		int R = reach[i][j].s;

		if(mn >= R) continue;

		set<int>::iterator ns = beg.lower_bound(mn+1);
		mn = R;		
		for(; ns != beg.end() && *ns <= R; ns++){
			total = min(total, C + pd(*ns));
		}

		if(total < INF) return total;
	}
	return memo[i] = total;
}

