template<class T>
struct SegmentTree{
    using F=function<T(T,T)>;

    const F f;
    int size;
    vector<T> seg;
    const T inf;

    SegmentTree(int N,const F f,const T &inf) :f(f),inf(inf){
        size=1;
        while(size<N) size<<=1;
        seg.assign(2*size,inf);
    }
    void set(int k,const T &x){
        seg[k+size]=x;
    }
    void build(){
        for(int k=size-1;k>0;k--){
            seg[k]=f(seg[2*k],seg[2*k+1]);
        }
    }
    void update(int k,const T &x){
        k+=size;
        seg[k]=x;
        while(k>>=1){
            seg[k]=f(seg[2*k],seg[2*k+1]);
        }
    }
    //[a:b)
    T query(int a,int b){
        T L=inf,R=inf;
        for(a+=size,b+=size;a<b;a>>=1,b>>=1){
            if(a&1) L=f(L,seg[a++]);
            if(b&1) R=f(seg[--b],R);
        }
        return f(L,R);
    }

    T operator[](const int &k) const{
        return seg[k+size];
    }
};

