using namespace std;
typedef long long ll;

struct Edge { 
  int from, to;
  ll cost;
  Edge() {}
  Edge(int f, int t, ll c): from(f), to(t), cost(c) {}
};

struct Node {
  int id;
  ll cost;
  Node(int id, ll c) : id(id), cost(c) {}
  friend bool operator < (const Node& lhs, const Node& rhs) { return lhs.cost < rhs.cost; };
  friend bool operator > (const Node& lhs, const Node& rhs) { return rhs < lhs; };
  friend bool operator <= (const Node& lhs, const Node& rhs) { return !(lhs > rhs); };
  friend bool operator >= (const Node& lhs, const Node& rhs) { return !(lhs < rhs); };
};

typedef vector<vector<Edge>> Graph;

ll dist[100010];
bool visit[100010];
void dijkstra(Graph &g) { 
  for (int i = 0; i < g.size(); ++i) { 
    dist[i] = -1;
  }
  dist[0] = 0;
  priority_queue<Node, vector<Node>, greater<Node>> pq;
  pq.push(Node(0, 0));
  while (!pq.empty()) { 
    Node node = pq.top(); pq.pop();
    if (visit[node.id]) continue;
    visit[node.id] = true;
    // cerr << node.id << " " << node.cost << endl;
    for (Edge& e: g[node.id]) { 
      ll cost = dist[e.from]+e.cost;
      if (dist[e.to] != -1 && dist[e.to] <= cost) {
        continue;
      }
      // cerr << e.from << " " << e.to << " " << cost << endl;
      dist[e.to] = cost;
      pq.push(Node(e.to, dist[e.to]));
    }
  }
}

