using namespace std;

class Hen {
	int L;
	int R;
	int C;
public:
	Hen() :L(0), R(0), C(0) {}
	Hen(int l, int r, int c) :L(l), R(r), C(c) {}

	int Left() {
		return L;
	}
	int Right() {
		return R;
	}
	int Cost() {
		return C;
	}

	bool operator<(const Hen& a){
		return L < a.L;
	}
};

int main() {
	int N, M;
	cin >> N >> M;

	vector<Hen> Hen_ary(M);
	for (int i = 0; i < M; i++) {
		int ll, rr, cc;
		cin >> ll >> rr >> cc;
		Hen_ary[i] = (Hen(ll, rr, cc));
	}

	sort(Hen_ary.begin(), Hen_ary.end());

	vector<long long> Dis(N, LLONG_MAX);
	Dis[0] = 0LL;

	for (int i = 0; i < M; i++) {

		//辺データ区間内の最小値を探す
		long long Cost_min = LLONG_MAX;
		for (int j = Hen_ary[i].Left(); j < Hen_ary[i].Right(); j++) {
			if (Dis[j - 1] < Cost_min) {
				Cost_min = Dis[j - 1];
			}
		}

		//辺が途切れていたらそこで終了
		if (Cost_min == LLONG_MAX) {
			cout << -1;
			return 0;
		}

		//辺データ区間内の、始点からの距離を更新
		for (int j = Hen_ary[i].Left() + 1; j <= Hen_ary[i].Right(); j++) {
			if (Dis[j - 1] > Hen_ary[i].Cost() + Cost_min) {
				Dis[j - 1] = Hen_ary[i].Cost() + Cost_min;
			}
		}
	}

	cout << Dis[N - 1];
	return 0;

}

