template<class T> constexpr auto RLE(std::vector<T> const& v) { // run length encoding
  std::vector<std::pair<T, std::size_t>> w{}; auto t=std::begin(v); std::size_t cnt=0;
  for(auto i=std::begin(v); i!=std::end(v); ++i) { if(*t == *i) ++cnt; else w.emplace_back(*t, cnt), t=i, cnt=1; }
  if(cnt > 0) w.emplace_back(*t, cnt); return w;
}

template<class T> auto cum_sum(std::vector<T> const& v) {
  std::vector<T> a(v.size()+1);
  for(std::size_t i=0;i<a.size();++i) a[i+1] = a[i] + v[i];
  return a;
}

