struct Edge{
  int to;
  ll weight;
  Edge(int t, ll w) : to(t),weight(w){}
};
using Graph = vector<vector<Edge>>;
typedef pair<ll, int> P;  // first: 最短距離, second: 頂点番号

Graph G;
vector<ll> d;

void dijkstra(int s) {
    fill(all(d), INF);
    d[s] = 0;  // 始点sへの最短距離は0

    priority_queue<P, vector<P>, greater<P>> pq;  // 距離が小さい順に取り出せるようgreater<P>を指定
    pq.push(P(0, s));
    while (!pq.empty()) {
        P p = pq.top();
        pq.pop();
        int v = p.second;  // 更新した頂点の中で距離が最小の頂点v
        if (d[v] < p.first) {
            continue;
        }
        for (auto e : G[v]) {  // 頂点vから出る辺eを走査
            if (d[e.to] > d[v] + e.weight) {
                d[e.to] = d[v] + e.weight;
                pq.push(P(d[e.to], e.to));
            }
        }
    }
}

