#include<bits/stdc++.h>
using namespace std;

const int N = 1e5 + 5;
vector<pair<int, int>> C[N];
long long a[N], seg[N << 1];
int n, m;

void update(int p, long long x, int id = 1, int st = 0, int en = n) {
	if (en - st == 1) {
		seg[id] = x;
		return;
	}
	int mid = st + en >> 1;
	if (p < mid)
		update(p, x, id << 1, st, mid);
	else
		update(p, x, id << 1 | 1, mid, en);
	seg[id] = min(seg[id << 1], seg[id << 1 | 1]);
}

long long get(int l, int r, int id = 1, int st = 0, int en = n) {
	if (r <= st || en <= l)
		return 1e18;
	if (l <= st && en <= r)
		return seg[id];
	int mid = st + en >> 1;
	return min(get(l, r, id << 1, st, mid), get(l, r, id << 1 | 1, mid, en));
}

inline void read_input() {
	cin >> n >> m;
	for (int i = 0; i < m; i++) {
		int l, r, c;
		cin >> l >> r >> c;
		C[--r].push_back({--l, c});
	}
}

inline void solve() {
	memset(a, 63, sizeof a);
	memset(seg, 63, sizeof seg);
	for (int i = a[0] = 0; i < n; update(i, a[i]), i++)
		for (auto x: C[i])
			a[i] = min(a[i], get(x.first, i) + x.second);
	cout << (a[n - 1] < 1e18? a[n - 1]: -1);
}

int main() {
	ios:: sync_with_stdio(0), cin.tie(0), cout.tie(0);
	read_input(), solve();
	return 0;
}

