#include <bits/stdc++.h>
using namespace std;
using LL = long long;
constexpr LL INF = 1E18;
constexpr int N = 1E5;
int n, m;
struct Node {
    int cnt;
    LL mn, lazy;
    vector<tuple<int, int, int>> e;
} t[4 * N];
void build(int p, int l, int r) {
    t[p].cnt = r - l;
    t[p].lazy = INF;
    if (r - l == 1) {
        t[p].mn = l == 0 ? 0 : INF;
        return;
    }
    int mid = (l + r) / 2;
    build(2 * p, l, mid);
    build(2 * p + 1, mid, r);
    t[p].mn = min(t[2 * p].mn, t[2 * p + 1].mn);
}
void addEdge(int p, int l, int r, int x, int y, int c) {
    if (l >= y || r <= x)
        return;
    if (l >= x && r <= y) {
        t[p].e.emplace_back(x, y, c);
        return;
    }
    int mid = (l + r) / 2;
    addEdge(2 * p, l, mid, x, y, c);
    addEdge(2 * p + 1, mid, r, x, y, c);
}
void pushdown(int p) {
    if (t[2 * p].cnt != 0) {
        t[2 * p].lazy = min(t[2 * p].lazy, t[p].lazy);
        t[2 * p].mn = min(t[2 * p].mn, t[p].lazy);
    }
    if (t[2 * p + 1].cnt != 0) {
        t[2 * p + 1].lazy = min(t[2 * p + 1].lazy, t[p].lazy);
        t[2 * p + 1].mn = min(t[2 * p + 1].mn, t[p].lazy);
    }
}
pair<int, LL> getMin(int p, int l, int r) {
    --t[p].cnt;
    if (r - l == 1) {
        LL tmp = t[p].mn;
        t[p].mn = INF + 1;
        return {l, tmp};
    }
    int mid = (l + r) / 2;
    pushdown(p);
    pair<int, LL> result;
    if (t[2 * p].mn == t[p].mn) {
        result = getMin(2 * p, l, mid);
    } else {
        result = getMin(2 * p + 1, mid, r);
    }
    t[p].mn = min(t[2 * p].mn, t[2 * p + 1].mn);
    return result;
}
void rangeCover(int p, int l, int r, int x, int y, LL d) {
    if (t[p].cnt == 0)
        return;
    if (l >= y || r <= x)
        return;
    if (l >= x && r <= y) {
        t[p].lazy = min(t[p].lazy, d);
        t[p].mn = min(t[p].mn, d);
        return;
    }
    int mid = (l + r) / 2;
    pushdown(p);
    rangeCover(2 * p, l, mid, x, y, d);
    rangeCover(2 * p + 1, mid, r, x, y, d);
    t[p].mn = min(t[2 * p].mn, t[2 * p + 1].mn);
}
void expand(int p, int l, int r, int u, LL d) {
    for (auto _e : t[p].e) {
        int l, r, c;
        tie(l, r, c) = _e;
        rangeCover(1, 0, n, l, r, c + d);
    }
    t[p].e.clear();
    if (r - l == 1)
        return;
    int mid = (l + r) / 2;
    if (u < mid)
        expand(2 * p, l, mid, u, d);
    else
        expand(2 * p + 1, mid, r, u, d);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    build(1, 0, n);
    for (int i = 0; i < m; ++i) {
        int l, r, c;
        cin >> l >> r >> c;
        addEdge(1, 0, n, --l, r, c);
    }
    for (int i = 0; i < n; ++i) {
        int u;
        LL d;
        tie(u, d) = getMin(1, 0, n);
        if (u == n - 1) {
            cout << (d == INF ? -1 : d) << endl;
            return 0;
        }
        expand(1, 0, n, u, d);
    }
    return 0;
}

