ll solve() {
    ll INF = 1LL<<60;
    ll N, M;
    cin >> N >> M;
    vector<ll> L(M), R(M), C(M);
    //vector<pii> ri;
    vector<pii> li;
    for ( int i = 0; i < M; i++ ) {
        cin >> L[i] >> R[i] >> C[i];
        L[i]--, R[i]--;
        li.push_back(pii(L[i], i));
    }
    sort(li.begin(), li.end());
    priority_queue<pii, vector<pii>, greater<>> q;  //dp[L]+C,R
    int ii = 0;
    vector<ll> dp(N+1, INF);
    q.push(pii(0,0));
    for ( ll l = 0; l < N; l++ ) {
        while ( !q.empty() && q.top().second < l ) q.pop();
        if ( q.empty() ) return -1;
        dp[l] = q.top().first;
        while ( !q.empty() && q.top().second <= l ) q.pop();
        while ( ii < M && li[ii].first == l ) {
            int j = li[ii].second;
            q.push(pii(dp[l]+C[j], R[j]));
            ii++;
        }
    }
    if ( dp[N-1] == INF ) return -1;
    return dp[N-1];
}

