ll ans = INT_MAX;
bool is_found = false;
int dst = -1;

void calc(const vector<vector<pair<int, int>>> & memo, int cur, ll cost)
{
	if (ans <= cost) { return; }

	if (cur == dst)
	{
		ans = cost;
		is_found = true;
	}

	for (auto && root : memo[cur])
	{
		calc(memo, root.second, root.first + cost);
	}
}

