struct Dijkstra {
    ll N;
    vvpll to;
    vll cost;
    vll prev;
    priority_queue<tll> q;  // (cost, loc, prev)
    explicit Dijkstra(ll N)
    {
        this->N = N;
        this->to = vvpll(this->N);
        this->cost = vll(this->N, INF);
        this->prev = vll(this->N, -1);
    }
    void connect(ll from, ll to, ll length)
    {
        // Add a new edge of the specified length that
        // connects the specified two vertices.
        this->to[from].emplace_back(to, length);
    }
    void init(ll loc, ll cost = 0)
    {
        // Set the initial value.
        this->q.push(make_tuple(-cost, loc, -1));
    }
    void calc()
    {
        while (!this->q.empty()) {
            ll co, lo, pr;
            tie(co, lo, pr) = this->q.top();
            this->q.pop();
            co = -co;
            if (this->cost[lo] > co) {
                this->cost[lo] = co;
                this->prev[lo] = pr;
                for (pll& pa : this->to[lo]) {
                    ll lo2 = pa.first;
                    ll co2 = co + pa.second;
                    this->q.push(make_tuple(-co2, lo2, lo));
                }
            }
        }
    }
    ll get(ll loc) { return this->cost[loc]; }
    ll get_prev(ll loc) { return this->prev[loc]; }
};
//---------------------------------------------------------
void solve()
{
    ll N, M;
    in(N, M);
    Dijkstra di(N);
    for1 (i, M) {
        ll l, r, c;
        in(l, r, c);
        --l;
        --r;
        di.connect(l, r, c);
    }
    for2 (i, 1, N) {
        di.connect(i, i - 1, 0);
    }
    di.init(0);
    di.calc();

    // dump(di.cost);
    if (di.get(N - 1) == INF) {
        print(-1);
    }
    else {
        print(di.get(N - 1));
    }
}
