    ios::sync_with_stdio(false);

    ll n, m;
    cin >> n >> m;
    ll l, r, c;
    vector<edge> ee;
    REP(i, m) {
        cin >> l >> r >> c;
        l--, r--;
        ee.push_back(edge{l, r, c});
    }
    sort(ee.begin(), ee.end(), comp);
    a[0] = 0;
    REP(i, m) {
        l = ee[i].l, r = ee[i].r, c = ee[i].c;
        // 頂点 0 からの最短距離を update
        update(l, r, c);
    }
    ll res = a[n - 1];
    if (res == inf) res = -1;
    cout << res << endl;
    return 0;
}

