using namespace std;
const ll inf = 0x3f3f3f3f3f3f3f3f;
const int maxn = 100010;
int n, m;
ll ans[maxn << 2], tag[maxn << 2];
struct event {
    int l, r, c;
    bool operator < (const event & a) const { return l < a.l; }
} a[maxn];
void push_up(int p) { ans[p] = min(ans[ls(p)], ans[rs(p)]); }
void build(int p, int l, int r) {
    tag[p] = -1;
    if(l == r) {
        ans[p] = inf;
        return;
    }
    int mid = (l + r) >> 1;
    build(ls(p), l, mid), build(rs(p), mid + 1, r);
    push_up(p);
}
void push_down(int p) {
    ans[ls(p)] = min(ans[ls(p)], tag[p]);
    ans[rs(p)] = min(ans[rs(p)], tag[p]);
    if(~tag[ls(p)]) tag[ls(p)] = min(tag[ls(p)], tag[p]);
    else tag[ls(p)] = tag[p];
    if(~tag[rs(p)]) tag[rs(p)] = min(tag[rs(p)], tag[p]);
    else tag[rs(p)] = tag[p];
    tag[p] = -1;
}
ll query(int p, int l, int r, int x) {
    if(l == r) return ans[p];
    if(~tag[p]) push_down(p);
    int mid = (l + r) >> 1;
    if(x <= mid) return query(ls(p), l, mid, x);
    else return query(rs(p), mid + 1, r, x);
}
void update(int p, int l, int r, int ql, int qr, ll x) {
    if(ql <= l && r <= qr) {
        ans[p] = min(ans[p], x);
        if(~tag[p]) tag[p] = min(tag[p], x);
        else tag[p] = x;
        return;
    }
    if(~tag[p]) push_down(p);
    int mid = (l + r) >> 1;
    if(ql <= mid) update(ls(p), l, mid, ql, qr, x);
    if(qr > mid) update(rs(p), mid + 1, r, ql, qr, x);
    push_up(p);
}
int main()
{
    read(n), read(m);
    build(1, 1, n);
    rep(i, 1, m)
        read(a[i].l), read(a[i].r), read(a[i].c);
    sort(a + 1, a + 1 + m);
    update(1, 1, n, 1, 1, 0);
    rep(i, 1, m) {
        ll tmp = query(1, 1, n, a[i].l);
        update(1, 1, n, a[i].l + 1, a[i].r, tmp + a[i].c);
    }
    ll res = query(1, 1, n, n);
    printf("%lld\n", res == inf ? -1 : res);
    return 0;
}

