const int MAXN=1e5+10;
vector<vector<pair<int,int>>> gra(MAXN);
int dist[MAXN];
const int INF=1e18;
int32_t main(){
	int n,m;cin>>n>>m;
	priority_queue<pair<pair<int,int>,int>,vector<pair<pair<int,int>,int>>,greater<pair<pair<int,int>,int>>> pq;
	for(int i=0;i<m;i++){
		int l,r,c;cin>>l>>r>>c;
		pair<pair<int,int>,int> tmp;
		tmp.first.first=l;
		tmp.first.second=r;
		tmp.second=c;
		pq.push(tmp);
	}
	vector<int> mv;
	int count=0;
	while(!pq.empty()){
		pair<pair<int,int>,int> t=pq.top();pq.pop();
		int l=t.first.first;
		int r=t.first.second;
		int w=t.second;
		l-=1;
		r-=1;
		if(l==0){
			if(!count){
				mv.push_back(0);
				count++;
			}
			auto it=upper_bound(mv.begin(),mv.end(),r);
			mv.insert(it,r);
			gra[l].emplace_back(make_pair(r,w));

		}else{
			int pos1=lower_bound(mv.begin(),mv.end(),l)-mv.begin();
			if(pos1==(int)mv.size()){
				cout<<-1<<endl;
				return 0;
			}
			int pos2=upper_bound(mv.begin(),mv.end(),r)-mv.begin();
			for(int poi=pos1;poi<pos2;poi++){
				int a=mv[poi];
				gra[a].emplace_back(make_pair(r,w));
			}
			auto it=upper_bound(mv.begin(),mv.end(),r);
			mv.insert(it,r);
		}
	}
	for(int i=0;i<MAXN;i++)dist[i]=INF;
	priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pq2;
	int u=0;
	dist[u]=0;
	pq2.push(make_pair(0,u));
	while(!pq2.empty()){
		pair<int,int> ii=pq2.top();pq2.pop();
		int dis=ii.first;int u=ii.second;
		if(dis>dist[u])continue;
		for(int i=0;i<(int)gra[u].size();i++){
			int nx=gra[u][i].first;
			int we=gra[u][i].second;
			if(dist[nx]>dist[u]+we){
				dist[nx]=dist[u]+we;
				pq2.push(make_pair(dist[nx],nx));
			}
		}
	}
	if(dist[n-1]>=INF)cout<<-1<<endl;
	else cout<<dist[n-1]<<endl;
	return 0;
}

