        l--; r--;
        edge e = {r, c};
        G[l].push_back(e);
    }
    REP(i, n - 1) {
        edge e = {i, 0};
        G[i + 1].push_back(e);
    }
    dijkstra(0);
    cout << (d[n - 1] == LINF ? -1 : d[n - 1]) << EOL;
}

