	auto lazycalcfn=[](long a,long b){return a<b?a:b;};
	auto updatefn=[](long a,long b,int l,int r){return a<b?a:b;};
	lazysegtree<long>P(N,1e18,calcfn,lazycalcfn,updatefn,1e18);
	P.update(0,1,0);
	for(pair<pair<int,int>,int>p:E)
	{
		long X=P.query(p.first.first,p.first.second);
		P.update(p.first.first,p.first.second,X+p.second);
	}
	long ans=P.query(N-1,N);
	cout<<(ans<1e18?ans:-1)<<endl;
