void dijkstra(int s){
  priority_queue<P,vector<P>,greater<P>> PQ;
  dist[s] = 0;
  PQ.push(P(0,s));

  while(PQ.size()){
    P p = PQ.top();
    PQ.pop();
    int64_t v = p.second; //from
    if(dist[v] < p.first){ //現在わかっている距離が更新できない
      continue;
