            cost.erase(itr);
            overwrap.pop();
        }

        if (i > 0) {
            if (cost.empty()) dist[i] = INF;
            else dist[i] = *cost.begin();
        }

        while (idx < sz(segs) && segs[idx].first.first == i) {
            overwrap.emplace(segs[idx].first.second, idx);
            C[idx] = min(INF, dist[i] + segs[idx].second);
            cost.insert(C[idx]);
            idx++;
        }
    }
    if (dist[N - 1] == INF) cout << -1 << endl;
    else cout << dist[N - 1] << endl;
    return (0^_^0);
}

