using i64 = int64_t;

constexpr i64 INF = 1e18;

template <typename T, typename E> class SegmentTree {
  private:
    int n;
    vector<T> node;
    const function<T(T, T)> query_func;
    const function<T(T, E)> update_func;
    const T identity;

  public:
    SegmentTree() = default;

    SegmentTree(int size, function<T(T, T)> query_func,
                function<T(T, E)> update_func, T identity,
                vector<T> v = vector<T>())
        : query_func(query_func), update_func(update_func), identity(identity) {
        n = 1;
        while (n < size)
            n *= 2;
        node.resize(2 * n - 1, identity);
        if (size == v.size())
            build(size, v);
    }

    void build(int size, vector<T> v) {
        for (int i = 0; i < size; ++i)
            node[i + n - 1] = v[i];
        for (int i = n - 2; i >= 0; --i)
            node[i] = query_func(node[2 * i + 1], node[2 * i + 2]);
    }

    void update(int x, E val) {
        x += n - 1;

        node[x] = update_func(node[x], val);
        while (x > 0) {
            x = (x - 1) / 2;
            node[x] = query_func(node[2 * x + 1], node[2 * x + 2]);
        }
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0)
            r = n;

        if (r <= a || b <= l)
            return identity;

        if (a <= l && r <= b)
            return node[k];

        T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return query_func(vl, vr);
    }
};

struct Node{
    i64 l, r, c;
    bool operator<(const Node &obj)const{
        if(l == obj.l)return r < obj.r;
        return l < obj.l;
    }
};

int main(){
    i64 n, m;
    cin >> n >> m;
    vector<Node> v;
    for(int i=0;i<m;++i){
        i64 l, r, c;
        cin >> l >> r >> c;
        v.push_back({l, r, c});
    }
    vector<i64> dp(n+1, INF);
    dp[1] = 0;
    SegmentTree<i64, i64> sgt(
        n+1,
        [](i64 x, i64 y){return min(x, y);},
        [](i64 x, i64 y){return y;},
        INF,
        dp
    );
    sort(v.begin(), v.end());
    for(auto e: v){
        i64 tmp = sgt.query(e.l, e.r+1);
        //cout << e.l << " " << e.r << " " << tmp << endl;
        if(tmp >= INF)continue;
        if(sgt.query(e.r, e.r+1) <= tmp + e.c)continue;
        sgt.update(e.r, tmp + e.c);
    }
    i64 ans = sgt.query(n, n+1);

    cout << (ans >= INF ? -1 : ans) << endl;

    return 0;
}

