	int N=in(),M=in();
	ConnectNodeInfo connect(N);
	REP(i,N-1){
		connect.AddDirectionalConnection(i+1,i,0);
	}
	REP(i,M){
		int L=in()-1,R=in()-1,C=in();
		connect.AddNonDirectionalConnection(L,R,C);
	}
	Dijkstra Dij;
	Dij.CalcShortestPath(0,connect);
	auto dist = Dij.GetDistance(N-1);
	out(dist>=1LL<<60?-1:dist);

	return 0;
}

