    else
    {
        LL tm = (tl + tr) / 2;
        build_tree(2 * v, tl, tm);
        build_tree(2 * v + 1, tm + 1, tr);
        lazy[v] = INF;
    }
}

void push_value(LL v)
{
    lazy[2 * v] = min(lazy[v], lazy[2 * v]);
    lazy[2 * v + 1] = min(lazy[v], lazy[2 * v + 1]);
    lazy[v] = INF;
}

void update_range(LL v, LL tl, LL tr, LL left, LL right, LL value)
{
    if (right < left)
    {
        return;
    }
    else if (tl == left && tr == right)
    {
        lazy[v] = min(lazy[v], value);
    }
    else
    {
        LL tm = (tl + tr) / 2;
        if (lazy[v] != INF)
        {
            push_value(v);
        }
        update_range(2 * v, tl, tm, left, min(tm, right), value);
        update_range(2 * v + 1, tm + 1, tr, max(left, tm + 1), right, value);
    }
}

void find_value(LL v, LL tl, LL tr, LL pos)
{
    if (tl == tr)
    {
        extract = lazy[v];
    }
    else
    {
        LL tm = (tl + tr) / 2;
        if (lazy[v] != INF)
        {
            push_value(v);
        }
        if(pos<=tm)
        {
            find_value(2*v,tl,tm,pos);
        }
        else
        {
            find_value(2*v+1,tm+1,tr,pos);
        }

    }
}

