            int L,R,w;
            scanf("%d%d%d",&L,&R,&w);
            addedge(L,R,w);
        }
        Dijkstra(n,1);
        if(dist[n] == INF) dist[n] = -1;
        printf("%d\n",dist[n]);
    }
    return 0;
}

