typedef long long ll;

using namespace std;

template <class Monoid>
class SegmentTree
{
public:
  using Func = function<Monoid(Monoid, Monoid)>;
  const Func F;
  const Monoid M1;
  int sz;
  vector<Monoid> seg;

  SegmentTree(int n,const Func fu, const Monoid &m1): F(fu) , M1(m1) {init(n);}
  void init(int n)
  {
      sz= 1;
      while (sz < n) sz *= 2;
      seg.assign(sz * 2, M1);
  }
  void update(int k,const Monoid &x)
  {
    k+=sz;
    seg[k]=x;
    while(k>>=1)
    {
      seg[k]=F(seg[k*2],seg[k*2+1]);
    }
  }
  Monoid query(int l,int r)
  {
    Monoid L=M1,R=M1;
    l+=sz;r+=sz;
    for(;l<r;l>>=1,r>>=1)
    {
      if(l&1)L=F(L,seg[l++]);
      if(r&1)R=F(seg[--r],R);
    }
    return F(L,R);
  }
};

int main()
{
  ios::sync_with_stdio(false);
  cin.tie(0);
  ll n,m;cin>>n>>m;
  struct kukann{ll l,r,c;};
  vector<kukann>lr(m);
  rep(i,m){
    cin>>lr[i].l>>lr[i].r>>lr[i].c;
    lr[i].l--;
  }
  sort(all(lr),[&](kukann a,kukann b){return a.r<b.r;});
  SegmentTree<ll> st(n+7,[&](ll a,ll b){return min(a,b);},(ll)1e17);
  st.update(0,0);
  ll id=0;
  rep(i,n+1){
    ll nc=st.query(i-1,i);
    while(id<n&&lr[id].r==i){
      nc=min(nc,lr[id].c+st.query(lr[id].l,lr[id].r));
      id++;
    }
    st.update(i-1,nc);
  }
  ll res=st.query(n-1,n);
  if(res>=1e17)res=-1;
  cout<<res<<endl;
  return 0;

}

