    L[i]--;R[i]--;
  }

  vvi es(N);
  map<pii, ll> cost;

  REP(i,M) {
    int l = L[i], r = R[i];
    if (cost.count(pii(l,r)) == 0) {
      es[l].push_back(r);
      cost[pii(l,r)] = (ll)C[i];
    } else {
      cost[pii(l,r)] = min(cost[pii(l,r)], (ll)C[i]);
    }

    for(int i = l; i<r; i++) {
      if (cost.count(pii(i+1,i)) == 0) {
        es[i+1].push_back(i);
        cost[pii(i+1,i)] = 0LL;
      }
    }
  }

  vl dist;
  dijkstra(dist, es, 0, cost);

  ll ans = dist[N-1] >= LINF ? -1 : dist[N-1];
  cout << ans << endl;

  return 0;
}

