int N, M;
pair<pair<int, int>, int>e[100000];
ll tree[1 << 18];

void update(int l, int r, int p, int q, int k, ll x) {
	if (r < p || q < l)return;
	if (p <= l&&r <= q) {
		tree[k] = min(tree[k], x);
		return;
	}
	update(l, (l + r) / 2, p, q, k * 2, x);
	update((l + r) / 2 + 1, r, p, q, k * 2 + 1, x);
}

ll get(int x) {
	ll a = llmax;
	x += (1 << 17);
	while (x) {
		a = min(a, tree[x]);
		x /= 2;
	}
	return a;
}

int main() {
	cin >> N >> M;
	for (int i = 0; i < M; i++) {
		cin >> e[i].first.first >> e[i].first.second >> e[i].second;
	}
	sort(e, e + M);
	for (int i = 0; i < (1 << 18); i++) {
		tree[i] = llmax;
	}
	update(0, (1 << 17) - 1, 1, 1, 1, 0);
	int p = 0;
	for (int i = 1; i <= N; i++) {
		ll t = get(i);
		if (t == llmax) {
			cout << -1 << endl;
			return 0;
		}
		for (; p < M&&e[p].first.first == i; p++) {
			update(0, (1 << 17) - 1, i, e[p].first.second, 1, t + e[p].second);
		}
	}
	cout << get(N) << endl;
}

