int n, m;
long long ans[400005], tag[400005];
#define ls (p<<1)
#define rs (p<<1|1)
#define mid ((l + r) >> 1)
void pushdown(int p) {
    if(tag[p] == inf) return;
	tag[ls] = min(tag[ls], tag[p]);
	tag[rs] = min(tag[rs], tag[p]);
	ans[ls] = min(ans[ls], tag[p]);
	ans[rs] = min(ans[rs], tag[p]);
	tag[p] = inf;
	return;
}
void update(int p, int l, int r, int ql, int qr, long long c) {
	if(ql <= l && r <= qr) {
		tag[p]= min(tag[p], c);
		ans[p]= min(ans[p], c);
		return;
	}
	pushdown(p);
	if(mid >= ql) update(ls, l, mid, ql, qr, c);
	if(mid < qr) update(rs, mid + 1, r, ql, qr, c);
	return;
}
long long query(int p, int l, int r, int x) {
	if(l == r) return ans[p];
	pushdown(p);
	if(mid >= x) return query(ls, l, mid, x);
	return query(rs, mid + 1, r, x);
}
