template <typename T> class LazySegmentTreeRangeMinimumQuery{
private:
  int size;
  vector<T> vec;
  T e;

  inline void propagate(int i){
    if(i<size/2){
      vec[i*2+1] = min(vec[i], vec[i*2+1]);
      vec[i*2+2] = min(vec[i], vec[i*2+2]);
      vec[i] = e;
    }
  }

  inline void update_aux(int s, int t, int i, int l, int r, const T &x){
    if(r <= s || t <= l) return;
    else if(s <= l && r <= t) vec[i] = min(vec[i], x);
    else{
      propagate(i);
      update_aux(s,t,i*2+1,l,(l+r)/2,x);
      update_aux(s,t,i*2+2,(l+r)/2,r,x);
    }
  }

  inline void get_aux(int i){
    if(i>0) get_aux((i-1)/2);
    propagate(i);
  }

public:
  LazySegmentTreeRangeMinimumQuery(int n, const T &e): e(e){
    size = 1;
    while(size < n) size *= 2;
    size = size*2-1;
    vec = vector<T>(size, e);
  }

  inline void update(int s, int t, const T &x){
    update_aux(s,t,0,0,size/2+1,x);
  }

  inline T get(int i){
    int j=i+size/2;
    get_aux((j-1)/2);
    return vec[j];
  }
};



