    int64 c; cin >> c;
    --l; --r;
    v.push_back((edge){l, r, c});
  }
  sort(v.begin(), v.end(), [](const edge& x, const edge& y) {
    return x.to < y.to;
  });
  SegmentTree<int64> seg(dp, INF, [](int64 x, int64 y) {
    return min(x, y);
  });

  for (int i = 0; i < m; ++i) {
    dp[v[i].to] = min(dp[v[i].to], seg.Query(v[i].from, v[i].to) + v[i].cost);
    seg.Update(v[i].to, dp[v[i].to]);
  }
  if (dp[n - 1] == INF) {
    cout << -1 << endl;
  } else {
    cout << dp[n - 1] << endl;
  }

  return 0;
}

