        if (l[v] == 1) {
            upd(1, 1, n, r[v], cost[v]);
            if (r[v] == n) bst = min(bst, (ll)cost[v]);
        }
        else {
            ll mn = get(1, 1, n, l[v], r[v]);
            if (mn == INF) continue;
            mn += cost[v];
            upd(1, 1, n, r[v], mn);
            if (r[v] == n) bst = min(bst, mn);
