const ll INF = 1LL << 60;
struct Edge{
  int to;
  int weight;
  Edge(int t, int w) : to(t), weight(w){}
};
using Graph = vector<vector<Edge>>;
using P = pair<ll, int>;

Graph G;
vector<ll> d; //distance;

// d[v] に頂点 s からの頂点 v の距離を入れる関数
void dijkstra(int s){
  fill(all(d), INF);
  d[s] = 0;

  priority_queue<P, vector<P>, greater<P>> pq;//距離が小さい順に取り出す
  pq.push(P(0,s)); // 頂点 s からスタート

  while (!pq.empty()) {
    P p = pq.top(); pq.pop();
    int v = p.second;
    if(d[v] < p.first) continue;// 既に v に辿り着く短い経路有ならスルー

    for(auto e : G[v]){// v から行ける頂点 nv 達を走査
      int nv = e.to;
      ll w = e.weight;
      if(d[nv] > d[v] + w){
        d[nv] = d[v] + w;
        pq.push(P(d[nv], nv));
      }
    }
  }
}

