vector<ll> dijkstra(int start, int n, vector<vector<Edge>> &g){
    vector<ll> dist(n, INF);
    priority_queue<pair<ll,ll>, vector<pair<ll,ll>>, greater<pair<ll,ll>>> q;
    q.push(make_pair(0, start));
    dist[start] = 0;
    while(!q.empty()){
        ll now = q.top().second;
        ll nowdist = q.top().first;
        q.pop();
        if(dist[now] < nowdist) continue;
        for(int i = 0; i < g[now].size(); i++){
            ll next = g[now][i].to;
            ll nextcost = g[now][i].cost;
            if(dist[next] <= nowdist + nextcost) continue;
            dist[next] = nowdist + nextcost;
            q.push(make_pair(dist[next], next));
        }
    }

    return dist;

}
