void build(int p,int l,int r) 
{
	tin[p].l = l, tin[p].r = r;
	tout[p].l = l, tout[p].r = r;
	if(l==r)
	{
		tin[p].id = tout[p].id = l;
		return;
	}
	int mid = (l+r) >> 1;
	build(p<<1,l,mid);
	build(p<<1|1,mid+1,r);
	tin[p].id = ++tot; tout[p].id = ++tot;
	add(tin[p].id,tin[p<<1].id,0);
	add(tin[p].id,tin[p<<1|1].id,0);
	add(tout[p<<1].id,tout[p].id,0);
	add(tout[p<<1|1].id,tout[p].id,0);
}
void treeadd2(int p,int x,int y,int u,int w) 
{
	int l = tout[p].l, r = tout[p].r;
	if(l>=x&&r<=y)
	{
		add(tout[p].id,u,w);
		return;
	}
	int mid = (l+r) >> 1;
	if(x<=mid) treeadd2(p<<1,x,y,u,w);
	if(y>mid) treeadd2(p<<1|1,x,y,u,w);
}
ll dis[N];
bool vis[N];
void Dijkstra(int s)
{
	memset(dis,0x3f,sizeof(dis));
	memset(vis,0,sizeof(vis));
	dis[s] = 0;
	priority_queue <pli,vector<pli>,greater<pli>> q;
	q.push(mp(0,s));
	while(!q.empty())
	{
		int u = q.top().second; 
		q.pop();
		if(vis[u]) continue;
		vis[u] = 1;
		for(int i=head[u];i;i=e[i].next)
		{
			int v = e[i].to;
			if(dis[v]>dis[u]+e[i].w)
			{
				dis[v] = dis[u] + e[i].w;
				q.push(mp(dis[v],v));
			}
		}
	}
}
