void dijkstra(int s)
{
    for (int i = 0; i <= n + 1; i++)
        d[i] = 1e18;

    priority_queue<P, vector<P>, greater<P>> q;

    q.push({0, s});

    while (q.size())
    {
        P p = q.top();
        q.pop();

        if (d[p.second] <= p.first)
            continue;

        d[p.second] = p.first;

        for (pair<int, int> i : g[p.second])
        {
            ll nex = d[p.second] + i.second;

            if (d[i.first] <= i.second)
                continue;

            q.push({nex, i.first});
        }
    }
}

