  static type op(const type &a ,const type &b){return min(a,b);}
};

void solve(long long N, long long M, std::vector<long long> L, std::vector<long long> R, std::vector<long long> C){
  vl idx(M);
  iota(ALL(idx),0LL);
  sort(ALL(idx), [&](ll lhs,ll rhs){return L[lhs]!=L[rhs] ? L[lhs]<L[rhs] : R[lhs]<R[rhs];});
  SegmentTree<RMQ> rmq(N+5);
  rmq.update(1,0LL);
  for(auto i:idx){
    ll mi = rmq.query(L[i],R[i]+1);
    ll val = rmq.query(R[i],R[i]+1);
    rmq.update(R[i],min(val,mi+C[i]));
    // dump(L[i], R[i], val, mi+C[i]);
  }
  ll ans = rmq.query(N,N+1);
  if(ans==LINF) cout << -1 << endl;
  else cout << ans << endl;
}

