class SegTree {

public:
	SegTree(int n, int64_t idt) {
		int m = 1;
		while (m < n) m *= 2;
		this->data_ = vector<int64_t>(2 * m, idt);
		this->idt_ = idt;
		this->m_ = m;
	}

	int64_t query(int i) {
		int64_t v = this->idt_;
		int idx = i + m_ - 1;
		v = min(v, this->data_[idx]);
		while (idx != 0) {
			bool from_left = (idx & 1);
			idx = (idx - 1) / 2;
			if (!from_left) continue;
			if (this->data_[idx] != this->idt_) v = min(v, this->data_[idx]);
		}

		return this->idt_;
	}

	void update(int i, int64_t v) {
		if (v < query(i)) {
			int idx = i + m_ - 1;
			this->data_[idx] = v;

			while (idx != 0) {
				bool from_left = (idx & 1);
				idx = (idx - 1) / 2;
				if (!from_left) this->data_[idx] = min(this->data_[idx], v);
			}
		}
	}

private:
	vector<int64_t> data_;
	int     m_;
	int64_t idt_;
};

