template <typename T> class seg {
    T t;
    using N = typename T::N;
    using F = typename T::F;
    vector<N> nt;
    vector<F> ft;
    void eval(int p, int l, int r) {
        if(ft[p] == t.IF)
            return;
        nt[p] = t.FN(ft[p], r - l, nt[p]);
        if(l + 1 < r) {
            t.FF(ft[p], ft[p + 1]);
            t.FF(ft[p], ft[p + (r - l & -2)]);
        }
        ft[p] = t.IF;
    }
    N init(N n, int p, int l, int r) {
        if(l + 1 == r)
            return nt[p] = n;
        int m = (l + r) / 2;
        return nt[p] =
                   t.NN(init(n, p + 1, l, m), init(n, p + (r - l & -2), m, r));
    }
    N upd(int a, int b, F f, int p, int l, int r) {
        eval(p, l, r);
        if(b <= l || r <= a)
            return nt[p];
        if(a <= l && r <= b)
            return t.FN(ft[p] = f, r - l, nt[p]);
        int m = (l + r) / 2;
        return nt[p] = t.NN(upd(a, b, f, p + 1, l, m),
                            upd(a, b, f, p + (r - l & -2), m, r));
    }
    N get(int a, int b, int p, int l, int r) {
        if(b <= l || r <= a)
            return t.IN;
        eval(p, l, r);
        if(a <= l && r <= b)
            return nt[p];
        int m = (l + r) / 2;
        return t.NN(get(a, b, p + 1, l, m), get(a, b, p + (r - l & -2), m, r));
    }

  public:
    const int s;
    seg(int s) : s(s), nt(s * 2 - 1, t.IN), ft(s * 2 - 1, t.IF) {}
    seg(int s, N n) : seg(s) { init(n, 0, 0, s); }
    void upd(int a, int b, F f) { upd(a, b, f, 0, 0, s); }
    N get(int a, int b) { return get(a, b, 0, 0, s); }
};
struct Min {
    typedef long N, F;
    const N IN = 1e18;
    const F IF = 1e18;
    N NN(N m, N n) { return min(m, n); }
    N FN(F f, int, N n) { return min(f, n); }
    void FF(F f, F &g) { g = min(f, g); }
};
