main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n,m; cin>>n>>m;
    vector<vector<pair<int,int>>> fro(n),to(n);
    while(m--)
    {
        int l,r,c; cin>>l>>r>>c;
        l--,r--;
        fro[l].emplace_back(r,c);
        to[r].emplace_back(l,c);
    }

    struct mino
    {
        long long val;
        mino(long long v=1ll<<60) : val(v) {}
        mino operator+(const mino& rhs) const
        {
            return val<rhs.val ? *this : rhs;
        }
    };

    struct chmi
    {
        long long val;
        chmi(long long v=1ll<<60) : val(v) {}
        void operator*=(const chmi& rhs)
        {
            if(val>rhs.val) val=rhs.val;
        }
        void apply(mino& rhs) const
        {
            if(rhs.val>val) rhs.val=val;
        }
    };

    lazy_segment_tree<mino,chmi> seg(n);
    seg.update(0,0);

    for(int i{}; i<n; ++i)
    {
        for(auto& itv: to[i])
        {
            int l,c; tie(l,c)=itv;
            seg.update(i,seg.fold(l,i).val+c);
        }
        for(auto& itv: fro[i])
        {
            int r,c; tie(r,c)=itv;
            seg.update(i,r+1,seg[i].val+c);
        }
    }

    if(seg[n-1].val!=mino().val)
    {
        cout << seg[n-1].val << "\n";
    }
    else
    {
        cout << -1 << "\n";
    }

}

