struct edge {
	int to;
	ll co;
	edge(int t, ll c):to(t), co(c){}
	bool operator<(const edge e) const {
		return co > e.co;
	}
};
int N, M;
vector<edge> G[100005];
ll cost[100005];
bool visited[100005] = {};
int main() {
	cin >> N >> M;
	rep(i, M) {
		int l, r, c;
		cin >> l >> r >> c;
		l--; r--;
		G[l].emplace_back(r, c);
	}
	rep(i, N - 1) {
		G[i + 1].emplace_back(i, 0);
	}

	rep(i, N) cost[i] = INF;
	cost[0] = 0;
	priority_queue<edge> pq;
	pq.emplace(0, 0);
	while (!pq.empty())
	{
		edge now = pq.top(); pq.pop();
		if (cost[now.to] < now.co) continue;
		visited[now.to] = true;
		for (auto e : G[now.to]) {
			if (visited[e.to]) continue;
			if (cost[e.to] > cost[now.to] + e.co) {
				cost[e.to] = cost[now.to] + e.co;
				pq.emplace(e.to, e.co);
			}
		}
	}
	if (cost[N - 1] == INF) cout << -1 << endl;
	else cout << cost[N - 1] << endl;

	return 0;
}

