struct Network {
private:
    vector<map<ll, ll>> adj;
    bool directed;
public:
    explicit Network(bool directed) : directed(directed) {}

    void add_edge(ll from, ll to, ll weight){
        assert(from >= 0);
        assert(to >= 0);
        assert(weight >= 0);
        if(adj.size() < max(from, to) + 1){
            adj.resize(max(from, to) + 1);
        }
        adj.at(from)[to] = weight;

        if(!directed){
            adj.at(to)[from] = weight;
        }
    }

    ll get_weight(ll from, ll to) const {
        return adj.at(from).at(to);
    }

    void dijkstra(ll src, vector<ll>& out){
        const ll n = adj.size();
        out.resize(n);
        fill(out.begin(), out.end(), -1);
        out.at(src) = 0;
        priority_queue<pair<ll, ll>> que;
        que.emplace(0, src);
        while(!que.empty()){
            const auto p = que.top(); que.pop();
            const ll v = p.second;
            for(auto nxt : adj[v]){
                if(out[nxt.first] == -1 ||
                   out[nxt.first] > out[v] + nxt.second){
                    out[nxt.first] = out[v] + nxt.second;
                    que.emplace(out[nxt.first], nxt.first);
                }
            }
        }
    }

    void floyd_warhsall(vector<vector<ll>>& out){
        const ll n = adj.size();
        out.resize(adj.size(), vector<ll>(n, -1));
        for(ll i = 0; i < n; ++i){
            for(auto p : adj.at(i)){
                out.at(i).at(p.first) = p.second;
            }
            out.at(i).at(i) = 0;
        }

        for(ll k = 0; k < n; ++k){
            for(ll i = 0; i < n; ++i){
                if(out.at(i).at(k) == -1){
                    continue;
                }
                const ll dik = out.at(i).at(k);
                for(ll j = 0; j < n; ++j){
                    if(out.at(k).at(j) == -1){
                        continue;
                    }
                    const ll dkj = out.at(k).at(j);
                    const ll dij = out.at(i).at(j);

                    if(dij == -1 || dij > dik + dkj){
                        out.at(i).at(j) = dik + dkj;
                    }
                }
            }
        }
    }
};

int main(){
    ll n, m;
    cin >> n >> m;
    Network net(true);
    REP(i, m){
        ll li, ri, ci;
