        li--; ri--;
        net.add_edge(li, ri, ci);
    }
    REP(i, n - 1){
        net.add_edge(i + 1, i, 0);
    }

    vector<ll> dist;
    net.dijkstra(0, dist);
    cout << dist[n - 1] << endl;
    return 0;
}

