ll n;
vector<ll> t(4*Nmax,INF);
vector<bool> marked(4*Nmax,0);

void push(ll v) {
    if (marked[v]) {
        t[v*2] = min(t[v*2],t[v]);
        t[v*2+1] = min(t[v*2+1],t[v]);
        marked[v*2] = marked[v*2+1] = true;
        marked[v] = false;
    }
}

void build(ll v, ll tl, ll tr) {
    if (tl == tr) {
        t[v] = (tl==1 ? 0 : INF);
    } else {
        ll tm = (tl + tr) / 2;
        build(v*2, tl, tm);
        build(v*2+1, tm+1, tr);
    }
}

void update(ll v, ll tl, ll tr, ll l, ll r, ll new_val) {
    if (l > r) 
        return;
    if (l == tl && tr == r) {
        t[v] = min(t[v],new_val);
        marked[v] = true;
    } else {
        push(v);
        ll tm = (tl + tr) / 2;
        update(v*2, tl, tm, l, min(r, tm), new_val);
        update(v*2+1, tm+1, tr, max(l, tm+1), r, new_val);
    }
}

ll find(ll v, ll tl, ll tr, ll pos) {
    if (tl == tr) {
        return t[v];
    }
    push(v);
    ll tm = (tl + tr) / 2;
    if (pos <= tm) 
        return find(v*2, tl, tm, pos);
    else
        return find(v*2+1, tm+1, tr, pos);
}

