// 0-indexed bottom up Segment Tree
// UNIT is the identity element of operation func
template <typename T = int>
struct SegmentTree {
    using F = function<T(T, T)>;
    int n;
    vector<T> dat;
    F func;
    T UNIT;

    SegmentTree(int n_, F func_, T UNIT_) : func(func_), UNIT(UNIT_) {
        n = 1;
        // full binary tree: num of leaves = n = 2^k >= n_
        while (n < n_)
            n *= 2;
        dat.assign(2 * n - 1, UNIT);
    }
    SegmentTree(vector<T> v_, F func_, T UNIT_) : func(func_), UNIT(UNIT_) {
        n = 1;
        while (n < v_.size())
            n *= 2;
        dat.assign(2 * n - 1, UNIT);
        for (int i = 0; i < v_.size(); ++i) {
            dat[n - 1 + i] = v_[i];
        }
        for (int i = n - 2; i >= 0; --i) {
            dat[i] = func(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }
    void update(int k, T a) {
        // leaves are at index n-1 to 2*n-2
        k += n - 1;
        dat[k] = a;
        while (k > 0) {
            // k -> parent node
            k = (k - 1) / 2;
            // func(child nodes)
            dat[k] = func(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }
    // get result of func() in [l, r)
    T query(int l, int r) {
        l += n - 1;
        r += n - 1;
        T ret = UNIT;
        while (l < r) {
            if ((l & 1) == 0)
                ret = func(ret, dat[l]);
            if ((r & 1) == 0)
                ret = func(ret, dat[r - 1]);
            l = l / 2;
            r = (r - 1) / 2;
        }
        return ret;
    }
};

int main() {
    int n, m;
    cin >> n >> m;
    vl l(m), r(m), c(m);
    vector<pair<pii, ll>> lrc(m);
    for (int i = 0; i < m; ++i) {
        cin >> l[i] >> r[i] >> c[i];
        l[i]--, r[i]--;
        lrc[i] = {{l[i], r[i]}, c[i]};
    }
    auto f = [](ll l, ll r) { return min(l, r); };
    SegmentTree<ll> st(n, f, INF);
    st.update(0, 0);
    sort(lrc.begin(), lrc.end());
    for (int i = 0; i < m; ++i) {
        ll curr = st.query(lrc[i].first.second, lrc[i].first.second + 1);
        ll ne   = st.query(lrc[i].first.first, lrc[i].first.second + 1) + lrc[i].second;
        if (curr > ne)
            st.update(lrc[i].first.second, ne);
    }
    if (st.query(n - 1, n) == INF) {
        cout << -1 << "\n";
    } else {
        cout << st.query(n - 1, n) << "\n";
    }
    return 0;
}

