//http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=3982722#1
struct SegmentTree{
private:
	vector<ll> node;
	int n;
    ll I=inf;//ここに代入

public:
	SegmentTree(){
		int sz=100010;
		n=1;
		//要素数を2のべき乗にする
		while(n<sz) n*=2;
		rep(i,2*n-1) node.push_back(I);//全ての要素をinfで初期化//これは定義される演算における単位元
	}

	//k番目の値をaに変更する
	void update(int k,ll a){
		k+=n-1;
		node[k]=a;
		while(k>0){
			k=(k-1)/2;
			node[k]=min(node[2*k+1],node[2*k+2]);//これは結合則が満たされる任意の演算でok
		}
	}

	//[a,b)の最小値を求める,find(a,b+1)でよぶ
	ll find(int a,int b,int k=0,int l=0,int r=-1){
		if(r<0) r=n;
		if(r<=a || b<=l) return I;
		if(a<=l && r<=b) return node[k];
		else{
			ll vl=find(a,b,2*k+1,l,(l+r)/2);
			ll vr=find(a,b,2*k+2,(l+r)/2,r);
			return min(vl,vr);
		}
	}
};

