const int M=  2e5+5;
using namespace std;
typedef long long ll;
struct Edge
{
    int next;
    int to;
    int dis;
}edge[M*2];
int head[M],tot;
int d[M];bool vis[M];
inline void add(int from,int to,int dis){
    edge[++tot].next = head[from];
    edge[tot].to = to;
    edge[tot].dis = dis;
    head[from] = tot;
}
struct node
{
    int val,id;
    node(){}
    node(int a,int b):id(a),val(b){}
    bool operator <(node A)const{
        return val > A.val;
    }
};
void dij(int u)
{
    mmt(d,0x3f);
    mmt(vis,0);
    d[u] = 0;
    priority_queue<node> Q;
    Q.push({u,0});
    node tmp;
    while(Q.size()){
        tmp = Q.top();
        Q.pop();
        int x = tmp.id;
        if(vis[x]) continue;
        for(int i =  head[x];~i;i = edge[i].next){
            int y = edge[i].to;
            int dis = edge[i].dis;
            if(d[y] > d[x] +dis){
                d[y] = d[x] + dis;
                Q.push({y,d[y]});
            }
        }
    }
}
inline void init()
{
    mmt(head,-1);
    tot = 0;
}
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    init();
    int n,m;
    cin>>n>>m;
    int u,v,dis;
    for(int i = 1;i <= n;++i){
        add(i,i - 1,0);
    }
    for(int i = 1;i <= m;++i){
        cin>>u >> v>>dis;
        add(u,v,dis);
    }
    dij(1);
    if(d[n] == INF) cout<<-1<<endl;
    else cout<<d[n]<<endl;
}

