vector<pair<ll,ll>> g[100001];
vector<ll> ans(100001,1000000000000000000);
vector<bool> vis(100001,0);
void solve()
{   
    int n,m;
    cin>>n>>m;
    for(int i=1;i<=n;++i)
        g[i].push_back({i,0});
    for(int i=0;i<m;++i){
        int l,r; ll c;
        cin>>l>>r>>c;
        g[l].push_back({r,c});
    }
    for(int i=1;i<=n;++i)
        sort(g[i].begin(),g[i].end());
    priority_queue<pair<ll,ll>,vector<pair<ll,ll>>,greater<pair<ll,ll>>> q;
    q.push({0,1});
    ans[1]=0;
    while(!q.empty())
    {
        pair<ll,ll> v=q.top(); q.pop();
        if(vis[v.second]) continue;
        if(v.first==INT_MAX) break;
        vis[v.second]=1;
        ans[v.second]=v.first;
        int j=v.second+1;
        if(vis[n]) break;
        ll tmp=INT_MAX;
        for(int i=g[v.second].size()-1;i>=1;--i){
            tmp=min(tmp,g[v.second][i].second);
            int to=g[v.second][i].first; int from=g[v.second][i-1].first;
            for(int j=from+1;j<=to;++j)
                if(ans[j]>v.first+tmp)
                {
                    ans[j]=v.first+tmp;
                    q.push({ans[j],j});
                }
        }
    }
    if(ans[n]==1000000000000000000) cout<<-1;
    else cout<<ans[n];
}   
int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL); 
