const int N = 1e5+7, INF = 5e18;
bool live[N << 2];
int prop[N << 2], mn[N << 2];
void build(int v, int tl, int tr) {
    mn[v] = INF;
    prop[v] = INF;
    live[v] = 1;
    if (tl == tr)
        return;
    int tm = (tl + tr) >> 1;
    build(v * 2 + 1, tl, tm);
    build(v * 2 + 2, tm + 1, tr);                        
}   
void gap(int v, int x) {
    if (!live[v])
        return;

    prop[v] = min(prop[v], x);
    mn[v] = min(mn[v], x);
}   
void push(int v) {
    if (prop[v] != INF) {
        gap(v * 2 + 1, prop[v]);
        gap(v * 2 + 2, prop[v]);
        prop[v] = INF;
    }   
}   
void relax(int v) {
    live[v] = live[v * 2 + 1] || live[v * 2 + 2];
    mn[v] = min(mn[v * 2 + 1], mn[v * 2 + 2]);
}   
void upd(int v, int tl, int tr, int l, int r, int x) {
    if (tr < l || r < tl)
        return;
    if (l <= tl && tr <= r) {
        gap(v, x);
        return;
    }   
    int tm = (tl + tr) >> 1;
    push(v);
    upd(v * 2 + 1, tl, tm, l, r, x);
    upd(v * 2 + 2, tm + 1, tr, l, r, x);
    relax(v);
}   
ii get(int v, int tl, int tr) {
    //cout << "get " << tl << ' ' << tr << ' ' << mn[v] << /*' ' << live[v] << */endl;

    if (mn[v] == INF || !live[v]) {
        return mp(-1, -1);
    }
    if (tl == tr) {
        live[v] = 0;
        int ret = mn[v];
        mn[v] = INF;
        //cout << "ban " << tl << endl;
        return mp(tl, ret);
    }   
    int tm = (tl + tr) >> 1;
    push(v);
    if (mn[v * 2 + 1] == mn[v]) {
        auto t = get(v * 2 + 1, tl, tm);
        relax(v);

        //cout << "relax " << tl << ' ' << tr << ' ' << mn[v] << endl;

        if (t.f != -1)
            return t;
    }   
    if (mn[v * 2 + 2] == mn[v]) {
        auto t = get(v * 2 + 2, tm + 1, tr);
        relax(v);
        if (t.f != -1)
            return t;
    }       
    return mp(-1, -1);
}   

