using namespace std;

struct Bridge {
	int l;
	int r;
	int64_t c;
};

struct Data {
	int64_t lval;
	int64_t rval;
};
class SegTree {

public:
	SegTree(int n, int64_t idt) {
		int m = 1;
		while (m < n) m *= 2;
		this->data_ = vector<Data>(2 * m, Data({ idt, idt }));
		this->idt_ = idt;
		this->m_ = m;
	}

	int64_t query(int i) {
		int idx = i + m_ - 1;
		if (this->data_[idx].lval != this->idt_) return this->data_[idx].lval;
		while (idx != 0) {
			bool from_left = (idx & 1);
			idx = (idx - 1) / 2;
			if (!from_left) continue;
			if (this->data_[idx].rval != this->idt_) return this->data_[idx].rval;
		}

		return this->idt_;
	}

	void update(int i, int64_t v) {
		if (v < query(i)) {
			int idx = i + m_ - 1;
			this->data_[idx].rval = v;
			this->data_[idx].lval = v;

			while (idx != 0) {
				bool from_left = (idx & 1);
				idx = (idx - 1) / 2;
				if (from_left) this->data_[idx].lval = min(this->data_[idx].lval, v);
				else this->data_[idx].rval = v;
			}
		}
	}

private:
	vector<Data> data_;
	int     m_;
	int64_t idt_;
};

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n, m; cin >> n >> m;
	vector<Bridge> bs(m);
	for (auto& b : bs) {
		cin >> b.l >> b.r >> b.c;
	}

	sort(bs.begin(), bs.end(), [](auto & lhs, auto & rhs) {
		if (lhs.l != rhs.l) return lhs.l < rhs.l;
		return lhs.r < rhs.r;
	});

	SegTree segt(n + 1, INT64_MAX);
	segt.update(1, 0);
	for (auto& b : bs) {
		int64_t v = segt.query(b.l);
		if (v == INT64_MAX) {
			cout << -1 << endl;
			return 0;
		}

		segt.update(b.r, v + b.c);
	}

	int64_t v = segt.query(n);
	if (v == INT64_MAX) {
		cout << -1 << endl;
	}
	else {
		cout << v << endl;
	}

	return 0;
}

