	update(i * 2 + 1, l, (l + r) / 2, a, b, x);
	update(i * 2 + 2, (l + r) / 2, r, a, b, x);
	dat[i].x = min(dat[i * 2 + 1].x, dat[i * 2 + 2].x);
	eval(i, l, r);
