    SegmentTree<ll> seg(n, HIGHINF, 
        [&](ll i, ll j){ return min(i, j); },
        [&](ll i, ll j){ return min(i, j); });
    seg.change(0, 0);

    vll ord(m); iota(ALL(ord), 0LL);
    sort(ALL(ord), [&](ll i, ll j) {
