struct Edge {
  int dst;
  ll cost;
  Edge(int d, ll c) : dst(d), cost(c) {}
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;

void dijkstra(int s, Graph& g, vector<ll>& dist) {
  using Info = pair<ll, int>;
  // init
  dist.assign(g.size(), INFL);
  dist[s] = 0;
  priority_queue<Info, vector<Info>, greater<Info>> pq;
  pq.emplace(0, s);
  //
  // main
  while (!pq.empty()) {
    ll d = pq.top().first;
    int v = pq.top().second;
    pq.pop();
    if (dist[v] < d) continue;
    for (Edge e : g[v]) {
      if (dist[e.dst] > dist[v] + e.cost) {
        dist[e.dst] = dist[v] + e.cost;
        pq.emplace(dist[e.dst], e.dst);
      }
    }
  }
  //
}

int main() {
  int n, m;
  cin >> n >> m;

  Graph g(n);
  int l, r;
  ll c;
  rep(i, 0, m) {
    cin >> l >> r >> c;
    --l, --r;
    g[l].emplace_back(r, c);
  }
  rep(i, 0, n - 1) { g[i + 1].emplace_back(i, 0); }
  vector<ll> dist;
  dijkstra(0, g, dist);
  if (dist[n - 1] == INFL)
    cout << -1;
  else
    cout << dist[n - 1];
  return 0;
}

