ll stree[2*MAXN] ;
void init() {
     rep(i,n,2*n-1) {
        stree[i] = INFL ;
     }
     per(i,n-1,1) {
         stree[i] = min(stree[2*i], stree[2*i+1]) ;
     }
     stree[n] = 0 ;
}
void update(int l, int r, ll v) {
     l += n ;
     r += n ;
     while(l < r) {
        if(l&1) {
            stree[l] = min(stree[l], v) ;
            l++ ;
        }
        if(r&1) {
            r-- ;
            stree[r] = min(stree[r], v) ;
        }
        l /= 2 ;
        r /= 2 ;
     }
}
ll query(int l) {
   ll res = INFL ;
   l += n ;
   while(l) {
         res = min(res, stree[l]) ;
         l /= 2 ;
   }
   return res ;
}
