class Dijkstra{
public:
    struct edge{
        ll to;
        ll cost;
    };
    ll vertex;
    vector<vector<edge>> graph;
    vector<ll> dist;
    vector<ll> hist;

    Dijkstra(ll n){
        vertex = n;
        graph = vector<vector<edge>>(n);
        dist = vector<ll>(n);
        hist = vector<ll>(n,-1);
    };

    void dijkstra(ll s){
        priority_queue<pii, vector<pii>, greater<pii>> que;
        fill(dist.begin(), dist.end(), MAX_DIST);
        dist[s] = 0;
        que.push(pii(0, s));

        while (!que.empty()){
            pii p = que.top();  //cost/to
            que.pop();
            ll v = p.second;
            if (dist[v] < p.first) continue;
            for (ll i = 0; i < graph[v].size(); i++) {
                edge e = graph[v][i];
                if (dist[e.to] > dist[v] + e.cost && !(dist[e.to] == MAX_DIST && dist[v] == MAX_DIST)){
                    dist[e.to] = dist[v] + e.cost;
                    hist[e.to] = v;
                    que.push(pii(dist[e.to], e.to));
                }
            }
        }

    }

    void addEdge(ll from, ll to, ll cost) {
        edge e;
        e.to = to;
        e.cost = cost;
        graph[from].push_back(e);
    }

};


