priority_queue<pair<int, long long>, vector<pair<int, long long> >, greater<pair<int, long long> > > q;

void InitSegment(int x, int l, int r)
{
    int m;

    if(l == r)
    {
        k[l] = x;

        return;
    }

    m = (l + r) >> 1;
    InitSegment(x << 1    , l    , m);
    InitSegment(x << 1 | 1, m + 1, r);
    e[x << 1    ].push_back(make_pair(x, 0));
    e[x << 1 | 1].push_back(make_pair(x, 0));

    return;
}

void AddSegment(int x, int l, int r, int s, int t, int k, int w)
{
    int m;

    if(l > t || r < s)
        return;
    if(l >= s && r <= t)
    {
        e[x].push_back(make_pair(k, w));

        return;
    }

    m = (l + r) >> 1;
    AddSegment(x << 1    , l    , m, s, t, k, w);
    AddSegment(x << 1 | 1, m + 1, r, s, t, k, w);

    return;
}

int main(void)
{
    int n, m, l, r, w;
    int i;
    pair<int, long long> t;

    scanf("%d %d", &n, &m);
    InitSegment(1, 1, n);
    while(m --)
    {
        scanf("%d %d %d", &l, &r, &w);
        AddSegment(1, 1, n, l, r - 1, k[r], w);
    }

    for(i = 0; i < (N << 2); i ++)
        d[i] = LLONG_MAX >> 2;
    d[k[1]] = 0;
    for(q.push(make_pair(k[1], 0)); !q.empty(); )
