                if(d[e[t.first].at(i).first] > t.second + e[t.first].at(i).second)
                {
                    d[e[t.first].at(i).first] = t.second + e[t.first].at(i).second;
                    q.push(make_pair(e[t.first].at(i).first, d[e[t.first].at(i).first]));
                }
    }
    printf("%lld\n", d[k[n]] == LLONG_MAX >> 2 ? -1 : d[k[n]]);

