class query {
public:
  i64 L;
  i64 R;
  i64 C;
  friend std::istream& operator>>(std::istream& is, query& self) {
    is >> self.L >> self.R >> self.C;
    --self.L;
    return is;
  }
};

int main() {
  i64 N, M;
  std::cin >> N >> M;
  std::vector<query> queries;
  tools::read(queries, M);

  tools::dual_segtree<i64, i64> dual_segtree(
    tools::monoid<i64>(
      [](const i64& e1, const i64& e2) {
        return std::min(e1, e2);
      },
      std::numeric_limits<i64>::max()
    ),
    [](const i64& t, const i64& e) {
      return std::min(t, e);
    },
    static_cast<std::size_t>(N),
    std::numeric_limits<i64>::max()
  );
  dual_segtree.update(0, 1, 0);

  std::sort(queries.begin(), queries.end(), tools::less<query, i64>([](const query& query) { return query.L; }));
  const auto safe_sum = [](const i64& x, const i64& y) {
    if (x == std::numeric_limits<i64>::max()) return x;
    if (y == std::numeric_limits<i64>::max()) return y;
    return x + y;
  };
  for (const query& query : queries) {
    dual_segtree.update(query.L, query.R, safe_sum(dual_segtree.query(query.L), query.C));
  }

  i64 answer = dual_segtree.query(N - 1);
  if (answer == std::numeric_limits<i64>::max()) answer = -1;
  std::cout << answer << std::endl;
  return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MAX = 1e17 + 7;
const ll N = 1e5+7;

struct aa{
    ll u,d;
    bool operator < (const aa & a) const{
        return d>a.d;
    }
};

vector<aa>arr[N];

bool vis[N];
ll n,m;
ll d[N];

void Dij(){
    fill(d+1,d+n+1,MAX);
    d[1]=0;
    priority_queue<aa>Q;
    Q.push({1,0});
    while(!Q.empty()){
        aa x=Q.top();
		Q.pop();
        ll u=x.u;
        if(vis[u])continue;
        vis[u]=1;
        for(ll i=0;i<arr[u].size();i++){
            aa e=arr[u][i];
            if(d[e.u]>d[u]+e.d){
