signed main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);   //cin cout 高速化
    //cout << fixed << setprecision(10);

    int n, m; cin >> n >> m;
    W_Graph<int> G(n);
    rep(i,m) {
        int l, r, c;
        cin >> l >> r >> c;
        --l; --r;
        G[l].push_back(Edge<int>(r, c));
        G[r].push_back(Edge<int>(l, c));
        for(int j = l; j < r; ++j) {
            G[i+1].push_back(Edge<int>(i, 0));  //こうすればl~r間の全ての頂点が
                                               //重みcの辺で結ばれたことになる
        }
    }

    //dijkstra
    using p = pair<int,int>;
    priority_queue<p, vector<p>, greater<p>> que;
    vi min_dist(n+10, inf);
    min_dist[0] = 0;
    que.emplace(min_dist[0], 0);
    while(que.size()) {
        int dist;
        int index;
        tie(dist, index) = que.top();
        que.pop();
        if(dist > min_dist[index]) continue;

        for(auto edge : G[index]) {
            int new_dist = dist+edge.cost;
            if(!chmin(min_dist[edge.to], new_dist)) continue;
            que.emplace(min_dist[edge.to], edge.to);
        }
    }
    if(min_dist[n-1]!=inf) cout << min_dist[n-1] << '\n';
    else cout << "-1" << '\n';
}

