struct RangeGraph{
  vector<vector<edge>>g;
  ll n,sz;
  ll cnt;
  RangeGraph(ll n,ll m):n(n){
    sz=1;
    cnt=0;
    while(sz<n)sz <<= 1;
    g.assign(4*sz+n+m,vector<edge>());
    for(ll i=1;i<sz;i++){
      g[i].EB(2*i,0);
      g[i].EB(2*i+1,0);
      g[2*i+2*sz].EB(i+2*sz,0);
      g[2*i+1+2*sz].EB(i+2*sz,0);
    }
    for(ll i=0;i<n;i++){
      g[i+sz].EB(i+4*sz,0);
      g[i+4*sz].EB(i+3*sz,0);
    }
  }
  void add_edge(ll l1,ll r1,ll l2,ll r2,ll w){//[l1,r1)->[l2,r2)
    auto v=range(l1,r1);
    ll via=4*sz+n+cnt;
    for(auto z:v)g[z+2*sz].EB(via,w);
    v=range(l2,r2);
    for(auto z:v)g[via].EB(z,0);
    cnt++;
  }
  vector<ll>range(ll l,ll r){
    vector<ll>ret;
    l+=sz,r+=sz;
    while(l!=r){
      if(l&1)ret.PB(l++);
      if(r&1)ret.PB(--r);
      l>>=1,r>>=1;
    }
    return ret;
  };
  ll add(){
    return 4*sz;
  }
};
ll MAX_V = 1e6 + 5;
vector<ll> dist(MAX_V);
void dijkstra(ll s,vector<vector<edge>>&g) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(dist.begin(),dist.begin()+g.size(), INF);
    dist[s] = 0;
    que.emplace(0, s);
    while (!que.empty()) {
        P p = que.top();
        que.pop();
        ll v = p.second;
        if (dist[v] < p.first) continue;
        for(auto e:g[v]) {
            if (dist[e.to] > dist[v] + e.cost) {
                dist[e.to] = dist[v] + e.cost;
                que.emplace(dist[e.to], e.to);
            }
        }
    }
}
