using namespace std;

const int max_n = 100111;
const long long inf = 1000111222000111222LL;

struct tree {
    long long a[4 * max_n];

    tree() {
        for (int i = 0; i < 4 * max_n; ++i) {
            a[i] = inf;
        }
    }

    void update(int v, int tl, int tr, int l, int r, long long value) {
        if (tl == l && tr == r) {
            //cout << "upd " << v << " " << l << " " << r << ": " << value << endl;
            a[v] = min(a[v], value);
            return;
        }
        int mid = (tl + tr) / 2;
        if (r <= mid) {
            update(2 * v, tl, mid, l, r, value);
        } else if (l > mid) {
            update(2 * v + 1, mid + 1, tr, l, r, value);
        } else {
            update(2 * v, tl, mid, l, mid, value);
            update(2 * v + 1, mid + 1, tr, mid + 1, r, value);
        }
    }

    long long get(int v, int l, int r, int pos) {
        //cout << v << " " << l << " " << r << " " << pos << ": " << a[v] << endl;
        if (l == r) {
            return a[v];
        }
        long long res = a[v];
        int mid = (l + r) / 2;
        if (pos <= mid) {
            res = min(res, get(2 * v, l, mid, pos));
        } else {
            res = min(res, get(2 * v + 1, mid + 1, r, pos));
        }
        return res;
    }
};

struct edge {
    int l, r, c;

    bool operator < (const edge &e) const {
        return l < e.l;
    }
};

int n, m;
tree dist;
edge e[max_n];

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; ++i) {
        scanf("%d%d%d", &e[i].l, &e[i].r, &e[i].c);
        --e[i].l;
        --e[i].r;
    }
    sort(e, e + m);
    dist.update(1, 0, n - 1, 0, 0, 0);
    int pos = 0;
    for (int i = 0; i < n; ++i) {
        long long d = dist.get(1, 0, n - 1, i);
        //cout << "#" << i << ": " << d << endl;
        if (d == inf) {
            continue;
        }
        while (pos < m && e[pos].l <= i) {
            if (e[pos].r >= i) {
                dist.update(1, 0, n - 1, i, e[pos].r, d + e[pos].c);
            }
            ++pos;
        }
    }
    long long ans = dist.get(1, 0, n - 1, n - 1);
    if (ans == inf) {
        ans = -1;
    }
    cout << ans << "\n";
    return 0;
}

