	int l;
	int r;
	int c;
};

struct Data {
	int64_t lval;
	int64_t rval;
};
class SegTree {

public:
	SegTree(int n, int64_t idt) {
		int m = 1;
		while (m < n) m *= 2;
		this->data_ = vector<Data>(2 * m, Data({ idt, idt }));
		this->idt_ = idt;
		this->m_ = m;
	}

	int64_t query(int i) {
		int idx = i + m_ - 1;
		if (this->data_[idx].lval != this->idt_) return this->data_[idx].lval;
		while (idx != 0) {
			bool from_left = (idx & 1);
			idx = (idx - 1) / 2;
			if (!from_left) continue;
			if (this->data_[idx].rval != this->idt_) return this->data_[idx].rval;
		}

		return this->idt_;
	}

	void update(int i, int64_t v) {
		if (v < query(i)) {
			int idx = i + m_ - 1;
			this->data_[idx].rval = v;
			this->data_[idx].lval = v;

			while (idx != 0) {
				bool from_left = (idx & 1);
				idx = (idx - 1) / 2;
				if (from_left) this->data_[idx].lval = v;
				else this->data_[idx].rval = v;
			}
		}
	}

private:
	vector<Data> data_;
	int     m_;
	int64_t idt_;
};

