    l--, r--;
    if (i != 0) G[i].emplace_back(i - 1, 0);
    G[l].emplace_back(r, c);
  }
  auto dist = dijkstra(G, 0);

  if (dist[n - 1] == numeric_limits<lint>::max()) {
    cout << -1 << endl;
  } else {
    cout << dist[n - 1] << endl;
  }

  return 0;
}

