struct ban
{
    long long minu;
    int mini;
    long long laz;
    ban()
    {
        minu = INF;
        mini = -1;
        laz = INF;
    }
    ban(int i)
    {
        minu = INF;
        mini = i;
        laz = INF;
    }
};

ban t[N * 4];

void shi(int pos)
{
    t[pos * 2].minu = min(t[pos * 2].minu, t[pos].laz);
    t[pos * 2].laz = min(t[pos * 2].laz, t[pos].laz);
    t[pos * 2 + 1].minu = min(t[pos * 2 + 1].minu, t[pos].laz);
    t[pos * 2 + 1].laz = min(t[pos * 2 + 1].laz, t[pos].laz);
    t[pos].laz = INF;
}

ban mer(const ban& l, const ban& r)
{
    ban res;
    if (l.mini == -1 && r.mini == -1)
        return res;
    if (l.mini == -1)
    {
        res.mini = r.mini;
        res.minu = r.minu;
    }
    else if (r.mini == -1)
    {
        res.mini = l.mini;
        res.minu = l.minu;
    }
    else if (l.minu < r.minu)
    {
        res.mini = l.mini;
        res.minu = l.minu;
    }
    else
    {
        res.mini = r.mini;
        res.minu = r.minu;
    }
    return res;
}

void bil(int tl, int tr, int pos)
{
    if (tl == tr)
    {
        t[pos] = ban(tl);
        return;
    }
    int m = (tl + tr) / 2;
    bil(tl, m, pos * 2);
    bil(m + 1, tr, pos * 2 + 1);
    t[pos] = mer(t[pos * 2], t[pos * 2 + 1]);
}

void ubd(int tl, int tr, int l, int r, long long y, int pos)
{
    if (l > r)
        return;
    if (tl == l && tr == r)
    {
        t[pos].minu = min(t[pos].minu, y);
        t[pos].laz = min(t[pos].laz, y);
        return;
    }
    shi(pos);
    int m = (tl + tr) / 2;
    ubd(tl, m, l, min(m, r), y, pos * 2);
    ubd(m + 1, tr, max(m + 1, l), r, y, pos * 2 + 1);
    t[pos] = mer(t[pos * 2], t[pos * 2 + 1]);
}

