        es[b].push_back({a,c});
    }
    rep(i,N - 1){
        es[i + 1].push_back({i,0});
    }
    priority_queue<P,vector<P>,greater<P>> que;
    que.push(P(0,0));
    vector<ll> dist(N,INF);
    dist[0] = 0;
    while(que.size()){
        P p = que.top();
        que.pop();
        if(dist[p.sec] < p.fir)continue;
        for(auto x : es[p.sec]){
            if(chmin(dist[x.to],dist[p.sec] + x.cost)){
                que.push(P(dist[x.to],x.to));
            }
        }
    }
    if(dist[N - 1] == INF)cout << "-1\n";
    else cout << dist[N - 1] << "\n";
}

