const int MAX = 1e5 + 10;
int N, M;
int L[MAX], R[MAX]; // [ L[i], R[i] )
LL C[MAX];
VT<pair<LL, int>> edges[MAX];
int indexes[MAX];
LL dist[MAX];

int main(void) {
    cin >> N >> M;
    REP(i, M) {
        cin >> L[i] >> R[i] >> C[i];
        L[i]--;
        edges[L[i]].EB(C[i], R[i]);
    }
    REP(i, N) {
        SORT(edges[i]);
    }

    fill(dist, dist + MAX, LLINF);

    priority_queue<pair<LL, int>, VT<pair<LL, int>>, greater<pair<LL, int>>> pq;
    pq.emplace(0, 0);
    dist[0] = 0;
    while (!pq.empty()) {
        const auto cur = pq.top();
        pq.pop();
        if (dist[cur.second] < cur.first) continue;

        int nxt = cur.second + 1;
        auto itr = begin(edges[cur.second]);
        while (nxt < N && itr != end(edges[cur.second])) {
            if (edges[nxt].empty() && nxt < N - 1) {
                nxt++;
                continue;
            }
            while (itr != end(edges[cur.second]) && itr->second <= nxt) {
                itr++;
            }
            if (itr == end(edges[cur.second])) break;

            const auto nxt_cost = cur.first + itr->first;
            if (nxt_cost < dist[nxt]) {
                dist[nxt] = nxt_cost;
                pq.emplace(nxt_cost, nxt);
            }

            nxt++;
        }
    }

    // REP(i, N) {
    //     cerr << i + 1 << " " << dist[i] << endl;
    // }

    cout << (dist[N - 1] == LLINF ? -1 : dist[N - 1]) << endl;
