void dijkstra(vi& d, vvi& es, int s, map<pii,int>& cost) {
    int N = es.size();
    d = vi(N, INF);

    d[s] = 0;

    priority_queue<pii, vector<pii>, greater<pii>> pq;

    pq.push(pii(d[s], s));
    vb vis(N, false);

    while (!pq.empty()) {
        // get the smallest(nearest) element
        pii p = pq.top(); pq.pop();

        int i = p.second;
        vis[i] = true;

        for (int t : es[i]) {
            if (vis[t]) continue;

            if (p.first + cost[pii(i, t)] < d[t]) {
                d[t] = p.first + cost[pii(i, t)];
                pq.push(pii(d[t], t));
            }
        }
    }
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int N,M; cin>>N>>M;
  vi L(M),R(M),C(M);
  REP(i,M) {
    cin>>L[i]>>R[i]>>C[i];
    L[i]--;R[i]--;
  }

  vvi es(N);
  map<pii, int> cost;

  REP(i,M) {
    int l = L[i], r = R[i];
    if (cost.count(pii(l,r)) == 0) {
      es[l].push_back(r);
      cost[pii(l,r)] = C[i];
    } else {
      cost[pii(l,r)] = min(cost[pii(l,r)], C[i]);
    }

    for(int i = l; i < r; i++) {
      if (cost.count(pii(i+1,i)) == 0) {
        es[i+1].push_back(i);
        cost[pii(i+1,i)] = 0;
      }
    }
  }

  vi dist;
  dijkstra(dist, es, 0, cost);

  int ans = dist[N-1] >= INF ? -1 : dist[N-1];
  cout << ans << endl;

  return 0;
}

