template <typename T, typename OP>
class LazySegmentTree {
 public:
    using MERGE = function<T(T,T)>;
    using APPLY = function<T(T,OP)>;
    using MERGE_OP = function<OP(OP,OP)>;

    MERGE merge_data_func;
    APPLY apply_lazy_func;
    MERGE_OP merge_lazy_func;
    T elem_ident;
    OP op_ident;
    std::vector<T> data;
    std::vector<OP> lazy;
    int n, height;

    LazySegmentTree(MERGE f, APPLY g, MERGE_OP h, T elem_ident, OP op_ident)
        : merge_data_func(f), apply_lazy_func(g), merge_lazy_func(h),
          elem_ident(elem_ident), op_ident(op_ident) {
    }

    void init(int n_temp) {
        n = 1; height = 0;
        while (n < n_temp) { n <<= 1; ++height; }
        data.assign(2*n, elem_ident);
        lazy.assign(2*n, op_ident);
    }

    void build(const std::vector<T> &v){
        int n_temp = v.size();
        init(n_temp);
        std::copy(v.begin(), v.end(), data.begin()+n);
        for (int i=n-1; i>0; --i) {
            data[i] = merge_data_func(data[(i << 1)|0], data[(i << 1)|1]);
        }
    }

    inline T reflect_lazy(int k){
        if (lazy[k] == op_ident) {
            return data[k];
        } else {
            T applied = apply_lazy_func(data[k], lazy[k]);
            return applied;
        }
    }

    inline void eval(int k){
        if (lazy[k] == op_ident) return;
        lazy[(k << 1)|0] = merge_lazy_func(lazy[(k << 1)|0], lazy[k]);
        lazy[(k << 1)|1] = merge_lazy_func(lazy[(k << 1)|1], lazy[k]);
        data[k] = reflect_lazy(k);
        lazy[k] = op_ident;
    }

    inline void eval_down(int k) {
        for (int i=height; i>0; --i) {
            eval(k >> i);
        }
    }

    inline void merge_up(int k) {
        while (k >>= 1) {
            data[k] = merge_data_func(reflect_lazy((k << 1)|0), reflect_lazy((k << 1)|1));
        }
    }

    void update(int a, int b, OP x) {
        eval_down(a += n);
        eval_down(b += n-1);
        for (int l=a,r=b+1; l<r; l>>=1,r>>=1) {
            if (l&1) { lazy[l] = merge_lazy_func(lazy[l], x); ++l; }
            if (r&1) { --r; lazy[r] = merge_lazy_func(lazy[r], x); }
        }
        merge_up(a);
        merge_up(b);
    }

    void set_val(int a, T x) {
        eval_down(a += n);
        data[a] = x;
        lazy[a] = op_ident;
        merge_up(a);
    }

    T query(int a, int b) {
        eval_down(a += n);
        eval_down(b += n-1);
        T vl = elem_ident, vr = elem_ident;
        for (int l=a,r=b+1; l<r; l>>=1,r>>=1) {
            if (l & 1) {
                vl = merge_data_func(vl, reflect_lazy(l++));
            }
            if (r & 1) {
                vr = merge_data_func(reflect_lazy(--r), vr);
            }
        }
        T merged = merge_data_func(vl, vr);
        return merged;
    }

    void desc() {
    }
};

const int INF = INT_MAX;
struct _LazySegmentTree {
private:
    int n;
    vector<int> node, lazy;
    vector<bool> lazyFlag;

public:
    _LazySegmentTree(vector<int> v) {
        int sz = (int)v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1, INF);
        lazyFlag.resize(2*n-1, false);

        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = min(node[i*2+1], node[i*2+2]);
    }

    void lazyEvaluate(int k, int l, int r) {
        if(lazyFlag[k]) {
            node[k] = lazy[k];
            if(r - l > 1) {
                lazy[k*2+1] = lazy[k*2+2] = lazy[k];
                lazyFlag[k*2+1] = lazyFlag[k*2+2] = true;
            }
            lazyFlag[k] = false;
        }
    }

    void update(int a, int b, int x, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        lazyEvaluate(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            lazy[k] = x;
            lazyFlag[k] = true;
            lazyEvaluate(k, l, r);
        }
        else {
            update(a, b, x, 2*k+1, l, (l+r)/2);
            update(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = min(node[2*k+1], node[2*k+2]);
        }
    }

    int find(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        lazyEvaluate(k, l, r);
        if(b <= l || r <= a) return INF;
        if(a <= l && r <= b) return node[k];
        int vl = find(a, b, 2*k+1, l, (l+r)/2);
        int vr = find(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};

ll solve(int N, int M, vi& l, vi& r, vi& c) {
    map<int, set<ii>> mp;
    rep(i,M){
        mp[ l[i] ].insert( ii(r[i], c[i]) );
    }


    using ll2 = pair<ll,ll>;

    auto f = [](ll2 a, ll2 b){ return ll2(min(a.first, b.first), a.second + b.second); };
    auto g = [](ll2 a, ll b){ return ll2(min(a.first, b), a.second); };
    auto h = [](ll a, ll b){ return min(a,b); };

    LazySegmentTree<ll2,ll> st(f, g, h, ll2(INT_MAX,0), INT_MAX);

    st.build(vector<ll2>(N+1, ll2(INT_MAX,1)));
    st.desc();


    for(int i=1; i<N; ++i){
        int x = (i==1) ? 0 : st.query(i, i+1).first;
        if (x == INT_MAX) return -1;

        for(ii p: mp[i]) {
            st.update(i+1, p.first+1, x + p.second);
        }
    }
    return st.query(N, N+1).first;
}

