const ll INF = 1e17;
template<class T>
class SegTree{
    public:
        ll n;
        T g;
        vector<T> data;

        SegTree(vector<T> a, T _g){
            g = _g;
            for (n = 1; n < (T)a.size(); n *= 2);
            data.resize(n * 2, g);
        }

        T rec(int l, int r, int node, int node_l, int node_r, T val) {
            if (node_r <= l || node_l >= r) return g;
            if (node_l >= l && node_r <= r) return data[node] = min(data[node], val);
            ll mid = (node_l + node_r) / 2;
            return min( rec(l, r, node * 2, node_l, mid, val), rec(l, r, node * 2 + 1, mid, node_r,val));
        }

        void query(int l,int r, T val){
            rec(l,r,1,0,n,val);
        }

        T get(ll index){
            T res = data[index += n];
            for(;index /= 2;)
                res = min(res, data[index]);
            return res;
        }
};



