int n, m, i, j;
struct node {
	int l, r;
	long long c;
} b[200001*4],a[200001];
bool cmp (node a,node b)
{
	return a.l<b.l;
}
void build(int x,int l,int r)
{
	b[x].l=l;
	b[x].r=r;
	b[x].c=1E18;
	if (l==r) {
		if (l==1) b[x].c=0;
		return;
	}
	int mid=l+r>>1;
	if (l<=mid) build(x*2,l,mid);
	if (mid+1<=r) build(x*2+1,mid+1,r);
}
long long query(int x,int y)
{
	if (b[x].l==b[x].r) return b[x].c;
	long long ans=b[x].c;
	if (y<=b[x*2].r) {
		ans=min(ans,query(x*2,y));
	}
	else {
		ans=min(ans,query(x*2+1,y));
	}
	return ans;
}
void update(int x,long long y,int l,int r)
{
	if (l<=b[x].l&&b[x].r<=r) {
		b[x].c=min(b[x].c,y);
		return;
	}
	if (l<=b[x*2].r) update(x*2,y,l,r);
	if (r>=b[x*2+1].l) update(x*2+1,y,l,r);
}
