		scanf("%d%d%lld",&a[i].l,&a[i].r,&a[i].c);
	}
	sort(a+1,a+m+1,cmp);
	build(1,1,n);
	for (i=1; i<=m; ) {
		j=i;
		long long t=query(1,a[i].l);
		while (a[j].l==a[i].l&&j<=m) {
			update(1,t+a[j].c,a[j].l+1,a[j].r);
			j++;
		}
		i=j;
	}
	printf("%lld\n",query(1,n)==1E18?-1:query(1,n));
	return 0;
}

