void solver::run(){
    ll M;
    is >> N >> M;
    if(!is) return;
    vector<tuple<ll, ll, ll>> lcb(M);
    for (int i = 0; i < M; ++i) {
        ll a, b, c;
        is >> a >> b >> c;
        lcb[i] = tie(a, c, b);
    } // end i
    sort(ALL(lcb));
    min_queue<tuple<ll, ll>> drq;
    drq.emplace(0, 1);
    for (auto &&lll : lcb) {
        ll li, ci, ri;
        tie(li, ci, ri) = lll;
        if(ri < get<1>(drq.top())) continue;
        while(li > get<1>(drq.top())){
            drq.pop();
            if(drq.empty()){
                os << -1 << endl;
                return;
            }
        }
        ll d = get<0>(drq.top()) + ci;
        drq.emplace(d, ri);
    } // end lll
    ll d, p;
    if(drq.empty()){
        os << -1 << endl;
        return;
    }
    tie(d, p) = drq.top();
    while(p < N){
        drq.pop();
        if(drq.empty()){
            os << -1 << endl;
            return;
        }
        tie(d, p) = drq.top();
    }
    os << d << endl;

}

