    for (int y = 0; y < m; y++) {
        for (int x = 1; x < n; x++) {
            dp[y][x] = LONG_LONG_MAX;
        }
    }

    auto f = [](const Edge &a, const Edge &b) {
        if (a.l < b.l) {
            return true;
        } else if (a.l > b.l) {
            return false;
        } else {
            return a.r < b.r;
        }
