int64 getmin(int r)
{
	int64 result = inf;
	for (; r >= 0; r = (r & (r + 1)) - 1)
		result = min(result, t[r]);
	return result;
}

void update(int i, int64 val)
{
	for (; i < n; i = (i | (i + 1)))
		t[i] = min (t[i], val);
}

