template<class T>
class segment_tree{
	static const int N_MAX=1e5+10;
	int n;
	T dat[2*N_MAX];

	T query(int l,int r,int a,int b,int u){
		if(l<=a && b<=r) return dat[u];

		T res=INF;
		int c=(a+b+1)/2;
		if(l<c && a<r) res=min(res,query(l,r,a,c,2*u));
		if(l<b && c<r) res=min(res,query(l,r,c,b,2*u+1));
		return res;
	}

public:
	void build(int N,T val){
		for(n=1;n<N;n*=2);
		rep(u,2*n) dat[u]=val;
	}

	void update(int u,T v){
		u+=n;
		dat[u]=min(dat[u],v);
		for(u/=2;u>=1;u/=2) dat[u]=min(dat[2*u],dat[2*u+1]);
	}

	T query(int l,int r){ return query(l,r,0,n,1); }
};

