	for(int i=0;i<m;i++)
	{
		l[i]=lower_bound(itvs.begin(),itvs.end(),make_pair(l[i],0))-itvs.begin();
		st[l[i]].push_back(i);
		r[i]=lower_bound(itvs.begin(),itvs.end(),make_pair(r[i],1))-itvs.begin();
//		cout<<i<<" "<<l[i]<<" "<<r[i]<<endl;
	}
//	system("pause");
	memset(tree.bit,0x3f,sizeof(tree.bit));
	tree.add(itvs.size(),0);
//	cout<<tree.sum(itvs.size())<<endl;
	ll ans=linf;
	for(int i=0;i<itvs.size();i++)
	{
		int pos=itvs[i].first;
		int op=itvs[i].second;
	//	cout<<i<<" "<<pos<<" "<<op<<endl; 
		if(!i&&pos!=1)
		{
			printf("-1\n");
			return 0;
		}
		if(op==0)
		{
			ll val=tree.sum(itvs.size()-i);
			if(val>=linf)continue;
		//	cout<<itvs.size()<<" "<<(itvs.size()-i)<<" "<<val<<endl;
			for(int j=0;j<st[i].size();j++)
			{
				int rht=r[st[i][j]];
			//	cout<<"add "<<(itvs.size()-rht+1)<<" "<<val+c[st[i][j]]<<" "<<st[i][j]<<endl;
				tree.add(itvs.size()-rht+1,val+c[st[i][j]]);
			}
		}
		else
		{
			if(pos==n)
			{
				ans=min(ans,tree.sum(itvs.size()-i+1));
			}
		}
	}
	if(ans==linf)ans=-1;
	printf("%lld\n",ans);
	return 0;
}

