            if(dist[u] > dist[v] + cost) {
                dist[u] = dist[v] + cost;
                prQ.push(make_pair(u, dist[u]));
            }
        }
    }

    if(dist[n-1] == INF) {
        out(-1);
    }
    else {
        out(dist[n-1]);
