  cin >> N >> M;

  VL dist(N, INF);

  auto fm = [](ll a, ll b) { return min(a, b); };
  auto fa = [](ll &a, ll b) { a = min(a, b); };
  auto fl = [](ll &a, ll b) { a = min(a, b); };
  LazySegTree<ll, ll> st(N + 1, fm, fa, fl, INF, INF);
  st.update(0, 1, 0);

