// イベントソートのようなイメージ
void solve3() {
  ll N, M;
  cin >> N >> M;

  V<VPL> ls(N);  // ls[i]: i を左端とする辺 (to, cost)
  V<VPL> rs(N);  // rs[i]: i を右端とする辺 (from, cost)

  rep(i, M) {
    ll l, r, c;
    cin >> l >> r >> c;
    l--, r--;
    ls[l].push_back(PL(r, c));
    rs[r].push_back(PL(l, c));
  }

  VL dist(N, INF);
  dist[0] = 0;
  multiset<ll> costs;

  rep(i, N) {
    if (!costs.empty()) {
      dist[i] = *costs.cbegin();
    }

    if (dist[i] != INF) {
      for (auto e : ls[i]) {
        costs.insert(dist[i] + e.se);
      }
    }

    for (auto e : rs[i]) {
      costs.erase(dist[e.first] + e.se);
    }
  }

  ll res = dist[N - 1] == INF ? -1 : dist[N - 1];
  cout << res << endl;
}

