int main(){
    using namespace std;
    unsigned long N, M;
    cin >> N >> M;
    vector<pair<pair<unsigned long, unsigned long>, unsigned long>> q(M);
    for(auto& i : q){
        cin >> i.first.second >> i.first.first >> i.second;
        --i.first.second;
        --i.first.first;
    }
    sort(q.begin(), q.end());
    vector<unsigned long> segtree(2 * N, numeric_limits<unsigned long>::max() / 3);
    segtree[N] = 0;
    const auto& chmin = [](auto& i, auto j){i = min(i, j);};
    const auto& range_add = [&segtree, &N, &chmin](unsigned long r, unsigned long l, unsigned long a){
        r += N;
        l += N + 1;
        while(r < l){
            if(r & 1){
                chmin(segtree[r], a);
                ++r;
            }
            if(l & 1){
                --l;
                chmin(segtree[l], a);
            }
            r >>= 1;
            l >>= 1;
        }
    };
    const auto& point_fold = [&segtree, &N, &chmin](unsigned long r) -> unsigned long {
        unsigned long ret{numeric_limits<unsigned long>::max()};
        r += N;
        while(r){
            chmin(ret, segtree[r]);
            r >>= 1;
        }
        return ret;
    };
    const auto& range_fold = [&segtree, &N, &chmin, &point_fold](unsigned long r, unsigned long l) -> unsigned long {
        unsigned long ret{min(point_fold(r), point_fold(l))};
        r += N;
        l += N + 1;
        while(r < l){
            if(r & 1){
                chmin(ret, segtree[r]);
                ++r;
            }
            if(l & 1){
                --l;
                chmin(ret, segtree[l]);
            }
            r >>= 1;
            l >>= 1;
        }
        return ret;
    };
    constexpr unsigned long lim = numeric_limits<unsigned long>::max() / 7;
    for(const auto& i : q){
        auto k = range_fold(i.first.second, i.first.first);
        range_add(i.first.second, i.first.first, (k > lim ? k : k + i.second));
    }
    const auto ans = point_fold(N - 1);
    cout << static_cast<long>(ans > lim ? -1 : ans) << endl;
    return 0;
}

