using namespace std;

const long long INF = 1e18;

struct RMinQ{
private:
  int n;
  vector<long long> data;
public:
  RMinQ(vector<long long> V){
    int sz = V.size();
    n = 1;
    while(n < sz) n *= 2;
    data.resize(2*n-1,INF);
    for(int i = 0; i < sz; ++i) data[n-1+i] = V[i];
    for(int i = n-2; i >= 0; --i) data[i] = min(data[2*i+1],data[2*i+2]);
  }
  void update(int idx, long long val){//0-indexed
    idx += n-1;
    if(data[idx] <= val) return;
    data[idx] = val;
    while(idx > 0){
      idx = (idx-1)/2;
      data[idx] = min(data[2*idx+1],data[2*idx+2]);
    }
  }
  long long get_min(int l, int r){//[l,r)の区間の最小値
    long long ret = INF;
    l += n-1, r += n-1;
    while(l < r){
      if((l&1) == 0){
        ret = min(ret,data[l]);
      }
      if((r&1) == 0){
        ret = min(ret,data[r-1]);
      }
      l /= 2;
      r = (r-1)/2;
    }
    return ret;
  }
};

int main(){
  int N, M;
  cin >> N >> M;
  vector<long long> L(M), R(M), C(M);
  vector<int> I(M);
  for(int i = 0; i < M; ++i){
    I[i] = i;
    cin >> L[i] >> R[i] >> C[i];
    --L[i],--R[i];
  }
  sort(I.begin(), I.end(), [&](int a, int b){ return R[a] < R[b]; });
  vector<long long> init(N,INF);
  init[0] = 0;
  RMinQ rmq(init);
  for(auto idx : I){
    int l = L[idx], r = R[idx];
    long long d = rmq.get_min(l,r+1) + C[idx];
    rmq.update(r,d);
  }
  long long ans = rmq.get_min(N-1,N);
  if(ans >= INF) cout << -1 << endl;
  else cout << ans << endl;
}

