class Edge{
public:
    int to;
    long long cost;
    Edge(int v, long long c = 1): to(v), cost(c){}
    ~Edge(){}
    bool operator<(const Edge& e) const{return cost < e.cost;}
};

// Dijkstra's method
// solve minimum distances from root to each vertex
void Dijkstra(
        const std::vector<std::vector<Edge> >& edge,
        std::vector<long long>& dist,
        const int root = 0)
{
    using Pair = std::pair<long long, int>;
    const int V = edge.size();
    const long long infty = 1e+18;

    // initialize
    for(int i=0; i<V; i++) dist[i] = infty;

    std::priority_queue<Pair, std::vector<Pair>, std::greater<Pair> > pq;
    pq.emplace(0, root);

    // update
    while(!pq.empty()){
        long long d = pq.top().first;
        int tmp = pq.top().second;
        pq.pop();

        if(dist[tmp] <= d) continue; // not minimum
        dist[tmp] = d;

        for(const Edge& e: edge[tmp]) pq.emplace(dist[tmp] + e.cost, e.to);
    }
}

int main()
{
    int N, M;
    cin >> N >> M;
    Vvec<Edge> graph(N);
    for(int i=0; i<M; i++){
        int u, v; ll c;
        cin >> u >> v >> c; u--; v--;
        graph[u].emplace_back(v, c);
    }
    for(int i=0; i<N-1; i++) graph[i+1].emplace_back(i, 0);

    vector<ll> dist(N, 0);
    Dijkstra(graph, dist, 0);

    if(dist[N-1]>1e17) cout << -1 << endl;
    else cout << dist[N-1] << endl;
}

