        pq.pop();
        int u = k.v;
        if(vis[u]) continue;
        vis[u] = true;
        for(int i = 0 ; i < edge[u].size() ; i++) {
            int v = edge[u][i].v;
            int cost = edge[u][i].cost;
            if(!vis[v] && dist[v] > dist[u] + cost) {
