      auto it = rs.upper_bound(mp(r, -1LL)); // Use dummy cost -1 to search all r
      if (it == rs.end()) { // *it > the last of rs
        rs.emplace(r, c);
      } else {
        if (r == (*it).fr) { // same with *it
          rs.erase(it);
          rs.emplace(r, c);
        } else {
          rs.emplace(r, c);
        }
      }
      continue;
    }

    // TODO(south37) consider other case
