      ll new_c = (*it).sc + c;

      auto rit = rs.upper_bound(mp(r, -1LL));
      if (rit == rs.end()) {
        rs.emplace(r, new_c);
      } else {
        if (r == (*rit).fr) { // same with *rit
          if (new_c < (*rit).sc) {
            rs.erase(rit);
            rs.emplace(r, new_c);
          }
        } else { // r < *rit
          if (new_c < (*rit).sc) {
            rs.emplace(r, new_c);
          }
        }
      }
    }
  }

  // Now, all distance is calculated.
  if (rs.size() > 0) {
    ll r, c;
    tie(r, c) = *(--rs.end());
    if (r == n) {
