        l2r[l].push_back(r);
        l2c[l].push_back(c);
    }

    SegmentTree<ll> seg;
    seg.init(n);
    seg.update(0, 0);

    REP(i,n-1){
        ll x = seg.query(i, n);
        if (x == INF){
            cout << -1 << endl;
            return 0;
        }
        REP(j,l2r[i].size()){
            int r = l2r[i][j] - 1;
            ll c = l2c[i][j];
            if (seg.query(r, r + 1) > x + c){
                seg.update(r, x + c);
            }
        }
    }
    ll ans = seg.query(n - 1, n);
    if (ans == INF) ans = -1;
    cout << ans << endl;

    return 0;
}

