class Dijkstra {
private:
    struct Edge {
        int to;
        int cost;
    };
    // G[i]: vector of Edges connected to Edge i.
    vector<vector<Edge>> G;

public:
    int n;
    // d[i]: minimum cost to visit Edge i.
    vector<int> d;

    explicit Dijkstra(int size) {
        n = size;
        G.resize(n, vector<Edge>());
        d.resize(n, INF);
    }

    // `from` and `to` must be 0-indexed.
    void add(int from, int to, int cost) {
        Edge e = {to, cost};
        G[from].push_back(e);
    }

    void dijkstra(int start) {
        priority_queue <PII, vector<PII>, greater<PII>> pq;
        // vector of { minimum cost to Edge i, Edge i}
        d[start] = 0;
        pq.push({0, start});
        while (!pq.empty()) {
            PII p = pq.top();
            pq.pop();
            if (d[p.second] < p.first) continue;
            for (auto &&e : G[p.second]) {
                if (d[e.to] > d[p.second] + e.cost) {
                    d[e.to] = d[p.second] + e.cost;
                    pq.push({d[e.to], e.to});
                }
            }
        }
    }
};

