int s;
vector<int> dat, lazy;

void init(int n_) {
	s = 1;
	while (s < n_)s *= 2;
	dat.resize(2 * s - 1);
	dat[s - 1] = 0;
	for (int i = s; i < 2 * s - 1; i++)dat[i] = INF;
	for (int i = s - 2; i >= 0; i--)dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);
	lazy.resize(2 * s - 1, INF);
}

void eval(int k, int l, int r) {
	if (lazy[k] != INF) {
		dat[k] = min(dat[k], lazy[k]);
		if (r - l > 1) {
			lazy[2 * k + 1] = min(lazy[k], lazy[2 * k + 1]);
			lazy[2 * k + 2] = min(lazy[k], lazy[2 * k + 2]);
		}
		lazy[k] = INF;
	}
}

void add(int a, int b, int x, int k = 0, int l = 0, int r = -1) {
	if (r < 0)r = s;
	if (r <= a || b <= l)return;
	eval(k, l, r);
	if (a <= l && r <= b) {
		lazy[k] = min(lazy[k], x);
		eval(k, l, r);
	}
	else {
		add(a, b, x, 2 * k + 1, l, (l + r) / 2);
		add(a, b, x, 2 * k + 2, (l + r) / 2, r);
		dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
	}
}

int query(int a, int b, int k = 0, int l = 0, int r = -1) {
	if (r < 0)r = s;
	if (r <= a || b <= l)return INF;
	eval(k, l, r);
	if (a <= l && b <= r)return dat[k];
	int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
	int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
	return min(vl, vr);
}

int n, m;
vector<P> vec[100010];

int solve() {
	init(n);
	for (int i = 1; i < n; i++) {
		int k = query(i - 1, i);
		for (int j = 0; j < (int)vec[i].size(); j++) {
			add(i, vec[i][j].first, k + vec[i][j].second);
		}
	}
	int res = query(n - 1, n);
	if (res == INF)return -1;
	else return res;
}

