const ll MAX = (1ll << 59);

ll dijkstra(auto& graph){
  int n = graph.size();
  vector<ll> dist(n, MAX);
  vector<bool> fin(n, false);
  priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;

  int turn = 0;
  pq.push(make_pair(0ll, 0));
  do{
    auto s = pq.top();
    pq.pop();
    fin[s.second] = true;
    for(auto v : graph[s.second]){
      if(fin[v.second]) continue;
      dist[v.second] = min(s.first + v.first, dist[v.second]);
      pq.push(make_pair(dist[v.second], v.second));
    }
    turn++;
  }while(!pq.empty() && !fin[n - 1] && turn < 1e6);

  return dist[n - 1];
}

