        a--;b--;
        edge e = {b, c};
        G[a].push_back(e);
    }
    for (int i = V-1; i > 0; --i) {
        edge e = {i-1,0};
        G[i].push_back(e);
    }
    dijkstra(0);
    if(d[V - 1] == INF){
        cout << -1 << endl;
        return 0;
    }
    cout << d[V - 1] << endl;
}

