int n, m, dist[N];
bool vis[N], done[N];
vector< pair<int, pair<int, int> > > a;
vector< pair<int, int> > start[N];
priority_queue< pair<int, int>, vector<pair<int,int> >, greater<> > Q;

void solve() {
    int last = 0;
    f(i, n + 4) dist[i] = inf, vis[i] = done[i] = false;
    dist[0] = 0;
    vis[0] = true;
    done[0] = true;
    for(auto &it: start[0]) {
        Q.push(it);
        dist[it.second] = it.first;
    }
    while(!Q.empty()) {
        auto it = Q.top();
        Q.pop();
        int u = it.second;
       // dbg(u);
        if(vis[u]) continue;
        vis[u] = true;
        if(u == n - 1) break;
        for(int tt = last + 1; tt <= u; tt++) {
            if(done[tt]) continue;
            done[tt] = true;
            for(auto &qt: start[tt]) {
                int v = qt.second;
                int w = qt.first;
                if(dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    Q.push({dist[v], v});
                }
            }
        }  
        last = u;
    }
    // f(i, n) cout<<dist[i]<<' ';
    // cout<<endl;
    if(dist[n - 1] == inf) cout<<"-1";
    else cout<<dist[n - 1];
}

