typedef pair<long long, long long> P;
typedef long long ll;
class LazySegTree
{
    int n;
    vector<long long int> node, lazy;

public:
    LazySegTree(vector<long long int> v)
    {
        int s = int(v.size());
        n = 1;
        while (n < s)
        {
            n <<= 1;
        }
        node.resize(2 * n - 1,1e18);
        lazy.resize(2 * n - 1, 1e18);

        for (int i = 0; i < s; i++)
        {
            node[i + n - 1] = v[i];
        }
        for (int i = n - 2; i >= 0; i--)
        {
            node[i] = min(node[i * 2 + 1],node[i * 2 + 2]);
        }
    }

    void eval(int k, int l, int r)
    {
        if (lazy[k]<1e18)
        {
            node[k] = min(node[k],lazy[k]);
            if (r - l > 1)
            {
                lazy[2 * k + 1] = min(lazy[k], lazy[2 * k + 1]);
                lazy[2 * k + 2] = min(lazy[k], lazy[2 * k + 2]);
            }
            lazy[k] = 1e18;
        }
    }

    void add(int a, int b, long long int x, int k = 0, int l = 0, int r = -1)
    {
        if (r < 0)
            r = n;
        eval(k, l, r);
        if (b <= l || r <= a)
        {
            return;
        }
        if (a <= l && r <= b)
        {
            lazy[k] = min(lazy[k],x);
            eval(k, l, r);
        }
        else
        {
            add(a, b, x, 2 * k + 1, l, (l + r) / 2);
            add(a, b, x, 2 * k + 2, (l + r) / 2, r);
            node[k] = node[2 * k + 1] + node[2 * k + 2];
        }
    }

    long long int rangeMin(int a, int b, int k = 0, int l = 0, int r = -1)
    {
        if (r < 0)
            r = n;
        eval(k, l, r);
        if (b <= l || r <= a)
        {
            return 1e18;
        }
        if (a <= l && r <= b)
        {
            return node[k];
        }
        long long int vl = rangeMin(a, b, 2 * k + 1, l, (l + r) / 2);
        long long int vr = rangeMin(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl,vr);
    }

    void set(int a, long long int x)
    {
        add(a, a + 1, x);
    }

    long long int get(int a)
    {
        return rangeMin(a, a + 1);
    }
};
