void solve() {
  using T=tuple<int,int,LL>;
  vector<T> X;
  REP(i,M) X.emplace_back(R[i],L[i],W[i]);
  sort(ALL(X));
  map<int,LL> D;
  D[1]=0;
  REP(i,M) {
    int l,r; LL w; tie(r,l,w)=X[i];
    auto it=D.lower_bound(l);
    if(it!=D.end()) {
      if(D.count(r)==0) D[r]=Inf;
      SMIN(D[r],it->second+w);
