void solve()
{
    ll N, M;
    in(N, M);
    vll L(M);
    vll R(M);
    vll C(M);
    // set<ll> za;
    // za.insert(0);
    // za.insert(N - 1);
    for1 (i, M) {
        ll l, r, c;
        in(l, r, c);
        --l;
        --r;
        L[i] = l;
        R[i] = r;
        C[i] = c;
        // za.insert(l);
        // za.insert(r);
    }
    /*
    ll idx = 0;
    map<ll, ll> zaa;
    for (ll z : za) {
        zaa[z] = idx;
        idx++;
    }
    dump(za);
    dump(zaa);
    for1 (i, M) {
        L[i] = zaa[L[i]];
        R[i] = zaa[R[i]];
    }
    N = zaa.size();
    */
    vector<vector<pll>> to(N);
    dump(L);
    dump(R);
    for1 (i, M) {
        for2 (j, L[i], R[i]) {
            ll k = R[i];
            to[j].emplace_back(k, C[i]);
        }
        ll j = L[i];
        for2 (k, L[i] + 1, R[i]) {
            to[j].emplace_back(k, C[i]);
        }
    }
    vll dis(N, INF);
    priority_queue<pair<ll, ll>> q;
    q.push(make_pair(0, 0));
    while (!q.empty()) {
        ll cost, loc;
        tie(cost, loc) = q.top();
        q.pop();
        cost = -cost;
        if (dis[loc] < cost) {
            continue;
        }
        dis[loc] = cost;
        for (auto t : to[loc]) {
            ll cost2 = cost + t.second;
            ll loc2 = t.first;
            q.push(make_pair(-cost2, loc2));
        }
    }
    dump(dis);
    if (dis[N - 1] == INF) {
        print(-1);
    }
    else {
        print(dis[N - 1]);
    }
}
