class aint {
    int n;
    vector<ll> v;
public:
    aint(int N): n(N), v(2 * n, 0x3f3f3f3f3f3f3f3fll){}
    void update(int poz, ll val){
        poz += n;
        v[poz] = min(v[poz], val);
        for(poz /= 2; poz; poz /= 2)
            v[poz] = min(v[2*poz], v[2*poz+1]);
    }
    ll query(int st, int dr){
        ll ret = 0x3f3f3f3f3f3f3f3fll;
        for(st += n, dr += n+1; st < dr; st /= 2, dr /= 2){
            if(st%2) ret = min(ret, v[st++]);
            if(dr%2) ret = min(ret, v[--dr]);
        }
        return ret;
    }
};

int main(){
    int n, m;
    cin >> n >> m;

    vector<vector<pair<int, ll>>> by_rhs(n + 1);

    for(int i = 0, l, r, c; i < m; ++i){
        cin >> l >> r >> c;
        by_rhs[r].emplace_back(l, c);
    }

    aint a(n + 1);

    a.update(1, 0);

    for(int i = 2; i <= n; ++i)
        for(auto x : by_rhs[i])
            a.update(i, min(a.query(x.first, i) + x.second, 0x3f3f3f3f3f3f3f3fll));

    cout << (a.query(n, n) == 0x3f3f3f3f3f3f3f3fll ? -1 : a.query(n, n)) << endl;
}

