void build(ll i,ll s,ll e)
{
	seg[i] = 1e18;
	if(s==e)
	{
		if(s==1)
			seg[i]=0;
		return;
	}
	ll m=(s+e)/2;
	build(2*i,s,m);
	build(2*i+1,m+1,e);
}
void update(ll i,ll s,ll e,ll l,ll r,ll x)
{
	if(s>r || l>e)
		return;
	if(s>=l && e<=r)
	{
		seg[i]=min(seg[i],x);
		return;
	}
	ll m=(s+e)/2;
	update(2*i,s,m,l,r,x);
	update(2*i+1,m+1,e,l,r,x);
}
ll query(ll i,ll s,ll e,ll x)
{
	if(s==e)
		return seg[i];
	ll m=(s+e)/2;
	if(x<=m)
		return min(seg[i],query(2*i,s,m,x));
	else
		return min(seg[i],query(2*i+1,m+1,e,x));
}
