#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const static ll INF = 1e15;
const ll mod = 1e9+7;
// __uint128_t

//このSegmentTreeは最小値を扱う仕様になっている
struct SegmentTree {
private:
    ll n;
    vector<ll> node;
    ll INF = 1e18;
public:
    // 元配列 v をセグメント木で表現する
    SegmentTree(vector<ll> v) {
        // 最下段のノード数は元配列のサイズ以上になる最小の 2 冪 -> これを n とおく
        // セグメント木全体で必要なノード数は 2n-1 個である
        ll sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, INF);

        // 最下段に値を入れたあとに、下の段から順番に値を入れる
        // 値を入れるには、自分の子の 2 値を参照すれば良い
        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = min(node[2*i+1], node[2*i+2]);
    }
    void update(ll x, ll val) {
        // x番目をvalに変える
        // 最下段のノードにアクセスする
        x += (n - 1);

        // 最下段のノードを更新したら、あとは親に上って更新していく
        node[x] = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2*x+1], node[2*x+2]);
        }
    }

    ll get_X(ll x){
        x += (n - 1);
        return node[x];
    }

    // 要求区間 [a, b) 中の要素の最小値を答える
    // k := 自分がいるノードのインデックス
    // 対象区間は [l, r) にあたる

    ll get_min(ll a, ll b, ll k=0, ll l=0, ll r=-1) {
        // 最初に呼び出されたときの対象区間は [0, n)
        if(r < 0) r = n;

        // 要求区間と対象区間が交わらない -> 適当に返す
        if(r <= a || b <= l) return INF;

        // 要求区間が対象区間を完全に被覆 -> 対象区間を答えの計算に使う
        if(a <= l && r <= b) return node[k];

        // 要求区間が対象区間の一部を被覆 -> 子について探索を行う
        // 左側の子を vl ・ 右側の子を vr としている
        // 新しい対象区間は、現在の対象区間を半分に割ったもの
        ll vl = get_min(a, b, 2*k+1, l, (l+r)/2);
        ll vr = get_min(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }

};

int main(){
    ll N, M; cin >> N >> M;
    vector<pair<pair<ll, ll>, ll>> V(M); 
    for(int i = 0; i < M; i++){
        ll l, r, c; cin >> l >> r >> c;
        V[i] = {{l, r}, c};
    }
    sort(V.begin(), V.end());
    vector<ll> DP(N+1, INF);
    SegmentTree tree(DP);
    for(int i = 0; i < M; i++){
        auto p = V[i];
        ll l = p.first.first, r = p.first.second, c = p.second;
        if(l == 1) tree.update(r, c);
        else{
            ll Min = tree.get_min(l, r);
            tree.update(r, min(tree.get_X(r), Min+c));
        }
    }
    if(tree.get_X(N) == INF) cout << -1 << endl;
    else cout << tree.get_X(N) << endl;
}

