#include<bits/stdc++.h>
using namespace std;
#define ll long long

const int MAXN = 1e5+10;
const ll inf = 1e15;

struct EDGE{
    int u,v;
    ll w;
}edge[MAXN];

bool cmp(EDGE x,EDGE y)
{
    return x.u == y.u?x.v < y.v:x.u<y.u;
}

struct node{
    int l,r;
    ll minn,lazy,maxn;
    int mid(){return (r + l) / 2;}
};

struct seg_tree{
    node tree[MAXN<<2];
    inline void pushup(int x)
    {
        tree[x].minn = min(tree[x<<1].minn,tree[x<<1|1].minn);
        tree[x].maxn = max(tree[x<<1].maxn,tree[x<<1|1].maxn);
    }
    void pushdown(int x)
    {
        if (tree[x].lazy == 0) return;
        tree[x<<1].minn = min(tree[x<<1].minn,tree[x].lazy);
        tree[x<<1|1].minn = min(tree[x<<1|1].minn,tree[x].lazy);
        if (tree[x<<1].maxn > tree[x].lazy)
        {
            tree[x<<1].maxn = tree[x].lazy;
            tree[x<<1].lazy = tree[x].lazy;
        }
        if (tree[x<<1|1].maxn > tree[x].lazy)
        {
            tree[x<<1|1].maxn = tree[x].lazy;
            tree[x<<1|1].lazy = tree[x].lazy;
        }
        tree[x].lazy = 0;
    }
    void build(int l,int r,int x)
    {
        tree[x].l = l,tree[x].r = r;
        if (l == r)
        {
            if (l == 1) tree[x].minn = tree[x].maxn = 0;
            else tree[x].minn = tree[x].maxn = inf;
            return;
        }
        int mid = tree[x].mid();
        build(l,mid,x<<1);
        build(mid+1,r,x<<1|1);
        pushup(x);
    }
    void add(int st,int ed,int x,ll v)
    {
        if (st<=tree[x].l && ed>=tree[x].r)
        {
            if (tree[x].minn > v)
            {
                tree[x].minn = v;
            }
            if (tree[x].maxn > v)
            {
                tree[x].maxn = v;
                tree[x].lazy = v;
            }
            return;
        }
        pushdown(x);
        int mid = tree[x].mid();
        if (st <= mid) add(st,ed,x<<1,v);
        if (ed > mid) add(st,ed,x<<1|1,v);
        pushup(x);
    }
    ll query(int st,int ed,int x)
    {
        if (st<=tree[x].l && ed>=tree[x].r) return tree[x].minn;
        pushdown(x);
        int mid = tree[x].mid();
        ll res = inf;
        if (st <= mid) res = min(res,query(st,ed,x<<1));
        if (ed > mid) res = min(res,query(st,ed,x<<1|1));
        pushup(x);
        return res;
    }
}seg;

int main()
{
    int n,m;
    scanf("%d%d",&n,&m);
    for (int i = 1;i<=m;i++)
    {
        scanf("%d%d%lld",&edge[i].u,&edge[i].v,&edge[i].w);
    }
    sort(edge+1,edge+m,cmp);
    seg.build(1,n,1);
    for (int i = 1;i<=m;i++)
    {
        ll dis = seg.query(edge[i].u,edge[i].v,1);
        seg.add(edge[i].u,edge[i].v,1,dis+edge[i].w);
    }
    ll dis = seg.query(n,n,1);
    if (dis == inf) cout<<-1;
    else cout<<dis;
    return 0;
}

