set< lint > divisor(lint n){
	set< lint > ret;
	for(lint i = 1; i * i <= n; i++){
		if(n % i == 0){
			ret.insert(i);
			if(i * i != n) ret.insert(n / i);
		}
	}
	return (ret);
}


