struct SegmentTree{
    int n;
    vector<ll> nodes;

    SegmentTree(vector<ll> v) {
        int sz=v.size();
        n=1;
        while(n<sz) {
            n*=2;
        }
        nodes.resize(2*n-1,LINF);
        for(int i=0;i<sz;i++) {
            nodes[i+n-1]=v[i];
        }
        for(int i=n-2;i>=0;i--) {
            nodes[i]=min(nodes[2*i+1],nodes[2*i+2]);
        }
    }

    void update(int x,ll val) {
        x=n+x-1;
        nodes[x]=val;
        while(x>0) {
            x=(x-1)/2;
            nodes[x]=min(nodes[2*x+1],nodes[2*x+2]);
        }
    }

    ll getmin(int a,int b,int k=0,int l=0,int r=-1) {
        if(r<0) r=n;

        if(r<=a || b<=l) return LINF;
        if(a<=l && r<=b) return nodes[k];

        ll vl=getmin(a,b,2*k+1,l,(l+r)/2);
        ll vr=getmin(a,b,2*k+2,(l+r)/2,r);

        return min(vl,vr);
    }

    ll at(int x) {
        return nodes[n+x-1];
    }
};

int main() {
    int n,m;
    cin>>n>>m;
    vector<pair<pair<int,int>,ll>> vec(m);
    rep(i,m) {
        int l,r;
        ll c;
        cin>>l>>r>>c;
        l--;r--;
        vec[i]={{r,l},c};
    }
    sort(all(vec));

    vector<ll> v(n,LINF);
    SegmentTree segt(v);
    segt.update(0,0);
    rep(i,m) {
        int l=vec[i].first.second;
        int r=vec[i].first.first;
        ll c=vec[i].second;
        segt.update(r,min(segt.at(r),segt.getmin(l,r+1)+c));
    }
    cout<<(segt.at(n-1)==LINF ? -1 : segt.at(n-1))<<endl;
}

