const int N=1e5+10;
const long long int INF=1e16+10;
struct seg_tree{
	vector<long long int> v,f;
	void init(int n){v.resize(n<<2,INF);f.resize(n<<2,-1ll);}
	void push(int n){
		if(f[n]>=0){
			if(v[n*2+1]>f[n])v[n*2+1]=f[n*2+1]=f[n];
			if(v[n*2+2]>f[n])v[n*2+2]=f[n*2+2]=f[n];
			f[n]=-1;
		}
		return ;
	}
	void pull(int n){
		v[n]=max(v[n*2+1],v[n*2+2]);
		return ;
	}
	void fix(int n,int l,int r,int L,int R,long long int x){
		if(L<=l&&r<=R){
			if(v[n]>x)f[n]=v[n]=x;
			return ;
		}
		else if(L>r||l>R||v[n]<=x)return ;
		else{
			int mid=(l+r)>>1;
			push(n);
			fix(n*2+1,l,mid,L,R,x);
			fix(n*2+2,mid+1,r,L,R,x);
			pull(n);
			return ;
		}
	}
	long long int ask(int n,int l,int r,int pos){
		if(l==r)return v[n];
		else {
			int mid=(l+r)>>1;
			push(n);
			if(pos>mid)return ask(n*2+2,mid+1,r,pos);
			else return ask(n*2+1,l,mid,pos);
		}
	}
};
int main(){
	int n,m;
	pair<pair<int,int>,int> p[N];
	long long int ans;
	seg_tree sg;
	scanf("%d%d",&n,&m);
	for(int i=1;i<=m;i++)scanf("%d%d%d",&p[i].F.F,&p[i].F.S,&p[i].S);
	sort(p+1,p+m+1);
	sg.init(n);
	sg.fix(0,1,n,1,1,0);
	for(int i=1;i<=m;i++)sg.fix(0,1,n,p[i].F.F,p[i].F.S,sg.ask(0,1,n,p[i].F.F)+p[i].S);
	ans=sg.ask(0,1,n,n);
	if(ans>=INF)ans=-1;
	printf("%lld\n",ans);
}

