#include <bits/stdc++.h>
using namespace std;

#define LLINF 12345678901234567LL

struct addedge{
	int L;
	int R;
	long long C;
};

vector<long long> dist;
int N,M,n;
vector<addedge> A;

bool sort_addedge(const addedge &x,const addedge &y){
	if(x.R==y.R)return x.L<y.L;
	else return x.R<y.R;
}

void update(int i,long long x){
	i+=n-1;
	dist[i]=x;
	while(i>0){
		i=(i-1)/2;
		dist[i]=min(dist[i*2+1],dist[i*2+2]);
	}
}

long long query(int a,int b,int k,int l,int r){
	if(r<=a || b<=l)return LLINF;
	if(a<=l && r<=b)return dist[k];
	long long ret1=query(a,b,2*k+1,l,(l+r)/2);
	long long ret2=query(a,b,2*k+2,(l+r)/2,r);
	return min(ret1,ret2);
}

int main(){
	cin >> N >> M;
	n=1;
	while(n<N)n*=2;

	dist=vector<long long>(2*n-1,LLINF);

	for(int i=0;i<M;i++){
		addedge a;
		cin >> a.L >> a.R >> a.C;
		a.L--;
		a.R--;
		A.push_back(a);
	}

	sort(A.begin(),A.end(),sort_addedge);

	update(0,0LL);
	for(auto a:A){
		//cout << query(a.L,a.R,0,0,n) << endl;
		update(a.R,min(dist[a.R+n-1],query(a.L,a.R,0,0,n)+a.C));
	}

	long long ans= (dist[N-1+n-1]==LLINF)?(-1):(dist[N-1+n-1]);
	cout << ans << endl;

	//for(int i=0;i<N;i++)cout << dist[i+n-1] << " ";
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef vector<int> vi;
typedef pair<int,int> ii;
typedef vector<ii> vii;
vector<vii> graph;
vi dist;
void dijkstra()
{
	dist[1] = 0;
	priority_queue<ii,vector<ii>,greater<ii> >pq;
	pq.push(ii(0,1));
	while(!pq.empty())
	{
		ii x = pq.top();pq.pop();
		int a = x.first;
		int b = x.second;
		if(dist[b]==a)
		{
			for(int i=0;i<graph[b].size();++i)
			{
				ii c = graph[b][i];
				if(dist[c.first]==-1||dist[c.first] > dist[b] + c.second)
				{
					dist[c.first] = dist[b] + c.second;
					pq.push(ii(dist[c.first],c.first));
				}
			}
		}
	}
}
int main()
{
	int n,m,i,x,y,w;
	cin>>n>>m;
	graph.assign(n+1,vii());
	dist.assign(n+1,-1);
	for(i=1;i<=n;++i)
	{
		graph[i].push_back(ii(i-1,0));
	}
	for(i=1;i<=m;++i)
	{
		cin>>x>>y>>w;
		graph[x].push_back(ii(y,w));
		graph[y].push_back(ii(x,w));
	}
	dijkstra();
	printf("%d",dist[n]);
}

