LL N,M;
//i->jにコストcで行けるとき、
//集合adj[i]は(j,c)を含む
vector<vector<pair<LL,LL>>> adj;

LL ans = 0;

void solve(){
	for(int i=2;i<=N;i++) adj[i].push_back(pair<LL,LL>(i-1,0));

	//ダイクストラ
	//pair<LL,LL>(最短距離、頂点番号)
	priority_queue<pair<LL,LL>,vector<pair<LL,LL>>,greater<pair<LL,LL>>> q;
	q.push(pair<LL,LL>(0,1));
	//点1から点iまでの最短距離をdist[i]とおく
	vector<LL> dist(N+1,INF);
	dist[1] = 0;
	while(!q.empty()){
		LL now_node = q.top().second;
		LL now_dist = q.top().first;
		q.pop();
		for(auto next:adj[now_node]){
			LL next_node = next.first;
			LL d = next.second;
			if(dist[next_node]>dist[now_node]+d){
				dist[next_node] = dist[now_node]+d;
				q.push(pair<LL,LL>(dist[next_node],next_node));
			}
		}
	}
	ans = dist[N];
	if(ans==INF) ans = -1;
}

int main(){
    cin >> N >> M;
    adj = vector<vector<pair<LL,LL>>>(N+1);
    for(int i=0;i<M;i++){
    	LL l,r,c;cin >> l >> r >> c;
    	adj[l].push_back(pair<LL,LL>(r,c));
    	adj[r].push_back(pair<LL,LL>(l,c));
    }

    solve();

    cout << ans << endl;
    return 0;
}

