#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll INF = 1e17;

struct RU {
	using t1 = ll;
	using t2 = ll;
	static t2 id2() { return INF; }
	static t1 op2(const t1& l, const t2& r) { return min(l, r); }
	static t2 op3(const t2& l, const t2& r) { return min(l, r); }
};

template <typename M>
class lazy_segment_tree {
	using T1 = typename M::t1;
	using T2 = typename M::t2;
	const int h, n;
	vector<T1> data;
	vector<T2> lazy;
	void push(int node) {
		if (lazy[node] == M::id2()) return;
		lazy[node << 1] = M::op3(lazy[node << 1], lazy[node]);
		lazy[(node << 1) | 1] = M::op3(lazy[(node << 1) | 1], lazy[node]);
		lazy[node] = M::id2();
	}
public:
	lazy_segment_tree(int n_, T1 v1)
		: h(ceil(log2(n_))), n(1 << h), data(n_, v1), lazy(n << 1, M::id2()) {}
	lazy_segment_tree(const vector<T1>& data_)
		: h(ceil(log2(data_.size()))), n(1 << h), data(data_), lazy(n << 1, M::id2()) {}
	void update(int l, int r, T2 val) {
		l += n, r += n - 1;
		for (int i = h; i > 0; i--) push(l >> i), push(r >> i);
		r++;
		while (l < r) {
			if (l & 1) lazy[l] = M::op3(lazy[l], val), l++;
			if (r & 1) r--, lazy[r] = M::op3(lazy[r], val);
			l >>= 1; r >>= 1;
		}
	}
	T1 find(int p) {
		T1 res = data[p]; p += n;
		while (p) res = M::op2(res, lazy[p]), p >>= 1;
		return res;
	}
};

int main()
{
	int N, M;
	cin >> N >> M;
	vector<int> L(M), R(M), C(M);
	vector<vector<pair<int, ll>>> G(N);
	for (int i = 0; i < M; i++) {
		cin >> L[i] >> R[i] >> C[i]; --L[i];
		G[L[i]].emplace_back(R[i], C[i]);
	}
	lazy_segment_tree<RU> lst(N, INF);
	lst.update(0, 1, 0);
	for (int i = 0; i < N; i++) {
		ll d = lst.find(i);
		for (auto e : G[i]) {
			lst.update(i, e.first, d + e.second);
		}
	}
	ll res = lst.find(N - 1);
	cout << (res == INF ? -1 : res) << endl;
	return 0;
}

