using namespace std;
typedef long long lli;
typedef pair<int, int> pii;
const int maxn = 1e5 + 5;
const lli INF = 1e18;
int n, m;

vector<pii> g[maxn];

lli val[maxn * 4];
lli lazy[maxn * 4];

void ReadInput()
{
    cin >> n >> m;
    for(int i = 1; i <= m; ++i)
    {
        int L, R, c;
        cin >> L >> R >> c;
        g[L].push_back(pii(R, c));
    }
}

void push(int x)
{
    if(lazy[x] == -1) return;

    if(val[x * 2] > lazy[x])
    {
        val[x * 2] = lazy[x];
        lazy[x * 2] = lazy[x];
    }

    if(val[x * 2 + 1] > lazy[x])
    {
        val[x * 2 + 1] = lazy[x];
        lazy[x * 2 + 1] = lazy[x];
    }

    lazy[x] = -1;
}

void Update(int x, int l, int r, int L, int R, lli nval)
{
    if(L > r || l > R) return;
    if(l >= L && r <= R)
    {
        if(nval < val[x])
        {
            val[x] = nval;
            lazy[x] = nval;
        }
        return;
    }
    push(x);
    int mid = (l + r) / 2;
    Update(x * 2, l, mid, L, R, nval); Update(x * 2 + 1, mid + 1, r, L, R, nval);
}

lli Get(int x, int l, int r, int p)
{
    if(p < l || p > r) return INF;
    if(l == r)
        return val[x];
    push(x);
    int mid = (l + r) / 2;
    return min(Get(x * 2, l, mid, p), Get(x * 2 + 1, mid + 1, r, p));
}

void Solve()
{
    fill(begin(val), end(val), INF);
    fill(begin(lazy), end(lazy), -1);
    Update(1, 1, n, 1, 1, 0);
    for(int i = 1; i < n; ++i)
    {
        lli k = Get(1, 1, n, i);
        for(auto to: g[i])
        {
            int L = i, R = to.first, c = to.second;
            lli nval = k + (lli)c;
            Update(1, 1, n, L + 1, R, nval);
        }
    }

    lli ans = Get(1, 1, n, n);
    if(ans == INF) ans = -1;
    cout << ans << '\n';
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    ReadInput();
    Solve();
}

