    auto h = [](ll a, ll b) { return b != -1 ? min(b, a) : a; };
    ll e1 = LINF, e2 = LINF;
    SegmentTree<ll, ll> dp(N + 1, f, g, h, e1, e2, VL(N + 1, LINF));
    dp.update(0, 1, 0);
