const ll INF = 1.0e15;

void dijkstra(int s) {
    priority_queue<P, vector<P>, greater<P> > que;
    //priority_queue<P> que;
    fill(d, d+V, INF);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;

        for (int i = 0; i < G[v].size(); i++) {
            Edge e = G[v][i];
            if (d[e.dst] > d[v] + e.weight) {
                d[e.dst] = d[v] + e.weight;
                que.push(P(d[e.dst], e.dst));
            }
        }
    }
}



