        ll l, r, c; tie(l, r, c) = e[i];
        ll x = sgt.fetch(l, r+1);
        sgt.apply(l, r+1, x + c);
    }

    ll ans = sgt.fetch(n-1, n);
    cout << (ans == LINF ? -1 : ans) << endl;

}

