	while (!pq.empty()) {
		ll d = pq.top().first;
		int cur = pq.top().second;
		pq.pop();
		if (d != dist[cur]) continue;
		for (auto it : adj[cur]) {
			int nxt = it.first;
			ll nd = d + it.second;
			if (nd < dist[nxt]) {
				dist[nxt] = nd;
				pq.emplace(dist[nxt], nxt);
			}
		}
	}

	if (dist[S+N] == INF) cout << -1 << '\n';
	else cout << dist[S+N] << '\n';

	return 0;
}

