		for (; k < i; k++)
			RMQ.push_back(f[k]);
		for (const auto & e : vtr[i]) {
			int l = e.first, r = i, c = e.second;
			f[i] = min(f[i], f[RMQ.query(l, r)] + c);
		}
	}

	if (f[N - 1] == inf)
		cout << "-1";
	else
		cout << f[N - 1];
	cout << '\n';

	return 0;
}

