void __solve()
{
    int n; cin>>n;
    int m; cin>>m;
    vector<vector<pii>> fro(n),to(n);
    for(i32 i=0; i<m; ++i)
    {
        int l,r,c; cin>>l>>r>>c;
        l--; r--;
        fro[l].emplace_back(r,c);
        to[r].emplace_back(l,c);
    }

    const i64 inf=1e18;
    // Lazy_segment_tree<i64,i64> seg(n,inf,inf,minf<i64>,sbminf,sbminf);
    min_monoid<i64> mono;
    actor act;
    lazy_segment_tree<min_monoid<i64>,actor> seg(n,mono,act);

    seg.update(0,0);

    for(i32 i=0; i<n; ++i)
    {
        for(auto itv : to[i])
        {
            int l,c; tie(l,c)=itv;
            seg.update(i,seg.fold(l,i)+c);
        }
        for(auto itv : fro[i])
        {
            int r,c; tie(r,c)=itv;
            seg.update(i,r+1,seg[i]+c);
        }
    }

    if(seg[n-1]!=inf)
    {
        cout << seg[n-1] << "\n";
    }
    else
    {
        cout << -1 << "\n";
    }

}

