  priority_queue<pli,vector<pli>,greater<pli>> q;
  vector<ll> dist(v.size(),longinf);
  dist[x]=0;
  q.push({0LL,x});

  while(q.size()){
    pli p=q.top(); q.pop();
    ll d=p.F, now=p.S;
    if(dist[now]<d){ continue; }
    for(auto to:v[now]){
      if(dist[to.S]>d+to.F){
        dist[to.S] = d+to.F;
        q.push({dist[to.S], to.S});
      }
    }
  }
  return dist;
}

int main(){
  int n,m;
  cin >> n >> m;
  wgraph v(n);
  rep(i,m){
    int x,y,z;
    cin >> x >> y >> z; x--; y--;
    v[x].emplace_back(z,y);
  }
  for(int i=n-1; i>0; i--){
    v[i].emplace_back(0,i-1);
  }
  vector<ll> dist=bfs(v,0);
  ll ans = dist[n-1];
  if(ans==longinf) ans=-1;
  cout << ans << endl;
  return 0;  
}

