struct edge{int to,cost;};
struct graph{
  int N;  
  vector<vector<edge>> G;
  Vi dist;

  graph(int n){
    init(n);
  }

  void init(int n){
    N = n;
    G.resize(N);
    dist.resize(N);
    rep(i,0,N){
      dist[i] = INF;
    }
  }

  void add_edge(int s,int t,int cost){
    edge e;
    e.to = t, e.cost = cost;
    G[s].push_back(e);
  }

  void bfs(int s){

    rep(i,0,N){
      dist[i] = 0;
    }

    dist[s] = 1;
    queue<int> q;
    q.push(s);

    while(!q.empty()){
      int now=q.front();q.pop();
      //終了条件などの処理
      for(auto e : G[now]){
        if(dist[e.to]==0){
          dist[e.to] = dist[now]+1;
          q.push(e.to);
        }
      }
    }

  }

  void dijkstra(int s){

    rep(i,0,N){
      dist[i] = INF;
    }

    dist[s] = 0;
    priority_queue<Pii,vector<Pii>,greater<Pii>> q;
    q.push(mp(s,0));
    while(!q.empty()){
      int now,nowdist;
      tie(now,nowdist) = q.top();q.pop();
      if(dist[now]<nowdist) continue;
      for(auto e : G[now]){
        if(dist[e.to]>dist[now]+e.cost){
          dist[e.to] = dist[now]+e.cost;
          q.push(mp(e.to,dist[e.to]));
        }
      }
    }
  }
  void bellman_ford(int s){ // O(VE)
    rep(i,0,N){
      dist[i] = INF;
    }

    dist[s] = 0;

    rep(i,0,N){
      rep(j,0,N){
        for(auto e : G[j]){
          if(dist[e.to] > dist[j] + e.cost){
            dist[e.to] = dist[j] + e.cost;
            if(i == N-1){
              //閉路発見！
            }
          }
        }
      }
    }
  }
  /* そのまま使わせてもらうのは申し訳ないと思っている */
};

