/**
 * @note O((E + V) log V)
 */
vector<int64_t> dijkstra(vector<vector<pair<int, int64_t> > > const & g, int root) {
    vector<int64_t> dist(g.size(), INT64_MAX);
    priority_queue<pair<int64_t, int> > que;
    dist[root] = 0;
    que.emplace(- dist[root], root);
    while (not que.empty()) {
        int64_t dist_i; int i; tie(dist_i, i) = que.top(); que.pop();
        if (dist[i] < - dist_i) continue;
        for (auto it : g[i]) {
            int j; int64_t cost; tie(j, cost) = it;
            if (- dist_i + cost < dist[j]) {
                dist[j] = - dist_i + cost;
                que.emplace(dist_i - cost, j);
            }
        }
    }
    return dist;
}

int main() {
    int n, m; cin >> n >> m;
    vector<vector<pair<int, int64_t> > > g(n);
    REP (i, n - 1) {
        g[i + 1].emplace_back(i, 0);
    }
    REP (i, m) {
        int l, r; int64_t c; cin >> l >> r >> c;
        -- l;
        -- r;
        g[l].emplace_back(r, c);
    }
    int64_t dist = dijkstra(g, 0)[n - 1];
    cout << (dist == INT64_MAX ? -1 : dist) << endl;
    return 0;
}

