struct segtree {
	int n = 1;
	vector<int>node, lazy;
	vector<bool>lazyF;
	void init(int N) {
		while (n < N)n *= 2;
		node.resize(2 * n - 1,inf);
		lazy.resize(2 * n - 1);
		lazyF.resize(2 * n - 1, false);
	}
	void eval(int k, int l, int r) {
		if (!lazyF[k])return;
		node[k] = lazy[k];
		if (k < n - 1) {
			for (int i = 1; i <= 2; i++)lazy[2 * k + i] = lazy[k];
			for (int i = 1; i <= 2; i++)lazyF[2 * k + i] = true;
		}
		lazyF[k] = false;
	}
	void update(int a, int b, int x, int k, int l, int r) {
		eval(k, l, r);
		if (r <= a || b <= l)return;
		if (a <= l && r <= b) {
			lazy[k] = x;
			lazyF[k] = true;
			eval(k, l, r);
			return;
		}
		update(a, b, x, k * 2 + 1, l, (l + r) / 2);
		update(a, b, x, k * 2 + 2, (l + r) / 2, r);
		node[k] = min(node[k * 2 + 1] ,node[k * 2 + 2]);
	}
	int calc(int a, int b, int k, int l, int r) {
		eval(k, l, r);
		if (r <= a || b <= l)return inf;
		if (a <= l && r <= b)return node[k];
		int vl = calc(a, b, k * 2 + 1, l, (l + r) / 2);
		int vr = calc(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vl , vr);
	}
	void replace(int a, int b, int x) {
		update(a, b, x, 0, 0, n);
	}
	int getmin(int a, int b) {
		return calc(a, b, 0, 0, n);
	}
};
