void solve() {
  int n, m;
  cin >> n >> m;
  vector<state> v;
  for(int i = 0; i < n; i++) {
    int a, b, c;
    cin >> a >> b >> c;
    v.push_back({pii(a, b), c});
  }
  sort(v.begin(), v.end());
  priority_queue<pll> q;
  map<int, ll> dp;
  q.push({0, 1});
  int lastSeen = 0;
  int idx = 0;
  while(!q.empty()) {
    pll curr = q.top(); q.pop();
    if(curr.second <= lastSeen || dp[curr.second] != -curr.first) continue;
    lastSeen = curr.second;
    while(idx < sz(v) && v[idx].first.first <= curr.second) {
      if(v[idx].first.second > curr.second) {
        ll candD = dp[curr.second] + v[idx].second;
        if(!dp.count(v[idx].first.second) || candD < dp[v[idx].first.second]) {
          dp[v[idx].first.second] = candD;
          q.push({-candD, v[idx].first.second});
        }
      }
      idx++;
    }
  }
  if(!dp.count(n)) cout << "-1\n";
  else cout << dp[n] << "\n";
}

