	}
	sort(p, p + m);
	priority_queue<tuple<int, int, int64_t>, vector<tuple<int, int, int64_t>>, greater<tuple<int, int, int64_t>>> pq;
	for(int i = 0; i < m; ++i) {
		int l, r, c;
		tie(l, r, c) = p[i];
		int64_t cost = seg.get(l, r + 1);
		if(cost != LINF) {
			pq.emplace(l, r, c);
			continue;
		} else {
			i--;
			if(pq.size() == 0) {
				cout << -1 << endl;
				return 0;
			}
			while(pq.size()) {
				int64_t ll, rr, cc;
				tie(ll, rr, cc) = pq.top();
				pq.pop();
				int64_t ncos = seg.get(ll, rr + 1) + cc;
				if(ncos <= seg.get(rr, n)) {
					// cerr << ll << " " << rr << " " << cc << endl;
					seg.replace(rr, ncos);
				}
			}
		}
	}
	// for(int i = 0; i < n; ++i) {
