const int mex = 1e16 + 5;
int seg[400005];

void update(int node, int s, int e, int l, int r, int value){
          if(s > r || e < l) return;
          if(s >= l && e <= r) {
              seg[node] = min(seg[node], value); return;
          }
          int mid = (s+e)>>1;
          update(node<<1, s, mid, l, r, value);
          update((node<<1)|1, mid+1, e, l, r, value);
}

int query(int node, int s, int e, int ind){
         if(s == e) return seg[node];
         int mid = (s+e)>>1;
         seg[node<<1] = min(seg[node<<1], seg[node]);
         seg[(node<<1)|1] = min(seg[(node<<1)|1], seg[node]);
         if(ind <= mid) return query(node<<1, s, mid, ind);
         else return query((node<<1)|1, mid+1, e, ind);
}

