        l--; r--;
        g[l].emplace_back(r, c);
    }
    REP(i, n - 1) g[i + 1].emplace_back(i, 0);
    vector<ll> d = dijkstra(0, g);
    cout << (d[n - 1] == LINF ? -1 : d[n - 1]) << EOL;
}

