    }
    for(int i = N - 1; i > 0; i--) {
        G[i].pb(edge<ll>(i - 1, 0));
    }
    vector<ll> dist(N);
    dijkstra<ll>(0, LINF, dist, G);
    cout << (dist[N - 1] == LINF ? -1 : dist[N - 1]) << endl;
    return 0;
}

