const int INF = 1l << 60;

struct RMQ {
    static const int N = 131072;
    int data[2 * N];

    void init() {
        rep(i, 2 * N) {
            data[i] = INF;
        }
    }

    int query(int a, int b, int l = 0, int r = N, int k = 0) {
        if (b <= l || r <= a)return INF;
        if (a <= l && r <= b)return data[k];
        int lch = query(a, b, l, (l + r) / 2, 2 * k + 1);
        int rch = query(a, b, (l + r) / 2, r, 2 * k + 2);
        return min(lch, rch);
    }

    void update(int a, int x) {
        int a2 = a + N - 1;
        data[a2] = min(data[a2], x);
        while (a2) {
            a2 = (a2 - 1) / 2;
            data[a2] = min(data[2 * a2 + 1], data[2 * a2 + 2]);
        }
    }
};

