const int N = 1e5 + 5;
const ll inf = 1e16;

struct node { int l, r, c; } a[N];
int n, m;
ll T[N * 4], lazy[N * 4];

inline bool cmp(const node& a, const node& b) {
    if (a.l != b.l) 
        return a.l < b.l; 
    if (a.r != b.r) 
        return a.r < b.r;
    return a.c < b.c;
}

void build(int k, int l, int r) {
    T[k] = lazy[k] = inf;
    if (l == r)
        return;
    int mid = (l + r) / 2;
    build(k * 2, l, mid);
    build(k * 2 + 1, mid + 1, r);
}

inline void pushdown(int k) {
    cmin(T[k * 2], lazy[k]), cmin(lazy[k * 2], lazy[k]);
    cmin(T[k * 2 + 1], lazy[k]), cmin(lazy[k * 2 + 1], lazy[k]);
    lazy[k] = inf;
}

void modify(int k, int l, int r, int x, int y, ll v) {
    if (x <= l && r <= y) {
        cmin(T[k], v), cmin(lazy[k], v);
        return;
    }
    pushdown(k);
    int mid = (l + r) / 2;
    if (x <= mid)
        modify(k * 2, l, mid, x, y, v);
    if (y > mid)
        modify(k * 2 + 1, mid + 1, r, x, y, v);
    T[k] = min(T[k * 2], T[k * 2 + 1]);
}

ll query(int k, int l, int r, int x, int y) {
    if (x <= l && r <= y)
        return T[k];
    pushdown(k);
    int mid = (l + r) / 2;
    ll ans = inf;
    if (x <= mid)
        cmin(ans, query(k * 2, l, mid, x, y));
    if (y > mid)
        cmin(ans, query(k * 2 + 1, mid + 1, r, x, y));
    return ans;
}

void debug(int x) {
    printf("%lld", query(1, 1, n, x, x));
}

int main() {
    using io ::in;
    n = in(), m = in();
    for (int i = 1; i <= m; ++i)
        a[i].l = in(), a[i].r = in(), a[i].c = in();
    std ::sort(a + 1, a + 1 + m, cmp);
    build(1, 1, n);
    //for (int i = 1; i <= n; ++i)
    //    printf("%lld ", T[i]); puts("");
    modify(1, 1, n, 1, 1, 0);
    //for (int i = 1; i <= n; ++i)
    //    debug(i), printf(" "); puts("");
    for (int i = 1; i <= m; ++i) {
        ll cur = query(1, 1, n, a[i].l, a[i].r) + a[i].c;
        //printf("%d %d %lld\n", a[i].l, a[i].r, cur);
        modify(1, 1, n, a[i].l, a[i].r, cur);
    }
    //for (int i = 1; i <= n; ++i)
    //    debug(i), printf(" "); puts("");
    ll ans = query(1, 1, n, n, n);
    if (ans >= inf) 
        puts("-1");
    else
        printf("%lld\n", ans);
    return 0;
}

