struct SegmentTree {
    int N;
    vector<long long> node;

    SegmentTree(vector<long long> v) {
        int sz = v.size();
        N = 1; while (N < sz) N *= 2;
        node.assign(2*N,1e18);

        for (int i = 0; i < sz; i++) node[i+N] = v[i];
        for (int i = N-1; i >= 1; i--) node[i] = min(node[i<<1|0],node[i<<1|1]);
    }


    void update(int x, long long val) {
        x += N;

        node[x] = val;
        while (x > 1) {
            x >>= 1;
            node[x] = min(node[x<<1|0],node[x<<1|1]);
        }
    }

    long long getmin(int a, int b, int k = 1, int l = 0, int r = -1) {
        if (r < 0) r = N;

        if (r <= a || b <= l) return 1e18;

        if (a <= l && r <= b) return node[k];

        long long vl = getmin(a, b, k<<1|0, l, (l+r)/2);
        long long vr = getmin(a, b, k<<1|1, (l+r)/2, r);
        return min(vl,vr);
    }

    ll getnum(int a) {
        return node[a+N];
    }    
};

int main() {
