    dist[0] = 0;
    SegmentTree sg(dist);
    rep(i,M) {
        int L,R; ll C;
        tie(R,L,C) = Q[i];
        ll d = sg.getmin(L,R+1);
        if (sg.getnum(R) > d+C) sg.update(R,d+C);
    }

    ll ans = sg.getnum(N-1);
    if (ans == 1e18) cout << -1 << endl;
    else cout << ans << endl;
}

