const ll INF = 1e15;
//始点sとした最短距離を求める O((V+E)logV)
vector<ll> dijkstra(vector<vector<P>>& g, ll s) {
  ll n = SZ(g);
  vector<ll> d(n, INF);
  priority_queue<P, vector<P>, greater<P>> pq;
  vector<bool> fixed(n, false);
  d[s] = 0;
  pq.push(make_pair(0, s));
  while (!pq.empty()) {
    P f = pq.top();
    pq.pop();
    ll cv = f.second;
    fixed[cv] = true;
    if (d[cv] < f.first) continue;
    FOREACH(p, g[cv]) {
      ll nv = p.first;
      ll wgt = p.second;
      if (fixed[nv]) continue;
      if (d[nv] <= d[cv] + wgt) continue;
      d[nv] = d[cv] + wgt;
      pq.push(make_pair(d[nv], nv));
    }
  }
  return d;
}

int main() {
  ll n, m;
  cin >> n >> m;
  vector<vector<P>> to(n);
  FOR(i, 1, n) { to[i].push_back(make_pair(i - 1, 0)); }
  REP(i, m) {
    ll l, r, c;
    cin >> l >> r >> c;
    l--;
    r--;
    to[l].push_back(make_pair(r, c));
  }

  vector<ll> d = dijkstra(to, 0);

  if (d[n - 1] == INF) {
    cout << -1 << endl;
    return 0;
  }
  cout << d[n - 1] << endl;
}

