using namespace std;
using lint = long long int;

/**
 * Segment Tree (0-indexed)
 */
template<class Monoid> struct SegmentTree {
    using func = function<Monoid(Monoid, Monoid)>;
    int n;
    Monoid ie;
    func f;
    vector<Monoid> node;

    SegmentTree(){};
    SegmentTree(int n, Monoid ie, func f) : n(n), ie(ie), f(f) {
        const int cn = n;
        n = 1; while(n < cn)  n *= 2;
        node.assign(2*n, ie);
    }

    void update(int i, Monoid x) {
        i += n;
        node[i] = x;
        while(i /= 2)  node[i] = f(node[2*i], node[2*i+1]);
    }

    // [l, r)
    Monoid query(int l, int r) {
        l = max(l, 0);  r = min(n, r);
        if(l >= r)  return ie;

        Monoid res = ie;
        for(l += n, r += n; l != r; l /= 2, r /= 2) {
            if(l % 2)  res = f(res, node[l++]);
            if(r % 2)  res = f(res, node[--r]);
        }
        return res;
    }

    Monoid operator[](int i) {
        assert(0 <= i && i < n);
        return node[i+n];
    }
};

int main() {
    lint n, m;
    cin >> n >> m;

    using T = tuple<lint, lint, lint>;
    vector<T> query(m);
    for(auto& e : query) {
        lint l, r, c;
        cin >> l >> r >> c;
        e = T(--l, --r, c);
    }

    sort(begin(query), end(query));
    SegmentTree<lint> sg(n, 1e18, [](lint a, lint b){return min(a, b);});
    sg.update(0, 0);

    for(auto q : query) {
        lint l, r, c;
        tie(l, r, c) = q;
        lint mi = sg.query(l, r+1);
        sg.update(r, min(sg[r], mi+c));
    }

    cout << (sg[n-1] == 1e18 ? -1 : sg[n-1]) << endl;
}

