typedef pair<int, int>P;
const int MOD = 998244353;const int MAX = 200020;
const double pi = acos(-1); const double EPS = 1e-12;
const ll INF = 1e18;

struct edge { int to, cost; };
int V;//頂点数
vector<edge>G[MAX];
int d[MAX];//始点からの距離
void dijkstra(int s) {
	priority_queue<P, vector<P>, greater<P>>que;
	fill(d, d + V, INF);
	d[s] = 0;
	que.push(P(0, s));
	while (!que.empty()) {
		P p = que.top(); que.pop();
		int v = p.second;
		if (d[v] < p.first)continue;
		for (int i = 0; i < G[v].size(); i++) {
			edge e = G[v][i];
			if (d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				que.push(P(d[e.to], e.to));
			}
		}
	}
}

void solve() {
	int N; cin >> N;
	int M; cin >> M;
	REP(i, M) {
		int l, r, c; cin >> l >> r >> c;
		l--, r--;
		G[l].push_back({ N + i,c });
		G[N + i].push_back({ l,0 });
		G[N + i].push_back({ r,0 });
		G[r].push_back({ N + i,c });
	}
	V = N+M;
	REP(i, N) {
		d[i] = INF;
		if(i<N-1)G[i + 1].push_back({ i,0 });
	}
	d[0] = 0;
	dijkstra(0);
	if (d[N - 1] == INF)print(-1);
	else print(d[N - 1]);
}


