LL st[400005];
void build(int n, int s, int e){
    if(s == e) st[n] = 1e18;
    else{
        int mid = (s+e)/2;
        build(n+n, s, mid);
        build(n+n+1, mid+1, e);
        st[n] = min(st[n+n], st[n+n+1]);
    }
}
void update(int n, int s, int e, int idx, LL v){
    if(s == e){
        st[n] = min(st[n], v);
        return;
    }
    int mid = (s+e)/2;
    if(idx <= mid) update(n+n, s, mid, idx, v);
    else update(n+n+1, mid+1, e, idx, v);
    st[n] = min(st[n+n], st[n+n+1]);
}
LL query(int n, int s, int e, int l, int r){
    if(s > r || l > e) return 1e18;
    if(l <= s && e <= r) return st[n];
    int mid = (s+e)/2;
    return min(query(n+n, s, mid, l, r), query(n+n+1, mid+1, e, l, r));
}

