template<typename Monoid>
struct SegmentTree {
    using F = function<Monoid(Monoid,Monoid)>;
    int sz;
    vector< Monoid > data;
    const F f;
    const Monoid M1;
    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
        sz = 1;
        while(sz < n) sz <<= 1;
        data.assign(2 * sz, M1);
    }
    void set(int k, const Monoid &x) {
        data[k + sz] = x;
    }
    void build() {
        for(int k = sz - 1; k > 0; --k) {
            data[k] = f(data[2 * k + 0], data[2 * k + 1]);
        }
    }
    void update(int k, const Monoid &x) {
        k += sz;
        data[k] = x;
        while(k >>= 1) {
            data[k] = f(data[2 * k + 0], data[2 * k + 1]);
        }
    }
    void add(int k, const Monoid &x) {
        update(k, data[k+sz] + x);
    }
    Monoid query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) {
            return M1;
        } else if (a <= l && r <= b) {
            return data[k];
        } else {
            return f(query(a, b, 2 * k + 0, l, (l + r) / 2),
                    query(a, b, 2 * k + 1, (l + r) / 2, r));
        }
    }
    Monoid query(int a, int b) {
        // return f[a, b).
        return query(a, b, 1, 0, sz);
    }
};


int main()
{
    int n, m; cin >> n >> m;
    vector<int> l(m), r(m), c(m);
    for (int i = 0; i < m; ++i) {
        cin >> l[i] >> r[i] >> c[i];
        --l[i], --r[i];
    }

    const LL INF = numeric_limits<LL>::max();
    auto rmq = SegmentTree<LL>(n, [](LL a, LL b){return min(a,b);}, INF);
    rmq.set(0, 0);
    rmq.build();

    vector<int> ord(m);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int i, int j) {
            return r[i] < r[j];
            });


    for (int i = 0; i < m; ++i) {
        int id = ord[i];
        LL mi = rmq.query(l[id], r[id]);
        if (mi == INF) {
            continue;
        }

        LL prev = rmq.query(r[id], r[id]+1);
        rmq.update(r[id], min(prev, mi + c[id]));
    }

    LL ans = rmq.query(n-1, n);
    if (ans == INF) {
        ans = -1;
    }
    cout << ans << endl;


    return 0;
}

