class SegmentTree{
	public:
	int n;
	bool isLazy;
	private:
	vector<lli> segTree,lazy;
	public:
	SegmentTree(){}
	SegmentTree(int n){
		segTree=vector<lli>(4*n);
		lazy=vector<lli>(4*n);
	}
	void buildTree(int node,int l,int r,vector<lli>& anaDizi){
		if(l>r)return;
		if(l==r)segTree[node]=anaDizi[l];
		else{
			buildTree(node*2,l,(l+r)/2,anaDizi);
			buildTree(node*2+1,(l+r)/2+1,r,anaDizi);
			segTree[node]=min(segTree[node*2],segTree[node*2+1]);
		}
	}
	void updateTree(int node,int a,int b,int ind,lli x){
		if(a>b)return;
		if(a>ind ||b<ind)return;
		if(a==b&&a==ind){
			segTree[node]=x;
			return;
		}
		updateTree(node*2,a,(a+b)/2,ind,x);
		updateTree(node*2+1,(a+b)/2+1,b,ind,x);
		segTree[node]=min(segTree[node*2],segTree[node*2+1]);
	}
	lli query(int node,int a,int b,int l,int r){
		if(l>r)return 1e17;
		if(a>b||a>r||b<l)return 1e17;
		if(lazy[node]!=0){
			segTree[node]+=lazy[node]*(b-a+1);
			lazy[node*2]+=lazy[node];
			lazy[node*2+1]+=lazy[node];
			lazy[node]=0;
		}
		if(a>=l&&b<=r)return segTree[node];
		return min(query(node*2,a,(a+b)/2,l,r),
		query(node*2+1,(a+b)/2+1,b,l,r));

	}
};
