      for(int i=0;i<l;i++)seg.pb(INF);
      reverse(all(seg));
      for(int i=1;i<seg.size();i+=2)seg.pb(min(seg[i],seg[i-1]));
      seg.pb(INF);
      reverse(all(seg));
      lazy.resize(seg.size()*2,INF);
}
void push(int j){
      int x=lazy[j];
      seg[j]=min(seg[j],lazy[j]);
      lazy[j*2]=min(lazy[j*2],x);
      lazy[j*2+1]=min(lazy[j*2+1],x);
      lazy[j]=INF;
}
void up(int j){
      while(j>0){
            push(j);
            if(j*2<seg.size()){
            push(j*2);
            push(j*2+1);
            seg[j]=min(seg[j*2],seg[j*2+1]);
            }
            j/=2;
      }
}
void update(int j,int a,int b,int x,int y,int key){
      push(j);
      if(y<a||b<x)return;
      if(a<=x&&y<=b){
            lazy[j]=min(lazy[j],key);
            up(j);
      }
      else{
            update(j*2,a,b,x,(x+y)/2,key);
            update(j*2+1,a,b,(x+y)/2+1,y,key);
      }
}
