      push(j);
      if(y<a||b<x)return INF;
      if(a<=x&&y<=b) return seg[j];
      else{
            return min(query(j*2,a,b,x,(x+y)/2),query(j*2+1,a,b,(x+y)/2+1,y));
      }
}
