    }
    rep2(i, 1, N) {
        dijkstra.add_edge(i, i - 1, 0);
    }

    dijkstra.exec(0);

    ll ans = dijkstra.get_cost(N - 1);

    if (ans != INF) {
        cout << ans << '\n';
    } else {
        cout << -1 << '\n';
    }
}

