const ll INF = 1e18;

struct RMQ {
    int n;
    vl rangeMin;
    RMQ(const vl& array) {
        n = array.size();
        rangeMin.resize(n * 4);
        init(array, 0, n-1, 1);
    }
    ll init(const vl& array, int left, int right, int node) {
        if(left == right)
            return rangeMin[node] = array[left];
        int mid = (left + right) / 2;
        ll leftMin = init(array, left, mid, node * 2);
        ll rightMin = init(array, mid + 1, right, node * 2 + 1);
        return rangeMin[node] = min(leftMin, rightMin);
    }
    ll query(int left, int right, int node, int nodeLeft, int nodeRight) {
        if(right < nodeLeft || nodeRight < left) return INF;
        if(left <= nodeLeft && nodeRight <= right)
            return rangeMin[node];
        int mid = (nodeLeft + nodeRight) / 2;
        return min(query(left, right, node*2, nodeLeft, mid),
            query(left, right, node*2+1, mid+1, nodeRight));
    }
    ll query(int left, int right) {
        return query(left, right, 1, 0, n-1);
    }
    ll update(int index, ll newValue, int node, int nodeLeft, int nodeRight) {
        if(index < nodeLeft || nodeRight < index) 
            return rangeMin[node];
        if(nodeLeft == nodeRight) return rangeMin[node] = newValue;
        int mid = (nodeLeft + nodeRight) / 2;
        return rangeMin[node] = min(
            update(index, newValue, node*2, nodeLeft, mid),
            update(index, newValue, node*2+1, mid+1, nodeRight));
    }
    ll update(int index, ll newValue) {
        return update(index, newValue, 1, 0, n-1);
    }
};


int main(void) {
	ios_base::sync_with_stdio(false); cin.tie(0);
	//freopen("in.txt", "r", stdin);
	int n, m;
	cin >> n >> m;
	vector<pair<pii, ll> > v(m);
	rep(i,0,m) {
		ll l, r, c;
		cin >> l >> r >> c;
		--l; --r;
		v[i] = mp(mp(l,r), c);
	}
	vl d(n, INF);
	d[0] = 0;
	RMQ myR(d);
	sort(all(v));
	rep(i,0,m) {
		int l = v[i].F.F;
		int r = v[i].F.S;
		ll c = v[i].S;

		ll lc = myR.query(l,n-1);
		ll rc = myR.query(r,r);
		if(lc + c < rc) {
			myR.update(r, lc+c);
		}
	}
	ll ret = myR.query(n-1,n-1);
	if(ret == INF) {
		cout << -1 << '\n';
	} else {
		cout << ret << '\n';
	}
	return 0;
}

