void upd(int v, int tl, int tr, int pos, ll val) {
    if (tl == tr) {
        upmin(tree[v], val);
        return;
    }
    int tm = (tl + tr) >> 1;
    if (pos <= tm) {
        upd(v<<1, tl, tm, pos, val);
    } else {
        upd(v<<1|1, tm + 1, tr, pos, val);
    }
    tree[v] = min(tree[v<<1], tree[v<<1|1]);
}

ll get(int v, int tl,  int tr, int l, int r) {
    if (l > r) return llinf;
    if (tl == l && tr == r) {
        return tree[v];
    }
    int tm = (tl + tr) >> 1;
    return min(get(v<<1, tl, tm, l, min(r, tm)),  get(v<<1|1, tm + 1, tr, max(l, tm + 1), r));
}

