    for(int i=0;i<edge[node].size();++i) {
      if(amap[edge[node][i].fi]<=cost+edge[node][i].se) continue;
      que.push(mp(cost+edge[node][i].se, edge[node][i].fi));
    }
  }
  if(amap[N-1]==big) cout<<-1<<endl;
  else cout<<amap[N-1]<<endl;
}

