  }

  vvi es(N);
  map<pii, ll> cost;

  REP(i,M) {
    for(int s = L[i]; s<R[i]; s++) {
      for(int t = s+1; t <= R[i]; t++) {        
        if (cost.count(pii(s,t)) == 0) {
          es[s].push_back(t);
          cost[pii(s,t)] = (ll)C[i];
        } else {
          cost[pii(s,t)] = min(cost[pii(s,t)], (ll)C[i]);
        }

        if (cost.count(pii(t,s)) == 0) {
          es[t].push_back(s);
          cost[pii(t,s)] = (ll)C[i];
        } else {
          cost[pii(t,s)] = min(cost[pii(t,s)], (ll)C[i]);
        }
      }
    }
  }

  vl dist;
  dijkstra(dist, es, 0, cost);

  ll ans = dist[N-1] >= LINF ? -1 : dist[N-1];
  cout << ans << endl;

  return 0;
}

