class RMQ{
    //0-index
    public:
    long long  n=1,*data;

    RMQ(long long n_){
        while(n<n_)n*=2;//要素数nを2の冪乗に
        data=new long long [n*2-1];
        for(long long i=0;i<n*2-1;i++)data[i]=100000000000000000;//木を最大値で初期化
    }

    void updata(long long k,long long a){//k番目の要素をaに更新
        k+=n-1;//k番目の葉のインデックス
        data[k]=a;//葉を更新
        while(k>0){//頂点に達するまで親を更新
            k=(k-1)/2;
            data[k]=min(data[k*2+1],data[k*2+2]);
        }
    }

    //[a,b)の最小値を返す
    //k 接点番号　[l,r)に対応
    long long query(long long a,long long b,long long k,long long l,long long r){
        if(r<=a||b<=l)return 100000000000000000;//完全に範囲外
        if(a<=l&&r<=b)return data[k];//完全に範囲内
        long long mid=(l+r)/2;
        return min(query(a,b,k*2+1,l,mid),query(a,b,k*2+2,mid,r));
    }
    //query(a,b,0,0,n)を呼ぶ
    long long query(long long a,long long b){return query(a,b,0,0,n);}
};



int main(){
    long long n,m,l,r,c,mi;
    cin>>n>>m;
