        l=get<1>(e[i]),r=get<0>(e[i]),c=get<2>(e[i]);
        //cin>>l>>r>>c;
        l--,r--;
        mi=rmq.query(l,r);
        rmq.updata(r,min(mi+c,rmq.query(r,r+1)));
        //e[i]=make_tuple(l,r,c);
    }
    cout<<(rmq.query(n-1,n)==100000000000000000?-1:rmq.query(n-1,n))<<endl;
    return 0;
}

