struct Node {
    int l, r, v, w;
    Node *lch, *rch;

    Node(int l, int r) {
        this->l = l;
        this->r = r;
        v = n++;
        G.pb({});
        w = n++;
        G.pb({});
        if (r - l == 1) {
            if (l == 0) s = v;
            if (l == N - 1) t = w;
            G[v].pb(edge{w, 0});
            return;
        }
        int m = (l + r) / 2;
        lch = new Node(l, m);
        rch = new Node(m, r);
        G[v].pb(edge{lch->v, 0});
        G[v].pb(edge{rch->v, 0});
        G[lch->w].pb(edge{w, 0});
        G[rch->w].pb(edge{w, 0});
    }
};

void dfs(int v0, int v1, int l, int r, Node* z) {
    if (z->r <= l || r <= z->l) return;
    if (l <= z->l && z->r <= r) {
        G[z->w].pb(edge{v0, 0});
        G[v1].pb(edge{z->v, 0});
        return;
    }
    dfs(v0, v1, l, r, z->lch);
    dfs(v0, v1, l, r, z->rch);
}

