template<typename T> vector<vector<T>> pre_warshall_floyd(int n, T inf) {
    vector<vector<T>> g(n, vector<T>(n, inf));
    REP(i, n) g[i][i] = 0;
    return g;
}

template<typename T> void warshall_floyd(vector<vector<T>>& g) {
    int n = sz(g);
    REP(k, n) REP(i, n) REP(j, n) chmin(g[i][j] ,g[i][k] + g[k][j]);
}

void solve() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g = pre_warshall_floyd(n, INF);
    int l, r, c;
    REP(i, m) {
        cin >> l >> r >> c;
        l--; r--;
        FOR(j, l, r + 1) {
            FOR(k, l, r + 1) {
                if (j == k) continue;
                g[j][k] = min(c, g[j][k]);
            }
        }
    }
    warshall_floyd(g);
    cout << (g[0][n - 1] == INF ? -1 : g[0][n - 1]) << EOL;
}

