struct Segment_tree {
	#define lson (root << 1)
	#define rson (root << 1 | 1)
	#define mid ((tree[root].sl + tree[root].sr) >> 1)
	struct Node {
		int sl, sr;
		lint tag, val;
		Node() {}
	}	tree[SIZE];
	inline void build(int root, int l, int r) {
		tree[root].sl = l;
		tree[root].sr = r;
		tree[root].tag = INF;
		tree[root].val = l == 1 ? 0 : INF;
		if (l == r) return;
		build(lson, l, mid);
		build(rson, mid + 1, r);
	}
	inline void pushdown(int root) {
		if (tree[root].tag != INF) {
			tree[lson].tag = min(tree[lson].tag, tree[root].tag);
			tree[lson].val = min(tree[lson].val, tree[lson].tag);
			tree[rson].tag = min(tree[rson].tag, tree[root].tag);
			tree[rson].val = min(tree[rson].val, tree[rson].tag);
			tree[root].tag = INF;
		}
	}
	inline lint query(int root, int l, int r) {
		if (l <= tree[root].sl && tree[root].sr <= r) {
			return tree[root].val;
		}
		pushdown(root);
		lint res = INF;
		if (l <= mid) res = query(lson, l, r);
		if (r > mid) res = min(res, query(rson, l, r));
		tree[root].val = min(tree[lson].val, tree[rson].val);
		return res;
	}
	inline void modify(int root, int l, int r, lint v) {
		if (l <= tree[root].sl && tree[root].sr <= r) {
			tree[root].tag = min(tree[root].tag, v);
			tree[root].val = min(tree[root].val, v);
			return;
		}
		pushdown(root);
		if (l <= mid) modify(lson, l, r, v);
		if (r > mid) modify(rson, l, r, v);
		tree[root].val = min(tree[lson].val, tree[rson].val);
	}
}	tr;
int main() {
	ios::sync_with_stdio(false);
	cin.tie(NULL), cout.tie(NULL);
	int n, m;
	cin >> n >> m;
	rep (i, 1, m) {
		cin >> path[i].L;
		cin >> path[i].R;
		cin >> path[i].C;
	}
	sort(path + 1, path + m + 1);
	tr.build(1, 1, n);
	rep (i, 1, m) {
		lint upd = tr.query(1, path[i].L, path[i].R);
		tr.modify(1, path[i].L, path[i].R, upd + path[i].C);
	}
	lint ans = tr.query(1, n, n);
	if (ans >= INF) ans = -1;
	cout << ans << endl;
	return 0;
}

