void lazy_propagate(int p) {
    if (lazy[p] != -1) {
        val[p] = min(val[p], lazy[p]);
        if (p < size-1) {
        	if(lazy[p*2+1] == -1) lazy[p*2+1] = lazy[p];
        	else lazy[p*2+1] = min(lazy[p], lazy[p*2+1]);
            if(lazy[p*2+2] == -1) lazy[p*2+2] = lazy[p];
        	else lazy[p*2+2] = min(lazy[p], lazy[p*2+2]);
        }
        lazy[p] = -1;
    }
}

void update(int wishl, int wishr, int watchl, int watchr, int k, long long int x) {
    if (wishr <= watchl || watchr <= wishl) {
        lazy_propagate(k);
        return;
    }
    if (wishl <= watchl && watchr <= wishr) {
    	if(lazy[k] == -1) lazy[k] = x;
    	else lazy[k] = min(lazy[k], x);
        lazy_propagate(k);
        return;
    }
    int mid = (watchl+watchr)/2;
    lazy_propagate(k);
    update(wishl, wishr, watchl, mid, k*2+1, x);
    update(wishl, wishr, mid, watchr, k*2+2, x);
    val[k] = min(val[k*2+1], val[k*2+2]);
}
void update(int wishl, int wishr, long long int x) {
    update(wishl, wishr, 0, size, 0, x);
}

long long getmin(int wishl, int wishr, int watchl, int watchr, int k) {
    if (wishr <= watchl || watchr <= wishl) {
        return INF;
    }
    if (wishl <= watchl && watchr <= wishr) {
        lazy_propagate(k);
        return val[k];
    }
    int mid = (watchl+watchr)/2;
    lazy_propagate(k);
    long long ml = getmin(wishl, wishr, watchl, mid, k*2+1);
    long long mr = getmin(wishl, wishr, mid, watchr, k*2+2);
    return min(ml, mr);
}
long long getmin(int wishl, int wishr) {
    return getmin(wishl, wishr, 0, size, 0);
}

