void add(int a,int b,ll c)
{
    e[idx].u = a;e[idx].v = b;
    e[idx].w = c;
    e[idx].next = first[a];
    first[a] = idx++;
}
struct node{
    int id;
    ll val;
    node(int a,ll b):id(a),val(b){}
    bool operator < (const node& t) const
    {
        return val>t.val;
    }
};
void init()
{
    fill(first,first+n+1,-1);
    idx = 1;
}
void dijkstra(int x)
{
    for(int i = 1;i <= n;i++){
        dist[i] = INF;
        vis[i] = 0;
    }
    priority_queue<node> q;
    q.push(node(x,0));
    dist[x] = 0;
    while(!q.empty()){
        node cur = q.top();
        q.pop();
        if(vis[cur.id]) continue;
        vis[cur.id] = 1;
        for(int i = first[cur.id];i!=-1;i=e[i].next){
            int v = e[i].v;
            if(dist[v]>dist[cur.id]+e[i].w){
                dist[v] = dist[cur.id]+e[i].w;
                q.push(node(v,dist[v]));
            }
        }
    }
}
