ll solve(ll start, ll prev) {
	if (dp[start] < INF) {
		return dp[start];
	}

	if (start == N) { //到達
		dp[start] = 0;
		return 0;
	}

	//開始点がprevより後ろでstart以前の区間を探索
	ll s = upper_bound(B.begin(), B.end(), prev) - B.begin();
	ll e = upper_bound(B.begin(), B.end(), start) - B.begin() - 1;
	ll result = INF;

	reps(i, s, e) {
		if (get<1>(A[i]) <= start) {
			continue;
		}
		ll ret = solve(get<1>(A[i]), start) + get<2>(A[i]);
		chmin(result, ret);
	}

	chmin(dp[start], result);
	return result;
}

