using namespace std;
typedef long long ll;
const ll INF = 1e18;
const int maxN = 1e5 + 55;

struct Segment {
    int l, r;   ll w;

    bool operator < (const Segment &other) const {
        return r < other.r;
    }

    Segment(){};
    Segment(int _l, int _r, ll _w) : l(_l), r(_r), w(_w) {};
};

ll segTree[4 * maxN], lazy[4 * maxN];
int n, m;
Segment a[maxN];

void propagate(int id, int l, int r){
    segTree[id] = min(segTree[id], lazy[id]);

    if(l != r){
        lazy[id * 2] = min(lazy[id * 2], lazy[id]);
        lazy[id * 2 + 1] = min(lazy[id * 2 + 1], lazy[id]);
    }

    lazy[id] = INF;
}

void upd(int id, int l, int r, int L, int R, ll val){
    propagate(id, l, r);
    if(L <= l && r <= R){
        lazy[id] = min(lazy[id], val);
        propagate(id, l, r);
        return;
    }

    if(r < L || l > R){
        return;
    }

    int mid = (l + r) / 2;
    upd(id * 2, l, mid, L, R, val);
    upd(id * 2 + 1, mid + 1, r, L, R, val);

    segTree[id] = min(segTree[id * 2], segTree[id * 2 + 1]);
}

ll getMn(int id, int l, int r, int L, int R){
    propagate(id, l, r);
    if(L <= l && r <= R){
        return segTree[id];
    }

    if(r < L || l > R){
        return INF;
    }

		int mid = (l + r) / 2;
		ll ans = getMn(id * 2, l, mid, L, R);
		ans = min(ans, getMn(id * 2 + 1, mid + 1, r, L, R));

		return ans;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    cin >> n >> m;

    for(int i = 0; i < m; i++){
        int l, r;   ll w;   cin >> l >> r >> w;
        a[i] = Segment(l, r, w);
    }

    sort(a, a + m);

    for(int i = 0; i < 4 * maxN; i++){
        segTree[i] = lazy[i] = INF;
    }

    upd(1, 1, n, 1, 1, 0);
    for(int i = 0; i < m; i++){
        ll mn = getMn(1, 1, n, a[i].l, a[i].r);
				upd(1, 1, n, a[i].l, a[i].r, a[i].w + mn);
    }

		ll fRes = getMn(1, 1, n, n, n);

		if(fRes >= INF){
			cout << "-1\n";
			return 0;
		}

		cout << fRes << '\n';

    return 0;
}

