  }
  for (long long i = 0; i < nedge; i++) {
    long long from, to, cost;
    cin >> from >> to >> cost;
    from--;
    to--;
    node.at(from).edge.emplace_back(to, cost);
  }
  priority_queue<Mov, vector<Mov>, decltype(&has_larger_cost)> pq(&has_larger_cost);
  pq.emplace(0LL, 0LL);
