	priority_queue <pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pque;

	for(int i=0;i<m;i++)
	{
		while(!pque.empty())
		{
			if(pque.top().first < l[i].l)
			{
				S.erase(dp[pque.top().second]);
				pque.pop();
			}
			else
			{
				break;
			}
		}

		if(l[i].l==1)
		{
