const long long inf = 1'000'000'000'000'000'000;

const int N = 100'009;

long long t[4 * N];

void put(int x, int l, int r, int pos, long long v) {
  if (l == r) {
    t[x] = min(t[x], v);
    return;
  }
  int s = (l + r) / 2;
  if (pos <= s) {
    put(2 * x, l, s, pos, v);
  } else {
    put(2 * x + 1, s + 1, r, pos, v);
  }
  t[x] = min(t[2 * x], t[2 * x + 1]);
}

long long get(int x, int l, int r, int ql, int qr) {
  if (r < ql || l > qr) {
    return inf;
  }
  if (l >= ql && r <= qr) {
    return t[x];
  }
  int s = (l + r) / 2;
  return min(get(2 * x, l, s, ql, qr), get(2 * x + 1, s + 1, r, ql, qr));
}

vector<pair<int, int>> g[N];

int main() {
  int n, m;
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n; ++i) {
    g[i].clear();
  }
  for (int i = 0; i < m; ++i) {
    int l, r, c;
    scanf("%d%d%d", &l, &r, &c);
    --l;
    --r;
    g[r].emplace_back(l, c);
  }
  for (int i = 0; i < 4 * N; ++i) {
    t[i] = inf;
  }
  put(1, 0, n - 1, 0, 0);
  for (int r = 1; r < n; ++r) {
    for (auto &e : g[r]) {
      int l = e.first;
      int c = e.second;
      long long mn = get(1, 0, n - 1, l, r - 1) + c;
      put(1, 0, n - 1, r, mn);
    }
  }
  long long ans = get(1, 0, n - 1, n - 1, n - 1);
  if (ans == inf) {
    ans = -1;
  }
  printf("%lld\n", ans);
}

