int nxt;
int buildTree1(int L, int R) {
	if (L == R) return L;
	int cur = nxt++;
	T[cur].L = L;
	T[cur].R = R;
	if (L < R) {
		T[cur].pl = buildTree1(L, (L + R) / 2);
		T[cur].pr = buildTree1((L + R) / 2 + 1, R);
		neigh[cur].emplace_back(T[cur].pl, 0);
		neigh[cur].emplace_back(T[cur].pr, 0);
	}
	return cur;	
}
int buildTree2(int L, int R) {
	if (L == R) return L;
	int cur = nxt++;
	T[cur].L = L;
	T[cur].R = R;
	if (L < R) {
		T[cur].pl = buildTree2(L, (L + R) / 2);
		T[cur].pr = buildTree2((L + R) / 2 + 1, R);
		neigh[T[cur].pl].emplace_back(cur, 0);
		neigh[T[cur].pr].emplace_back(cur, 0);
	}
	return cur;	
}
void add1(int L, int R, int to, int c, int cur) {
	if (L <= T[cur].L && R >= T[cur].R) {
		neigh[to].emplace_back(cur, 0);
		return;
	}
	if (L <= T[ T[cur].pl ].R) {
		add1(L, R, to, c, T[cur].pl);
	}
	if (T[ T[cur].pr ].L <= R) {
		add1(L, R, to, c, T[cur].pr);
	}
}
void add2(int L, int R, int to, int c, int cur) {
	if (L <= T[cur].L && R >= T[cur].R) {
		neigh[cur].emplace_back(to, c);
		return;
	}
	if (L <= T[ T[cur].pl ].R) {
		add2(L, R, to, c, T[cur].pl);
	}
	if (T[ T[cur].pr ].L <= R) {
		add2(L, R, to, c, T[cur].pr);
	}
}

