struct SegTree{ //0indexed
    vector<ll> nod;
    int size;
    SegTree(int x){
        size=1;
        while(x>size){
            size*=2;
        }
        nod=vector<ll>(size*2-1,LLONG_MAX/2);
    }
    ll update(int k){
        k+=size-1;
        ll ret =nod[k];//最下の処理
        while(k>0){
            k=(k-1)/2;
            ret = min(nod[k],ret); //下から上へ 
        }
        return ret;
    }
    void Update(int k,ll a){
        k+=size-1;
        nod[k]=a;//最下の処理
        while(k>0){
            k=(k-1)/2;
            nod[k]=a; //下から上へ 
        }
    }
    void query(int a,int b,int k,int l,int r,ll x){
        //[a,b)について
        //kは節点の番号,[l,r)はその節点がカバーする範囲
        if(r<=a||b<=l){ //[a,b)と[l,r)が重なって無いとき
            return;
        }
        if(a<=l && r<=b){ //[a,b)が[l,r)を完全に含んでいるとき
            nod[k] = min(nod[k],x);
        }
        else{
            query(a,b,k*2+1,l,(l+r)/2,x);
            query(a,b,k*2+2,(l+r)/2,r,x);
        }
    }
    void deb(){ //全ノードの出力
		for(int i=0;i<size*2-1;i++){
			if(i==size*2-2){
				cout << nod[i] << endl;
			}
			else{
				cout << nod[i] << ' ';
			}
		}
		return;
	}
};

