		long long x = rmq.query(l, r + 1) + c;
		long long y = rmq.query(r, r + 1);
		if(x < y) rmq.update(r, x);
	}
	long long ans = rmq.query(n - 1, n);
	if (ans==(1LL<<60)) {
		cout << -1 << endl;
	}
	else {
		cout << ans << endl;
	}


