// 0-indexed, [l, r)
template<class T = long long>
class SegmentTree {
    public :
        vector<T> __data;
        T __size;
        T initValue;
        function<T(T, T)> cmpFunc;

        SegmentTree (T size, T initValue = 100000000000000000LL, function<T(T, T)> cmpFunc = [](T l, T r){return min(l, r);}) {
            this->init(size, initValue, cmpFunc);
        };

        void init (T size, T initValue, function<T(T, T)> cmpFunc) {
            // 完全二分木にする
            T binSize = 0;
            while((1 << binSize) < size) {
                binSize++;
            }
            this->__size = (1 << binSize);
            this->initValue = initValue;
            this->cmpFunc = cmpFunc;

            this->__data.resize(this->__size * 2);
            for(T i = 0; i < this->__size * 2; i++) {
                this->__data[i] = initValue;
            }
        };

        /* メソッド */
        void update(T index, T value) {
            index += this->__size - 1;
            this->__data[index] = value;
            while(index > 0) {
                index = (index - 1) / 2;
                this->__data[index] = this->cmpFunc(this->__data[index * 2 + 1], this->__data[index * 2 + 2]);
            }
        };

        T __query(T qLeft, T qRight, T node, T left, T right) {
            if(right <= qLeft || qRight <= left) return initValue;
            if(qLeft <= left && right <= qRight) return this->__data[node];

            T leftVal = this->__query(qLeft, qRight, node * 2 + 1, left, (left + right) / 2);
            T rightVal = this->__query(qLeft, qRight, node * 2 + 2, (left + right) / 2, right);
            return this->cmpFunc(leftVal, rightVal);
        }

        // wrapper
        T query(T left, T right) {
            return this->__query(left, right, 0, 0, this->__size);
        };
};

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    llong N, M;
    cin >> N >> M;

    SegmentTree<llong> tree(N + 1);
    tree.update(1, 0);
    vector<tuple<llong, llong, llong>> edges(M);

    FOR(i, M) cin >> get<0>(edges[i]) >> get<1>(edges[i]) >> get<2>(edges[i]);
    sort(edges.begin(), edges.end());

    FOR(i, 10) {
        for(auto a : edges) {
            llong L, R, C;
            tie(L, R, C) = a;
            llong cost = tree.query(L, R + 1) + C;
            tree.update(R, min(cost, tree.query(R, R + 1)));
        }
    }

    llong ans = tree.query(N, N + 1);
    if(ans == INF) ans = -1;
    cout << ans << endl;

    return 0;
}

