struct Edge {
  int src, dst;
  ll cost;
  bool operator < ( const Edge &e ) const {
    if( src != e.src ) return src < e.src;
    return cost < e.cost;
  }
};



#define INF 1e18
SegmentTree seg;
ll tmp[MAX];

void compute() {
  {
    rep(i,N+1) tmp[i] = INF;
    seg.my_init(N,tmp);
    seg.update_min(0,1,0);
  }

  deque<Edge> edges;
  rep(i,M) edges.push_back((Edge){L[i],R[i],C[i]});
  sort(ALL(edges));

  while( !edges.empty() ) {
    Edge &e = edges.front(); edges.pop_front();
    ll mini = INF;
    if( e.src == 0 ) mini = 0;
    else mini = seg.query_max(e.src,e.src+1);
    if( debug ) {
      puts("");
      cout << "dp info---" << endl;
      rep(i,N) {
	cout << i << "-th : " << seg.query_max(i,i+1) << endl;
      }
      cout << "---" << endl;
      cout << "edge = " << e.src << "," << e.dst << ", cost = " << e.cost << endl;
      cout << "mini = " << mini << endl;
    }
    if( mini == INF ) {
      puts("-1");
      return;
    }
    if( debug ) {
      cout << "update [" << e.src << "," << e.dst << "] = " << mini+e.cost << endl;
    }
    seg.update_min(e.src,e.dst+1,mini+e.cost);
  }
  ll ans = seg.query_max(N-1,N);
  if( ans == INF ) puts("-1");
  else cout << ans << endl;
}


