    if (begin->second == INF_MAX) continue;
    ll length = begin->second + static_cast<ll>(distance);
    if (length >= last->second) continue;
    shortest[right] = length;

    while (begin != last) {
      if (length < begin->second) {
        begin = shortest.erase(begin);
      } else {
        begin++;
      }
    }
  }

  if (shortest[n] == INF_MAX) {
    cout << -1 << endl;
  } else {
