				seg[sl] = min(seg[sl], seg[l[a[i]] + p - 1] + c[a[i]]);
			if (sr % 2 > 0)
			{
				seg[sr] = min(seg[sr], seg[l[a[i]] + p - 1] + c[a[i]]);
				sr--;
			}
			sl = (sl - 1) / 2;
			sr = (sr - 1) / 2;
		}
		seg[sl] = min(seg[sl], seg[l[a[i]] + p - 1] + c[a[i]]);
	}
	sl = 0;
	sr = p;
	j = 0;
	while (j < p - 1)
	{
		seg[2 * j + 1] = min(seg[2 * j + 1], seg[j]);
		seg[2 * j + 2] = min(seg[2 * j + 2], seg[j]);
		if (n - 1 < (sr + sl) / 2)
		{
			sr = (sl + sr) / 2;
			j = 2 * j + 1;
		}
		else
		{
			sl = (sl + sr) / 2;
			j = 2 * j + 2;
		}
	}
	if (seg[n + p - 2] > 1000000000000015)
		printf("-1\n");
	else
		printf("%lld\n", seg[n + p - 2]);
	return 0;
}

