// Segment Tree
// セグメント木
// 区間最小
// i = 0～
#define SEGT_N ((1<<17)) // > 10^5
#define SEGT_INVALID (INT64_MAX)
typedef ll st;
st segt[SEGT_N*2];

void SEGTinit(void)
{
    for(int i=0;i<SEGT_N*2;i++) segt[i] = SEGT_INVALID;
}

void SEGTupdate(int i, st val)
{
    i = SEGT_N-1+i;
    segt[i] = min(segt[i],val);
    // segt[i] += val;
    while(i)
    {
        i = (i-1)/2;
        segt[i] = min(segt[i*2+1], segt[i*2+2]);
        // segt[i] = segt[i*2+1] + segt[i*2+2];
    }
}

st SEGTget_sub(int l, int r, int i, int il, int ir)
{
    if((ir < l) || (r < il) ) return SEGT_INVALID; // 被らない
    if((l <= il) && (ir<=r) )
    {
        return segt[i]; // 完全にかぶっている
    }else
    {
        st lv = SEGTget_sub(l,r,i*2+1,il, (il+ir+1)/2-1);
        st rv = SEGTget_sub(l,r,i*2+2, (il+ir+1)/2,ir);
        return min(lv,rv);
        // return lv+rv;
    }
}

st SEGTget(int l, int r)
{
    return SEGTget_sub(l,r,0,0,SEGT_N-1);
}

