#include <stdio.h>

typedef struct {
	int key, id;
} data;

typedef struct {
	data obj[100001];
	int size;
} max_heap;

void push(data x, max_heap* h)
{
	int i = h->size;
	data tmp;
	h->obj[(h->size)++] = x;
	while (1) {
		if (i == 0) break;
		else if (h->obj[i].key > h->obj[(i-1)/2].key) {
			tmp = h->obj[(i-1)/2];
			h->obj[(i-1)/2] = h->obj[i];
			h->obj[i] = tmp;
			i = (i - 1) / 2;
		} else break;
	}
}

data pop(max_heap* h)
{
	int i = 0, j;
	data output = h->obj[0], tmp;
	h->obj[0] = h->obj[--(h->size)];
	while (1) {
		if (i * 2 + 1 >= h->size) break;
		else if (i * 2 + 2 >= h->size) j = i * 2 + 1;
		else if (h->obj[i*2+1].key > h->obj[i*2+2].key) j = i * 2 + 1;
		else j = i * 2 + 2;
		if (h->obj[j].key > h->obj[i].key) {
			tmp = h->obj[j];
			h->obj[j] = h->obj[i];
			h->obj[i] = tmp;
			i = j;
		} else break;
	}
	return output;
}

void BIT_update(long long BIT[], int n, int i, long long k)
{
	while (i <= n) {
		if (BIT[i] > k) BIT[i] = k;
		i += (i & -i);
	}
}

long long BIT_min(long long BIT[], int r)
{
	long long min = BIT[r];
	while (r > 0) {
		if (BIT[r] < min) min = BIT[r];
		r -= (r & -r);
	}
	return min;
}

int main()
{
	int i, N, M, L[100001], R[100001], C[100001];
	scanf("%d %d", &N, &M);
	for (i = 1; i <= M; i++) scanf("%d %d %d", &(L[i]), &(R[i]), &(C[i]));

	data d;
	max_heap h;
	h.size = 0;
	for (i = 1; i <= M; i++) {
		d.key = R[i];
		d.id = i;
		push(d, &h);
	}

	const long long sup = (long long)1 << 60;
	long long min, BIT[100001];
	for (i = 1; i <= N; i++) BIT[i] = sup;
	BIT_update(BIT, N, N, 0);
	while (h.size > 0) {
		d = pop(&h);
		min = BIT_min(BIT, R[d.id]);
		if (BIT_min(BIT, L[d.id]) > min + C[d.id]) BIT_update(BIT, N, L[d.id], min + C[d.id]);
	}

	if (BIT_min(BIT, 1) < sup) printf("%lld\n", BIT_min(BIT, 1));
	else printf("-1\n");
	fflush(stdout);
	return 0;
}

