    }

    val cost = LongArray(N) { Long.MAX_VALUE }
    cost[0] = 0L
    val queue = ArrayDeque<Int>()

    queue.add(0)

    while (!queue.isEmpty()) {
        val node = queue.poll()!!

        for ((k, v) in edges[node]) {
            if (cost[k] > cost[node] + v) {
                cost[k] = cost[node] + v
                queue.add(k)
            }
        }
    }

    if (cost[N - 1] == Long.MAX_VALUE) {
        println(-1)
    } else {
        println(cost[N - 1])
    }
}

