    public static void solve(){
        //TODO:Solve problem like ***
        Scanner sc=new Scanner();
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] l = new int[m];
        int[] r = new int[m];
        int[] c = new int[m];
        for (int i = 0; i < m; i++) {
            l[i] = sc.nextInt()-1;
            r[i] = sc.nextInt()-1;
            c[i] = sc.nextInt();
        }
        List<Container> list = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            list.add(new Container(l[i], r[i], c[i]));
        }
        list.sort(Comparator.comparingInt((Container con) -> con.l).thenComparing(con -> con.r).thenComparing(con -> con.c));
        long[] b = new long[n];
        b[1] = INF;
        int minInfIndex=1;
        BinaryIndexedTree bit = new BinaryIndexedTree(b);
        for (Container con : list) {
//            put("con", "l", con.l, "r", con.r, "c", con.c);
            //okはcon.l以上ノードのうち今のconを使えばより低いコストで移動できるノードのうちの最小のもの
            int ok=n;
            int ng = con.l - 1;
            while (abs(ok - ng) > 1) {
                int mid = (ok + ng) / 2;
                if (bit.sum(mid) >= bit.sum(con.l)+con.c) {
                    ok=mid;
                }else{
                    ng=mid;
                }
            }
//            put("ok",ok);
            if(minInfIndex<ok){
                //INFが[1:n]の間に挟まる(到達不可)
                put(-1);
                return;
            }
            if(ok>con.r||ok==con.l)continue;//このconを使う必要はない
            if(minInfIndex==ok){
                bit.add(ok,-INF);
            }
            long prev = bit.sum(ok);
            long next=bit.sum(con.l)+con.c;
//            put("prev", prev);
            bit.add(ok, -prev);
            bit.add(ok, next);
            bit.add(con.r + 1, -next);
            bit.add(con.r + 1, prev);
            if (minInfIndex == ok) {
                bit.add(con.r+1,INF);
                minInfIndex = con.r + 1;
            }
//            put(bit);
//            put("----------");
        }
//        put(bit);
        if(minInfIndex<n){
            put(-1);
            return;
        }
        put(bit.sum(n - 1));




    }
