        // 重み付きグラフの始点からの最短経路を求める　←　有向・無方向どちらも大丈夫
        // 優先度付きキューを使った版（速い）
        final long INF = 1000000000000000000L;
        final int WHITE = 0, GRAY = 1, BLACK = 2;
    													// グラフの隣接リスト(頂点と辺の長さ）
        GraphWith G = new GraphWith();
														// 辺の長さの短い順で並ぶ、優先度付きキュー
    	PriorityQueue<PPL> PQ = new PriorityQueue<PPL>(comparing(PPL::getKey));

        int N, M;										// 頂点の数、辺の数
    	long[] d;										// d[3] なら 頂点３ から始点までの最短コストを記録する
    	int[] color;									// 白：未処理　黒：処理済み　グレー：

        // 先頭の頂点番号を指定する　０～
        void dijkstra(int s) {
        	Arrays.fill(d, INF);						// 変数の初期化
        	Arrays.fill(color, WHITE);
        	d[s] = 0;									// 先頭は　０
        	PQ.add(new PPL(0,s));						// 優先度付きキューにいれるのは　辺の長さと頂点のペア（並びに注意）
        	int u, v;
        	PPL p;
        	while(!PQ.isEmpty()) {
        		p = PQ.poll();							// 始点に一番近い頂点を取り出して、消す
        		u = (int)p.getVal();					// 頂点の番号
        		color[u] = BLACK;

        		// 最小値を取り出して、それが最短でなければ無視
        		if(d[u] < p.getKey())	continue;

        		if(G.contains(u)) {
	        		for(PP wk : G.get(u)) {
	        			v = wk.getKey();					// u につながる頂点
	        			if(color[v] == BLACK)	continue;	// 処理済みなら　次へ
	        			if(d[v] > d[u] + wk.getVal()) {		// wk.getVal() が辺の長さ
	        				d[v] = d[u] + wk.getVal();
	        				PQ.add(new PPL(d[v], v));
	        			}
	        		}
        		}
        	}
        }

        public void solve() {
    		N = ni();
    		M = ni();
    		d = new long[N];
    		color = new int[N];
    		int a, b, c;
    		for(int i=0; i < M; i++) {
    			a = ni() - 1;
    			b = ni() - 1;
    			c = ni();
    			G.add(a, new PP(b, c));
    			G.add(b, new PP(a, c));
    		}
    		for (int i = N - 1; i > 0; i--) {
				G.add(i, new PP(i-1, 0));
			}
    		// ダイクストラ
    		dijkstra(0);

    		prn(d[N-1] == INF ? -1 : d[N-1]);
        }

