public class Main {
	static class Node {
		int id;
		Map<Integer, Long> edges;

		Node(int id) {
			this.id = id;
			this.edges = new HashMap<>();
		}

		void setEdge(int dst, long c) {
			if (!this.edges.containsKey(dst)) {
				this.edges.put(dst, c);
			} else if (this.edges.get(dst) > c) {
				this.edges.put(dst, c);
			}
		}

		Set<Edge> getEdges() {
			Set<Edge> set = new HashSet<>();
			for (Integer dst : this.edges.keySet()) {
				set.add(new Edge(this.id, dst, this.edges.get(dst)));
			}
			this.edges.clear();
			return set;
		}
	}

	static class Edge {
		int src, dst;
		long c;

		Edge(int src, int dst, long c) {
			this.src = src;
			this.dst = dst;
			this.c = c;
		}
	}

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		int N, M;
		String[] tokens = in.readLine().split(" ");
		N = Integer.parseInt(tokens[0]);
		M = Integer.parseInt(tokens[1]);
		Node[] nodes = new Node[N];
		for (int i = 0; i < N; ++i) {
			nodes[i] = new Node(i);
		}
		// 区間の中間からの処理を可能とするための便宜上の辺を追加
		for( int i = 1; i < N; ++i) {
			nodes[i].setEdge(i-1, 0L);
		}
		for (int i = 0; i < M; ++i) {
			tokens = in.readLine().split(" ");
			int src = Integer.parseInt(tokens[0]) - 1;
			int dst = Integer.parseInt(tokens[1]) - 1;
			long c = Long.parseLong(tokens[2]);
			nodes[src].setEdge(dst, c);
		}
		/*
		Queue<Edge> queue = new PriorityQueue<>(new Comparator<Edge>() {
			@Override
			public int compare(Edge o1, Edge o2) {
				return Integer.compare(o1.dst, o2.dst);
			}
		});
		*/
		Queue<Edge> queue = new ArrayDeque<>();
		// queueにrootから出ているedgeを追加する
		queue.addAll(nodes[0].getEdges());
		long[] distances = new long[N];
		Arrays.fill(distances, Long.MAX_VALUE / 2);
		distances[0] = 0;
		while (!queue.isEmpty()) {
			Edge edge = queue.poll();
			distances[edge.dst] = Math.min(distances[edge.dst], distances[edge.src] + edge.c);
			queue.addAll(nodes[edge.dst].getEdges());
		}
		if (distances[N - 1] >= Long.MAX_VALUE / 2) {
			System.out.println(-1);
		} else {
			System.out.println(distances[N - 1]);
		}
	}
}

import java.io.*;
import java.util.*;
import java.math.*;

class Main {
    public static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    public static PrintWriter pw = new PrintWriter(System.out);
    public static String line;
    public static StringTokenizer st;
    public static ArrayList<ArrayList<Integer>> adjList;
    public static int[] dx = {-1, 0, 1, 0, -1, 1, 1, -1, 0};
    public static int[] dy = {0, 1, 0, -1, 1, 1, -1, -1, 0};
    public static int INF = 0x3f3f3f3f;
    public static int MOD = 1000000007;
    public static long LINF = 0x3f3f3f3f3f3f3f3fL;

    public static void main(String[] args) throws Exception {
        st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        ArrayList<Interval> A = new ArrayList<Interval>();
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken()) - 1;
            int b = Integer.parseInt(st.nextToken()) - 1;
            int cost = Integer.parseInt(st.nextToken());

            A.add(new Interval(a, 0, cost, i));
            A.add(new Interval(b, 1, cost, i));
        }

        Collections.sort(A);

        long[] dist = new long[N];
        Arrays.fill(dist, LINF);
        dist[0] = 0;

        int curIndex = 0;
        TreeMap<Long, Integer> d = new TreeMap<Long, Integer>();
        long[] idxValue = new long[M];
        Arrays.fill(idxValue, -1);

        for (int i = 0; i < N; i++) {
            if (d.size() > 0) {
                dist[i] = Math.min(dist[i], d.firstKey());                
            }

            while (curIndex < A.size() && A.get(curIndex).a == i) {
                Interval cur = A.get(curIndex);
                if (cur.b == 0) {
                    long total = 0;
                    if (i != 0) {
                        if (d.size() == 0) {
                            curIndex++;
                            continue;
                        }
                        total = d.firstKey();
                    }
                    long sum = total + cur.cost;
                    if (!d.containsKey(sum)) {
                        d.put(sum, 1);
                    } else {
                        d.put(sum, d.get(sum) + 1);
                    }
                    idxValue[cur.id] = sum;
                } else {
                    long sum = idxValue[cur.id];
                    if (d.containsKey(sum)) {
                        if (d.get(sum) > 1) {
                            d.put(sum, d.get(sum) - 1);
                        } else {
                            d.remove(sum);
                        }
                    }
                }
                curIndex++;
            }
        }

        pw.println(dist[N-1] == LINF ? -1 : dist[N-1]);

        pw.close();
        br.close();
    }
}

class Interval implements Comparable<Interval>{
    public int a, b, cost, id;

    Interval(int _a, int _b, int _cost, int id){
        a = _a;
        b = _b;
        cost = _cost;
        this.id = id;
    }

    public String toString(){
        return a + " " + b + " " + cost;
    }

    public int compareTo(Interval p){
        if (a != p.a) return a < p.a ? -1 : 1;
        if (b != p.b) return b < p.b ? -1 : 1;
        if (cost != p.cost) return cost < p.cost ? -1 : 1;
        return 0;
    }
}

