  static PrintWriter out = new PrintWriter(System.out);
  public static void main(String args[]){
    int n=sc.nextInt();
    int m=sc.nextInt();
    Edge[] es=new Edge[m];
    for(int i=0;i<m;i++){
      es[i]=new Edge(sc.nextInt()-1,sc.nextInt()-1,sc.nextInt());
    }
    long[] dp=new long[n];
    long ans=calc(n-1,es,dp);
    out.println(ans);
    out.flush();
  }
  static long calc(int h,Edge[] es,long[] dp){
    if(h==0){
      return 0;
    }
    if(dp[h]!=0){
      return dp[h];
    }
    long min=Long.MAX_VALUE;
    for(int i=0;i<es.length;i++){
      if(es[i].t(h)){
        long are=calc(es[i].l,es,dp);
        if(are==-1){
          return -1;
        }
        min=Math.min(are+es[i].c,min);
      }
    }
    if(min==Long.MAX_VALUE){
      return -1;
    }
    dp[h]=min;
    return dp[h];
  }
  static class Edge{
    int l;
    int r;
    int c;
    Edge(int le,int ri,int co){
      l=le;
      r=ri;
      c=co;
    }
    boolean t(int p){
      return (l<p&&p<=r);
    }
  }
