  static Scnr sc = new Scnr();
  static PrintWriter out = new PrintWriter(System.out);
  public static void main(String args[]){
    int n=sc.nextInt();
    int m=sc.nextInt();
    int[] l=new int[m];
    int[] r=new int[m];
    int[] c=new int[m];
    Node[] ns=new Node[n];
    for(int i=0;i<n;i++){
      ns[i]=new Node(m);
    }
    for(int i=0;i<m;i++){
      l[i]=sc.nextInt()-1;
      r[i]=sc.nextInt()-1;
      c[i]=sc.nextInt();
      for(int j=l[i]+1;j<=r[i];j++){
        ns[j].fid.add(l[i]);
        ns[j].fco.add(c[i]);
      }
    }
    long[] dp=new long[n];
    long ans=calc(n-1,ns,dp);
    out.println(ans);
    out.flush();
  }
  static long calc(int h,Node[] ns,long[] dp){
    if(h==0){
      return 0;
    }
    if(dp[h]!=0){
      return dp[h];
    }
    if(ns[h].fid.size()==0){
      return -1;
    }
    long min=Long.MAX_VALUE;
    for(int i=0;i<ns[h].fid.size();i++){
      long are=calc(ns[h].fid.get(i),ns,dp);
      if(are==-1){
        return -1;
      }
      min=Math.min(are+ns[h].fco.get(i),min);
    }
    dp[h]=min;
    return dp[h];
  }
  static class Node{
    List<Integer> fid;
    List<Integer> fco;
    Node(int m){
      fid=new ArrayList<Integer>(m);
      fco=new ArrayList<Integer>(m);
    }
  }
