	private class Edge implements Comparable<Edge>{
		int L, R, C;
		Edge(int l, int r, int c) {
			L = l;
			R = r;
			C = c;
		}
		@Override
		public int compareTo(Edge o) {
			return Integer.compare(L, o.L);
		}
	}
	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * 第二回全国統一プログラミング王決定戦予選 D問題
		 * 考察メモ
		 * まず、頂点2までの距離を考える
		 * これはL_i=1, L_2≧2なる物があった時、その中のC_i最小
		 * 次に頂点3までの距離を考える
		 * これはL_i=1, R_i≧3なるもののC_i最小とL_i=2, R_i≧3におけるC_i最小+D_2のより小さい方
		 * ところで前者は前もって値を配ることができて
		 * つまり、L_i昇順にソートするとする
		 * で、minになるように併合していく
		 * 区間minができれば良いので遅延セグ木かな
		 *
		 */
		int N = io.nextInt(), M = io.nextInt();
		final long INF = Long.MAX_VALUE >> 1;
		Edge[] edge = new Edge[M];
		for (final int i : IntRange.open(M)) edge[i] = new Edge(io.nextInt(), io.nextInt(), io.nextInt());
		DualSegmentTree<Long> segment = new DualSegmentTree<Long>(N, INF, new Minimum<Long>());
		segment.update(0L, 0);
		Arrays.sort(edge);
		for (Edge i : edge) {
			if (segment.get(i.L - 1) >= INF) continue;
			segment.update(segment.get(i.L - 1) + i.C, i.L, i.R);
		}
		long ans = segment.get(N - 1);
		if (ans >= INF) ans = -1;
		io.println(ans);

	}

