	public class Minimum<T extends Comparable<T>> implements Monoid<T>, Commutative<T>{

		@Override
		public T apply(T left, T right) {
			if (left == null) return right;
			else if (right == null) return left;
			return left.compareTo(right) < 0 ? left : right;
		}

		@Override
		public T unit() {
			return null;
		}

		@Override
		public T hyper(T element, int repeat) {
			return element;
		}

	}

	public interface SegmentTreeInterface<T, E> {
		/**
		 * データを更新します。
		 * @param dat 更新するデータ
		 * @param index 更新する場所
		 */
		public void update(E dat, int index);
		/**
		 * 区間[left, right)のデータを更新します。
		 * @param dat 更新するデータ
		 * @param left 更新する場所の左区間
		 * @param right 更新する場所の右区間
		 */
		public void update(E dat, int left, int right);
		/**
		 * 全ての値を取得します。
		 * @return 現在の値
		 */
		public Object[] get();
		/**
		 * 全ての値を取得します。
		 * @param array データを格納する配列
		 * @return 現在の値
		 */
		public T[] get(T[] array);
		/**
		 * 指定した場所の値を取得します。
		 * @param index 取得したい場所
		 * @return その場所の値
		 */
		public T get(int index);
		/**
		 * 指定した値を除く場所の値を取得します。
		 * @param index 取得しない場所
		 * @return 全体からindexを取り除いた値
		 */
		public default T getAvoid(int index) {
			return getAvoid(index, index + 1);
		}
		/**
		 * 指定した範囲の合計を取得します。
		 * @param left 範囲の左区間
		 * @param right 範囲の右区間
		 * @return 半開区間[left, right)の合計
		 */
		public T get(int left, int right);
		/**
		 * 指定した範囲を除く区間の合計を取得します。
		 * @param left 範囲の左区間
		 * @param right 範囲の右区間
		 * @return 半開区間[0, left)+[right, size)の合計
		 */
		public T getAvoid(int left, int right);
		/**
		 * 全区間で二分探索を行います。
		 * @param f 単調性を持つ関数
		 * @return 半開区間[0, size)において関数fがtrueを返す最大の値(無ければleft-1)
		 */
		public default int binarySearch(Predicate<T> f) {
			return binarySearch(0, size(), f);
		}

		/**
		 * 指定した範囲で二分探索を行います。
		 * @param left 範囲の左区間
		 * @param f 単調性を持つ関数
		 * @return 半開区間[left, size)において関数fがtrueを返す最大の値(無ければleft-1)
		 */
		public default int binarySearch(int left, Predicate<T> f) {
			return binarySearch(left, size(), f);
		}
		/**
		 * 指定した範囲で二分探索を行います。
		 * @param left 範囲の左区間
		 * @param right 範囲の右区間
		 * @param f 単調性を持つ関数
		 * @return 半開区間[left, right)において関数fがtrueを返す最大の値(無ければleft-1)<br>
		 * ただしleft>rightなら、半開区間[right, left)において関数fがtrueを返す最小の値(無ければleft)
		 */
		public int binarySearch(int left, int right, Predicate<T> f);
		/**
		 * 要素数を返します。
		 * @return 要素数
		 */
		public int size();
	}

	/**
	 * 双対セグメント木です。<br>
	 * 範囲更新をO(logN)、1点取得をO(logN)でできるデータ構造です。
	 * @author 31536000
	 *
	 * @param <T> 範囲更新及び1点取得を行いたいクラス
	 */
	public static class DualSegmentTree<T> implements SegmentTreeInterface<T, T>{
		private final Monoid<T> semigroup; // 演算関数
		private final Object dat[]; // データ
		private final int size;

		/**
		 * 双対セグメント木を構築します。
		 * @param N 要素数
		 * @param dat 初期値
		 * @param semigroup 演算関数
		 */
		public DualSegmentTree(int N, T dat, Monoid<T> semigroup) {
			this.semigroup = semigroup;
			size = N;
			this.dat = new Object[Integer.highestOneBit(N) << 2]; // 要素数を超える最小の2冪*2
			Arrays.fill(this.dat, this.dat.length >> 1, (this.dat.length >> 1) + N, dat);
			Arrays.fill(this.dat, (this.dat.length >> 1) + N, this.dat.length, semigroup.unit());
		}

		/**
		 * 双対セグメント木を構築します。
		 * @param dat 初期値
		 * @param semigroup 演算関数
		 */
		public DualSegmentTree(T[] dat, Monoid<T> semigroup) {
			this.semigroup = semigroup;
			size = dat.length;
			this.dat = new Object[Integer.highestOneBit(dat.length) << 2]; // 要素数を超える最小の2冪*2
			System.arraycopy(dat, 0, this.dat, this.dat.length >> 1, dat.length); // 最下段を埋める
			Arrays.fill(dat, (this.dat.length >> 1) + dat.length, this.dat.length, semigroup.unit());
		}

		/**
		 * 双対セグメント木を構築します。
		 * @param N 要素数
		 * @param dat 初期値
		 * @throws ClassCastException 演算関数が定義されていなければ返す
		 */
		@SuppressWarnings("unchecked")
		public DualSegmentTree(int N, T dat) throws ClassCastException {
			this(N, dat, (Monoid<T>)dat);
		}

		/**
		 * 双対セグメント木を構築します。
		 * @param dat 初期値
		 * @throws ClassCastException 演算関数が定義されていなければ返す
		 */
		@SuppressWarnings("unchecked")
		public DualSegmentTree(T dat[]) throws ClassCastException {
			this(dat, (Monoid<T>)dat[0]);
		}

		@SuppressWarnings("unchecked")
		private void lazy(int index) {
			dat[index << 1] = semigroup.apply((T)dat[index << 1], (T)dat[index]);
			dat[index << 1 | 1] = semigroup.apply((T)dat[index << 1 | 1], (T)dat[index]);
			dat[index] = semigroup.unit();
		}

		/**
		 * データを更新します。
		 * @param data 更新するデータ
		 * @param left 更新する場所の左閉区間
		 * @param right 更新する場所の右開区間
		 */
		@Override
		public void update(T data, int left, int right) {
			if (left >= right || right > size) throw new IllegalArgumentException("[" + left + ", " + right + ") is undefined.");
			int mid = left ^ right, m = 1, l, r, length = this.dat.length >> 1;
			while ((mid & length) == 0) { // 共通区間
				if ((left & length) != 0) {
					left &= ~length;
					right &= ~length;
					++ m;
				}
				lazy(m);
				m <<= 1;
				length >>= 1;
			}
			l = m;
			int lengthL = length;
			while(left != 0) { // 左側評価
				lazy(l);
				l <<= 1;
				lengthL >>= 1;
				if ((left & lengthL) == 0) {
					@SuppressWarnings("unchecked")
					T t = (T)dat[l + 1];
					dat[l + 1] = semigroup.apply(t, data);
				} else {
					left &= ~lengthL;
					++ l;
				}
			}
			@SuppressWarnings("unchecked")
			T t = (T)dat[l];
			dat[l] = semigroup.apply(t, data);
			r = m + 1;
			int lengthR = length;
			right &= ~lengthR;
			while(right != 0) { // 右側評価開始
				lazy(r);
				r <<= 1;
				lengthR >>= 1;
				if ((right & lengthR) != 0) {
					right &= ~lengthR;
					@SuppressWarnings("unchecked")
					T t1 = (T)dat[r];
					dat[r] = semigroup.apply(t1, data);
					++ r;
				}
			}
		}

		@SuppressWarnings("unchecked")
		private void update() {
			for (int i = 1, l = dat.length >> 1;i < l;++ i) {
				dat[i << 1] = semigroup.apply((T)dat[i << 1], (T)dat[i]);
				dat[i << 1 | 1] = semigroup.apply((T)dat[i << 1 | 1], (T)dat[i]);
				dat[i] = semigroup.unit();
			}
		}

		/**
		 * 全ての値を取得します。
		 * @return 現在の値
		 */
		@Override
		public Object[] get() {
			update();
			Object[] ret = new Object[size];
			System.arraycopy(dat, dat.length >> 1, ret, 0, size);
			return  ret;
		}

		/**
		 * 全ての値を取得します。
		 * @param array データを格納する配列
		 * @return 現在の値
		 */
		@Override
		public T[] get(T[] array) {
			update();
			if (array.length < size) {
				@SuppressWarnings("unchecked")
				T[] ret  = (T[])Arrays.copyOfRange(dat, dat.length >> 1, (dat.length >> 1) + size, array.getClass());
				return ret;
			}
			System.arraycopy(dat, dat.length >> 1, array, 0, size);
			return array;
		}

		/**
		 * 指定した場所の値を取得します。
		 * @param index 取得したい場所
		 * @return その場所の値
		 */
		@Override
		public T get(int index) {
			T ret = null;
			for (int i = dat.length >> 1 | index; i > 0; i >>= 1) {
				@SuppressWarnings("unchecked")
				T u = (T)dat[i];
				ret = semigroup.apply(ret, u);
			}
			return ret;
		}

		/**
		 * 要素数を返します。
		 * @return 要素数
		 */
		@Override
		public int size() {
			return size;
		}

		@Override
		public void update(T dat, int index) {
			update(dat, index, index + 1);
		}

		@Override
		public T get(int left, int right) {
			throw new UnsupportedOperationException();
		}

		@Override
		public int binarySearch(int left, int right, Predicate<T> f) {
			throw new UnsupportedOperationException();
		}

		@Override
		public T getAvoid(int left, int right) {
			throw new UnsupportedOperationException();
		}
	}

	public static class FastIO {
		private final InputStream in;
		private final byte[] buffer = new byte[1024];
		private int read = 0;
		private int length = 0;
		public final PrintWriter out;
		public final PrintWriter err;
		private boolean autoFlush = false;

		public FastIO() {
			this(System.in, System.out, System.err);
		}

		public FastIO(InputStream in, PrintStream out, PrintStream err) {
			this.in = in;
			this.out = new PrintWriter(out, false);
			this.err = new PrintWriter(err, false);
		}

		public void setAutoFlush(boolean flush) {
			autoFlush = flush;
		}

		private boolean hasNextByte() {
			if (read < length) return true;
			read = 0;
			try {
				length = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			return length > 0;
		}

		private int readByte() {
			return hasNextByte() ? buffer[read++] : -1;
		}

		private static boolean isPrintableChar(int c) {
			return 33 <= c && c <= 126;
		}

		private static boolean isNumber(int c) {
			return '0' <= c && c <= '9';
		}

		public boolean hasNext() {
			while (hasNextByte() && !isPrintableChar(buffer[read])) read++;
			return hasNextByte();
		}

		public char nextChar() {
			if (!hasNextByte())  throw new NoSuchElementException();
			return (char)readByte();
		}

		public char[][] nextChar(int height) {
			char[][] ret = new char[height][];
			for (int i = 0;i < ret.length;++ i) ret[i] = next().toCharArray();
			return ret;
		}

		public String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b;
			while (isPrintableChar(b = readByte())) sb.appendCodePoint(b);
			return sb.toString();
		}

		public String nextLine() {
			StringBuilder sb = new StringBuilder();
			int b;
			while(!isPrintableChar(b = readByte()));
			do sb.appendCodePoint(b); while(isPrintableChar(b = readByte()) || b == ' ');
			return sb.toString();
		}

		public long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (!isNumber(b)) throw new NumberFormatException();
			while (true) {
				if (isNumber(b)) {
					n *= 10;
					n += b - '0';
				} else if (b == -1 || !isPrintableChar(b)) return minus ? -n : n;
				else throw new NumberFormatException();
				b = readByte();
			}
		}

		public int nextInt() {
			long nl = nextLong();
			if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
			return (int) nl;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextInt(int width) {
			int[] ret = new int[width];
			for (int i = 0;i < width;++ i) ret[i] = nextInt();
			return ret;
		}

		public int[] nextInts() {
			return nextInts(" ");
		}

		public int[] nextInts(String parse) {
			String[] get = nextLine().split(parse);
			int[] ret = new int[get.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = Integer.valueOf(get[i]);
			return ret;
		}

		public long[] nextLong(int width) {
			long[] ret = new long[width];
			for (int i = 0;i < width;++ i) ret[i] = nextLong();
			return ret;
		}

		public long[] nextLongs() {
			return nextLongs(" ");
		}

		public long[] nextLongs(String parse) {
			String[] get = nextLine().split(parse);
			long[] ret = new long[get.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = Long.valueOf(get[i]);
			return ret;
		}

		public int[][] nextInt(int width, int height) {
			int[][] ret = new int[height][width];
			for (int i = 0, j;i < height;++ i) for (j = 0;j < width;++ j) ret[i][j] = nextInt();
			return ret;
		}

		public long[][] nextLong(int width, int height) {
			long[][] ret = new long[height][width];
			for (int i = 0, j;i < height;++ i) for (j = 0;j < width;++ j) ret[j][i] = nextLong();
			return ret;
		}

		public boolean[] nextBoolean(char T) {
			char[] s = next().toCharArray();
			boolean[] ret = new boolean[s.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = s[i] == T;
			return ret;
		}

		public boolean[][] nextBoolean(char T, int height) {
			boolean[][] ret = new boolean[height][];
			for (int i = 0;i < ret.length;++ i) {
				char[] s = next().toCharArray();
				ret[i] = new boolean[s.length];
				for (int j = 0;j < ret[i].length;++ j) ret[i][j] = s[j] == T;
			}
			return ret;
		}

		public Point nextPoint() {
			return new Point(nextInt(), nextInt());
		}

		public Point[] nextPoint(int width) {
			Point[] ret = new Point[width];
			for (int i = 0;i < width;++ i) ret[i] = nextPoint();
			return ret;
		}

		@Override
		protected void finalize() throws Throwable {
			try {
				super.finalize();
			} finally {
				in.close();
				out.close();
				err.close();
			}
		}

		public boolean print(boolean b) {
			out.print(b);
			if (autoFlush) flush();
			return b;
		}

		public Object print(boolean b, Object t, Object f) {
			return b ? print(t) : print(f);
		}

		public char print(char c) {
			out.print(c);
			if (autoFlush) flush();
			return c;
		}

		public char[] print(char[] s) {
			out.print(s);
			return s;
		}

		public double print(double d) {
			out.print(d);
			if (autoFlush) flush();
			return d;
		}

		public double print(double d, int length) {
			if (d < 0) {
				out.print('-');
				d = -d;
			}
			d += Math.pow(10, -length) / 2;
			out.print((long)d);
			out.print('.');
			d -= (long)d;
			for (int i = 0;i < length;++ i) {
				d *= 10;
				out.print((int)d);
				d -= (int)d;
			}
			if (autoFlush) flush();
			return d;
		}

		public float print(float f) {
			out.print(f);
			if (autoFlush) flush();
			return f;
		}

		public int print(int i) {
			out.print(i);
			if (autoFlush) flush();
			return i;
		}

		public long print(long l) {
			out.print(l);
			if (autoFlush) flush();
			return l;
		}

		public Object print(Object obj) {
			if (obj.getClass().isArray()) {
				if (obj instanceof boolean[][]) print(obj, "\n", " ");
				else if (obj instanceof byte[][]) print(obj, "\n", " ");
				else if (obj instanceof short[][]) print(obj, "\n", " ");
				else if (obj instanceof int[][]) print(obj, "\n", " ");
				else if (obj instanceof long[][]) print(obj, "\n", " ");
				else if (obj instanceof float[][]) print(obj, "\n", " ");
				else if (obj instanceof double[][]) print(obj, "\n", " ");
				else if (obj instanceof char[][]) print(obj, "\n", " ");
				else if (obj instanceof Object[][]) print(obj, "\n", " ");
				else print(obj, " ");
			} else {
				out.print(obj);
				if (autoFlush) flush();
			}
			return obj;
		}

		public String print(String s) {
			out.print(s);
			if (autoFlush) flush();
			return s;
		}

		public Object print(Object array, String... parse) {
			print(array, 0, parse);
			if (autoFlush) flush();
			return array;
		}

		private Object print(Object array, int check, String... parse) {
			if (check >= parse.length) {
				if (array.getClass().isArray()) throw new IllegalArgumentException("not equal dimension");
				print(array);
				return array;
			}
			String str = parse[check];
			if (array instanceof Object[]) {
				Object[] obj = (Object[]) array;
				if (obj.length == 0) return array;
				print(obj[0], check + 1, parse);
				for (int i = 1;i < obj.length;++ i) {
					print(str);
					print(obj[i], check + 1, parse);
				}
				return array;
			}
			if (array instanceof Collection) {
				Iterator<?> iter = ((Collection<?>)array).iterator();
				if (!iter.hasNext()) return array;
				print(iter.next(), check + 1, parse);
				while(iter.hasNext()) {
					print(str);
					print(iter.next(), check + 1, parse);
				}
				return array;
			}
			if (!array.getClass().isArray()) throw new IllegalArgumentException("not equal dimension");
			if (check != parse.length - 1) throw new IllegalArgumentException("not equal dimension");
			if (array instanceof boolean[]) {
