	private static final long MOD = 1000000007;
	private static final long inf = 100000000000L;

	void solve() {
		int T = 1;
		for (int i = 0; i < T; i++)
			solve(i);
	}

	int n;

	void solve(int T) {
		n = ni();
		int m = ni();
		List<int[]> e[] = new List[n];

		for (int i = 0; i < n; i++)
			e[i] = new ArrayList<int[]>();

		for (int i = 0; i < m; i++)
			e[ni() - 1].add(new int[] { ni() - 1, ni() });

		PriorityQueue<int[]> p = new PriorityQueue<int[]>(new Comparator<int[]>() {

			@Override
			public int compare(int[] arg0, int[] arg1) {
				// TODO Auto-generated method stub
				return arg0[0]-arg1[0];
			}
		});

		int dis = 0;
		for (int i = 0; i < n; i++) {
			while (!p.isEmpty() && p.peek()[1] < i)
				p.poll();
			if (i > 0 && p.isEmpty()) {
				out.print(-1);
				return;
			}
			dis = i == 0 ? 0 : p.peek()[0];
			for (int[] e0 : e[i]) {
				p.add(new int[] { dis + e0[1], e0[0] });
			}
		}
		out.println(dis);
	}

	// a^b
	long power(long a, long b) {
		long x = 1, y = a;
		while (b > 0) {
			if (b % 2 != 0) {
				x = (x * y) % MOD;
			}
			y = (y * y) % MOD;
			b /= 2;
		}
		return x % MOD;
	}

	private long gcd(long a, long b) {
		while (a != 0) {
			long tmp = b % a;
			b = a;
			a = tmp;
		}
		return b;
	}

