	static void solve() {
		int n = ni(), m = ni();
		g = new ArrayList[n];
		for(int i=0;i<n;i++)g[i] = new ArrayList<>();
		for(int i=0;i<n-1;i++) {
			g[i+1].add(new Edge(i, 0L));
		}
		for(int i=0;i<m;i++) {
			int l = ni()-1, r = ni()-1, c = ni();
			g[l].add(new Edge(r, (long)c));
		}
		dist = new long[n];
