	static void dijkstra(int v){
		fill(dist, linf);
		dist[v] = 0;
		PriorityQueue<Vertex> q = new PriorityQueue<>((v1, v2)->v1.dist.compareTo(v2.dist));
		q.add(new Vertex(v, 0L));
		while(!q.isEmpty()) {
			Vertex now = q.poll();
			if(now.dist>dist[now.id])continue;
			for(Edge e:g[now.id]) {
				if(dist[e.to]>dist[now.id] + e.cost) {
					dist[e.to] = dist[now.id] + e.cost;
					q.add(new Vertex(e.to, dist[e.to]));
				}
			}
		}
	}

