  static long calc(int h,Edge[] es,long[] dp){
    if(h==0){
      return 0;
    }
    if(dp[h]!=0){
      return dp[h];
    }
    long min=Long.MAX_VALUE;
    for(int i=0;i<es.length;i++){
      if(es[i].t(h)){
        long are=calc(es[i].l,es,dp);
        min=Math.min(are+es[i].c,min);
      }
    }
    if(min==Long.MAX_VALUE){
      return -1;
    }
    dp[h]=min;
    return dp[h];
  }
  static class Edge{
    int l;
    int r;
    int c;
    Edge(int le,int ri,int co){
      l=le;
      r=ri;
      c=co;
    }
    boolean t(int p){
      return (l<p&&p<=r);
    }
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

public class Main {

    public static void main(String[] args) throws Exception {
        try (Reader r = new Reader(System.in)) {
            int N = r.i();
            int M = r.i();

            long[][] D = new long[N + 1][N + 1];
            for (int i = 0; i <= N; i++) {
                for (int j = 0; j <= N; j++) {
                    D[i][j] = Long.MAX_VALUE;
                }
            }

            for (int m = 0; m < M; m++) {
                int L = r.i() - 1;
                int R = r.i() - 1;
                long C = r.l();

                for (int s = L; s < R; s++) {
                    for (int t = s + 1; t <= R; t++) {
                        D[s][t] = Math.min(D[s][t], C);
                        D[t][s] = Math.min(D[t][s], C);
                    }
                }
            }

            List<Edge>[] edges = initDijkstra(N);
            for (int i = 0; i < N; i++) {
                for (int j = i + 1; j < N; j++) {
                    if (D[i][j] != Long.MAX_VALUE) {
                        edges[i].add(new Edge(j, D[i][j]));
                        edges[j].add(new Edge(i, D[i][j]));
                    }
                }
            }

            long[] distances = execDijkstra(edges, 0);

            System.out.println(distances[N - 1]);
        }
    }

    @SuppressWarnings("unchecked")
    public static List<Edge>[] initDijkstra(int N) {
        List<Edge>[] edges = new List[N];
        for (int i = 0; i < N; i++) {
            edges[i] = new ArrayList<>();
        }

        return edges;
    }

    public static long[] execDijkstra(List<Edge>[] edges, int start) {
        long[] distances = new long[edges.length];
        for (int i = 0; i < edges.length; i++) {
            distances[i] = -1;
        }

        PriorityQueue<Vertex> queue = new PriorityQueue<>(new Comparator<Vertex>() {
            @Override
            public int compare(Vertex o1, Vertex o2) {
                return Long.compare(o1.distance, o2.distance);
            }
        });

        queue.add(new Vertex(start, 0));

        while (queue.size() > 0) {
            Vertex vertex = queue.poll();

            if (distances[vertex.n] != -1) {
                continue;
            }

            distances[vertex.n] = vertex.distance;

            for (Edge edge : edges[vertex.n]) {
                if (distances[edge.to] == -1) {
                    queue.add(new Vertex(edge.to, vertex.distance + edge.distance));
                }
            }
        }

        return distances;
    }

    public static class Edge {

        public int to;

        public long distance;

        public Edge(int to, long distance) {
            this.to = to;
            this.distance = distance;
        }

    }

    public static class Vertex {

        public int n;

        public long distance;

        public Vertex(int n, long distance) {
            this.n = n;
            this.distance = distance;
        }

    }

    public static class Reader implements AutoCloseable {

        private BufferedReader br;

        private String[] buf;

        private int bufidx = -1;

        public Reader(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        @Override
        public void close() throws Exception {
