class Main {
    public static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    public static PrintWriter pw = new PrintWriter(System.out);
    public static String line;
    public static StringTokenizer st;
    public static ArrayList<ArrayList<Integer>> adjList;
    public static int[] dx = {-1, 0, 1, 0, -1, 1, 1, -1, 0};
    public static int[] dy = {0, 1, 0, -1, 1, 1, -1, -1, 0};
    public static int INF = 0x3f3f3f3f;
    public static int MOD = 1000000007;
    public static long LINF = 0x3f3f3f3f3f3f3f3fL;

    public static void main(String[] args) throws Exception {
        st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        ArrayList<Interval> A = new ArrayList<Interval>();
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken()) - 1;
            int b = Integer.parseInt(st.nextToken()) - 1;
            int cost = Integer.parseInt(st.nextToken());

            A.add(new Interval(a, 0, cost, i));
            A.add(new Interval(b, 1, cost, i));
        }

        Collections.sort(A);

        long[] dist = new long[N];
        Arrays.fill(dist, LINF);
        dist[0] = 0;

        int curIndex = 0;
        TreeMap<Long, Integer> d = new TreeMap<Long, Integer>();
        long[] idxValue = new long[N];
        Arrays.fill(idxValue, -1);

        for (int i = 0; i < N; i++) {
            if (d.size() > 0) {
                dist[i] = Math.min(dist[i], d.firstKey());                
            }

            while (curIndex < A.size() && A.get(curIndex).a == i) {
                Interval cur = A.get(curIndex);
                if (cur.b == 0) {
                    long total = 0;
                    if (i == 0) {
                        total = 0;
                    } else {
                        if (d.size() == 0) {
                            curIndex++;
                            continue;
                        }
                        total = d.firstKey();
                    }
                    long sum = total + cur.cost;
                    if (!d.containsKey(sum)) {
                        d.put(sum, 1);
                    } else {
                        d.put(sum, d.get(sum) + 1);
                    }
                    idxValue[cur.id] = sum;
                } else {
                    long sum = idxValue[cur.id];
                    if (d.containsKey(sum)) {
                        if (d.get(sum) > 1) {
                            d.put(sum, d.get(sum) - 1);
                        } else {
                            d.remove(sum);
                        }
                    }
                }
                curIndex++;
            }
        }

        pw.println(dist[N-1] == LINF ? -1 : dist[N-1]);

        pw.close();
        br.close();
    }
}

class Interval implements Comparable<Interval>{
    public int a, b, cost, id;

    Interval(int _a, int _b, int _cost, int id){
        a = _a;
        b = _b;
        cost = _cost;
        this.id = id;
    }

    public String toString(){
        return a + " " + b + " " + cost;
    }

    public int compareTo(Interval p){
        if (a != p.a) return a < p.a ? -1 : 1;
        if (b != p.b) return b < p.b ? -1 : 1;
        if (cost != p.cost) return cost < p.cost ? -1 : 1;
        return 0;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class ShortestPath {
  public long solve() {
    FastReader fr = new FastReader();
    int N = fr.nextInt();
    int M = fr.nextInt();

    final long INF = 1L << 60;
    long [][] G = new long[N][N];
    long [] dist = new long[N];

    for (int i = 0; i < N; i++) {
      Arrays.fill(G[i], INF);
      G[i][i] = 0;
      dist[i] = 0;
    }

    for (int i = 0; i < M; i++) {
      int L = fr.nextInt() - 1;
      int R = fr.nextInt() - 1;
      int C = fr.nextInt();
      G[L][R] = C;
      G[R][L] = C;
    }

    dijkstra(G, dist, 0);
    return dist[N - 1];
  }

  void dijkstra(long graph[][], long [] dist, int src)
  {
    int V = graph.length;

    // sptSet[i] will true if vertex i is included in shortest
    // path tree or shortest distance from src to i is finalized
    Boolean sptSet[] = new Boolean[V];

    // Initialize all distances as INFINITE and stpSet[] as false
    for (int i = 0; i < V; i++) {
      dist[i] = Integer.MAX_VALUE;
      sptSet[i] = false;
    }

    // Distance of source vertex from itself is always 0
    dist[src] = 0;

    // Find shortest path for all vertices
    for (int count = 0; count < V - 1; count++) {
      // Pick the minimum distance vertex from the set of vertices
      // not yet processed. u is always equal to src in first
      // iteration.
      int u = minDistance(dist, sptSet);

      // Mark the picked vertex as processed
      sptSet[u] = true;

      // Update dist value of the adjacent vertices of the
      // picked vertex.
      for (int v = 0; v < V; v++)

        // Update dist[v] only if is not in sptSet, there is an
        // edge from u to v, and total weight of path from src to
        // v through u is smaller than current value of dist[v]
        if (!sptSet[v] && graph[u][v] != 0 && dist[u] != Integer.MAX_VALUE && dist[u] + graph[u][v] < dist[v])
          dist[v] = dist[u] + graph[u][v];
    }
  }

  int minDistance(long dist[], Boolean sptSet[])
  {
    // Initialize min value
    long min = Long.MAX_VALUE;
    int min_index = -1;

    for (int v = 0; v < dist.length; v++)
      if (!sptSet[v] && dist[v] <= min) {
        min = dist[v];
        min_index = v;
      }

    return min_index;
  }

  public static void main(String [] args) {
    System.out.println(new ShortestPath().solve());
  }
}

