            d[v.id] = Math.min(d[v.id],v.distance);
            for (Edge edge : edges.get(v.id)) {
                int newCost = d[v.id] + edge.cost;
                if (d[edge.dest] <= newCost) continue;
                pq.add(new Vertex(edge.dest, newCost));
            }
        }
