                    for (int k = j + 1; k <= r; ++k) {
                        int c0 = costs[k][j];
                        if (c0 != 0 && c > c0) {
                            continue;
                        }
                        costs[k][j] = c;
                        links.get(k).add(j);
                    }
                }
            }
        }

        PriorityQueue<Entry> h = new PriorityQueue<>(Comparator.comparingInt(e -> e.cost));
        h.add(new Entry(n - 1, 0));
        while (!h.isEmpty()) {
            Entry e = h.poll();

            int c1 = e.cost;
            int n1 = e.id;

            if (n1 == 0) {
                System.out.println(e.cost);
                System.exit(0);
            }
            for (int n2 : links.get(n1)) {
                int c2 = costs[n1][n2];
                if (c2 == 0) {
                    continue;
                }
                h.add(new Entry(n2, c1 + c2));
            }
        }
        System.out.println(-1);
    }

