static class Q implements Comparable<Q>{
  int index;
  long sum;
  Q(int index, long sum){
    this.index = index;
    this.sum = sum;
  }
  public int compareTo(Q ato){
    if(this.sum < ato.sum){
      return -1;
    }else if(this.sum > ato.sum){
      return 1;
    }else{
      if(this.index < ato.index){
        return -1;
      }else if(this.index > ato.index){
        return 1;
      }else{
        return 0;
      }
    }
  }
