import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni(), m = ni();
		int H = Integer.highestOneBit(Math.max(1, n-1))*2;
		int p = 0;
//		for(int i = 1;i < H;i++){
//			from[p] = i; to[p] = 2*i; ws[p] = 0; p++;
//			from[p] = i; to[p] = 2*i+1; ws[p] = 0; p++;
//			to[p] = 2*H+i; from[p] = 2*H+2*i; ws[p] = 0; p++;
//			to[p] = 2*H+i; from[p] = 2*H+2*i+1; ws[p] = 0; p++;
//		}

		int[] from = new int[31*n];
		int[] to = new int[31*n];
		int[] cs = new int[m];
		int[] temp = new int[100];
		for(int i = 0;i < m;i++){
			int y = 0;
			int l = ni()-1, r = ni()-1+1, C = ni();
			cs[i] = C;
			while(l != 0){
				int f = l&-l;
				if(l+f > r)break;
				temp[y++] = (H+l)/f;
				l += f;
			}

			while(l < r){
				int f = r&-r;
				temp[y++] = (H+r)/f-1;
				r -= f;
			}
			for(int j = 0;j < y;j++){
				int f = 2*H+temp[j];
				if(f >= 3*H)f -= 2*H;
				from[p] = f; to[p] = 3*H+i; p++;
				from[p] = 3*H+i; to[p] = temp[j]; p++;
			}
		}
		int[][] g = packD(3*H+m, from, to, p);

		long[] td = new long[3*H+m];

		Arrays.fill(td, Long.MAX_VALUE / 2);
		MinHeapL q = new MinHeapL(3*H+m);
		q.add(H, 0);
		td[H] = 0;

		while(q.size() > 0){
			int cur = q.argmin();
			q.remove(cur);

			for(int e : g[cur]){
				int next = e;
				long nd = td[cur];
				if(cur >= 3*H){
					nd += cs[cur-3*H];
				}
				if(nd < td[next]){
					td[next] = nd;
					q.update(next, nd);
				}
			}
			if(cur < H){
				for(int k = 0;k < 2;k++){
					int next = cur*2+k;
					long nd = td[cur];
					if(nd < td[next]){
						td[next] = nd;
						q.update(next, nd);
					}
				}
			}else if(cur >= H && cur < H+n){
				int next = cur/2+2*H;
				long nd = td[cur];
				if(nd < td[next]){
					td[next] = nd;
					q.update(next, nd);
				}
			}else if(cur >= 2*H+2 && cur < 3*H){
				int next = (cur-2*H)/2+2*H;
				long nd = td[cur];
				if(nd < td[next]){
					td[next] = nd;
					q.update(next, nd);
				}
			}
		}
		if(td[H+n-1] >= Long.MAX_VALUE / 2){
			out.println(-1);
		}else{
			out.println(td[H+n-1]);
		}
	}


	public static int[][] packD(int n, int[] from, int[] to){ return packD(n, from, to, from.length);}
	public static int[][] packD(int n, int[] from, int[] to, int sup)
	{
		int[][] g = new int[n][];
		int[] p = new int[n];
		for(int i = 0;i < sup;i++)p[from[i]]++;
		for(int i = 0;i < n;i++)g[i] = new int[p[i]];
		for(int i = 0;i < sup;i++){
			g[from[i]][--p[from[i]]] = to[i];
		}
		return g;
	}



	public static class MinHeapL {
		public long[] a;
		public int[] map;
		public int[] imap;
		public int n;
		public int pos;
		public static long INF = Long.MAX_VALUE;

		public MinHeapL(int m)
		{
			n = Integer.highestOneBit((m+1)<<1);
			a = new long[n];
			map = new int[n];
			imap = new int[n];
			Arrays.fill(a, INF);
			Arrays.fill(map, -1);
			Arrays.fill(imap, -1);
			pos = 1;
		}

		public long add(int ind, long x)
		{
			int ret = imap[ind];
			if(imap[ind] < 0){
				a[pos] = x; map[pos] = ind; imap[ind] = pos;
				pos++;
				up(pos-1);
			}
			return ret != -1 ? a[ret] : x;
		}

		public long update(int ind, long x)
		{
			int ret = imap[ind];
			if(imap[ind] < 0){
				a[pos] = x; map[pos] = ind; imap[ind] = pos;
				pos++;
				up(pos-1);
			}else{
				a[ret] = x;
				up(ret);
				down(ret);
			}
			return x;
		}

		public long remove(int ind)
		{
			if(pos == 1)return INF;
			if(imap[ind] == -1)return INF;

			pos--;
			int rem = imap[ind];
			long ret = a[rem];
			map[rem] = map[pos];
			imap[map[pos]] = rem;
			imap[ind] = -1;
			a[rem] = a[pos];
			a[pos] = INF;
			map[pos] = -1;

			up(rem);
			down(rem);
			return ret;
		}

		public long min() { return a[1]; }
		public int argmin() { return map[1]; }
		public int size() {	return pos-1; }

		private void up(int cur)
		{
			for(int c = cur, p = c>>>1;p >= 1 && a[p] > a[c];c>>>=1, p>>>=1){
				long d = a[p]; a[p] = a[c]; a[c] = d;
				int e = imap[map[p]]; imap[map[p]] = imap[map[c]]; imap[map[c]] = e;
				e = map[p]; map[p] = map[c]; map[c] = e;
			}
		}

		private void down(int cur)
		{
			for(int c = cur;2*c < pos;){
				int b = a[2*c] < a[2*c+1] ? 2*c : 2*c+1;
				if(a[b] < a[c]){
					long d = a[c]; a[c] = a[b]; a[b] = d;
					int e = imap[map[c]]; imap[map[c]] = imap[map[b]]; imap[map[b]] = e;
					e = map[c]; map[c] = map[b]; map[b] = e;
					c = b;
				}else{
					break;
				}
			}
		}
	}

	public static int[][][] packWD(int n, int[] from, int[] to, int[] w){ return packWD(n, from, to, w, from.length); }
	public static int[][][] packWD(int n, int[] from, int[] to, int[] w, int sup)
	{
		int[][][] g = new int[n][][];
		int[] p = new int[n];
		for(int i = 0;i < sup;i++)p[from[i]]++;
		for(int i = 0;i < n;i++)g[i] = new int[p[i]][2];
		for(int i = 0;i < sup;i++){
			--p[from[i]];
			g[from[i]][p[from[i]]][0] = to[i];
			g[from[i]][p[from[i]]][1] = w[i];
		}
		return g;
	}


