import java.io.*;
import java.util.*;

public class Main {

  static FastScanner sc = new FastScanner();
  static Output out = new Output(System.out);

  static final int[] dx = {0, 1, 0, -1};
  static final int[] dy = {-1, 0, 1, 0};

  static final long MOD = (long) (1e9 + 7);
  static final long INF = Long.MAX_VALUE / 2;

  static final int e5 = (int) 1e5;

  public static class Solver {
    public Solver() {

      int N = sc.nextInt();
      int M = sc.nextInt();

      long[] initial = new long[N];
      Arrays.fill(initial, INF);
      initial[0] = 0;
      SegmentTree seg = new SegmentTree(initial);

      Range[] ranges = new Range[M];
      for (int i=0; i<M; i++) {
        int l = sc.nextInt()-1;
        int r = sc.nextInt()-1;
        long c = sc.nextLong();
        ranges[i] = new Range(l, r, c);
      }

      Arrays.sort(ranges, (o1, o2) -> {
        if (o1.l == o2.l) {
          return o2.r - o1.r;
        } else {
          return o1.l - o2.l;
        }
      });

      for (int i=0; i<M; i++) {
        int l = ranges[i].l;
        int r = ranges[i].r;
        long c = ranges[i].c;
        long min = seg.query(l, r+1).val;
        seg.put(l, r+1, min+c);
      }

      long ans = seg.query(N-1, N).val;
      out.println(ans == INF ? -1 : ans);

    }

    public class Range {
      int l, r;
      long c;
      Range(int l, int r, long c) {
        this.l = l;
        this.r = r;
        this.c = c;
      }
    }

    public static class SegmentTree {

      static final long INF = Long.MAX_VALUE / 2;

      Node[] tree;
      int N = 1; //元配列の要素数以上で最小の2の冪乗
      int size; //木のサイズ
      Node initialNode;

      public static class Node {
        static long initialVal = INF;
        static long initialLazy = INF;
        boolean isLazy = false;
        long val;
        long lazy;

        public Node() {
          val = initialVal;
          lazy = initialLazy;
        }
        public Node(long val) {
          this.val = val;
          lazy = initialLazy;
        }

        public Node operation(Node nl, Node nr) {
          val = Math.min(nl.val, nr.val);
          return this;
        }
        public void prop(Node par) {
          if (!par.isLazy) return;
          lazy = Math.min(lazy, par.lazy); //changed
          isLazy = true;
        }
        public void prop(long x, int l, int r) {
          lazy = Math.min(lazy, x); //changed
          isLazy = true;
        }
        public void update() {
          if (!isLazy) return;
          val = Math.min(lazy, val); //changed
          lazy = initialLazy;
          isLazy = false;
        }
      }

      public void update(int k, long x) {
        k += N-1;
        tree[k] = new Node(x);

        while(k != 0) {
          k = parent(k);
          tree[k].operation(tree[childL(k)], tree[childR(k)]);
        }
      }

      private void prop(int k) {
        if (childL(k) < size) { //葉じゃなければ
          tree[childL(k)].prop(tree[k]);
          tree[childR(k)].prop(tree[k]);
        }
        tree[k].update();
      }

      public void put(int a, int b, long x) {
        put(a, b, 0, 0, N, x);
      }

      private void put(int a, int b, int k, int l, int r, long x) {
        prop(k);

        if (r <= a || b <= l) return; //区間外
        if (a <= l && r <= b) { //区間に完全に含まれる
          tree[k].prop(x, l, r);
          prop(k);
        } else { //一部区間外
          put(a, b, childL(k), l, (l + r) / 2, x);
          put(a, b, childR(k), (l + r) / 2, r, x);
          tree[k].operation(tree[childL(k)], tree[childR(k)]);
        }
      }

      public SegmentTree(long[] A) {
        initialNode = new Node();

        //元配列の要素数が2の冪乗でない場合,2の冪乗サイズに拡大して初期値をつめておく
        while (N < A.length) N *= 2;

        size = N*2-1;
        tree = new Node[size];

        for (int i=0; i<size; i++) {
          tree[i] = new Node();
        }

        for (int i=0; i<A.length; i++) {
          update(i, A[i]);
        }

      }

      public Node query(int a, int b) {
        return query(a, b, 0, 0, N);
      }

      private Node query(int a, int b, int k, int l, int r) {
        prop(k);

        if (r <= a || b <= l) return initialNode;
        if (a <= l && r <= b) return tree[k];

        return new Node().operation(query(a, b, childL(k), l, (l+r)/2), query(a, b, childR(k), (l+r)/2, r));
      }

      private int parent(int k) {
        return k % 2 == 0 ? (k-2)/2 : (k-1)/2;
      }

      private int childL(int k) {
        return 2*k+1;
      }

      private int childR(int k) {
        return 2*k+2;
      }
    }

  }

