	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * 第二回全国統一プログラミング王決定戦予選 D問題
		 * 考察メモ
		 * まず、頂点2までの距離を考える
		 * これはL_i=1, L_2≧2なる物があった時、その中のC_i最小
		 * 次に頂点3までの距離を考える
		 * これはL_i=1, R_i≧3なるもののC_i最小とL_i=2, R_i≧3におけるC_i最小+D_2のより小さい方
		 * ところで前者は前もって値を配ることができて
		 * つまり、L_i昇順にソートするとする
		 * で、minになるように併合していく
		 * 区間minができれば良いので遅延セグ木かな
		 *
		 */
		int N = io.nextInt(), M = io.nextInt();
		final int INF = Integer.MAX_VALUE >> 1;
		Edge[] edge = new Edge[M];
		for (final int i : IntRange.open(M)) edge[i] = new Edge(io.nextInt(), io.nextInt(), io.nextInt());
