		segment.update(0, 0);
		Arrays.sort(edge);
		for (Edge i : edge) {
			if (segment.get(i.L - 1) == INF) continue;
			segment.update(segment.get(i.L - 1) + i.C, i.L, i.R);
		}
		int ans = segment.get(N - 1);
		if (ans >= INF) ans = -1;
		io.println(ans);

