import java.util.*;

import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	static class Pair {
		int l, r;
		long c;

		Pair(int l, int r, long c) {
			this.l = l;
			this.r = r;
			this.c = c;
		}
	}

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		int N, M;
		String[] tokens = in.readLine().split(" ");
		N = Integer.parseInt(tokens[0]);
		M = Integer.parseInt(tokens[1]);
		List<Pair> sections = new ArrayList<>(M);
		for (int i = 0; i < M; ++i) {
			tokens = in.readLine().split(" ");
			sections.add(new Pair(Integer.parseInt(tokens[0]) - 1, Integer.parseInt(tokens[1]) - 1,
					Long.parseLong(tokens[2])));
		}
		long[] distances = new long[N];
		Arrays.fill(distances, Long.MAX_VALUE / 2);
		distances[0] = 0L;
		Collections.sort(sections, new Comparator<Pair>() {
			@Override
			public int compare(Pair o1, Pair o2) {
				if (o1.l != o2.l) {
					return Integer.compare(o1.l, o2.l);
				} else if (o1.r != o2.r) {
					return Integer.compare(o1.r, o2.r);
				} else {
					return Long.compare(o1.c, o2.c);
				}
			}
		});
		for (int i = 0; i < sections.size(); ++i) {
			Pair sec = sections.get(i);
			long baseDist = distances[sec.l];
			for (int j = sec.l; j <= sec.r; ++j) {
				distances[j] = Math.min(distances[j], baseDist + sec.c);
			}
		}
		if (distances[N - 1] >= Long.MAX_VALUE / 2) {
			System.out.println(-1);
		} else {
			System.out.println(distances[N - 1]);
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {

    public static void main(String[] args) throws Exception {
        try (Reader r = new Reader(System.in)) {
            int N = r.i();
            int M = r.i();

            int[][] LRC = r.im(M);
            Arrays.sort(LRC, (o1, o2) -> {
                int compare = Integer.compare(o1[0], o2[0]);
                if (compare != 0) {
                    return compare;
                }
                return Integer.compare(o1[2], o2[2]);
            });

            long[] distance = new long[N];
            for (int i = 1; i < N; i++) {
                distance[i] = Long.MAX_VALUE;
            }

            int preL = -1;
            int preR = -1;
            for (int[] lrc : LRC) {
                int L = lrc[0] - 1;
                int R = lrc[1] - 1;
                long C = lrc[2];

                if (distance[L] == Long.MAX_VALUE) {
                    System.out.println(-1);
                    return;
                }

                int t = L + 1;
                if (preL == L) {
                    if (preR >= R) {
                        continue;
                    }
                    t = preR + 1;
                }

                for (; t <= R; t++) {
                    distance[t] = Math.min(distance[t], distance[L] + C);
                }

                preL = L;
                preR = R;
            }

            System.out.println(distance[N - 1]);
        }
    }

    public static class Reader implements AutoCloseable {

        private BufferedReader br;

        private String[] buf;

        private int bufidx = -1;

        public Reader(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        @Override
        public void close() throws Exception {
            br.close();
        }

        private void readBuf() throws IOException {
            if (bufidx == -1 || bufidx == buf.length) {
                buf = br.readLine().split(" ");
                bufidx = 0;
            }
        }

        public String s() throws IOException {
            readBuf();
            return buf[bufidx++];
        }

        public int i() throws IOException {
            return Integer.parseInt(s());
        }

        public long l() throws IOException {
            return Long.parseLong(s());
        }

        public double d() throws IOException {
            return Double.parseDouble(s());
        }

        public String[] sa() throws IOException {
            readBuf();
            if (bufidx != 0) {
                throw new RuntimeException("illegal read");
            }
            bufidx = -1;
            return buf;
        }

        public int[] ia() throws IOException {
            String[] sa = sa();
            int[] ia = new int[sa.length];
            for (int i = 0; i < sa.length; i++) {
                ia[i] = Integer.parseInt(sa[i]);
            }
            return ia;
        }

        public long[] la() throws IOException {
            String[] sa = sa();
