import java.util.*;
import java.math.*;
public class Main{
	public static void main(String[] args){
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int m=sc.nextInt();
		ArrayList<State>[] map=new ArrayList[n];
		map[0]=new ArrayList<>();
		for(int i=n-1; i>=1; i--){
			map[i]=new ArrayList<>();
			map[i].add(new State(i-1,0));
		}
		for(int i=0; i<m; i++){
			int l=sc.nextInt()-1;
			int r=sc.nextInt()-1;
			long c=sc.nextLong();
			map[l].add(new State(r,c));
		}
		PriorityQueue<State> q=new PriorityQueue<>();
		long[] dist=new long[n];
		Arrays.fill(dist,-1);
		q.add(new State(0,0));
		while(!q.isEmpty() && dist[n-1]==-1){
			State s=q.poll();
			if(dist[s.l]!=-1){
				continue;
			}
			dist[s.l]=s.c;
			for(State ss:map[s.l]){
				if(dist[ss.l]==-1){
					q.add(new State(ss.l,ss.c+s.c));
				}
			}
		}
		System.out.println(dist[n-1]);
	}
	static class State implements Comparable<State>{
		int l;
		long c;
		State(int l,long c){
			this.l=l;
			this.c=c;
		}
		@Override
		public int compareTo(State o){
			return Long.compare(this.c,o.c);
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.StringTokenizer;
import java.util.function.BinaryOperator;
import java.util.function.UnaryOperator;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(final String[] args) {
        final FastScanner scanner = new FastScanner(System.in);
        final int n = scanner.nextInt();
        final int m = scanner.nextInt();
        final List<Operation> operations = IntStream.range(0, m)
            .mapToObj(i -> new Operation(scanner.nextInt(), scanner.nextInt(), scanner.nextInt()))
            .sorted(Comparator.comparingInt(o -> o.left))
            .collect(Collectors.toList());

        if (operations.get(0).left > 1) {
            System.out.println(-1);
            return;
        }

        final List<Integer> initial = IntStream.rangeClosed(0, n)
            .mapToObj(i -> i == 1 ? 0 : Integer.MAX_VALUE)
            .collect(Collectors.toList());

        final SegmentTree<Integer> tree = new SegmentTree<>(initial, Integer.MAX_VALUE, Math::min);
        for (final Operation operation : operations) {
            final int queryResult = tree.query(operation.left, n + 1);
            if (queryResult == Integer.MAX_VALUE) {
                System.out.println(-1);
                return;
            }
            tree.update(operation.right, value -> Math.min(value, queryResult + operation.c));
        }

        final int answer = tree.get(n) < Integer.MAX_VALUE ? tree.get(n) : -1;
        System.out.println(answer);
    }

    private static class Operation {
        final int left;
        final int right;
        final int c;

        Operation(final int left, final int right, final int c) {
            this.left = left;
            this.right = right;
            this.c = c;
        }
    }

    private static class SegmentTree<T> {
        private final T[] internalTree;
        private final int exponent;
        private final T initialValue;
        private final BinaryOperator<T> comparator;

        SegmentTree(final List<T> list, final T initialValue, final BinaryOperator<T> comparator) {
            this.exponent = calcExponent(list.size());
            this.comparator = comparator;
            this.initialValue = initialValue;
            internalTree = initTree(list, initialValue);
        }

        T get(final int index) {
            return internalTree[index + exponent];
        }

        /**
         * 値の更新
         *
         * @param index "0-indexed"のインデックス
         * @param value 更新後の値
         */
        void update(final int index, final T value) {
            internalTree[index + exponent] = value;
            int current = (index + exponent) / 2;
            while (current > 0) {
                internalTree[current] = comparator.apply(internalTree[current * 2], internalTree[current * 2 + 1]);
                current /= 2;
            }
        }

        /**
         * 値の更新
         *
         * @param index    "0-indexed"のインデックス
         * @param operator 更新式
         */
        void update(final int index, final UnaryOperator<T> operator) {
            internalTree[index + exponent] = operator.apply(internalTree[index + exponent]);
            int current = (index + exponent) / 2;
            while (current > 0) {
                internalTree[current] = comparator.apply(internalTree[current * 2], internalTree[current * 2 + 1]);
                current /= 2;
            }
        }

        /**
         * クエリ
         * クエリの区間を [left, right) の半開区間で渡すことに注意
         *
         * @param left  "0-indexed"のクエリの左端
         * @param right "0-indexed"のクエリの右端 + 1
         *              つまり"1-indexed"のクエリの右端
         * @return クエリ結果
         */
        T query(final int left, final int right) {
            return query(left, right, 0, exponent, 1);
        }

        T query(final int left, final int right, final int begin, final int end, final int k) {
            if (left >= end || right <= begin) {
                return initialValue;
            }

            if (left <= begin && end <= right) {
                return internalTree[k];
            }

            final int mid = (begin + end) / 2;
            return comparator.apply(query(left, right, begin, mid, k * 2), query(left, right, mid, end, k * 2 + 1));
        }

        @SuppressWarnings("unchecked")
        private T[] initTree(final List<T> list, final T initialValue) {
            final Object[] array = new Object[exponent * 2];
            Arrays.fill(array, initialValue);
            for (int i = 0; i < list.size(); i++) {
                array[i + exponent] = list.get(i);
            }

            for (int i = exponent - 1; i > 0; i--) {
                array[i] = comparator.apply((T) array[i * 2], (T) array[i * 2 + 1]);
            }

            return (T[]) array;
        }

        private int calcExponent(final int n) {
            int exp = 1;
            while (exp < n) {
                exp <<= 1;
            }
            return exp;
        }
    }

    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(final InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (final IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

public class Main {

    Edge[] g;
    int n;


    void run() {
        Scanner sc = new Scanner(System.in);

        n = sc.nextInt();
        int m = sc.nextInt();

        g = new Edge[n];
        for (int i = 0; i < n; i++) {
            g[i] = new Edge();
            if (i != 0) g[i].add(new P(i - 1, 0));
        }

        for (int i = 0; i < m; i++) {
            int l = sc.nextInt() - 1, r = sc.nextInt() - 1, c = sc.nextInt();
            g[l].add(new P(r, c));
        }
        System.out.println(dijkstra());
    }

    long dijkstra() {
        long[] d = new long[n];
        Arrays.fill(d, 1L << 60);
        d[0] = 0;
        PriorityQueue<P> q = new PriorityQueue<>(Comparator.comparingLong(p -> p.c));
        q.add(new P(0, 0));

        while (!q.isEmpty()) {
            P cur = q.remove();
            if (cur.t == n - 1) return cur.c;
            if (cur.c != d[cur.t]) continue;

            for (P next: g[cur.t]) {
                if (d[next.t] > cur.c + next.c) {
                    d[next.t] = cur.c + next.c;
                    q.add(new P(next.t, cur.c + next.c));
                }
            }
        }
        return -1;
    }

    class Edge extends ArrayList<P> {}

    class P {
        int t;
        long c;
        P(int t, long c) {
            this.t = t;
            this.c = c;
        }
    }

    void debug(Object...os) {
        System.err.println(Arrays.deepToString(os));
    }

    public static void main(String[] args) {
        new Main().run();
    }

}

import java.util.*;
import java.io.*;

public class Main {
    static ArrayList<Path>[] graph;
    static long[] score;
	public static void main (String[] args) throws Exception {
	    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
	    String[] first = br.readLine().split(" ", 2);
		int n = Integer.parseInt(first[0]);
		int m = Integer.parseInt(first[1]);
		graph = new ArrayList[n + 1];
		for (int i = 1; i <= n; i++) {
		    graph[i] = new ArrayList<Path>();
		}
		score = new long[n + 1];
		Arrays.fill(score, Long.MAX_VALUE / 10);
		for (int i = 0; i < m; i++) {
		    String[] line = br.readLine().split(" ", 3);
		    int a = Integer.parseInt(line[0]);
		    int b = Integer.parseInt(line[1]);
		    int c = Integer.parseInt(line[2]);
		    graph[a].add(new Path(b, c));
		    for (int j = a + 1; j < b; j++) {
		        graph[j].add(new Path(a, 0));
		        graph[b].add(new Path(j, 0));
		    }
		}
		search(1, 0);
		if (score[n] >= Long.MAX_VALUE / 10) {
		    System.out.println(-1);
		} else {
		    System.out.println(score[n]);
		}
	}

	static void search(int idx, long value) {
	    if (score[idx] <= value) {
	        return;
	    }
	    score[idx] = value;
	    for (Path next : graph[idx]) {
	        search(next.to, value + next.value);
	    }
	}

	static class Path {
	    int to;
	    int value;

	    public Path(int to, int value) {
	        this.to = to;
	        this.value = value;
	    }
	}
}

