        // -----------------------------------------
        public void solve() {
        	int N = ni();
        	int M = ni();
        	List<PPP> LRC = new ArrayList<>();
        	int l, r, c;
        	boolean start = false;
        	for (int i = 0; i < M; i++) {
				l = ni();
				r = ni();
				c = ni();
				LRC.add(new PPP(l, r, c));
				if(l == 1)	start = true;
			}
        	if(!start) {
        		prn(-1);
        		return;
        	}
        	LRC.sort(comparing(PPP::getKey).thenComparing(PPP::getVal1, reverseOrder()));
        	int svKey = -1, svVal = 1000000100;
        	for(PPP ppp : LRC) {
        		if(ppp.key == svKey) {
        			if(ppp.val2 > svVal) {
        				ppp.val2 = svVal;
        			} else {
        				svVal = ppp.val2;
        			}
        		} else {
        			svKey = ppp.key;
        			svVal = 1000000100;
        		}
        	}
        	TreeMap<Integer, Long> map = new TreeMap<>();
        	map.put(1, 0L);
    		Entry<Integer, Long> high;
    		long wk1, wk2;
        	for(PPP ppp : LRC) {
        		high = map.higherEntry(ppp.key - 1);		
        		if(high != null) {
        			wk1 = 1000000000000000000L;
        			if(map.containsKey((ppp.val1))) {
	        			wk1 = map.get(ppp.val1);
        			}
        			wk2 = (long)ppp.val2 + high.getValue();
        			if(wk1 > wk2)	map.put(ppp.val1, wk2);
        		}
        	}
        	if(map.containsKey(N)) {
        		prn(map.get(N));
        	} else {
        		prn(-1);
        	}
    	}

        // -----------------------------------------
        // Integer のキーに対して、Integer のカウントを管理する（カウントを足したり、引いたりする）
        // キーの最大、最小の取得、データの追加、削除も O(long(N)) で処理できる
        //
        static class MapCounter {
        	private TreeMap<Integer, Integer> map;
        	// 昇順のマップ
        	public MapCounter() {
        		map = new TreeMap<>();
        	}
        	// reverse = tree なら降順のマップ
        	public MapCounter(boolean reverse) {
        		if(reverse) {
        			map = new TreeMap<Integer, Integer>(Collections.reverseOrder());
        		} else {
            		map = new TreeMap<>();
        		}
        	}
        	// キーを追加する（キーが存在すれば、カウントに１足す）
        	public void add(Integer key) {
        		add(key, 1);
        	}
           	public void add(Integer key, int cnt) {
           		Integer val = map.get(key);
        		if(val == null) {
        			map.put(key, cnt);
        		} else {
        			map.put(key,  val + cnt);
        		}
        	}
        	// キーを消す（キーが存在すれば、カウントを１減らす）
        	public void remove(Integer key) {
        		sub(key, 1, false);
        	}
           	// キーのカウントを減らす
        	public void sub(Integer key) {
        		sub(key, 1);
        	}
        	// キーのカウントから値を引く（マイナスのカウントを許す）
        	public void sub(Integer key, int cnt) {
        		sub(key, cnt, true);
        	}
        	// キーのカウントから値を引く
        	//  →　マイナスを許可しない場合で、カウントがマイナスになったら消す
           	public void sub(Integer key, int cnt, boolean minus) {
        		Integer val = map.get(key);
        		if(val == null) {
        			if(minus) {
        				map.put(key, -cnt);				// カウントのマイナスを許す
        			}
        		} else if(val > cnt || minus){
       				map.put(key, val - cnt);
        		} else {
        			map.remove(key);
        		}
        	}
           	// キーのカウントを設定する
           	public void set(Integer key, int cnt) {
    			map.put(key, cnt);
        	}
           	// キーのカウントを取得する（なければ　ＮＵＬＬを返す）
        	public Integer getCountwithNull(Integer key) {
        		return map.get(key);
        	}
        	// キーのカウントを取得する（なければ　０　を返す）
        	public Integer getCount(Integer key) {
        		Integer val = map.get(key);
        		if(val == null)		return 0;
        		else 				return val;
        	}
        	public Set<Integer> getKey() {
        		return map.keySet();
        	}
        	// 登録されているキーの数を返す
        	public int getKeyCount() {
        		return map.keySet().size();
        	}
        	// 先頭キーを返す
        	public Integer getFirstKey() {
        		return map.firstKey();
        	}
        	// 最終キーを返す
        	public Integer getLastKey() {
        		return map.lastKey();
        	}
        	// マップの初期化
        	public void clear() {
        		map.clear();
        	}
       }
