//                    if (R >= lrcs[i].R) {
//                        continue;
//                    }
//                    t = R + 1;
//                }

                for (int j = lrcs[i].R; j >= lrcs[i].L + 1; j--) {
                    if (d[j] < d[lrcs[i].L] + lrcs[i].C) {
