	static void solve()
	{
		int n = ni(), m = ni();
		int H = Integer.highestOneBit(Math.max(1, n-1))*2;
		int p = 0;
//		for(int i = 1;i < H;i++){
//			from[p] = i; to[p] = 2*i; ws[p] = 0; p++;
//			from[p] = i; to[p] = 2*i+1; ws[p] = 0; p++;
//			to[p] = 2*H+i; from[p] = 2*H+2*i; ws[p] = 0; p++;
//			to[p] = 2*H+i; from[p] = 2*H+2*i+1; ws[p] = 0; p++;
//		}

		long[] ft = new long[38*n];
		int[] ws = new int[38*n];
		int[] temp = new int[100];
		for(int i = 0;i < m;i++){
			int y = 0;
			int l = ni()-1, r = ni()-1+1, C = ni();
			while(l != 0){
				int f = l&-l;
				if(l+f > r)break;
				temp[y++] = (H+l)/f;
				l += f;
			}

			while(l < r){
				int f = r&-r;
				temp[y++] = (H+r)/f-1;
				r -= f;
			}
			for(int j = 0;j < y;j++){
				ft[p] = (long)2*H+temp[j]<<32|4*H+i; ws[p] = C; p++;
				ft[p] = (long)4*H+i<<32|temp[j]; ws[p] = 0; p++;
			}
		}
		long[][] g = packWD(4*H+m, ft, ws, p);

		long[] td = new long[4*H+m];

		Arrays.fill(td, Long.MAX_VALUE / 2);
		MinHeapL q = new MinHeapL(4*H+m);
		q.add(H, 0);
		td[H] = 0;

		while(q.size() > 0){
			int cur = q.argmin();
			q.remove(cur);

			for(long e : g[cur]){
				int next = (int)(e>>>32);
				long nd = td[cur] + (int)e;
				if(nd < td[next]){
					td[next] = nd;
					q.update(next, nd);
				}
			}
			if(cur < H){
				for(int k = 0;k < 2;k++){
					int next = cur*2+k;
					long nd = td[cur];
					if(nd < td[next]){
						td[next] = nd;
						q.update(next, nd);
					}
				}
			}else if(cur >= 2*H+2 && cur < 4*H){
				int next = (cur-2*H)/2+2*H;
				long nd = td[cur];
				if(nd < td[next]){
					td[next] = nd;
					q.update(next, nd);
				}
			}else if(cur < H+n){
				int next = cur+2*H;
				long nd = td[cur];
				if(nd < td[next]){
					td[next] = nd;
					q.update(next, nd);
				}
			}
		}
//		for(int i = 0;i < n;i++){
//			tr(i, td[i+H]);
//		}
		if(td[H+n-1] >= Long.MAX_VALUE / 2){
			out.println(-1);
		}else{
			out.println(td[H+n-1]);
		}
	}

	public static long[][] packWD(int n, long[] ft, int[] w){ return packWD(n, ft, w, ft.length); }
	public static long[][] packWD(int n, long[] ft, int[] w, int sup)
	{
		long[][] g = new long[n][];
		int[] p = new int[n];
		for(int i = 0;i < sup;i++)p[(int)(ft[i]>>>32)]++;
		for(int i = 0;i < n;i++)g[i] = new long[p[i]];
		for(int i = 0;i < sup;i++){
			int f = (int)(ft[i]>>>32);
			int t = (int)ft[i];
			--p[f];
			g[f][p[f]] = (long)t<<32|w[i];
		}
		return g;
	}



	public static class MinHeapL {
		public long[] a;
		public int[] map;
		public int[] imap;
		public int n;
		public int pos;
		public static long INF = Long.MAX_VALUE;

		public MinHeapL(int m)
		{
			n = Integer.highestOneBit((m+1)<<1);
			a = new long[n];
			map = new int[n];
			imap = new int[n];
			Arrays.fill(a, INF);
			Arrays.fill(map, -1);
			Arrays.fill(imap, -1);
			pos = 1;
		}

		public long add(int ind, long x)
		{
			int ret = imap[ind];
			if(imap[ind] < 0){
				a[pos] = x; map[pos] = ind; imap[ind] = pos;
				pos++;
				up(pos-1);
			}
			return ret != -1 ? a[ret] : x;
		}

		public long update(int ind, long x)
		{
			int ret = imap[ind];
			if(imap[ind] < 0){
				a[pos] = x; map[pos] = ind; imap[ind] = pos;
				pos++;
				up(pos-1);
			}else{
				a[ret] = x;
				up(ret);
				down(ret);
			}
			return x;
		}

		public long remove(int ind)
		{
			if(pos == 1)return INF;
			if(imap[ind] == -1)return INF;

			pos--;
			int rem = imap[ind];
			long ret = a[rem];
			map[rem] = map[pos];
			imap[map[pos]] = rem;
			imap[ind] = -1;
			a[rem] = a[pos];
			a[pos] = INF;
			map[pos] = -1;

			up(rem);
			down(rem);
			return ret;
		}

		public long min() { return a[1]; }
		public int argmin() { return map[1]; }
		public int size() {	return pos-1; }

		private void up(int cur)
		{
			for(int c = cur, p = c>>>1;p >= 1 && a[p] > a[c];c>>>=1, p>>>=1){
				long d = a[p]; a[p] = a[c]; a[c] = d;
				int e = imap[map[p]]; imap[map[p]] = imap[map[c]]; imap[map[c]] = e;
				e = map[p]; map[p] = map[c]; map[c] = e;
			}
		}

		private void down(int cur)
		{
			for(int c = cur;2*c < pos;){
				int b = a[2*c] < a[2*c+1] ? 2*c : 2*c+1;
				if(a[b] < a[c]){
					long d = a[c]; a[c] = a[b]; a[b] = d;
					int e = imap[map[c]]; imap[map[c]] = imap[map[b]]; imap[map[b]] = e;
					e = map[c]; map[c] = map[b]; map[b] = e;
					c = b;
				}else{
					break;
				}
			}
		}
	}

	public static int[][][] packWD(int n, int[] from, int[] to, int[] w){ return packWD(n, from, to, w, from.length); }
	public static int[][][] packWD(int n, int[] from, int[] to, int[] w, int sup)
	{
		int[][][] g = new int[n][][];
		int[] p = new int[n];
		for(int i = 0;i < sup;i++)p[from[i]]++;
		for(int i = 0;i < n;i++)g[i] = new int[p[i]][2];
		for(int i = 0;i < sup;i++){
			--p[from[i]];
			g[from[i]][p[from[i]]][0] = to[i];
			g[from[i]][p[from[i]]][1] = w[i];
		}
		return g;
	}


	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

import java.util.*;

import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	static class Node {
		int id;
		Map<Integer, Long> edges;

		Node(int id) {
			this.id = id;
			this.edges = new HashMap<>();
		}

		void setEdge(int dst, long c) {
			if (!this.edges.containsKey(dst)) {
				this.edges.put(dst, c);
			} else if (this.edges.get(dst) > c) {
				this.edges.put(dst, c);
			}
		}

		Set<Edge> getEdges() {
			Set<Edge> set = new HashSet<>();
			for (Integer dst : this.edges.keySet()) {
				set.add(new Edge(this.id, dst, this.edges.get(dst)));
			}
			this.edges.clear();
			return set;
		}
	}

	static class Edge {
		int src, dst;
		long c;

		Edge(int src, int dst, long c) {
			this.src = src;
			this.dst = dst;
			this.c = c;
		}
	}

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		int N, M;
		String[] tokens = in.readLine().split(" ");
		N = Integer.parseInt(tokens[0]);
		M = Integer.parseInt(tokens[1]);
		Node[] nodes = new Node[N];
		for (int i = 0; i < N; ++i) {
			nodes[i] = new Node(i);
		}
		// 区間の中間からの処理を可能とするための便宜上の辺を追加
		for( int i = 1; i < N; ++i) {
			nodes[i].setEdge(i-1, 0L);
		}
		for (int i = 0; i < M; ++i) {
			tokens = in.readLine().split(" ");
			int src = Integer.parseInt(tokens[0]) - 1;
			int dst = Integer.parseInt(tokens[1]) - 1;
			long c = Long.parseLong(tokens[2]);
			nodes[src].setEdge(dst, c);
		}
		Queue<Edge> queue = new PriorityQueue<>(new Comparator<Edge>() {
			@Override
			public int compare(Edge o1, Edge o2) {
				return Integer.compare(o1.dst, o2.dst);
			}
		});
		// queueにrootから出ているedgeを追加する
		queue.addAll(nodes[0].getEdges());
		long[] distances = new long[N];
		Arrays.fill(distances, Long.MAX_VALUE / 2);
		distances[0] = 0;
		while (!queue.isEmpty()) {
			Edge edge = queue.poll();
			distances[edge.dst] = Math.min(distances[edge.dst], distances[edge.src] + edge.c);
			queue.addAll(nodes[edge.dst].getEdges());
		}
		if (distances[N - 1] >= Long.MAX_VALUE / 2) {
			System.out.println(-1);
		} else {
			System.out.println(distances[N - 1]);
		}
	}
}

