            				mapLow.put(now, mapLow.get(next));
            			}
            			continue;
            		}
            		number++;
            		low = bridgeDfs(next, now);
        			if(mapLow.get(now) > low) {
        				mapLow.put(now, low);
        			}
            	}
            	return mapLow.get(now);
