import java.io.PrintWriter;
import java.util.*;

public class Main {
    PrintWriter out = new PrintWriter(System.out);
    final long max = Long.MAX_VALUE/10;
    int n=1;
    long[] dat;
    public static void main(String[] args) {
        Main main = new Main();
        System.out.println(main.solve());
    }
    // segment tree to record minimum value
    // Each point has a infinite distance from 0 (except itself)
    long solve() {
        Scanner sc = new Scanner(System.in);
        int n0 = sc.nextInt(), m = sc.nextInt();
        while(n<n0) n*=2; // let n be 1<<x
        dat = new long[2*n]; // this is why something like 4*n0+10 is safe
        for(int i=0;i<2*n-1;i++) dat[i] = max;
        update(0,0);
        Edge[] edges = new Edge[m];
        for(int i=0;i<m;i++){
            edges[i] = new Edge(sc.nextInt()-1, sc.nextInt()-1, sc.nextInt());
        }
        Arrays.sort(edges);
        if(edges[0].from!=0) return -1;
        for(Edge e:edges){
            int end = e.to;
            long curVal = find(end,end), prev = find(e.from,end-1);
            if(prev+e.cost<curVal){
                update(end,prev+e.cost);
            }
        }
        long ans = find(n0-1,n0-1);
        if(ans<max) return ans;
        return -1;
    }
    // find the minimum value in [left, right]
    long find(int left, int right){
        return query(left, right+1, 0, 0, n);
    }
    void update(int idx, long val){
        idx += n-1;
        dat[idx] = val;
        // update in an upward direction
        while(idx>0){
            idx = (idx-1)/2;
            dat[idx] = Math.min(dat[idx*2+1], dat[idx*2+2]);
        }
    }
    // find the minimum value in [a,b)
    // when invoking, query(a,b,0,0,n), n is the adjusted value ( n = 1<<x)
    long query(int a, int b, int idx, int left, int right){
        if(right<=a||left>=b) return max;
        if(a<=left&&right<=b) return dat[idx];
        int mid = (left+right)/2;
        long vl = query(a,b,2*idx+1, left, mid);
        long vr = query(a,b,2*idx+2, mid, right);
        return Math.min(vl,vr);
    }
    class Edge implements Comparable<Edge>{
        int from,to, cost;
        public Edge(int f, int t, int c){
            from = f; to = t; cost = c;
        }
        public int compareTo(Edge e){
            if(this.from!=e.from) return Integer.compare(from, e.from);
            if(this.to!=e.to) return Integer.compare(to, e.to);
            return cost-e.cost;
        }
    }
}

import java.util.*;

import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	static class Pair {
		int l, r;
		long c;

		Pair(int l, int r, long c) {
			this.l = l;
			this.r = r;
			this.c = c;
		}
	}

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		int N, M;
		String[] tokens = in.readLine().split(" ");
		N = Integer.parseInt(tokens[0]);
		M = Integer.parseInt(tokens[1]);
		List<Pair> sections = new ArrayList<>(M);
		for (int i = 0; i < M; ++i) {
			tokens = in.readLine().split(" ");
			sections.add(new Pair(Integer.parseInt(tokens[0]) - 1, Integer.parseInt(tokens[1]) - 1,
					Long.parseLong(tokens[2])));
		}
		long[] distances = new long[N];
		Arrays.fill(distances, Long.MAX_VALUE / 2);
		distances[0] = 0L;
		Collections.sort(sections, new Comparator<Pair>() {
			@Override
			public int compare(Pair o1, Pair o2) {
				if (o1.c != o2.c) {
					return Long.compare(o1.c, o2.c);
				} else {
					return -1 * Integer.compare(o1.r - o1.l, o2.r - o2.l);
				}
			}
		});
		Set<Integer> covered = new HashSet<>();
		List<Pair> useSecs = new ArrayList<>();
		for (int i = 0; i < sections.size(); ++i) {
			Pair sec = sections.get(i);
			useSecs.add(sec);
			for (int j = sec.l + 1; j <= sec.r; ++j) {
				covered.add(j);
			}
			if (covered.size() >= N - 1) {
				break;
			}
		}
		Collections.sort(useSecs, new Comparator<Pair>() {
			@Override
			public int compare(Pair o1, Pair o2) {
				if (o1.l != o2.l) {
					return Integer.compare(o1.l, o2.l);
				} else if (o2.r != o2.r) {
					return Integer.compare(o1.r, o2.r);
				} else {
					return Long.compare(o1.c, o2.c);
				}
			}
		});

		int left = 0;
		for (int i = 0; i < useSecs.size(); ++i) {
			Pair sec = useSecs.get(i);
			long baseDist = distances[sec.l];
			for (int j = left; j <= sec.r; ++j) {
				distances[j] = Math.min(distances[j], baseDist + sec.c);
			}
			left = sec.r;
		}
		if (distances[N - 1] >= Long.MAX_VALUE / 2) {
			System.out.println(-1);
		} else {
			System.out.println(distances[N - 1]);
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Set;

public class Main {

    private static class Entry {
        final int id;
        final long cost;

        Entry(int id, long cost) {
            this.id = id;
            this.cost = cost;
        }
    }

    public static void main(String[] args) throws IOException {
        int[][] costs;
        List<Set<Integer>> links = new ArrayList<>();
        int n, m;
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in))) {
            String[] array;
            array = in.readLine().split(" ");
            n = Integer.parseInt(array[0]);
            m = Integer.parseInt(array[1]);

            costs = new int[n][];
            for (int i = 0; i < n; ++i) {
                links.add(new HashSet<>());
                costs[i] = new int[i];
            }

            for (int i = 0; i < m; ++i) {
                array = in.readLine().split(" ");
                int l = Integer.parseInt(array[0]) - 1;
                int r = Integer.parseInt(array[1]) - 1;
                int c = Integer.parseInt(array[2]);

                for (int j = l; j < r; ++j) {
                    for (int k = j + 1; k <= r; ++k) {
                        int c0 = costs[k][j];
                        if (c0 != 0 && c0 <= c) {
                            continue;
                        }
                        costs[k][j] = c;
                        links.get(k).add(j);
                    }
                }
            }
        }

        int closed = n;
        PriorityQueue<Entry> h = new PriorityQueue<>(Comparator.comparingLong(e -> e.cost));
        h.add(new Entry(n - 1, 0));
        while (!h.isEmpty()) {
            Entry e = h.poll();

            int n1 = e.id;
            if (closed <= n1) {
                continue;
            }
            closed = n1;
            if (n1 == 0) {
                System.out.println(e.cost);
                System.exit(0);
            }

            long c1 = e.cost;
            for (int n2 : links.get(n1)) {
                long c2 = costs[n1][n2];
                h.add(new Entry(n2, c1 + c2));
            }
        }
        System.out.println(-1);
    }
}

