    static List<Node>[] g = new ArrayList[n];
    static long[] d = new long[n];

    public static void main(String[] args){
        d[0] = 0;
        for (int i=0; i<n; i++){
            g[i] = new ArrayList<>();
        }

        for (int i=0; i<n; i++) {
            g[i] = new ArrayList<Node>();
