        	// mapCnt, mapLow を設定する
            int bridgeDfs(int now, int pre) {
//            	prn("bridgeDfs  now = " + now + " number = " + number);
            	mark.add(now);
            	mapCnt.put(now, number);
            	mapLow.put(now, number);
