    long gcd(long a, long b){return b == 0 ? a : gcd(b, a % b);}
    long lcm(long a, long b){return a / gcd(a, b) * b;}

    void solve(){
        int N = in.nextInt(), M = in.nextInt();
        ArrayList<ArrayList<Edge>> G = new ArrayList<>();
        for(int i = 0; i < N; i++) G.add(new ArrayList<>());
        for(int i = 0; i < M; i++){
            int L = in.nextInt()-1;
            int R = in.nextInt()-1;
            long C = in.nextLong();
            G.get(L).add(new Edge(L, R, C));
        }
        for(int i = 1; i < N; i++) G.get(i).add(new Edge(i, i-1, 0));
        long[] res = dijkstra(G, 0);
        out.println(res[N-1] == Long.MAX_VALUE / 2 ? "-1" : res[N-1]);
    }
    //end solve

    class Edge implements Comparable<Edge>{
        int from;
        int to;
        long cost;
        public Edge(int f, int t, long c){
            from = f;to = t;cost = c;
        }
        @Override
        public int compareTo(Edge o) {
            return Long.compare(this.cost, o.cost);
        }
    }

    class Node implements Comparable<Node>{
        int index;
        long cost;
        public Node(int i, long c){
            index = i; cost = c;
        }
        @Override
        public int compareTo(Node o) {
            return Long.compare(this.cost, o.cost);
        }
    }

    long[] dijkstra(ArrayList<ArrayList<Edge>> g, int start){
        long INF = Long.MAX_VALUE / 2;
        long[] dist = new long[g.size()];
        Arrays.fill(dist, INF);
        dist[start] = 0;
        PriorityQueue<Node> priorityQueue = new PriorityQueue<Node>();
        priorityQueue.add(new Node(start, 0));

        while(!priorityQueue.isEmpty()){
            Node node = priorityQueue.poll();
            if(dist[node.index] < node.cost) continue;
            for(Edge e : g.get(node.index)){
                if(dist[e.to] > dist[node.index] + e.cost){
                    dist[e.to] = dist[node.index] + e.cost;
                    priorityQueue.add(new Node(e.to, dist[e.to]));
                }
            }
        }

        return dist;
    }

