        // 重み付きグラフの始点からの最短経路を求める　←　有向・無方向どちらも大丈夫
        // 優先度付きキューを使った版（速い）
        final int INF = 1000000010;
        final int WHITE = 0, GRAY = 1, BLACK = 2;
    													// グラフの隣接リスト(頂点と辺の長さ）
        GraphWith G = new GraphWith();
														// 辺の長さの短い順で並ぶ、優先度付きキュー
    	PriorityQueue<PP> PQ = new PriorityQueue<PP>(comparing(PP::getKey));

        int N, M;										// 頂点の数、辺の数
    	int[] d;										// d[3] なら 頂点３ から始点までの最短コストを記録する
    	int[] color;									// 白：未処理　黒：処理済み　グレー：

        // 先頭の頂点番号を指定する　０～
        void dijkstra(int s) {
        	Arrays.fill(d, INF);						// 変数の初期化
        	Arrays.fill(color, WHITE);
        	d[s] = 0;									// 先頭は　０
        	PQ.add(new PP(0,s));						// 優先度付きキューにいれるのは　辺の長さと頂点のペア（並びに注意）
        	int u, v;
        	PP p;
        	while(!PQ.isEmpty()) {
        		p = PQ.poll();							// 始点に一番近い頂点を取り出して、消す
        		u = p.getVal();							// 頂点の番号
        		color[u] = BLACK;

        		// 最小値を取り出して、それが最短でなければ無視
        		if(d[u] < p.getKey())	continue;

        		if(G.contains(u)) {
	        		for(PP wk : G.get(u)) {
	        			v = wk.getKey();					// u につながる頂点
	        			if(color[v] == BLACK)	continue;	// 処理済みなら　次へ
	        			if(d[v] > d[u] + wk.getVal()) {		// wk.getVal() が辺の長さ
	        				d[v] = d[u] + wk.getVal();
	        				PQ.add(new PP(d[v], v));
	        			}
	        		}
        		}
        	}
        }

        public void solve() {
    		N = ni();
    		M = ni();
    		d = new int[N];
    		color = new int[N];
    		int a, b, c;
    		for(int i=0; i < M; i++) {
    			a = ni() - 1;
    			b = ni() - 1;
    			c = ni();
    			G.add(a, new PP(b, c));
    			G.add(b, new PP(a, c));
    		}
    		for (int i = N - 1; i > 0; i--) {
				G.add(i, new PP(i-1, 0));
			}
    		// ダイクストラ
    		dijkstra(0);

    		prn(d[N-1] == INF ? -1 : d[N-1]);
        }

        // -----------------------------------------
        // Integer のキーに対して、Integer のカウントを管理する（カウントを足したり、引いたりする）
        // キーの最大、最小の取得、データの追加、削除も O(long(N)) で処理できる
        //
        static class MapCounter {
        	private TreeMap<Integer, Integer> map;
        	// 昇順のマップ
        	public MapCounter() {
        		map = new TreeMap<>();
        	}
        	// reverse = tree なら降順のマップ
        	public MapCounter(boolean reverse) {
        		if(reverse) {
        			map = new TreeMap<Integer, Integer>(Collections.reverseOrder());
        		} else {
            		map = new TreeMap<>();
        		}
        	}
        	// キーを追加する（キーが存在すれば、カウントに１足す）
        	public void add(Integer key) {
        		add(key, 1);
        	}
           	public void add(Integer key, int cnt) {
           		Integer val = map.get(key);
        		if(val == null) {
        			map.put(key, cnt);
        		} else {
        			map.put(key,  val + cnt);
        		}
        	}
        	// キーを消す（キーが存在すれば、カウントを１減らす）
        	public void remove(Integer key) {
        		sub(key, 1, false);
        	}
           	// キーのカウントを減らす
        	public void sub(Integer key) {
        		sub(key, 1);
        	}
        	// キーのカウントから値を引く（マイナスのカウントを許す）
        	public void sub(Integer key, int cnt) {
        		sub(key, cnt, true);
        	}
        	// キーのカウントから値を引く
        	//  →　マイナスを許可しない場合で、カウントがマイナスになったら消す
           	public void sub(Integer key, int cnt, boolean minus) {
        		Integer val = map.get(key);
        		if(val == null) {
        			if(minus) {
        				map.put(key, -cnt);				// カウントのマイナスを許す
        			}
        		} else if(val > cnt || minus){
       				map.put(key, val - cnt);
        		} else {
        			map.remove(key);
        		}
        	}
           	// キーのカウントを設定する
           	public void set(Integer key, int cnt) {
    			map.put(key, cnt);
        	}
           	// キーのカウントを取得する（なければ　ＮＵＬＬを返す）
        	public Integer getCountwithNull(Integer key) {
        		return map.get(key);
        	}
        	// キーのカウントを取得する（なければ　０　を返す）
        	public Integer getCount(Integer key) {
        		Integer val = map.get(key);
        		if(val == null)		return 0;
        		else 				return val;
        	}
        	public Set<Integer> getKey() {
        		return map.keySet();
        	}
        	// 登録されているキーの数を返す
        	public int getKeyCount() {
        		return map.keySet().size();
        	}
        	// 先頭キーを返す
        	public Integer getFirstKey() {
        		return map.firstKey();
        	}
        	// 最終キーを返す
        	public Integer getLastKey() {
        		return map.lastKey();
        	}
        	// マップの初期化
        	public void clear() {
        		map.clear();
        	}
       }
