{
    private const long INF = 1001001001;
        struct Edge : IComparable<Edge>
        {
            public int To;
            public long Cost;

            public int CompareTo(Edge other)
            {
                if (Cost > other.Cost) return 1;
                if (Cost == other.Cost) return 0;
                return -1;
            }
        }

        class PriorityQueue<T> where T : IComparable<T>
        {
            public readonly T[] Array;
            public readonly bool Greater;
            public int Count { get; private set; }

            public PriorityQueue(int capacity, bool greater = true)
            {
                Array = new T[capacity];
                Greater = greater;
            }

            public void Enqueue(T item)
            {
                Array[Count] = item;
                Count += 1;
                UpHeap();
            }

            public T Dequeue()
            {
                // 先頭要素を末尾にして再構成
                Swap(0, Count - 1);
                Count -= 1;
                DownHeap();

                return Array[Count];
            }


            private void UpHeap()
            {
                var n = Count - 1;
                while (n != 0)
                {
                    // 親要素の座標
                    var parent = (n - 1) / 2;

                    if (Compare(Array[n], Array[parent]) > 0)
                    {
                        Swap(n, parent);
                        n = parent;
                    }
                    else
                    {
                        break;
                    }
                }
            }

            private void DownHeap()
            {
                var parent = 0;
                while (true)
                {
                    var child = 2 * parent + 1;
                    if (child > Count - 1) break;

                    if (child < Count - 1 && Compare(Array[child], Array[child + 1]) < 0)
                    {
                        // 左より右の子のほうが大きい値の場合、右を入れ替え対象にする
                        child += 1;
                    }

                    if (Compare(Array[parent], Array[child]) < 0)
                    {
                        Swap(parent, child);
                        parent = child;
                    }
                    else
                    {
                        break;
                    }
                }
            }

            private int Compare(T a, T b)
            {
                var c = a.CompareTo(b);
                if (!Greater)
                {
                    c = -c;
                }
                return c;
            }

            private void Swap(int a, int b)
            {
                var tmp = Array[a];
                Array[a] = Array[b];
                Array[b] = tmp;
            }
        }

