                    long cost = longInput[2];

                    var e = new Edge {To = r, Cost = cost};
                    if (G[l] == null) G[l] = new List<Edge>();
                    G[l].Add(e);
                }

//                for (int i = 0; i < n; i++)
//                {
//                    foreach (var e in G[i])
//                    {
//                        WriteLine($"From:{i}To:{e.To}Cost:{e.Cost}");
//                    }
//                }

                var pq = new PriorityQueue<Edge>(100000);
                pq.Enqueue(new Edge {Cost = 0, To = 0});
                var d = new long[n];
                for (int i=0; i < n; i++) d[i] = INF;
