                            pp.first = e.To;
                            pp.second = d[e.To];
                            pq.Enqueue(pp);
                        }
                    }

                }

                long ans = d[n - 1];
                if (ans == INF) ans = -1;
                WriteLine(ans);
            }
            catch (Exception e)
            {
                WriteLine(e.StackTrace);
            }

        }
    }

