public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int M = GetInt();
		int[] L = new int[M];
		int[] R = new int[M];
		long[] C = new long[M];
		for(int i = 0; i < M; i++)
		{
			L[i] = GetInt() - 1;
			R[i] = GetInt() - 1;
			C[i] = GetLong();
		}

		var pq = new PriorityQueue<Range>(M, (x, y) => y.Right - x.Right);
		for(int i = 0; i < M; i++)
			pq.Push(new Range(L[i], R[i], C[i]));

		var next = new SortedSet<int>();
		long[] d = Enumerable.Repeat(-1L, N).ToArray();
		int pos = N - 1;
		d[pos] = 0;
		while(pq.Size > 0)
		{
			var range = pq.Pop();
			while(next.Count > 0 && pos > range.Right)
			{
				pos = next.Max;
				next.Remove(pos);
			}
			if(pos > range.Right)
				break;

			if(pos < range.Left)
				continue;

			if(d[range.Left] == -1)
				d[range.Left] = d[pos] + range.Cost;
			else
				chmin(ref d[range.Left], d[pos] + range.Cost);

			next.Add(range.Left);
		}

		if(d[0] == -1)
			Console.WriteLine(-1);
		else
			Console.WriteLine(d[0]);
	}

	private void chmin(ref long x, long y) => x = Math.Min(x, y);
}

public class PriorityQueue<T>
{
	public long Size { get; private set; } = 0;
	public long MaxSize { get; private set; } = 0;
	private T[] m_heap;
	private Comparison<T> Comp = null;

	public PriorityQueue(long maxSize, Comparison<T> comp)
	{
		if(maxSize <= 0)
			throw new Exception();
		MaxSize = maxSize;
		m_heap = new T[maxSize];

		Comp = comp;
	}

	public void Push(T x)
	{
		if(Size == MaxSize)
		{
			T[] new_heap = new T[MaxSize << 1];
			Array.Copy(m_heap, new_heap, MaxSize);
			m_heap = new_heap;
			MaxSize <<= 1;
		}

		long i = Size++;
		while(i > 0)
		{
			long p = (i - 1)/2;
			if(Comp(m_heap[p], x) <= 0)
				break;
			m_heap[i] = m_heap[p];
			i = p;			
		}
		m_heap[i] = x;		
	}

	public T Pop()
	{
		if(Size == 0)
			throw new Exception("Queue is empty.");

		T result = m_heap[0];
		T x = m_heap[--Size];
		long i = 0;
		while(i * 2 + 1 < Size)
		{
			long c1 = i * 2 + 1, c2 = i * 2 + 2;
			if(c2 < Size && Comp(m_heap[c2], m_heap[c1]) < 0)
				c1 = c2;
			if(Comp(m_heap[c1], x) >= 0)
				break;
			m_heap[i] = m_heap[c1];
			i = c1;
		}
		m_heap[i] = x;

		return result;		
	}	
}

