//                    WriteLine($"To:{v.To}Cost:{v.Cost}");
                    if (d[v.To] < v.Cost) continue;
                    foreach (var e in G[v.To])
                    {
                        if (d[e.To] > d[v.To] + e.Cost)
                        {
                            d[e.To] = d[v.To] + e.Cost;
                            pq.Enqueue(new Edge{Cost = d[e.To], To = e.To});
                        }
                    }

                }

                long ans = d[n - 1];
                if (ans == INF) ans = -1;
                WriteLine(ans);
            }
            catch (Exception e)
            {
                WriteLine(e.StackTrace);
            }

        }
    }

