        public List<long> ScanLongs(int count) => Enumerable.Range(0, count).Select(_ => Scan).ToList();
        public List<long> ScanLongs(long count) => ScanLongs((int)count);
        public int ScanInt => int.Parse(Str);
        public long Scan => long.Parse(Str);
        public double ScanDouble => (double)Scan;

        StringBuilder sb = new StringBuilder();

        public string Str => ScanStr();
        public string ScanStr()
        {
            sb.Clear();

            int r = 0;
            bool? b = null;
            do
            {
                r = Console.Read();
                b = IsBreak(r);
            } while (b == true);

            if (b == null)
                throw new Exception("input error: unexpected end of stream");

            do
            {
                sb.Append((char)r);
                r = Console.Read();
                b = IsBreak(r);
            } while (b == false);

            return sb.ToString();
        }

        bool? IsBreak(int c)
        {
            switch (c)
            {
                case -1:
                    return null;
                case (int)' ':
                case (int)'\n':
                case (int)'\r':
                    return true;
                default:
                    return false;
            }
        }

        public IEnumerable<int> Loop(int count) => Enumerable.Range(0, count);
        public IEnumerable<int> Loop(int from, int to) => Enumerable.Range(from, to - from + 1);

        public IEnumerable<long> Loop(long count) => Loop(0, count - 1);
        public IEnumerable<long> Loop(long from, long to)
        {
            for (long i = from; i <= to; i++)
                yield return i;
        }

        public string YesNo(bool isYes) => isYes ? "Yes" : "No";

        public HashSet<T> ToHashSet<T>(IEnumerable<T> ts) => new HashSet<T>(ts);

        public class LRC
        {
            public int L { get; set; }
            public int R { get; set; }
            public long C { get; set; }
        }

        public IEnumerable<string> Solve()
        {
            var n = ScanInt;
            var m = ScanInt;

            var lrcs = new List<LRC>();

            foreach (var i in Loop(m))
            {
                lrcs.Add(new LRC()
                {
                    L = ScanInt - 1,
                    R = ScanInt - 1,
                    C = Scan,
                });
            }

            lrcs = lrcs.OrderBy(x => x.L).ThenBy(x => x.C).ThenByDescending(x => x.R).ToList();

            var ds = Enumerable.Range(0, n).Select(_ => long.MaxValue).ToArray();
            ds[0] = 0;

            foreach (var lrc in lrcs)
            {
                if (ds[lrc.L] == long.MaxValue)
                {
                    yield return (-1).ToString();
                    yield break;
                }

                var newD = ds[lrc.L] + lrc.C;

                for (int i = lrc.R; i >= lrc.L + 1; i--)
                {
                    if (newD < ds[i])
                        ds[i] = newD;
                    else
                        break;
                }
            }

            var res = ds[n - 1] == long.MaxValue ? -1 : ds[n - 1];
            yield return res.ToString();
        }
    }
}

