public class Scanner {
    private readonly TextReader Reader;
    private readonly Queue<string> TokenQueue = new Queue<string>();
    private readonly CultureInfo ci = CultureInfo.InvariantCulture;

    public Scanner()
        : this(Console.In) {
    }

    public Scanner(TextReader reader) {
        Reader = reader;
    }

    public int NextInt() { return int.Parse(Next(), ci); }
    public long NextLong() { return long.Parse(Next(), ci); }
    public double NextDouble() { return double.Parse(Next(), ci); }
    public string[] NextArray(int size) {
        string[] array = new string[size];
        for (int i = 0; i < size; i++) {
            array[i] = Next();
        }

        return array;
    }
    public int[] NextIntArray(int size) {
        int[] array = new int[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextInt();
        }

        return array;
    }

    public long[] NextLongArray(int size) {
        long[] array = new long[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextLong();
        }

        return array;
    }

    public double[] NextDoubleArray(int size) {
        double[] array = new double[size];
        for (int i = 0; i < size; i++) {
            array[i] = NextDouble();
        }

        return array;
    }

    public string Next() {
        if (TokenQueue.Count == 0) {
            if (!StockTokens()) {
                throw new InvalidOperationException();
            }
        }
        return TokenQueue.Dequeue();
    }

    public bool HasNext() {
        if (TokenQueue.Count > 0) {
            return true;
        }

        return StockTokens();
    }

    private static readonly char[] _separator = new[] { ' ', '\t' };
    private bool StockTokens() {
        while (true) {
            string line = Reader.ReadLine();
            if (line == null) {
                return false;
            }

            string[] tokens = line.Split(_separator, StringSplitOptions.RemoveEmptyEntries);
            if (tokens.Length == 0) {
                continue;
            }

            foreach (string token in tokens) {
                TokenQueue.Enqueue(token);
            }

            return true;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;

public static class Program
{
    private const long INF = 1001001001;
        struct Edge : IComparable<Edge>
        {
            public int To;
            public long Cost;

            public int CompareTo(Edge other)
            {
                if (Cost > other.Cost) return 1;
                if (Cost == other.Cost) return 0;
                return -1;
            }
        }

        class PriorityQueue<T> where T : IComparable<T>
        {
            public readonly T[] Array;
            public readonly bool Greater;
            public int Count { get; private set; }

            public PriorityQueue(int capacity, bool greater = true)
            {
                Array = new T[capacity];
                Greater = greater;
            }

            public void Enqueue(T item)
            {
                Array[Count] = item;
                Count += 1;
                UpHeap();
            }

            public T Dequeue()
            {
                // 先頭要素を末尾にして再構成
                Swap(0, Count - 1);
                Count -= 1;
                DownHeap();

                return Array[Count];
            }


            private void UpHeap()
            {
                var n = Count - 1;
                while (n != 0)
                {
                    // 親要素の座標
                    var parent = (n - 1) / 2;

                    if (Compare(Array[n], Array[parent]) > 0)
                    {
                        Swap(n, parent);
                        n = parent;
                    }
                    else
                    {
                        break;
                    }
                }
            }

            private void DownHeap()
            {
                var parent = 0;
                while (true)
                {
                    var child = 2 * parent + 1;
                    if (child > Count - 1) break;

                    if (child < Count - 1 && Compare(Array[child], Array[child + 1]) < 0)
                    {
                        // 左より右の子のほうが大きい値の場合、右を入れ替え対象にする
                        child += 1;
                    }

                    if (Compare(Array[parent], Array[child]) < 0)
                    {
                        Swap(parent, child);
                        parent = child;
                    }
                    else
                    {
                        break;
                    }
                }
            }

            private int Compare(T a, T b)
            {
                var c = a.CompareTo(b);
                if (!Greater)
                {
                    c = -c;
                }
                return c;
            }

            private void Swap(int a, int b)
            {
                var tmp = Array[a];
                Array[a] = Array[b];
                Array[b] = tmp;
            }
        }

        public static void Main(string[] args)
        {
            try
            {
                var intInput = ReadLine().Split(' ').Select(int.Parse).ToArray();
                int n = intInput[0];
                int m = intInput[1];

                //グラフの生成
                var G = new List<Edge>[n];
                for (int i = 0; i < n-1; i++)
                {
                    var e = new Edge {To = i, Cost = 0};
                    if (G[i+1] == null) G[i+1] = new List<Edge>();
                    G[i+1].Add(e);
                }

                for (int i = 0; i < m; i++)
                {
                    var longInput = ReadLine().Split(' ').Select(int.Parse).ToArray();
                    int l = longInput[0] - 1;
                    int r = longInput[1] - 1;
                    long cost = longInput[2];

                    var e = new Edge {To = r, Cost = cost};
                    if (G[l] == null) G[l] = new List<Edge>();
                    G[l].Add(e);
                }

//                for (int i = 0; i < n; i++)
//                {
//                    foreach (var e in G[i])
//                    {
//                        WriteLine($"From:{i}To:{e.To}Cost:{e.Cost}");
//                    }
//                }

                var pq = new PriorityQueue<Edge>(10);
                pq.Enqueue(new Edge {Cost = 0, To = 0});
                var d = new long[n];
                for (int i=0; i < n; i++) d[i] = INF;
                d[0] = 0;
                while (pq.Count > 0)
                {
                    var v = pq.Dequeue();
//                    WriteLine($"To:{v.To}Cost:{v.Cost}");
                    if (d[v.To] < v.Cost) continue;
                    foreach (var e in G[v.To])
                    {
                        if (d[e.To] > d[v.To] + e.Cost)
                        {
                            d[e.To] = d[v.To] + e.Cost;
                            pq.Enqueue(new Edge{Cost = d[e.To], To = e.To});
                        }
                    }

                }

                long ans = d[n - 1];
                if (ans == INF) ans = -1;
                WriteLine(ans);
            }
            catch (Exception e)
            {
                WriteLine(e.StackTrace);
            }

        }
    }

