class D
{
	static void Main()
	{
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var h = read();
		var qs = new int[h[1]].Select(_ => read()).OrderBy(x => x[1]).ThenBy(x => x[0]).ThenBy(x => x[2]).ToArray();

		var dp = Enumerable.Repeat(-1L, h[0] + 1).ToArray();
		dp[1] = 0;

		foreach (var q in qs)
		{
			if (dp[q[0]] == -1) continue;
			var d = dp[q[0]] + q[2];

			for (int i = q[1]; i > 0; i--)
			{
				if (dp[i] != -1 && dp[i] <= d) break;
				dp[i] = d;
			}
		}
		Console.WriteLine(dp[h[0]]);
	}
}

using System;
using System.Collections.Generic;

public class Program
{
    private int N, M;
    private S[] LRC;

    private const long Inf = 999999999999999;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        LRC = new S[M];
        for (int i = 0; i < M; i++)
        {
            LRC[i] = new S(sc.NextInt() - 1, sc.NextInt() - 1, sc.NextInt());
        }

        var st = new SegTree<long>(N, Inf);

        st[0] = 0;

        Array.Sort(LRC, (a, b) => a.L.CompareTo(b.L));

        foreach (S s in LRC)
        {
            long tmp = st[s.R];
            long min = st.Query(s.L, s.R);
            st[s.R] = Math.Min(tmp, min + s.C);
        }

        long ans = st[N - 1];
        Console.WriteLine(ans == Inf ? -1 : ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

struct S
