{
    private static readonly long INF = 1001001000100;
        struct Edge : IComparable<Edge>
        {
            public int To;
            public long Cost;

            public int CompareTo(Edge other)
            {
                if (Cost > other.Cost) return 1;
//                if (Cost == other.Cost) return 0;
                return -1;
            }
        }

        struct Pair<T, U> : IComparable<Pair<T, U>>
            where T : IComparable<T>
            where U : IComparable<U>
        {
            public T first;
            public U second;
            private bool CompWithFirst;

            public Pair(T f, U s, int comp)
            {
                first = f;
                second = s;
                CompWithFirst = comp == 1;
            }

            public int CompareTo(Pair<T, U> other)
            {
                return CompWithFirst ? first.CompareTo(other.first) : second.CompareTo(other.second);
            }
        }

     public class PriorityQueue<T> where T : IComparable<T>
    {

        private List<T> Q;
        private readonly int r;

        public PriorityQueue(bool ascending)
        {
            if (ascending)
            {
                r = 1;
            }
            else
            {
                r = -1;
            }
            Q = new List<T>();
        }


        private void PushHeap(List<T> list, T item)
        {
            int n = list.Count();
            list.Add(item);

            while (n != 0)
            {
                int pIndex = (n - 1) / 2;

                if (list[n].CompareTo(list[pIndex]) * r > 0)
                {
                    Swap(Q, n, pIndex);
                }
                else { break; }

                n = pIndex;
            }
        }

        private void PopHeap(List<T> list)
        {
            int n = list.Count() - 1;
            list[0] = list[n];
            list.RemoveAt(n);

            int cur = 0;
            int comp;

            while (2 * cur + 1 <= n - 1)
            {
                int c1 = 2 * cur + 1;
                int c2 = 2 * (cur + 1);
                if (c1 == n - 1)
                {
                    comp = c1;
                }
                else
                {

                    comp = list[c1].CompareTo(list[c2]) * r > 0 ? c1 : c2;
                }

                if (list[cur].CompareTo(list[comp]) * r < 0)
                {
                    Swap(Q, cur, comp);
                }
                else { break; }

                cur = comp;
            }
        }

        private void Swap(List<T> list, int a, int b)
        {
            T keep = list[a];
            list[a] = list[b];
            list[b] = keep;
        }



        public void Enqueue(T value)
        {
            PushHeap(Q, value);
        }

        public T Dequeue()
        {
            T ret = Q[0];
            PopHeap(Q);
            return ret;
        }

        public T Peek()
        {
            return Q[0];
        }

        public int CountItem()
        {
            return Q.Count();
        }
    }
        public static void Main(string[] args)
        {
            try
            {
                var intInput = ReadLine().Split(' ').Select(int.Parse).ToArray();
                int n = intInput[0];
                int m = intInput[1];

                //グラフの生成
                var G = new List<Edge>[n];
                for (int i = 0; i < n-1; i++)
                {
                    var e = new Edge {To = i, Cost = 0};
                    if (G[i+1] == null) G[i+1] = new List<Edge>();
                    G[i+1].Add(e);
                }

                for (int i = 0; i < m; i++)
                {
                    var longInput = ReadLine().Split(' ').Select(long.Parse).ToArray();
                    int l = (int)longInput[0] - 1;
                    int r = (int)longInput[1] - 1;
                    long cost = longInput[2];

                    var e = new Edge {To = r, Cost = cost};
                    if (G[l] == null) G[l] = new List<Edge>();
                    G[l].Add(e);
                }

//                for (int i = 0; i < n; i++)
//                {
//                    foreach (var e in G[i])
//                    {
//                        WriteLine($"From:{i}To:{e.To}Cost:{e.Cost}");
//                    }
//                }

                var pq = new PriorityQueue<Pair<int, long>>(false);
                var p = new Pair<int, long>();
                p.first = 0;
                p.second = 0;
                pq.Enqueue(p);
                var d = new long[n];
                for (int i=0; i < n; i++) d[i] = INF;
                d[0] = 0;
                while (pq.CountItem() > 0)
                {
                    var v = pq.Dequeue();
//                    WriteLine($"To:{v.To}Cost:{v.Cost}");
                    if (d[v.first] < v.second) continue;
                    foreach (var e in G[v.first])
                    {
                        if (d[e.To] > d[v.first] + e.Cost)
                        {
                            d[e.To] = d[v.first] + e.Cost;
                            var pp = new Pair<int, long>();
                            pp.first = e.To;
                            pp.second = d[e.To];
                            pq.Enqueue(pp);
                        }
                    }

                }

                long ans = d[n - 1];
                if (ans == INF) ans = -1;
                WriteLine(ans);
            }
            catch (Exception e)
            {
                WriteLine(e.StackTrace);
