    class Program
    {
        static void Main(string[] args)
        {
            var N = RInt;
            var M = RInt;

            List<Edge>[] edges = new List<Edge>[N].Select(x => new List<Edge>()).ToArray();
            for (int i = 0; i < M; i++)
            {
                var l = RInt - 1;
                var r = RInt - 1;
                var c = RInt;
                edges[l].Add(new Edge() { to = r, cost = c });
            }
            for (int i = 1; i < N; i++)
            {
                edges[i].Add(new Edge() { to = i - 1, cost = 0 });
            }

            Queue<int> que = new Queue<int>();
            que.Enqueue(0);
            bool[] accessed = new bool[N];
            long[] distance = new long[N].Select(x => long.MaxValue).ToArray();
            distance[0] = 0;

            while (que.Count > 0)
            {
                var now = que.Dequeue();

                foreach (var e in edges[now])
                {
                    var cand = distance[now] + e.cost;
                    if(cand < distance[e.to])
                    {
                        distance[e.to] = cand;
                        que.Enqueue(e.to);
                    }
                }
            }

            var ans = distance.Last();
            if (ans == long.MaxValue) ans = -1;
            Console.WriteLine(ans);
        }

        struct Edge
        {
            public int to;
            public long cost;
        }

    }


