public static class Entry
{

	public static void Main() {
		checked{
			long n, m;
			Lib_IO.rm(out n, out m);
			P<ll,ll,ll>[] lrc;
			rl(m,out lrc);

			List<P<ll,ll,ll>> e = new List<P<ll, ll, ll>>();
			foreach (var q in lrc)
			{
				e.Add(new P<ll, ll, ll>(q.A-1,q.B-1,q.C));
			} 
			for (int i = 0 ;i < n-1; i++)
			{
				e.Add(new P<ll, ll, ll>(i+1,i,0));
			}
			var d = Dijkstra(e.ToArray(),n,0);

			long ans = (d[n-1]==ll.MaxValue||d[n-1]<0?-1:d[n-1]);

			Lib_IO.wm(ans);
		}
	}

	public static long[] Dijkstra(P<long,long,long>[] inEdges, long V, long start, out long[] prev) {
		long[] dist = Enumerable.Repeat(long.MaxValue, (int)V).ToArray();
		prev = Enumerable.Repeat(-1L, (int)V).ToArray();
		var G = new Dictionary<long,long>[V]; 
		for(int i=0;i<V;i++) G[i] = new Dictionary<long,long>();
		foreach(var e in inEdges){
			G[e.A][e.B] = e.C;
			//G[e.B][e.A] = e.C;
		}

		var que = new PriorityQueue<KeyValuePair<long, long>>(V, (x,y)=>(x.Key.CompareTo(y.Key)));
		dist[start] = 0;
		que.Enqueue(new KeyValuePair<long, long>(dist[start], start));
		while(0<que.Count) {
			var q = que.Dequeue();
			if(dist[q.Value] < q.Key) continue;
			foreach(var e in G[q.Value]){
				var next_cost = q.Key + e.Value;
				if(dist[e.Key] <= next_cost) continue;
				dist[e.Key] = next_cost;
				que.Enqueue(new KeyValuePair<long, long>(dist[e.Key], e.Key));
			   	prev[e.Key] = q.Value;
			}
		}
		return dist;
	}
