		cur, _ := q.Pop().(int)
		for _, edge := range e[cur] {
			if d[cur]+edge.Cost < d[edge.To] {
				d[edge.To] = d[cur] + edge.Cost
				q.Push(d[edge.To], edge.To)
			}
		}
	}

	if d[n-1] == inf {
		stdout.Println(-1)
	} else {
		stdout.Println(d[n-1])
	}
}

