	for index := 0; index < M; index++ {
		ls = append(ls, oneInt())
		rs = append(rs, oneInt())
		cs = append(cs, oneInt())
	}

	cost, nokori := find(N, ls, rs, cs)
	var tempCost int
	for nokori != 1 {
		tempCost, nokori = find(nokori, ls, rs, cs)
		if tempCost == -1 {
			fmt.Print(-1)
			return
		}
		cost += tempCost
	}
	fmt.Print(cost)
}

func find(mokuteki int, ls, rs, cs []int) (cost, nokori int) {
	tempCost := 1000000000000
	tempNoko := mokuteki + 1
	var retIndex int
	for i, v := range rs {
		if v >= mokuteki && mokuteki > ls[i] {
			perConst := (mokuteki - ls[i]) / cs[i]
			if tempCost > perConst {
				tempCost = perConst
				tempNoko = ls[i]
				retIndex = i
			}
		}
	}

	if tempCost == 1000000000000 {
		return -1, -1
	}

	return cs[retIndex], tempNoko
}

