func NewPq(c int) Pq {
	p := make(Pq, 1, c)
	p[0] = pqe{v: -1, p: -1}
	return p
}
func (pq *Pq) mhf(i int) {
	for {
		lc, rc := 2*i, 2*i+1
		var lg int
		if lc < len(*pq) && (*pq)[lc].p > (*pq)[i].p {
			lg = lc
		} else {
			lg = i
		}
		if rc < len(*pq) && (*pq)[rc].p > (*pq)[lg].p {
			lg = rc
		}
		if lg == i {
			break
		}
		(*pq)[i], (*pq)[lg] = (*pq)[lg], (*pq)[i]
		i = lg
	}
}
func (pq *Pq) Insert(v interface{}, p int) {
	*pq = append(*pq, pqe{v, p})
	for i := len(*pq) - 1; i > 1 && (*pq)[i].p > (*pq)[i/2].p; i = i / 2 {
		(*pq)[i], (*pq)[i/2] = (*pq)[i/2], (*pq)[i]
	}
}
func (pq *Pq) Extract() interface{} {
	if len(*pq) <= 1 {
		return nil
	}
	me := (*pq)[1]
	(*pq)[1] = (*pq)[len(*pq)-1]
	*pq = (*pq)[:len(*pq)-1]
	(*pq).mhf(1)
	return me.v
}
