type wEdge struct{ to, c int }

func solve() {
	n, m := ri(), ri()
	g := make([][]wEdge, n)
	for i := 0; i < m; i++ {
		l, r, c := ri()-1, ri()-1, ri()
		g[l] = append(g[l], wEdge{to: r, c: c})
		g[r] = append(g[r], wEdge{to: l, c: c})
	}
	for i := 1; i < n; i++ {
		g[i] = append(g[i], wEdge{to: i - 1, c: 0})
	}
	s := 0
	pq := NewPq(len(g))
	d, u := make([]int, len(g)), make([]int, len(g))
	for i := range u {
		d[i], u[i] = inf, 0
	}
	d[s], u[s] = 0, 1
	pq.Insert(wEdge{0, 0}, 0)
	for pq.Size() != 0 {
		we := pq.Extract().(wEdge)
		u[we.to] = 2
		if d[we.to] < we.c {
			continue
		}
		for _, e := range g[we.to] {
			if u[e.to] != 2 && d[e.to] > d[we.to]+e.c {
				d[e.to], u[e.to] = d[we.to]+e.c, 1
				pq.Insert(wEdge{e.to, d[e.to]}, -d[e.to])
			}
		}
	}
	if d[n-1] == inf {
		pln(-1)
	} else {
		pln(d[n-1])
	}
}

