type Item struct {
  id int
  wt int64
}

type PriorityQueue []*Item
func(pq PriorityQueue) Len() int { return len(pq) }
func(pq PriorityQueue) Less(i,j int) bool { return pq[i].wt < pq[j].wt }
func(pq PriorityQueue) Swap(i,j int) { pq[i],pq[j] = pq[j],pq[i] }
func(pq *PriorityQueue) Push(x interface{}) {
  item := x.(*Item)
  *pq = append(*pq,item)
}
func(pq *PriorityQueue) Pop() interface{} {
  old := *pq
  n := len(old)
  item := old[n-1]
  *pq = old[0:n-1]
  return item
}

type Graph [][]Item
func NewGraph(n int) Graph { return make([][]Item,n) }
func(g Graph) AddEdge(from int,item Item) { g[from] = append(g[from],item) }
func(g Graph) Add(from,to int,wt int64) { g.AddEdge(from,Item{to,wt}) }
func(g Graph) Dijkstra(s int) []int64 {
  n := len(g)
  d := make([]int64,n)
  for i:=0;i<n;i++ { d[i] = INF }
  d[s] = 0
  var pq PriorityQueue
  heap.Init(&pq)
  heap.Push(&pq,&Item{s,d[s]})
  for pq.Len() > 0 {
    i := heap.Pop(&pq).(*Item)
    if i.wt > d[i.id] { continue }
    for _,e := range g[i.id] {
      if d[e.id] > i.wt+e.wt {
        d[e.id] = i.wt+e.wt
        heap.Push(&pq,&Item{e.id,d[e.id]})
      }
    }
  }
  return d
}

