void solve(){
	int n = rint, m = rint;

	P[] ps;
	foreach(_; 0 .. m){
		int l = rint - 1, r = rint - 1;
		long c = rlong;
		ps ~= P(l, r, c);
	}
	ps.sort!"a.l<b.l"();
	log("ps:", ps);

	auto seg = new SegTree!long(0, n, (long x, long y) => min(x, y), 1_000_000_000_000);

	foreach(p; ps){
		seg.setValue(p.l, p.r + 1, seg.getValue(p.l) + p.c);
	}

