alias P = Tuple!(int, "p", long, "c", long, "max_c");

void main()
{
    auto nm = readln.split.to!(int[]);
    auto N = nm[0];
    auto M = nm[1];
    auto ps = new P[](M);
    P[][] G;
    G.length = N;
    foreach (i; 1..N) G[i] ~= P(i-1, 0, long.max);
    foreach (i; 0..M) {
        auto lrc = readln.split.to!(int[]);
        auto l = lrc[0]-1;
        auto r = lrc[1]-1;
        long c = lrc[2];
        G[l] ~= P(r, c, long.max);
    }

    auto Q = priority_queue!("a.max_c < b.max_c", P)([P(0, 0, 0)]);
    long res = -1;
    while (!Q.empty) {
        auto p = Q.dequeue();
        foreach (ref r; G[p.p]) if (r.max_c > p.max_c + r.c) {
            r.max_c = p.max_c + r.c;
            if (r.p == N-1) {
                if (res == -1) {
                    res = r.max_c;
                } else {
                    res = min(res, r.max_c);
                }
            }
            Q.enqueue(r);
        }
    }
    writeln(res);
    return;
}

