            {
                long eCount = this[x, y].to!string.length;
                static if(is(typeof(this[x,y].isInf)))
                {
                    if(this[x,y].isInf)
                    {
                        eCount = 1;
                    }
                }
                static if(is(typeof(this[x,y])==bool))
                {
                    eCount = 1;
                }
                count = max(count, eCount);
            }
        }
        count++;

        string res = "\n";
        foreach(y; 0..height)
        {
            foreach(x; 0..width)
            {
                string joinStr = this[x, y].to!string;
                static if(is(typeof(this[x,y].isInf)))
                {
                    if(this[x,y].isInf)
                    {
                        joinStr = "*";
                    }
                }
                static if(is(typeof(this[x,y])==bool))
                {
                    joinStr = this[x,y]?"+":"-";
                }
                foreach(i;0..count-joinStr.length)
                {
                    res ~= ' ';
                }
                res ~= joinStr;
            }
            res ~= '\n';
        }
        return res;
    }
}

struct UnionFind{
    private int[] arr;
    int rootCount;

    @disable this();
    this(long n){
        arr.length = n.to!int;
        arr[] = -1;
        rootCount = n.to!int;
    }

    void merge(long a, long b)
    {
        merge(a.to!int, b.to!int);
    }
    void merge(int a, int b)
    {
        if(same(a,b)) return;
        arr[root(a)] = root(b);
        rootCount--;
    }

    bool same(long a, long b)
    {
        return same(a.to!int, b.to!int);
    }
    bool same(int a, int b)
    {
        return root(a)==root(b);
    }

    private int root(int i)
    {
        if(arr[i] == -1) return i;
        return arr[i] = root(arr[i]);
    }
}

