struct Factor
{
    long n;
    long c;
}

//素因数分解
Factor[] factors(long n) pure
{
    Factor[] res;
    for (long i = 2; i ^^ 2 <= n; i++)
    {
        if (n % i != 0)
            continue;

        long c;
        while (n % i == 0)
        {
            n = n / i;
            c++;
        }
        res ~= Factor(i, c);
    }
    if (n != 1)
        res ~= Factor(n, 1);

    return res;
}
//約数をすべて列挙
long[] divisors(long n) pure
{
    long[] list;
    void func(Factor[] fs, long n)
    {
        if(fs.empty){
            list ~= n;
            return;
        }

        foreach(c; 0..fs[0].c+1)
        {
            func(fs[1..$], n * (fs[0].n ^^ c));
        }
    }

    func(factors(n), 1);
    sort(list);
    return list;
}
//nまでの素数のリスト
long[] primes(long n) pure
{
    if(n<2)return [];

    auto table = new long[cast(size_t)n+1];

    long[] res;
    for(size_t i = 2;i<=n;i++)
    {
        if(table[i]==-1) continue;
        for(size_t a = i;a<table.length;a+=i)
        {
            table[a] = -1;
        }
        res ~= i;
    }
    return res;
}
//素数判定
bool isPrime(long n) pure
{
    if (n <= 1)
        return false;
    if (n == 2)
        return true;
    if (n % 2 == 0)
        return false;
    for (long i = 3; i ^^ 2 <= n; i += 2)
        if (n % i == 0)
            return false;
    return true;
}

//桁を数える
long digitCount(long n, long base=10) pure
{
    long res;
    do{
        n/=base;
        res++;
    }while(n!=0);

    return res;
}

import std.stdio, std.algorithm, std.conv, std.array, std.string, std.math, std.typecons, std.numeric, std.container, std.range;

alias P = Tuple!(int, "to", long, "c");

void main()
{
    auto nm = readln.split.to!(int[]);
    auto N = nm[0];
    auto M = nm[1];
    auto G = new P[][N];
    foreach (i; 1..N) {
        G[i] ~= P(i-1, 0);
    }
    foreach (_; 0..M) {
        auto lrc = readln.split.to!(int[]);
        auto L = lrc[0]-1;
        auto R = lrc[1]-1;
        long C = lrc[2];
        G[L] ~= P(R, C);
    }

    auto Q = heapify!"a.c > b.c"([P(0, 0)]);
    auto DP = new long[](N);
    DP[] = long.max/3;
    DP[0] = 0;
    while (!Q.empty) {
        auto i = Q.front.to;
        auto c = Q.front.c;
        Q.popFront();
        if (DP[i] < c) continue;
        foreach (n; G[i]) if (DP[n.to] > c + n.c) {
            DP[n.to] = c + n.c;
            Q.insert(P(n.to, c + n.c));
        }
    }
    writeln(DP[N-1] == long.max/3 ? -1 : DP[N-1]);
}

