using namespace std;
const int MAX = 1e9 + 7;
const int N = 1e6+7;

struct aa{
    int u,d;
    bool operator < (const aa & a) const{
        return d>a.d;
    }
};

vector<aa>arr[N];

bool vis[N];
int n,m;
int d[N];

void Dij(){
    fill(d+1,d+n+1,MAX);
    d[1]=0;
    priority_queue<aa>Q;
    Q.push({1,0});
    while(!Q.empty()){
        aa x=Q.top();
		Q.pop();
        int u=x.u;
        if(vis[u])continue;
        vis[u]=1;
        for(int i=0;i<arr[u].size();i++){
            aa e=arr[u][i];
            if(d[e.u]>d[u]+e.d){
                d[e.u]=d[u]+e.d;
                Q.push({e.u,d[e.u]});
            }
        }
    }
}

