type Edge = tuple[to, cost: int]

# (頂点数, 始点, 辺集合): 始点からの最短距離
proc dijkstra(N: int, S: int, G: seq[seq[Edge]]): seq[int] =
  type P = tuple[dist, v: int]
  const INF = 10 ^ 18
  var d = newseq[int](N + 1)
  d.fill(INF); d[S] = 0
  var que = initPriorityQueue[P]((p1: P, p2: P) => p1.dist < p2.dist)
  que.enqueue((0, S))
  while que.len > 0:
    var (dist, v) = que.dequeue()
    if d[v] < dist:
      continue
    for data in G[v]:
      var u = data.to
      var c = data.cost
      if d[u] > d[v] + c:
        d[u] = d[v] + c
        que.enqueue((d[u], u))
  return d

