type
  MergeOperator[T] = proc(a: T, b: T): T
  SegmentTree[T] = object
    node: seq[T]
    identityElement: T
    nodeCount: Natural
    innerNodeCount: Natural
    leafNodeCount: Natural 
    merge: MergeOperator[T]

proc initSegmentTree[T](n: Natural, identityElement: T, merge: MergeOperator[T]): SegmentTree[T] =
  var n = nextPowerOfTwo(n)
  result.node = newSeqWith(2 * n, identityElement)
  result.identityElement = identityElement
  result.nodeCount = 2 * n - 1
  result.innerNodeCount = n - 1
  result.leafNodeCount = n
  result.merge = merge

proc update[T](this: var SegmentTree[T], x: Natural, value: T) =
  var idx = (x + this.innerNodeCount)
  this.node[idx] = value
  while idx > 1:
    idx = idx div 2
    this.node[idx] = this.merge(this.node[idx * 2], this.node[idx * 2 + 1])

# [l, r)
proc query[T](this: var SegmentTree[T], l: Natural, r: Natural): T =
  var l = l + this.innerNodeCount
  var r = r + this.innerNodeCount
  var leftResult = this.identityElement
  var rightResult = this.identityElement
  while l < r:
    if (l mod 2 == 1):
      leftResult = this.merge(leftResult, this.node[l])
      inc l
    if (r mod 2 == 1):
      dec r
      rightResult = this.merge(this.node[r], rightResult)
    l = l div 2
    r = r div 2
  result = this.merge(leftResult, rightResult)

