class RangeMinimunQuery:
    def __init__(self, n):
        self._n = 1
        while self._n < n:
             self._n *= 2
        self._d = [INF] * (2 * self._n)

    def update(self, k, v):
        k += self._n - 1
        self._d[k] = v
        while k >= 0:
            k = (k - 1) / 2
            self._d[k] = min(self._d[2 * k + 1], self._d[2 * k + 2])

    def query(self, l, r):
        l += self._n - 1
        r += self._n - 1
        res = INF
        while l < r:
            if l & 1 == 0:
                res = min(res, self._d[l])
                l += 1
            if r & 1:
                r -= 1
                res = min(res, self._d[r])
            l >>= 1
            r >>= 1
        return res

    def a(self, k):
        return self._d[k + self._n - 1]

    def d(self):
        return self._d[self._n - 1:]

