def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


def Dijkstra(g, s):
    prev = {}
    q = []
    d = defaultdict(lambda: INF)
    d[s] = 0
    heapq.heappush(q, (d[s], s))

    while q:
        c, u = heapq.heappop(q)
        if d[u] < c:
            continue
        for v in g[u]:
            alt = g[u][v] + c
            if d[v] > alt:
                d[v] = alt
                prev[v] = u
                heapq.heappush(q, (alt, v))
    return d


class D2():
    def __init__(self, graph, start):
        self.g = graph

        self.dist = defaultdict(lambda: INF)
        self.dist[start] = 0

        self.prev = defaultdict(lambda: None)

        self.Q = []
        heapq.heappush(self.Q, (self.dist[start], start))

        while self.Q:
            dist_u, u = heapq.heappop(self.Q)

            if self.dist[u] < dist_u:
                continue

            for v, weight in self.g[u].items():
                alt = dist_u + weight
                if self.dist[v] > alt:
                    self.dist[v] = alt
                    self.prev[v] = u
                    heapq.heappush(self.Q, (alt, v))

