    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


def Dijkstra(g, s, N):
    V = set(range(1, N+1))

    d = {}
    prev = {}
    q = []
    done = set()
    for v in V:
        if v == s:
            d[v] = 0
        else:
            d[v] = INF
    heapq.heappush(q, (d[s], s))

    while q:
        c, u = heapq.heappop(q)
        if u in done:
            continue
        done.add(u)
        for v in g[u]:
            alt = g[u][v] + d[u]
            if d[v] > alt:
                d[v] = alt
                prev[v] = u
                heapq.heappush(q, (d[v], v))
    return d


@mt
def slv(N, LRC):
    g = defaultdict(dict)
    for i in range(1, N):
        g[i+1][i] = 0

    for l, r, c in LRC:
        g[l][r] = c
        if g[r][l] != 0:
            g[r][l] = c

    d = Dijkstra(g, 1, N)

    return -1 if d[N] == INF else d[N]


