        E[u].append((v, w))

    tree = SegmentTree([INF] * n, min, INF)
    tree.update(0, 0)
    for v in range(n):
        for nv, w in E[v]:
            tree.update(nv, min(tree[nv], tree.sum(v, nv) + w))

    ans = tree[n - 1]
    if ans == INF:
        ans = -1
    print(ans)
