from heapq import heappop, heappush


def dijkstra(s, t, links):
    q = [(0, s)]
    visited = set()
    while q:
        cost, v = heappop(q)
        if v in visited:
            continue
        if v == t:
            return cost
        visited.add(v)
        for u, c in links[v]:
            if u in visited:
                continue
            heappush(q, (cost + c, u))
    return -1


