        edge[l].append((r, c))
        edge[r].append((l, c))

    for i in range(1, N):
        edge[i + 1].append((i, 0))

    pq = PriorityQueue()
    pq.push((0, 1))
    dist = defaultdict(lambda: INF)

    while pq:
        cur, u = pq.pop()
        for v, c in edge[u]:
            nc = cur + c
            if nc < dist[v]:
                dist[v] = nc
                pq.push((nc, v))

    if dist[N] != INF:
        print(dist[N])
    else:
        print(-1)


