def slv(N, LRC):
    g = defaultdict(dict)
    for i in range(1, N):
        g[i+1][i] = 0

    for l, r, c in LRC:
        g[l][r] = c
        if not (r in g and l in g[r]):
            g[r][l] = c

    d = Dijkstra(g, 1, N)

    return -1 if d[N] == INF else d[N]


