fn main() {
    let mut scanner = Scanner::new(stdin());
    let line = scanner.read_vector::<usize>().unwrap();
    let (n, m) = (line[0], line[1]);
    let mut edges = vec![];
    for _ in 0..m {
        let line = scanner.read_vector::<usize>().unwrap();
        let (l, r, c) = (line[0] - 1, line[1] - 1, line[2] as i64);
        edges.push((l, r, c));
    }
    edges.sort();
    let mut adj = vec![vec![]; n];
    let mut crt = vec![0];
    for (l, r, c) in edges.into_iter() {
        let index = match crt.binary_search(&l) {
            Ok(i) => crt[i],
            Err(i) => {
                if i == crt.len() {
                    println!("-1");
                    return;
                }
                if crt[i] > r {
                    l
                } else {
                    crt[i]
                }
            },
        };
        if index == std::usize::MAX {
            continue;
        }
        adj[index].push((r, c));
        match crt.binary_search(&r) {
            Ok(_) => {},
            Err(i) => crt.insert(i, r),
        }
    }
    if crt[crt.len() - 1] != n - 1 {
        println!("-1");
        return;
    }

    let ans = dijkstra(0, n - 1, n, &adj);
    println!("{}", ans);
}

fn encode(tuple: (usize, i64)) -> (i64, usize) {
    (tuple.1 * (-1), tuple.0)
}

fn decode(tuple: (i64, usize)) -> (usize, i64) {
    (tuple.1, tuple.0 * (-1))
}

fn dijkstra(s: usize, e: usize, n: usize, adjacency_list: &Vec<Vec<(usize, i64)>>) -> i64 {
    let mut used = vec![false; n];
    let mut heap = BinaryHeap::<(i64, usize)>::new();
    heap.push(encode((s, 0)));
    let mut answer = 0;
    while heap.len() > 0 {
        let (node, cost) = decode(heap.pop().unwrap());
        if used[node] {
            continue;
        }
        used[node] = true;
        if node == e {
            answer = cost;
            break;
        }
        for &(neighbor, c) in adjacency_list[node].iter() {
            if used[neighbor] {
                continue;
            }
            heap.push(encode((neighbor, cost + c)));
        }
    }
    return answer;
}

