fn run() {
    input! {
        n: usize,
        m: usize,
        e: [(usize1, usize, i64); m],
    }
    let mut g = vec![vec![]; n];
    for (l, r, c) in e {
        g[l].push((r, c));
    }
    let inf = 1_000_000_000_000_000i64;
    let mut dp = vec![inf; n];
    dp[0] = 0;
    let mut h = std::collections::BinaryHeap::new();
    h.push((0, 1));
    for i in 0..n {
        while let Some((d, r)) = h.pop() {
            if r > i {
                h.push((d, r));
                break;
            }
        }
        if h.is_empty() {
            println!("-1");
            return;
        }
        let (d, _) = *h.peek().unwrap();
        dp[i] = -d;
        for &(r, c) in &g[i] {
            h.push((d - c, r));
        }
    }
    println!("{}", dp[n - 1]);
}

fn main() {
    run();
}

