            setc.remove(&(cost, x, nonce));
        }
        setx = setx_ok;
        if let Some(&(cost, _, _)) = setc.iter().next() {
            let new_cost = cost + c;
            i += 1;
            setc.insert((new_cost, r, i));
            setx.insert((r, new_cost, i));
        }
    }

    {
        let setx_ok = setx.split_off(&(n, 0, 0));
        for (x, cost, nonce) in setx.into_iter() {
            setc.remove(&(cost, x, nonce));
        }
        setx = setx_ok;
    }
    let tmp = setc.iter().next();
    let ans = if let Some(&(cost, _, _)) = tmp {
        cost
    } else {
        -1
    };
    println!("{}", ans);
}

