#[derive(Clone, Copy, PartialEq, Eq)]
struct Pointer(usize);

impl Pointer {
    const NULL: usize = std::usize::MAX;
    fn new(p: usize) -> Self {
        Pointer(p)
    }
    fn set(&mut self, x: usize) {
        self.0 = x;
    }
    fn get(&self) -> Option<usize> {
        if self.is_null() {
            None
        } else {
            Some(self.0)
        }
    }
    fn clear(&mut self) {
        self.set(Self::NULL);
    }
    fn is_null(&self) -> bool {
        self.0 == Self::NULL
    }
}

impl Default for Pointer {
    fn default() -> Self {
        Pointer::new(Pointer::NULL)
    }
}

struct Node<K, V> {
    key: K,
    value: V,
    parent: Pointer,
    child: Pointer,
    left: Pointer,
    right: Pointer,
}

impl<K, V> Node<K, V> {
    fn new(key: K, value: V) -> Self {
        Node {
            key: key,
            value: value,
            parent: Pointer::default(),
            child: Pointer::default(),
            left: Pointer::default(),
            right: Pointer::default(),
        }
    }
    fn rooting(&mut self, x: usize) {
        self.parent.clear();
        self.left.set(x);
        self.right.set(x);
    }
}

struct Heap<K, V> {
    array: Vec<Node<K, V>>,
    free: Pointer,
    root: Pointer,
}

impl<K: Ord + Copy, V: Copy> Heap<K, V> {
    fn new() -> Self {
        Heap {
            array: vec![],
            free: Pointer::default(),
            root: Pointer::default(),
        }
    }
    fn meld(&mut self, x: Pointer, y: Pointer) -> Pointer {
        if x.is_null() {
            return y;
        }
        if y.is_null() {
            return x;
        }
        let mut x = x.get().unwrap();
        let mut y = y.get().unwrap();
        let node = &mut self.array;
        if node[x].key >= node[y].key {
            std::mem::swap(&mut x, &mut y);
        }
        node[y].parent.set(x);
        let child = node[x].child;
        node[x].child.set(y);
        if let Some(c) = child.get() {
            let r = node[c].right.get().unwrap();
            node[c].right.set(y);
            node[r].left.set(y);
            node[y].left.set(c);
            node[y].right.set(r);
        }
        Pointer::new(x)
    }
    fn merge_list(&mut self, lst: Pointer) -> Pointer {
        if lst.is_null() {
            return lst;
        }
        let k = lst.get().unwrap();
        let l = self.array[k].left.get().unwrap();
        self.array[l].right.clear();
        self.array[k].left.clear();
        let mut lst = lst;
        let mut root = Pointer::default();
        while let Some(a) = lst.get() {
            if let Some(b) = self.array[a].right.get() {
                lst = self.array[b].right;
                self.array[a].rooting(a);
                self.array[b].rooting(b);
                let x = self.meld(Pointer::new(a), Pointer::new(b));
                root = self.meld(root, x);
            } else {
                lst.clear();
                self.array[a].rooting(a);
                root = self.meld(root, Pointer::new(a));
            }
        }
        root
    }
    fn push(&mut self, key: K, value: V) -> Pointer {
        if self.free.is_null() {
            let x = self.array.len();
            self.free.set(x);
            self.array.push(Node::new(key, value));
        }
        let res = self.free;
        let x = res.get().unwrap();
        self.free = self.array[x].child;
        self.array[x] = Node::new(key, value);
        self.array[x].rooting(x);
        self.root = self.meld(self.root, res);
        res
    }
    fn pop(&mut self) -> Option<(K, V)> {
        let root = self.root;
        root.get().map(|root| {
            let lst = self.array[root].child;
            self.array[root].child = self.free;
            self.free.set(root);
            self.root = self.merge_list(lst);
            (self.array[root].key, self.array[root].value)
        })
    }
    fn decrease_key(&mut self, p: Pointer, key: K) {
        let p = p.get().unwrap();
        assert!(key < self.array[p].key);
        self.array[p].key = key;
        let parent = self.array[p].parent;
        if parent.get().map_or(false, |q| self.array[q].key > key) {
            let q = parent.get().unwrap();
            let l = self.array[p].left.get().unwrap();
            let r = self.array[p].right.get().unwrap();
            self.array[l].right.set(r);
            self.array[r].left.set(l);
            self.array[p].rooting(p);
            if self.array[q].child.get().unwrap() == p {
                self.array[q].child.set(r);
            }
            if self.array[q].child.get().unwrap() == p {
                self.array[q].child.clear();
            }
            self.root = self.meld(self.root, Pointer::new(p));
        }
    }
}
