fn main(){
    let line = read_as_vec::<usize>();

    let (n, m) = (line[0], line[1]);

    let mut edges = vec![vec![];n];

    for _ in 0..m{
        let line = read_as_vec::<usize>();
        let (l, r, c) = (line[0]-1, line[1] - 1, line[2] as i64);
        edges[l].push((r, c));
    }

    for i in 1..n{
        edges[i].push((i-1,0));
    }


    let mut heap = BinaryHeap::new();
    let mut min_paths = vec![std::i64::MAX;n];
    min_paths[0] = 0;
    heap.push((0, 0));

    while let Some((cost, u)) = heap.pop(){
        let cur_cost = -cost;
        for &(next_v, next_cost) in &edges[u]{
            if cur_cost + next_cost < min_paths[next_v]{
                min_paths[next_v] = cur_cost + next_cost;
                heap.push((-(cur_cost + next_cost), next_v));
            }
        }
    }
    if min_paths[n-1] == std::i64::MAX{
        println!("{}", -1);
    }else{
        println!("{}", min_paths[n-1]);
    }
}

