use std::collections::{BTreeMap, BinaryHeap};

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner(s.lock());
    let n: usize = sc.read();
    let m: usize = sc.read();

    let mut edges = vec![vec![]; n];
    for _ in 0..m {
        let l: usize = sc.read::<usize>() - 1;
        let r: usize = sc.read::<usize>() - 1;
        let c: i64 = sc.read();
        edges[l].push((r, c));
    }

    //    eprintln!("{:?}", edges);
    let mut heap = BinaryHeap::new();
    heap.push((0, 0));
    for cur in 0..n {
        while let Some((c, v)) = heap.pop() {
            let z = (-v) as usize;
            if z >= cur {
                heap.push((c, v));
                break;
            }
        }
        if let Some(&(cost, v)) = heap.peek() {
            let v = (-v) as usize;
            let cur_cost = -cost;
            if v == n - 1 {
                println!("{}", cur_cost);
                return;
            }
            for &(next, cost) in edges[cur].iter() {
                let next_cost = cost + cur_cost;
                heap.push((-next_cost, -(next as i64)));
            }
        } else {
            println!("-1");
            return;
        }

        //        eprintln!("{:?}", heap);
    }
}

pub struct Scanner<R>(R);

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::collections::BinaryHeap;
fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut lrc: Vec<(usize, usize, i64)> = (0..m)
        .map(|_| {
            let l: usize = sc.read();
            let r: usize = sc.read();
            let c: i64 = sc.read();
            (l - 1, r - 1, c)
        })
        .collect();
    lrc.sort();
    let mut heap = BinaryHeap::new();
    heap.push((0, 0, 0));
    let mut max_id = 0;
    let mut results = vec![None; n + 1];
    while let Some(res) = heap.pop() {
        let cost = -res.0;
        let pos = res.1;
        let idx = res.2;
        if results[pos].is_some() {
            continue;
        }
        results[pos] = Some(cost);
        max_id = std::cmp::max(max_id, idx);
        for i in max_id..m {
            let (l, r, c) = lrc[i];
            if l <= pos && pos < r {
                heap.push((-(cost + c), r, i + 1));
            } else if pos < l {
                break;
            }
        }
    }
    let result = if results[n - 1].is_some() {
        results[n - 1].unwrap()
    } else {
        -1
    };
    println!("{}", result);
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}

