fn main() {
    let (N, M) = read!(usize, usize);
    let T = read![usize, usize, i64; M];

    let mut b = vec![];
    for &(l, r, _) in &T {
        b.push(l);
        b.push(r);
    }
    b.sort();
    b.dedup();

    let mut next = vec![N; N + 1];
    for w in b.windows(2) {
        next[w[0]] = w[1];
    }
    debug!(next);

    let mut U = T.iter().map(|&(l, r, c)| (c, l, r)).collect::<Vec<_>>();
    U.sort();
    U.reverse();

    let mut cost = vec![std::i64::MAX; N + 1];
    let mut skip = next.clone();
    for &(c, l, r) in &U {
        let mut v = l;
        while v < r {
            cost[v] = c;
            skip[v] = r;
            v = next[v];
        }
    }
    debug!(cost);

    let mut ok = true;
    let mut total = 0_i64;
    let mut v = 1;
    while v < N {
        if cost[v] == std::i64::MAX {
            ok = false;
            break;
        }
        total += cost[v];
        v = skip[v];
    }

    if !ok {
        println!("-1");
        return;
    }

    println!("{}", total)
}

