fn solve() {
    let (n,m) = get!(usize, usize);
    let lrc = get!(usize, usize, usize; m);

    let mut nodes = vec![Vec::new(); n+1];
    for i in 1..n+1 {
        nodes[i].push((i-1,0))
    }

    for (l,r,c) in lrc {
        nodes[l].push((r,c));
    }

    let mut heap = BinaryHeap::new();
    let mut visited = vec![false; n+1];
    heap.push(Rev((0, 1)));
    while let Some(Rev((cost,node))) = heap.pop() {
        visited[node] = true;
        if node == n {
            println!("{}", cost);
            return;
        }
        for &(next, c) in &nodes[node] {
            if visited[next] {
                continue;
            }
            heap.push(Rev((c+cost, next)));
        }
    }
    println!("-1");
}

