fn solve<R: BufRead, W: Write>(reader: R, mut writer: W) {
  let mut _scanner = spella::io::Scanner::new(reader);

  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.next::<$T>().unwrap().unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($($T:ty),+; $n:expr $(; $m:expr)*) => {{
      (0..$n).map(|_| scan!($($T),+ $(; $m)*)).collect::<Vec<_>>()
    }};
  }

  #[allow(unused_macros)]
  macro_rules! scan_iter {
    ($($T:ty),+; $n:expr) => {
      (0..$n).map(|_| scan!($($T),+))
    };
  }

  #[allow(unused_macros)]
  macro_rules! print {
    ($fmt:expr) => {
      write!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      write!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! println {
    ($fmt:expr) => {
      writeln!(writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      writeln!(writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprint {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      write!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprintln {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      writeln!(std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! dbg {
    ($($x:expr),+) => {{
      eprintln!(concat!("[{}:{}] ", $(stringify!($x), " = {:?}; "),+), file!(), line!(), $($x),+);
    }};
  }

  use std::cmp::Ordering;

  #[derive(Clone, Copy, PartialEq, Eq, Default, Debug, Hash)]
  pub struct Reverse<T>(pub T);

  impl<T: PartialOrd> PartialOrd for Reverse<T> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
      other.0.partial_cmp(&self.0)
    }
  }

  impl<T: Ord> Ord for Reverse<T> {
    fn cmp(&self, other: &Self) -> Ordering {
      other.0.cmp(&self.0)
    }
  }

  const FAR: u64 = u64::MAX / 2;

  let (n, m) = scan!(usize, usize);
  let mut g = vec![vec![]; n];
  for (l, r, c) in scan_iter!(usize, usize, u64; m) {
    g[l - 1].push((c, r - 1));
  }
  for i in 1..n {
    g[i].push((0, i - 1));
  }

  if let Some(ans) = {
    let mut visited = vec![false; n];
    let mut dist = vec![FAR; n];
    let mut heap = BinaryHeap::<(Reverse<u64>, usize)>::new();
    heap.push((Reverse(0), 0));
    while let Some((Reverse(d), t)) = heap.pop() {
      if visited[t] {
        continue;
      }
      visited[t] = true;
      dist[t] = d;
      for e in &g[t] {
        if dist[e.1] <= d + e.0 {
          continue;
        }
        heap.push((Reverse(d + e.0), e.1));
      }
    }
    if dist[n - 1] < FAR {
      Some(dist[n - 1])
    } else {
      None
    }
  } {
    println!("{}", ans);
  } else {
    println!("-1");
  }
}

