fn run() {
    let stdin = std::io::stdin();
    let mut sc = Scanner::new(stdin.lock());
    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut ds = vec![Vec::new(); n + 1];
    for _ in 0..m {
        let l: usize = sc.read::<usize>() - 1;
        let r: usize = sc.read::<usize>() - 1;
        let c: usize = sc.read();
        ds[l].push((l, r, c));
    }
    let mut cost = vec![usize::max_value(); n + 1];
    cost[0] = 0;
    let mut heap = BinaryHeap::new();
    for &(l, r, c) in &ds[0] {
        heap.push(Reverse((c, r)));
    }
    let mut output = false;
    while let Some(Reverse((c, x))) = heap.pop() {
        if x == n - 1 {
            output = true;
            println!("{}", c);
            break;
        }
        if cost[x] > c {
            cost[x] = c;
            for &(_, r, c) in &ds[x] {
                heap.push(Reverse((cost[x] + c, r)));
            }
            let mut idx = x - 1;
            while idx > 0 && cost[idx] > c {
                cost[idx] = c;
                for &(_, r, c) in &ds[idx] {
                    heap.push(Reverse((cost[idx] + c, r)));
                }
                idx -= 1;
            }
        }
    }
    if !output {
        println!("-1");
    }
}

#[derive(PartialEq, Eq, Debug, Copy, Clone, Default, Hash)]
pub struct Reverse<T>(pub T);

impl<T: PartialOrd> PartialOrd for Reverse<T> {
    #[inline]
    fn partial_cmp(&self, other: &Reverse<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }

    #[inline]
    fn lt(&self, other: &Self) -> bool {
        other.0 < self.0
    }
    #[inline]
    fn le(&self, other: &Self) -> bool {
        other.0 <= self.0
    }
    #[inline]
    fn ge(&self, other: &Self) -> bool {
        other.0 >= self.0
    }
    #[inline]
    fn gt(&self, other: &Self) -> bool {
        other.0 > self.0
    }
}

impl<T: Ord> Ord for Reverse<T> {
    #[inline]
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

