fn run() {
	let (N, M) = read!(usize, usize);
	let mut g = vec![vec![]; N];
	for i in 1..N {
		g[i].push((i - 1, 0));
	}
	for (l, r, c) in read!(usize1, usize1, i64; M) {
		g[l].push((r, c));
	}
	let mut que = BinaryHeap::new();
	let mut dist = vec![INF; N];
	dist[0] = 0;
	que.push((0, 0));
	while let Some((d, u)) = que.pop() {
		let d = -d;
		if dist[u] != d {
			continue;
		}
		for &(v, l) in &g[u] {
			if dist[v].setmin(d + l) {
				que.push((-dist[v], v));
			}
		}
	}
	if dist[N - 1] == INF {
		dist[N - 1] = -1;
	}
	println!("{}", dist[N - 1]);
}

