fn solve() {
    input!{
        n:usize,m:usize,
        LRC:[(usize,usize,i64);m]
    }

    let mut lrc = vec![];
    for (l,r,c) in LRC {
        lrc.push((l-1,r-1,c));
    }

    lrc.sort_by_key(|&x| (x.1, x.0));

    let max = 1<<62;
    let mut seg: SEG<MIN_RUQ> = SEG::new(max, n);
    let (l,r,c) = lrc[0];
    seg.update(l,r+1,c);

    for i in 1..m {
        let (l,r,c) = lrc[i];

        let precost = seg.query(l, r+1);

        let newcost = precost+c;

        let oldval = seg.query(r, r+1);
        if oldval > newcost {
            seg.update(l, r+1, newcost);
        }
    }

    let ncost = seg.query(n-1, n);
    if ncost >= max {
        println!("-1"); 
    } else {
        println!("{}", ncost);
    }
}

