fn solve() {
    input!{
        n:usize,m:usize,
        LRC:[(usize,usize,i64);m]
    }

    let mut lrc = vec![];
    for (l,r,c) in LRC {
        lrc.push((l-1,r-1,c));
    }

    lrc.sort_by_key(|&x| x.0);
    lrc.sort_by_key(|&x| x.1);

    let max = 1<<60;
    let mut seg: SEG<MIN_RUQ> = SEG::new(max, n);
    let (l,r,c) = lrc[0];
    seg.update(l,r+1,c);

    for i in 1..m {
        let (l,r,c) = lrc[i];

        let precost = seg.query(l, r+1);

        let newcost = precost+c;

        let oldval = seg.query(r, r+1);
        if oldval > newcost {
            seg.update(r, r+1, newcost);
        }
    }

    let ncost = seg.query(n-1, n);
    if ncost >= max {
        println!("-1"); 
    } else {
        println!("{}", ncost);
    }
}

struct MIN_RUQ;
impl SEGImpl for MIN_RUQ {
