#[derive(Debug)]
struct LSegT {
    v: Vec<usize>,
    lazy: Vec<Option<usize>>,
    n: usize
}

impl LSegT {
    fn new(n: usize) -> LSegT {
        let mut s = 1;
        while s < n {
            s *= 2;
        }
        LSegT{v: vec![usize::max_value(); 2 * s - 1], lazy: vec![None; 2 * s - 1], n: s}
    }

    fn eval(&mut self, p: usize) {
        if let Some(l) = self.lazy[p] {
            self.v[p] = min(self.v[p], l);
            if p < self.n - 1 {
                self.lazy[2 * p + 1] = Some(self.lazy[2 * p + 1].map_or(l, |x| min(x, l)));
                self.lazy[2 * p + 2] = Some(self.lazy[2 * p + 2].map_or(l, |x| min(x, l)));
            }
            self.lazy[p] = None;
        }
    }

    fn update(&mut self, l: usize, r: usize, x: usize) {
        let n = self.n;
        self.update_rec(l, r, x, 0, 0, n - 1);
    }

    fn update_rec(&mut self, l: usize, r: usize, x: usize, p: usize, pl: usize, pr: usize) {
        self.eval(p);
        if pl > r || pr < l {
            return;
        } else if l <= pl && pr <= r {
            self.lazy[p] = Some(self.lazy[p].map_or(x, |y| min(x, y)));
            self.eval(p);
        } else {
            self.update_rec(l, r, x, 2 * p + 1, pl, (pl + pr - 1) / 2);
            self.update_rec(l, r, x, 2 * p + 2, (pl + pr + 1) / 2, pr);
            self.v[p] = min(self.v[2 * p + 1], self.v[2 * p + 2]);
        }
    }

    fn get(&mut self, l: usize, r: usize) -> usize {
        let n = self.n;
        self.get_rec(l, r, 0, 0, n - 1)
    }

    fn get_rec(&mut self, l: usize, r: usize, p: usize, pl: usize, pr: usize) -> usize {
        self.eval(p);
        if pl > r || pr < l {
            usize::max_value()
        } else if l <= pl && pr <= r {
            self.v[p]
        } else {
            let a = self.get_rec(l, r, 2 * p + 1, pl, (pl + pr - 1) / 2);
            let b = self.get_rec(l, r, 2 * p + 2, (pl + pr + 1) / 2, pr);
            min(a, b)
        }
    }
}

use proconio::input;
use proconio::marker::Usize1;
use std::collections::BinaryHeap;
use std::cmp::Reverse;

fn main()
{
    input! {
    n:usize,
    m:usize,
    edge:[(Usize1,Usize1,i64);m],
    }

    let mut v = vec![vec![]; n];
    for i in 1..n {
        v[i].push((i - 1, 0));
    }
    for (a, b, c) in edge {
        v[a].push((b, c));
    }

    let inf = 1i64 << 60;
    let mut dist = vec![inf; n];

    let mut q = BinaryHeap::new();
    q.push(Reverse((0, 0)));

    while let Some(Reverse((dst, idx))) = q.pop() {
        if dist[idx] < dst {
            continue;
        }
        for &(nxt, cost) in v[idx].iter() {
            let dst = dst + cost;
            if dist[nxt] <= dst {
                continue;
            }
            dist[nxt] = dst;
            q.push(Reverse((dst, nxt)));
        }
    }

    let ans = if dist[n - 1] == inf {
        -1
    } else {
        dist[n - 1]
    };
    println!("{}", ans);
}

