use std::process::exit;
use std::collections::BinaryHeap;
use std::cmp;

fn fail() -> ! {
    println!("-1");
    exit(0)
}

#[derive(PartialEq, Eq, Clone)]
struct Node {
    end: usize,
    dist: u64
}

impl Ord for Node {
    fn cmp(&self, other: &Node) -> cmp::Ordering {
        other.dist.cmp(&self.dist)
    }
}

impl PartialOrd for Node {
    fn partial_cmp(&self, other: &Node) -> Option<cmp::Ordering> {
        Some(self.cmp(other))
    }
}

fn main() {
    read!(n = usize, _ = ());
    let mut es = readx::<(usize_, usize, u64)>();
    es.sort_by_key(|&(l, _, _)| l);
    if es[0].0 != 0 {
        fail();
    }
    let mut queue = BinaryHeap::new();
    queue.push(Node { end: 1, dist: 0 });
    for (l, end, cost) in es {
        let dist;
        loop {
            match queue.pop() {
                None => fail(),
                Some(node) => {
                    if l < node.end {
                        dist = node.dist;
                        queue.push(node);
                        break;
                    }
                }
            }
        };
        queue.push(Node { end: end, dist: dist + cost });
    }

    loop {
        match queue.pop() {
            None => fail(),
            Some(node) => {
                if node.end == n {
                    println!("{}", node.dist);
                    break;
                }
            }
        }
    }
}

