/*
 * Dijkstra's algorithm.
 * Verified by: AtCoder ABC035 (http://abc035.contest.atcoder.jp/submissions/676539)
 */

struct Dijkstra {
    edges: Vec<Vec<(usize, i64)>>, // adjacent list representation
}

/*
 * Code from https://doc.rust-lang.org/std/collections/binary_heap/
 */
#[derive(Copy, Clone, Eq, PartialEq)]
struct State {
    cost: i64,
    position: usize,
}

// The priority queue depends on `Ord`.
// Explicitly implement the trait so the queue becomes a min-heap
// instead of a max-heap.
impl Ord for State {
    fn cmp(&self, other: &State) -> Ordering {
        // Notice that the we flip the ordering here
        match other.cost.cmp(&self.cost) {
            std::cmp::Ordering::Equal => other.position.cmp(&self.position),
            x => x,
        }
    }
}

// `PartialOrd` needs to be implemented as well.
impl PartialOrd for State {
    fn partial_cmp(&self, other: &State) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}


impl Dijkstra {
    fn new(n: usize) -> Self {
        Dijkstra { edges: vec![Vec::new(); n] }
    }
    fn add_edge(&mut self, from: usize, to: usize, cost: i64) {
        self.edges[from].push((to, cost));
    }
    /*
     * This function returns a Vec consisting of the distances from vertex source.
     */
    fn solve(&self, source: usize, inf: i64) -> Vec<i64> {
        let n = self.edges.len();
        let mut d = vec![inf; n];
        let mut que = std::collections::BinaryHeap::new();
        que.push(State {cost: 0, position: source});
        while let Some(State {cost, position: pos}) = que.pop() {
            if d[pos] <= cost {
                continue;
            }
            d[pos] = cost;
            for adj in &self.edges[pos] {
                que.push(State {cost: cost + adj.1, position: adj.0});
            }
        }
        return d;
    }
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize, m: usize,
        lrc: [(usize1, usize1, i64); m],
    }
    let mut dijk = Dijkstra::new(n);
    for i in 0..n - 1 {
        dijk.add_edge(i + 1, i, 0);
    }
    for &(l, r, c) in &lrc {
        dijk.add_edge(l, r, c);
    }
    const INF: i64 = 1 << 50;
    let ans = dijk.solve(0, INF);
    puts!("{}\n", if ans[n - 1] >= INF { -1 } else { ans[n - 1] });
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

use std::collections::BinaryHeap;
fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut lrc: Vec<(usize, usize, i64)> = (0..m)
        .map(|_| {
            let l: usize = sc.read();
            let r: usize = sc.read();
            let c: i64 = sc.read();
            (l - 1, r - 1, c)
        })
        .collect();
    lrc.sort();
    let mut heap = BinaryHeap::new();
    heap.push((0, 0, 0));
    let mut max_id = 0;
    let mut results = vec![None; n + 1];
    while let Some(res) = heap.pop() {
        let cost = -res.0;
        let pos = res.1;
        let idx = res.2;
        if results[pos].is_some() {
            continue;
        }
        results[pos] = Some(cost);
        max_id = std::cmp::max(max_id, idx);
        for i in max_id..m {
            let (l, r, c) = lrc[i];
            if l <= pos && pos < r {
                heap.push((-(cost + c), r, i + 1));
            } else if pos < l {
                max_id = std::cmp::max(max_id, i);
                break;
            }
        }
    }
    let result = if results[n - 1].is_some() {
        results[n - 1].unwrap()
    } else {
        -1
    };
    println!("{}", result);
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}

