fn main() {
    input! {
        n: usize,
        m: usize,
        mut edges: [(usize1, usize1, usize); m],
    }

    let mut st = SegmentTree::new(n + 1);
    st.update(0, 0);
    edges.sort();
    for &(l, r, c) in &edges {
        let next = st.query(l, r) as usize + c;
        let old = st.query(r, r + 1) as usize;
        st.update(r, min(next, old) as i64);
    }

    let a = st.query(n - 1, n);
    if a > 1 << 40 {
        println!("-1");
    } else {
        println!("{}", a);
    }
}

use std::collections::BinaryHeap;
fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut lrc: Vec<(usize, usize, i64)> = (0..m)
        .map(|_| {
            let l: usize = sc.read();
            let r: usize = sc.read();
            let c: i64 = sc.read();
            (l - 1, r - 1, c)
        })
        .collect();
    lrc.sort();
    let mut heap = BinaryHeap::new();
    heap.push((0, 0, 0));
    let mut max_id = 0;
    let mut results = vec![None; n + 1];
    while let Some(res) = heap.pop() {
        let cost = -res.0;
        let pos = res.1;
        let idx = res.2;
        if results[pos].is_some() {
            continue;
        }
        results[pos] = Some(cost);
        max_id = std::cmp::max(max_id, idx);
        for i in max_id..m {
            let (l, r, c) = lrc[i];
            if l <= pos && pos < r {
                heap.push((-(cost + c), r, i + 1));
            } else {
                break;
            }
        }
    }
    let result = if results[n - 1].is_some() {
        results[n - 1].unwrap()
    } else {
        -1
    };
    println!("{}", result);
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}

